window.FATAWA={"title":"الفتاوى الميسّرة","subtitle":"في ضوء الكتاب والسنة","author":"عبد الحسيب منيب الأفغاني","email":"","intro":["الحمد لله رب العالمين، والصلاة والسلام على نبينا محمد وعلى آله وصحبه أجمعين. أما بعد:","فهذه فتاوى ميسرة جمعتها وأعددتها في ضوء الكتاب والسنة، أعرض في كل مسألة خلاصتها أولًا، ثم أدلتها من القرآن الكريم والسنة النبوية، ثم أقوال أهل العلم من كتب المذاهب المعتمدة وفتاوى العلماء المعاصرين، ثم سبب الخلاف، ثم ما ترجح عندي بدليله، والله أعلم.","وأحب أن أنبه القارئ الكريم إلى أصول سرت عليها في هذا الكتاب:","أولًا: أن القرآن الكريم والسنة الصحيحة هما الحاكمان على أقوال الناس جميعًا، وأن أهل العلم من الأئمة الأربعة وغيرهم، مع جلالة قدرهم وعلو مكانتهم وسبقهم في العلم والفضل، ليسوا معصومين، وليسوا حاكمين على الكتاب والسنة، بل الكتاب والسنة قاضيان عليهم وعلينا، وكلهم رحمهم الله أوصى بذلك.","ثانيًا: أن أهل العلم جميعًا، قديمهم وحديثهم، محل احترامنا وتوقيرنا، نستفيد من علومهم وندعو لهم، ولا ننتقص أحدًا منهم، ونعرض أقوالهم بأمانة كما قالوها، وأدلتهم كما استدلوا بها، فما ترجح عندي ذكرته بأدب، وما خالفته فإني أعتذر لقائله وأعرف له فضله.","ثالثًا: أن الاختلاف في المسائل الاجتهادية لا يعني أن يحقر بعضنا بعضًا، أو أن يبدّع بعضنا بعضًا؛ فقد اختلف الصحابة رضي الله عنهم والأئمة من بعدهم، وكانوا مع اختلافهم جماعة واحدة متحابين متراحمين، يصلي بعضهم خلف بعض، ويثني بعضهم على بعض.","رابعًا: أن من أخذ بقول إمام معتبر في مسألة اجتهادية، له دليل معتبر، فلا ينكر عليه، وعملُه صحيح إن شاء الله، وإنما أذكر الراجح عندي ليستعين به القارئ في معرفة أقرب الأقوال إلى الدليل.","وأسأل الله تعالى أن يجعل هذا العمل خالصًا لوجهه الكريم، وأن يجمع به كلمة المسلمين، وأن ينفع به كاتبه وقارئه، إنه سميع مجيب."],"fatawa":[{"n":1,"bab":"العقيدة","sub":"التوحيد","title":"معنى التوحيد وأقسامه","q":"ما معنى التوحيد؟ وما أقسامه التي يذكرها العلماء؟","short":"التوحيد هو إفراد الله تعالى بما يختص به من الربوبية والألوهية والأسماء والصفات. وقد ذكر العلماء أنه ثلاثة أقسام عُرفت بتتبع نصوص الكتاب والسنة: توحيد الربوبية، وتوحيد الألوهية (العبادة)، وتوحيد الأسماء والصفات.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"التوحيد أصل الدين وأول واجب على المكلف، ولأجله أرسل الله الرسل وأنزل الكتب. ويسأل كثير من الناس عن معناه، وعن تقسيمه الذي يذكره أهل العلم في كتب العقيدة."},{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"رَّبُّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَٱعْبُدْهُ وَٱصْطَبِرْ لِعِبَـٰدَتِهِۦ ۚ هَلْ تَعْلَمُ لَهُۥ سَمِيًّا","ref":"مريم: ٦٥"},{"t":"p","text":"ففي الآية ذكر ربوبيته سبحانه للسماوات والأرض، والأمر بعبادته وحده، ونفي أن يكون له سميّ يماثله في أسمائه وصفاته."},{"t":"aya","text":"قُلْ هُوَ ٱللَّهُ أَحَدٌ","ref":"الإخلاص: ١"},{"t":"aya","text":"ٱللَّهُ ٱلصَّمَدُ","ref":"الإخلاص: ٢"},{"t":"aya","text":"لَمْ يَلِدْ وَلَمْ يُولَدْ","ref":"الإخلاص: ٣"},{"t":"aya","text":"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","ref":"الإخلاص: ٤"},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فالتوحيد هو إفراد الله عز وجل بما يستحقه ويختص به من الربوبية والألوهية والأسماء والصفات، ولهذا قال العلماء رحمهم الله: إن التوحيد ينقسم إلى ثلاثة أقسام: توحيد الربوبية، وتوحيد الألوهية، وتوحيد الأسماء والصفات","src":"فتاوى نور على الدرب لابن عثيمين","loc":"١/٢","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"وقد علمنا مما سبق أن أقسام التوحيد ثلاثة: توحيد الربوبية، وتوحيد الألوهية، وتوحيد الأسماء والصفات","src":"مجموع فتاوى ابن باز","loc":"٩/٦٧","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"فتوحيد الربوبية وهو الإيمان بأفعال الرب سبحانه وأنه فعال لما يريد، وأنه الخلاق الرزاق، وهذا القسم ما أنكره المشركون بل أقروا به، وهو يستلزم توحيد العبادة ويلزمهم بذلك","src":"مجموع فتاوى ابن باز","loc":"٩/٦٧"},{"t":"tanbih","items":[{"t":"p","text":"هذا التقسيم اصطلاح تعليمي عُرف بالاستقراء، كما صرّح به العلماء، ومقصوده تقريب معاني النصوص؛ فمن عبّر عن هذه المعاني بغير هذا الاصطلاح وهو مقرّ بها فلا مشاحّة في الاصطلاح."}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"التوحيد إفراد الله بما يختص به، ويدخل فيه الإقرار بأنه الخالق المدبر وحده، وإخلاص العبادة له وحده، وإثبات ما أثبته لنفسه من الأسماء والصفات من غير تمثيل. وأعظم هذه الأقسام في دعوة الرسل توحيد العبادة؛ لأنه الذي وقع فيه النزاع بين الرسل وأقوامهم."}],"refs":["فتاوى نور على الدرب لابن عثيمين (١/٢)","مجموع فتاوى ابن باز (٩/٦٧)"],"related":["معنى لا إله إلا الله","منهج أهل السنة في الأسماء والصفات"],"alts":["أنواع التوحيد","توحيد الربوبية والألوهية","تعريف التوحيد"]},{"n":2,"bab":"العقيدة","sub":"التوحيد","title":"معنى لا إله إلا الله","q":"ما معنى كلمة التوحيد «لا إله إلا الله»؟","short":"معناها: لا معبود بحق إلا الله؛ فهي نفي وإثبات: تنفي استحقاق العبادة عن كل ما سوى الله، وتثبتها لله وحده لا شريك له.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِۦ هُوَ ٱلْبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ","ref":"الحج: ٦٢"},{"t":"aya","text":"فَٱعْلَمْ أَنَّهُۥ لَآ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ۗ وَٱللَّهُ يَعْلَمُ مُتَقَلَّبَكُمْ وَمَثْوَىٰكُمْ","ref":"محمد: ١٩"},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"ومعنى (لا إله إلا الله) : لا معبود بحق إلا الله، وهي نفي وإثبات. (لا إله) نافيا جميع العبادة لغير الله، (إلا الله) مثبتا جميع العبادة لله وحده لا شريك له","src":"فتاوى اللجنة الدائمة","loc":"١/٨٦","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"لأن معناها: لا معبود بحق إلا الله، فهي تنفي الألوهية وهي العبادة عن غير الله، وتثبت العبادة لله وحده، دون ما سواه من سائر المخلوقات","src":"مجموع فتاوى ابن باز","loc":"١/١٥٩","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"ثم إن هذة الكلمة إذا قالها الإنسان وهو يفهم معناها فإنها تستلزم أن يقوم بطاعة الله عز وجل؛ لأن معنى لا إله إلا الله: لا معبود بحق إلا الله، وهذا يقتضي أن يعبد هذا الإله الحق على الوجه الذي أمر به: مخلصاً له الدين، متبعاً لخاتم النبيين محمد صلى الله عليه وعلى آله وسلم","src":"فتاوى نور على الدرب لابن عثيمين","loc":"٤/٢","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"معناها: لا معبود بحق إلا الله. وقول من قال: معناها لا خالق إلا الله، صحيح في نفسه، لكنه بعض معناها لا كله؛ فإن المشركين كانوا يقرّون بأن الله هو الخالق، ثم يعبدون معه غيره."}],"refs":["فتاوى اللجنة الدائمة (١/٨٦)","مجموع فتاوى ابن باز (١/١٥٩)","فتاوى نور على الدرب لابن عثيمين (٤/٢)"],"related":["معنى التوحيد وأقسامه"],"alts":["معنى الشهادة","تفسير لا إله إلا الله","كلمة التوحيد"]},{"n":3,"bab":"العقيدة","sub":"الإيمان","title":"أركان الإيمان","q":"ما أركان الإيمان التي يجب على المسلم أن يؤمن بها؟","short":"أركان الإيمان ستة: الإيمان بالله، وملائكته، وكتبه، ورسله، واليوم الآخر، والقدر خيره وشره، كما بيّنها النبي ﷺ في حديث جبريل عليه السلام.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ","ref":"البقرة: ٢٨٥"},{"t":"aya","text":"إِنَّا كُلَّ شَىْءٍ خَلَقْنَـٰهُ بِقَدَرٍ","ref":"القمر: ٤٩"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قَالَ: فَأَخْبِرْنِي عَنِ الْإِيمَانِ، قَالَ: «أَنْ تُؤْمِنَ بِاللهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ»","src":"رواه مسلم ٨","pre":"في حديث عمر بن الخطاب رضي الله عنه في سؤال جبريل عليه السلام:","links":[{"book":"mt_muslim","num":8,"id":"h8"}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"هذه الأركان الستة محل إجماع بين المسلمين، ومن أنكر واحدًا منها بعد علمه بثبوته فليس بمؤمن."}],"refs":["مسلم ٨"],"related":["الإيمان قول وعمل، وزيادته ونقصانه","الإيمان بالقدر ومراتبه"],"alts":["أركان الإيمان الستة","حديث جبريل"]},{"n":4,"bab":"العقيدة","sub":"الإيمان","title":"الإيمان: قول وعمل، وزيادته ونقصانه","q":"هل الأعمال داخلة في مسمى الإيمان؟ وهل يزيد الإيمان وينقص؟","short":"مذهب جمهور السلف وأهل الحديث أن الإيمان قول باللسان واعتقاد بالقلب وعمل بالجوارح، يزيد بالطاعة وينقص بالمعصية. وذهب الإمام أبو حنيفة وأصحابه إلى أن الإيمان تصديق بالقلب وإقرار باللسان، وأن الأعمال ليست جزءًا من مسماه، مع اتفاقهم على وجوبها وعلى أن تاركها مستحق للعقوبة. وكثير من النزاع بين الفريقين لفظي كما قرره المحققون، ولم يكفّر أحد من السلف أصحاب القول الثاني.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"اتفق أهل السنة على أن الإيمان لا بد فيه من تصديق القلب وإقرار اللسان، وعلى أن الطاعات واجبة والمعاصي محرمة، وأن مرتكب الكبيرة لا يخرج من الإسلام. واختلفوا في دخول أعمال الجوارح في مسمى الإيمان، وفي زيادة الإيمان ونقصانه."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الإيمان قول وعمل واعتقاد، يزيد بالطاعة وينقص بالمعصية، وهو قول جمهور الصحابة والتابعين ومالك والشافعي وأحمد وأهل الحديث."},{"t":"p","text":"ومن أدلتهم:"},{"t":"aya","text":"هُوَ ٱلَّذِىٓ أَنزَلَ ٱلسَّكِينَةَ فِى قُلُوبِ ٱلْمُؤْمِنِينَ لِيَزْدَادُوٓا۟ إِيمَـٰنًا مَّعَ إِيمَـٰنِهِمْ ۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا","ref":"الفتح: ٤"},{"t":"aya","text":"إِنَّمَا ٱلْمُؤْمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ ءَايَـٰتُهُۥ زَادَتْهُمْ إِيمَـٰنًا وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ","ref":"الأنفال: ٢"},{"t":"quote","text":"من أصول أهل السنة والجماعة: أن الإيمان يزيد وينقص وقد دل على ذلك الكتاب والسنة","src":"مجموع فتاوى ابن عثيمين","loc":"٤/٩٢","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"qawl","label":"القول الثاني","text":"الإيمان تصديق بالقلب وإقرار باللسان، والأعمال ليست جزءًا من حقيقته وإن كانت واجبة وثمرة له، وهو قول الإمام أبي حنيفة وأصحابه، وعليه جمهور الحنفية."},{"t":"p","text":"واستدلوا بأن الإيمان في اللغة التصديق، وبأن الله عطف العمل الصالح على الإيمان في آيات كثيرة، والعطف يقتضي المغايرة، كقوله تعالى:"},{"t":"aya","text":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ","ref":"العصر: ٣"},{"t":"h","text":"سبب الخلاف وحقيقته"},{"t":"p","text":"سبب الخلاف: هل الأعمال أجزاء من الإيمان أو ثمرات ولوازم له؟ والفريقان متفقان على أن تارك الواجب وفاعل المحرم مستحق للذم والعقوبة، وأن صاحب الكبيرة لا يخرج من الملة؛ ولهذا عدّ المحققون كثيرًا من هذا النزاع لفظيًّا."},{"t":"quote","text":"فَإِذَا عُرِفَ أَنَّ الذَّمَّ وَالْعِقَابَ وَاقِعٌ فِي تَرْكِ الْعَمَلِ كَانَ بَعْدَ ذَلِكَ نِزَاعُهُمْ لَا فَائِدَةَ فِيهِ بَلْ يَكُونُ نِزَاعًا لَفْظِيًّا مَعَ أَنَّهُمْ مُخْطِئُونَ فِي اللَّفْظِ مُخَالِفُونَ لِلْكِتَابِ وَالسُّنَّةِ","src":"مجموع الفتاوى","loc":"٧/١٨١","pre":"قال شيخ الإسلام ابن تيمية رحمه الله:"},{"t":"quote","text":"وَلِهَذَا دَخَلَ فِي \" إرْجَاءِ الْفُقَهَاءِ \" جَمَاعَةٌ هُمْ عِنْدَ الْأُمَّةِ أَهْلُ عِلْمٍ وَدِينٍ. وَلِهَذَا لَمْ يُكَفِّرْ أَحَدٌ مِنْ السَّلَفِ أَحَدًا مِنْ \" مُرْجِئَةِ الْفُقَهَاءِ \" بَلْ جَعَلُوا هَذَا مِنْ بِدَعِ الْأَقْوَالِ وَالْأَفْعَالِ؛ لَا مِنْ بِدَعِ الْعَقَائِدِ فَإِنَّ كَثِيرًا مِنْ النِّزَاعِ فِيهَا لَفْظِيٌّ لَكِنَّ اللَّفْظَ الْمُطَابِقَ لِلْكِتَابِ وَالسُّنَّةِ هُوَ الصَّوَابُ","src":"مجموع الفتاوى","loc":"٧/٣٩٤","pre":"وقال أيضًا:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأرجح ما عليه جمهور السلف من أن الإيمان قول وعمل، يزيد وينقص؛ لصراحة الآيات في زيادة الإيمان، ولحديث شعب الإيمان. ومع ذلك فإن الأئمة القائلين بالقول الثاني أئمة هدى، ومرادهم التفريق بين أصل الإيمان وثمراته، لا التهوين من الأعمال؛ فلا يجوز أن يكون هذا الخلاف سببًا للتنافر بين المسلمين."}],"refs":["مجموع فتاوى ابن عثيمين (٤/٩٢)","مجموع الفتاوى (٧/١٨١)","مجموع الفتاوى (٧/٣٩٤)"],"related":["أركان الإيمان","التحذير من تكفير المسلمين"],"alts":["هل الإيمان يزيد وينقص","دخول الأعمال في الإيمان","تعريف الإيمان عند أبي حنيفة"]},{"n":5,"bab":"العقيدة","sub":"الأسماء والصفات","title":"منهج أهل السنة في الأسماء والصفات","q":"كيف نؤمن بأسماء الله وصفاته الواردة في القرآن والسنة؟","short":"نؤمن بما وصف الله به نفسه في كتابه وبما وصفه به رسوله ﷺ، إثباتًا يليق بجلاله، من غير تحريف ولا تعطيل، ومن غير تكييف ولا تمثيل؛ لأن الله تعالى نفى عن نفسه المثيل وأثبت لنفسه السمع والبصر في آية واحدة.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"فَاطِرُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَـٰمِ أَزْوَٰجًا ۖ يَذْرَؤُكُمْ فِيهِ ۚ لَيْسَ كَمِثْلِهِۦ شَىْءٌ ۖ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ","ref":"الشورى: ١١"},{"t":"aya","text":"وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا ۖ وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَـٰٓئِهِۦ ۚ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ","ref":"الأعراف: ١٨٠"},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"إثباتا حقيقيا على ما يليق بجلال الله سبحانه من غير تحريف ولا تعطيل ومن غير تكييف ولا تمثيل. ونؤمن بأن الله ليس كمثله شيء وهو السميع البصير فلا ننفي عنه ما وصف به نفسه ولا نحرف الكلم عن مواضعه ولا نكيف ولا نمثل صفاته بصفات خلقه؛ لأنه سبحانه لا سمي له ولا كفوء له ولا ند له ولا يقاس بخلقه سبحانه وتعالى. فكما أن له سبحانه ذاتا حقيقية لا تشبه ذوات خلقه فكذلك له صفات حقيقية لا تشبه صفات خلقه، ولا يلزم من إثبات الصفة للخالق سبحانه مشابهتها لصفة المخلوق","src":"مجموع فتاوى ابن باز","loc":"٣/٨٤","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"بَلْ عَلَى النَّاسِ أَنْ يَلْتَزِمُوا الْأُصُولَ الْجَامِعَةَ الْكُلِّيَّةَ الَّتِي اتَّفَقَ عَلَيْهَا سَلَفُ الْأُمَّةِ وَأَئِمَّتُهَا: فَيُؤْمِنُونَ بِمَا وَصَفَ اللَّهُ بِهِ نَفْسَهُ وَبِمَا وَصَفَهُ بِهِ رَسُولُهُ: مِنْ غَيْرِ تَحْرِيفٍ وَلَا تَعْطِيلٍ وَمِنْ غَيْرِ تَكْيِيفٍ وَلَا تَمْثِيلٍ","src":"مجموع الفتاوى","loc":"١٢/٤٦٦","pre":"وقال شيخ الإسلام ابن تيمية رحمه الله:"},{"t":"tanbih","items":[{"t":"p","text":"سلك بعض أهل العلم من الأشاعرة والماتريدية في بعض الصفات مسلك التفويض أو التأويل، وقصدهم تنزيه الله تعالى عن مشابهة خلقه، وهم علماء أجلاء خدموا السنة والفقه والتفسير. والأسلم ما كان عليه الصحابة والتابعون من الإثبات بلا تمثيل والتنزيه بلا تعطيل، مع حفظ مقام العلماء وعدم الطعن فيهم."}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الواجب إثبات ما أثبته الله لنفسه وأثبته له رسوله ﷺ، ونفي ما نفاه عن نفسه، وتفويض الكيفية إلى الله؛ فكما أن له ذاتًا لا تشبه الذوات، فله صفات لا تشبه الصفات."}],"refs":["مجموع فتاوى ابن باز (٣/٨٤)","مجموع الفتاوى (١٢/٤٦٦)"],"related":["استواء الله على العرش","معنى التوحيد وأقسامه"],"alts":["عقيدة السلف في الصفات","إثبات الصفات بلا تكييف","التأويل والتفويض"]},{"n":6,"bab":"العقيدة","sub":"الأسماء والصفات","title":"استواء الله على العرش","q":"ما معنى استواء الله تعالى على العرش الوارد في القرآن؟ وكيف نؤمن به؟","short":"نؤمن بأن الله تعالى استوى على عرشه استواءً يليق بجلاله، لا يشبه استواء المخلوقين، ولا نعلم كيفيته؛ كما قال الإمام مالك وشيخه ربيعة: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عنه بدعة.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"ٱلرَّحْمَـٰنُ عَلَى ٱلْعَرْشِ ٱسْتَوَىٰ","ref":"طه: ٥"},{"t":"aya","text":"إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ","ref":"الأعراف: ٥٤"},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"ولما سئل الإمام مالك رحمه الله عن ذلك, قال: (الاستواء معلوم والكيف مجهول والإيمان به واجب والسؤال عنه بدعة)","src":"مجموع فتاوى ابن باز","loc":"١/١٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"فبين - رحمه الله - أن الاستواء معلوم حيث نفى جهله وهو العلو والارتفاع. وأن الكيف لا يدرك بالعقل وإنما يدرك بالسمع، ولم يرد به فيبقى مجهولا، وأن الإيمان بالاستواء واجب على حسب مراد الله تعالى سواء فهمنا كيفيته أم لم نفهمها، وأن السؤال عنه أي عن الكيف بدعة، لأنه من سمات أهل البدع، ولأنه لم يسبق السؤال عنه من الصحابة الذين هم أحرص الناس على سلامة العقيدة وتصحيحها وفهم كلام الله ورسوله","src":"مجموع فتاوى ابن عثيمين","loc":"١/١٣٧","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"هذه القاعدة المأثورة عن الإمام مالك رحمه الله ميزان في سائر الصفات: معناها معلوم من لغة العرب التي نزل بها القرآن، وكيفيتها لا يعلمها إلا الله، والإيمان بها واجب، والخوض في كيفيتها بدعة."}],"refs":["مجموع فتاوى ابن باز (١/١٧)","مجموع فتاوى ابن عثيمين (١/١٣٧)"],"related":["منهج أهل السنة في الأسماء والصفات"],"alts":["آية الاستواء","قول مالك في الاستواء","أين الله"]},{"n":7,"bab":"العقيدة","sub":"القدر","title":"الإيمان بالقدر ومراتبه","q":"ما معنى الإيمان بالقدر؟ وما مراتبه؟","short":"الإيمان بالقدر ركن من أركان الإيمان، ومعناه: الإيمان بأن الله علم كل شيء، وكتبه في اللوح المحفوظ، وأن ما شاء كان وما لم يشأ لم يكن، وأنه خالق كل شيء. وهذه مراتبه الأربع: العلم، والكتابة، والمشيئة، والخلق.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"إِنَّا كُلَّ شَىْءٍ خَلَقْنَـٰهُ بِقَدَرٍ","ref":"القمر: ٤٩"},{"t":"aya","text":"أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ إِنَّ ذَٰلِكَ فِى كِتَـٰبٍ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ","ref":"الحج: ٧٠"},{"t":"aya","text":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ","ref":"التكوير: ٢٩"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُلُّ شَيْءٍ بِقَدَرٍ، حَتَّى الْعَجْزِ وَالْكَيْسِ، أَوِ الْكَيْسِ وَالْعَجْزِ","src":"رواه مسلم ٢٦٥٥","pre":"عن عبد الله بن عمر رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":2655,"id":"h2655"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"الإيمان بالقدر معناه أن تؤمن بأن الله - عز وجل - قد قدر كل شيء يكون إلى ما لا نهاية له، وأنه قدره عن علم، ولهذا قال العلماء: إن مراتب الإيمان بالقدر أربع مراتب","src":"مجموع فتاوى ابن عثيمين","loc":"٣/١٨٨","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"وهذه هي مراتب القدر الأربع التي يجب الإيمان بها، ولا يكون العبد مؤمنا بالقدر على الكمال حتى يكون مؤمنا بها","src":"فتاوى اللجنة الدائمة","loc":"١/٥٣","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الإيمان بالقدر لا ينافي الأخذ بالأسباب، ولا يسلب العبد اختياره؛ فللعبد مشيئة وقدرة يفعل بهما، وهما تابعتان لمشيئة الله وقدرته."}],"refs":["مسلم ٢٦٥٥","مجموع فتاوى ابن عثيمين (٣/١٨٨)","فتاوى اللجنة الدائمة (١/٥٣)"],"related":["الاحتجاج بالقدر على المعاصي","أركان الإيمان"],"alts":["مراتب القدر الأربع","القضاء والقدر","هل الإنسان مسير أم مخير"]},{"n":8,"bab":"العقيدة","sub":"القدر","title":"الاحتجاج بالقدر على المعاصي","q":"هل يجوز للإنسان أن يعتذر عن معصيته أو تركه للواجب بأن الله قدّر ذلك عليه؟","short":"لا يجوز الاحتجاج بالقدر على فعل المعاصي وترك الواجبات؛ لأن الله أمر ونهى، وأعطى العبد مشيئة واختيارًا، وأما الاحتجاج بالقدر على المصائب التي لا اختيار للعبد فيها، أو على ذنب تاب منه، فلا بأس به، وعليه يُحمل حديث احتجاج آدم وموسى عليهما السلام.","body":[{"t":"h","text":"الدليل من القرآن"},{"t":"aya","text":"سَيَقُولُ ٱلَّذِينَ أَشْرَكُوا۟ لَوْ شَآءَ ٱللَّهُ مَآ أَشْرَكْنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمْنَا مِن شَىْءٍ ۚ كَذَٰلِكَ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ حَتَّىٰ ذَاقُوا۟ بَأْسَنَا ۗ قُلْ هَلْ عِندَكُم مِّنْ عِلْمٍ فَتُخْرِجُوهُ لَنَآ ۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنْ أَنتُمْ إِلَّا تَخْرُصُونَ","ref":"الأنعام: ١٤٨"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"احْتَجَّ آدَمُ وَمُوسَى، فَقَالَ لَهُ مُوسَى يَا آدَمُ أَنْتَ أَبُونَا خَيَّبْتَنَا وَأَخْرَجْتَنَا مِنَ الْجَنَّةِ. قَالَ لَهُ آدَمُ يَا مُوسَى اصْطَفَاكَ اللَّهُ بِكَلاَمِهِ، وَخَطَّ لَكَ بِيَدِهِ، أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَ اللَّهُ عَلَىَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً. فَحَجَّ آدَمُ مُوسَى","src":"رواه البخاري ٦٦١٤","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":6614,"id":"h6614"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَإِنَّ الْقَدَرَ يَجِبُ الْإِيمَانُ بِهِ وَلَا يَجُوزُ الِاحْتِجَاجُ بِهِ عَلَى مُخَالَفَةِ أَمْرِ اللَّهِ وَنَهْيِهِ وَوَعْدِهِ وَوَعِيدِهِ","src":"مجموع الفتاوى","loc":"٢/٣٠٠","pre":"قال شيخ الإسلام ابن تيمية رحمه الله:"},{"t":"quote","text":"لكنه احتجاج بالقدر على المصيبة الناتجة من فعله، فهو من باب الاحتجاج بالقدر على المصائب لا على المعائب، ولهذا قال: «خيبتنا وأخرجتنا، ونفسك من الجنة» ولم يقل: عصيت ربك فأخرجت من الجنة","src":"مجموع فتاوى ابن عثيمين","loc":"٢/١٠٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله في حديث آدم وموسى:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"القدر يُحتج به عند المصائب، لا عند المعائب؛ فالمؤمن يصبر على ما قُدّر عليه من المصائب، ويتوب مما وقع فيه من الذنوب، ولا يجعل القدر عذرًا لترك أمر الله."}],"refs":["البخاري ٦٦١٤","مجموع الفتاوى (٢/٣٠٠)","مجموع فتاوى ابن عثيمين (٢/١٠٦)"],"related":["الإيمان بالقدر ومراتبه"],"alts":["المعصية بقدر الله","حديث آدم وموسى","الاحتجاج بالقدر"]},{"n":9,"bab":"العقيدة","sub":"أحكام الإيمان والكفر","title":"التحذير من تكفير المسلمين","q":"ما حكم تكفير المسلم أو رميه بالكفر بسبب خطأ أو معصية أو خلاف في مسألة؟","short":"لا يجوز تكفير مسلم بعينه بمعصية أو خطأ أو تأويل، ولا يُحكم بكفر من ثبت إسلامه إلا ببرهان واضح بعد إقامة الحجة عليه وانتفاء الموانع، وذلك إلى أهل العلم والقضاء، لا إلى آحاد الناس. وقد جاء الوعيد الشديد فيمن قال لأخيه: يا كافر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَيُّمَا رَجُلٍ قَالَ لأَخِيهِ يَا كَافِرُ. فَقَدْ بَاءَ بِهَا أَحَدُهُمَا","src":"رواه البخاري ٦١٠٤","pre":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":6104,"id":"h6104"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَلَيْسَ لِأَحَدِ أَنْ يُكَفِّرَ أَحَدًا مِنْ الْمُسْلِمِينَ وَإِنْ أَخْطَأَ وَغَلِطَ حَتَّى تُقَامَ عَلَيْهِ الْحُجَّةُ وَتُبَيَّنَ لَهُ الْمَحَجَّةُ وَمَنْ ثَبَتَ إسْلَامُهُ بِيَقِينِ لَمْ يَزُلْ ذَلِكَ عَنْهُ بِالشَّكِّ؛ بَلْ لَا يَزُولُ إلَّا بَعْدَ إقَامَةِ الْحُجَّةِ وَإِزَالَةِ الشُّبْهَةِ","src":"مجموع الفتاوى","loc":"١٢/٤٦٦","pre":"قال شيخ الإسلام ابن تيمية رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"التكفير حكم شرعي خطير، والخطأ في ترك تكفير من يستحقه أهون من الخطأ في تكفير مسلم. والواجب على المسلم حفظ لسانه، والحرص على جمع كلمة المسلمين، والنصح لمن أخطأ بالحكمة والموعظة الحسنة."}],"refs":["البخاري ٦١٠٤","مجموع الفتاوى (١٢/٤٦٦)"],"related":["الإيمان: قول وعمل، وزيادته ونقصانه"],"alts":["حكم التكفير","من قال لأخيه يا كافر","تكفير المعين"]},{"n":10,"bab":"الطهارة","sub":"المياه","title":"الوضوء والغسل بماء البحر","q":"هل يجوز الوضوء والغسل بماء البحر مع ملوحته؟","short":"نعم، ماء البحر طهور، يُتوضأ به ويُغتسل، ولا تضرّه ملوحته؛ وهذا قول عامة أهل العلم، ومنهم الأئمة الأربعة.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"ماء البحر ماء باقٍ على أصل خلقته، وإنما تغيّر طعمه بالملوحة التي خُلق عليها؛ فهل يخرجه ذلك عن كونه ماءً مطلقًا يُتطهَّر به؟"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طهور يُتوضأ به ويُغتسل كسائر المياه، وهو قول عامة أهل العلم."},{"t":"p","text":"ودليلهم عموم قوله تعالى:"},{"t":"aya","text":"ۚ وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءً طَهُورًا","ref":"الفرقان: ٤٨"},{"t":"p","text":"ونصُّ السنة الصريح فيه:"},{"t":"quote","text":"سَأَلَ رَجُلٌ رَسُولَ اللَّهِ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ إِنَّا نَرْكَبُ الْبَحْرَ وَنَحْمِلُ مَعَنَا الْقَلِيلَ مِنَ الْمَاءِ فَإِنْ تَوَضَّأْنَا بِهِ عَطِشْنَا أَفَنَتَوَضَّأُ مِنْ مَاءِ الْبَحْرِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ»","src":"رواه الترمذي ٦٩، وأبو داود ٨٣، والنسائي ٥٩، وابن ماجه ٣٨٦","pre":"عن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":69,"id":"h69"},{"book":"mt_abudawud","num":83,"id":"h83"},{"book":"mt_nasai","num":59,"id":"h59"},{"book":"mt_ibnmajah","num":386,"id":"h386"}]},{"t":"p","text":"قال الترمذي: هذا حديث حسن صحيح."},{"t":"quote","text":"أَخْرَجَهُ الْأَرْبَعَةُ، وَابْنُ أَبِي شَيْبَةَ، وَاللَّفْظُ لَهُ، وَصَحَّحَهُ ابْنُ خُزَيْمَةَ وَالتِّرْمِذِيُّ، وَرَوَاهُ مَالِكٌ وَالشَّافِعِيُّ وَأَحْمَدُ","src":"سبل السلام","loc":"١/١٩","pre":"وفي تخريجه قال الصنعاني:"},{"t":"quote","text":"وَرُوِيَ عَنْ عُمَرَ - رَضِيَ اللَّهُ عَنْهُ - أَنَّهُ قَالَ: \" مَنْ لَمْ يُطَهِّرْهُ مَاءُ الْبَحْرِ فَلَا طَهَّرَهُ اللَّهُ \" وَلِأَنَّهُ مَاءٌ بَاقٍ عَلَى أَصِلْ خِلْقَتِهِ، فَجَازَ الْوُضُوءُ بِهِ كَالْعَذْبِ","src":"المغني","loc":"١/٩","pre":"وقال ابن قدامة:"},{"t":"qawl","label":"القول الثاني","text":"كراهة التطهّر به، وأن التيمم أحب منه، وهو مرويّ عن عبد الله بن عمر وعبد الله بن عمرو رضي الله عنهم، وعن سعيد بن المسيب."},{"t":"quote","text":"إلَّا أَنَّهُ حُكِيَ عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ وَعَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّهُمَا قَالَا فِي الْبَحْرِ: التَّيَمُّمُ أَعْجَبُ إلَيْنَا مِنْهُ. هُوَ نَارٌ. وَحَكَاهُ الْمَاوَرْدِيُّ عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ","src":"المغني","loc":"١/٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"الثَّالِثَةُ) جَوَازُ الطَّهَارَةِ بِمَاءِ الْبَحْرِ (الرَّابِعَةُ) أَنَّ الْمَاءَ الْمُتَغَيِّرَ بِمَا يَتَعَذَّرُ صَوْنُهُ عَنْهُ طَهُورٌ","src":"المجموع","loc":"١/٨٤","pre":"وقال النووي الشافعي في «المجموع» في فوائد حديث البحر:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"يجوز لك أن تتوضأ بماء البحر لقوله صلى الله عليه وسلم: «هو الطهور ماؤه الحل ميتته » ولا فرق في ذلك سواء وجد عندك ماء عذب","src":"فتاوى اللجنة الدائمة","loc":"٥/٩٠","pre":"جاء في فتاوى اللجنة الدائمة للبحوث العلمية والإفتاء:"},{"t":"quote","text":"نعم يصح الوضوء بالماء المالح بطبيعته أو بوضع ملح فيه لأن النبي صلى الله عليه وسلم سُئل عن الوضوء بماء البحر فقال: \" هو الطهور ماؤه الحل ميتته\"","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٨٨","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن الوضوء بالماء المالح، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول بلا تردد؛ لأن الحديث صحيح صريح في محل السؤال نفسه، ولأن الله تعالى لم يأذن بالتيمم إلا عند فقد الماء، وماء البحر ماء."},{"t":"quote","text":"وَالْأَوَّلُ أَوْلَى، لِقَوْلِ اللَّهِ تَعَالَى: {فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا} النساء: 43 وَمَاءُ الْبَحْرِ مَاءٌ، لَا يَجُوزُ الْعُدُولُ إلَى التَّيَمُّمِ مَعَ وُجُودِهِ","src":"المغني","loc":"١/٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَقَوْلُهُمْ: \" هُوَ نَارٌ \" إنْ أُرِيدَ بِهِ أَنَّهُ نَارٌ فِي الْحَالِ فَهُوَ خِلَافُ الْحِسِّ، وَإِنْ أُرِيدَ أَنَّهُ يَصِيرُ نَارًا، لَمْ يَمْنَعْ ذَلِكَ الْوُضُوءَ بِهِ حَالَ كَوْنِهِ مَاءً","src":"المغني","loc":"١/٩"},{"t":"quote","text":"وَأَجْمَعَ الْعُلَمَاءُ عَلَى أَنَّ جَمِيعَ أَنْوَاعِ الْمِيَاهِ طَاهِرَةٌ فِي نَفْسِهَا مُطَهِّرَةٌ لِغَيْرِهَا، إِلَّا مَاءَ الْبَحْرِ، فَإِنَّ فِيهِ خِلَافًا فِي الصَّدْرِ الْأَوَّلِ شَاذًّا. وَهُمْ مَحْجُوجُونَ بِتَنَاوُلِ اسْمِ الْمَاءِ الْمُطْلَقِ لَهُ، وَبِالْأَثَرِ الَّذِي خَرَّجَهُ مَالِكٌ وَهُوَ قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - «هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مِيتَتُهُ» وَهُوَ وَإِنْ كَانَ حَدِيثًا مُخْتَلَفًا فِي صِحَّتِهِ، فَظَاهِرُ الشَّرْعِ يُعَضِّدُهُ","src":"بداية المجتهد","loc":"١/٢٩-٣٠","pre":"ولهذا حكى ابن رشد الاتفاق فقال:"}],"refs":["الترمذي ٦٩، وأبو داود ٨٣، والنسائي ٥٩، وابن ماجه ٣٨٦","سبل السلام (١/١٩)","المغني (١/٩)","المجموع (١/٨٤)","فتاوى اللجنة الدائمة (٥/٩٠)","مجموع فتاوى ابن عثيمين (١١/٨٨)","بداية المجتهد (١/٢٩-٣٠)"],"related":["الماء المتغير بطول المكث أو بالطحلب","الماء الذي خالطه شيء طاهر فغيّره"],"alts":["ماء البحر طاهر","الوضوء بالماء المالح","الاغتسال في البحر"]},{"n":11,"bab":"الطهارة","sub":"المياه","title":"الماء المتغير بطول المكث أو بالطحلب","q":"ماءٌ في خزان أو بركة تغيّر لونه أو رائحته بطول بقائه أو بالطحالب وأوراق الشجر، فهل يُتوضأ به؟","short":"نعم، يجوز الوضوء به عند عامة أهل العلم؛ لأن ما يغيّر الماء مما لا يُستطاع الاحتراز منه غالبًا لا يسلبه الطهورية، ما لم يكن التغير بنجاسة.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"يتغيّر الماء أحيانًا بلا نجاسة: إما بطول مكثه في مكانه — وهو الماء الآجن — وإما بما ينبت فيه أو يسقط فيه من غير قصد، كالطحلب وورق الشجر والتراب الذي يجري عليه."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه باقٍ على طهوريته، يُتوضأ به بلا كراهة، وهو قول جماهير أهل العلم."},{"t":"quote","text":"وَكَذَلِكَ أَجْمَعُوا عَلَى أَنَّ كُلَّ مَا يُغَيِّرُ الْمَاءَ مِمَّا لَا يَنْفَكُّ عَنْهُ غَالِبًا أَنَّهُ لَا يَسْلُبُهُ صِفَةَ الطَّهَارَةِ وَالتَّطْهِيرِ إِلَّا خِلَافًا شَاذًّا رُوِيَ فِي الْمَاءِ الْآجِنِ عَنِ ابْنِ سِيرِينَ، وَهُوَ أَيْضًا مَحْجُوجٌ بِتَنَاوُلِ اسْمِ الْمَاءِ الْمُطْلَقِ لَهُ","src":"بداية المجتهد","loc":"١/٣٠","pre":"قال ابن رشد:"},{"t":"quote","text":"الثَّانِي: مَا لَا يُمْكِنُ التَّحَرُّزُ مِنْهُ، كَالطُّحْلُبِ وَالْخَزِّ وَسَائِرِ مَا يَنْبُتُ فِي الْمَاءِ، وَكَذَلِكَ وَرَقُ الشَّجَرِ الَّذِي يَسْقُطُ فِي الْمَاءِ، أَوْ تَحْمِلُهُ الرِّيحُ فَتُلْقِيهِ فِيهِ، وَمَا تَجْذِبُهُ السُّيُولُ مِنْ الْعِيدَانِ وَالتِّبْنِ وَنَحْوِهِ، فَتُلْقِيهِ فِي الْمَاءِ، وَمَا هُوَ فِي قَرَارِ الْمَاءِ كَالْكِبْرِيتِ وَالْقَارِ وَغَيْرِهِمَا، إذَا جَرَى عَلَيْهِ الْمَاءُ فَتَغَيَّرَ بِهِ، أَوْ كَانَ فِي الْأَرْضِ الَّتِي يَقِفُ فِيهَا الْمَاءُ. فَهَذَا كُلُّهُ يُعْفَى عَنْهُ؛ لِأَنَّهُ يَشُقُّ التَّحَرُّزُ مِنْهُ، فَإِنْ أُخِذَ شَيْءٌ مِنْ ذَلِكَ وَأُلْقِيَ فِي الْمَاءِ وَغَيْرِهِ كَانَ حُكْمُهُ حُكْمَ مَا أَمْكَنَ التَّحَرُّزُ مِنْهُ، مِنْ الزَّعْفَرَانِ وَنَحْوِهِ؛ لِأَنَّ الِاحْتِرَازَ مِنْهُ مُمْكِنٌ","src":"المغني","loc":"١/١٢","pre":"وقال ابن قدامة في أنواع الماء المضاف الذي يجوز الوضوء به:"},{"t":"qawl","label":"القول الثاني","text":"كراهة الوضوء بالماء الآجن، وهو قول محمد بن سيرين وحده."},{"t":"quote","text":"وَالْمَاءُ الْآجِنُ، وَهُوَ الَّذِي يَتَغَيَّرُ بِطُولِ مُكْثِهِ فِي الْمَكَانِ، مِنْ غَيْرِ مُخَالَطَةِ شَيْءٍ يُغَيِّرُهُ، بَاقٍ عَلَى إطْلَاقِهِ فِي قَوْلِ أَكْثَرِ أَهْلِ الْعِلْمِ، قَالَ ابْنُ الْمُنْذِرِ: أَجْمَعَ كُلُّ مَنْ نَحْفَظُ قَوْلَهُ مِنْ أَهْلِ الْعِلْمِ عَلَى أَنَّ الْوُضُوءَ بِالْمَاءِ الْآجِنِ مِنْ غَيْرِ نَجَاسَةٍ حَلَّتْ فِيهِ جَائِزٌ، غَيْرَ ابْنِ سِيرِينَ فَإِنَّهُ كَرِهَ ذَلِكَ","src":"المغني","loc":"١/١٢","pre":"قال ابن قدامة:"},{"t":"quote","text":"فَإِنْ كَانَ مِمَّا لَا يُمْكِنُ حِفْظُ الْمَاءِ مِنْهُ كَالطُّحْلُبِ وَمَا يَجْرِي عَلَيْهِ الْمَاءُ مِنْ الْمِلْحِ وَالنُّورَةِ وَغَيْرِهِمَا جَازَ الْوُضُوءُ بِهِ","src":"المجموع","loc":"١/١٠١","pre":"وقال أبو إسحاق الشيرازي في «المهذب» من كتب الشافعية، مع شرحه «المجموع» للنووي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"هذا الماء طهور وإن تغير، لأنه لم يتغير بمازج خارج وإنما تغير بطول مُكثه في هذا المكان، وهذا لا بأس به يُتوضأ منه والوضوء صحيح","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٨٨","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"فإن هذا لا يضر، ولو حصل بعض التغير بذلك، كما لو تغير بالطحلب الذي ينبت فيه، وبأوراق الشجر، وبالتراب الذي يعتريه، وما أشبه ذلك","src":"مجموع فتاوى ابن باز","loc":"١٠/١٩","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح قول الجمهور؛ لأن هذا التغير لا ينفك عنه الماء في العادة، ولا يُخرجه عن اسم الماء المطلق."},{"t":"quote","text":"وَقَوْلُ الْجُمْهُورِ أُولَى، فَإِنَّهُ يُرْوَى «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - تَوَضَّأَ مِنْ بِئْرٍ كَأَنَّ مَاءَهُ نُقَاعَةُ الْحِنَّاءِ» وَلِأَنَّهُ تَغَيَّرَ مِنْ غَيْرِ مُخَالَطَةٍ","src":"المغني","loc":"١/١٢","pre":"قال ابن قدامة:"},{"t":"tanbih","items":[{"t":"p","text":"إذا أُلقي الطحلب أو الورق في الماء قصدًا حتى غيّره، فحكمه حكم الماء الذي خالطه شيء طاهر (انظر الفتوى رقم ٣)، كما في كلام ابن قدامة المنقول آنفًا."},{"t":"p","text":"وإذا كان تغيّر الماء بنجاسة لم يجز الوضوء به، وهذا باب آخر (انظر الفتوى رقم ٥)."}]}],"refs":["بداية المجتهد (١/٣٠)","المغني (١/١٢)","المجموع (١/١٠١)","مجموع فتاوى ابن عثيمين (١١/٨٨)","مجموع فتاوى ابن باز (١٠/١٩)"],"related":["الماء الذي خالطه شيء طاهر فغيّره","الماء القليل تقع فيه نجاسة ولم يتغير"],"alts":["الماء الآسن","ماء الخزان المتغير","الطحالب في الماء"]},{"n":12,"bab":"الطهارة","sub":"المياه","title":"الماء الذي خالطه شيء طاهر فغيّره","q":"هل يجوز الوضوء بماء خالطه صابون أو زعفران أو نحوهما فتغيّر لونه أو ريحه؟","short":"إن بقي اسم الماء عليه ورقّته وجريانه — كماء قليلِ الصابون أو السدر — جاز الوضوء به على الراجح، وهو مذهب الحنفية ورواية عن أحمد؛ وإن غلب عليه المخالط حتى صار يسمّى باسم آخر — كالشاي والحبر وماء الورد — لم يجز بالاتفاق.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"p","text":"اتفق العلماء على طرفين في هذه المسألة، واختلفوا فيما بينهما:"},{"t":"quote","text":"وَلَا نَعْلَمُ خِلَافًا بَيْنَ أَهْلِ الْعِلْمِ فِي جَوَازِ الْوُضُوءِ بِمَاءٍ خَالَطَهُ طَاهِرٌ، لَمْ يُغَيِّرْهُ، إلَّا مَا حُكِيَ عَنْ أُمِّ هَانِئٍ، فِي مَاءٍ بُلَّ فِيهِ خُبْزٌ: لَا يُتَوَضَّأُ بِهِ. وَلَعَلَّهَا أَرَادَتْ مَا تَغَيَّرَ بِهِ","src":"المغني","loc":"١/١٣","pre":"الطرف الأول — ما لم يتغير بالمخالط: قال ابن قدامة:"},{"t":"quote","text":"أَحَدُهَا، مَا اُعْتُصِرَ مِنْ الطَّاهِرَاتِ كَمَاءِ الْوَرْدِ، وَمَاءِ الْقَرَنْفُلِ، وَمَا يَنْزِلُ مِنْ عُرُوقِ الشَّجَرِ إذَا قُطِعَتْ رَطْبَةً. الثَّانِي، مَا خَالَطَهُ طَاهِرٌ فَغَيَّرَ اسْمَهُ، وَغَلَبَ عَلَى أَجْزَائِهِ، حَتَّى صَارَ صِبْغًا، أَوْ حِبْرًا، أَوْ خَلًّا، أَوْ مَرَقًا، وَنَحْوَ ذَلِكَ. الثَّالِثُ، مَا طُبِخَ فِيهِ طَاهِرٌ فَتَغَيَّرَ بِهِ، كَمَاءِ الْبَاقِلَّا الْمَغْلِيِّ. فَجَمِيعُ هَذِهِ الْأَنْوَاعِ لَا يَجُوزُ الْوُضُوءُ بِهَا، وَلَا الْغُسْلُ، لَا نَعْلَمُ فِيهِ خِلَافًا، إلَّا مَا حُكِيَ عَنْ ابْنِ أَبِي لَيْلَى وَالْأَصَمِّ فِي الْمِيَاهِ الْمُعْتَصَرَةِ، أَنَّهَا طَهُورٌ يَرْتَفِعُ بِهَا الْحَدَثُ، وَيُزَالُ بِهَا النَّجَسُ","src":"المغني","loc":"١/١١","pre":"الطرف الثاني — ما غلب عليه المخالط حتى زال عنه اسم الماء: قال ابن قدامة:"},{"t":"p","text":"وأما محل الخلاف: فهو الماء الذي غيّر المخالطُ الطاهر أحدَ أوصافه، وبقي مع ذلك يسمّى ماءً."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر غير مطهِّر، فلا يرفع الحدث، وهو قول مالك والشافعي وإسحاق، ورواية عن أحمد."},{"t":"quote","text":"وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي الْوُضُوءِ بِهِ، وَاخْتَلَفْت الرِّوَايَةُ عَنْ إمَامِنَا، - رَحِمَهُ اللَّهُ -، فِي ذَلِكَ؛ فَرُوِيَ عَنْهُ: لَا تَحْصُلُ الطَّهَارَةُ بِهِ. وَهُوَ قَوْلُ مَالِكٍ وَالشَّافِعِيِّ وَإِسْحَاقَ وَقَالَ الْقَاضِي أَبُو يَعْلَى وَهِيَ أَصَحُّ، وَهِيَ الْمَنْصُورَةُ عِنْدَ أَصْحَابِنَا فِي الْخِلَافِ","src":"المغني","loc":"١/١١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَوَجْهُ الْأُولَى: أَنَّهُ مَاءٌ تَغَيَّرَ بِمُخَالَطَةِ مَا لَيْسَ بِطَهُورٍ يُمْكِنُ الِاحْتِرَازُ مِنْهُ، فَلَمْ يَجُزْ الْوُضُوءُ بِهِ، كَمَاءِ الْبَاقِلَّا الْمَغْلِيِّ؛ وَلِأَنَّهُ زَالَ عَنْ إطْلَاقِهِ، فَأَشْبَهَ الْمَغْلِيَّ","src":"المغني","loc":"١/١١","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثاني","text":"أنه طهور يُتوضأ به ما دام اسم الماء باقيًا عليه، وهو مذهب أبي حنيفة وأصحابه، ورواية عن أحمد نقلها جماعة من أصحابه."},{"t":"quote","text":"وَنَقَلَ عَنْ أَحْمَدَ جَمَاعَةٌ مِنْ أَصْحَابِهِ، مِنْهُمْ أَبُو الْحَارِثِ، وَالْمَيْمُونِيُّ، وَإِسْحَاقُ بْنُ مَنْصُورٍ، جَوَازَ الْوُضُوءِ بِهِ. وَهَذَا مَذْهَبُ أَبِي حَنِيفَةَ وَأَصْحَابِهِ؛ لِأَنَّ اللَّهَ تَعَالَى قَالَ: {فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا} النساء: 43 وَهَذَا عَامٌّ فِي كُلِّ مَاءٍ؛ لِأَنَّهُ نَكِرَةٌ فِي سِيَاقِ النَّفْيِ، وَالنَّكِرَةُ فِي سِيَاقِ النَّفْي تَعُمُّ، فَلَا يَجُوزُ التَّيَمُّمُ مَعَ وُجُودِهِ، وَأَيْضًا قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي حَدِيثِ أَبِي ذَرٍّ: «التُّرَابُ كَافِيكَ مَا لَمْ تَجِدْ الْمَاءَ» . وَهَذَا وَاجِدٌ لِلْمَاءِ؛ وَلِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ كَانُوا يُسَافِرُونَ، وَغَالِبُ أَسْقِيَتِهِمْ الْأُدْمُ، وَالْغَالِبُ أَنَّهَا تُغَيِّرُ الْمَاءَ، فَلَمْ يُنْقَلْ عَنْهُمْ تَيَمُّمٌ مَعَ وُجُودِ شَيْءٍ مِنْ تِلْكَ الْمِيَاهِ؛ وَلِأَنَّهُ طَهُورٌ خَالَطَهُ طَاهِرٌ لَمْ يَسْلُبْهُ اسْمَ الْمَاءِ، وَلَا رِقَّتَهُ، وَلَا جَرَيَانَهُ، فَأَشْبَهَ الْمُتَغَيِّرَ بِالدُّهْنِ","src":"المغني","loc":"١/١١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَكَذَا يَجُوزُ بِمَاءٍ خَالَطَهُ طَاهِرٌ جَامِدٌ مُطْلَقًا كَأُشْنَانٍ وَزَعْفَرَانٍ لَكِنْ فِي الْبَحْرِ عَنْ الْقُنْيَةِ: إنْ أَمْكَنَ الصَّبْغُ بِهِ لَمْ يَجُزْ كَنَبِيذِ تَمْرٍ","src":"الدر المختار مع رد المحتار","loc":"١/١٨٦","pre":"وقال في «الدر المختار» من كتب الحنفية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وإن كان التغير بطاهر أو بطول مكثه جاز الوضوء به وكذلك الغسل وإزالة النجاسة","src":"فتاوى اللجنة الدائمة","loc":"٥/٩٢","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"فإن العلماء متفقون على أن الماء إذا خالطه طاهرٌ فسلبه اسم الماء لم يجز التطهر به، وأيضاً فهم كالمتفقين على عدم جواز التطهر بالماء المعتصر كماء الورد ونحوه","src":"فتاوى الشبكة الإسلامية","loc":"١١/١٧","pre":"وجاء في فتاوى الشبكة الإسلامية:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح — والله أعلم — القول الثاني؛ لأن الله تعالى علّق التيمم بعدم الماء، وهذا ماء، ولأن النبي ﷺ أمر بغسل الميت بماء وسدر، ومعلوم أن السدر يغيّر الماء."},{"t":"quote","text":"دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ تُوُفِّيَتِ ابْنَتُهُ فَقَالَ «اغْسِلْنَهَا ثَلاَثًا أَوْ خَمْسًا أَوْ أَكْثَرَ مَنْ ذَلِكَ إِنْ رَأَيْتُنَّ ذَلِكَ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا أَوْ شَيْئًا مِنْ كَافُورٍ، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي»","src":"رواه البخاري ١٢٥٣","pre":"وحديث أم عطية رضي الله عنها في تغسيل ابنة النبي ﷺ قالت:","links":[{"book":"mt_bukhari","num":1253,"id":"h1253"}]},{"t":"tanbih","items":[{"t":"p","text":"فالضابط في هذا الباب: بقاء اسم الماء المطلق؛ فما دام الناس يسمّونه ماءً جاز التطهّر به، فإذا صار يسمّى باسم المخالط — شايًا أو مرقًا أو عصيرًا — خرج عن ذلك."}]}],"refs":["المغني (١/١٣)","المغني (١/١١)","الدر المختار مع رد المحتار (١/١٨٦)","فتاوى اللجنة الدائمة (٥/٩٢)","فتاوى الشبكة الإسلامية (١١/١٧)","بداية المجتهد (١/٣٣)","البخاري ١٢٥٣"],"related":["الوضوء بالنبيذ وسائر المائعات","الماء المتغير بطول المكث أو بالطحلب"],"alts":["الوضوء بماء فيه صابون","الماء المخلوط","الوضوء بماء الزعفران"]},{"n":13,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالماء المستعمل","q":"هل يجوز الوضوء بالماء الذي استُعمل في وضوء أو غسل قبل ذلك؟","short":"الماء المستعمل طاهر باتفاق المعتمد في المذاهب، والراجح أنه مطهِّر أيضًا ما لم يتغير؛ والأولى أن يُستعمل غيره إن تيسّر، خروجًا من الخلاف.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"الماء المستعمل: هو الماء المنفصل عن أعضاء المتوضئ أو المغتسل بعد استعماله في رفع الحدث. أما ما استُعمل في التبرّد أو التنظيف فلا خلاف فيه:"},{"t":"quote","text":"وَلَا تَخْتَلِفُ الرِّوَايَةُ أَنَّ مَا اُسْتُعْمِلَ فِي التَّبَرُّدِ وَالتَّنْظِيفِ، أَنَّهُ بَاقٍ عَلَى إطْلَاقِهِ، وَلَا نَعْلَمُ فِيهِ خِلَافًا","src":"المغني","loc":"١/١٨","pre":"قال ابن قدامة:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر غير مطهِّر، وهو ظاهر مذهب أحمد والشافعي، والمشهور عن أبي حنيفة، وإحدى الروايتين عن مالك."},{"t":"quote","text":"وَظَاهِرُ الْمَذْهَبِ أَنَّ الْمُسْتَعْمَلَ فِي رَفْعِ الْحَدَثِ طَاهِرٌ غَيْرُ مُطَهِّرٍ، لَا يَرْفَعُ حَدَثًا، وَلَا يُزِيلُ نَجَسًا، وَبِهِ قَالَ اللَّيْثُ وَالْأَوْزَاعِيُّ، وَهُوَ الْمَشْهُورُ عَنْ أَبِي حَنِيفَةَ، وَإِحْدَى الرِّوَايَتَيْنِ عَنْ مَالِكٍ، وَظَاهِرُ مَذْهَبِ الشَّافِعِيِّ","src":"المغني","loc":"١/١٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"فَالدَّلِيلُ عَلَى خُرُوجِهِ عَنْ الطَّهُورِيَّةِ قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَا يَغْتَسِلْ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ وَهُوَ جُنُبٌ» رَوَاهُ مُسْلِمٌ، مَنَعَ مِنْ الْغُسْلِ فِيهِ كَمَنْعِهِ مِنْ الْبَوْلِ فِيهِ، فَلَوْلَا أَنَّهُ يُفِيدُهُ مَنْعًا لَمْ يَنْهَ عَنْهُ؛ وَلِأَنَّهُ أُزِيلَ بِهِ مَانِعٌ مِنْ الصَّلَاةِ، فَلَمْ يَجُزْ اسْتِعْمَالُهُ فِي طَهَارَةٍ أُخْرَى، كَالْمُسْتَعْمَلِ فِي إزَالَةِ النَّجَاسَةِ","src":"المغني","loc":"١/١٧","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثاني","text":"أنه طاهر مطهِّر، وهو رواية عن أحمد ومالك، وقول للشافعي، وقول أهل الظاهر وجماعة من التابعين."},{"t":"quote","text":"وَعَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى، أَنَّهُ طَاهِرٌ مُطَهِّرٌ. وَبِهِ قَالَ الْحَسَنُ، وَعَطَاءٌ، وَالنَّخَعِيُّ، وَالزُّهْرِيُّ، وَمَكْحُولٌ، وَأَهْلُ الظَّاهِرِ، وَالرِّوَايَةُ الثَّانِيَةُ لِمَالِكٍ، وَالْقَوْلُ الثَّانِي لِلشَّافِعِيِّ. وَرُوِيَ عَنْ عَلِيٍّ، وَابْنِ عُمَرَ، وَأَبِي أُمَامَةَ فِيمَنْ نَسِيَ مَسْحَ رَأْسِهِ، إذَا وَجَدَ بَلَلًا فِي لِحْيَتِهِ، أَجْزَأَهُ أَنْ يَمْسَحَ رَأْسَهُ بِذَلِكَ الْبَلَلِ","src":"المغني","loc":"١/١٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَوَجْهُ ذَلِكَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «الْمَاءُ لَا يُجْنِبُ» ، وَقَالَ: «الْمَاءُ لَيْسَ عَلَيْهِ جَنَابَةٌ» ، وَرُوِيَ «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - اغْتَسَلَ مِنْ الْجَنَابَةِ، فَرَأَى لُمْعَةً لَمْ يُصِبْهَا الْمَاءُ، فَعَصَرَ شَعَرَهُ عَلَيْهَا» . رَوَاهُمَا الْإِمَامُ أَحْمَدُ، فِي \" الْمُسْنَدِ \" وَابْنُ مَاجَهْ، وَغَيْرُهُمَا وَلِأَنَّهُ غُسِلَ بِهِ مَحَلٌّ طَاهِرٌ، فَلَمْ تَزُلْ بِهِ طَهُورِيَّتُهُ، كَمَا لَوْ غُسِلَ بِهِ الثَّوْبُ؛ وَلِأَنَّهُ لَاقَى مَحَلًّا طَاهِرًا، فَلَا يَخْرُجُ عَنْ حُكْمِهِ بِتَأْدِيَةِ الْفَرْضِ بِهِ، كَالثَّوْبِ يُصَلَّى فِيهِ مِرَارًا","src":"المغني","loc":"١/١٦","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثالث","text":"أنه نجس، وهو قول أبي يوسف، ورواية عن أبي حنيفة."},{"t":"quote","text":"وَقَالَ أَبُو يُوسُفَ: هُوَ نَجِسٌ. وَهُوَ رِوَايَةٌ عَنْ أَبِي حَنِيفَةَ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ، وَلَا يَغْتَسِلْ فِيهِ مِنْ جَنَابَةٍ.» رَوَاهُ أَبُو دَاوُد فَاقْتَضَى أَنَّ الْغُسْلَ فِيهِ، كَالْبَوْلِ فِيهِ؛ وَلِأَنَّهُ يُسَمَّى طَهَارَةً وَالطَّهَارَةُ لَا تَكُونُ إلَّا عَنْ نَجَاسَةٍ، إذْ تَطْهِيرُ الطَّاهِرِ لَا يُعْقَلُ","src":"المغني","loc":"١/١٧","pre":"قال ابن قدامة:"},{"t":"quote","text":"مَسْأَلَةٌ: وَالْوُضُوءُ بِالْمَاءِ الْمُسْتَعْمَلِ جَائِزٌ، وَكَذَلِكَ الْغُسْلُ بِهِ لِلْجَنَابَةِ، وَسَوَاءٌ وُجِدَ مَاءٌ آخَرُ غَيْرُهُ أَوْ لَمْ يُوجَدْ","src":"المحلى","loc":"١/١٨٢","pre":"وقال ابن حزم في «المحلى»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الوضوء من الماء المجتمع في إناء من أعضاء المتوضئ أو المغتسل يعتبر طاهرا. واختلف العلماء في طهوريته، هل هو طهور يجوز الوضوء والغسل به، أم طاهر فقط، كالماء المقيد مثل: ماء الرمان وماء العنب، ونحوهما؟ والأرجح: أنه طهور؛ لعموم قول النبي - صلى الله عليه وسلم -: «إن الماء طهور لا ينجسه شيء » أخرجه الإمام أحمد، وأهل السنن إلا ابن ماجه بإسناد صحيح. ولا يستثنى من ذلك إلا ما تغير لونه أو طعمه أو ريحه بالنجاسة، فإذا تغير بذلك صار نجسا بالإجماع. لكن ترك الوضوء من مثل هذا الماء المستعمل أولى وأحوط؛ خروجا من الخلاف، ولما يقع فيه من بعض الأوساخ، الحاصلة بالوضوء به أو الغسل","src":"مجموع فتاوى ابن باز","loc":"١٠/١٨","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن الوضوء من الماء المجتمع تحت الصنبور، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"أما القول بنجاسته فمردود بالأحاديث الصحيحة في تبرّك الصحابة بوضوء النبي ﷺ، وصبّه وَضوءه على جابر رضي الله عنه:"},{"t":"quote","text":"جَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعُودُنِي، وَأَنَا مَرِيضٌ لاَ أَعْقِلُ، فَتَوَضَّأَ وَصَبَّ عَلَىَّ مِنْ وَضُوئِهِ، فَعَقَلْتُ","src":"رواه البخاري ١٩٤","pre":"عن جابر بن عبد الله رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":194,"id":"h194"}]},{"t":"p","text":"وقد حقّق علماء الحنفية أنفسهم أن رواية النجاسة ضعيفة، وأن المفتى به عندهم طهارته؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"قال الشيخ ابن الهُمَام وابن نُجَيم رحمهما الله تعالى: إنَّ العراقيين قاطبةً أنكروا روايةَ النجاسة عن الإِمام، وهم المُتَثَبِّتُون في نقل مذهب الإِمام عندي. وأثبَتَها ما وراء النهر من علمائنا، وهي ضعيفة جدًا، لأنِّي لا أجدُ أحدًا من السلف يُعَامِلُ الماءَ المستعمل معاملة النجاسات، إلا أنه لا شك أن المطلوب عند الشرع هو صيانةُ وضوئه عنه، كما عند الطحاوي عن أبي هريرة قال رسول الله صلى الله عليه وسلّم «لا يَغْتَسِلُ أحدكُم في الماء وهو جنب»، فقال: كيف يفعل يا أبا هريرة فقال: «يتناوله تناولًا». وكذا نَهَى الرجلَ عن فَضلِ طَهورِ المرأة. عندي يُبتنى على هذه الدقيقة كما سيجيء تقريره","src":"فيض الباري","loc":"١/٣٨٦-٣٨٧"},{"t":"quote","text":"اتَّفَقَ أَصْحَابُنَا - رَحِمَهُمُ اللَّهُ - أَنَّ الْمَاءَ الْمُسْتَعْمَلَ لَيْسَ بِطَهُورٍ حَتَّى لَا يَجُوزُ التَّوَضُّؤُ بِهِ وَاخْتَلَفُوا فِي طَهَارَتِهِ قَالَ مُحَمَّدٌ - رَحِمَهُ اللَّهُ -: هُوَ طَاهِرٌ وَهُوَ رِوَايَةٌ عَنْ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ - وَعَلَيْهِ الْفَتْوَى","src":"الفتاوى الهندية","loc":"١/٢٢","pre":"وفي «الفتاوى الهندية»:"},{"t":"p","text":"وبقي الخلاف بين القولين الأولين في رفع الحدث به، والأظهر أنه مطهِّر؛ لأنه ماء طاهر لاقى أعضاءً طاهرة، فلم يخرج عن اسم الماء المطلق، وقد قال النبي ﷺ: «الماء لا يجنب». وأما نهيه ﷺ الجنبَ عن الاغتسال في الماء الدائم فمحمول على صيانة الماء عن أن يُستقذر ويُفسد على غيره، كما أشار إليه الشيخ الكشميري بقوله: إن المطلوب عند الشرع صيانة الوضوء عنه."},{"t":"quote","text":"وَقَدْ ثَبَتَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - كَانَ أَصْحَابُهُ يَقْتَتِلُونَ عَلَى فَضْلِ وُضُوئِهِ. وَلَا بُدَّ أَنْ يَقَعَ مِنَ الْمَاءِ الْمُسْتَعْمَلِ فِي الْإِنَاءِ الَّذِي بَقِيَ فِيهِ الْفَضْلُ.","src":"بداية المجتهد","loc":"١/٣٤","pre":"وقال ابن رشد:"}],"refs":["المغني (١/١٨)","المغني (١/١٦)","المغني (١/١٧)","المحلى (١/١٨٢)","مجموع فتاوى ابن باز (١٠/١٨)","البخاري ١٩٤","فيض الباري (١/٣٨٦-٣٨٧)","الفتاوى الهندية (١/٢٢)","بداية المجتهد (١/٣٤)"],"related":["الماء الذي خالطه شيء طاهر فغيّره"],"alts":["الماء المتساقط من الوضوء","إعادة استعمال ماء الوضوء","ماء الغسل المستعمل"]},{"n":14,"bab":"الطهارة","sub":"المياه","title":"الماء القليل تقع فيه نجاسة ولم يتغير","q":"وقعت نجاسة يسيرة في ماء قليل ولم يتغير لونه ولا طعمه ولا ريحه، فهل ينجس؟","short":"اختلف العلماء فيه على قولين مشهورين: فمنهم من قال: لا ينجس الماء إلا بالتغير، قليلًا كان أو كثيرًا؛ ومنهم من فرّق بين القليل والكثير، ثم اختلف هؤلاء في حد الكثير: فقدّره الشافعي وأحمد بالقلتين، وجعله الحنفية ما يغلب على ظن المبتلى به أن النجاسة لا تصل إلى جانبه الآخر. والأظهر دليلًا أنه لا ينجس إلا بالتغير، والأحوط أن يُترك الماء القليل الذي وقعت فيه نجاسة إذا وُجد غيره.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"فَأَمَّا نَجَاسَةُ مَا تَغَيَّرَ بِالنَّجَاسَةِ فَلَا خِلَافَ فِيهِ، قَالَ ابْنُ الْمُنْذِرِ: أَجْمَعَ أَهْلُ الْعِلْمِ عَلَى أَنَّ الْمَاءَ الْقَلِيلَ وَالْكَثِيرَ، إذَا وَقَعَتْ فِيهِ نَجَاسَةٌ فَغَيَّرَتْ لِلْمَاءِ طَعْمًا أَوْ لَوْنًا أَوْ رَائِحَةً، أَنَّهُ نَجِسٌ مَا دَامَ كَذَلِكَ","src":"المغني","loc":"١/٢٠","pre":"اتفق العلماء على أن الماء إذا غيّرته النجاسة نجس، قليلًا كان أو كثيرًا؛ قال ابن قدامة:"},{"t":"p","text":"واختلفوا في الماء تقع فيه النجاسة فلا تغيّره، على قولين؛ وأصحاب القول الثاني طائفتان:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أن الماء لا ينجس إلا إذا تغيّر أحد أوصافه بالنجاسة، قليلًا كان أو كثيرًا."},{"t":"quote","text":"وَرُوِيَ عَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى، أَنَّ الْمَاءَ لَا يَنْجُسُ إلَّا بِالتَّغَيُّرِ قَلِيلُهُ وَكَثِيرُهُ، وَرُوِيَ مِثْلُ ذَلِكَ عَنْ حُذَيْفَةَ، وَأَبِي هُرَيْرَةَ، وَابْنِ عَبَّاسٍ، قَالُوا: الْمَاءُ لَا يَنْجُسُ. وَرُوِيَ ذَلِكَ عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ، وَالْحَسَنِ، وَعِكْرِمَةَ، وَعَطَاءٍ، وَجَابِرِ بْنِ زَيْدٍ، وَابْنِ أَبِي لَيْلَى، وَمَالِكٍ وَالْأَوْزَاعِيِّ، وَالثَّوْرِيِّ، وَيَحْيَى الْقَطَّانِ، وَعَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ، وَابْنِ الْمُنْذِرِ، وَهُوَ قَوْلٌ لِلشَّافِعِيِّ","src":"المغني","loc":"١/٢٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"فَقَالَ قَوْمٌ: هُوَ طَاهِرٌ سَوَاءٌ أَكَانَ كَثِيرًا أَوْ قَلِيلًا، وَهِيَ إِحْدَى الرِّوَايَاتِ عَنْ مَالِكٍ، وَبِهِ قَالَ أَهْلُ الظَّاهِرِ","src":"بداية المجتهد","loc":"١/٣٠","pre":"وقال ابن رشد:"},{"t":"quote","text":"قِيلَ يَا رَسُولَ اللَّهِ أَنَتَوَضَّأُ مِنْ بِئْرِ بُضَاعَةَ وَهِيَ بِئْرٌ يُلْقَى فِيهَا الْحِيَضُ وَلُحُومُ الْكِلاَبِ وَالنَّتْنُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّ الْمَاءَ طَهُورٌ لاَ يُنَجِّسُهُ شَيْءٌ»","src":"رواه الترمذي ٦٦، وأبو داود ٦٧","pre":"ومن أدلتهم حديث أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":66,"id":"h66"},{"book":"mt_abudawud","num":67,"id":"h67"}]},{"t":"p","text":"حسّنه الترمذي، وصححه الإمام أحمد."},{"t":"quote","text":"وَرُوِيَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «سُئِلَ عَنْ الْحِيَاضِ الَّتِي بَيْنَ مَكَّةَ وَالْمَدِينَةِ، تَرِدُهَا السِّبَاعُ وَالْكِلَابُ وَالْحُمُرُ، وَعَنْ الطَّهَارَةِ بِهَا، فَقَالَ: لَهَا مَا حَمَلَتْ فِي بُطُونِهَا، وَلَنَا مَا غَبَرَ طَهُورٌ» وَلَمْ يُفَرِّقْ بَيْنَ الْقَلِيلِ وَالْكَثِيرِ؛ وَلِأَنَّهُ لَمْ يَظْهَرْ عَلَيْهِ إحْدَى صِفَاتُ النَّجَاسَةِ، فَلَمْ يَنْجُسْ بِهَا كَالزَّائِدِ عَنْ الْقُلَّتَيْنِ","src":"المغني","loc":"١/٢٠"},{"t":"qawl","label":"القول الثاني","text":"التفريق بين القليل والكثير: فالكثير لا ينجس إلا بالتغير، والقليل ينجس بمجرد ملاقاة النجاسة وإن لم يتغير."},{"t":"taifa","label":"الطائفة الأولى","text":"قدّرت الكثير بالقلتين، فما بلغهما لم ينجس إلا بالتغير، وما دونهما قليل ينجس بالملاقاة؛ وهو مذهب الشافعي، والمشهور عن أحمد، وقول إسحاق وأبي عبيد، ومروي عن ابن عمر رضي الله عنهما."},{"t":"quote","text":"وَأَمَّا مَا دُونَ الْقُلَّتَيْنِ إذَا لَاقَتْهُ النَّجَاسَةُ فَلَمْ يَتَغَيَّرْ بِهَا، فَالْمَشْهُورُ فِي الْمَذْهَبِ أَنَّهُ يَنْجُسُ، وَرُوِيَ عَنْ ابْنِ عُمَرَ، وَسَعِيدِ بْنِ جُبَيْرٍ، وَمُجَاهِدٍ، وَبِهِ قَالَ الشَّافِعِيُّ، وَإِسْحَاقُ، وَأَبُو عُبَيْدٍ","src":"المغني","loc":"١/٢٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"إِذَا كَانَ الْمَاءُ قُلَّتَيْنِ لَمْ يَحْمِلِ الْخَبَثَ","src":"رواه الترمذي ٦٧، وأبو داود ٦٣، والنسائي ٥٢، وابن ماجه ٥١٨","pre":"ودليلهم حديث عبد الله بن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_tirmidhi","num":67,"id":"h67"},{"book":"mt_abudawud","num":63,"id":"h63"},{"book":"mt_nasai","num":52,"id":"h52"},{"book":"mt_ibnmajah","num":518,"id":"h518"}]},{"t":"p","text":"صححه ابن خزيمة والحاكم وابن حبان."},{"t":"quote","text":"وَتَحْدِيدُهُ بِالْقُلَّتَيْنِ يَدُلُّ عَلَى أَنَّ مَا دُونَهُمَا يَنْجُسُ، إذْ لَوْ اسْتَوَى حُكْمُ الْقُلَّتَيْنِ وَمَا دُونَهُمَا لَمْ يَكُنْ التَّحْدِيدُ مُفِيدًا","src":"المغني","loc":"١/٢١","pre":"ووجه الاستدلال كما قال ابن قدامة:"},{"t":"quote","text":"وَالْمُرَادُ بِهَا هَاهُنَا قُلَّتَانِ مِنْ قِلَالِ هَجَرَ، وَهُمَا خَمْسُ قِرَبٍ، كُلُّ قِرْبَةٍ مِائَةُ رِطْلٍ بِالْعِرَاقِيِّ، فَتَكُونُ الْقُلَّتَانِ خَمْسَمِائَةِ رِطْلٍ بِالْعِرَاقِيِّ","src":"المغني","loc":"١/١٩","pre":"وفي مقدار القلتين قال:"},{"t":"taifa","label":"الطائفة الثانية","text":"الحنفية: لم يحدّوا الكثير بعدد، بل جعلوه ما يغلب على الظن أن النجاسة لا تصل إلى جانبه الآخر، وعبّر عنه بعضهم بأنه الماء الذي إذا حُرّك أحد طرفيه لم يتحرك الآخر، وقدّره بعض متأخريهم بعشرة أذرع في عشرة."},{"t":"quote","text":"وَذَهَبَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ إلَى أَنَّ الْكَثِيرَ يَنْجُسُ بِالنَّجَاسَةِ، إلَّا أَنْ يَبْلُغَ حَدًّا يَغْلِبُ عَلَى الظَّنِّ أَنَّ النَّجَاسَةَ لَا تَصِلُ إلَيْهِ. وَاخْتَلَفُوا فِي حَدِّهِ؛ فَقَالَ بَعْضُهُمْ: مَا إذَا حُرِّكَ أَحَدُ طَرَفَيْهِ لَمْ يَتَحَرَّكْ الْآخَرُ. وَقَالَ بَعْضُهُمْ: مَا بَلَغَ عَشَرَةَ أَذْرُعٍ فِي عَشَرَةِ أَذْرُعٍ، وَمَا دُونَ ذَلِكَ يَنْجُسُ، وَإِنْ بَلَغَ أَلْفَ قُلَّةٍ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا يَبُولَنَّ أَحَدُكُمْ فِي الْمَاءِ الدَّائِمِ ثُمَّ يَتَوَضَّأُ مِنْهُ» . مُتَّفَقٌ عَلَيْهِ، فَنَهَى عَنْ الْوُضُوءِ مِنْ الْمَاءِ الرَّاكِدِ بَعْدَ الْبَوْلِ فِيهِ، وَلَمْ يُفَرِّقْ بَيْنَ قَلِيلِهِ وَكَثِيرِهِ؛ وَلِأَنَّهُ مَاءٌ حَلَّتْ فِيهِ نَجَاسَةٌ لَا يُؤْمَنُ انْتِشَارُهَا إلَيْهِ، فَيَنْجُسُ بِهَا كَالْيَسِيرِ","src":"المغني","loc":"١/٢١","pre":"قال ابن قدامة:"},{"t":"quote","text":"ففي الدر المختار: والمعتبر في مقدار الراكد أكبر رأي المبتلي به فيه فإن غلب على ظنه عدم وصول النجاسة إلى الجانب الآخر جاز وإلا لا، هذا ظاهر الرواية عن الإمام وإليه رجع محمد وهو الأصح كما في الغاية وغيرها وحقق في البحر أنه المذهب وبه يعمل","src":"الكوكب الدري على جامع الترمذي","loc":"١/٩٠","pre":"وفي بيان المعتمد عندهم قال صاحب «الكوكب الدري»:"},{"t":"p","text":"وفي المذهب المالكي روايات ثلاث في الماء اليسير تحلّه النجاسة اليسيرة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والصواب: أن ما دون القلتين لا ينجس إلا بالتغير، كالذي بلغ القلتين؛ لقول النبي - صلى الله عليه وسلم -: «إن الماء طهور لا ينجسه شيء » أخرجه الإمام أحمد، وأبو داود، والترمذي، والنسائي بإسناد صحيح، من حديث أبي سعيد الخدري - رضي الله عنه -","src":"مجموع فتاوى ابن باز","loc":"٢/٤٨٢","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"أن الماء قسمان: طهور ونجس، فما تغير بالنجاسة، فهو نجس، وما لم يتغير بنجاسة، فهو طَهُورٌ","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٨٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله: الراجح"},{"t":"quote","text":"فالأصل في ماء حمام السباحة أنه طاهر ما لم يتغير لونه أو طعمه أو ريحه بالنجاسة، أو يكون ماء قليلا ويتيقن من وقوع النجاسة فيه، فإنه يتنجس بذلك وإن لم يتغير عند كثير من العلماء","src":"فتاوى الشبكة الإسلامية","loc":"١١/١٦","pre":"وجاء في فتاوى الشبكة الإسلامية في ماء المسبح:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الذي يظهر — والله أعلم — أن الماء لا ينجس إلا بالتغير؛ لأن حديث «إن الماء طهور لا ينجسه شيء» عام، وحديث القلتين — وهو حديث صحيح — منطوقه أن ما بلغ القلتين لا يحمل الخبث، وأما مفهومه فيدل على أن ما دونهما قد يتأثر بالنجاسة فيحتاج إلى نظر، لا أنه ينجس بكل حال."},{"t":"quote","text":"وَأَمَّا تَخْصِيصُ الْقُلَّتَيْنِ بِالذِّكْرِ فَإِنَّهُمْ سَأَلُوهُ عَنْ الْمَاءِ يَكُونُ بِأَرْضِ الْفَلَاةِ؛ وَمَا يَنُوبُهُ مِنْ السِّبَاعِ وَالدَّوَابِّ؛ وَذَلِكَ الْمَاءُ الْكَثِيرُ فِي الْعَادَةِ فَبَيَّنَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ مِثْلَ ذَلِكَ لَا يَكُونُ فِيهِ خَبَثٌ فِي الْعَادَةِ بِخِلَافِ الْقَلِيلِ فَإِنَّهُ قَدْ يَحْمِلُ الْخَبَثَ وَقَدْ لَا يَحْمِلُهُ؛ فَإِنَّ الْكَثِيرَةَ تُعِينُ عَلَى إحَالَةِ الْخَبَثِ إلَى طَبْعِهِ؛ وَالْمَفْهُومُ لَا يَجِبُ فِيهِ الْعُمُومُ فَلَيْسَ إذَا كَانَ الْقُلَّتَانِ لَا تَحْمِلُ الْخَبَثَ يَلْزَمُ أَنَّ مَا دُونَهَا يَلْزَمُهُ مُطْلَقًا عَلَى أَنَّ التَّخْصِيصَ وَقَعَ جَوَابًا لِأُنَاسِ سَأَلُوهُ عَنْ مِيَاهٍ مُعَيَّنَةٍ؛ فَقَدْ يَكُونُ التَّخْصِيصُ لِأَنَّ هَذِهِ كَثِيرَةٌ لَا تَحْمِلُ الْخَبَثَ وَالْقُلَّتَانِ كَثِيرٌ وَلَا يَلْزَمُ أَنْ لَا يَكُونَ الْكَثِيرُ إلَّا قُلَّتَيْنِ","src":"مجموع الفتاوى","loc":"٢٠/٥٢٠","pre":"قال شيخ الإسلام ابن تيمية:"},{"t":"quote","text":"قَالَ أَبُو دَاوُد: قَدَّرْت بِئْرَ بُضَاعَةَ بِرِدَائِي، مَدَدْته عَلَيْهَا، ثُمَّ ذَرَعْته، فَإِذَا عَرْضُهَا سِتَّةُ أَذْرُعٍ، وَسَأَلْت الَّذِي فَتَحَ لِي بَابَ الْبُسْتَانِ: هَلْ غُيِّرَ بِنَاؤُهَا عَمَّا كَانَتْ عَلَيْهِ؟ قَالَ: لَا. وَسَأَلْت قَيِّمَهَا عَنْ عُمْقِهَا، فَقُلْت: أَكْثَرُ مَا يَكُونُ فِيهَا الْمَاءُ؟ قَالَ: إلَى الْعَانَةِ. قُلْت: فَإِذَا نَقَصَ. قَالَ: دُونَ الْعَوْرَةِ","src":"المغني","loc":"١/٢١","pre":"ومما يدل على أن الحكم لا يتوقف على عشر في عشر: أن بئر بضاعة — وقد قال فيها النبي ﷺ: «إن الماء طهور لا ينجسه شيء» — كانت دون ذلك؛ قال ابن قدامة:"},{"t":"p","text":"وقد نبّه المحققون من علماء الحنفية أنفسهم إلى أن التقدير بعشر في عشر ليس منقولًا عن أئمة المذهب، وأن أصل المذهب الرجوع إلى غلبة الظن؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"وقال أبو حنيفة: يحكم بالنجاسة إلى حد يظن خلوص النجاسة إليه، ثم مالك اعتبر الحس، وأبو حنيفة اعتبر العلم، والظاهر أن في أكثر الأنجاس عبرة العلم، وأما ما في كتبنا من العشر في العشر فعين توقيت وهو ليس بمروي عن أئمتنا الثلاثة، وقال الشيخ في الفتح: إن محمداً ليس بمؤقت، ولو سُلِّم فرجع عنه، وحكى أن محمداً سئل عن الماء الكثير فقال: نحو مسجدي هذا، فقدره تلامذته فوجدوه ثمانية في ثمانية من داخله، وعشراً في عشر من خارجه، وفي الفتح عن محمد: لا أوقت فيه، ونقل صاحب البحر عبارات أركان المذاهب على أن العشر في العشر ليس عن الأئمة، وأما ما في القدوري من تحرك الطرف بتحريك طرف آخر فهو علامة العلم بالخلوص، وأول من قال في العشر أبو سليمان الجوجزاني كما في الفتاوى الهندية","src":"العرف الشذي","loc":"١/٩٧"},{"t":"p","text":"وأثبت الشاه ولي الله الدهلوي صحة حديث القلتين، وبيّن أن ما أطالوا فيه من فروع نزح الآبار لا يقوم عليه دليل يُعتدّ به:"},{"t":"quote","text":"حَدِيث الْقلَّتَيْنِ فَإِنَّهُ حَدِيث صَحِيح روى بطرق كَثِيرَة معظمها ترجع إِلَى أبي الْوَلِيد بن كثير. عَن مُحَمَّد بن جَعْفَر بن الزبير عَن عبد الله - أَو مُحَمَّد بن عباد بن جَعْفَر - عَن عبيد الله بن عبد الله كِلَاهُمَا عَن ابْن عمر، ثمَّ تشعبت الطّرق بعد ذَلِك؛ وَهَذَانِ وَإِن كَانَا من الثِّقَات لكنهما لَيْسَ مِمَّن وسد إِلَيْهِم الْفَتْوَى، وعول النَّاس عَلَيْهِم، فَلم يظْهر الحَدِيث فِي عصر سعيد بن الْمسيب وَلَا فِي عصر الزُّهْرِيّ، وَلم يمش عَلَيْهِ الْمَالِكِيَّة وَلَا الْحَنَفِيَّة، فَلم يعملوا بِهِ، وَعمل بِهِ الشَّافِعِي","src":"حجة الله البالغة","loc":"١/٢٥٣"},{"t":"quote","text":"وَقد أَطَالَ الْقَوْم من فروع موت الْحَيَوَان فِي الْبِئْر، وَالْعشر فِي الْعشْر، وَالْمَاء الْجَارِي وَلَيْسَ فِي كل ذَلِك حَدِيث عَن النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ألبته، وَأما الْآثَار المنقولة عَن الصَّحَابَة وَالتَّابِعِينَ كأثر ابْن الزبير فِي الزنْجِي، وَعلي رَضِي الله عَنهُ فِي الْفَأْرَة، وَالنَّخَعِيّ. وَالشعْبِيّ فِي نَحْو السنور فَلَيْسَتْ مِمَّا يشْهد لَهُ المحدثون بِالصِّحَّةِ وَلَا مِمَّا اتّفق عَلَيْهِ جُمْهُور أهل الْقُرُون الأولى،، وعَلى تَقْدِير صِحَّتهَا يُمكن أَن يكون ذَلِك تطبيبا للقلوب وتنظيفا للْمَاء لَا من جِهَة الْوُجُوب الشَّرْعِيّ كَمَا ذكر فِي كتب الْمَالِكِيَّة، وَدون نفي هَذَا الِاحْتِمَال خرط القتاد. وَبِالْجُمْلَةِ فَلَيْسَ فِي هَذَا الْبَاب شَيْء يعْتد بِهِ، وَيجب الْعَمَل عَلَيْهِ، وَحَدِيث الْقلَّتَيْنِ أثبت فِي ذَلِك كُله بِغَيْر شُبْهَة، وَمن الْمحَال أَن يكون الله تَعَالَى شرع فِي هَذِه الْمسَائِل لعبادة شَيْئا زِيَادَة على مَا لَا ينفكون عَنهُ من الارتفاقات وَهِي مِمَّا يكثر وُقُوعه، وتعم بِهِ الْبلوى، ثمَّ لَا ينص عَلَيْهِ النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نصا جليا، وَلَا يستفيض فِي الصَّحَابَة وَمن بعدهمْ وَلَا حَدِيث وَاحِد فِيهِ","src":"حجة الله البالغة","loc":"١/٣١٣","pre":"وقال:"},{"t":"quote","text":"ويؤيِّده ما حكاه أصحاب الفتاوى المعتمدة من أصحابنا من تقليد أبي يوسف يوماً الشافعيَّ في طهارة القُلَّتَيْن، وإلى الله المشتكى من جهلة زماننا حيث يطعنون على من ترك تقليد إمامه في مسألة واحدة لقوة دليلها، ويُخرجونه عن مقلِّديه","src":"التعليق الممجد","loc":"١/٥٧","pre":"بل حكى العلامة عبد الحي اللكنوي أن الإمام أبا يوسف أخذ يومًا بقول الشافعي في القلتين، وأنكر على من يعيب ترك قول الإمام لقوة الدليل، فقال:"},{"t":"tanbih","items":[{"t":"p","text":"من وجد ماءً قليلًا وقعت فيه نجاسة لم تغيّره، وتيسّر له غيره، فالأحوط أن يتركه إلى غيره؛ خروجًا من خلاف القائلين بنجاسته، وعملًا بمفهوم حديث القلتين. فإن لم يجد غيره توضأ به، ولا يعدل إلى التيمم."}]}],"refs":["المغني (١/٢٠)","بداية المجتهد (١/٣٠)","الترمذي ٦٦، وأبو داود ٦٧","الترمذي ٦٧، وأبو داود ٦٣، والنسائي ٥٢، وابن ماجه ٥١٨","المغني (١/٢١)","المغني (١/١٩)","الكوكب الدري على جامع الترمذي (١/٩٠)","مجموع فتاوى ابن باز (٢/٤٨٢)","مجموع فتاوى ابن عثيمين (١١/٨٦)","فتاوى الشبكة الإسلامية (١١/١٦)","بداية المجتهد (١/٣٠-٣١)","مجموع الفتاوى (٢٠/٥٢٠)","العرف الشذي (١/٩٧)","حجة الله البالغة (١/٢٥٣)","حجة الله البالغة (١/٣١٣)","التعليق الممجد (١/٥٧)"],"related":["تطهير الماء النجس","تطهير البئر","مياه الصرف الصحي بعد معالجتها"],"alts":["نجاسة في ماء قليل","حديث القلتين","وقوع فأرة في الماء","عشر في عشر"]},{"n":15,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالماء المسخَّن بالشمس أو بالنار","q":"هل يُكره الوضوء بالماء الذي سخّنته الشمس، أو بالماء المسخَّن بالنار والسخّانات؟","short":"لا يُكره الوضوء بالماء المسخَّن بالشمس ولا بالنار عند جمهور العلماء، واختاره النووي من الشافعية، والحديث الوارد في النهي عن المشمَّس لا يثبت؛ إلا إذا كان شديد الحرارة يمنع إسباغ الوضوء أو يضرّ.","body":[{"t":"h","text":"صورة المسألة"},{"t":"p","text":"المسألة فرعان: الماء المسخَّن بالنار — ومنه ماء السخّانات اليوم — والماء المشمَّس، وهو الذي سخّنته الشمس، ولا سيما إذا قُصد تشميسه في الأواني."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يُكره الوضوء بالمسخَّن بالنار ولا بالمشمَّس، وهو مذهب مالك وأبي حنيفة وأحمد وداود والجمهور."},{"t":"quote","text":"وَلَا يُكْرَهُ الْوُضُوءُ بِالْمَاءِ الْمُسَخَّنِ بِطَاهِرٍ، إلَّا أَنْ يَكُونَ حَارًّا يَمْنَعُ إسْبَاغَ الْوُضُوءِ لِحَرَارَتِهِ. وَمِمَّنْ رُوِيَ عَنْهُ أَنَّهُ رَأَى الْوُضُوءَ بِالْمَاءِ الْمُسَخَّنِ عُمَرُ وَابْنُهُ، وَابْنُ عَبَّاسٍ، وَأَنَسٌ - رَضِيَ اللَّهُ عَنْهُمْ -. وَهُوَ قَوْلُ أَهْلِ الْحِجَازِ وَأَهْلِ الْعِرَاقِ جَمِيعِهِمْ غَيْرَ مُجَاهِدٍ","src":"المغني","loc":"١/١٤","pre":"قال ابن قدامة في المسخن بالنار:"},{"t":"quote","text":"وَمَذْهَبُ مَالِكٍ وَأَبِي حَنِيفَةَ وَأَحْمَدَ وَدَاوُد وَالْجُمْهُورِ أَنَّهُ لَا كَرَاهَةَ كَمَا هُوَ الْمُخْتَارُ","src":"المجموع","loc":"١/٨٨","pre":"وقال النووي في المشمس:"},{"t":"qawl","label":"القول الثاني","text":"كراهة الوضوء بالماء المشمَّس إذا قُصد تشميسه، وهو المشهور عند كثير من أصحاب الشافعي، واختاره أبو الحسن التميمي من الحنابلة؛ وكره مجاهدٌ المسخَّنَ بالنار."},{"t":"quote","text":"وَقَالَ الشَّافِعِيُّ: تُكْرَهُ الطَّهَارَةُ بِمَاءٍ قُصِدَ إلَى تَشْمِيسِهِ فِي الْأَوَانِي، وَلَا أَكْرَهُهُ إلَّا مِنْ جِهَةِ الطِّبِّ؛ لِمَا رُوِيَ عَنْ عَائِشَةَ - رَضِيَ اللَّهُ عَنْهَا - قَالَتْ: «دَخَلَ عَلَيَّ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَقَدْ سَخَّنْت لَهُ الْمَاءَ فِي الشَّمْسِ، فَقَالَ: لَا تَفْعَلِي يَا حُمَيْرَاءُ، فَإِنَّهُ يُورِثُ الْبَرَصَ» وَاخْتَارَهُ أَبُو الْحَسَنِ التَّمِيمِيُّ","src":"المغني","loc":"١/١٤-١٥","pre":"قال ابن قدامة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا نعلم دليلا صحيحا يمنع من استعمال الماء المشمس","src":"فتاوى اللجنة الدائمة","loc":"٥/٨٩","pre":"جاء في فتاوى اللجنة الدائمة في استعمال الماء المشمس والسخانات الشمسية:"},{"t":"quote","text":"وما ورد من أحاديث وآثار في منع استعمال الماء المسخن أو المشمس وهو الذي يسخن عن طريق الشمس فكلها باطلة لا تصح ولا تثبت عن النبي - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ -","src":"فتاوى يسألونك للدكتور حسام عفانة","loc":"٨/٣٩٣","pre":"وقال الدكتور حسام الدين عفانة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول؛ لأن حديث «يورث البرص» لا يثبت، والتسخين صفة لا تُخرج الماء عن إطلاقه."},{"t":"quote","text":"وَلَنَا أَنَّهُ سُخِّنَ بِطَاهِرٍ، أَشْبَهَ مَا فِي الْبِرَكِ وَالْأَنْهَارِ، وَمَا سُخِّنَ بِالنَّارِ وَمَا لَمْ يُقْصَدْ تَشْمِيسُهُ، فَإِنَّ الضَّرَرَ لَا يَخْتَلِفُ بِالْقَصْدِ وَعَدَمِهِ، وَالْحَدِيثُ غَيْرُ ثَابِتٍ، يَرْوِيهِ، خَالِدُ بْنُ إسْمَاعِيلَ، وَهُوَ مَتْرُوكُ الْحَدِيثِ، وَعَمْرُو بْنُ مُحَمَّدٍ الْأَعْسَمُ، وَهُوَ مُنْكَرُ الْحَدِيثِ. قَالَهُ الدَّارَقُطْنِيّ، قَالَ: وَلَا يَصِحُّ عَنْ الزُّهْرِيِّ. وَحُكِيَ عَنْ أَهْلِ الطِّبِّ أَنَّهُمْ لَا يَعْرِفُونَ لِذَلِكَ تَأْثِيرًا فِي الضَّرَرِ","src":"المغني","loc":"١/١٥","pre":"قال ابن قدامة:"},{"t":"quote","text":"لَا أَكْرَهُ الْمُشَمَّسَ إلَّا أَنْ يُكْرَهَ مِنْ جِهَةِ الطِّبِّ كَذَا رَأَيْتُهُ فِي الْأُمِّ: وَكَذَا نَقَلَهُ الْبَيْهَقِيُّ بِإِسْنَادِهِ فِي كِتَابِهِ مَعْرِفَةُ السُّنَنِ وَالْآثَارِ عَنْ الشَّافِعِيِّ: وَأَمَّا قَوْلُهُ فِي مُخْتَصَرِ الْمُزَنِيِّ إلَّا مِنْ جِهَةِ الطِّبِّ لِكَرَاهَةِ عُمَرَ لِذَلِكَ وَقَوْلِهِ إنَّهُ يُورِثُ الْبَرَصَ فَلَيْسَ صَرِيحًا فِي مُخَالَفَةِ نَصِّهِ فِي الام بل يمكن جمله عَلَيْهِ فَيَكُونُ مَعْنَاهُ لَا أَكْرَهُهُ إلَّا مِنْ جهة الطلب إنْ قَالَ أَهْلُ الطِّبِّ إنَّهُ يُورِثُ الْبَرَصَ","src":"المجموع","loc":"١/٨٧-٨٨","pre":"وحقّق النووي أن نص الإمام الشافعي نفسه في «الأم» على عدم الكراهة إلا من جهة الطب، فقال:"},{"t":"tanbih","items":[{"t":"p","text":"إذا كان الماء شديد الحرارة أو البرودة بحيث يمنع إسباغ الوضوء أو يضرّ بالبدن، تُرك لضرره، لا لأنه غير طهور."}]}],"refs":["المغني (١/١٤)","المجموع (١/٨٨)","المغني (١/١٤-١٥)","فتاوى اللجنة الدائمة (٥/٨٩)","فتاوى يسألونك للدكتور حسام عفانة (٨/٣٩٣)","المغني (١/١٥)","المجموع (١/٨٧-٨٨)"],"related":["الإسراف في ماء الوضوء"],"alts":["ماء السخان","الماء الحار للوضوء","الماء المشمس يورث البرص"]},{"n":16,"bab":"الطهارة","sub":"المياه","title":"الوضوء بالنبيذ وسائر المائعات","q":"هل يصح الوضوء بالنبيذ أو العصير أو ماء الورد عند عدم الماء؟","short":"لا يصح الوضوء بغير الماء، فمن لم يجد ماءً تيمّم؛ وهذا قول الجمهور، وهو المفتى به عند الحنفية أيضًا في نبيذ التمر.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"فَأَمَّا غَيْرُ النَّبِيذِ مِنْ الْمَائِعَاتِ، غَيْرِ الْمَاءِ، كَالْخَلِّ، وَالدُّهْنِ، وَالْمَرَقِ، وَاللَّبَنِ، فَلَا خِلَافَ بَيْنَ أَهْلِ الْعِلْمِ، فِيمَا نَعْلَمُ، أَنَّهُ لَا يَجُوزُ بِهَا وُضُوءٌ وَلَا غُسْلٌ","src":"المغني","loc":"١/١٠","pre":"اتفق العلماء على أن المائعات غير الماء — كالخل واللبن والعصير — لا يُتوضأ بها؛ قال ابن قدامة:"},{"t":"p","text":"وإنما اختُلف في نبيذ التمر خاصة إذا لم يوجد الماء."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجوز الوضوء بالنبيذ، بل يتيمم من عدم الماء، وهو قول مالك والشافعي وأحمد وأبي يوسف، والرواية التي استقر عليها المذهب الحنفي."},{"t":"quote","text":"وَمِنْهَا اخْتِصَاصُ حُصُولِ الطَّهَارَةِ بِالْمَاءِ، لِتَخْصِيصِهِ إيَّاهُ بِالذِّكْرِ، فَلَا يَحْصُلُ بِمَائِعٍ سِوَاهُ، وَبِهَذَا قَالَ مَالِكٌ وَالشَّافِعِيُّ، وَأَبُو عُبَيْدٍ وَأَبُو يُوسُفَ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"aya","text":"فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا","ref":"المائدة: ٦"},{"t":"quote","text":"وَهَذَا نَصٌّ فِي الِانْتِقَالِ إلَى التُّرَابِ عِنْدَ عَدَمِ الْمَاءِ، وَقَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «الصَّعِيدُ الطَّيِّبُ وَضُوءُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدْ الْمَاءَ عَشْرَ سِنِينَ»","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"qawl","label":"القول الثاني","text":"جواز الوضوء بنبيذ التمر عند عدم الماء، أو الجمع بينه وبين التيمم، وهو مروي عن عكرمة والحسن والأوزاعي وإسحاق، وعن أبي حنيفة روايات."},{"t":"quote","text":"وَرُوِيَ عَنْ عَلِيٍّ - رَضِيَ اللَّهُ عَنْهُ - وَلَيْسَ بِثَابِتٍ عَنْهُ - أَنَّهُ كَانَ لَا يَرَى بَأْسًا بِالْوُضُوءِ بِالنَّبِيذِ، وَبِهِ قَالَ الْحَسَنُ وَالْأَوْزَاعِيُّ وَقَالَ عِكْرِمَةُ النَّبِيذُ وَضُوءُ مَنْ لَمْ يَجِدُ الْمَاءَ. وَقَالَ إِسْحَاقُ: النَّبِيذُ حُلْوًا أَحَبُّ إلَيَّ مِنْ التَّيَمُّمِ، وَجَمْعُهُمَا أَحَبُّ إلَيَّ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"quote","text":"وعن أبي حنيفة روايات: في رواية: الجمع بين الوضوء والتيمم، وأيهما قدم جاز، وفي رواية: يتوضأ ولا يتيمم، وفي رواية العكس، والثالثة جزم بها قاضي خان، واعتمد عليها صاحب البحر، واختارها الطحاوي، وربما ينقل رجوع الإمام إليها فلم يبق المحل لأن يطنب فيه ويبحث","src":"العرف الشذي","loc":"١/١٢١","pre":"وقال الشيخ أنور شاه الكشميري في بيان الروايات عن أبي حنيفة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح القول الأول؛ لأن القرآن نقل من الماء إلى التيمم بلا واسطة، وحديث ليلة الجن الذي احتُجّ به للوضوء بالنبيذ لا يثبت."},{"t":"quote","text":"وَحَدِيثُهُمْ لَا يَثْبُتُ، وَرَاوِيهِ أَبُو زَيْدٍ مَجْهُولٌ عِنْدَ أَهْلِ الْحَدِيثِ، لَا يُعْرَفُ لَهُ غَيْرُ هَذَا الْحَدِيثِ، وَلَا يُعْرَفُ بِصُحْبَةِ عَبْدِ اللَّهِ. قَالَهُ التِّرْمِذِيُّ وَابْنُ الْمُنْذِرِ، وَقَدْ رُوِيَ عَنْ ابْنِ مَسْعُودٍ، أَنَّهُ سُئِلَ: هَلْ كُنْت مَعَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَيْلَةَ الْجِنِّ؟ فَقَالَ: مَا كَانَ مَعَهُ مِنَّا أَحَدٌ. رَوَاهُ أَبُو دَاوُد. وَرَوَى مُسْلِمٌ بِإِسْنَادِهِ، عَنْ ابْنِ مَسْعُودٍ، قَالَ: لَمْ أَكُنْ مَعَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَيْلَةَ الْجِنِّ، وَوَدِدْت أَنِّي كُنْت مَعَهُ","src":"المغني","loc":"١/١٠","pre":"قال ابن قدامة:"},{"t":"p","text":"وهذا ما قرّره محققو الحنفية أنفسهم؛ قال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"واتفق أئمة الحديث، على تضعيف الحديث، وأبو زيد مجهول الحال لا مجهول العين، فإنه روى عنه التلميذان أبو فزارة راشد بن كيسان وأبو روق عطية بن الحارث، فصار معلوم العين بضابطة المحدثين","src":"العرف الشذي","loc":"١/١٢١"},{"t":"quote","text":"ولم أجد أحداً من الحفاظ والمحدثين يصحح حديثاً من أحاديث الوضوء بالنبيذ","src":"العرف الشذي","loc":"١/١٢١","pre":"وقال:"},{"t":"p","text":"ثم ذكر الشيخ رحمه الله رواية أخرجها الزيلعي يرى أن سندها يقوى بعد تصحيح خطأ في أسماء بعض رواتها (العرف الشذي ١/١٢١)؛ والذي عليه أئمة الحديث تضعيف أحاديث الباب، كما نقله هو نفسه."},{"t":"quote","text":"وَيُقَدِّمُ التَّيَمُّمَ عَلَى نَبِيذِ التَّمْرِ عَلَى الْمَذْهَبِ الْمُصَحَّحِ الْمُفْتَى بِهِ","src":"الدر المختار مع رد المحتار","loc":"١/٢٢٧","pre":"وفي «الدر المختار»:"},{"t":"quote","text":"وَأما الْوضُوء من المَاء الْمُقَيد الَّذِي لَا ينْطَلق عَلَيْهِ اسْم المَاء بِلَا قيد فَأمر تَدْفَعهُ الْملَّة بادئ الرَّأْي","src":"حجة الله البالغة","loc":"١/٣١٣","pre":"وقال الشاه ولي الله الدهلوي:"}],"refs":["المغني (١/١٠)","العرف الشذي (١/١٢١)","الدر المختار مع رد المحتار (١/٢٢٧)","حجة الله البالغة (١/٣١٣)"],"related":["الماء الذي خالطه شيء طاهر فغيّره","متى يجوز التيمم"],"alts":["الوضوء بالعصير","نبيذ التمر","الوضوء بماء الورد"]},{"n":17,"bab":"الطهارة","sub":"المياه","title":"سؤر الهرة وسؤر الحيوانات","q":"شربت الهرة من ماء، فهل يجوز الوضوء منه أو شربه؟ وما حكم سؤر الحيوانات عمومًا؟","short":"سؤر الهرة طاهر، يجوز الوضوء منه وشربه، وهذا محل اتفاق في الإجزاء، وإنما كره بعضهم الوضوء به تنزيهًا؛ وسؤر الآدمي وبهيمة الأنعام طاهر بالاتفاق.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"p","text":"السؤر: بقية الماء التي يُبقيها الشارب في الإناء."},{"t":"h","text":"أقوال العلماء في سؤر الهرة"},{"t":"qawl","label":"القول الأول","text":"أنه طاهر يُتوضأ به بلا كراهة، وهو قول جمهور العلماء."},{"t":"quote","text":"أَنَّ أَبَا قَتَادَةَ، دَخَلَ فَسَكَبَتْ لَهُ وَضُوءًا فَجَاءَتْ هِرَّةٌ فَشَرِبَتْ مِنْهُ فَأَصْغَى لَهَا الإِنَاءَ حَتَّى شَرِبَتْ قَالَتْ كَبْشَةُ فَرَآنِي أَنْظُرُ إِلَيْهِ فَقَالَ أَتَعْجَبِينَ يَا ابْنَةَ أَخِي فَقُلْتُ نَعَمْ . فَقَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «إِنَّهَا لَيْسَتْ بِنَجَسٍ إِنَّهَا مِنَ الطَّوَّافِينَ عَلَيْكُمْ وَالطَّوَّافَاتِ»","src":"رواه أبو داود ٧٥، والترمذي ٩٢","pre":"ودليلهم حديث كبشة بنت كعب بن مالك:","links":[{"book":"mt_abudawud","num":75,"id":"h75"},{"book":"mt_tirmidhi","num":92,"id":"h92"}]},{"t":"p","text":"صححه الترمذي وابن خزيمة."},{"t":"qawl","label":"القول الثاني","text":"أنه طاهر يجزئ الوضوء به، ويُكره تنزيهًا مع وجود غيره، وهو قول أبي حنيفة ومحمد؛ وكان ابن عمر رضي الله عنهما لا يتوضأ بفضل الهر."},{"t":"quote","text":"ظاهر كلامه أن الكراهة في سؤر الهرة تنزيهية، وهو ظاهر كلامه في \"كتاب الآثار\"، حيث روى عن أبي حنيفة، عن حماد، عن إبراهيم في السِّنَّوْر يشرب في الإِناء، قال: هي من أهل البيت، لا بأس بشرب فضلها، فسألته أيُتطهَّر بفضلها للصلاة؟ فقال: إن الله قد رخَّص الماء. ولم يأمره ولم ينهه، ثم قال: قال أبو حنيفة: غيره أحبُّ إليَّ منه، وإن توضأ به أجزاه وإن شربه فلا بأس به، وبقول أبي حنيفة نأخذ","src":"التعليق الممجد","loc":"١/٣٥٠","pre":"قال العلامة عبد الحي اللكنوي في شرح قول الإمام محمد في موطئه:"},{"t":"quote","text":"قد صرح محمد في الموطأ وكتاب الآثار والمبسوط بالكراهة تنزيهاً وهو المشهور في الكتب، ثم الكراهة إما لنجاسة لحمها، وإما لعدم توقيهما من النجاسات، واختار ابن الهمام الثاني","src":"العرف الشذي","loc":"١/١٢٥","pre":"وقال الشيخ أنور شاه الكشميري:"},{"t":"quote","text":"فقد أخرج الطحاوي في \"شرح معاني الآثار\"، عن يزيد بن سنان، نا أبو بكر الحنفي، نا عبد الله بن نافع، عن أبيه، عن ابن عمر، أنه كان لا يتوضأ بفضل الكلب والهر، وما سوى ذلك فليس به بأس. وأخرج أيضاً عن ابن أبي داود، نا الربيع بن يحيى، نا شعبة، عن واقد بن محمد، عن نافع، عن ابن عمر، أنه قال: لا توضؤوا من سؤر الحمار ولا الكلب ولا السّنَّور","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"وفي الأثر عن ابن عمر قال اللكنوي:"},{"t":"quote","text":"وَمَذْهَبُنَا أَنَّ سُؤْرَ الْهِرَّةِ طَاهِرٌ غَيْرُ مَكْرُوهٍ","src":"المجموع","loc":"١/١٧٢","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"هذا يختلف إذا كان الحيوان من مأكول اللحم، كالإبل والبقر والغنم والطيور المباحة لا بأس، يستعمل ويشرب منه ولا حرج في ذلك، أما إذا كان الماء الذي ولغ فيه حيوان نجس كالكلب فإنه يراق إذا كان قليلا، أما إذا كان كثيرا فإنه لا يضر","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٣٨٨","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن الماء الذي شرب منه حيوان، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن سؤر الهرة طاهر لا كراهة فيه؛ لأن النبي ﷺ علّل طهارته بكثرة تطوافها على الناس، وأصغى لها الإناء. وقد نصّ الإمام أبو حنيفة نفسه على أنه يجزئ الوضوء به، فالخلاف إنما هو في الأولوية لا في الصحة."},{"t":"quote","text":"وأما التابعون ومن بعدهم فاختلفوا فيه أيضاً بعد اتفاقهم على أن سؤر الهرة ليس بنجس إلاَّ ما يُستفاد مما حكاه صاحب \"رحمة الأمة في اختلاف الأئمة\"، عن الأَوْزاعي والثوري، أن سؤر ما لا يؤكل لحمه نجس غير الآدمي، فإنه يقتضي أن يكون سؤر الهرة نجساً عندهما. والأحاديث الواردة في ذلك تردّهما، ومن عداهما بعدما اتفقوا على الطهارة، منهم: من كره سؤر الهرة، وهو قول أبي حنيفة ومحمد، وبه قال طاووس وابن سيرين وابن أبي ليلى ويحيى الأنصاري، حكاه عنهم العيني","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"قال اللكنوي:"},{"t":"quote","text":"ويُستنبط من قوله صلّى الله عليه وسلّم: \"فإنها من الطوّافين\"، عدم نجاسة سؤر جميع سواكن البيوت لوجود هذه العلة فيها","src":"التعليق الممجد","loc":"١/٣٤٨","pre":"وقال:"}],"refs":["بداية المجتهد (١/٣٤)","أبو داود ٧٥، والترمذي ٩٢","التعليق الممجد (١/٣٥٠)","العرف الشذي (١/١٢٥)","التعليق الممجد (١/٣٤٨)","المجموع (١/١٧٢)","فتاوى نور على الدرب لابن باز (٥/٣٨٨)"],"related":["ولوغ الكلب في الإناء"],"alts":["شرب القطة من الماء","سؤر القط","بقية شراب الحيوان"]},{"n":18,"bab":"الطهارة","sub":"المياه","title":"ولوغ الكلب في الإناء","q":"شرب كلب من إناء، فكيف يُطهَّر الإناء؟ وما حكم الماء الذي ولغ فيه؟","short":"يُراق ما ولغ فيه الكلب، ويُغسل الإناء سبع مرات، أولاهن بالتراب؛ وهذا نص الحديث الصحيح، وقد صرّح علماء الحنفية باستحباب السبع، فالعمل به جامع بين النص والخروج من الخلاف.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"طَهُورُ إِنَاءِ أَحَدِكُمْ إِذَا وَلَغَ فِيهِ الْكَلْبُ، أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ أُولَاهُنَّ بِالتُّرَابِ","src":"رواه مسلم ٢٧٩","pre":"عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":279,"id":"h279-3"}]},{"t":"quote","text":"إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيُرِقْهُ وَلْيَغْسِلْهُ سَبْعَ مَرَّاتٍ","src":"بداية المجتهد","loc":"١/٣٥","pre":"وفي لفظ لمسلم:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أن سؤر الكلب نجس، ويُغسل الإناء منه سبعًا إحداهن بالتراب، وهو مذهب الشافعي وأحمد."},{"t":"quote","text":"قال الشافعي وأحمد: إن الإناء الذي ولغ فيه الكلب يغسل سبع مرات، وفي رواية عن أحمد ثمان مرات، ويستحب التتريب عند أهل المذهبين","src":"العرف الشذي","loc":"١/١٢٤","pre":"قال الشيخ أنور شاه الكشميري في حكاية المذاهب:"},{"t":"qawl","label":"القول الثاني","text":"أن سؤر الكلب طاهر، والغسل سبعًا تعبّد غير معلَّل، وهو المشهور عن مالك."},{"t":"qawl","label":"القول الثالث","text":"أن سؤر الكلب نجس، ويُغسل الإناء منه ثلاثًا كسائر النجاسات، وهو مذهب الحنفية، واحتجوا بفتوى أبي هريرة رضي الله عنه بالثلاث."},{"t":"quote","text":"ثم نقول بالغسل ثلاثاً، ويقول الشوافع بالغسل سبعاً، وجواب الحديث من جانبنا أن التسبيع مستحب عندنا كما صرح به فخر الدين الزيلعي الفقيه شارح الكنز، ثم وجدته مروياً عن أبي حنيفة: في تحرير ابن الهمام عن الوبري عن أبي حنيفة فإن أبا هريرة راوي الحديث أفتى بالغسل ثلاثاً كما في الطحاوي ص ، عن عطاء عن أبي هريرة بسند قوي بإقرار ابن دقيق العيد، وفي فتوى أبي هريرة الآخر التسبيع، فقال الحافظ: المأخوذ من الفتوتين ما يوافق المرفوع، ونقول: لو كان الواجب التسبيع كيف اكتفى أبو هريرة بالتثليث؟ فالتثليث واجب والتسبيع مستحب","src":"العرف الشذي","loc":"١/١٢٤","pre":"قال الكشميري:"},{"t":"quote","text":"وَيُغْسَلُ الْإِنَاءُ مِنْ وُلُوغِ الْكَلْبِ ثَلَاثًا. كَذَا فِي الْهِدَايَةِ","src":"الفتاوى الهندية","loc":"١/٢٤","pre":"وفي «الفتاوى الهندية» من كتب الحنفية:"},{"t":"quote","text":"وَقَالَ مَالِكٌ: إنْ وَلَغَ الْكَلْبُ فِي إنَاءٍ فِيهِ لَبَنٌ فَلَا بَأْسَ بِأَنْ يُؤْكَلَ ذَلِكَ اللَّبَنُ","src":"المدونة","loc":"١/١١٥","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ولهذا ثبت عنه - صلى الله عليه وسلم - أنه قال: «إذا ولغ الكلب في إناء أحدكم فليرقه، ثم ليغسله سبع مرات » أخرجه مسلم في صحيحه","src":"مجموع فتاوى ابن باز","loc":"٢/٤٨٢","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"إذا كانت النجاسة على غير الأرض وهي نجاسة كلب، فإنه لابد من تطهيرها من سبع غسلات إحدها بالتراب، لقول النبي صلى الله عليه وسلم: (إذا ولغ الكلب في إناء أحدكم فليغسله سبعا إحداهن بالتراب)","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٤٥","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح العمل بنص الحديث: الإراقة والغسل سبعًا أولاهن بالتراب. وأما القول بطهارة سؤره مع الأمر بغسله سبعًا فبعيد؛ وقد ناقشه الكشميري بقوله:"},{"t":"quote","text":"ويرد عليه أنه لو لم يكن سؤره نجساً فكيف يأمر الشارع بالغسل سبع مرات، ولم يكتف بالمرة الواحدة","src":"العرف الشذي","loc":"١/١٢٤"},{"t":"p","text":"وأما فتوى أبي هريرة رضي الله عنه بالثلاث، فقد رُوي عنه أيضًا الإفتاء بالسبع، والمأخوذ من الفتويين ما يوافق المرفوع، كما نقله الشيخ الكشميري عن الحافظ ابن حجر في كلامه السابق؛ ونقل فيه أيضًا تصريح علماء الحنفية باستحباب السبع، وأنه مرويّ عن الإمام أبي حنيفة نفسه."},{"t":"p","text":"فمن غسل سبعًا أولاهن بالتراب فقد عمل بنص الحديث، وبما استحبّه علماء الحنفية، وخرج من الخلاف كله."},{"t":"tanbih","items":[{"t":"p","text":"يقوم مقامَ التراب عند بعض أهل العلم ما يقوم مقامه في الإزالة من المنظفات، والأولى التزام التراب لورود النص به."}]}],"refs":["مسلم ٢٧٩","بداية المجتهد (١/٣٥)","العرف الشذي (١/١٢٤)","بداية المجتهد (١/٣٦)","الفتاوى الهندية (١/٢٤)","المدونة (١/١١٥)","مجموع فتاوى ابن باز (٢/٤٨٢)","مجموع فتاوى ابن عثيمين (١١/٢٤٥)"],"related":["سؤر الهرة وسؤر الحيوانات","أنواع النجاسات"],"alts":["غسل الإناء من الكلب","لعاب الكلب","التتريب"]},{"n":19,"bab":"الطهارة","sub":"المياه","title":"مياه الصرف الصحي بعد معالجتها","q":"هل يجوز الوضوء بمياه الصرف الصحي (المجاري) بعد تنقيتها في محطات المعالجة؟","short":"إذا نُقّيت تنقية كاملة حتى زال أثر النجاسة منها، فلا يظهر فيها طعمها ولا لونها ولا ريحها، فهي طاهرة مطهّرة يجوز الوضوء بها؛ والأولى الاستغناء عنها في الشرب متى وُجد غيرها.","body":[{"t":"h","text":"أصل المسألة"},{"t":"p","text":"هذه مسألة معاصرة، تُبنى على أصلين مقررين عند الفقهاء:"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّ الْمَاءَ الَّذِي غَيَّرَتِ النَّجَاسَةُ إِمَّا طَعْمَهُ أَوْ لَوْنَهُ أَوْ رِيحَهُ أَوْ أَكْثَرَ مِنْ وَاحِدٍة مِنْ هَذِهِ الْأَوْصَافِ أَنَّهُ لَا يَجُوزُ بِهِ الْوُضُوءُ وَلَا الطُّهُورُ","src":"بداية المجتهد","loc":"١/٣٠","pre":"الأول: أن النجاسة إنما تؤثر في الماء بتغييرها له؛ قال ابن رشد:"},{"t":"quote","text":"طَهُرَ الْكَثِيرُ بِالنَّزْحِ وَطُولِ الْمُكْثِ، وَلَمْ يَطْهُرْ الْقَلِيلُ، فَإِنَّ الْكَثِيرَ لَمَّا كَانَتْ عِلَّةُ تَنْجِيسِهِ التَّغَيُّرَ زَالَ تَنْجِيسُهُ بِزَوَالِ عِلَّتِهِ، كَالْخَمْرَةِ إذَا انْقَلَبَتْ خَلًّا","src":"المغني","loc":"١/٢٨","pre":"الثاني: أن الحكم يدور مع علته، فإذا زال التغيّر زالت النجاسة؛ قال ابن قدامة:"},{"t":"h","text":"قرار هيئة كبار العلماء"},{"t":"p","text":"وقد عُرضت المسألة على هيئة كبار العلماء في دورتها الثالثة عشرة (شوال ١٣٩٨هـ)، فقرّرت ما يلي:"},{"t":"quote","text":"بناءً على ما ذكره أهل العلم من أن الماء الكثير المتغير بنجاسة يطهر إذا زال تغيره بنفسه أو بإضافة ماء طهور إليه، أو زال تغيره بطول مكث أو تأثير شمس ومرور الرياح عليه أو نحو ذلك لزوال الحكم بزوال علته","src":"الإسلام سؤال وجواب","loc":"٥/٣٧"},{"t":"quote","text":"ولذلك فإن المجلس يرى طهارتها بعد تنقيتها التنقية الكاملة بحيث تعود إلى خلقتها الأولى لا يرى فيها تغير بنجاسة في طعم ولا لون ولا ريح، ويجوز استعمالها في إزالة الأحداث والأخباث، وتحصل الطهارة بها منها، كما يجوز شربها إلا إذا كانت هناك أضرار صحية تنشأ عن استعمالها فيمتنع ذلك للمحافظة على النفس، وتفادياً للضرر، لا لنجاستها. والمجلس إذ يقرر ذلك يستحسن الاستغناء عنها في استعمالها للشرب متى وجد إلى ذلك سبيل، احتياطاً للصحة، واتقاءً للضرر، وتنزهاً عما تستقذره النفوس، وتنفر منه الطباع","src":"الإسلام سؤال وجواب","loc":"٥/٣٧"},{"t":"h","text":"الخلاصة","k":"r"},{"t":"p","text":"فالعبرة بزوال أثر النجاسة كليًّا: فإذا عاد الماء إلى خلقته الأولى، لا يظهر فيه طعم النجاسة ولا لونها ولا ريحها، فهو طهور. وأما الشرب منه فيُترك متى وُجد غيره، صيانةً للصحة وتنزّهًا عما تستقذره النفوس، لا لنجاسته."}],"refs":["بداية المجتهد (١/٣٠)","المغني (١/٢٨)","الإسلام سؤال وجواب (٥/٣٧)"],"related":["الماء القليل تقع فيه نجاسة ولم يتغير","تطهير الماء النجس"],"alts":["مياه المجاري المعالجة","الماء المكرر","تنقية مياه الصرف"]},{"n":20,"bab":"الطهارة","sub":"الآنية","title":"الأكل والشرب والوضوء في آنية الذهب والفضة","q":"هل يجوز الأكل والشرب أو الوضوء في أوانٍ من الذهب أو الفضة؟ وهل يصح الوضوء منها؟","short":"يحرم الأكل والشرب في آنية الذهب والفضة، وكذا سائر استعمالها، على الرجال والنساء؛ ومن توضأ منها أثِم وصحّ وضوؤه عند الجمهور. وأما الأواني الثمينة من غيرهما — كالبلّور والنحاس والزجاج — فمباحة عند عامة أهل العلم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَلَكِنِّي سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ «لاَ تَلْبَسُوا الْحَرِيرَ وَلاَ الدِّيبَاجَ وَلاَ تَشْرَبُوا فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَلاَ تَأْكُلُوا فِي صِحَافِهَا، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَنَا فِي الآخِرَةِ»","src":"رواه البخاري ٥٤٢٦، ومسلم ٢٠٦٧","pre":"عن حذيفة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":5426,"id":"h5426"},{"book":"mt_muslim","num":2067,"id":"h2067"}]},{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"وَلَا خِلَافَ بَيْنَ أَصْحَابِنَا فِي أَنَّ اسْتِعْمَالَ آنِيَةِ الذَّهَبِ وَالْفِضَّةِ حَرَامٌ، وَهُوَ مَذْهَبُ أَبِي حَنِيفَةَ، وَمَالِكٍ، وَالشَّافِعِيِّ، وَلَا أَعْلَمُ فِيهِ خِلَافًا","src":"المغني","loc":"١/٥٥-٥٦","pre":"اتفق الأئمة الأربعة على تحريم الأكل والشرب فيها؛ قال ابن قدامة:"},{"t":"quote","text":"وَالْعِلَّةُ فِي تَحْرِيمِ الشُّرْبِ فِيهَا مَا يَتَضَمَّنُهُ ذَلِكَ مِنْ الْفَخْرِ وَالْخُيَلَاءِ، وَكَسْرِ قُلُوبِ الْفُقَرَاءِ، وَهُوَ مَوْجُودٌ فِي الطَّهَارَةِ مِنْهَا وَاسْتِعْمَالِهَا كَيْفَمَا كَانَ، بَلْ إذَا حَرُمَ فِي غَيْرِ الْعِبَادَةِ فَفِيهَا أَوْلَى","src":"المغني","loc":"١/٥٦","pre":"وألحقوا بالأكل والشرب سائر الاستعمال؛ لأن العلة واحدة:"},{"t":"p","text":"واختلفوا في مسألتين: صحة الوضوء منها، والأواني الثمينة من غير الذهب والفضة."},{"t":"h","text":"المسألة الأولى: صحة الوضوء من آنية الذهب والفضة"},{"t":"qawl","label":"القول الأول","text":"يصح الوضوء مع الإثم، وهو قول الشافعي وأصحاب الرأي وإسحاق وابن المنذر، وأحد الوجهين عند الحنابلة."},{"t":"qawl","label":"القول الثاني","text":"لا يصح، وهو اختيار أبي بكر من الحنابلة."},{"t":"quote","text":"فَإِنْ تَوَضَّأَ مِنْهَا، أَوْ اغْتَسَلَ، فَعَلَى وَجْهَيْنِ: أَحَدهمَا تَصِحُّ طَهَارَتُهُ. وَهُوَ قَوْلُ الشَّافِعِيِّ، وَإِسْحَاقَ، وَابْنِ الْمُنْذِرِ، وَأَصْحَابِ الرَّأْيِ؛ لِأَنَّ فِعْلَ الطَّهَارَةِ وَمَاءَهَا لَا يَتَعَلَّقُ بِشَيْءٍ مِنْ ذَلِكَ، أَشْبَهَ الطَّهَارَةَ فِي الدَّارِ الْمَغْصُوبَةِ. وَالثَّانِي: لَا يَصِحُّ اخْتَارَهُ أَبُو بَكْرٍ؛ لِأَنَّهُ اسْتَعْمَلَ الْمُحَرَّمَ فِي الْعِبَادَةِ، فَلَمْ يَصِحَّ، كَالصَّلَاةِ فِي الدَّارِ الْمَغْصُوبَةِ وَالْأَوَّلُ أَصَحُّ، وَيُفَارِقُ هَذَا الصَّلَاةَ فِي الدَّارِ الْمَغْصُوبَةِ؛ لِأَنَّ أَفْعَالَ الصَّلَاةِ مِنْ الْقِيَامِ وَالْقُعُودِ وَالرُّكُوعِ وَالسُّجُودِ، فِي الدَّارِ الْمَغْصُوبَةِ؛ مُحَرَّمٌ؛ لِكَوْنِهِ تَصَرُّفًا فِي مِلْكِ غَيْرِهِ بِغَيْرِ إذْنِهِ، وَشُغْلًا لَهُ، وَأَفْعَالُ الْوُضُوءِ؛ مِنْ الْغَسْلِ، وَالْمَسْحِ، لَيْسَ بِمُحَرَّمٍ، إذْ لَيْسَ هُوَ اسْتِعْمَالًا لِلْإِنَاءِ، وَلَا تَصَرُّفًا فِيهِ، وَإِنَّمَا يَقَعُ ذَلِكَ بَعْدَ رَفْعِ الْمَاءِ مِنْ الْإِنَاءِ، وَفَصْلِهِ عَنْهُ، فَأَشْبَهَ مَا لَوْ غَرَفَ بِآنِيَةِ الْفِضَّةِ فِي إنَاءٍ غَيْرِهِ، ثُمَّ تَوَضَّأَ بِهِ؛ وَلِأَنَّ الْمَكَانَ شَرْطٌ لِلصَّلَاةِ، إذْ لَا يُمْكِنُ وُجُودُهَا فِي غَيْرِ مَكَان، وَالْإِنَاءُ لَيْسَ بِشَرْطٍ، فَأَشْبَهَ مَا لَوْ صَلَّى وَفِي يَدِهِ خَاتَمُ ذَهَبٍ","src":"المغني","loc":"١/٥٦","pre":"قال ابن قدامة:"},{"t":"h","text":"المسألة الثانية: الأواني الثمينة من غير الذهب والفضة"},{"t":"qawl","label":"القول الأول","text":"أنها مباحة، وهو قول عامة أهل العلم."},{"t":"qawl","label":"القول الثاني","text":"أن ما كان ثمينًا لنفاسة جوهره محرّم، وهو أحد قولي الشافعي؛ وكره ابن عمر رضي الله عنهما الوضوء في النحاس والصفر."},{"t":"quote","text":"فَأَمَّا سَائِرُ الْآنِيَةِ فَمُبَاحٌ اتِّخَاذُهَا وَاسْتِعْمَالُهَا، سَوَاءٌ كَانَتْ ثَمِينَةً، كَالْيَاقُوتِ وَالْبِلَّوْرِ وَالْعَقِيقِ وَالصُّفْرِ وَالْمَخْرُوطِ مِنْ الزُّجَاجِ، أَوْ غَيْرَ ثَمِينَةٍ، كَالْخَشَبِ وَالْخَزَفِ وَالْجُلُودِ. وَلَا يُكْرَهُ اسْتِعْمَالُ شَيْءٍ مِنْهَا فِي قَوْلِ عَامَّةِ أَهْلِ الْعِلْمِ، إلَّا أَنَّهُ رُوِيَ عَنْ ابْنِ عُمَرَ أَنَّهُ كَرِهَ الْوُضُوءَ فِي الصُّفْرِ وَالنُّحَاسِ وَالرَّصَاصِ وَمَا أَشْبَهَ ذَلِكَ. وَاخْتَارَ ذَلِكَ الشَّيْخُ أَبُو الْفَرَجِ الْمَقْدِسِيُّ؛ لِأَنَّ الْمَاءَ يَتَغَيَّرُ فِيهَا، وَرُوِيَ أَنَّ الْمَلَائِكَةَ تَكْرَهُ رِيحَ النُّحَاسِ، وَقَالَ الشَّافِعِيُّ فِي أَحَدِ قَوْلَيْهِ: مَا كَانَ ثَمِينًا لِنَفَاسَةِ جَوْهَرِهِ فَهُوَ مُحَرَّمٌ؛ لِأَنَّ تَحْرِيمَ الْأَثْمَانِ تَنْبِيهٌ عَلَى تَحْرِيمِ مَا هُوَ أَعْلَى مِنْهُ؛ وَلِأَنَّ فِيهِ سَرَفًا وَخُيَلَاءَ وَكَسْرَ قُلُوبِ الْفُقَرَاءِ، فَكَانَ مُحَرَّمًا كَالْأَثْمَانِ","src":"المغني","loc":"١/٥٨","pre":"قال ابن قدامة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الصحيح أن الاتخاذ والاستعمال في غير الأكل والشرب ليس بحرام وذلك لأن النبي صلى الله عليه وسلم، إنما نهى عن شيء مخصوص، وهو الأكل والشرب","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٩٢","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن استعمال آنية الذهب والفضة، فقال:"},{"t":"quote","text":"لقول النبي - صلى الله عليه وسلم -: «لا تشربوا في آنية الذهب والفضة، ولا تأكلوا في صحافهما، فإنها لهم في الدنيا ولكم في الآخرة»","src":"فتاوى اللجنة الدائمة","loc":"٢٢/١٥٦","pre":"وجاء في فتاوى اللجنة الدائمة في تحريم الأكل والشرب فيها على الرجال والنساء:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح في المسألة الأولى صحة الوضوء مع الإثم؛ لأن الوضوء يقع بعد انفصال الماء عن الإناء، فلا يتعلق التحريم بنفس العبادة. والراجح في الثانية الإباحة؛ لأن النبي ﷺ توضأ من تَور من صُفر، والأصل في الأشياء الحلّ."},{"t":"quote","text":"وَلَنَا مَا رُوِيَ عَنْ عَبْدِ اللَّهِ بْنِ زَيْدٍ، قَالَ: «أَتَانَا رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَأَخْرَجْنَا لَهُ مَاءً فِي تَوْرٍ مِنْ صُفْرٍ، فَتَوَضَّأَ.» مُتَّفَقٌ عَلَيْهِ، وَرَوَى أَبُو دَاوُد فِي \" سُنَنِهِ \"، عَنْ عَائِشَةَ قَالَتْ: «كُنْت أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي تَوْرٍ مِنْ شَبَهٍ» وَلِأَنَّ الْأَصْلَ الْحِلُّ، فَيَبْقَى عَلَيْهِ، وَلَا يَصِحُّ قِيَاسُهُ عَلَى الْأَثْمَانِ؛ لِوَجْهَيْنِ: أَحَدُهُمَا أَنَّ هَذَا لَا يَعْرِفُهُ إلَّا خَوَاصُّ النَّاسِ، فَلَا تَنْكَسِرُ قُلُوبُ الْفُقَرَاءِ بِاسْتِعْمَالِهِ، بِخِلَافِ الْأَثْمَانِ","src":"المغني","loc":"١/٥٨","pre":"قال ابن قدامة:"},{"t":"tanbih","items":[{"t":"quote","text":"وَيَحْرُمُ ذَلِكَ عَلَى الرِّجَالِ وَالنِّسَاءِ؛ لِعُمُومِ النَّصِّ فِيهِمَا، وَوُجُودِ مَعْنَى التَّحْرِيمِ فِي حَقِّهِمَا، وَإِنَّمَا أُبِيحَ التَّحَلِّي فِي حَقِّ الْمَرْأَةِ؛ لِحَاجَتِهَا إلَى التَّزَيُّنِ لِلزَّوْجِ، وَالتَّجَمُّلِ عِنْدَهُ، وَهَذَا يَخْتَصُّ الْحُلِيَّ، فَتَخْتَصُّ الْإِبَاحَةُ بِهِ","src":"المغني","loc":"١/٥٧","pre":"التحريم عامّ للرجال والنساء؛ قال ابن قدامة:"}]}],"refs":["البخاري ٥٤٢٦، ومسلم ٢٠٦٧","المغني (١/٥٥-٥٦)","المغني (١/٥٦)","المغني (١/٥٨)","مجموع فتاوى ابن عثيمين (١١/٩٢)","فتاوى اللجنة الدائمة (٢٢/١٥٦)","المغني (١/٥٧)"],"related":["الإناء المضبَّب بالفضة","آنية الكفار وثيابهم"],"alts":["الشرب في كأس من فضة","ملاعق الذهب","الأواني المذهبة"]},{"n":21,"bab":"الطهارة","sub":"الآنية","title":"الإناء المضبَّب بالفضة أو الذهب","q":"إناء انكسر فأُصلح بقطعة أو سلسلة من فضة، أو فيه شيء من الذهب أو الفضة، فهل يجوز استعماله؟","short":"يجوز استعمال الإناء الذي فيه ضبّة يسيرة من فضة للحاجة، كإصلاح الكسر، ويُتجنّب مباشرة موضع الفضة بالفم؛ وأما الكثير من الفضة، والذهب مطلقًا، فيُترك إلا لضرورة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَأَمَّا الْفِضَّةُ فَيُبَاحُ مِنْهَا الْيَسِيرُ؛ لِمَا رَوَى أَنَسٌ، «أَنَّ قَدَحَ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - انْكَسَرَ، فَاتَّخَذَ مَكَانَ الشَّعْبِ سِلْسِلَةً مِنْ فِضَّةٍ.» رَوَاهُ الْبُخَارِيُّ؛ وَلِأَنَّ الْحَاجَةَ تَدْعُو إلَيْهِ، وَلَيْسَ فِيهِ سَرَفٌ وَلَا خُيَلَاءُ، فَأَشْبَهَ الضَّبَّةَ مِنْ الصُّفْرِ","src":"المغني","loc":"١/٥٧-٥٨","pre":"قال ابن قدامة:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يحرم الكثير من الضبّة مطلقًا، ذهبًا كانت أو فضة، ويباح اليسير من الفضة للحاجة؛ وهو قول الشافعي والحنابلة."},{"t":"qawl","label":"القول الثاني","text":"يباح المضبَّب وإن كانت الضبّة كثيرة؛ لأنها تابعة للإناء المباح، وهو قول أبي حنيفة."},{"t":"quote","text":"فَأَمَّا الْمُضَبَّبُ بِالذَّهَبِ أَوْ الْفِضَّةِ، فَإِنْ كَانَ كَثِيرًا فَهُوَ مُحَرَّمٌ بِكُلِّ حَالٍ؛ ذَهَبًا كَانَ أَوْ فِضَّةً، لَحَاجَةٍ أَوْ لِغَيْرِهَا. وَبِهَذَا قَالَ الشَّافِعِيُّ. وَأَبَاحَ أَبُو حَنِيفَةَ الْمُضَبَّبَ، وَإِنْ كَانَ كَثِيرًا؛ لِأَنَّهُ صَارَ تَابِعًا لِلْمُبَاحِ، فَأَشْبَهَ الْمُضَبَّبَ بِالْيَسِيرِ وَلَنَا أَنَّ هَذَا فِيهِ سَرَفٌ وَخُيَلَاءُ، فَأَشْبَهَ الْخَالِصَ، وَيَبْطُلُ مَا قَالَهُ بِمَا إذَا اتَّخَذَ أَبْوَابًا مِنْ فِضَّةٍ أَوْ ذَهَبٍ، أَوْ رُفُوفًا، فَإِنَّهُ يَحْرُمُ، وَإِنْ كَانَ تَابِعًا، وَفَارَقَ الْيَسِيرَ، فَإِنَّهُ لَا يُوجَدُ فِيهِ الْمَعْنَى الْمُحَرَّمُ. إذَا ثَبَتَ هَذَا، فَاخْتَلَفَ أَصْحَابُنَا؛ فَقَالَ أَبُو بَكْرٍ يُبَاحُ الْيَسِيرُ مِنْ الذَّهَبِ وَالْفِضَّةِ؛ لِمَا ذَكَرْنَا، وَأَكْثَرُ أَصْحَابِنَا عَلَى أَنَّهُ لَا يُبَاحُ الْيَسِيرُ مِنْ الذَّهَبِ، وَلَا يُبَاحُ مِنْهُ إلَّا مَا دَعَتْ الضَّرُورَةُ إلَيْهِ، كَأَنْفِ الذَّهَبِ، وَمَا رَبَطَ بِهِ أَسْنَانَهُ","src":"المغني","loc":"١/٥٧","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَأَمَّا) الْإِنَاءُ الْمُضَبَّبُ بِالذَّهَبِ فَلَا بَأْسَ بِالْأَكْلِ وَالشُّرْبِ فِيهِ عِنْدَ أَبِي حَنِيفَةَ - رَضِيَ اللَّهُ عَنْهُ - وَهُوَ قَوْلُ مُحَمَّدٍ ذَكَرَهُ فِي الْمُوَطَّإِ وَعِنْدَ أَبِي يُوسُفَ يُكْرَهُ","src":"بدائع الصنائع","loc":"٥/١٣٢","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"quote","text":"وَلَا بَأْسَ بِالْأَكْلِ وَالشُّرْبِ مِنْ إنَاءٍ مُذَهَّبٍ وَمُفَضَّضِ إذَا لَمْ يَضَعْ فَاهُ عَلَى الذَّهَبِ وَالْفِضَّةِ، وَكَذَا الْمُضَبَّبُ مِنْ الْأَوَانِي وَالْكَرَاسِيِّ وَالسَّرِيرِ إذَا لَمْ يَقْعُدْ عَلَى الذَّهَبِ وَالْفِضَّةِ","src":"الفتاوى الهندية","loc":"٥/٣٣٤","pre":"وفي «الفتاوى الهندية»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الذي يدل عليه الحديث إباحة اليسير من الفضة للحاجة؛ لأن النبي ﷺ أصلح قدحه بسلسلة من فضة. وأما الكثير فإن فيه معنى الفخر والخيلاء الذي من أجله حُرّمت الآنية، فالأولى تركه، خروجًا من الخلاف."},{"t":"quote","text":"قَالَ الْقَاضِي: وَيُبَاحُ ذَلِكَ مَعَ الْحَاجَةِ وَعَدَمِهَا؛ لِمَا ذَكَرْنَا، إلَّا أَنَّ مَا يُسْتَعْمَلُ مِنْ ذَلِكَ لَا يُبَاحُ كَالْحَلْقَةِ، وَمَا لَا يُسْتَعْمَلُ كَالضَّبَّةِ يُبَاحُ. وَقَالَ أَبُو الْخَطَّابِ لَا يُبَاحُ الْيَسِيرُ إلَّا لِحَاجَةٍ؛ لِأَنَّ الْخَبَرَ إنَّمَا وَرَدَ فِي تَشْعِيبِ الْقَدَحِ فِي مَوْضِعِ الْكَسْرِ، وَهُوَ لِحَاجَةٍ، وَمَعْنَى الْحَاجَةِ أَنْ تَدْعُوَ الْحَاجَةُ إلَى مَا فَعَلَهُ بِهِ، وَإِنْ كَانَ غَيْرُهُ يَقُومُ مَقَامَهُ، وَتُكْرَهُ مُبَاشَرَةُ مَوْضِعِ الْفِضَّةِ بِالِاسْتِعْمَالِ؛ كَيْ لَا يَكُونَ مُسْتَعْمِلًا لَهَا","src":"المغني","loc":"١/٥٨","pre":"وقد اختلف الحنابلة في اشتراط الحاجة؛ قال ابن قدامة:"}],"refs":["المغني (١/٥٧-٥٨)","المغني (١/٥٧)","بدائع الصنائع (٥/١٣٢)","الفتاوى الهندية (٥/٣٣٤)","المغني (١/٥٨)"],"related":["الأكل والشرب والوضوء في آنية الذهب والفضة"],"alts":["إصلاح الإناء بالفضة","الكأس المطلي بالفضة","الضبة"]},{"n":22,"bab":"الطهارة","sub":"الآنية","title":"جلد الميتة إذا دُبغ","q":"هل يطهر جلد الميتة بالدباغ، فيجوز استعماله في القِرَب والأحذية والملابس والصلاة عليه؟","short":"نعم، جلد الميتة يطهر بالدباغ على الراجح، فيجوز استعماله في كل شيء إلا الأكل؛ وهذا قول جمهور العلماء، ومنهم الحنفية والشافعية؛ واستثنى الحنفية جلد الخنزير، والشافعية جلد الكلب والخنزير.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"لَا يَخْتَلِفُ الْمَذْهَبُ فِي نَجَاسَةِ الْمَيْتَةِ قَبْلَ الدَّبْغِ، وَلَا نَعْلَمُ أَحَدًا خَالَفَ فِيهِ","src":"المغني","loc":"١/٤٩","pre":"جلد الميتة قبل الدباغ نجس بالاتفاق؛ قال ابن قدامة:"},{"t":"p","text":"واختلفوا فيه بعد الدباغ:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يطهر بالدباغ، وهو المشهور عند الحنابلة، وإحدى الروايتين عن مالك."},{"t":"qawl","label":"القول الثاني","text":"يطهر بالدباغ جلدُ ما كان طاهرًا في حال الحياة، وهو قول الشافعي ورواية عن أحمد؛ فيطهر عنده كل جلد إلا جلد الكلب والخنزير."},{"t":"qawl","label":"القول الثالث","text":"يطهر كل جلد إلا جلد الخنزير، وهو قول أبي حنيفة."},{"t":"qawl","label":"القول الرابع","text":"يطهر كل جلد، وهو محكيّ عن أبي يوسف، ورواية عن مالك."},{"t":"quote","text":"وَأَمَّا بَعْدَ الدَّبْغِ فَالْمَشْهُورُ فِي الْمَذْهَبِ أَنَّهُ نَجِسٌ أَيْضًا، وَهُوَ إحْدَى الرِّوَايَتَيْنِ عَنْ مَالِكٍ، وَيُرْوَى ذَلِكَ عَنْ عُمَرَ وَابْنِهِ عَبْدِ اللَّهِ بْنِ عُمَرَ - رَضِيَ اللَّهُ عَنْهُمَا - وَعِمْرَانَ بْنِ حُصَيْنٍ، وَعَائِشَةَ - رَضِيَ اللَّهُ عَنْهُمْ -. وَعَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى: أَنَّهُ يَطْهُرُ مِنْهَا جِلْدُ مَا كَانَ طَاهِرًا فِي حَالِ الْحَيَاةِ. وَرُوِيَ نَحْوُ هَذَا عَنْ عَطَاءٍ، وَالْحَسَنِ، وَالشَّعْبِيِّ، وَالنَّخَعِيِّ، وَقَتَادَةَ، وَيَحْيَى الْأَنْصَارِيِّ، وَسَعِيدِ بْنِ جُبَيْرٍ، وَالْأَوْزَاعِيِّ، وَاللَّيْثِ، وَالثَّوْرِيِّ، وَابْنِ الْمُبَارَكِ، وَإِسْحَاقَ، وَرُوِيَ ذَلِكَ عَنْ عُمَرَ، وَابْنِ عَبَّاسٍ، وَابْنِ مَسْعُودٍ، وَعَائِشَةَ - رَضِيَ اللَّهُ عَنْهُمْ -، مَعَ اخْتِلَافِهِمْ فِيمَا هُوَ طَاهِرٌ فِي الْحَيَاةِ، وَهُوَ مَذْهَبُ الشَّافِعِيِّ، وَهُوَ يَرَى طَهَارَةَ الْحَيَوَانَاتِ كُلِّهَا، إلَّا الْكَلْبَ وَالْخِنْزِيرَ، فَيَطْهُرُ عِنْدَهُ كُلُّ جِلْدٍ إلَّا جِلْدَهُمَا. وَلَهُ فِي جِلْدِ الْآدَمِيِّ وَجْهَانِ. وَقَالَ أَبُو حَنِيفَةَ: يَطْهُرُ كُلُّ جِلْدٍ بِالدَّبْغِ إلَّا جِلْدَ الْخِنْزِيرِ. وَحُكِيَ عَنْ أَبِي يُوسُفَ: أَنَّهُ يَطْهُرُ كُلُّ جِلْدٍ. وَهُوَ رِوَايَةٌ عَنْ مَالِكٍ، وَمَذْهَبُ مَنْ حَكَمَ بِطَهَارَةِ الْحَيَوَانَاتِ كُلِّهَا؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «إذَا دُبِغَ الْإِهَابُ فَقَدْ طَهُرَ.» مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «وَجَدَ شَاةً مَيِّتَةً أُعْطِيَتْهَا مَوْلَاةٌ لِمَيْمُونَةَ مِنْ الصَّدَقَةِ. فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - هَلَّا انْتَفَعْتُمْ بِجِلْدِهَا؟ قَالُوا: إنَّهَا مَيْتَةٌ. قَالَ: إنَّمَا حَرُمَ أَكْلُهَا.» وَفِي لَفْظٍ: «أَلَا أَخَذُوا إهَابَهَا فَدَبَغُوهُ فَانْتَفَعُوا بِهِ» . مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّهُ إنَّمَا نَجُسَ بِاتِّصَالِ الدِّمَاءِ وَالرُّطُوبَاتِ بِهِ بِالْمَوْتِ، وَالدَّبْغُ يُزِيلُ ذَلِكَ، فَيَرْتَدُّ الْجِلْدُ إلَى مَا كَانَ عَلَيْهِ فِي حَالِ الْحَيَاةِ","src":"المغني","loc":"١/٤٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَلَنَا مَا رَوَى عَبْدُ اللَّهِ بْنُ عُكَيْمٍ، «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - كَتَبَ إلَى جُهَيْنَةَ إنِّي كُنْت رَخَّصْت لَكُمْ فِي جُلُودِ الْمَيْتَةِ، فَإِذَا جَاءَكُمْ كِتَابِي هَذَا فَلَا تَنْتَفِعُوا مِنْ الْمَيْتَةِ بِإِهَابٍ وَلَا عَصَبٍ»","src":"المغني","loc":"١/٤٩","pre":"ودليل من قال لا يطهر:"},{"t":"quote","text":"فَرْعٌ فِي مَذَاهِبِ الْعُلَمَاءِ فِي جُلُودِ الْمَيْتَةِ) هِيَ سَبْعَةُ مَذَاهِبَ أَحَدُهَا لَا يَطْهُرُ بِالدِّبَاغِ شئ مِنْ جُلُودِ الْمَيْتَةِ","src":"المجموع","loc":"١/٢١٧","pre":"وذكر النووي في «المجموع» أن للعلماء في جلود الميتة سبعة مذاهب، فقال:"},{"t":"quote","text":"وَقَالَ مَالِكٌ: لَا يُعْجِبُنِي أَنْ يُصَلَّى عَلَى جُلُودِ الْمَيْتَةِ وَإِنْ دُبِغَتْ وَمَنْ صَلَّى عَلَيْهَا أَعَادَ مَا دَامَ فِي الْوَقْتِ، قَالَ: وَأَمَّا جُلُودُ السِّبَاعِ فَلَا بَأْسَ أَنْ يُصَلَّى عَلَيْهَا وَتُلْبَسُ إذَا ذُكِّيَتْ","src":"المدونة","loc":"١/١٨٣","pre":"وفي «المدونة» عن الإمام مالك:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"قد ثبت عن النبي صلى الله عليه وسلم أنه قال: «إذا دبغ الجلد فقد طهر » وقال: «دباغ جلود الميتة طهورها » واختلف العلماء في ذلك، هل يعم هذا الحديث جميع الجلود أم يختص بجلود الميتة التي تحل بالذكاة، ولا شك أن ما دبغ من جلود الميتة التي تحل بالذكاة كالإبل والبقر والغنم طهور يجوز استعماله في كل شيء في أصح أقوال أهل العلم","src":"مجموع فتاوى ابن باز","loc":"١/٢٧٠","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن الجلد يطهر بالدباغ؛ لحديث ابن عباس رضي الله عنهما في صحيح مسلم:"},{"t":"quote","text":"إِذَا دُبِغَ الْإِهَابُ فَقَدْ طَهُرَ","src":"رواه مسلم ٣٦٦","pre":"عن ابن عباس رضي الله عنهما قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_muslim","num":366,"id":"h366"}]},{"t":"p","text":"وعند أصحاب السنن: «أيما إهاب دبغ فقد طهر»."},{"t":"quote","text":"أَنَّهُ حَدِيثٌ مُضْطَرِبٌ فِي سَنَدِهِ، فَإِنَّهُ رُوِيَ عَنْ كِتَابِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَتَارَةً عَنْ مَشَايِخَ مِنْ جُهَيْنَةَ عَمَّنْ قَرَأَ كِتَابَ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَمُضْطَرِبٌ أَيْضًا فِي مَتْنِهِ، فَرُوِيَ مِنْ غَيْرِ تَقْيِيدٍ فِي رِوَايَةِ الْأَكْلِ، وَرُوِيَ بِالتَّقْيِيدِ بِشَهْرٍ أَوْ شَهْرَيْنِ أَوْ أَرْبَعِينَ يَوْمًا أَوْ ثَلَاثَةِ أَيَّامٍ، ثُمَّ إنَّهُ مُعَلٌّ أَيْضًا بِالْإِرْسَالِ، فَإِنَّهُ لَمْ يَسْمَعْهُ \" عَبْدُ اللَّهِ بْنُ عُكَيْمٍ \" مِنْهُ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَمُعَلٌّ بِالِانْقِطَاعِ؛ لِأَنَّهُ لَمْ يَسْمَعْهُ \" عَبْدُ الرَّحْمَنِ بْنُ أَبِي لَيْلَى \" مِنْ \" ابْنِ عُكَيْمٍ \"، وَلِذَلِكَ تَرَكَ أَحْمَدُ بْنُ حَنْبَلٍ الْقَوْلَ بِهِ آخِرًا، وَكَانَ يَذْهَبُ إلَيْهِ أَوَّلًا كَمَا قَالَ عَنْهُ التِّرْمِذِيُّ. وَ (ثَانِيًا) : بِأَنَّهُ لَا يَقْوَى عَلَى النَّسْخِ؛ لِأَنَّ حَدِيثَ الدِّبَاغِ أَصَحُّ؛ فَإِنَّهُ مِمَّا اتَّفَقَ عَلَيْهِ الشَّيْخَانِ، وَأَخْرَجَ مُسْلِمٌ وَرُوِيَ مِنْ طُرُقٍ مُتَعَدِّدَةٍ فِي مَعْنَاهُ عِدَّةُ أَحَادِيثَ عَنْ جَمَاعَةٍ مِنْ الصَّحَابَةِ، فَعَنْ ابْنِ عَبَّاسٍ حَدِيثَانِ، وَعَنْ أُمِّ سَلَمَةَ ثَلَاثَةٌ، وَعَنْ أَنَسٍ حَدِيثَانِ، وَعَنْ سَلَمَةَ بْنِ الْمُحَبِّقِ وَعَائِشَةَ وَالْمُغِيرَةِ وَأَبِي أُمَامَةَ وَابْنِ مَسْعُودٍ، وَلِأَنَّ النَّاسِخَ لَا بُدَّ مِنْ تَحْقِيقِ تَأَخُّرِهِ وَلَا دَلِيلَ عَلَى تَأَخُّرِ حَدِيثِ ابْنِ عُكَيْمٍ، وَرِوَايَةُ التَّارِيخِ فِيهِ بِشَهْرٍ أَوْ شَهْرَيْنِ مُعَلَّةٌ، فَلَا تَقُومُ بِهَا حُجَّةٌ عَلَى النَّسْخِ، عَلَى أَنَّهَا لَوْ كَانَتْ رِوَايَةُ التَّارِيخِ صَحِيحَةً مَا دَلَّتْ عَلَى أَنَّهُ آخِرُ الْأَمْرَيْنِ جَزْمًا، وَلَا يُقَالُ: فَإِذَا لَمْ يَتِمَّ النَّسْخُ تَعَارَضَ الْحَدِيثَانِ، حَدِيثُ عَبْدِ اللَّهِ بْنِ عُكَيْمٍ وَحَدِيثُ ابْنِ عَبَّاسٍ وَمَنْ مَعَهُ، وَمَعَ التَّعَارُضِ يُرْجَعُ إلَى التَّرْجِيحِ أَوْ الْوَقْفِ،؛ لِأَنَّا نَقُولُ لَا تَعَارُضَ إلَّا مَعَ الِاسْتِوَاءِ، وَهُوَ مَفْقُودٌ كَمَا عَرَفْت مِنْ صِحَّةِ حَدِيثِ ابْنِ عَبَّاسٍ، وَكَثْرَةِ مَنْ مَعَهُ مِنْ الرُّوَاةِ، وَعَدَمِ ذَلِكَ فِي حَدِيثِ ابْنِ عُكَيْمٍ","src":"سبل السلام","loc":"١/٤٢","pre":"وأما حديث عبد الله بن عُكيم فقد أجاب عنه الصنعاني بأجوبة، فقال: الأول:"},{"t":"tanbih","items":[{"t":"p","text":"لا يحلّ أكل جلد الميتة ولو دُبغ؛ لقوله ﷺ: «إنما حرم أكلها»، وهو قول أكثر أهل العلم (المغني ١/٥١)."},{"t":"quote","text":"وَيَجُوزُ بَيْعُهُ، وَإِجَارَتُهُ، وَالِانْتِفَاعُ بِهِ فِي كُلِّ مَا يُمْكِنُ الِانْتِفَاعُ بِهِ فِيهِ، سِوَى الْأَكْلِ؛ لِأَنَّهُ صَارَ بِمَنْزِلَةِ الْمُذَكَّى فِي غَيْرِ الْأَكْلِ وَلَا يَجُوزُ بَيْعُهُ قَبْلَ دَبْغِهِ؛ لِأَنَّهُ نَجِسٌ، مُتَّفَقٌ عَلَى نَجَاسَةِ عَيْنِهِ، فَأَشْبَهَ الْخِنْزِيرَ","src":"المغني","loc":"١/٥١","pre":"قال ابن قدامة في الجلد المدبوغ عند من قال بطهارته:"}]}],"refs":["المغني (١/٤٩)","المجموع (١/٢١٧)","المدونة (١/١٨٣)","مجموع فتاوى ابن باز (١/٢٧٠)","مسلم ٣٦٦","سبل السلام (١/٤٢)","المغني (١/٥١)"],"related":["عظم الميتة وشعرها وصوفها"],"alts":["دباغ الجلد","جلود الحيوانات الميتة","الصلاة على جلد مدبوغ"]},{"n":23,"bab":"الطهارة","sub":"الآنية","title":"عظم الميتة وقرنها وشعرها وصوفها","q":"هل عظم الميتة وقرنها وشعرها وصوفها وريشها طاهر، فيجوز الانتفاع به؟","short":"شعر الميتة وصوفها ووبرها وريشها طاهر عند جمهور العلماء؛ وأما العظم والقرن والظفر ففيها خلاف، والراجح طهارتها أيضًا، وهو قول أبي حنيفة، واختاره ابن تيمية.","body":[{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا عَظْمُ الْمَيْتَةِ وَقَرْنُهَا؛ وَظُفْرُهَا؛ وَمَا هُوَ مِنْ جِنْسِ ذَلِكَ كَالْحَافِرِ وَنَحْوِهِ وَشَعْرِهَا وَرِيشِهَا؛ وَوَبَرِهَا: فَفِي هَذَيْنَ النَّوْعَيْنِ لِلْعُلَمَاءِ ثَلَاثَةُ أَقْوَالٍ: أَحَدُهَا: نَجَاسَةُ الْجَمِيعِ. كَقَوْلِ الشَّافِعِيِّ فِي الْمَشْهُورِ عَنْهُ؛ وَذَلِكَ رِوَايَةٌ عَنْ أَحْمَد. وَالثَّانِي: أَنَّ الْعِظَامَ وَنَحْوَهَا نَجِسَةٌ وَالشُّعُورَ وَنَحْوَهَا طَاهِرَةٌ. وَهَذَا هُوَ الْمَشْهُورُ مِنْ مَذْهَبِ مَالِكٍ وَأَحْمَد. وَالثَّالِثُ: أَنَّ الْجَمِيعَ طَاهِرٌ. كَقَوْلِ أَبِي حَنِيفَةَ؛ وَهُوَ قَوْلٌ فِي مَذْهَبِ مَالِكٍ وَأَحْمَد","src":"مجموع الفتاوى","loc":"٢١/٩٦-٩٧","pre":"جمع ابن تيمية الأقوال في المسألة فقال:"},{"t":"p","text":"فالأقوال ثلاثة:"},{"t":"qawl","label":"القول الأول","text":"نجاسة الجميع: العظم والشعر وما في معناهما، وهو المشهور عن الشافعي، ورواية عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"نجاسة العظام ونحوها، وطهارة الشعور ونحوها، وهو المشهور من مذهب مالك وأحمد."},{"t":"quote","text":"وَجُمْلَةُ ذَلِكَ، أَنَّ عِظَامَ الْمَيْتَةِ نَجِسَةٌ، سَوَاءٌ كَانَتْ مَيْتَةَ مَا يُؤْكَلُ لَحْمُهُ، أَوْ مَا لَا يُؤْكَلُ لَحْمُهُ، كَالْفِيَلَةِ، وَلَا يَطْهُرُ بِحَالٍ، وَهَذَا مَذْهَبُ مَالِكٍ، وَالشَّافِعِيِّ، وَإِسْحَاقَ، وَكَرِهَ عَطَاءٌ، وَطَاوُسٌ، وَالْحَسَنُ، وَعُمَرُ بْنُ عَبْدِ الْعَزِيزِ - رَضِيَ اللَّهُ عَنْهُمْ - عِظَامَ الْفِيَلَةِ، وَرَخَّصَ فِي الِانْتِفَاعِ بِهَا مُحَمَّدُ بْنُ سِيرِينَ، وَغَيْرُهُ، وَابْنُ جُرَيْجٍ؛ لِمَا رَوَى أَبُو دَاوُد بِإِسْنَادِهِ عَنْ ثَوْبَانِ، أَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «اشْتَرِ لِفَاطِمَةَ - رَضِيَ اللَّهُ عَنْهَا - قِلَادَةً مِنْ عَصَبٍ وَسِوَارَيْنِ مِنْ عَاجٍ» . وَلَنَا قَوْلُ اللَّهِ تَعَالَى: {حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ} المائدة: 3 وَالْعَظْمُ مِنْ جُمْلَتِهَا، فَيَكُونُ مُحَرَّمًا، وَالْفِيلُ لَا يُؤْكَلُ لَحْمُهُ فَهُوَ نَجِسٌ عَلَى كُلِّ حَالٍ، وَأَمَّا الْحَدِيثُ، فَقَالَ الْخَطَّابِيُّ: قَالَ الْأَصْمَعِيُّ: الْعَاجُ الذَّبْلُ، وَيُقَال: هُوَ عَظْمُ ظَهْرِ السُّلَحْفَاةِ الْبَحْرِيَّةِ. وَذَهَبَ مَالِكٌ إلَى أَنَّ الْفِيلَ إنَّ ذُكِّيَ فَعَظْمُهُ طَاهِرٌ، وَإِلَّا فَهُوَ نَجِسٌ؛ لِأَنَّ الْفِيلَ مَأْكُولٌ عِنْدَهُ، وَهُوَ غَيْرُ صَحِيحٍ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «نَهَى عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنْ السِّبَاعِ» رَوَاهُ مُسْلِمٌ وَالْفِيلُ أَعْظَمُهَا نَابًا فَأَمَّا عِظَامُ بَقِيَّةِ الْمَيْتَاتِ، فَذَهَبَ الثَّوْرِيُّ، وَأَبُو حَنِيفَةَ، إلَى طَهَارَتِهَا؛ لِأَنَّ الْمَوْتَ لَا يُحِلُّهَا فَلَا تَنْجُسُ بِهِ، كَالشَّعْرِ؛ وَلِأَنَّ عِلَّةَ التَّنْجِيسِ فِي اللَّحْمِ وَالْجِلْدِ اتِّصَالُ الدِّمَاءِ وَالرُّطُوبَاتِ بِهِ، وَلَا يُوجَدُ ذَلِكَ فِي الْعِظَامِ وَلَنَا قَوْلُ اللَّهِ تَعَالَى {قَالَ مَنْ يُحْيِي الْعِظَامَ وَهِيَ رَمِيمٌ} يس: 78 {قُلْ يُحْيِيهَا الَّذِي أَنْشَأَهَا أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ} يس: 79 وَمَا يَحْيَا فَهُوَ يَمُوتُ؛ وَلِأَنَّ دَلِيلَ الْحَيَاةِ الْإِحْسَاسُ وَالْأَلَمُ، وَالْأَلَمُ فِي الْعَظْمِ أَشَدُّ مِنْ الْأَلَمِ فِي اللَّحْمِ وَالْجِلْدِ، وَالضِّرْسُ يَأْلَمُ، وَيَلْحَقُهُ الضِّرْسُ، وَيُحِسُّ بِبَرْدِ الْمَاءِ وَحَرَارَتِهِ، وَمَا تَحِلُّهُ الْحَيَاةُ يَحِلُّهُ الْمَوْتُ؛ إذْ كَانَ الْمَوْتُ مُفَارَقَةَ الْحَيَاةِ، وَمَا يَحُلُّهُ الْمَوْتُ يَنْجُسُ بِهِ كَاللَّحْمِ","src":"المغني","loc":"١/٥٣-٥٤","pre":"قال ابن قدامة في دليل نجاسة العظام:"},{"t":"qawl","label":"القول الثالث","text":"طهارة الجميع، وهو قول أبي حنيفة والثوري، وقول في مذهب مالك وأحمد."},{"t":"quote","text":"وَشَعْرُ الْمَيْتَةِ غَيْرُ الْخِنْزِيرِ عَلَى الْمَذْهَبِ وَعَظْمُهَا وَعَصَبُهَا عَلَى الْمَشْهُورِ وَحَافِرُهَا وَقَرْنُهَا الْخَالِيَةُ عَنْ الدُّسُومَةِ وَكَذَا كُلُّ مَا لَا تُحِلُّهُ الْحَيَاةُ","src":"الدر المختار مع رد المحتار","loc":"١/٢٠٦","pre":"وقال في «الدر المختار» من كتب الحنفية في عدّ الأشياء الطاهرة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"أما الشعر والصوف فطهارته قول الجمهور؛ لأنه لا تحله الحياة الحيوانية، ولهذا يجوز جزّه من الحيوان الحي، فلا ينجس بموته."},{"t":"quote","text":"وَلِأَنَّهُ لَا تَفْتَقِرُ طَهَارَةٌ مُنْفَصِلَةٌ إلَى ذَكَاةِ أَصْلِهِ، فَلَمْ يَنْجُسْ بِمَوْتِهِ، كَأَجْزَاءِ السَّمَكِ وَالْجَرَادِ؛ وَلِأَنَّهُ لَا يَحُلُّهُ الْمَوْتُ فَلَمْ يَنْجُسُ بِمَوْتِ الْحَيَوَانِ، كَبَيْضِهِ، وَالدَّلِيلُ عَلَى أَنَّهُ لَا حَيَاةَ فِيهِ، أَنَّهُ لَا يُحِسُّ وَلَا يَأْلَمُ، وَهُمَا دَلِيلَا الْحَيَاةِ، وَلَوْ انْفَصَلَ فِي الْحَيَاةِ كَانَ طَاهِرًا، وَلَوْ كَانَتْ فِيهِ حَيَاةٌ لَنَجِسَ بِفَصْلِهِ؛ لِقَوْلِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «مَا أُبِينَ مِنْ حَيٍّ فَهُوَ مَيِّتٌ.» رَوَاهُ أَبُو دَاوُد بِمَعْنَاهُ، وَمَا ذَكَرُوهُ يُنْتَقَضُ بِالْبَيْضِ، وَيُفَارِقُ الْأَعْضَاءَ، فَإِنَّ فِيهَا حَيَاةً، وَتَنْجُسُ بِفَصْلِهَا فِي حَيَاةِ الْحَيَوَانِ، وَالنُّمُوُّ بِمُجَرَّدِهِ لَيْسَ بِدَلِيلِ الْحَيَاةِ، فَإِنَّ الْحَشِيشَ يَنْمُو، وَلَا يَنْجُسُ","src":"المغني","loc":"١/٥٩","pre":"قال ابن قدامة:"},{"t":"p","text":"وأما العظم والقرن والظفر فالراجح طهارتها كذلك، وهو قول الحنفية، وقد صوّبه ابن تيمية فقال:"},{"t":"quote","text":"وَهَذَا الْقَوْلُ هُوَ الصَّوَابُ؛ وَذَلِكَ لِأَنَّ الْأَصْلَ فِيهَا الطَّهَارَةُ؛ وَلَا دَلِيلَ عَلَى النَّجَاسَةِ. وَأَيْضًا فَإِنَّ هَذِهِ الْأَعْيَانَ هِيَ مِنْ الطَّيِّبَاتِ لَيْسَتْ مِنْ الْخَبَائِثِ فَتَدْخُلُ فِي آيَةِ التَّحْلِيلِ؛ وَذَلِكَ لِأَنَّهَا لَمْ تَدْخُلْ فِيمَا حَرَّمَهُ اللَّهُ مِنْ الْخَبَائِثِ لَا لَفْظًا وَلَا مَعْنًى","src":"مجموع الفتاوى","loc":"٢١/٩٧"},{"t":"tanbih","items":[{"t":"p","text":"ما قُطع من البهيمة وهي حية مما تحلّه الحياة — كالسنام والألية — فهو ميتة؛ بخلاف الشعر والصوف إذا جُزّ منها، فهو طاهر بالاتفاق."}]}],"refs":["مجموع الفتاوى (٢١/٩٦-٩٧)","المغني (١/٥٣-٥٤)","الدر المختار مع رد المحتار (١/٢٠٦)","المغني (١/٥٩)","مجموع الفتاوى (٢١/٩٧)"],"related":["جلد الميتة إذا دُبغ"],"alts":["العاج","أمشاط العظم","الصوف والشعر من الحيوان الميت"]},{"n":24,"bab":"الطهارة","sub":"الآنية","title":"آنية الكفار وثيابهم","q":"هل يجوز الأكل والشرب في أواني غير المسلمين، أو لبس ثيابهم والصلاة فيها؟","short":"أواني أهل الكتاب وغيرهم من الكفار وثيابهم طاهرة يجوز استعمالها ما لم تُعلم نجاستها؛ لأن الأصل الطهارة. والأولى غسل الأواني التي يُطبخ فيها الخنزير أو يُشرب فيها الخمر قبل استعمالها، فإن تُيقّنت نجاستها وجب غسلها.","body":[{"t":"h","text":"الدليل من القرآن والسنة"},{"t":"aya","text":"ۖ وَطَعَامُ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ","ref":"المائدة: ٥"},{"t":"quote","text":"وَرُوِيَ أَنَّ «النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَضَافَهُ يَهُودِيٌّ بِخُبْزٍ وَإِهَالَةٍ سَنِخَةٍ.» رَوَاهُ الْإِمَامُ أَحْمَدُ، فِي \" الْمُسْنَدِ \" وَكِتَابِ \" الزُّهْدِ \"، وَتَوَضَّأَ عُمَرُ مِنْ جَرَّةِ نَصْرَانِيَّةٍ","src":"المغني","loc":"١/٦١"},{"t":"quote","text":"يَا نَبِيَّ اللَّهِ إِنَّا بِأَرْضِ قَوْمٍ أَهْلِ الْكِتَابِ، أَفَنَأْكُلُ فِي آنِيَتِهِمْ وَبِأَرْضِ صَيْدٍ، أَصِيدُ بِقَوْسِي وَبِكَلْبِي الَّذِي لَيْسَ بِمُعَلَّمٍ، وَبِكَلْبِي الْمُعَلَّمِ، فَمَا يَصْلُحُ لِي قَالَ «أَمَّا مَا ذَكَرْتَ مِنْ أَهْلِ الْكِتَابِ فَإِنْ وَجَدْتُمْ غَيْرَهَا فَلاَ تَأْكُلُوا فِيهَا، وَإِنْ لَمْ تَجِدُوا فَاغْسِلُوهَا وَكُلُوا فِيهَا»","src":"رواه البخاري ٥٤٧٨، ومسلم ١٩٣٠","pre":"وعن أبي ثعلبة الخشني رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":5478,"id":"h5478"},{"book":"mt_muslim","num":1930,"id":"h1930"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أما أواني أهل الكتاب فاتفق العلماء على جواز استعمالها ما لم تُتيقّن نجاستها، واختلفوا في كراهة ذلك؛ وأما أواني غير أهل الكتاب ففيها قولان:"},{"t":"qawl","label":"القول الأول","text":"أنها طاهرة مباحة الاستعمال ما لم تُتيقّن نجاستها، وهو مذهب الشافعي، واختاره أبو الخطاب من الحنابلة."},{"t":"qawl","label":"القول الثاني","text":"لا يُستعمل ما استعملوه من آنيتهم في أطعمتهم إلا بعد غسله، وهو قول القاضي أبي يعلى، وظاهر كلام أحمد."},{"t":"quote","text":"الضَّرْبُ الثَّانِي: غَيْرُ أَهْلِ الْكِتَابِ، وَهُمْ الْمَجُوسُ، وَعَبَدَةُ الْأَوْثَانِ، وَنَحْوُهُمْ، فَحُكْمُ ثِيَابِهِمْ حُكْمُ ثِيَابِ أَهْلِ الذِّمَّةِ، وَأَمَّا أَوَانِيهِمْ، فَقَالَ الْقَاضِي: لَا يُسْتَعْمَلُ مَا اسْتَعْمَلُوهُ مِنْ آنِيَتِهِمْ؛ لِأَنَّ أَوَانِيَهُمْ لَا تَخْلُو مِنْ أَطْعِمَتِهِمْ، وَذَبَائِحُهُمْ مَيْتَةٌ، فَلَا تَخْلُو أَوَانِيهِمْ مِنْ وَضْعِهَا فِيهَا. وَقَالَ أَبُو الْخَطَّابِ حُكْمُهُمْ حُكْمُ أَهْلِ الْكِتَابِ، وَثِيَابُهُمْ وَأَوَانِيهِمْ طَاهِرَةٌ، مُبَاحَةُ الِاسْتِعْمَالِ، مَا لَمْ يَتَيَقَّنْ نَجَاسَتَهَا، وَهُوَ مَذْهَبُ الشَّافِعِيِّ؛ «لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ تَوَضَّئُوا مِنْ مَزَادَةِ مُشْرِكَةٍ» مُتَّفَقٌ عَلَيْهِ؛ وَلِأَنَّ الْأَصْلَ الطَّهَارَةُ، فَلَا تَزُولُ بِالشَّكِّ. وَظَاهِرُ كَلَامِ أَحْمَدَ، - رَحِمَهُ اللَّهُ -، مِثْلُ قَوْلِ الْقَاضِي، فَإِنَّهُ قَالَ فِي الْمَجُوسِ: لَا يُؤْكَلُ مِنْ طَعَامِهِمْ إلَّا الْفَاكِهَةُ؛ لِأَنَّ الظَّاهِرَ نَجَاسَةُ آنِيَتِهِمْ الْمُسْتَعْمَلَةِ فِي أَطْعِمَتِهِمْ، فَأَشْبَهَتْ السَّرَاوِيلَاتِ مِنْ ثِيَابِهِمْ. وَمَنْ يَأْكُلُ الْخِنْزِيرَ مِنْ النَّصَارَى، فِي مَوْضِعٍ يُمْكِنُهُمْ أَكْلُهُ، أَوْ يَأْكُلُ الْمِيتَةَ، أَوْ يَذْبَحُ بِالسِّنِّ وَالظُّفْرِ وَنَحْوِهِ، فَحُكْمُهُ حُكْمُ غَيْرِ أَهْلِ الْكِتَابِ؛ لِاتِّفَاقِهِمْ فِي نَجَاسَةِ أَطْعِمَتِهِمْ. وَمَتَى شَكَّ فِي الْإِنَاءِ؛ هَلْ اسْتَعْمَلُوهُ فِي أَطْعِمَتِهِمْ، أَوْ لَمْ يَسْتَعْمِلُوهُ، فَهُوَ طَاهِرٌ؛ لِأَنَّ الْأَصْلَ طَهَارَتُهُ","src":"المغني","loc":"١/٦٢","pre":"قال ابن قدامة:"},{"t":"h","text":"ثيابهم"},{"t":"quote","text":"وَلَا نَعْلَمُ خِلَافًا بَيْنَ أَهْلِ الْعِلْمِ فِي إبَاحَةِ الصَّلَاةِ فِي الثَّوْبِ الَّذِي يَنْسِجُهُ الْكُفَّارُ؛ فَإِنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَأَصْحَابَهُ، إنَّمَا كَانَ لِبَاسُهُمْ مِنْ نَسْجِ الْكُفَّارِ. فَأَمَّا ثِيَابُهُمْ، الَّتِي يَلْبَسُونَهَا، فَأَبَاحَ الصَّلَاةَ فِيهَا الثَّوْرِيُّ، وَأَصْحَابُ الرَّأْيِ، وَقَالَ مَالِكٌ فِي ثَوْبِ الْكُفَّارِ: يَلْبَسُهُ عَلَى كُلِّ حَالٍ، وَإِنْ صَلَّى فِيهِ يُعِيدُ، مَا دَامَ فِي الْوَقْتِ. وَلَنَا أَنَّ الْأَصْلَ الطَّهَارَةُ، وَلَمْ تَتَرَجَّحْ جِهَةُ التَّنْجِيسِ فِيهِ، فَأَشْبَهَ مَا نَسَجَهُ الْكُفَّارُ","src":"المغني","loc":"١/٦٢","pre":"قال ابن قدامة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"قال عليه الصلاة والسلام (لا تأكلوا في آنيتهم إلا تجدوا غيرها فاغسلوها وكلوا فيها) . وقال عليه الصلاة والسلام ذلك من أجل أن يبتعد المسلم عن مخالطة الكفار, وإلا فالطاهر منها طاهر","src":"مجموع فتاوى ابن عثيمين","loc":"١٥/٤٤١","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن الأكل في آنية الكفار، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن الأصل في أوانيهم وثيابهم الطهارة، فلا تزول بالشك؛ وقد توضأ النبي ﷺ وأصحابه من مزادة امرأة مشركة. وحديث أبي ثعلبة محمول على من عُرفوا بالأكل في آنيتهم مما حرّمه الله، فإن لم يوجد غيرها غُسلت ثم استُعملت."}],"refs":["المغني (١/٦١)","البخاري ٥٤٧٨، ومسلم ١٩٣٠","المغني (١/٦٢)","مجموع فتاوى ابن عثيمين (١٥/٤٤١)"],"related":["الأكل والشرب والوضوء في آنية الذهب والفضة"],"alts":["أواني غير المسلمين","الأكل في مطاعم غير المسلمين","لبس ثياب الكفار"]},{"n":25,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"حكم الختان ووقته","q":"ما حكم الختان؟ وهل هو واجب أو سنة؟ ومتى يُختن الصبي؟ وما حكم من أسلم كبيرًا؟","short":"الختان من سنن الفطرة باتفاق، واختلفوا في وجوبه: فأوجبه الشافعي، وأوجبه أحمد على الرجال، وجعله مالك وأبو حنيفة سنة؛ والراجح أنه في حق الرجال سنة مؤكدة من شعائر الإسلام لا ينبغي تركها. ولا يختص بوقت، والأفضل تعجيله في الصغر؛ ومن أسلم كبيرًا وخاف على نفسه سقط عنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الْفِطْرَةُ خَمْسٌ - أَوْ خَمْسٌ مِنَ الْفِطْرَةِ - الْخِتَانُ، وَالِاسْتِحْدَادُ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبِطِ، وَقَصُّ الشَّارِبِ»","src":"رواه مسلم ٢٥٧، والبخاري ٥٨٩١","links":[{"book":"mt_muslim","num":257,"id":"h257"},{"book":"mt_bukhari","num":5891,"id":"h5891"}]},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «اخْتَتَنَ إِبْرَاهِيمُ ـ عَلَيْهِ السَّلاَمُ ـ وَهْوَ ابْنُ ثَمَانِينَ سَنَةً بِالْقَدُّومِ»","src":"رواه البخاري ٣٣٥٦","links":[{"book":"mt_bukhari","num":3356,"id":"h3356"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتُلِفَ فِي وُجُوبِ الْخِتَانِ فَرَوَى الْإِمَامُ يَحْيَى عَنْ الْعِتْرَةِ وَالشَّافِعِيُّ وَكَثِيرٌ مِنْ الْعُلَمَاءِ أَنَّهُ وَاجِبٌ فِي حَقِّ الرِّجَالِ وَالنِّسَاءِ. وَعِنْدَ مَالِكٍ وَأَبِي حَنِيفَةَ وَالْمُرْتَضَى، قَالَ النَّوَوِيُّ: وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ أَنَّهُ سُنَّةٌ فِيهِمَا","src":"نيل الأوطار","loc":"١/١٤٥","pre":"قال الشوكاني:"},{"t":"qawl","label":"القول الأول","text":"أنه واجب على الرجال والنساء، وهو مذهب الشافعي."},{"t":"qawl","label":"القول الثاني","text":"أنه واجب على الرجال، مَكرُمة في حق النساء، وهو مذهب أحمد."},{"t":"quote","text":"فَأَمَّا الْخِتَانُ فَوَاجِبٌ عَلَى الرِّجَالِ، وَمَكْرُمَةٌ فِي حَقِّ النِّسَاءِ، وَلَيْسَ بِوَاجِبٍ عَلَيْهِنَّ. هَذَا قَوْلُ كَثِيرٍ مِنْ أَهْلِ الْعِلْمِ","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَالدَّلِيلُ عَلَى وُجُوبِهِ: أَنَّ سَتْرَ الْعَوْرَةِ وَاجِبٌ، فَلَوْلَا أَنَّ الْخِتَانَ وَاجِبٌ لَمْ يَجُزْ هَتْكُ حُرْمَةِ الْمَخْتُونِ بِالنَّظَرِ إلَى عَوْرَتِهِ مِنْ أَجْلِهِ؛ وَلِأَنَّهُ مِنْ شِعَارِ الْمُسْلِمِينَ، فَكَانَ وَاجِبًا، كَسَائِرِ شِعَارِهِمْ","src":"المغني","loc":"١/٦٤","pre":"ودليلهم:"},{"t":"qawl","label":"القول الثالث","text":"أنه سنة في الرجال والنساء، وهو مذهب مالك وأبي حنيفة، وقول أكثر العلماء كما حكاه النووي."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"أما الختان فهو من سنن الفطرة ومن شعار المسلمين لما في الصحيحين من حديث أبي هريرة رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم: «الفطرة خمس الختان والاستحداد وقص الشارب وتقليم الأظافر ونتف الإبط»","src":"مجموع فتاوى ابن باز","loc":"٢/٢٣٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"حكم الختان محل خلاف، وأقرب الأقوال أن الختان واجب في حق الرجال، سنة في حق النساء","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١١٧","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"وَالْحَقُّ أَنَّهُ لَمْ يَقُمْ دَلِيلٌ صَحِيحٌ يَدُلُّ عَلَى الْوُجُوبِ وَالْمُتَيَقَّنُ السُّنِّيَّةُ كَمَا فِي حَدِيثِ: (خَمْسٌ مِنْ الْفِطْرَةِ) وَنَحْوِهِ، وَالْوَاجِبُ الْوُقُوفُ عَلَى الْمُتَيَقَّنِ إلَى أَنْ يَقُومَ مَا يُوجِبُ الِانْتِقَالَ عَنْهُ","src":"نيل الأوطار","loc":"١/١٤٦","pre":"قال الشوكاني بعد أن ناقش أدلة الأقوال:"},{"t":"p","text":"فالختان في حق الرجال سنة مؤكدة من خصال الفطرة وشعائر المسلمين، فلا ينبغي التهاون به، ومن أخذ بقول من أوجبه احتياطًا فقد أحسن."},{"t":"h","text":"وقت الختان"},{"t":"quote","text":"وَأَوْرَدَ الْمُصَنِّفُ الْحَدِيثَ فِي هَذَا الْبَابِ لِلِاسْتِدْلَالِ بِهِ عَلَى أَنَّ مُدَّةَ الْخِتَانِ لَا تَخْتَصُّ بِوَقْتٍ مُعَيَّنٍ، وَهُوَ مَذْهَبُ الْجُمْهُورِ وَلَيْسَ بِوَاجِبٍ فِي حَالِ الصِّغَرِ","src":"نيل الأوطار","loc":"١/١٤٥"},{"t":"quote","text":"عَنْ سَعِيدِ بْنِ جُبَيْرٍ، قَالَ سُئِلَ ابْنُ عَبَّاسٍ مِثْلُ مَنْ أَنْتَ حِينَ قُبِضَ النَّبِيُّ صلى الله عليه وسلم قَالَ أَنَا يَوْمَئِذٍ مَخْتُونٌ. قَالَ وَكَانُوا لاَ يَخْتِنُونَ الرَّجُلَ حَتَّى يُدْرِكَ","src":"رواه البخاري ٦٢٩٩","links":[{"book":"mt_bukhari","num":6299,"id":"h6299"}]},{"t":"tanbih","items":[{"t":"quote","text":"وَإِنْ أَسْلَمَ رَجُلٌ كَبِيرٌ فَخَافَ عَلَى نَفْسِهِ مِنْ الْخِتَانِ سَقَطَ عَنْهُ؛ لِأَنَّ الْغُسْلَ وَالْوُضُوءَ وَغَيْرَهُمَا يَسْقُطُ إذَا خَافَ عَلَى نَفْسِهِ مِنْهُ، فَهَذَا أَوْلَى","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"}]}],"refs":["مسلم ٢٥٧، والبخاري ٥٨٩١","البخاري ٣٣٥٦","نيل الأوطار (١/١٤٥)","المغني (١/٦٤)","مجموع فتاوى ابن باز (٢/٢٣٩)","مجموع فتاوى ابن عثيمين (١١/١١٧)","نيل الأوطار (١/١٤٦)","البخاري ٦٢٩٩"],"related":["خصال الفطرة ومدة تركها"],"alts":["ختان الكبير","ختان المولود","هل الختان واجب"]},{"n":26,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"خصال الفطرة: حلق العانة ونتف الإبط وتقليم الأظفار، ومدة تركها","q":"ما خصال الفطرة؟ وما أقصى مدة يجوز فيها ترك حلق العانة ونتف الإبط وتقليم الأظفار وقص الشارب؟","short":"خصال الفطرة سنن مؤكدة، منها: قص الشارب، وإعفاء اللحية، والسواك، وحلق العانة، ونتف الإبط، وتقليم الأظفار؛ ولا يُترك شيء من ذلك أكثر من أربعين ليلة. ويجوز إزالة شعر الإبط والعانة بأي وسيلة، والأفضل ما وافق السنة: النتف في الإبط، والحلق في العانة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «عَشْرٌ مِنَ الْفِطْرَةِ: قَصُّ الشَّارِبِ، وَإِعْفَاءُ اللِّحْيَةِ، وَالسِّوَاكُ، وَاسْتِنْشَاقُ الْمَاءِ، وَقَصُّ الْأَظْفَارِ، وَغَسْلُ الْبَرَاجِمِ، وَنَتْفُ الْإِبِطِ، وَحَلْقُ الْعَانَةِ، وَانْتِقَاصُ الْمَاءِ» قَالَ زَكَرِيَّا: قَالَ مُصْعَبٌ: وَنَسِيتُ الْعَاشِرَةَ إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ","src":"رواه مسلم ٢٦١، وأبو داود ٥٣، والترمذي ٢٧٥٧","links":[{"book":"mt_muslim","num":261,"id":"h261"},{"book":"mt_abudawud","num":53,"id":"h53"},{"book":"mt_tirmidhi","num":2757,"id":"h2757"}]},{"t":"quote","text":"عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: - قَالَ أَنَسٌ - «وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ، وَتَقْلِيمِ الْأَظْفَارِ، وَنَتْفِ الْإِبِطِ، وَحَلْقِ الْعَانَةِ، أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً»","src":"رواه مسلم ٢٥٨، وابن ماجه ٢٩٥","links":[{"book":"mt_muslim","num":258,"id":"h258"},{"book":"mt_ibnmajah","num":295,"id":"h295"}]},{"t":"h","text":"معنى الفطرة"},{"t":"quote","text":"وَالْمُرَادُ بِقَوْلِهِ: (خَمْسٌ مِنْ الْفِطْرَةِ) فِي حَدِيث الْبَابِ أَنَّ هَذِهِ الْأَشْيَاءَ إذَا فُعِلَتْ اتَّصَفَ فَاعِلُهَا بِالْفِطْرَةِ الَّتِي فَطَرَ اللَّهُ الْعِبَادَ عَلَيْهَا وَحَثَّهُمْ عَلَيْهَا وَاسْتَحَبَّهَا لَهُمْ لِيَكُونُوا عَلَى أَكْمَلِ الصِّفَاتِ وَأَشْرَفِهَا صُورَةً","src":"نيل الأوطار","loc":"١/١٤١","pre":"قال الشوكاني:"},{"t":"h","text":"كيفية الإزالة"},{"t":"quote","text":"وَالِاسْتِحْدَادُ: حَلْقُ الْعَانَةِ. وَهُوَ مُسْتَحَبٌّ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَفْحُشُ بِتَرْكِهِ، فَاسْتُحِبَّتْ إزَالَتُهُ، وَبِأَيِّ شَيْءٍ أَزَالَهُ صَاحِبُهُ فَلَا بَأْسَ؛ لِأَنَّ الْمَقْصُودَ إزَالَتُهُ","src":"المغني","loc":"١/٦٤","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَنَتْفُ الْإِبْطِ سُنَّةٌ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَفْحُشُ بِتَرْكِهِ. وَإِنْ أَزَالَ الشَّعْرَ بِالْحَلْقِ أَوْ النُّورَةِ جَازَ، وَنَتْفُهُ أَفْضَلُ لِمُوَافَقَتِهِ الْخَبَرَ","src":"المغني","loc":"١/٦٥","pre":"وقال:"},{"t":"quote","text":"وَيُسْتَحَبُّ تَقْلِيمُ الْأَظْفَارِ؛ لِأَنَّهُ مِنْ الْفِطْرَةِ، وَيَتَفَاحَشُ إذَا تَرَكَهَا، وَرُبَّمَا حَكَّ بِهِ الْوَسَخَ، فَيَجْتَمِعُ تَحْتَهَا مِنْ الْمَوَاضِعِ الْمُنْتِنَةِ، فَتَصِيرُ رَائِحَةُ ذَلِكَ فِي رُءُوسِ الْأَصَابِعِ. وَرُبَّمَا مَنَعَ وُصُولَ الطَّهَارَةِ إلَى مَا تَحْتَهُ","src":"المغني","loc":"١/٦٥","pre":"وقال:"},{"t":"quote","text":"ويستحب أن يقلم الاظافر ويقص الشارب ويغسل البراجم وينتف الابط ويحلق العانة","src":"المجموع","loc":"١/٢٨٣","pre":"وقال في «المهذب» مع شرحه «المجموع» من كتب الشافعية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"إزالة شعر الإبط من الفطرة التي فطر الله الخلق عليها، وجاءت بها الشرائع المنزلة من عند الله عز وجل","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٣٠","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الخلاصة","k":"r"},{"t":"p","text":"هذه الخصال سنن مؤكدة، وحديث أنس رضي الله عنه حدّ أقصى المدة بأربعين ليلة، فلا ينبغي أن تُترك أكثر من ذلك؛ والأفضل تعاهدها كلما طالت، ولا سيما يوم الجمعة."},{"t":"tanbih","items":[{"t":"p","text":"لا يتوقف على هذه الخصال صحة الوضوء ولا الصلاة، إلا إذا كان تحت الأظفار ما يمنع وصول الماء إلى البشرة، كما أشار إليه ابن قدامة في كلامه المنقول."}]}],"refs":["مسلم ٢٦١، وأبو داود ٥٣، والترمذي ٢٧٥٧","مسلم ٢٥٨، وابن ماجه ٢٩٥","نيل الأوطار (١/١٤١)","المغني (١/٦٤)","المغني (١/٦٥)","المجموع (١/٢٨٣)","مجموع فتاوى ابن عثيمين (١١/١٣٠)"],"related":["حكم الختان ووقته","إعفاء اللحية وقص الشارب"],"alts":["مدة حلق العانة","تقليم الأظفار","سنن الفطرة"]},{"n":27,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"إعفاء اللحية وقص الشارب","q":"ما حكم حلق اللحية أو تقصيرها؟ وما الأخذ مما زاد على القبضة؟ وما السنة في الشارب: القص أم الحلق؟","short":"حلق اللحية وتقصيرها عن القبضة لا يجوز في المذاهب الأربعة، والمأمور به إعفاؤها؛ وأما ما زاد على القبضة ففيه خلاف: فأجاز أخذه جماعة — منهم ابن عمر رضي الله عنهما والحنفية — واستحب آخرون تركها على حالها. وأما الشارب فالسنة قصّه حتى يبدو طرف الشفة، وذهب جماعة إلى أن إحفاءه أفضل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «خَالِفُوا الْمُشْرِكِينَ، وَفِّرُوا اللِّحَى، وَأَحْفُوا الشَّوَارِبَ». وَكَانَ ابْنُ عُمَرَ إِذَا حَجَّ أَوِ اعْتَمَرَ قَبَضَ عَلَى لِحْيَتِهِ، فَمَا فَضَلَ أَخَذَهُ","src":"رواه البخاري ٥٨٩٢","links":[{"book":"mt_bukhari","num":5892,"id":"h5892"}]},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «جُزُّوا الشَّوَارِبَ، وَأَرْخُوا اللِّحَى خَالِفُوا الْمَجُوسَ»","src":"رواه مسلم ٢٦٠","links":[{"book":"mt_muslim","num":260,"id":"h260"}]},{"t":"h","text":"المسألة الأولى: حلق اللحية وتقصيرها"},{"t":"quote","text":"وأما تقصير اللحية بحيث تصير قصيرة من القبضة فغير جائز في المذاهب الأربعة، وكذلك كل في الدر المختار في الصيام وترد شهادة مرتكب هذا الفعل","src":"العرف الشذي","loc":"٤/١٦٢","pre":"قال الشيخ أنور شاه الكشميري:"},{"t":"h","text":"المسألة الثانية: الأخذ مما زاد على القبضة"},{"t":"qawl","label":"القول الأول","text":"يجوز أخذ ما زاد على القبضة، وهو فعل ابن عمر رضي الله عنهما وجماعة من التابعين، والمختار عند الحنفية."},{"t":"qawl","label":"القول الثاني","text":"يُكره الأخذ منها مطلقًا، وتُترك على حالها، وهو اختيار النووي."},{"t":"quote","text":"قال الغزالي: اختلف السلف فيما زاد من اللحية، فقيل: لا بأس أن يقبض عليها ويقص ما تحت القبضة، كان ابن عمر يفعله، ثم جماعة من التابعين، والأمر في هذا قريب لأن الطول المفرط قد يشوه الخلقة، قال النووي: والصحيح كراهة الأخذ منها مطلقًا ويتركها على حالها كيف كانت لحديث أعفوا اللحى، وأما حديث عمرو بن عشيب بسنده أن النبي صلى الله عليه وسلم كان يأخذ من لحيته، فرواه الترمذي بإسناد ضعيف لا يحتج به، هكذا في البذل، وفي الدر المختار: لا بأس بأخذ أطراف اللحية والسنة فيها القبضة، قال ابن عابدين: كذا ذكره محمد في كتاب الآثار عن الإمام، قال: وبه نأخذ، انتهى","src":"الكوكب الدري على جامع الترمذي","loc":"٣/٤٠٢","pre":"وفي «الكوكب الدري» من شروح الحنفية:"},{"t":"quote","text":"وأما الذي زائد مسترسل من القبضة فقيل: الأولى الترك، قيل: الأولى القصر، والمختار القصر ولي في هذا الأولوية عبارة محمد في كتاب الآثار","src":"العرف الشذي","loc":"٤/١٦٢","pre":"وقال الكشميري:"},{"t":"h","text":"المسألة الثالثة: الشارب"},{"t":"quote","text":"وَقَدْ اخْتَلَفَ النَّاسُ فِي حَدِّ مَا يُقَصُّ مِنْ الشَّارِبِ، وَقَدْ ذَهَبَ كَثِيرٌ مِنْ السَّلَفِ إلَى اسْتِئْصَالِهِ وَحَلْقِهِ لِظَاهِرِ قَوْلِهِ: (أَحْفُوا وَانْهَكُوا) وَهُوَ قَوْلُ الْكُوفِيِّينَ، وَذَهَبَ كَثِيرٌ مِنْهُمْ إلَى مَنْعِ الْحَلْقِ وَالِاسْتِئْصَالِ، وَإِلَيْهِ ذَهَبَ مَالِكٌ وَكَانَ يَرَى تَأْدِيبَ مَنْ حَلَقَهُ. وَرَوَى عَنْهُ ابْنُ الْقَاسِمِ أَنَّهُ قَالَ: إحْفَاءُ الشَّارِبِ مُثْلَةً. قَالَ النَّوَوِيُّ: الْمُخْتَارُ أَنَّهُ يَقُصُّ حَتَّى يَبْدُوَ طَرَفُ الشَّفَةِ وَلَا يُحْفِيهِ مِنْ أَصْلِهِ، قَالَ: وَأَمَّا رِوَايَةُ: (أَحْفُوا الشَّوَارِبَ) فَمَعْنَاهُ أَحْفُوا مَا طَالَ عَنْ الشَّفَتَيْنِ، وَكَذَلِكَ قَالَ مَالِكٌ فِي الْمُوَطَّإِ يُؤْخَذُ مِنْ الشَّارِبِ حَتَّى يَبْدُوَ أَطْرَافُ الشَّفَةِ، قَالَ ابْنُ الْقَيِّمِ: وَأَمَّا أَبُو حَنِيفَةَ وَزُفَرُ وَأَبُو يُوسُفَ وَمُحَمَّدٌ. فَكَانَ مَذْهَبُهُمْ فِي شَعْرِ الرَّأْسِ وَالشَّوَارِبِ أَنَّ الْإِحْفَاءَ أَفْضَلُ مِنْ التَّقْصِيرِ","src":"نيل الأوطار","loc":"١/١٤٨","pre":"قال الشوكاني:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وأما بالنسبة لمسألة اللحية: فلا ريب أن إعفاءها عبادة؛ لأن النبي، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أمر به، وكل ما أمر به النبي، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فهو عبادة يتقرب بها الإنسان إلى ربه","src":"مجموع فتاوى ابن عثيمين","loc":"٣/١٢٥","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الواجب إعفاء اللحية، وحلقها أو تقصيرها عن القبضة محرّم باتفاق المذاهب الأربعة كما نقله الشيخ الكشميري. وأما ما زاد على القبضة فالأمر فيه واسع: فمن أخذه فله سلف من الصحابة، ومن تركه على حاله فقد وافق ظاهر الأمر بالإعفاء. وأما الشارب فكلٌّ من القص والإحفاء ثابت، والمقصود ألا يطول حتى يغطي الشفة."}],"refs":["البخاري ٥٨٩٢","مسلم ٢٦٠","العرف الشذي (٤/١٦٢)","الكوكب الدري على جامع الترمذي (٣/٤٠٢)","نيل الأوطار (١/١٤٨)","مجموع فتاوى ابن عثيمين (٣/١٢٥)"],"related":["خصال الفطرة","الخضاب بالسواد"],"alts":["حلق اللحية","تقصير اللحية","الأخذ من اللحية","حلق الشارب"]},{"n":28,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"صبغ الشيب، والخضاب بالسواد","q":"هل يُستحب صبغ الشيب؟ وما حكم صبغ الشعر أو اللحية بالسواد؟","short":"يُستحب تغيير الشيب بالحناء والكتم ونحوهما مما ليس سوادًا خالصًا؛ وأما الخضاب بالسواد فقد نهى عنه النبي ﷺ، فحرّمه جماعة وكرهه آخرون، ورخّص فيه بعضهم؛ والراجح اجتنابه، ويُستثنى عند الحنفية الغازي ليهابه العدو.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «إِنَّ الْيَهُودَ وَالنَّصَارَى لاَ يَصْبُغُونَ، فَخَالِفُوهُمْ»","src":"رواه البخاري ٣٤٦٢، ومسلم ٢١٠٣","pre":"عن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":3462,"id":"h3462"},{"book":"mt_muslim","num":2103,"id":"h2103"}]},{"t":"quote","text":"عَنْ جَابِرِ بْنِ عَبْدِ اللهِ، قَالَ: أُتِيَ بِأَبِي قُحَافَةَ يَوْمَ فَتْحِ مَكَّةَ وَرَأْسُهُ وَلِحْيَتُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «غَيِّرُوا هَذَا بِشَيْءٍ، وَاجْتَنِبُوا السَّوَادَ»","src":"رواه مسلم ٢١٠٢، وأبو داود ٤٢٠٤، والنسائي ٥٠٧٦","links":[{"book":"mt_muslim","num":2102,"id":"h2102-2"},{"book":"mt_abudawud","num":4204,"id":"h4204"},{"book":"mt_nasai","num":5076,"id":"h5076"}]},{"t":"h","text":"أقوال العلماء في الخضاب بالسواد"},{"t":"qawl","label":"القول الأول","text":"التحريم، وهو ما صوّبه النووي من الشافعية."},{"t":"quote","text":"قَالَ النَّوَوِيُّ: وَالصَّحِيحُ بَلْ الصَّوَابُ أَنَّهُ حَرَامٌ يَعْنِي الْخِضَابَ بِالسَّوَادِ، وَمِمَّنْ صَرَّحَ بِهِ صَاحِبُ الْحَاوِي انْتَهَى","src":"نيل الأوطار","loc":"١/١٥١"},{"t":"qawl","label":"القول الثاني","text":"الكراهة، وهو مذهب الحنابلة، وقول عامة مشايخ الحنفية إذا كان للزينة."},{"t":"quote","text":"وَيُكْرَهُ الْخِضَابُ بِالسَّوَادِ. قِيلَ لِأَبِي عَبْدِ اللَّهِ: تَكْرَهُ الْخِضَابَ بِالسَّوَادِ؟ قَالَ: إي وَاَللَّهِ. قَالَ: «وَجَاءَ أَبُو بَكْرٍ بِأَبِيهِ إلَى رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَرَأْسُهُ وَلِحْيَتُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - غَيِّرُوهُمَا وَجَنِّبُوهُ السَّوَادَ» . وَرَوَى أَبُو دَاوُد، بِإِسْنَادِهِ عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ مَرْفُوعًا «يَكُونُ قَوْمٌ فِي آخِرِ الزَّمَانِ يُخَضِّبُونَ بِالسَّوَادِ كَحَوَاصِلِ الْحَمَامِ، لَا يَرِيحُونَ رَائِحَةَ الْجَنَّةِ» . وَرَخَّصَ فِيهِ إِسْحَاقُ بْنُ رَاهْوَيْهِ لِلْمَرْأَةِ تَتَزَيَّنُ بِهِ لِزَوْجِهَا","src":"المغني","loc":"١/٦٩","pre":"قال ابن قدامة:"},{"t":"quote","text":"قَالَ فِي الذَّخِيرَةِ: أَمَّا الْخِضَابُ بِالسَّوَادِ لِلْغَزْوِ، لِيَكُونَ أَهْيَبَ فِي عَيْنِ الْعَدُوِّ فَهُوَ مَحْمُودٌ بِالِاتِّفَاقِ وَإِنْ لِيُزَيِّنَ نَفْسَهُ لِلنِّسَاءِ فَمَكْرُوهٌ، وَعَلَيْهِ عَامَّةُ الْمَشَايِخِ، وَبَعْضُهُمْ جَوَّزَهُ بِلَا كَرَاهَةٍ رُوِيَ عَنْ أَبِي يُوسُفَ أَنَّهُ قَالَ: كَمَا يُعْجِبُنِي أَنْ تَتَزَيَّنَ لِي يُعْجِبُهَا أَنْ أَتَزَيَّنَ لَهَا","src":"الدر المختار مع رد المحتار","loc":"٦/٤٢٢","pre":"وقال ابن عابدين:"},{"t":"qawl","label":"القول الثالث","text":"الجواز، وهو مرويّ عن أبي يوسف، وعن جماعة من السلف أنهم خضبوا بالسواد."},{"t":"quote","text":"وَبَعْضُهُمْ بِالزَّعْفَرَانِ. وَخَضَّبَ جَمَاعَةٌ بِالسَّوَادِ، رُوِيَ ذَلِكَ عَنْ عُثْمَانَ وَالْحَسَنِ وَالْحُسَيْنِ ابْنَيْ عَلِيٍّ، وَعُقْبَةَ بْنِ عَامِرٍ وَابْنِ سِيرِينَ وَأَبِي بُرْدَةَ وَآخَرِينَ. قَالَ الطَّبَرِيُّ: الصَّوَابُ أَنَّ الْأَحَادِيثَ الْوَارِدَةَ عَنْ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بِتَغْيِيرِ الشَّيْبِ، وَبِالنَّهْيِ عَنْهُ كُلُّهَا صَحِيحَةٌ وَلَيْسَ فِيهَا تَنَاقُضٌ بَلْ الْأَمْرُ بِالتَّغْيِيرِ لِمَنْ شَيْبُهُ كَشَيْبِ أَبِي قُحَافَةَ، وَالنَّهْيُ لِمَنْ لَهُ شَمْطٌ فَقَطْ قَالَ: وَاخْتِلَافُ السَّلَفِ فِي فِعْلِ الْأَمْرَيْنِ بِحَسَبِ اخْتِلَافِ أَحْوَالِهِمْ فِي ذَلِكَ مَعَ أَنَّ الْأَمْرَ وَالنَّهْيَ فِي ذَلِكَ لَيْسَ لِلْوُجُوبِ بِالْإِجْمَاعِ، وَلِهَذَا لَمْ يُنْكِرْ بَعْضُهُمْ عَلَى بَعْضٍ","src":"نيل الأوطار","loc":"١/١٥٢","pre":"قال الشوكاني ناقلًا عن القاضي عياض والطبري:"},{"t":"quote","text":"قَالَ فِي الذَّخِيرَةِ: أَمَّا الْخِضَابُ بِالسَّوَادِ لِلْغَزْوِ، لِيَكُونَ أَهْيَبَ فِي عَيْنِ الْعَدُوِّ فَهُوَ مَحْمُودٌ بِالِاتِّفَاقِ وَإِنْ لِيُزَيِّنَ نَفْسَهُ لِلنِّسَاءِ فَمَكْرُوهٌ، وَعَلَيْهِ عَامَّةُ الْمَشَايِخِ، وَبَعْضُهُمْ جَوَّزَهُ بِلَا كَرَاهَةٍ","src":"الدر المختار مع رد المحتار","loc":"٦/٤٢٢","pre":"وقال ابن عابدين الحنفي في «رد المحتار»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وفي ذلك أحاديث أخرى كلها تدل على تحريم الخضاب بالسواد وعلى شرعية الخضاب بغيره","src":"مجموع فتاوى ابن باز","loc":"٣/٣١٦","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"ثم إن الحكمة في ذلك هو أن في صبغ الشعر بالسواد مضادة لحكمة الله تعالى التي خلق الخلق عليها، فإنه إذا حوَّل شعره الأبيض إلى السواد، فكأنه يريد أن يرجع بشخوخته إلى الشباب","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٢١","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح اجتناب الخضاب بالسواد؛ لصريح أمر النبي ﷺ: «وجنبوه السواد». وقد صرّح العلامة عبد الحي اللكنوي من محققي الحنفية بأن الخضاب بالسواد الخالص غير جائز، واحتجّ بحديث ابن عباس رضي الله عنهما في الذين يخضبون بالسواد في آخر الزمان، ثم أجاب عمّن رُوي عنه فعله فقال:"},{"t":"quote","text":"وجنح ابن الجوزي في \"العلل المتناهية\" إلى تضعيفه مستنداً بما رُوي أن سعداً والحسين بن عليّ كانا يخضبان بالسواد، وليس بجيد بَأْسًا، وَإِنْ تَرَكَهُ أَبْيَضَ فَلا بَأْسَ بِذَلِكَ، كلُّ ذَلِكَ حَسَنٌ . 43 - بَابُ الْوَلِيِّ يَسْتَقْرِضُ مِنْ مَالِ الْيَتِيمِ 937 - أَخْبَرَنَا مَالِكٌ، أَخْبَرَنَا يَحْيَى بْنُ سَعِيدٍ قَالَ: سَمِعْتُ الْقَاسِمَ بْنَ مُحَمَّدٍ يَقُولُ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ لَهُ: إِنَّ لِي يَتِيمًا وَلَهُ إِبِلٌ فَأَشْرَبُ مِنْ لَبَنِ إِبِلِهِ؟ قَالَ لَهُ ابن عباس: __________ فلعله لم يبلغهما الحديث، والكلام في بعض رواته ليس بحيث يُخرجه عن حيز الاحتجاج به، ومن ثمَّ عدّ ابن حجر المكي في \"الزواجر\" الخضاب بالسواد من الكبائر ويؤيده ما أخرجه الطبراني عن أبي الدرداء مرفوعاً: من خضب بالسواد سودّ الله وجهه يوم القيامة، وعند أحمد: وغيِّروا الشيب ولا تقربوا السواد. وأما ما في \"سنن ابن ماجه\" مرفوعاً: إن أحسن ما اختضبتم به هذا السواد أرغب لنسائكم وأهيب لكم في صدور أعدائكم، ففي سنده ضعفاء فلا يُعارِض الروايات الصحيحة، وأخذ منه بعض الفقهاء جوازه في الجهاد","src":"التعليق الممجد","loc":"٣/٤٦٣-٤٦٤"},{"t":"tanbih","items":[{"t":"p","text":"يُستحب تغيير الشيب بالحناء والكتم، أو بالصفرة؛ لأمر النبي ﷺ بمخالفة اليهود والنصارى في ذلك. وما خُلط فيه الحناء بالكتم فصار بين السواد والحمرة فليس من السواد الخالص."}]}],"refs":["البخاري ٣٤٦٢، ومسلم ٢١٠٣","مسلم ٢١٠٢، وأبو داود ٤٢٠٤، والنسائي ٥٠٧٦","نيل الأوطار (١/١٥١)","المغني (١/٦٩)","الدر المختار مع رد المحتار (٦/٤٢٢)","نيل الأوطار (١/١٥٢)","مجموع فتاوى ابن باز (٣/٣١٦)","مجموع فتاوى ابن عثيمين (١١/١٢١)","التعليق الممجد (٣/٤٦٣-٤٦٤)"],"related":["إعفاء اللحية وقص الشارب"],"alts":["صبغ الشعر بالأسود","الحناء للشيب","صبغ اللحية"]},{"n":29,"bab":"الطهارة","sub":"سنن الفطرة والسواك","title":"السواك: حكمه، ومواضعه، وللصائم بعد الزوال","q":"ما حكم السواك؟ ومتى يتأكد؟ وهل يُكره للصائم بعد الزوال؟","short":"السواك سنة مؤكدة باتفاق أهل العلم، ويتأكد عند الوضوء والصلاة والقيام من النوم وتغيّر الفم ودخول البيت؛ وهو مستحب للصائم في أول النهار وآخره على الراجح، وهو قول الجمهور، وكرهه الشافعي في المشهور عنه بعد الزوال.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي ـ أَوْ عَلَى النَّاسِ ـ لأَمَرْتُهُمْ بِالسِّوَاكِ مَعَ كُلِّ صَلاَةٍ»","src":"رواه البخاري ٨٨٧، ومسلم ٢٥٢","links":[{"book":"mt_bukhari","num":887,"id":"h887"},{"book":"mt_muslim","num":252,"id":"h252"}]},{"t":"quote","text":"عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ «السِّوَاكُ مَطْهَرَةٌ لِلْفَمِ مَرْضَاةٌ لِلرَّبِّ»","src":"رواه النسائي ٥","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_nasai","num":5,"id":"h5"}]},{"t":"h","text":"حكمه"},{"t":"quote","text":"أَكْثَرُ أَهْلِ الْعِلْمِ يَرَوْنَ السِّوَاكَ سُنَّةً غَيْرَ وَاجِبٍ، وَلَا نَعْلَمُ أَحَدًا قَالَ بِوُجُوبِهِ إلَّا إِسْحَاقَ وَدَاوُد؛ لِأَنَّهُ مَأْمُورٌ بِهِ، وَالْأَمْرُ يَقْتَضِي الْوُجُوبَ. وَقَدْ رَوَى أَبُو دَاوُد بِإِسْنَادِهِ، «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَمَرَ بِالْوُضُوءِ عِنْدَ كُلِّ صَلَاةٍ طَاهِرًا وَغَيْرَ طَاهِرٍ، فَلَمَّا شَقَّ ذَلِكَ عَلَيْهِ أَمَرَ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ» . وَلَنَا قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتهمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ» . مُتَّفَقٌ عَلَيْهِ، يَعْنِي لَأَمَرْتهمْ أَمْرَ إيجَابٍ؛ لِأَنَّ الْمَشَقَّةَ إنَّمَا تَلْحَقُ بِالْإِيجَابِ لَا بِالنَّدْبِ، وَهَذَا يَدُلُّ عَلَى أَنَّ الْأَمْرَ فِي حَدِيثِهِمْ أَمْرُ نَدْبٍ وَاسْتِحْبَابٍ، وَيَحْتَمِلُ أَنْ يَكُونَ ذَلِكَ وَاجِبًا فِي حَقِّ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - عَلَى الْخُصُوصِ، جَمْعًا بَيْنَ الْخَبَرَيْنِ، وَاتَّفَقَ أَهْلُ الْعِلْمِ عَلَى أَنَّهُ سُنَّةٌ مُؤَكَّدَةٌ، لِحَثِّ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَمُوَاظَبَتِهِ عَلَيْهِ، وَتَرْغِيبِهِ فِيهِ وَنَدْبِهِ إلَيْهِ، وَتَسْمِيَتِهِ إيَّاهُ مِنْ الْفِطْرَةِ فِيمَا رَوَيْنَا مِنْ الْحَدِيثِ","src":"المغني","loc":"١/٧١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَيَتَأَكَّدُ اسْتِحْبَابُهُ فِي مَوَاضِعَ ثَلَاثَةٍ: عِنْدَ الصَّلَاةِ؛ لِلْخَبَرِ الْأَوَّلِ. وَعِنْدَ الْقِيَامِ مِنْ النَّوْمِ؛ لِمَا رَوَى حُذَيْفَةُ، قَالَ: كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إذَا قَامَ مِنْ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ. مُتَّفَقٌ عَلَيْهِ، يَعْنِي: يَغْسِلُهُ، يُقَالُ: شَاصَهُ، يَشُوصُهُ، وَمَاصَهُ: إذَا غَسَلَهُ، وَعَنْ عَائِشَةَ، - رَضِيَ اللَّهُ عَنْهَا - قَالَتْ: «كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَا يَرْقُدُ مِنْ لَيْلٍ أَوْ نَهَارٍ فَيَسْتَيْقِظُ إلَّا تَسَوَّكَ قَبْلَ أَنْ يَتَوَضَّأَ.» رَوَاهُ أَبُو دَاوُد؛ وَلِأَنَّهُ إذَا نَامَ يَنْطَبِقُ فُوهُ فَتَتَغَيَّرُ رَائِحَتُهُ. وَعِنْدَ تَغَيُّرِ رَائِحَةِ فِيهِ بِمَأْكُولٍ أَوْ غَيْرِهِ؛ وَلِأَنَّ السِّوَاكَ مَشْرُوعٌ لِإِزَالَةِ رَائِحَتِهِ وَتَطْيِيبِهِ","src":"المغني","loc":"١/٧١","pre":"وقال:"},{"t":"h","text":"السواك للصائم بعد الزوال"},{"t":"qawl","label":"القول الأول","text":"يُكره للصائم بعد الزوال، وهو قول الشافعي في المشهور عنه، وإسحاق وأبي ثور، وإحدى الروايتين عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"لا يُكره، بل يُستحب في أول النهار وآخره، وهو قول مالك وأصحاب الرأي، والرواية الأخرى عن أحمد."},{"t":"quote","text":"قَالَ ابْنُ عَقِيلٍ لَا يَخْتَلِفُ الْمَذْهَبُ أَنَّهُ لَا يُسْتَحَبُّ لِلصَّائِمِ السِّوَاكُ بَعْدَ الزَّوَالِ، وَهَلْ يُكْرَهُ؟ عَلَى رِوَايَتَيْنِ: إحْدَاهُمَا يُكْرَهُ، وَهُوَ قَوْلُ الشَّافِعِيِّ، وَإِسْحَاقَ وَأَبِي ثَوْرٍ وَرُوِيَ ذَلِكَ عَنْ عُمَرَ وَعَطَاءٍ وَمُجَاهِدٍ لِمَا رُوِيَ عَنْ عُمَرَ - رَضِيَ اللَّهُ عَنْهُ - أَنَّهُ قَالَ: يَسْتَاكُ مَا بَيْنَهُ وَبَيْنَ الظُّهْرِ، وَلَا يَسْتَاكُ بَعْدَ ذَلِكَ. وَلِأَنَّ السِّوَاكَ إنَّمَا اُسْتُحِبَّ لِإِزَالَةِ رَائِحَةِ الْفَمِ، وَقَدْ قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ» . قَالَ التِّرْمِذِيُّ: هَذَا حَدِيثٌ حَسَنٌ","src":"المغني","loc":"١/٧٢","pre":"قال ابن قدامة:"},{"t":"quote","text":"لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ","src":"رواه البخاري ١٨٩٤، ومسلم ١١٥١","pre":"ودليل من كرهه قوله ﷺ:","links":[{"book":"mt_bukhari","num":1894,"id":"h1894"},{"book":"mt_muslim","num":1151,"id":"h1151"}]},{"t":"quote","text":"عَنْ الشَّافِعِيِّ رَحِمَهُ اللَّهُ أَنَّهُ لَمْ يَرَ بِالسِّوَاكِ لِلصَّائِمِ بَأْسًا أَوَّلَ النَّهَارِ وَآخِرَهُ","src":"المجموع","loc":"١/٢٧٦","pre":"وقال النووي الشافعي في «المجموع»: حكى أبو عيسى الترمذي في جامعه في كتاب الصيام"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"كما يشرع استعمال السواك للصائم في أول النهار وآخره، وذهب بعض أهل العلم إلى كراهة السواك بعد الزوال، وهو قول مرجوح، والصواب عدم الكراهة","src":"مجموع فتاوى ابن باز","loc":"١٥/٢٦١","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"وَقَدْ نَقَلَ التِّرْمِذِيُّ أَنَّ الشَّافِعِيَّ قَالَ: لَا بَأْسَ بِالسِّوَاكِ لِلصَّائِمِ أَوَّلَ النَّهَارِ وَآخِرَهُ. وَاخْتَارَهُ جَمَاعَةٌ مِنْ أَصْحَابِهِ مِنْهُمْ: أَبُو شَامَةَ وَابْنُ عَبْدِ السَّلَامِ وَالنَّوَوِيُّ وَالْمُزَنِيِّ","src":"نيل الأوطار","loc":"١/١٣٩","pre":"الراجح استحبابه في أول النهار وآخره؛ لعموم الأحاديث. وقد نقل عن الشافعي نفسه ما يوافق ذلك؛ قال الشوكاني:"},{"t":"quote","text":"وَقَوْلُ أَبِي هُرَيْرَةَ مَعَ كَوْنِهِ لَا يَدُلُّ عَلَى الْمَطْلُوبِ لَا حُجَّةَ فِيهِ عَلَى أَنَّ فِيهِ عُمَرَ بْنَ قَيْسٍ وَهُوَ مَتْرُوكٌ، وَكَذَلِكَ حَدِيثُ عَلِيٍّ مَعَ ضَعْفِهِ لَمْ يُصَرِّحْ فِيهِ بِالرَّفْعِ، فَالْحَقُّ أَنَّهُ يُسْتَحَبُّ السِّوَاكُ لِلصَّائِمِ أَوَّلَ النَّهَارِ وَآخِرَهُ وَهُوَ مَذْهَبُ جُمْهُورِ الْأَئِمَّةِ","src":"نيل الأوطار","loc":"١/١٣٩","pre":"ثم قال:"},{"t":"tanbih","items":[{"t":"quote","text":"وَإِنْ اسْتَاكَ بِأُصْبُعِهِ أَوْ خِرْقَةٍ، فَقَدْ قِيلَ: لَا يُصِيبُ السُّنَّةَ؛ لِأَنَّ الشَّرْعَ لَمْ يَرِدْ بِهِ، وَلَا يَحْصُلُ الْإِنْقَاءُ بِهِ حُصُولَهُ بِالْعُودِ، وَالصَّحِيحُ أَنَّهُ يُصِيبُ بِقَدْرِ مَا يَحْصُلُ مِنْ الْإِنْقَاءِ، وَلَا يُتْرَكُ الْقَلِيلُ مِنْ السُّنَّةِ لِلْعَجْزِ عَنْ كَثِيرِهَا","src":"المغني","loc":"١/٧٢","pre":"من لم يجد السواك فاستاك بأصبعه أو بالفرشاة؛ قال ابن قدامة:"}]}],"refs":["البخاري ٨٨٧، ومسلم ٢٥٢","النسائي ٥","المغني (١/٧١)","المغني (١/٧٢)","البخاري ١٨٩٤، ومسلم ١١٥١","المجموع (١/٢٧٦)","مجموع فتاوى ابن باز (١٥/٢٦١)","نيل الأوطار (١/١٣٩)"],"related":["خصال الفطرة"],"alts":["السواك في رمضان","فرشاة الأسنان والسواك","السواك عند الصلاة"]},{"n":30,"bab":"الطهارة","sub":"الوضوء","title":"النية في الوضوء","q":"هل تشترط النية لصحة الوضوء؟ وهل يُتلفّظ بها؟","short":"النية شرط لصحة الوضوء عند جمهور العلماء: مالك والشافعي وأحمد؛ ولم يشترطها أبو حنيفة والثوري، مع قولهم إن الوضوء بلا نية لا يكون عبادة يُثاب عليها. والراجح اشتراطها، ومحلها القلب، فلا يُشرع التلفظ بها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى","src":"رواه البخاري ١","pre":"عن عمر بن الخطاب رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_bukhari","num":1,"id":"h1"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"النية شرط لصحة الوضوء، وهو مذهب مالك والشافعي وأحمد وأبي ثور وداود."},{"t":"qawl","label":"القول الثاني","text":"ليست بشرط في الوضوء بالماء، وإنما تشترط في التيمم، وهو مذهب أبي حنيفة والثوري."},{"t":"quote","text":"اخْتَلَفَ عُلَمَاءُ الْأَمْصَارِ هَلِ النِّيَّةُ شَرْطٌ فِي صِحَّةِ الْوُضُوءِ أَمْ لَا؟ بَعْدَ اتِّفَاقِهِمْ عَلَى اشْتِرَاطِ النِّيَّةِ فِي الْعِبَادَاتِ لِقَوْلِهِ تَعَالَى: {وَمَا أُمِرُوا إِلا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ} البينة: 5 . وَلِقَوْلِهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ» الْحَدِيثَ الْمَشْهُورَ.","src":"بداية المجتهد","loc":"١/١٥","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الصلاة عبادة، والعبادات توقيفية لا يشرع فيها إلا ما دل عليه القرآن الكريم أو السنة الصحيحة المطهرة، ولم يثبت عن النبي صلى الله عليه وسلم أنه تلفظ في صلاة فرضا كانت أم نافلة بالنية","src":"فتاوى اللجنة الدائمة","loc":"٦/٣٢٣","pre":"وجاء في فتاوى اللجنة الدائمة في التلفظ بالنية:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"وَلَنَا: مَا رَوَى عُمَرُ، عَنْ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهُ قَالَ «إنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى» . مُتَّفَقٌ عَلَيْهِ، فَنَفَى أَنْ يَكُونَ لَهُ عَمَلٌ شَرْعِيٌّ بِدُونِ النِّيَّةِ؛ وَلِأَنَّهَا طَهَارَةٌ عَنْ حَدَثٍ، فَلَمْ تَصِحَّ بِغَيْرِ نِيَّةٍ","src":"المغني","loc":"١/٨٢-٨٣","pre":"الراجح اشتراط النية؛ قال ابن قدامة:"},{"t":"p","text":"وقد قرّر الشيخ أنور شاه الكشميري من محققي الحنفية أن الوضوء بلا نية لا ينعقد عبادة، وأن من الوسائل ما تشترط فيه النية عندهم أيضًا كالتيمم؛ فقال في حكاية مذهبهم والجواب عن الحديث:"},{"t":"quote","text":"أما الكلام على مسائلهم فقال الحنفية: إن النية لا تُشترط في الوضوء، وقالوا بصحته بدونها. والحديثُ واردٌ عليهم، فقال بعضهم: إن الحديث إنما ورد في العبادات دون القُرُبات والطاعات، ونحن نلتزم أن الوضوء بدون النية لا ينعقدُ عبادة. أما أنه لا يصلح لكونه مفتاحًا للصلاة، فلا يدل عليه الحديث أصلًا","src":"فيض الباري","loc":"١/٨٢"},{"t":"p","text":"فالمسلم يحرص على استحضار النية في وضوئه، فيجمع بين صحة الوضوء عند الجميع وحصول الثواب."},{"t":"tanbih","items":[{"t":"p","text":"النية عمل القلب، وهي قصد رفع الحدث أو استباحة الصلاة؛ فمن قام إلى الوضوء قاصدًا له فقد نوى، ولا يُشرع التلفّظ بها."}]}],"refs":["البخاري ١","بداية المجتهد (١/١٥)","فتاوى اللجنة الدائمة (٦/٣٢٣)","المغني (١/٨٢-٨٣)","فيض الباري (١/٨٢)"],"related":["التسمية عند الوضوء"],"alts":["نية الوضوء","التلفظ بالنية","الوضوء بلا نية"]},{"n":31,"bab":"الطهارة","sub":"الوضوء","title":"التسمية عند الوضوء","q":"ما حكم قول «بسم الله» عند الوضوء؟ ومن نسيها هل يعيد وضوءه؟","short":"التسمية عند الوضوء سنة عند جمهور العلماء، وأوجبها أحمد في رواية وإسحاق، ومال إلى وجوبها ابن الهمام من الحنفية؛ وحديثها ضعيف الإسناد، لكن له طرق كثيرة حسّنه بمجموعها جماعة من أهل الحديث، فالراجح أنها سنة، ومن نسيها أو تركها فوضوؤه صحيح.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"لاَ وُضُوءَ لِمَنْ لَمْ يَذْكُرِ اسْمَ اللَّهِ عَلَيْهِ","src":"رواه الترمذي ٢٥، وأبو داود ١٠١، وابن ماجه ٣٩٧","pre":"روي عن النبي ﷺ أنه قال:","links":[{"book":"mt_tirmidhi","num":25,"id":"h25"},{"book":"mt_abudawud","num":101,"id":"h101"},{"book":"mt_ibnmajah","num":397,"id":"h397"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنها سنة، وهو قول مالك والشافعي وأصحاب الرأي والثوري، وظاهر مذهب أحمد."},{"t":"qawl","label":"القول الثاني","text":"أنها واجبة، وهو رواية عن أحمد، وقول الحسن وإسحاق."},{"t":"quote","text":"ظَاهِرُ مَذْهَبِ أَحْمَدَ - رَضِيَ اللَّهُ عَنْهُ -: أَنَّ التَّسْمِيَةَ مَسْنُونَةٌ فِي طَهَارَةِ الْأَحْدَاثِ كُلِّهَا. رَوَاهُ عَنْهُ جَمَاعَةٌ مِنْ أَصْحَابِهِ. وَقَالَ الْخَلَّالُ الَّذِي اسْتَقَرَّتْ الرِّوَايَاتُ عَنْهُ أَنَّهُ لَا بَأْسَ بِهِ. يَعْنِي إذَا تَرَكَ التَّسْمِيَةَ. وَهَذَا قَوْلُ الثَّوْرِيِّ وَمَالِكٍ وَالشَّافِعِيِّ وَأَبِي عُبَيْدَةَ، وَابْنِ الْمُنْذِرِ وَأَصْحَابِ الرَّأْيِ. وَعَنْهُ أَنَّهَا وَاجِبَةٌ فِيهَا كُلِّهَا؛ الْوُضُوءِ، وَالْغُسْلِ، وَالتَّيَمُّمِ. وَهُوَ اخْتِيَارُ أَبِي بَكْرٍ وَمَذْهَبُ الْحَسَنِ وَإِسْحَاقَ لِمَا رُوِيَ أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهِ» . رَوَاهُ أَبُو دَاوُد، وَالتِّرْمِذِيُّ، رَوَاهُ عَنْ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - جَمَاعَةٌ مِنْ أَصْحَابِهِ. قَالَ الْإِمَامُ أَحْمَدُ: حَدِيثُ أَبِي سَعِيدٍ أَحْسَنُ حَدِيثٍ فِي هَذَا الْبَابِ. وَقَالَ التِّرْمِذِيُّ: حَدِيثُ سَعِيدِ بْنِ زَيْدٍ أَحْسَنُ. وَهَذَا نَفْيٌ فِي نَكِرَةٍ يَقْتَضِي أَنْ لَا يَصِحَّ وُضُوءُهُ بِدُونِ التَّسْمِيَةِ. وَوَجْهُ الرِّوَايَةِ الْأُولَى: أَنَّهَا طَهَارَةٌ، فَلَا تَفْتَقِرُ إلَى التَّسْمِيَةِ، كَالطَّهَارَةِ مِنْ النَّجَاسَةِ، أَوْ عِبَادَةٌ، فَلَا تَجِبُ فِيهَا التَّسْمِيَةُ كَسَائِرِ الْعِبَادَاتِ؛ وَلِأَنَّ الْأَصْلَ عَدَمُ الْوُجُوبِ، وَإِنَّمَا ثَبَتَ بِالشَّرْعِ وَالْأَحَادِيثِ، قَالَ أَحْمَدُ: لَيْسَ يَثْبُتُ فِي هَذَا حَدِيثٌ، وَلَا أَعْلَمُ فِيهَا حَدِيثًا لَهُ إسْنَادٌ جَيِّدٌ","src":"المغني","loc":"١/٧٦-٧٧","pre":"قال ابن قدامة:"},{"t":"quote","text":"نسب إلى داود الظاهري وجوب التسمية عند الوضوء وكذلك رواية عن أحمد بن حنبل، أقول: لم يرد الوجوب عن أحمد، وتفرد بالوجوب منا الشيخ ابن الهمام وجد على تفرده، وكذلك تفرد في بعض المسائل، وقال تلميذه العلامة قاسم بن قطلوبفا: لا تقبل تفردات شيخنا","src":"العرف الشذي","loc":"١/٦٩","pre":"وقال الشيخ أنور شاه الكشميري في بيان من أوجبها:"},{"t":"quote","text":"وَلَنَا) أَنَّ آيَةَ الْوُضُوءِ مُطْلَقَةٌ عَنْ شَرْطِ التَّسْمِيَةِ فَلَا تُقَيَّدُ إلَّا بِدَلِيلٍ صَالِحٍ لِلتَّقْيِيدِ","src":"بدائع الصنائع","loc":"١/٢٠","pre":"وقال الكاساني الحنفي في «بدائع الصنائع» في عدّ التسمية من سنن الوضوء:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"إلا التسمية عند الوضوء، فإنه يأتي بها إذا لم يتيسر الوضوء خارج الحمام؛ لأنها واجبة عند بعض أهل العلم، وسنة مؤكدة عند الجمهور","src":"مجموع فتاوى ابن باز","loc":"٥/٤٠٨","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"تجب التسمية عند الوضوء ومن توضأ بدون تسمية ناسيا أو جاهلا بالحكم الشرعي فوضوءه صحيح، ومن تركها عمدا فوضوءه باطل على الصحيح من قولي العلماء","src":"فتاوى اللجنة الدائمة","loc":"٥/٢١٩","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"quote","text":"هَذَا الحَدِيث لم يجمع أهل الْمعرفَة بِالْحَدِيثِ على تَصْحِيحه وعَلى تَقْدِير صِحَّته، فَهُوَ من الْمَوَاضِع الَّتِي اخْتلف فِيهَا طَرِيق التلقي من النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فقد اسْتمرّ الْمُسلمُونَ يحكون وضوء النَّبِي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ويعلمون النَّاس، وَلَا يذكرُونَ التَّسْمِيَة حَتَّى ظهر زمَان أهل الحَدِيث","src":"حجة الله البالغة","loc":"١/٢٩٧","pre":"الراجح أنها سنة؛ لأن حديثها ضعيف الإسناد وإن كانت له طرق كثيرة حسّنه بمجموعها جماعة من أهل الحديث، ولأن الذين وصفوا وضوء النبي ﷺ لم يذكروها. قال الشاه ولي الله الدهلوي:"},{"t":"quote","text":"وَإِنْ صَحَّ ذَلِكَ فَيُحْمَلُ عَلَى تَأْكِيدِ الِاسْتِحْبَابِ وَنَفْيِ الْكَمَالِ بِدُونِهَا، كَقَوْلِهِ: «لَا صَلَاةَ لِجَارِ الْمَسْجِدِ إلَّا فِي الْمَسْجِدِ»","src":"المغني","loc":"١/٧٧","pre":"وقال ابن قدامة في الجمع:"},{"t":"tanbih","items":[{"t":"quote","text":"سَأَلْت أَحْمَدَ بْنَ حَنْبَلٍ: إذَا نَسِيَ التَّسْمِيَةَ فِي الْوُضُوءِ؟ قَالَ: أَرْجُو أَنْ لَا يَكُونَ عَلَيْهِ شَيْءٌ. وَهَذَا قَوْلُ إِسْحَاقَ","src":"المغني","loc":"١/٧٧","pre":"ومن نسيها فلا شيء عليه حتى عند من أوجبها؛ قال أبو داود:"}]}],"refs":["الترمذي ٢٥، وأبو داود ١٠١، وابن ماجه ٣٩٧","المغني (١/٧٦-٧٧)","العرف الشذي (١/٦٩)","بدائع الصنائع (١/٢٠)","مجموع فتاوى ابن باز (٥/٤٠٨)","فتاوى اللجنة الدائمة (٥/٢١٩)","حجة الله البالغة (١/٢٩٧)","المغني (١/٧٧)"],"related":["النية في الوضوء"],"alts":["البسملة في الوضوء","نسيان التسمية","بسم الله قبل الوضوء"]},{"n":32,"bab":"الطهارة","sub":"الوضوء","title":"المضمضة والاستنشاق في الوضوء","q":"هل المضمضة والاستنشاق واجبان في الوضوء أو سنتان؟ وما حكم من تركهما؟","short":"اختلف العلماء فيهما على أقوال: فهما سنتان في الوضوء عند مالك والشافعي وأبي حنيفة، وواجبان عند أحمد في المشهور، وأوجب جماعة الاستنشاق وحده. والأحوط ألا يتركهما المتوضئ؛ لمواظبة النبي ﷺ عليهما وأمره بهما.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنْ أَبِي هُرَيْرَةَ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: «إِذَا اسْتَجْمَرَ أَحَدُكُمْ فَلْيَسْتَجْمِرْ وِتْرًا، وَإِذَا تَوَضَّأَ أَحَدُكُمْ فَلِيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَنْتَثِرْ»","src":"رواه مسلم ٢٣٧، وأبو داود ١٤٠، والنسائي ٨٦","links":[{"book":"mt_muslim","num":237,"id":"h237"},{"book":"mt_abudawud","num":140,"id":"h140"},{"book":"mt_nasai","num":86,"id":"h86"}]},{"t":"quote","text":"فَدَعَا بِمَاءٍ، فَأَفْرَغَ عَلَى يَدَيْهِ فَغَسَلَ يَدَهُ مَرَّتَيْنِ، ثُمَّ مَضْمَضَ وَاسْتَنْثَرَ ثَلاَثًا، ثُمَّ غَسَلَ وَجْهَهُ ثَلاَثًا، ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ، ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ، بَدَأَ بِمُقَدَّمِ رَأْسِهِ، حَتَّى ذَهَبَ بِهِمَا إِلَى قَفَاهُ، ثُمَّ رَدَّهُمَا إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ، ثُمَّ غَسَلَ رِجْلَيْهِ","src":"رواه البخاري ١٨٥","pre":"وفي صفة وضوء النبي ﷺ عن عبد الله بن زيد رضي الله عنه:","links":[{"book":"mt_bukhari","num":185,"id":"h185"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أنهما سنتان في الوضوء والغسل، وهو قول مالك والشافعي."},{"t":"qawl","label":"القول الثاني","text":"أنهما واجبان في الوضوء والغسل، وهو المشهور عن أحمد، وقول ابن المبارك وابن أبي ليلى وإسحاق."},{"t":"qawl","label":"القول الثالث","text":"أنهما سنتان في الوضوء، واجبتان في الغسل، وهو مذهب الحنفية والثوري، ورواية عن أحمد."},{"t":"qawl","label":"القول الرابع","text":"أن الاستنشاق واجب والمضمضة سنة، وهو قول أبي ثور وأبي عبيد وجماعة من أهل الظاهر، ورواية عن أحمد."},{"t":"quote","text":"يَعْنِي أَنَّ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ وَاجِبَانِ فِي الطَّهَارَتَيْنِ جَمِيعًا: الْغُسْلُ، وَالْوُضُوءُ؛ فَإِنَّ غَسْلَ الْوَجْهِ وَاجِبٌ فِيهِمَا. هَذَا الْمَشْهُورُ فِي الْمَذْهَبِ، وَبِهِ قَالَ ابْنُ الْمُبَارَكِ وَابْنُ أَبِي لَيْلَى وَإِسْحَاقُ وَحُكِيَ عَنْ عَطَاءٍ وَرُوِيَ عَنْ أَحْمَدَ رِوَايَةٌ أُخْرَى فِي الِاسْتِنْشَاقِ وَحْدَهُ أَنَّهُ وَاجِبٌ. قَالَ الْقَاضِي: الِاسْتِنْشَاقُ وَاجِبٌ فِي الطَّهَارَتَيْنِ، رِوَايَةً وَاحِدَةً، وَبِهِ قَالَ أَبُو عُبَيْدٍ وَأَبُو ثَوْرٍ وَابْنُ الْمُنْذِرِ؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «مَنْ تَوَضَّأَ فَلْيَسْتَنْثِرْ» . وَفِي رِوَايَةٍ قَالَ: «إذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ مَاءً ثُمَّ لِيَسْتَنْثِرْ» . مُتَّفَقٌ عَلَيْهِ. وَلِمُسْلِمٍ: «مَنْ تَوَضَّأَ فَلْيَسْتَنْشِقْ» . وَعَنْ ابْنِ عَبَّاسٍ، مَرْفُوعًا «اسْتَنْثِرُوا مَرَّتَيْنِ بَالِغَتَيْنِ أَوْ ثَلَاثًا» . وَهَذَا أَمْرٌ يَقْتَضِي الْوُجُوبَ؛ وَلِأَنَّ الْأَنْفَ لَا يَزَالُ مَفْتُوحًا، وَلَيْسَ لَهُ غِطَاءٌ يَسْتُرُهُ، بِخِلَافِ الْفَمِ. وَقَالَ غَيْرُ الْقَاضِي، عَنْ أَحْمَدَ رِوَايَةً أُخْرَى: إنَّ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ وَاجِبَانِ فِي الْكُبْرَى، مَسْنُونَانِ فِي الصُّغْرَى. وَهَذَا مَذْهَبُ الثَّوْرِيِّ وَأَصْحَابِ الرَّأْيِ؛ لِأَنَّ الْكُبْرَى يَجِبُ فِيهَا غَسْلُ كُلِّ مَا أَمْكَنَ مِنْ الْبَدَنِ كَبَوَاطِنِ الشُّعُورِ الْكَثِيفَةِ، وَلَا يَمْسَحُ فِيهَا عَنْ الْحَوَائِلِ، فَوَجَبَا فِيهَا، بِخِلَافِ الصُّغْرَى. وَقَالَ مَالِكٌ وَالشَّافِعِيُّ لَا يَجِبَانِ فِي الطَّهَارَتَيْنِ، وَإِنَّمَا هُمَا مَسْنُونَانِ فِيهِمَا","src":"المغني","loc":"١/٨٨","pre":"قال ابن قدامة:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وَسَبَبُ اخْتِلَافِهِمْ فِي كَوْنِهَا فَرْضًا أَوْ سُنَّةً: اخْتِلَافُهُمْ فِي السُّنَنِ الْوَارِدَةِ فِي ذَلِكَ، هَلْ هِيَ زِيَادَةٌ تَقْتَضِي مُعَارَضَةَ آيَةِ الْوُضُوءِ أَوْ لَا تَقْتَضِي ذَلِكَ؟","src":"بداية المجتهد","loc":"١/١٧","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأحوط للمسلم ألا يترك المضمضة والاستنشاق؛ فإن كل من وصف وضوء النبي ﷺ ذكرهما، وقد أمر بالاستنشاق أمرًا صريحًا. ومن تركهما ناسيًا فوضوؤه صحيح عند الجمهور."}],"refs":["مسلم ٢٣٧، وأبو داود ١٤٠، والنسائي ٨٦","البخاري ١٨٥","المغني (١/٨٨)","بداية المجتهد (١/١٧)"],"related":["النية في الوضوء","خصال الفطرة"],"alts":["المضمضة في الوضوء","الاستنشاق","ترك المضمضة"]},{"n":33,"bab":"الطهارة","sub":"الوضوء","title":"القدر المجزئ في مسح الرأس، والمسح على العمامة","q":"هل يجب مسح الرأس كله في الوضوء أو يكفي بعضه؟ وهل يجوز المسح على العمامة أو غطاء الرأس؟","short":"اتفق العلماء على أن مسح الرأس فرض، واختلفوا في قدره: فأوجب مالك وأحمد مسحه كله، واكتفى الشافعي بأقل ما يقع عليه اسم المسح، وأبو حنيفة بالربع. والسنة مسحه كله، وإن مسح الناصية وأتمّ على العمامة أجزأه؛ وأجاز أحمد المسح على العمامة، ومنعه الأئمة الثلاثة.","body":[{"t":"h","text":"صفة مسح الرأس في السنة"},{"t":"quote","text":"ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ، فَأَقْبَلَ بِهِمَا وَأَدْبَرَ، بَدَأَ بِمُقَدَّمِ رَأْسِهِ، حَتَّى ذَهَبَ بِهِمَا إِلَى قَفَاهُ، ثُمَّ رَدَّهُمَا إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ","src":"رواه البخاري ١٨٥، ومسلم ٢٣٥","pre":"عن عبد الله بن زيد رضي الله عنه في صفة وضوء النبي ﷺ:","links":[{"book":"mt_bukhari","num":185,"id":"h185"},{"book":"mt_muslim","num":235,"id":"h235"}]},{"t":"h","text":"المسألة الأولى: القدر المجزئ"},{"t":"qawl","label":"القول الأول","text":"يجب مسح الرأس كله، وهو مذهب مالك وأحمد."},{"t":"qawl","label":"القول الثاني","text":"يجزئ مسح بعضه؛ ثم اختلف أصحابه: فلم يحدّه الشافعي بحدّ، وحدّه أبو حنيفة بالربع، وحدّه بعض المالكية بالثلث أو الثلثين."},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ مَسْحَ الرَّأْسِ مِنْ فُرُوضِ الْوُضُوءِ، وَاخْتَلَفُوا فِي الْقَدْرِ الْمُجْزِئِ مِنْهُ.","src":"بداية المجتهد","loc":"١/١٩","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: المسح على العمامة"},{"t":"quote","text":"رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يَمْسَحُ عَلَى عِمَامَتِهِ وَخُفَّيْهِ","src":"رواه البخاري ٢٠٥","pre":"عن عمرو بن أمية الضمري رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":205,"id":"h205"}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"السنة مسح الرأس كله؛ لأنه صفة وضوء النبي ﷺ الذي نقله الصحابة. ومن مسح بعضه أجزأه عند الحنفية والشافعية، والأحوط ألا يقتصر على ذلك. وقد ثبت عن النبي ﷺ المسح على العمامة، وعلى الناصية مع العمامة، في الصحيحين؛ فمن احتاج إليه — لبرد أو مشقة في نزعها — فله فيه سنة ثابتة، ومسح الناصية مع العمامة يجمع بين النص والخروج من الخلاف."}],"refs":["البخاري ١٨٥، ومسلم ٢٣٥","بداية المجتهد (١/١٩)","البخاري ٢٠٥","بداية المجتهد (١/٢٠-٢١)"],"related":["النية في الوضوء","الترتيب والموالاة في الوضوء"],"alts":["مسح بعض الرأس","المسح على الطاقية","المسح على الحجاب"]},{"n":34,"bab":"الطهارة","sub":"الوضوء","title":"الترتيب والموالاة في الوضوء","q":"من قدّم عضوًا على عضو في الوضوء، أو فرّق بين أعضائه فجفّ الماء، هل يصح وضوؤه؟","short":"الترتيب بين أعضاء الوضوء كما في الآية فرض عند الشافعي وأحمد، وسنة عند أبي حنيفة ومالك؛ والموالاة واجبة عند مالك وأحمد، وليست بواجبة عند أبي حنيفة والشافعي. والأحوط الترتيب والموالاة؛ لأن النبي ﷺ لم يتوضأ إلا مرتبًا متواليًا، وأمر من ترك لمعة من قدمه بإعادة الوضوء.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ رَجُلًا تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفُرٍ عَلَى قَدَمِهِ فَأَبْصَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «ارْجِعْ فَأَحْسِنْ وُضُوءَكَ» فَرَجَعَ، ثُمَّ صَلَّى","src":"رواه مسلم ٢٤٣","pre":"عن عمر بن الخطاب رضي الله عنه:","links":[{"book":"mt_muslim","num":243,"id":"h243"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم رَأَى رَجُلاً يُصَلِّي وَفِي ظَهْرِ قَدَمِهِ لُمْعَةٌ قَدْرُ الدِّرْهَمِ لَمْ يُصِبْهَا الْمَاءُ فَأَمَرَهُ النَّبِيُّ صلى الله عليه وسلم أَنْ يُعِيدَ الْوُضُوءَ وَالصَّلاَةَ","src":"رواه أبو داود ١٧٥","pre":"وعن بعض أصحاب النبي ﷺ:","links":[{"book":"mt_abudawud","num":175,"id":"h175"}]},{"t":"h","text":"المسألة الأولى: الترتيب"},{"t":"qawl","label":"القول الأول","text":"أنه فرض، وهو قول الشافعي وأحمد وأبي عبيد."},{"t":"qawl","label":"القول الثاني","text":"أنه سنة، وهو قول أبي حنيفة والثوري وداود، والمشهور عند متأخري المالكية."},{"t":"quote","text":"اخْتَلَفُوا فِي وُجُوبِ تَرْتِيبِ أَفْعَالِ الْوُضُوءِ عَلَى نَسَقِ الْآيَةِ. فَقَالَ قَوْمٌ: هُوَ سُنَّةٌ، وَهُوَ الَّذِي حَكَاهُ الْمُتَأَخِّرُونَ مِنْ أَصْحَابِ مَالِكٍ عَنِ الْمَذْهَبِ، وَبِهِ قَالَ أَبُو حَنِيفَةَ وَالثَّوْرِيُّ وَدَاوُدُ. وَقَالَ قَوْمٌ: هُوَ فَرِيضَةٌ، وَبِهِ قَالَ الشَّافِعِيُّ وَأَحْمَدُ وَأَبُو عُبَيْدٍ.","src":"بداية المجتهد","loc":"١/٢٣","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: الموالاة"},{"t":"qawl","label":"القول الأول","text":"أنها واجبة، وهو قول مالك مع الذكر والقدرة، ومذهب أحمد."},{"t":"qawl","label":"القول الثاني","text":"أنها ليست بواجبة، وهو قول أبي حنيفة والشافعي."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الترتيب في الوضوء معناه أن تبدأ بما بدأ الله به، وقد بدأ الله بذكر غسل الوجه، ثم غسل اليدين، ثم مسح الرأس، ثم غسل الرجلين","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٤١","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن الترتيب والموالاة في الوضوء، فقال:"},{"t":"quote","text":"وأما الموالاة، فمعناها: أن لا يفرق بين أعضاء الوضوء بزمن يفصل بعضها عن بعض، مثال ذلك لو غسل وجهه، ثم أراد أن يغسل يديه ولكن تأخر، فإن الموالاة قد فاتت وحينئذ يجب عليه أن يعيد الوضوء من أوله","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٤١","pre":"وقال:"},{"t":"quote","text":"وجب على الرجل المذكور إعادة الوضوء؛ لأن الموالاة في الوضوء واجبة","src":"فتاوى اللجنة الدائمة","loc":"٥/٢٣١","pre":"وجاء في فتاوى اللجنة الدائمة فيمن فرّق وضوءه:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأحوط الترتيب والموالاة؛ لأن الله تعالى ذكر أعضاء الوضوء مرتبة، ولم يُنقل عن النبي ﷺ أنه توضأ إلا مرتبًا متواليًا، وقد أمر من ترك لمعة في قدمه بإعادة الوضوء والصلاة، ولو لم تكن الموالاة واجبة لأمره بغسل اللمعة وحدها. فمن فرّق بين أعضاء وضوئه يسيرًا، أو لعذر كانقطاع الماء، فوضوؤه صحيح."}],"refs":["مسلم ٢٤٣","أبو داود ١٧٥","بداية المجتهد (١/٢٣)","بداية المجتهد (١/٢٤)","مجموع فتاوى ابن عثيمين (١١/١٤١)","فتاوى اللجنة الدائمة (٥/٢٣١)"],"related":["النية في الوضوء","القدر المجزئ في مسح الرأس"],"alts":["نسيان عضو في الوضوء","تفريق الوضوء","جفاف الأعضاء أثناء الوضوء"]},{"n":35,"bab":"الطهارة","sub":"الوضوء","title":"ما يمنع وصول الماء إلى أعضاء الوضوء: طلاء الأظافر، والحناء، والدهان والعجين","q":"امرأة تضع طلاء الأظافر (المناكير)، فهل يصح وضوؤها؟ وما الفرق بينه وبين الحناء؟ ومن كان على يده دهان (بوية) أو عجين أو شمع، فماذا يفعل؟","short":"اتفق الفقهاء على أن استيعاب أعضاء الوضوء بالماء فرض، وأن ما كان له جِرم يمنع وصول الماء إلى البشرة، كالشمع والعجين والدهان وطلاء الأظافر، يجب إزالته قبل الوضوء، فإن توضأ مع بقائه لم يصح وضوؤه في الموضع الذي تحته. وأما ما كان لونًا لا جرم له، كالحناء بعد إزالة جرمها، فلا يمنع صحة الوضوء باتفاقهم. وعفا الحنفية والمالكية عن اليسير الذي يشق التحرز منه كالدرن والوسخ اليسير تحت الأظفار للضرورة.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى ٱلْمَرَافِقِ وَٱمْسَحُوا۟ بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى ٱلْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟ ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَـٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُۥ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ","ref":"المائدة: ٦"},{"t":"quote","text":"أَنَّ رَجُلًا تَوَضَّأَ فَتَرَكَ مَوْضِعَ ظُفُرٍ عَلَى قَدَمِهِ فَأَبْصَرَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: «ارْجِعْ فَأَحْسِنْ وُضُوءَكَ» فَرَجَعَ، ثُمَّ صَلَّى","src":"رواه مسلم ٢٤٣","pre":"عن عمر بن الخطاب رضي الله عنه:","links":[{"book":"mt_muslim","num":243,"id":"h243"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَصْلٌ: إذَا كَانَ تَحْتَ أَظْفَارِهِ وَسَخٌ يَمْنَعُ وُصُولَ الْمَاءِ إلَى مَا تَحْتَهُ، فَقَالَ ابْنُ عَقِيلٍ لَا تَصِحُّ طَهَارَتُهُ حَتَّى يُزِيلَهُ","src":"المغني","loc":"١/٩٢","pre":"قال ابن قدامة الحنبلي في «المغني»:"},{"t":"quote","text":"قَوْلُهُ: بِهِ يُفْتَى صَرَّحَ بِهِ فِي الْمُنْيَةِ عَنْ الذَّخِيرَةِ فِي مَسْأَلَةِ الْحِنَّاءِ وَالطِّينِ وَالدَّرَنِ مُعَلِّلًا بِالضَّرُورَةِ","src":"الدر المختار مع رد المحتار","loc":"١/١٥٤","pre":"وقال ابن عابدين الحنفي في «رد المحتار» في العفو عن يسير ما تحت الأظفار:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ما يسمى (المناكير) وهو شيء يوضع على الأظفار تستعمله المرأة وله قشرة، لا يجوز استعماله للمرأة إذا كانت تصلي لأنه يمنع وصول الماء في الطهارة، وكل شيء يمنع وصول الماء فإنه لا يجوز استعماله للمتوضئ، أو المغتسل","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٤٨","pre":"سئل الشيخ محمد بن صالح العثيمين رحمه الله عن وضوء من على أظافرها المناكير، فقال:"},{"t":"quote","text":"وأما من كانت لا تصلي كالحائض فلا حرج عليها إذا استعملته إلا أن يكون هذا الفعل من خصائص نساء الكفار فإنه لا يجوز لما فيه من التشبه بهم","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٤٨","pre":"وقال:"},{"t":"quote","text":"لا نعلم شيئا في هذا، لكن تركه أولى؛ لعدم الحاجة إليه، ولأنه قد يحول دون وصول الماء إلى البشرة عند الوضوء","src":"مجموع فتاوى ابن باز","loc":"١٠/٤٨","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن المناكير، فقال:"},{"t":"quote","text":"إذا كان في أعضاء الطهارة شيء يمنع وصول الماء إلى الأعضاء التي يجب تطهيرها، فإن الواجب عليك أن تحسب الحساب، وأن تتقدم في إزالة هذا المانع حتى يأتي الوقت، وقد زال وتوضأت وضوءاً صحيحاً","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٤٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله فيمن على يده دهان ونحوه:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يجب على المتوضئ أن يوصل الماء إلى جميع أعضاء الوضوء، فإن كان عليها ما له جرم يمنع وصول الماء، كطلاء الأظافر (المناكير)، والشمع، والعجين، والصمغ، والدهان (البوية)، واللاصق، وجب عليه إزالته قبل الوضوء؛ لأمر النبي ﷺ من ترك موضع ظفر من قدمه أن يرجع فيحسن وضوءه. فمن توضأ والمناكير على أظفارها لم يصح وضوؤها، ولا بد أن تزيله ثم تتوضأ."},{"t":"p","text":"وأما الحناء وصبغ الشعر ونحوهما مما هو لون فقط بعد إزالة جِرمه فلا يمنع صحة الوضوء ولا الغسل، وكذلك الوسخ اليسير تحت الأظفار الذي يشق التحرز منه معفو عنه عند كثير من العلماء رفعًا للحرج. ولا حرج على المرأة في وضع طلاء الأظافر وقت حيضها إذا أزالته قبل طهرها، ما لم يكن فيه تشبه بالكافرات. وتوجد اليوم أنواع من الطلاء يُذكر أنها تسمح بنفاذ الماء، فإن ثبت ذلك يقينًا بالتجربة الموثوقة فلا تمنع صحة الوضوء، والأحوط إزالتها."}],"refs":["مسلم ٢٤٣","المغني (١/٩٢)","الدر المختار مع رد المحتار (١/١٥٤)","مجموع فتاوى ابن عثيمين (١١/١٤٨)","مجموع فتاوى ابن باز (١٠/٤٨)","مجموع فتاوى ابن عثيمين (١١/١٤٦)"],"related":["الترتيب والموالاة في الوضوء","صفة الغسل الكامل والمجزئ، وحكم المضمضة والاستنشاق فيه، ونقض الضفائر"],"alts":["طلاء الأظافر والوضوء","المناكير","الوضوء مع الحناء","الحائل في الوضوء","البوية على اليد","المكياج والوضوء"]},{"n":36,"bab":"الطهارة","sub":"الوضوء","title":"تنشيف الأعضاء بعد الوضوء، والذكر بعده، وصلاة ركعتين","q":"هل يجوز أن أنشف أعضائي بالمنديل بعد الوضوء؟ وما الذكر المشروع بعد الوضوء؟ وهل تسن صلاة ركعتين بعده؟","short":"أجاز أكثر العلماء تنشيف الأعضاء بعد الوضوء والغسل، ومنهم أبو حنيفة ومالك وأحمد، وكرهه بعض السلف، ونقل عن الشافعية أن تركه أولى. واتفقوا على استحباب الذكر بعد الوضوء بالشهادتين، وعلى استحباب صلاة ركعتين بعده.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَأَتَيْتُهُ بِخِرْقَةٍ، فَلَمْ يُرِدْهَا، فَجَعَلَ يَنْفُضُ بِيَدِهِ","src":"رواه البخاري ٢٧٤","pre":"عن ميمونة رضي الله عنها في صفة غسل النبي ﷺ قالت:","links":[{"book":"mt_bukhari","num":274,"id":"h274"}]},{"t":"quote","text":"مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَقُومُ فَيَرْكَعُ رَكْعَتَيْنِ يُقْبِلُ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ إِلاَّ قَدْ أَوْجَبَ «. فَقُلْتُ بَخْ بَخْ مَا أَجْوَدَ هَذِهِ . فَقَالَ رَجُلٌ مِنْ بَيْنِ يَدَىَّ الَّتِي قَبْلَهَا يَا عُقْبَةُ أَجْوَدُ مِنْهَا . فَنَظَرْتُ فَإِذَا هُوَ عُمَرُ بْنُ الْخَطَّابِ فَقُلْتُ مَا هِيَ يَا أَبَا حَفْصٍ قَالَ إِنَّهُ قَالَ آنِفًا قَبْلَ أَنْ تَجِيءَ» مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ ثُمَّ يَقُولُ حِينَ يَفْرُغُ مِنْ وُضُوئِهِ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ إِلاَّ فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ","src":"رواه أبو داود ١٦٩","pre":"وعن عقبة بن عامر رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_abudawud","num":169,"id":"h169"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَصْلٌ: وَلَا بَأْسَ بِتَنْشِيفِ أَعْضَائِهِ بِالْمِنْدِيلِ مِنْ بَلَلِ الْوُضُوءِ وَالْغُسْلِ، قَالَ الْخَلَّالُ الْمَنْقُولُ عَنْ أَحْمَدَ أَنَّهُ لَا بَأْسَ بِالتَّنْشِيفِ بَعْدَ الْوُضُوءِ","src":"المغني","loc":"١/١٠٤","pre":"قال ابن قدامة الحنبلي في «المغني»:"},{"t":"quote","text":"وَقَالَ مَالِكٌ: لَا بَأْسَ بِالْمَسْحِ بِالْمِنْدِيلِ بَعْدَ الْوُضُوءِ","src":"المدونة","loc":"١/١٢٥","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"تنشيف الأعضاء لا باس به، لأن الأصل عدم المنع، والأصل في ما عدا العبادات من العقود والأفعال والأعيان الحل والإباحة حتى يقود دليل على المنع","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٥٣","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"لا بأس بتنشيف أعضاء الوضوء والغسل بالمنديل ونحوه، وهو قول أكثر العلماء؛ لأن الأصل الإباحة، ورَدُّ النبي ﷺ الخرقة في حديث ميمونة رضي الله عنها لا يدل على الكراهة، فقد يكون لعارض، وقد نفض الماء بيده، ومن تركه اقتداءً بذلك فحسن."},{"t":"p","text":"ويستحب أن يقول بعد الوضوء: «أشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدًا عبده ورسوله»، لحديث عقبة بن عامر عن عمر رضي الله عنهما في فتح أبواب الجنة الثمانية لمن قالها، ويستحب أن يصلي ركعتين بعد الوضوء يقبل عليهما بقلبه ووجهه؛ لحديث عقبة بن عامر رضي الله عنه."}],"refs":["البخاري ٢٧٤","أبو داود ١٦٩","المغني (١/١٠٤)","المدونة (١/١٢٥)","مجموع فتاوى ابن عثيمين (١١/١٥٣)"],"related":["النية في الوضوء","التسمية عند الوضوء"],"alts":["تنشيف الأعضاء بعد الوضوء","المنديل بعد الوضوء","الدعاء بعد الوضوء","ركعتا الوضوء","سنة الوضوء"]},{"n":37,"bab":"الطهارة","sub":"المسح على الخفين","title":"مشروعية المسح على الخفين وشرطه","q":"هل يجوز المسح على الخفين في الحضر والسفر؟ وما شرط ذلك؟","short":"المسح على الخفين جائز في الحضر والسفر عند جمهور العلماء، ومنهم الأئمة الأربعة، والأحاديث فيه متواترة؛ وشرطه أن يلبسهما على طهارة كاملة بالماء.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَالَ، ثُمَّ تَوَضَّأَ وَمَسَحَ عَلَى خُفَّيْهِ». قَالَ الْأَعْمَشُ: قَالَ إِبْرَاهِيمُ: «كَانَ يُعْجِبُهُمْ هَذَا الْحَدِيثُ لِأَنَّ إِسْلَامَ جَرِيرٍ، كَانَ بَعْدَ نُزُولِ الْمَائِدَةِ","src":"رواه مسلم ٢٧٢","pre":"عن جرير بن عبد الله رضي الله عنه قال:","links":[{"book":"mt_muslim","num":272,"id":"h272"}]},{"t":"quote","text":"قَالُوا إِنَّمَا كَانَ ذَلِكَ قَبْلَ نُزُولِ الْمَائِدَةِ . قَالَ مَا أَسْلَمْتُ إِلاَّ بَعْدَ نُزُولِ الْمَائِدَةِ","src":"رواه أبو داود ١٥٤","pre":"وفي رواية أبي داود أنهم قالوا لجرير:","links":[{"book":"mt_abudawud","num":154,"id":"h154"}]},{"t":"quote","text":"كُنْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم فِي سَفَرٍ، فَأَهْوَيْتُ لأَنْزِعَ خُفَّيْهِ فَقَالَ «دَعْهُمَا، فَإِنِّي أَدْخَلْتُهُمَا طَاهِرَتَيْنِ». فَمَسَحَ عَلَيْهِمَا","src":"رواه البخاري ٢٠٦، ومسلم ٢٧٤","pre":"وعن المغيرة بن شعبة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":206,"id":"h206"},{"book":"mt_muslim","num":274,"id":"h274"}]},{"t":"h","text":"أقوال العلماء في جوازه"},{"t":"qawl","label":"القول الأول","text":"جوازه في الحضر والسفر، وهو قول جمهور فقهاء الأمصار."},{"t":"qawl","label":"القول الثاني","text":"جوازه في السفر دون الحضر."},{"t":"qawl","label":"القول الثالث","text":"منعه مطلقًا."},{"t":"quote","text":"فَأَمَّا الْجَوَازُ، فَفِيهِ ثَلَاثَةُ أَقْوَالٍ: الْقَوْلُ الْمَشْهُورُ: أَنَّهُ جَائِزٌ عَلَى الْإِطْلَاقِ، وَبِهِ قَالَ جُمْهُورُ فُقَهَاءِ الْأَمْصَارِ. وَالْقَوْلُ الثَّانِي: جَوَازُهُ فِي السَّفَرِ دُونَ الْحَضَرِ. وَالْقَوْلُ الثَّالِثُ: مَنْعُ جَوَازِهِ بِإِطْلَاقٍ، وَهُوَ أَشَدُّهَا. وَالْأَقَاوِيلُ الثَّلَاثَةُ مَرْوِيَّةٌ عَنِ الصَّدْرِ الْأَوَّلِ وَعَنْ مَالِكٍ","src":"بداية المجتهد","loc":"١/٢٥","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فمن رحمة الله أن شرع لهذه الأمة المسح على الخفين في القرآن والسنة وقد تواترت الأحاديث عن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ في المسح على الخفين","src":"مجموع فتاوى ابن عثيمين","loc":"٧/٣٤٢","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح جواز المسح على الخفين في الحضر والسفر؛ لثبوت الأحاديث الصحيحة فيه، ولأن جريرًا رضي الله عنه أسلم بعد نزول سورة المائدة، فلا يصح القول بنسخه بآية الوضوء. والأحوط ألا يلبس الخف إلا بعد تمام وضوئه، فيخرج من الخلاف."}],"refs":["مسلم ٢٧٢","أبو داود ١٥٤","البخاري ٢٠٦، ومسلم ٢٧٤","بداية المجتهد (١/٢٥)","بداية المجتهد (١/٢٨)","مجموع فتاوى ابن عثيمين (٧/٣٤٢)"],"related":["مدة المسح على الخفين","المسح على الجوارب"],"alts":["المسح على الخف","المسح على البوت","المسح على الحذاء"]},{"n":38,"bab":"الطهارة","sub":"المسح على الخفين","title":"مدة المسح على الخفين","q":"كم مدة المسح على الخفين للمقيم والمسافر؟ ومتى تبدأ؟","short":"مدة المسح يوم وليلة للمقيم، وثلاثة أيام بلياليهن للمسافر، وهذا قول جمهور العلماء ومنهم أبو حنيفة والشافعي وأحمد؛ ولم يوقّت مالك. والراجح التوقيت؛ لحديث علي رضي الله عنه في صحيح مسلم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ لِلْمُسَافِرِ، وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ","src":"رواه مسلم ٢٧٦","pre":"عن علي بن أبي طالب رضي الله عنه قال:","links":[{"book":"mt_muslim","num":276,"id":"h276"}]},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَأْمُرُنَا إِذَا كُنَّا سَفْرًا أَنْ لاَ نَنْزِعَ خِفَافَنَا ثَلاَثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ إِلاَّ مِنْ جَنَابَةٍ وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ","src":"رواه الترمذي ٩٦، والنسائي ١٥٨","pre":"وعن صفوان بن عسال رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":96,"id":"h96"},{"book":"mt_nasai","num":158,"id":"h158"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"المسح مؤقت: يوم وليلة للمقيم، وثلاثة أيام بلياليهن للمسافر، وهو قول أبي حنيفة والشافعي وأحمد والثوري وابن المبارك وإسحاق."},{"t":"qawl","label":"القول الثاني","text":"المسح غير مؤقت، فيمسح ما لم ينزعهما أو تصبه جنابة، وهو قول مالك."},{"t":"quote","text":"وَهُوَ قَوْلُ أَكْثَرِ الْعُلَمَاءِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَالتَّابِعِينَ وَمَنْ بَعْدَهُمْ مِنَ الْفُقَهَاءِ مِثْلِ سُفْيَانَ الثَّوْرِيِّ وَابْنِ الْمُبَارَكِ وَالشَّافِعِيِّ وَأَحْمَدَ وَإِسْحَاقَ قَالُوا يَمْسَحُ الْمُقِيمُ يَوْمًا وَلَيْلَةً وَالْمُسَافِرُ ثَلاَثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ . قَالَ أَبُو عِيسَى وَقَدْ رُوِيَ عَنْ بَعْضِ أَهْلِ الْعِلْمِ أَنَّهُمْ لَمْ يُوَقِّتُوا فِي الْمَسْحِ عَلَى الْخُفَّيْنِ وَهُوَ قَوْلُ مَالِكِ بْنِ أَنَسٍ . قَالَ أَبُو عِيسَى وَالتَّوْقِيتُ أَصَحُّ","src":"رواه الترمذي ٩٦","pre":"قال الترمذي:","links":[{"book":"mt_tirmidhi","num":96,"id":"h96"}]},{"t":"quote","text":"وَالسَّبَبُ فِي اخْتِلَافِهِمْ: اخْتِلَافُ الْآثَارِ فِي ذَلِكَ، وَذَلِكَ أَنَّهُ وَرَدَ فِي ذَلِكَ ثَلَاثَةُ أَحَادِيثَ: أَحَدُهَا حَدِيثُ عَلِيٍّ عَنِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهُ قَالَ: «جَعَلَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - ثَلَاثَةَ أَيَّامٍ وَلَيَالِيهِنَّ لِلْمُسَافِرِ وَيَوْمًا وَلَيْلَةً لِلْمُقِيمِ» خَرَّجَهُ مُسْلِمٌ.","src":"بداية المجتهد","loc":"١/٢٧-٢٨","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المشروع للمسلم أن يمسح على الخفين أو الجوربين إذا لبسهما على طهارة، وكانا ساترين للقدمين مع الكعبين؛ يوما وليلة إن كان مقيما، وثلاثة أيام بلياليها إن كان مسافرا","src":"مجموع فتاوى ابن باز","loc":"١٠/١٠٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"وتبدأ مدة المسح: من بعد الحدث الذي بعد اللبس، فإن خلعهما وغسل رجليه بعد غسل الوجه واليدين والمسح على الرأس والأذنين فلا بأس، لكن ذلك خلاف السنة","src":"مجموع فتاوى ابن باز","loc":"١٠/١٠٧","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح التوقيت؛ لأن حديث علي رضي الله عنه صحيح صريح في مسلم، وحديث ترك التوقيت لا يثبت كما قال ابن عبد البر فيما نقله ابن رشد."},{"t":"tanbih","items":[{"t":"p","text":"تبدأ المدة عند جمهور القائلين بالتوقيت من أول حدث بعد لبس الخفين، وقيل: من أول مسح بعد الحدث، وهو رواية عن أحمد؛ والأحوط أن يحسبها من أول حدث."}]}],"refs":["مسلم ٢٧٦","الترمذي ٩٦، والنسائي ١٥٨","الترمذي ٩٦","بداية المجتهد (١/٢٧-٢٨)","مجموع فتاوى ابن باز (١٠/١٠٧)"],"related":["مشروعية المسح على الخفين وشرطه","ما يبطل المسح على الخفين"],"alts":["مدة المسح للمقيم","مدة المسح للمسافر","متى تبدأ مدة المسح"]},{"n":39,"bab":"الطهارة","sub":"المسح على الخفين","title":"محل المسح على الخفين وصفته","q":"هل يُمسح أعلى الخف أو أسفله؟ وكيف يكون المسح؟","short":"الواجب مسح أعلى الخف (ظاهره)، ولا يجب مسح أسفله؛ وهذا قول جمهور العلماء. واستحب مالك والشافعي مسح الأسفل مع الأعلى، ولم يستحبه أبو حنيفة. والسنة أن يمرّ يديه مبلولتين على ظاهر الخفين من أطراف الأصابع إلى الساق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَوْ كَانَ الدِّينُ بِالرَّأْىِ لَكَانَ أَسْفَلُ الْخُفِّ أَوْلَى بِالْمَسْحِ مِنْ أَعْلاَهُ وَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَمْسَحُ عَلَى ظَاهِرِ خُفَّيْهِ","src":"رواه أبو داود ١٦٢","pre":"عن علي بن أبي طالب رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":162,"id":"h162"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الواجب مسح الأعلى، ومسح الأسفل مستحب، وهو قول مالك والشافعي."},{"t":"qawl","label":"القول الثاني","text":"الواجب مسح الأعلى وحده، ولا يستحب مسح الأسفل، وهو قول أبي حنيفة وداود وسفيان."},{"t":"qawl","label":"القول الثالث","text":"يجب مسح الأعلى والأسفل، وهو قول ابن نافع من المالكية."},{"t":"quote","text":"وَالْمَسْحُ عَلَى ظَاهِرِهِمَا خُطُوطًا بِالْأَصَابِعِ، يَبْدَأُ مِنْ قِبَلِ الْأَصَابِعِ إلَى السَّاقِ لِحَدِيثِ الْمُغِيرَةِ - رَضِيَ اللَّهُ عَنْهُ - «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَضَعَ يَدَيْهِ عَلَى خُفَّيْهِ وَمَدَّهُمَا مِنْ الْأَصَابِعِ إلَى أَعْلَاهُمَا مَسْحَةً وَاحِدَةً»","src":"الهداية مع فتح القدير","loc":"١/١٤٨","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن المسح على ظاهر الخف؛ لحديث علي رضي الله عنه، ومن مسح الأسفل معه استحبابًا فلا حرج. ولا يكفي مسح الأسفل وحده."}],"refs":["أبو داود ١٦٢","الهداية مع فتح القدير (١/١٤٨)"],"related":["مدة المسح على الخفين"],"alts":["مسح أسفل الخف","كيفية المسح على الخف"]},{"n":40,"bab":"الطهارة","sub":"المسح على الخفين","title":"المسح على الجوارب","q":"هل يجوز المسح على الجوارب (الشُّرّاب) القطنية أو الصوفية بدل غسل القدمين؟","short":"يجوز المسح على الجوربين الصفيقين اللذين يستران القدم ويمكن المشي فيهما، وهو قول أحمد وصاحبَي أبي حنيفة، ورُوي رجوع أبي حنيفة إليه في آخر عمره؛ ومنعه مالك والشافعي إلا أن يكونا مجلّدين أو منعّلين. وأما الرقيقان اللذان يشفّان الماء فلا يُمسح عليهما بالاتفاق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ تَوَضَّأَ النَّبِيُّ صلى الله عليه وسلم وَمَسَحَ عَلَى الْجَوْرَبَيْنِ وَالنَّعْلَيْنِ","src":"رواه الترمذي ٩٩، وأبو داود ١٥٩، وابن ماجه ٥٥٩","links":[{"book":"mt_tirmidhi","num":99,"id":"h99"},{"book":"mt_abudawud","num":159,"id":"h159"},{"book":"mt_ibnmajah","num":559,"id":"h559"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يجوز المسح على الجوربين الصفيقين، وهو قول أحمد وأبي يوسف ومحمد والثوري وابن المبارك وإسحاق، ومرويّ عن جماعة من الصحابة."},{"t":"quote","text":"إنَّمَا يَجُوزُ الْمَسْحُ عَلَى الْجَوْرَبِ بِالشَّرْطَيْنِ اللَّذَيْنِ ذَكَرْنَاهُمَا فِي الْخُفِّ، أَحَدُهُمَا أَنْ يَكُونَ صَفِيقًا، لَا يَبْدُو مِنْهُ شَيْءٌ مِنْ الْقَدَمِ. الثَّانِي أَنْ يُمْكِنَ مُتَابَعَةُ الْمَشْيِ فِيهِ. هَذَا ظَاهِرُ كَلَامِ الْخِرَقِيِّ. قَالَ أَحْمَدُ فِي الْمَسْحِ عَلَى الْجَوْرَبَيْنِ بِغَيْرِ نَعْلٍ: إذَا كَانَ يَمْشِي عَلَيْهِمَا، وَيَثْبُتَانِ فِي رِجْلَيْهِ، فَلَا بَأْسَ. وَفِي مَوْضِعٍ قَالَ: يَمْسَحُ عَلَيْهِمَا إذَا ثَبَتَا فِي الْعَقِبِ. وَفِي مَوْضِعٍ قَالَ: إنْ كَانَ يَمْشِي فِيهِ فَلَا يَنْثَنِي، فَلَا بَأْسَ بِالْمَسْحِ عَلَيْهِ، فَإِنَّهُ إذَا انْثَنَى ظَهَرَ مَوْضِعُ الْوُضُوءِ. وَلَا يُعْتَبَرُ أَنْ يَكُونَا مُجَلَّدَيْنِ، قَالَ أَحْمَدُ: يُذْكَرُ الْمَسْحُ عَلَى الْجَوْرَبَيْنِ عَنْ سَبْعَةٍ، أَوْ ثَمَانِيَةٍ، مِنْ أَصْحَابِ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ","src":"المغني","loc":"١/٢١٥","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَقَالَ ابْنُ الْمُنْذِرِ: وَيُرْوَى إبَاحَةُ الْمَسْحِ عَلَى الْجَوْرَبَيْنِ عَنْ تِسْعَةٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -؛ عَلِيٍّ، وَعَمَّارٍ، وَابْنِ مَسْعُودٍ، وَأَنَسٍ، وَابْنِ عُمَرَ، وَالْبَرَاءِ، وَبِلَالٍ، وَابْنِ أَبِي أَوْفَى، وَسَهْلِ بْنِ سَعْدٍ، وَبِهِ قَالَ عَطَاءٌ، وَالْحَسَنُ وَسَعِيدُ بْنُ الْمُسَيِّبِ، وَالنَّخَعِيُّ، وَسَعِيدُ بْنُ جُبَيْرٍ، وَالْأَعْمَشُ، وَالثَّوْرِيُّ، وَالْحَسَنُ بْنُ صَالِحٍ، وَابْنُ الْمُبَارَكِ، وَإِسْحَاقُ، وَيَعْقُوبُ، وَمُحَمَّدٌ. وَقَالَ أَبُو حَنِيفَةَ، وَمَالِكٌ، وَالْأَوْزَاعِيُّ، وَمُجَاهِدٌ، وَعَمْرُو بْنُ دِينَارٍ، وَالْحَسَنُ بْنُ مُسْلِمٍ، وَالشَّافِعِيُّ: لَا يَجُوزُ الْمَسْحُ عَلَيْهِمَا، إلَّا أَنْ يُنْعَلَا؛ لِأَنَّهُمَا لَا يُمْكِنُ مُتَابَعَةُ الْمَشْيِ فِيهِمَا، فَلَمْ يَجُزْ الْمَسْحُ عَلَيْهِمَا، كَالرَّقِيقِينَ","src":"المغني","loc":"١/٢١٥","pre":"وقال:"},{"t":"qawl","label":"القول الثاني","text":"لا يجوز المسح عليهما إلا أن يكونا منعّلين أو مجلّدين، وهو قول مالك والشافعي، وكان قول أبي حنيفة أولًا."},{"t":"quote","text":"وَاخْتَلَفُوا فِي الْمَسْحِ عَلَى الْجَوْرَبَيْنِ فَأَجَازَ ذَلِكَ قَوْمٌ وَمَنَعَهُ قَوْمٌ. وَمِمَّنْ مَنَعَ ذَلِكَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو حَنِيفَةَ، وَمِمَّنْ أَجَازَ ذَلِكَ أَبُو يُوسُفَ وَمُحَمَّدٌ صَاحِبَا أَبِي حَنِيفَةَ وَسُفْيَانُ الثَّوْرِيُّ.","src":"بداية المجتهد","loc":"١/٢٦","pre":"قال ابن رشد:"},{"t":"quote","text":"وَنَصَّ الشَّافِعِيُّ رَضِيَ اللَّهُ عَنْهُ عَلَيْهَا فِي الْأُمِّ كَمَا قَالَهُ الْمُصَنِّفُ وَهُوَ أَنَّهُ يَجُوزُ الْمَسْحُ عَلَى الْجَوْرَبِ بِشَرْطِ أَنْ يَكُونَ صَفِيقًا مُنَعَّلًا","src":"المجموع","loc":"١/٤٩٩","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"عن عمر وعلي بن أبي طالب - رضي الله عنهما - جواز المسح على الجورب الرقيق، وهذا يعضُد القول بجواز المسح على الجوارب الخفيفة الرقيقة وعلى الجوارب المخرقة","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٦٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله: ونقل بعض أصحاب الشافعي"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح جواز المسح على الجوربين الصفيقين؛ لحديث المغيرة الذي صححه الترمذي، ولفعل جماعة من الصحابة. وقد ثبت عند الحنفية أنفسهم رجوع الإمام أبي حنيفة إلى هذا القول في آخر حياته:"},{"t":"quote","text":"دَخَلْتُ عَلَى أَبِي حَنِيفَةَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ فَدَعَا بِمَاءٍ فَتَوَضَّأَ وَعَلَيْهِ جَوْرَبَانِ فَمَسَحَ عَلَيْهِمَا ثُمَّ قَالَ فَعَلْتُ الْيَوْمَ شَيْئًا لَمْ أَكُنْ أَفْعَلُهُ مَسَحْتُ عَلَى الْجَوْرَبَيْنِ وَهُمَا غَيْرُ مُنَعَّلَيْنِ","src":"رواه الترمذي ٩٩","pre":"قال الترمذي: سمعت صالح بن محمد الترمذي قال: سمعت أبا مقاتل السمرقندي يقول:","links":[{"book":"mt_tirmidhi","num":99,"id":"h99"}]},{"t":"quote","text":"وَأَمَّا الْمَسْحُ عَلَى الْجَوْرَبَيْنِ، فَإِنْ كَانَا مُجَلَّدَيْنِ، أَوْ مُنَعَّلَيْنِ، يُجْزِيهِ بِلَا خِلَافٍ عِنْدَ أَصْحَابِنَا وَإِنْ لَمْ يَكُونَا مُجَلَّدَيْنِ، وَلَا مُنَعَّلَيْنِ، فَإِنْ كَانَا رَقِيقَيْنِ يَشِفَّانِ الْمَاءَ، لَا يَجُوزُ الْمَسْحُ عَلَيْهِمَا بِالْإِجْمَاعِ، وَإِنْ كَانَا ثَخِينَيْنِ لَا يَجُوزُ عِنْدَ أَبِي حَنِيفَةَ وَعِنْدَ أَبِي يُوسُفَ، وَمُحَمَّدٍ يَجُوزُ. وَرُوِيَ عَنْ أَبِي حَنِيفَةَ أَنَّهُ رَجَعَ إلَى قَوْلِهِمَا فِي آخِرِ عُمُرِهِ، وَذَلِكَ أَنَّهُ مَسَحَ عَلَى جَوْرَبَيْهِ فِي مَرَضِهِ، ثُمَّ قَالَ لِعُوَّادِهِ: \" فَعَلْتُ مَا كُنْت أَمْنَعُ النَّاسَ عَنْهُ \" فَاسْتَدَلُّوا بِهِ عَلَى رُجُوعِهِ","src":"بدائع الصنائع","loc":"١/١٠","pre":"وقال الكاساني في «بدائع الصنائع»:"},{"t":"tanbih","items":[{"t":"p","text":"يُشترط في الجورب ما يُشترط في الخف: أن يُلبس على طهارة، وأن يكون صفيقًا ساترًا لمحل الفرض يمكن المشي فيه، وتُراعى فيه مدة المسح نفسها."}]}],"refs":["الترمذي ٩٩، وأبو داود ١٥٩، وابن ماجه ٥٥٩","المغني (١/٢١٥)","بداية المجتهد (١/٢٦)","المجموع (١/٤٩٩)","مجموع فتاوى ابن عثيمين (١١/١٦٦)","الترمذي ٩٩","بدائع الصنائع (١/١٠)"],"related":["مشروعية المسح على الخفين وشرطه","مدة المسح على الخفين"],"alts":["المسح على الشراب","المسح على الجوارب القطنية","المسح على الجوارب الرقيقة"]},{"n":41,"bab":"الطهارة","sub":"المسح على الخفين","title":"الخف المخرَّق، وما يبطل المسح","q":"هل يجوز المسح على خف فيه خرق؟ وماذا يفعل من نزع خفه بعد المسح عليه؟","short":"يُعفى عن الخرق اليسير في الخف عند جمهور العلماء، وأجاز الثوري المسح ما دام يسمى خفًّا. ويبطل المسح بنواقض الوضوء، وبالجنابة، وبانقضاء المدة؛ واختلفوا فيمن نزع خفه وهو على طهارة: فالجمهور على أنه يغسل قدميه أو يعيد الوضوء، وقال بعضهم: طهارته باقية.","body":[{"t":"h","text":"المسألة الأولى: الخف المخرَّق"},{"t":"quote","text":"وَأَمَّا صِفَةُ الْخُفِّ، فَإِنَّهُمُ اتَّفَقُوا عَلَى جَوَازِ الْمَسْحِ عَلَى الْخُفِّ الصَّحِيحِ، وَاخْتَلَفُوا فِي الْمُخَرَّقِ، فَقَالَ مَالِكٌ وَأَصْحَابُهُ: يَمْسَحُ عَلَيْهِ إِذَا كَانَ الْخَرْقُ يَسِيرًا، وَحَدَّدَ أَبُو حَنِيفَةَ بِمَا يَكُونُ الظَّاهِرُ مِنْهُ أَقَلَّ مِنْ ثَلَاثَةِ أَصَابِعَ.","src":"بداية المجتهد","loc":"١/٢٧","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: ما يبطل المسح"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَأْمُرُنَا إِذَا كُنَّا سَفْرًا أَنْ لاَ نَنْزِعَ خِفَافَنَا ثَلاَثَةَ أَيَّامٍ وَلَيَالِيَهُنَّ إِلاَّ مِنْ جَنَابَةٍ وَلَكِنْ مِنْ غَائِطٍ وَبَوْلٍ وَنَوْمٍ","src":"رواه الترمذي ٩٦","pre":"ويدل على أن الجنابة تبطل المسح حديث صفوان بن عسال رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":96,"id":"h96"}]},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فإن اسم الخف أو الجورب ما دام باقياً فإنه يجوز المسح عليه، لأن السنة جاءت بالمسح على الخف على وجه مطلق، وما أطلقه الشارع فإنه ليس لأحد أن يقيده إلا إذا كان لديه نص من الشارع أو إجماع أو قياس صحيح، وبناء على ذلك فإنه يجوز المسح على الخف المخرق ويجوز المسح على الخف الخفيف","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٦٦","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن الخرق اليسير الذي لا يمنع إطلاق اسم الخف عليه لا يمنع المسح؛ لأن خفاف الصحابة لم تكن تسلم من الخروق، ولم يُنقل عنهم تشديد في ذلك. ومن نزع خفه بعد المسح فالأحوط أن يعيد الوضوء، أو يغسل قدميه على الأقل؛ خروجًا من الخلاف."}],"refs":["بداية المجتهد (١/٢٧)","بداية المجتهد (١/٢٩)","الترمذي ٩٦","مجموع فتاوى ابن عثيمين (١١/١٦٦)"],"related":["مدة المسح على الخفين","المسح على الجوارب"],"alts":["الجورب المثقوب","نزع الخف بعد المسح","انتهاء مدة المسح"]},{"n":42,"bab":"الطهارة","sub":"نواقض الوضوء","title":"خروج الدم والقيء من البدن، هل ينقض الوضوء؟","q":"من خرج منه دم من جرح أو رعاف، أو قاء، هل ينتقض وضوؤه؟","short":"اتفق العلماء على أن الخارج المعتاد من السبيلين ينقض الوضوء، واختلفوا في الخارج النجس من غيرهما كالدم والقيء: فجعله أبو حنيفة وأحمد ناقضًا إذا كثر، ولم يجعله مالك والشافعي ناقضًا. والأحوط الوضوء من الدم الكثير السائل والقيء الكثير، ولا شيء في اليسير.","body":[{"t":"h","text":"تحرير محل النزاع"},{"t":"quote","text":"وَاتَّفَقُوا فِي هَذَا الْبَابِ عَلَى انْتِقَاضِ الْوُضُوءِ مِنَ الْبَوْلِ وَالْغَائِطِ وَالرِّيحِ وَالْمَذْيِ وَالْوَدْيِ لِصِحَّةِ الْآثَارِ فِي ذَلِكَ إِذَا كَانَ خُرُوجُهَا عَلَى وَجْهِ الصِّحَّةِ","src":"بداية المجتهد","loc":"١/٤٠","pre":"قال ابن رشد:"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"كل نجاسة تسيل من البدن تنقض الوضوء، كالدم الكثير والقيء، وهو قول أبي حنيفة وأصحابه والثوري وأحمد."},{"t":"qawl","label":"القول الثاني","text":"لا ينقض إلا ما خرج من السبيلين، معتادًا كان أو نادرًا، وهو قول الشافعي."},{"t":"qawl","label":"القول الثالث","text":"لا ينقض إلا الخارج المعتاد من السبيلين على وجه الصحة، وهو قول مالك."},{"t":"h","text":"أدلة الأقوال"},{"t":"quote","text":"وَلِذَا أَطْلَقُوا فِي الْخَارِجِ مِنْ غَيْرِ السَّبِيلَيْنِ كَالدَّمِ وَالْقَيْحِ وَالصَّدِيدِ أَنَّهُ يَنْقُضُ الْوُضُوءَ","src":"الدر المختار مع رد المحتار","loc":"١/١٤٨","pre":"وقال ابن عابدين الحنفي في «رد المحتار»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الخارج من غير السبيلين لا ينقض الوضوء قلَّ أو كَثُر إلا البول والغائط، وذلك أن الأصل عدم النقض، فمن ادَّعى خلاف الأصل فعليه الدليل","src":"مجموع فتاوى ابن عثيمين","loc":"١١/١٩٨","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأحاديث في نقض الوضوء بالدم والقيء ليست صريحة في الوجوب، والأصل بقاء الطهارة؛ وقد صلى عمر رضي الله عنه وجرحه يثعب دمًا. فالأظهر أنه لا ينقض، والأحوط لمن خرج منه دم كثير سائل أو قاء ملء فيه أن يتوضأ؛ خروجًا من خلاف من أوجبه، ولا شيء في اليسير بالاتفاق تقريبًا."}],"refs":["بداية المجتهد (١/٤٠)","بداية المجتهد (١/٤١)","الدر المختار مع رد المحتار (١/١٤٨)","مجموع فتاوى ابن عثيمين (١١/١٩٨)"],"related":["النوم هل ينقض الوضوء؟"],"alts":["الرعاف والوضوء","خروج الدم من الجرح","القيء ينقض الوضوء"]},{"n":43,"bab":"الطهارة","sub":"نواقض الوضوء","title":"النوم، هل ينقض الوضوء؟","q":"من نام وهو جالس أو مستند أو مضطجع، هل ينتقض وضوؤه؟","short":"ذهب جمهور العلماء إلى أن النوم المستغرق الذي يزول معه الشعور ينقض الوضوء، وأن النعاس والنوم اليسير الذي لا يزول معه الإحساس لا ينقضه؛ ثم اختلفوا في الهيئات: فلم يوجبه أبو حنيفة إلا على المضطجع، والشافعي على كل نائم إلا الجالس الممكِّن مقعدته. والأحوط أن من استغرق في نومه توضأ.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم يَنْتَظِرُونَ الْعِشَاءَ الآخِرَةَ حَتَّى تَخْفِقَ رُءُوسُهُمْ ثُمَّ يُصَلُّونَ وَلاَ يَتَوَضَّئُونَ","src":"رواه أبو داود ٢٠٠","pre":"عن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":200,"id":"h200"}]},{"t":"quote","text":"وِكَاءُ السَّهِ الْعَيْنَانِ فَمَنْ نَامَ فَلْيَتَوَضَّأْ","src":"رواه أبو داود ٢٠٣","pre":"وعن علي رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":203,"id":"h203"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"النوم حدث، ينقض قليله وكثيره."},{"t":"qawl","label":"القول الثاني","text":"النوم ليس بحدث، ولا ينقض إلا إذا تيقّن خروج الحدث."},{"t":"qawl","label":"القول الثالث","text":"ينقض النوم الكثير المستغرق دون القليل الخفيف، وهو قول جمهور فقهاء الأمصار، على تفصيل بينهم في الهيئات."},{"t":"quote","text":"وَالنَّوْمَ يَنْقُضُ الْوُضُوءَ وَهُوَ مَحْمُولٌ عَلَى نَوْمِ غَيْرِ مُمَكِّنِ مَقْعَدِهِ","src":"المجموع","loc":"١/٤٨١","pre":"وقال النووي الشافعي في «المجموع» في فوائد حديث صفوان: وفيه أن الغائط والبول"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"النوم ينقض الوضوء إذا كان مستغرقا قد أزال الشعور","src":"مجموع فتاوى ابن باز","loc":"٤/٩٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"والنوم يَنقض الوضوء إذا كان مستغرقاً، بحيث لا يدري النائم لو خرج منه شيء","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٠٠","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح قول الجمهور: أن النوم في نفسه ليس حدثًا، وإنما هو مظنّة الحدث؛ فما استغرق حتى زال معه الشعور نقض الوضوء، وما كان نعاسًا أو خفقة رأس مع بقاء الإحساس لم ينقضه؛ جمعًا بين حديث «وكاء السه العينان» وحديث أنس في نوم الصحابة جلوسًا."}],"refs":["أبو داود ٢٠٠","أبو داود ٢٠٣","بداية المجتهد (١/٤٢)","المجموع (١/٤٨١)","مجموع فتاوى ابن باز (٤/٩٧)","مجموع فتاوى ابن عثيمين (١١/٢٠٠)","بداية المجتهد (١/٤٣)"],"related":["خروج الدم والقيء من البدن","لمس المرأة"],"alts":["النوم جالسا","النعاس في الصلاة","النوم ينقض الوضوء"]},{"n":44,"bab":"الطهارة","sub":"نواقض الوضوء","title":"لمس المرأة، هل ينقض الوضوء؟","q":"هل ينتقض وضوء الرجل إذا لمس زوجته أو قبّلها، أو صافح امرأة؟","short":"اختلف العلماء فيه: فقال الشافعي: ينقض لمس المرأة بلا حائل مطلقًا، وقال مالك وأحمد: ينقض إذا كان بشهوة، وقال أبو حنيفة: لا ينقض. والراجح أن مجرد اللمس لا ينقض الوضوء، وأن المراد بالملامسة في الآية الجماع؛ فإن خرج منه مذي انتقض وضوؤه بالمذي.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ","ref":"النساء: ٤٣"},{"t":"quote","text":"فَقَدْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً مِنَ الْفِرَاشِ فَالْتَمَسْتُهُ فَوَقَعَتْ يَدِي عَلَى بَطْنِ قَدَمَيْهِ وَهُوَ فِي الْمَسْجِدِ وَهُمَا مَنْصُوبَتَانِ","src":"رواه مسلم ٤٨٦","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":486,"id":"h486"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم قَبَّلَ امْرَأَةً مِنْ نِسَائِهِ ثُمَّ خَرَجَ إِلَى الصَّلاَةِ وَلَمْ يَتَوَضَّأْ . قَالَ عُرْوَةُ فَقُلْتُ لَهَا مَنْ هِيَ إِلاَّ أَنْتِ فَضَحِكَتْ","src":"رواه أبو داود ١٧٩","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_abudawud","num":179,"id":"h179"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"ينقض لمس المرأة باليد بلا حائل، وكذا القبلة، بشهوة أو بغيرها، وهو قول الشافعي."},{"t":"qawl","label":"القول الثاني","text":"ينقض إذا قارنته الشهوة أو قصدها، وهو مذهب مالك وجمهور أصحابه، والمشهور عن أحمد."},{"t":"qawl","label":"القول الثالث","text":"لا ينقض مطلقًا، وهو مذهب أبي حنيفة."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وهكذا مس المرأة لا ينقض الوضوء مطلقا سواء كان ذلك عن شهوة أو غير شهوة في أصح قولي العلماء، ما لم يخرج منه شيء؛ لأن النبي صلى الله عليه وسلم قبل بعض نسائه ثم صلى، ولم يتوضأ","src":"مجموع فتاوى ابن باز","loc":"٣/٢٩٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"الصحيح أن مس المرأة لا ينقض الوضوء مطلقا، إلا إذا خرج منه شيء، ودليل هذا ما صح عن النبي، صلى الله عليه وسلم، أنه قبل بعض نسائه وخرج إلى الصلاة ولم يتوضأ","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٠١","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"tanbih","items":[{"t":"p","text":"من لمس امرأة فخرج منه مذي انتقض وضوؤه بالمذي باتفاق، لا باللمس. ومصافحة المرأة الأجنبية مسألة أخرى في باب الحلال والحرام، لا في باب نقض الوضوء."}]}],"refs":["مسلم ٤٨٦","أبو داود ١٧٩","بداية المجتهد (١/٤٣-٤٤)","مجموع فتاوى ابن باز (٣/٢٩٥)","مجموع فتاوى ابن عثيمين (١١/٢٠١)","بداية المجتهد (١/٤٤)"],"related":["مس الذكر","النوم هل ينقض الوضوء؟"],"alts":["تقبيل الزوجة والوضوء","لمس الزوجة ينقض الوضوء","لمس المرأة"]},{"n":45,"bab":"الطهارة","sub":"نواقض الوضوء","title":"مس الذكر، هل ينقض الوضوء؟","q":"من مسّ ذكره أو فرجه بيده بلا حائل، هل ينتقض وضوؤه؟","short":"ذهب الشافعي وأحمد إلى أن مسّ الذكر باليد بلا حائل ينقض الوضوء، وفصّل المالكية، ولم يره أبو حنيفة ناقضًا؛ لتعارض حديث بسرة وحديث طلق بن علي. والأحوط أن يتوضأ من مسّه، ولا سيما إذا كان بشهوة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ مَسَّ ذَكَرَهُ فَلْيَتَوَضَّأْ","src":"رواه أبو داود ١٨١","pre":"عن بسرة بنت صفوان رضي الله عنها أنها سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_abudawud","num":181,"id":"h181"}]},{"t":"quote","text":"قَدِمْنَا عَلَى نَبِيِّ اللَّهِ صلى الله عليه وسلم فَجَاءَ رَجُلٌ كَأَنَّهُ بَدَوِيٌّ فَقَالَ يَا نَبِيَّ اللَّهِ مَا تَرَى فِي مَسِّ الرَّجُلِ ذَكَرَهُ بَعْدَ مَا يَتَوَضَّأُ فَقَالَ «هَلْ هُوَ إِلاَّ مُضْغَةٌ مِنْهُ» . أَوْ قَالَ - «بَضْعَةٌ مِنْهُ»","src":"رواه أبو داود ١٨٢، والترمذي ٨٥","pre":"وعن طلق بن علي رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":182,"id":"h182"},{"book":"mt_tirmidhi","num":85,"id":"h85"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"ينقض الوضوء كيفما مسّه، وهو مذهب الشافعي وأحمد وداود."},{"t":"qawl","label":"القول الثاني","text":"لا ينقض أصلًا، وهو مذهب أبي حنيفة وأصحابه."},{"t":"qawl","label":"القول الثالث","text":"التفصيل: فينقض إن كان بلذة، أو بباطن الكف، أو عمدًا، على روايات عن مالك وأصحابه؛ وقيل: الوضوء منه سنة."},{"t":"quote","text":"مَسُّ الذَّكَرِ اخْتَلَفَ الْعُلَمَاءُ فِيهِ عَلَى ثَلَاثَةِ مَذَاهِبَ: فَمِنْهُمْ مَنْ رَأَى الْوُضُوءَ فِيهِ كَيْفَمَا مَسَّهُ، وَهُوَ مَذْهَبُ الشَّافِعِيِّ وَأَصْحَابِهِ، وَأَحْمَدَ، وَدَاوُدَ، وَمِنْهُمْ مَنْ لَمْ يَرَ فِيهِ وُضُوءًا أَصْلًا، وَهُوَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ، وَلِكِلَا الْفَرِيقَيْنِ سَلَفٌ مِنَ الصَّحَابَةِ وَالتَّابِعِينَ.","src":"بداية المجتهد","loc":"١/٤٥","pre":"قال ابن رشد:"},{"t":"quote","text":"وَلَنَا) مَا رُوِيَ عَنْ عُمَرَ، وَعَلِيٍّ، وَابْنِ مَسْعُودٍ، وَابْنِ عَبَّاسٍ، وَزَيْدِ بْنِ ثَابِتٍ، وَعِمْرَانَ بْنِ حُصَيْنٍ، وَحُذَيْفَةَ بْنِ الْيَمَانِ، وَأَبِي الدَّرْدَاءِ، وَأَبِي هُرَيْرَةَ - رَضِيَ اللَّهُ عَنْهُمْ - أَنَّهُمْ لَمْ يَجْعَلُوا مَسَّ الذَّكَرِ حَدَثًا","src":"بدائع الصنائع","loc":"١/٣٠","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المشهور من المذهب أن مس الذكر ناقض للوضوء، وعلى هذا فإذا مس ذكره أثناء غسله لزمه الوضوء بعد ذلك، سواء تعمد مس ذكره أم لا. والقول الثاني: أن مس الذكر ليس بناقض للوضوء، وإنما يستحب الوضوء منه استحبابا وهو اختيار شيخ الإسلام ابن تيمية وهو أقرب إلى الصواب، لاسيما إذا كان عن غير عمد لكن الوضوء أحوط","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٠٣","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأحوط الوضوء من مس الذكر بلا حائل؛ لحديث بسرة، وقد صححه أحمد وابن معين كما نقل ابن رشد، ومن أهل العلم من جمع بين الحديثين فحمل الأمر بالوضوء على المسّ بشهوة. فمن مسّه بشهوة فليتوضأ، ومن مسّه بلا شهوة فالوضوء أحوط له."}],"refs":["أبو داود ١٨١","أبو داود ١٨٢، والترمذي ٨٥","بداية المجتهد (١/٤٥)","بدائع الصنائع (١/٣٠)","مجموع فتاوى ابن عثيمين (١١/٢٠٣)","بداية المجتهد (١/٤٥-٤٦)"],"related":["لمس المرأة"],"alts":["لمس العورة والوضوء","مس الفرج"]},{"n":46,"bab":"الطهارة","sub":"نواقض الوضوء","title":"أكل لحم الإبل، هل ينقض الوضوء؟","q":"هل يجب الوضوء على من أكل لحم الإبل؟ وهل يجب الوضوء مما مسته النار؟","short":"لا يجب الوضوء مما مسّته النار عند جماهير العلماء؛ لأنه آخر الأمرين من رسول الله ﷺ. واختلفوا في لحم الإبل خاصة: فأوجب أحمد وإسحاق الوضوء منه، واختاره النووي من الشافعية لصحة الحديث فيه، ولم يوجبه الجمهور. والراجح دليلًا الوضوء من لحم الإبل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَأَتَوَضَّأُ مِنْ لُحُومِ الْغَنَمِ؟ قَالَ: «إِنْ شِئْتَ فَتَوَضَّأْ، وَإِنْ شِئْتَ فَلَا تَوَضَّأْ» قَالَ أَتَوَضَّأُ مِنْ لُحُومِ الْإِبِلِ؟ قَالَ: «نَعَمْ فَتَوَضَّأْ مِنْ لُحُومِ الْإِبِلِ»","src":"رواه مسلم ٣٦٠","pre":"عن جابر بن سمرة رضي الله عنه أن رجلًا سأل رسول الله ﷺ:","links":[{"book":"mt_muslim","num":360,"id":"h360"}]},{"t":"quote","text":"كَانَ آخِرُ الأَمْرَيْنِ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم تَرْكَ الْوُضُوءِ مِمَّا غَيَّرَتِ النَّارُ","src":"رواه أبو داود ١٩٢، والنسائي ١٨٥","pre":"وعن جابر بن عبد الله رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":192,"id":"h192"},{"book":"mt_nasai","num":185,"id":"h185"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجب الوضوء من أكل شيء، لحم الإبل وغيره، وهو قول جمهور العلماء ومنهم مالك وأبو حنيفة، والجديد من قول الشافعي."},{"t":"qawl","label":"القول الثاني","text":"يجب الوضوء من لحم الإبل خاصة، وهو قول أحمد وإسحاق، والقديم من قول الشافعي، واختاره ابن خزيمة وابن المنذر والنووي."},{"t":"qawl","label":"القول الثالث","text":"يجب الوضوء مما مسّته النار، وهو قول طائفة من السلف."},{"t":"quote","text":"وَمَذْهَبُنَا أَنَّهُ لَا ينتقض الوضوء بشئ مِنْ الْمَأْكُولَاتِ سَوَاءٌ مَا مَسَّتْهُ النَّارُ وَغَيْرُهُ غَيْرَ لَحْمِ الْجَزُورِ وَفِي لَحْمِ الْجَزُورِ بِفَتْحِ الْجِيمِ وَهُوَ لَحْمُ الْإِبِلِ قَوْلَانِ الْجَدِيدُ الْمَشْهُورُ لَا يَنْتَقِضُ وَهُوَ الصَّحِيحُ عِنْدَ الْأَصْحَابِ وَالْقَدِيمُ أَنَّهُ يَنْتَقِضُ وَهُوَ ضَعِيفٌ عِنْدَ الْأَصْحَابِ وَلَكِنَّهُ هُوَ الْقَوِيُّ أَوْ الصَّحِيحُ مِنْ حَيْثُ الدَّلِيلُ وَهُوَ الَّذِي أَعْتَقِدُ رُجْحَانَهُ وَقَدْ أَشَارَ الْبَيْهَقِيُّ إلى ترجيحه واختياره والذب عنه وستري دَلِيلَهُ إنْ شَاءَ اللَّهُ تَعَالَى وَقَدْ اخْتَلَفَ الْعُلَمَاءُ فِي هَذِهِ الْمَسْأَلَةِ عَلَى ثَلَاثَةِ مَذَاهِبَ احدها لا يجب الوضوء باكل شئ سَوَاءٌ مَا مَسَّتْهُ النَّارُ وَلَحْمُ الْإِبِلِ وَغَيْرُ ذَلِكَ وَبِهِ قَالَ جُمْهُورُ الْعُلَمَاءِ وَهُوَ مَحْكِيٌّ عَنْ أَبِي بَكْرٍ الصِّدِّيقِ وَعُمَرَ وَعُثْمَانَ وَعَلِيٍّ وَابْنِ مَسْعُودٍ وَأُبَيِّ بْنِ كَعْبٍ وَأَبِي طَلْحَةَ وَأَبِي الدَّرْدَاءِ وَابْنِ عَبَّاسٍ وَعَامِرِ بْنِ رَبِيعَةَ وَأَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُمْ وَبِهِ قَالَ جُمْهُورُ التَّابِعِينَ وَمَالِكٌ وَأَبُو حَنِيفَةَ * وَقَالَتْ طَائِفَةٌ يَجِبُ مِمَّا مَسَّتْهُ النَّارُ وَهُوَ قَوْلُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ وَالْحَسَنِ وَالزُّهْرِيِّ وَأَبِي قِلَابَةَ وابي مجاز وَحَكَاهُ ابْنُ الْمُنْذِرِ عَنْ جَمَاعَةٍ مِنْ الصَّحَابَةِ ابن عمروابي طَلْحَةَ وَأَبِي مُوسَى وَزَيْدِ بْنِ ثَابِتٍ وَأَبِي هُرَيْرَةَ وَعَائِشَةَ رَضِيَ اللَّهُ عَنْهُمْ * وَقَالَتْ طَائِفَةٌ يَجِبُ مِنْ أَكْلِ لَحْمِ الْجَزُورِ خَاصَّةً وَهُوَ قول احمد بن حنبل واسحق بْنِ رَاهْوَيْهِ وَيَحْيَى بْنِ يَحْيَى وَحَكَاهُ الْمَاوَرْدِيُّ عَنْ جَمَاعَةٍ مِنْ الصَّحَابَةِ زَيْدِ بْنِ ثَابِتٍ وَابْنِ عُمَرَ وَأَبِي مُوسَى وَأَبِي طَلْحَةَ وَأَبِي هُرَيْرَةَ وَعَائِشَةَ وَحَكَاهُ ابْنُ الْمُنْذِرِ عَنْ جَابِرِ بْنِ سَمُرَةَ الصَّحَابِيِّ وَمُحَمَّدِ بْنِ إِسْحَاقَ وَأَبِي ثَوْرٍ وَأَبِي خَيْثَمَةَ وَاخْتَارَهُ مِنْ أَصْحَابِنَا أَبُو بَكْرِ بْنُ خُزَيْمَةَ وَابْنُ الْمُنْذِرِ وَأَشَارَ إلَيْهِ الْبَيْهَقِيُّ كَمَا سَبَقَ","src":"المجموع","loc":"٢/٥٧","pre":"قال النووي:"},{"t":"quote","text":"وَفِي لَحْمِ الْجَزُورِ بِفَتْحِ الْجِيمِ وَهُوَ لَحْمُ الْإِبِلِ قَوْلَانِ الْجَدِيدُ الْمَشْهُورُ لَا يَنْتَقِضُ وَهُوَ الصَّحِيحُ عِنْدَ الْأَصْحَابِ وَالْقَدِيمُ أَنَّهُ يَنْتَقِضُ وَهُوَ ضَعِيفٌ عِنْدَ الْأَصْحَابِ وَلَكِنَّهُ هُوَ الْقَوِيُّ أَوْ الصَّحِيحُ مِنْ حَيْثُ الدَّلِيلُ","src":"المجموع","loc":"٢/٥٧","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لقوله صلى الله عليه وسلم لما سئل عن الوضوء من لحوم الإبل قال: \"نعم\" ولما سئل عن الوضوء من لحوم الغنم قال: إن شئت » رواه الإمام مسلم في صحيحه","src":"فتاوى اللجنة الدائمة","loc":"٥/٢٩٦","pre":"جاء في فتاوى اللجنة الدائمة في وجوب الوضوء من أكل لحم الإبل:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح من جهة الدليل الوضوء من لحم الإبل؛ لأن حديث جابر بن سمرة في صحيح مسلم صريح في التفريق بين لحم الغنم ولحم الإبل، وحديث «آخر الأمرين» عامّ فيما مسّته النار، فلا يعارض هذا الخاص. وقد صرّح الإمام النووي — وهو شافعي المذهب — بأن هذا القول هو الأقوى دليلًا، كما في كلامه المنقول."}],"refs":["مسلم ٣٦٠","أبو داود ١٩٢، والنسائي ١٨٥","المجموع (٢/٥٧)","فتاوى اللجنة الدائمة (٥/٢٩٦)"],"related":["خروج الدم والقيء من البدن"],"alts":["الوضوء من لحم الجمل","الوضوء مما مست النار"]},{"n":47,"bab":"الطهارة","sub":"الغسل","title":"الجماع بلا إنزال، هل يوجب الغسل؟","q":"من جامع زوجته ولم ينزل، هل يجب عليه الغسل؟","short":"يجب الغسل بتغييب الحشفة في الفرج وإن لم يحصل إنزال، وهو قول الأئمة الأربعة وعامة الفقهاء؛ وكان حديث «الماء من الماء» رخصة في أول الإسلام ثم نُسخ.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا جَلَسَ بَيْنَ شُعَبِهَا الأَرْبَعِ ثُمَّ جَهَدَهَا، فَقَدْ وَجَبَ الْغَسْلُ","src":"رواه البخاري ٢٩١، ومسلم ٣٤٨","pre":"عن أبي هريرة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":291,"id":"h291"},{"book":"mt_muslim","num":348,"id":"h348"}]},{"t":"p","text":"وزاد مسلم في روايته: «وإن لم ينزل»."},{"t":"quote","text":"إِنَّمَا كَانَ الْمَاءُ مِنَ الْمَاءِ رُخْصَةً فِي أَوَّلِ الإِسْلاَمِ ثُمَّ نُهِيَ عَنْهَا","src":"رواه الترمذي ١١٠","pre":"وعن أبي بن كعب رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":110,"id":"h110"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يجب الغسل بالتقاء الختانين أنزل أو لم ينزل، وهو قول الخلفاء الأربعة وأكثر الصحابة، ومذهب أبي حنيفة ومالك والشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"لا يجب الغسل إلا بالإنزال، وهو قول جماعة من الصحابة أول الأمر، وحكي عن داود وبعض أهل الظاهر."},{"t":"quote","text":"اخْتَلَفَ الصَّحَابَةُ - رَضِيَ اللَّهُ عَنْهُمْ - فِي سَبَبِ إِيجَابِ الطُّهْرِ مِنَ الْوَطْءِ، فَمِنْهُمْ مَنْ رَأَى الطُّهْرَ وَاجِبًا فِي الْتِقَاءِ الْخِتَانَيْنِ أَنْزَلَ أَوْ لَمْ يُنْزِلْ، وَعَلَيْهِ أَكْثَرُ فُقَهَاءِ الْأَمْصَارِ مَالِكٌ وَأَصْحَابُهُ، وَالشَّافِعِيُّ وَأَصْحَابُهُ، وَجَمَاعَةٌ مِنْ أَهْلِ الظَّاهِرِ، وَذَهَبَ قَوْمٌ مِنْ أَهْلِ الظَّاهِرِ إِلَى إِيجَابِ الطُّهْرِ مَعَ الْإِنْزَالِ فَقَطْ","src":"بداية المجتهد","loc":"١/٥٣","pre":"قال ابن رشد:"},{"t":"quote","text":"قَوْلُهُ: وَعِنْدَ إيلَاجِ أَيْ إدْخَالِ، وَهَذَا أَعْلَمُ مِنْ التَّعْبِيرِ بِالْتِقَاءِ الْخِتَانَيْنِ لِشُمُولِهِ الدُّبُرَ أَيْضًا","src":"الدر المختار مع رد المحتار","loc":"١/١٦١","pre":"وقال ابن عابدين الحنفي في «رد المحتار»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الثاني: الجماع، فإذا جامع الرجل زوجته، وجب عليه الغسل بأن يولج الحشفة في فرجها، فإذا أولج في فرجها الحشفة أو ما زاد، فعليه الغسل","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢١٧","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله في موجبات الغسل:"},{"t":"quote","text":"وهذه المسألة ـ اعني الجماع بدون إنزال ـ يخفى حكمها على كثير من الناس، حتى إن بعض الناس تمضي عليه الأسابيع والشهور وهو يجامع زوجته بدون إنزال ولا يغتسل جهلا منه","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢١٧","pre":"وقال:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"إِنَّمَا الْمَاءُ مِنَ الْمَاءِ","src":"رواه مسلم ٣٤٣","pre":"وهو حديث أبي سعيد الخدري رضي الله عنه في قصة عتبان، وفيه قوله ﷺ:","links":[{"book":"mt_muslim","num":343,"id":"h343"}]},{"t":"quote","text":"وَرُوِيَ عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ قَالَ: اخْتَلَفَ فِي ذَلِكَ رَهْطٌ مِنْ الْمُهَاجِرِينَ وَالْأَنْصَارِ، فَقَالَ الْأَنْصَارِيُّونَ: لَا يَجِبُ الْغُسْلُ إلَّا مِنْ الْمَاءِ الدَّافِقِ أَوْ مِنْ الْمَاءِ، وَقَالَ الْمُهَاجِرُونَ: بَلْ إذَا خَالَطَ فَقَدْ وَجَبَ الْغُسْلُ، فَقَالَ أَبُو مُوسَى فَأَنَا أَشْفِيكُمْ مِنْ ذَلِكَ، فَقُمْت فَاسْتَأْذَنْت عَلَى عَائِشَةَ، فَقُلْت: يَا أُمَّاهُ، أَوْ يَا أُمَّ الْمُؤْمِنِينَ، إنِّي أُرِيدُ أَنْ أَسْأَلَك عَنْ شَيْءٍ، وَأَنَا أَسْتَحْيِيك، فَقَالَتْ: لَا تَسْتَحْيِي أَنْ تَسْأَلَنِي عَنْ شَيْءٍ كُنْت سَائِلًا عَنْهُ أُمَّك الَّتِي وَلَدَتْك، فَإِنَّمَا أَنَا أُمُّك. قُلْت: فَمَا يُوجِبُ الْغُسْلَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «إذَا جَلَسَ بَيْنَ شُعَبِهَا الْأَرْبَعِ، وَمَسَّ الْخِتَانُ الْخِتَانَ، فَقَدْ وَجَبَ الْغُسْلُ» مُتَّفَقٌ عَلَيْهِ","src":"المغني","loc":"١/١٥٠","pre":"وقال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح وجوب الغسل بمجرد تغييب الحشفة وإن لم ينزل؛ لصراحة حديث أبي هريرة وعائشة، ولشهادة أبي بن كعب رضي الله عنه بأن «الماء من الماء» كان رخصة ثم نُهي عنها، وعلى هذا استقر عمل الصحابة. ويُحمل حديث «إنما الماء من الماء» على أول الأمر، أو على الاحتلام كما قال ابن عباس رضي الله عنهما."},{"t":"tanbih","items":[{"t":"p","text":"مسُّ الختان الختانَ من غير إيلاج لا يوجب الغسل بالاتفاق، وإنما يجب الوضوء على من يرى النقض بمسّ المرأة."}]}],"refs":["البخاري ٢٩١، ومسلم ٣٤٨","الترمذي ١١٠","بداية المجتهد (١/٥٣)","الدر المختار مع رد المحتار (١/١٦١)","مجموع فتاوى ابن عثيمين (١١/٢١٧)","مسلم ٣٤٣","المغني (١/١٥٠)"],"related":["خروج المني بغير شهوة، هل يوجب الغسل؟"],"alts":["الجماع بدون إنزال","الإكسال","التقاء الختانين","الماء من الماء"]},{"n":48,"bab":"الطهارة","sub":"الغسل","title":"خروج المني، ومتى يوجب الغسل؟ وهل على المرأة غسل إذا احتلمت؟","q":"خرج مني المني بغير شهوة لمرض أو حمل ثقيل، فهل علي غسل؟ وهل على المرأة غسل إذا رأت في المنام ما يراه الرجل؟","short":"أجمع العلماء على وجوب الغسل بخروج المني بشهوة في النوم أو اليقظة من الرجل والمرأة. فإن خرج بغير شهوة لمرض أو برد أو حمل ثقيل فالجمهور (أبو حنيفة ومالك وأحمد) على أنه لا غسل فيه وعليه الوضوء، وأوجبه الشافعي. والمرأة إذا احتلمت ورأت الماء وجب عليها الغسل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَاءَتْ أُمُّ سُلَيْمٍ امْرَأَةُ أَبِي طَلْحَةَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَتْ يَا رَسُولَ اللَّهِ، إِنَّ اللَّهَ لاَ يَسْتَحْيِي مِنَ الْحَقِّ، هَلْ عَلَى الْمَرْأَةِ مِنْ غُسْلٍ إِذَا هِيَ احْتَلَمَتْ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «نَعَمْ إِذَا رَأَتِ الْمَاءَ»","src":"رواه البخاري ٢٨٢","pre":"عن أم سلمة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":282,"id":"h282"}]},{"t":"quote","text":"كُنْتُ رَجُلاً مَذَّاءً فَجَعَلْتُ أَغْتَسِلُ حَتَّى تَشَقَّقَ ظَهْرِي فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم - أَوْ ذُكِرَ لَهُ - فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «لاَ تَفْعَلْ إِذَا رَأَيْتَ الْمَذْىَ فَاغْسِلْ ذَكَرَكَ وَتَوَضَّأْ وُضُوءَكَ لِلصَّلاَةِ فَإِذَا فَضَخْتَ الْمَاءَ فَاغْتَسِلْ»","src":"رواه أبو داود ٢٠٦","pre":"وعن علي رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":206,"id":"h206"}]},{"t":"h","text":"محل الاتفاق"},{"t":"quote","text":"وَاتَّفَقَ الْعُلَمَاءُ عَلَى وُجُوبِ هَذِهِ الطَّهَارَةِ مِنْ حَدَثَيْنِ: أَحَدُهُمَا: خُرُوجُ الْمَنِيِّ عَلَى وَجْهِ الصِّحَّةِ فِي النَّوْمِ أَوِ الْيَقَظَةِ مِنْ ذَكَرٍ كَانَ أَوْ أُنْثَى، إِلَّا مَا رُوِيَ عَنِ النَّخَعِيِّ مِنْ أَنَّهُ كَانَ لَا يَرَى عَلَى الْمَرْأَةِ غُسْلًا مِنْ الِاحْتِلَامِ","src":"بداية المجتهد","loc":"١/٥٢","pre":"قال ابن رشد:"},{"t":"h","text":"أقوال العلماء في المني الخارج بغير شهوة"},{"t":"qawl","label":"القول الأول","text":"لا يجب الغسل إلا إذا خرج المني دفقًا بلذة، فإن خرج لمرض أو برد بغير لذة فعليه الوضوء فقط، وهو قول أبي حنيفة ومالك وأحمد."},{"t":"qawl","label":"القول الثاني","text":"يجب الغسل بخروج المني كيفما خرج، بلذة أو بغير لذة، وهو قول الشافعي."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وإذا احتلمت المرأة أو الرجل كذلك ولم يجد شيئا بعد الاستيقاظ، أي ما وجد أثرا من الماء فإنه ليس عليها غسل، وإن وجدت الماء فإنه يجب إن تغتسل","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٣٠","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر قول الجمهور: أن الموجب للغسل هو المني الخارج دفقًا بلذة؛ لقوله ﷺ: «فإذا فضخت الماء فاغتسل»، والفضخ هو الدفق بقوة، وهو لا يكون في العادة إلا مع الشهوة؛ وأما ما خرج لمرض أو برد بغير لذة فحكمه حكم سائر الخارج، يوجب الوضوء. ومن احتلم فوجد البلل وجب عليه الغسل وإن لم يذكر احتلامًا، ومن ذكر احتلامًا ولم يجد بللًا فلا غسل عليه بالإجماع."},{"t":"tanbih","items":[{"t":"p","text":"من جامع فاغتسل ثم خرج منه بقية مني، فقد اختلف العلماء فيه: فأوجب الشافعي الغسل، وفرّق أبو حنيفة بين ما خرج قبل البول فيغتسل، وما خرج بعده فلا غسل، ولم يوجبه مالك وأحمد في المشهور عنه، والأحوط الغسل إذا خرج قبل البول."}]}],"refs":["البخاري ٢٨٢","أبو داود ٢٠٦","بداية المجتهد (١/٥٢)","بداية المجتهد (١/٥٤)","مجموع فتاوى ابن عثيمين (١١/٢٣٠)"],"related":["الجماع بلا إنزال، هل يوجب الغسل؟"],"alts":["الاحتلام","احتلام المرأة","خروج المني بدون شهوة","المني من مرض"]},{"n":49,"bab":"الطهارة","sub":"الغسل","title":"هل تشترط النية والدلك في الغسل؟","q":"اغتسلت من الجنابة بإفاضة الماء على جسدي من غير أن أمر يدي عليه، وأحيانًا أغتسل للتبرد ثم أتذكر الجنابة، فهل يصح غسلي؟","short":"جمهور العلماء على أن إفاضة الماء على جميع البدن تكفي في الغسل وإن لم يدلك، وأوجب مالك الدلك. والنية شرط عند مالك والشافعي وأحمد، ولا تشترط عند أبي حنيفة. فالأحوط أن ينوي رفع الجنابة، ويستحب الدلك.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قُلْتُ يَا رَسُولَ اللهِ إِنِّي امْرَأَةٌ أَشُدُّ ضَفْرَ رَأْسِي فَأَنْقُضُهُ لِغُسْلِ الْجَنَابَةِ؟ قَالَ: «لَا. إِنَّمَا يَكْفِيكِ أَنْ تَحْثِي عَلَى رَأْسِكِ ثَلَاثَ حَثَيَاتٍ ثُمَّ تُفِيضِينَ عَلَيْكِ الْمَاءَ فَتَطْهُرِينَ»","src":"رواه مسلم ٣٣٠","pre":"عن أم سلمة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":330,"id":"h330"}]},{"t":"h","text":"المسألة الأولى: الدلك"},{"t":"qawl","label":"القول الأول","text":"لا يجب الدلك، ويكفي إيصال الماء إلى جميع البدن، وهو قول أكثر العلماء: أبي حنيفة والشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"يجب إمرار اليد على جميع الجسد، وهو قول مالك وجل أصحابه والمزني."},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ هَلْ مِنْ شَرْطِ هَذِهِ الطَّهَارَةِ إِمْرَارُ الْيَدِ عَلَى جَمِيعِ الْجَسَدِ كَالْحَالِ فِي طَهَارَةِ أَعْضَاءِ الْوُضُوءِ، أَمْ يَكْفِي فِيهَا إِفَاضَةُ الْمَاءِ عَلَى جَمِيعِ الْجَسَدِ، وَإِنْ لَمْ يُمِرَّ يَدَيْهِ عَلَى بَدَنِهِ؟","src":"بداية المجتهد","loc":"١/٥٠","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: النية"},{"t":"qawl","label":"القول الأول","text":"النية شرط في صحة الغسل، وهو قول مالك والشافعي وأحمد وأبي ثور وداود."},{"t":"qawl","label":"القول الثاني","text":"يصح الغسل بغير نية، وهو قول أبي حنيفة وأصحابه والثوري."},{"t":"quote","text":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى","src":"رواه البخاري ١","pre":"ودليل من اشترطها قوله ﷺ:","links":[{"book":"mt_bukhari","num":1,"id":"h1"}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الدلك ليس بواجب؛ لأن النبي ﷺ حصر لأم سلمة ما يكفيها في الإفاضة، ولم يذكر الدلك، والأحاديث الواصفة لغسله ﷺ ليس فيها إلا الإفاضة؛ لكن يستحب الدلك ويتأكد فيما يُظن ألا يصل إليه الماء إلا به، كالإبط وطيات البطن وأصول الشعر."},{"t":"p","text":"وأما النية فالأظهر اشتراطها، لحديث «إنما الأعمال بالنيات»، والغسل عبادة؛ وهي عمل القلب، فمن قصد الاغتسال من الجنابة فقد نوى، ولا يتلفظ بها. فمن اغتسل للتبرد أو النظافة ولم يقصد رفع الجنابة فالأحوط أن يعيد الغسل خروجًا من الخلاف."}],"refs":["مسلم ٣٣٠","بداية المجتهد (١/٥٠)","بداية المجتهد (١/٥١)","البخاري ١"],"related":["المضمضة والاستنشاق في الغسل، وصفة الغسل الكامل والمجزئ"],"alts":["الدلك في الغسل","النية في غسل الجنابة","إفاضة الماء بدون دلك","الغسل للتبرد"]},{"n":50,"bab":"الطهارة","sub":"الغسل","title":"صفة الغسل الكامل والمجزئ، وحكم المضمضة والاستنشاق فيه، ونقض الضفائر","q":"ما صفة غسل الجنابة؟ وهل المضمضة والاستنشاق واجبتان فيه؟ وهل يجب على المرأة نقض ضفائرها؟","short":"للغسل صفتان: مجزئة، وهي تعميم البدن بالماء مع النية؛ وكاملة، وهي ما ورد في حديث عائشة وميمونة رضي الله عنهما. والمضمضة والاستنشاق واجبتان فيه عند أبي حنيفة وأحمد، وسنة عند مالك والشافعي، والأحوط فعلهما. ولا يجب على المرأة نقض ضفائرها في غسل الجنابة إذا وصل الماء إلى أصول الشعر.","body":[{"t":"h","text":"الصفة الكاملة"},{"t":"quote","text":"كَانَ إِذَا اغْتَسَلَ مِنَ الْجَنَابَةِ بَدَأَ فَغَسَلَ يَدَيْهِ، ثُمَّ يَتَوَضَّأُ كَمَا يَتَوَضَّأُ لِلصَّلاَةِ، ثُمَّ يُدْخِلُ أَصَابِعَهُ فِي الْمَاءِ، فَيُخَلِّلُ بِهَا أُصُولَ شَعَرِهِ ثُمَّ يَصُبُّ عَلَى رَأْسِهِ ثَلاَثَ غُرَفٍ بِيَدَيْهِ، ثُمَّ يُفِيضُ الْمَاءَ عَلَى جِلْدِهِ كُلِّهِ","src":"رواه البخاري ٢٤٨","pre":"عن عائشة رضي الله عنها زوج النبي ﷺ أن النبي ﷺ:","links":[{"book":"mt_bukhari","num":248,"id":"h248"}]},{"t":"quote","text":"وَضَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَضُوءًا لِجَنَابَةٍ فَأَكْفَأَ بِيَمِينِهِ عَلَى شِمَالِهِ مَرَّتَيْنِ، أَوْ ثَلاَثًا، ثُمَّ غَسَلَ فَرْجَهُ، ثُمَّ ضَرَبَ يَدَهُ بِالأَرْضِ ـ أَوِ الْحَائِطِ ـ مَرَّتَيْنِ أَوْ ثَلاَثًا، ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ، وَغَسَلَ وَجْهَهُ وَذِرَاعَيْهِ، ثُمَّ أَفَاضَ عَلَى رَأْسِهِ الْمَاءَ، ثُمَّ غَسَلَ جَسَدَهُ، ثُمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ","src":"رواه البخاري ٢٧٤","pre":"وعن ميمونة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":274,"id":"h274"}]},{"t":"h","text":"الصفة المجزئة"},{"t":"p","text":"ويكفي في الإجزاء ما في حديث أم سلمة رضي الله عنها: «إنما يكفيك أن تحثي على رأسك ثلاث حثيات ثم تفيضين عليك الماء فتطهرين» (رواه مسلم ٣٣٠)."},{"t":"h","text":"المضمضة والاستنشاق في الغسل"},{"t":"qawl","label":"القول الأول","text":"هما واجبتان في الغسل، وهو قول أبي حنيفة وأصحابه والثوري، وأحمد في المشهور عنه، ويوجبهما أحمد في الوضوء أيضًا."},{"t":"qawl","label":"القول الثاني","text":"هما سنتان في الغسل كالوضوء، وهو قول مالك والشافعي."},{"t":"quote","text":"وَقَالَ غَيْرُ الْقَاضِي، عَنْ أَحْمَدَ رِوَايَةً أُخْرَى: إنَّ الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ وَاجِبَانِ فِي الْكُبْرَى، مَسْنُونَانِ فِي الصُّغْرَى. وَهَذَا مَذْهَبُ الثَّوْرِيِّ وَأَصْحَابِ الرَّأْيِ؛ لِأَنَّ الْكُبْرَى يَجِبُ فِيهَا غَسْلُ كُلِّ مَا أَمْكَنَ مِنْ الْبَدَنِ كَبَوَاطِنِ الشُّعُورِ الْكَثِيفَةِ، وَلَا يَمْسَحُ فِيهَا عَنْ الْحَوَائِلِ، فَوَجَبَا فِيهَا، بِخِلَافِ الصُّغْرَى. وَقَالَ مَالِكٌ وَالشَّافِعِيُّ لَا يَجِبَانِ فِي الطَّهَارَتَيْنِ، وَإِنَّمَا هُمَا مَسْنُونَانِ فِيهِمَا","src":"المغني","loc":"١/٨٨","pre":"وقال ابن قدامة:"},{"t":"p","text":"ودليل من أوجبهما في الغسل قوله تعالى:"},{"t":"aya","text":"ۚ وَإِن كُنتُمْ جُنُبًا فَٱطَّهَّرُوا۟","ref":"المائدة: ٦"},{"t":"p","text":"فأمر بالتطهر بصيغة المبالغة، فيجب غسل كل ما يمكن غسله من البدن بلا حرج، والفم والأنف منه."},{"t":"h","text":"نقض الضفائر"},{"t":"p","text":"اتفق الأئمة الأربعة على أن المرأة لا يلزمها نقض ضفائرها في غسل الجنابة إذا بلغ الماء أصول الشعر؛ لحديث أم سلمة: «لا، إنما يكفيك أن تحثي على رأسك ثلاث حثيات». واختلفوا في غسل الحيض، ويأتي في بابه إن شاء الله."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأفضل أن يغتسل على صفة حديث عائشة وميمونة: يغسل يديه، ثم فرجه، ثم يتوضأ وضوءه للصلاة، ثم يخلل أصول شعره، ثم يفيض الماء على رأسه ثلاثًا، ثم على سائر جسده مبتدئًا بالأيمن، ثم يغسل رجليه إن لم يكن غسلهما. والمجزئ تعميم البدن بالماء مع النية."},{"t":"p","text":"وأما المضمضة والاستنشاق فالأحوط وجوبهما في الغسل، وهو أقوى من جهة النظر؛ لأن الأمر بالتطهير للبدن كله، والنبي ﷺ لم يُنقل عنه تركهما في غسله، فمن تركهما فليتداركهما ولو بعد الفراغ، ولا يعيد الغسل كله."}],"refs":["البخاري ٢٤٨","البخاري ٢٧٤","بداية المجتهد (١/٥١)","بداية المجتهد (١/٥٢)","المغني (١/٨٨)"],"related":["هل تشترط النية والدلك في الغسل؟"],"alts":["كيفية غسل الجنابة","المضمضة في الغسل","نقض الشعر للغسل","الوضوء قبل الغسل"]},{"n":51,"bab":"الطهارة","sub":"الغسل","title":"قراءة القرآن للجنب","q":"هل يجوز للجنب أن يقرأ القرآن من حفظه، أو يقرأ آية أو بعض آية بقصد الذكر؟","short":"جمهور العلماء من الأئمة الأربعة على تحريم قراءة القرآن على الجنب، وأجازها بعض السلف وأهل الظاهر. ويجوز له الذكر والتسبيح والدعاء، وما وافق القرآن من الأذكار إذا لم يقصد التلاوة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُقْرِئُنَا الْقُرْآنَ عَلَى كُلِّ حَالٍ مَا لَمْ يَكُنْ جُنُبًا","src":"رواه الترمذي ١٤٦، وأبو داود ٢٢٩","pre":"عن علي رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":146,"id":"h146"},{"book":"mt_abudawud","num":229,"id":"h229"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ اللهَ عَلَى كُلِّ أَحْيَانِهِ","src":"رواه مسلم ٣٧٣","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":373,"id":"h373"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يحرم على الجنب قراءة القرآن، وهو قول عمر وعلي رضي الله عنهما، ومذهب أبي حنيفة والشافعي وأحمد ومالك."},{"t":"qawl","label":"القول الثاني","text":"يجوز للجنب قراءة القرآن، وهو قول سعيد بن المسيب، وروي عن ابن عباس رضي الله عنهما، وهو مذهب داود وابن حزم."},{"t":"quote","text":"وَلَا يَقْرَأُ الْقُرْآنَ جُنُبٌ وَلَا حَائِضٌ وَلَا نُفَسَاءُ رُوِيت الْكَرَاهِيَةُ لِذَلِكَ عَنْ عُمَرَ وَعَلِيٍّ وَالْحَسَنِ وَالنَّخَعِيِّ وَالزُّهْرِيِّ وَقَتَادَةِ وَالشَّافِعِيِّ وَأَصْحَابِ الرَّأْيِ. وَقَالَ الْأَوْزَاعِيُّ لَا يَقْرَأُ إلَّا آيَةَ الرُّكُوبِ وَالنُّزُولِ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا} الزخرف: 13 ، {وَقُلْ رَبِّ أَنْزِلْنِي مُنْزَلا مُبَارَكًا} المؤمنون: 29 وَقَالَ ابْنُ عَبَّاسٍ يَقْرَأُ وِرْدَهُ. وَقَالَ سَعِيدُ بْنُ الْمُسَيِّبِ: يَقْرَأُ الْقُرْآنَ، أَلَيْسَ هُوَ فِي جَوْفِهِ، وَحُكِيَ عَنْ مَالِكٍ لِلْحَائِضِ الْقِرَاءَةُ دُونَ الْجُنُبِ؛ لِأَنَّ أَيَّامَهَا تَطُولُ، فَإِنْ مَنَعْنَاهَا مِنْ الْقِرَاءَةِ نَسِيَتْ","src":"المغني","loc":"١/١٠٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"فِي مَذَاهِبِ الْعُلَمَاءِ فِي قِرَاءَةِ الْجُنُبِ وَالْحَائِضِ: مَذْهَبُنَا أَنَّهُ يَحْرُمُ عَلَى الْجُنُبِ وَالْحَائِضِ قِرَاءَةُ الْقُرْآنِ قَلِيلُهَا وَكَثِيرُهَا حَتَّى بَعْضُ آيَةٍ وَبِهَذَا قَالَ أَكْثَرُ الْعُلَمَاءِ","src":"المجموع","loc":"٢/١٥٨","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا حرج على الجنب والحائض والنفساء، كلهم لا حرج عليهم أن يسمعوا القرآن والأذكار الشرعية، إنما المحرم قراءة القرآن للجنب، كونه يقرأ ولو من غير المصحف حتى يغتسل، أما الحائض والنفساء فالصواب أن لهما القراءة؛ لأنهما مدتهما تطول","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٣٠٩","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله، فقال:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وَالسَّبَبُ فِي ذَلِكَ الِاحْتِمَالُ الْمُتَطَرِّقُ إِلَى حَدِيثِ عَلِيٍّ أَنَّهُ قَالَ: «كَانَ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - لَا يَمْنَعُهُ مِنْ قِرَاءَةِ الْقُرْآنِ شَيْءٌ إِلَّا الْجَنَابَةُ» وَذَلِكَ أَنَّ قَوْمًا قَالُوا: إِنَّ هَذَا لَا يُوجِبُ شَيْئًا ; لِأَنَّهُ ظَنٌّ مِنَ الرَّاوِي، وَمِنْ أَيْنَ يَعْلَمُ أَحَدٌ أَنَّ تَرْكَ الْقِرَاءَةِ كَانَ لِمَوْضِعِ الْجَنَابَةِ إِلَّا لَوْ أَخْبَرَهُ بِذَلِكَ؟","src":"بداية المجتهد","loc":"١/٥٥","pre":"قال ابن رشد:"},{"t":"h","text":"بعض الآية"},{"t":"quote","text":"وَيَحْرُمُ عَلَيْهِمْ قِرَاءَةُ آيَةٍ. فَأَمَّا بَعْضُ آيَةٍ؛ فَإِنْ كَانَ مِمَّا لَا يَتَمَيَّزُ بِهِ الْقُرْآنُ عَنْ غَيْرِهِ كَالتَّسْمِيَةِ، وَالْحَمْدُ لِلَّهِ، وَسَائِرِ الذِّكْرِ، فَإِنْ لَمْ يُقْصَدْ بِهِ الْقُرْآنُ، فَلَا بَأْسَ؛ فَإِنَّهُ لَا خِلَافَ فِي أَنَّ لَهُمْ ذِكْرَ اللَّهِ تَعَالَى، وَيَحْتَاجُونَ إلَى التَّسْمِيَةِ عِنْدَ اغْتِسَالِهِمْ، وَلَا يُمْكِنُهُمْ التَّحَرُّزُ مِنْ هَذَا","src":"المغني","loc":"١/١٠٦","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح قول الجمهور: أن الجنب لا يقرأ القرآن؛ لحديث علي رضي الله عنه، وهو حديث حسن صححه الترمذي، وعلي لم يكن ليقول ذلك ظنًا، ولأن الجنابة يمكن رفعها بالغسل في الحال، بخلاف الحيض. ويجوز للجنب أن يذكر الله ويسبحه ويدعوه، وأن يقول البسملة عند الغسل، و«إنا لله وإنا إليه راجعون» عند المصيبة، وما أشبهها من الأذكار القرآنية إذا لم يقصد بها التلاوة."},{"t":"tanbih","items":[{"t":"p","text":"من لم يجد ماء أو لم يقدر على الغسل تيمم، ثم قرأ وصلى؛ والحائض حكمها مختلف لطول مدتها، وتأتي في بابها إن شاء الله."}]}],"refs":["الترمذي ١٤٦، وأبو داود ٢٢٩","مسلم ٣٧٣","المغني (١/١٠٦)","المجموع (٢/١٥٨)","فتاوى نور على الدرب لابن باز (٥/٣٠٩)","بداية المجتهد (١/٥٥)"],"related":["مكث الجنب في المسجد ومروره فيه"],"alts":["الجنب يقرأ القرآن","قراءة القرآن من الحفظ للجنب","الذكر للجنب"]},{"n":52,"bab":"الطهارة","sub":"الغسل","title":"مكث الجنب في المسجد ومروره فيه","q":"هل يجوز للجنب أن يجلس في المسجد، أو أن يمر فيه مرورًا؟","short":"لا يجوز للجنب المكث في المسجد عند عامة العلماء؛ واختلفوا في العبور: فأجازه الشافعي وأحمد، ومنعه أبو حنيفة ومالك إلا لضرورة. والراجح جواز المرور للحاجة دون المكث، ويجوز المكث إذا توضأ عند أحمد.","body":[{"t":"h","text":"الدليل من الكتاب"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقْرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمْ سُكَـٰرَىٰ حَتَّىٰ تَعْلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ حَتَّىٰ تَغْتَسِلُوا۟","ref":"النساء: ٤٣"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَوُجُوهُ بُيُوتِ أَصْحَابِهِ شَارِعَةٌ فِي الْمَسْجِدِ فَقَالَ «وَجِّهُوا هَذِهِ الْبُيُوتَ عَنِ الْمَسْجِدِ» . ثُمَّ دَخَلَ النَّبِيُّ صلى الله عليه وسلم وَلَمْ يَصْنَعِ الْقَوْمُ شَيْئًا رَجَاءَ أَنْ تَنْزِلَ فِيهِمْ رُخْصَةٌ فَخَرَجَ إِلَيْهِمْ بَعْدُ فَقَالَ «وَجِّهُوا هَذِهِ الْبُيُوتَ عَنِ الْمَسْجِدِ فَإِنِّي لاَ أُحِلُّ الْمَسْجِدَ لِحَائِضٍ وَلاَ جُنُبٍ»","src":"رواه أبو داود ٢٣٢","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_abudawud","num":232,"id":"h232"}]},{"t":"quote","text":"قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «نَاوِلِينِي الْخُمْرَةَ مِنَ الْمَسْجِدِ»، قَالَتْ فَقُلْتُ: إِنِّي حَائِضٌ، فَقَالَ: «إِنَّ حَيْضَتَكِ لَيْسَتْ فِي يَدِكِ»","src":"رواه مسلم ٢٩٨","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":298,"id":"h298"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يمنع الجنب من دخول المسجد مطلقًا، مكثًا وعبورًا، إلا لضرورة فيتيمم، وهو قول مالك وأصحابه، وأبي حنيفة وأصحابه والثوري وإسحاق."},{"t":"qawl","label":"القول الثاني","text":"يمنع من المكث ويباح له العبور، وهو قول ابن مسعود وابن عباس وابن المسيب والحسن، ومذهب الشافعي وأحمد، ويجوز له المكث عند أحمد إذا توضأ."},{"t":"qawl","label":"القول الثالث","text":"يباح له الدخول والمكث، وهو قول داود وأصحابه والمزني."},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي دُخُولِ الْمَسْجِدِ لِلْجُنُبِ عَلَى ثَلَاثَةِ أَقْوَالٍ: فَقَوْمٌ مَنَعُوا ذَلِكَ بِإِطْلَاقٍ، وَهُوَ مَذْهَبُ مَالِكٍ وَأَصْحَابِهِ ; وَقَوْمٌ مَنَعُوا ذَلِكَ إِلَّا لِعَابِرٍ فِيهِ لَا مُقِيمٍ، وَمِنْهُمُ الشَّافِعِيُّ ; وَقَوْمٌ أَبَاحُوا ذَلِكَ لِلْجَمِيعِ، وَمِنْهُمْ دَاوُدُ وَأَصْحَابُهُ فِيمَا أَحْسَبُ","src":"بداية المجتهد","loc":"١/٥٤","pre":"قال ابن رشد:"},{"t":"quote","text":"وَقَالَ مَالِكٌ قَالَ زَيْدُ بْنُ أَسْلَمَ: لَا بَأْسَ أَنْ يَمُرَّ الْجُنُبُ فِي الْمَسْجِدِ عَابِرَ سَبِيلٍ","src":"المدونة","loc":"١/١٣٧","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وَلَيْسَ لَهُمْ اللُّبْثُ فِي الْمَسْجِدِ، لِقَوْلِ اللَّهِ تَعَالَى: {وَلا جُنُبًا إِلا عَابِرِي سَبِيلٍ حَتَّى تَغْتَسِلُوا} النساء: 43 وَرَوَتْ عَائِشَةُ، قَالَتْ: «جَاءَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَبُيُوتُ أَصْحَابِهِ شَارِعَةٌ فِي الْمَسْجِدِ، فَقَالَ: وَجِّهُوا هَذِهِ الْبُيُوتَ عَنْ الْمَسْجِدِ؛ فَإِنِّي لَا أُحِلُّ الْمَسْجِدَ لِحَائِضٍ وَلَا جُنُبٍ» رَوَاهُ أَبُو دَاوُد. وَيُبَاحُ الْعُبُورُ لِلْحَاجَةِ، مِنْ أَخْذِ شَيْءٍ، أَوْ تَرْكِهِ، أَوْ كَوْنِ الطَّرِيقِ فِيهِ، فَأَمَّا لِغَيْرِ ذَلِكَ فَلَا يَجُوزُ بِحَالٍ","src":"المغني","loc":"١/١٠٧","pre":"وقال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الجنب لا يمكث في المسجد، ويجوز له العبور فيه لحاجة؛ لقوله تعالى: ﴿وَلَا جُنُبًا إِلَّا عَابِرِى سَبِيلٍ﴾، وقد فسرها ابن مسعود وابن عباس رضي الله عنهم بالمار في المسجد، وقد رُوي عن بعض الصحابة أنهم كانوا يمرون في المسجد وهم جنب. ومن فسّر «عابري سبيل» بالمسافر الذي لم يجد الماء فقوله وجه معتبر في التفسير، وله سلف من الصحابة، ولذلك كان الأحوط ألا يدخله الجنب إلا لحاجة."},{"t":"tanbih","items":[{"t":"p","text":"مصلى البيت، ومصلى العيد، وأماكن الصلاة المؤقتة في الدوائر والأسواق لا تأخذ حكم المسجد في هذا عند أكثر العلماء."}]}],"refs":["أبو داود ٢٣٢","مسلم ٢٩٨","بداية المجتهد (١/٥٤)","المدونة (١/١٣٧)","بداية المجتهد (١/٥٥)","المغني (١/١٠٧)"],"related":["قراءة القرآن للجنب"],"alts":["دخول الجنب المسجد","الجلوس في المسجد بدون غسل","المرور في المسجد للجنب"]},{"n":53,"bab":"الطهارة","sub":"التيمم","title":"هل يتيمم الجنب إذا لم يجد الماء؟","q":"أصابتني جنابة في سفر ولم أجد ماء، فهل يجزئني التيمم عن الغسل، أم أنتظر حتى أجد الماء ولو فاتت الصلاة؟","short":"أجمع العلماء على أن التيمم بدل عن الوضوء، وعامة الفقهاء ومنهم الأئمة الأربعة على أنه بدل عن الغسل أيضًا، فيتيمم الجنب والحائض إذا لم يجدا الماء ويصليان، ولا يؤخران الصلاة. وكان يُروى عن عمر وابن مسعود رضي الله عنهما خلاف ذلك، وروي رجوع ابن مسعود عنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا هُوَ بِرَجُلٍ مُعْتَزِلٍ لَمْ يُصَلِّ مَعَ الْقَوْمِ قَالَ «مَا مَنَعَكَ يَا فُلاَنُ أَنْ تُصَلِّيَ مَعَ الْقَوْمِ». قَالَ أَصَابَتْنِي جَنَابَةٌ وَلاَ مَاءَ. قَالَ «عَلَيْكَ بِالصَّعِيدِ، فَإِنَّهُ يَكْفِيكَ»","src":"رواه البخاري ٣٤٤","pre":"عن عمران بن حصين رضي الله عنه في حديث طويل قال:","links":[{"book":"mt_bukhari","num":344,"id":"h344"}]},{"t":"quote","text":"جَاءَ رَجُلٌ إِلَى عُمَرَ بْنِ الْخَطَّابِ فَقَالَ إِنِّي أَجْنَبْتُ فَلَمْ أُصِبِ الْمَاءَ. فَقَالَ عَمَّارُ بْنُ يَاسِرٍ لِعُمَرَ بْنِ الْخَطَّابِ أَمَا تَذْكُرُ أَنَّا كُنَّا فِي سَفَرٍ أَنَا وَأَنْتَ فَأَمَّا أَنْتَ فَلَمْ تُصَلِّ، وَأَمَّا أَنَا فَتَمَعَّكْتُ فَصَلَّيْتُ، فَذَكَرْتُ لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ النَّبِيُّ صلى الله عليه وسلم «إِنَّمَا كَانَ يَكْفِيكَ هَكَذَا». فَضَرَبَ النَّبِيُّ صلى الله عليه وسلم بِكَفَّيْهِ الأَرْضَ، وَنَفَخَ فِيهِمَا ثُمَّ مَسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ","src":"رواه البخاري ٣٣٨، ومسلم ٣٦٨","pre":"وعن عبد الرحمن بن أبزى رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":338,"id":"h338"},{"book":"mt_muslim","num":368,"id":"h368"}]},{"t":"quote","text":"إِنَّ الصَّعِيدَ الطَّيِّبَ طَهُورُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ فَإِنَّ ذَلِكَ خَيْرٌ","src":"رواه الترمذي ١٢٤","pre":"وعن أبي ذر رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_tirmidhi","num":124,"id":"h124"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"التيمم بدل عن الطهارتين الصغرى والكبرى، فيتيمم الجنب والحائض إذا عدما الماء، وهو قول علي وعمار وعمران وأبي موسى وغيرهم من الصحابة، وعامة الفقهاء: أبي حنيفة ومالك والشافعي وأحمد والثوري وإسحاق."},{"t":"qawl","label":"القول الثاني","text":"التيمم بدل عن الوضوء وحده، فلا يتيمم الجنب، وروي ذلك عن عمر وابن مسعود رضي الله عنهما، وروي عن ابن مسعود الرجوع عنه."},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ هَذِهِ الطَّهَارَةَ هِيَ بَدَلٌ مِنَ الطَّهَارَةِ الصُّغْرَى، وَاخْتَلَفُوا فِي الْكُبْرَى، فَرُوِيَ عَنْ عُمَرَ وَابْنِ مَسْعُودٍ أَنَّهُمَا كَانَا لَا يَرَيَانِهَا بَدَلًا مِنَ الْكُبْرَى، وَكَانَ عَلِيٌّ وَغَيْرُهُ مِنَ الصَّحَابَةِ يَرَوْنَ أَنَّ التَّيَمُّمَ يَكُونُ بَدَلًا مِنَ الطَّهَارَةِ الْكُبْرَى، وَبِهِ قَالَ عَامَّةُ الْفُقَهَاءِ","src":"بداية المجتهد","loc":"١/٧٠","pre":"قال ابن رشد:"},{"t":"quote","text":"إذَا تَيَمَّمَ الْجُنُبُ وَاَلَّتِي انْقَطَعَ حَيْضُهَا وَنِفَاسُهَا ثُمَّ قَدَرَ عَلَى اسْتِعْمَالِ الْمَاءِ لَزِمَهُ الْغُسْلُ هَذَا مَذْهَبُنَا وَبِهِ قَالَ الْعُلَمَاءُ كَافَّةً إلَّا أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ","src":"المجموع","loc":"٢/٢٠٨","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح الذي لا ينبغي العدول عنه أن الجنب والحائض يتيممان إذا لم يجدا الماء أو عجزا عن استعماله، ويصليان؛ لحديث عمار وعمران بن حصين وأبي ذر، وهي صحيحة صريحة. وما روي عن عمر رضي الله عنه فسببه أنه نسي القصة، وابن مسعود رضي الله عنه إنما كرهه سدًّا للذريعة خشية أن يتيمم الناس عند برد الماء، كما صرح به في الحديث؛ وقد قال الترمذي: وهو قول عامة الفقهاء."},{"t":"tanbih","items":[{"t":"p","text":"إذا تيمم الجنب ثم وجد الماء وجب عليه الغسل؛ لقوله ﷺ: «فإذا وجد الماء فليمسه بشرته»، ولا يعيد ما صلى بتيممه."}]}],"refs":["البخاري ٣٤٤","البخاري ٣٣٨، ومسلم ٣٦٨","الترمذي ١٢٤","بداية المجتهد (١/٧٠)","المجموع (٢/٢٠٨)","بداية المجتهد (١/٧١)"],"related":["من يجوز له التيمم؟ المريض والخائف من البرد ومن عدم الماء في البلد"],"alts":["التيمم عن الجنابة","التيمم للحائض","الجنب لا يجد الماء"]},{"n":54,"bab":"الطهارة","sub":"التيمم","title":"من يجوز له التيمم؟ المريض، والخائف من البرد، ومن عدم الماء في البلد","q":"أنا مريض يضرني الماء، وأحيانًا ينقطع الماء في بيتي في المدينة، وأحيانًا يكون البرد شديدًا ولا أجد ما أسخن به الماء، فهل أتيمم؟","short":"أجمع العلماء على جواز التيمم للمريض والمسافر إذا عدما الماء. ويجوز عند جمهورهم للمريض الذي يضره الماء، وللصحيح الذي يخاف الهلاك أو المرض من شدة البرد ولا يقدر على تسخين الماء، ولمن عدم الماء في الحضر، ولمن حال بينه وبين الماء خوف.","body":[{"t":"h","text":"الدليل من الكتاب"},{"t":"aya","text":"ۚ وَإِن كُنتُم مَّرْضَىٰٓ أَوْ عَلَىٰ سَفَرٍ أَوْ جَآءَ أَحَدٌ مِّنكُم مِّنَ ٱلْغَآئِطِ أَوْ لَـٰمَسْتُمُ ٱلنِّسَآءَ فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا","ref":"النساء: ٤٣"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"احْتَلَمْتُ فِي لَيْلَةٍ بَارِدَةٍ فِي غَزْوَةِ ذَاتِ السَّلاَسِلِ فَأَشْفَقْتُ إِنِ اغْتَسَلْتُ أَنْ أَهْلِكَ فَتَيَمَّمْتُ ثُمَّ صَلَّيْتُ بِأَصْحَابِي الصُّبْحَ فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ «يَا عَمْرُو صَلَّيْتَ بِأَصْحَابِكَ وَأَنْتَ جُنُبٌ» . فَأَخْبَرْتُهُ بِالَّذِي مَنَعَنِي مِنَ الاِغْتِسَالِ وَقُلْتُ إِنِّي سَمِعْتُ اللَّهَ يَقُولُ { وَلاَ تَقْتُلُوا أَنْفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا } فَضَحِكَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلَمْ يَقُلْ شَيْئًا","src":"رواه أبو داود ٣٣٤","pre":"عن عمرو بن العاص رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":334,"id":"h334"}]},{"t":"quote","text":"خَرَجْنَا فِي سَفَرٍ فَأَصَابَ رَجُلاً مِنَّا حَجَرٌ فَشَجَّهُ فِي رَأْسِهِ ثُمَّ احْتَلَمَ فَسَأَلَ أَصْحَابَهُ فَقَالَ هَلْ تَجِدُونَ لِي رُخْصَةً فِي التَّيَمُّمِ فَقَالُوا مَا نَجِدُ لَكَ رُخْصَةً وَأَنْتَ تَقْدِرُ عَلَى الْمَاءِ فَاغْتَسَلَ فَمَاتَ فَلَمَّا قَدِمْنَا عَلَى النَّبِيِّ صلى الله عليه وسلم أُخْبِرَ بِذَلِكَ فَقَالَ «قَتَلُوهُ قَتَلَهُمُ اللَّهُ أَلاَّ سَأَلُوا إِذْ لَمْ يَعْلَمُوا فَإِنَّمَا شِفَاءُ الْعِيِّ السُّؤَالُ إِنَّمَا كَانَ يَكْفِيهِ أَنْ يَتَيَمَّمَ وَيَعْصِرَ» . أَوْ «يَعْصِبَ» . شَكَّ مُوسَى «عَلَى جُرْحِهِ خِرْقَةً ثُمَّ يَمْسَحَ عَلَيْهَا وَيَغْسِلَ سَائِرَ جَسَدِهِ»","src":"رواه أبو داود ٣٣٦","pre":"وعن جابر رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":336,"id":"h336"}]},{"t":"h","text":"محل الاتفاق والخلاف"},{"t":"quote","text":"وَأَمَّا مَنْ تَجُوزُ لَهُ هَذِهِ الطَّهَارَةُ، فَأَجْمَعَ الْعُلَمَاءُ أَنَّهَا تَجُوزُ لِاثْنَيْنِ: لِلْمَرِيضِ وَالْمُسَافِرِ إِذَا عَدِمَا الْمَاءَ. وَاخْتَلَفُوا فِي أَرْبَعٍ: الْمَرِيضِ يَجِدُ الْمَاءَ وَيَخَافُ مِنِ اسْتِعْمَالِهِ، وَفِي الْحَاضِرِ يَعْدَمُ الْمَاءَ، وَفِي الصَّحِيحِ الْمُسَافِرِ يَجِدُ الْمَاءَ فَيَمْنَعُهُ مِنَ الْوُصُولِ إِلَيْهِ خَوْفٌ، وَفِي الَّذِي يَخَافُ مِنِ اسْتِعْمَالِهِ مِنْ شِدَّةِ الْبَرْدِ","src":"بداية المجتهد","loc":"١/٧٢","pre":"قال ابن رشد:"},{"t":"h","text":"من عدم الماء في الحضر"},{"t":"qawl","label":"القول الأول","text":"يتيمم ويصلي، وهو قول مالك والشافعي وأحمد والثوري والأوزاعي، وهو المعتمد عند الحنفية."},{"t":"qawl","label":"القول الثاني","text":"لا يتيمم الحاضر الصحيح، بل يؤخر حتى يجد الماء، وهو رواية عن أبي حنيفة وقول زفر."},{"t":"quote","text":"فَإِنْ عَدِمَ الْمَاءَ فِي الْحَضَرِ، بِأَنْ انْقَطَعَ الْمَاءُ عَنْهُمْ، أَوْ حُبِسَ فِي مِصْرٍ، فَعَلَيْهِ التَّيَمُّمُ وَالصَّلَاةُ. وَهَذَا قَوْلُ مَالِكٍ، وَالثَّوْرِيِّ، وَالْأَوْزَاعِيِّ، وَالشَّافِعِيِّ، وَقَالَ أَبُو حَنِيفَةَ، فِي رِوَايَةٍ عَنْهُ: لَا يُصَلِّي؛ لِأَنَّ اللَّهَ تَعَالَى شَرَطَ السَّفَرَ لِجَوَازِ التَّيَمُّمِ، فَلَا يَجُوزُ لِغَيْرِهِ","src":"المغني","loc":"١/١٧٢-١٧٣","pre":"قال ابن قدامة:"},{"t":"h","text":"الخائف من شدة البرد في البلد"},{"t":"quote","text":"وَلَوْ أَجْنَبَ فِي لَيْلَةٍ بَارِدَةٍ يَخَافُ عَلَى نَفْسِهِ الْهَلَاكَ لَوْ اغْتَسَلَ وَلَمْ يَقْدِرْ عَلَى تَسْخِينِ الْمَاءِ وَلَا عَلَى أُجْرَةِ الْحَمَّامِ فِي الْمِصْرِ أَجْزَأَهُ التَّيَمُّمُ فِي قَوْلِ أَبِي حَنِيفَةَ وَقَالَ أَبُو يُوسُفَ، وَمُحَمَّدٌ: إنْ كَانَ فِي الْمِصْرِ لَا يُجْزِئُهُ","src":"بدائع الصنائع","loc":"١/٤٨","pre":"قال الكاساني الحنفي:"},{"t":"quote","text":"وَلَمْ يَأْمُرْهُ بِالْإِعَادَةِ وَلَمْ يَسْتَفْسِرْهُ إنَّهُ كَانَ فِي مَفَازَةٍ، أَوْ مِصْرٍ، وَلِأَنَّهُ عَلَّلَ فِعْلَهُ بِعِلَّةٍ عَامَّةٍ، وَهِيَ خَوْفُ الْهَلَاكِ وَرَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - اسْتَصْوَبَ ذَلِكَ مِنْهُ، وَالْحُكْمُ يَتَعَمَّمُ بِعُمُومِ الْعِلَّةِ وَقَوْلُهُمَا: \" إنَّ الْعَجْزَ فِي الْمِصْرِ نَادِرٌ \" فَالْجَوَابُ عَنْهُ أَنَّهُ فِي حَقِّ الْفُقَرَاءِ الْغُرَبَاءِ لَيْسَ بِنَادِرٍ، عَلَى أَنَّ الْكَلَامَ فِيمَا إذَا تَحَقَّقَ الْعَجْزُ مِنْ كُلِّ وَجْهٍ، حَتَّى لَوْ قَدَرَ عَلَى الِاغْتِسَالِ بِوَجْهٍ مِنْ الْوُجُوهِ لَا يُبَاحُ لَهُ التَّيَمُّمُ","src":"بدائع الصنائع","loc":"١/٤٨","pre":"ثم قال في نصرة قول أبي حنيفة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الراجح أن مدار التيمم على العجز عن استعمال الماء: إما لعدمه، وإما لضرر استعماله؛ فيتيمم المريض الذي يضره الماء أو يتأخر به برؤه، والصحيح الذي يخاف الهلاك أو المرض من شدة البرد ولا يجد ما يسخن به الماء، ومن انقطع عنه الماء في بلده، ومن حال بينه وبين الماء عدو أو سبع أو خوف على نفسه أو ماله أو عرضه؛ لعموم الآية، ولحديث عمرو بن العاص وجابر، ولقوله تعالى: ﴿مَا يُرِيدُ ٱللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ﴾. والقول بأن الحاضر لا يتيمم يؤدي إلى إخراج الصلاة عن وقتها، والصلاة في وقتها بالتيمم أولى من تأخيرها."},{"t":"tanbih","items":[{"t":"p","text":"من كان به جرح أو جبيرة يضره الماء غسل الصحيح من بدنه، ومسح على الجبيرة، وتيمم للجرح عند من يرى الجمع بينهما، لحديث جابر."},{"t":"p","text":"ومن كان معه ماء يحتاجه لشربه أو شرب رفيقه أو دابته تيمم، وحفظ الماء للعطش بالاتفاق."}]}],"refs":["أبو داود ٣٣٤","أبو داود ٣٣٦","بداية المجتهد (١/٧٢)","المغني (١/١٧٢-١٧٣)","بدائع الصنائع (١/٤٨)"],"related":["هل يتيمم الجنب إذا لم يجد الماء؟","صفة التيمم"],"alts":["التيمم للمريض","التيمم في البرد","انقطاع الماء في البيت","التيمم في الحضر"]},{"n":55,"bab":"الطهارة","sub":"التيمم","title":"صفة التيمم: كم ضربة؟ وإلى أين يمسح اليدين؟","q":"كيف أتيمم؟ هل أضرب الأرض ضربة واحدة أو ضربتين؟ وهل أمسح يدي إلى المرفقين أو الكفين فقط؟","short":"التيمم الوارد في الحديث الصحيح ضربة واحدة يمسح بها الوجه والكفين، وهو مذهب أحمد وأهل الحديث. وذهب أبو حنيفة ومالك والشافعي إلى أنه ضربتان: ضربة للوجه وضربة لليدين إلى المرفقين. والأظهر أن ضربة واحدة للوجه والكفين تجزئ، ومن مسح إلى المرفقين بضربتين احتياطًا فلا حرج.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَذَكَرْتُ لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ النَّبِيُّ صلى الله عليه وسلم «إِنَّمَا كَانَ يَكْفِيكَ هَكَذَا». فَضَرَبَ النَّبِيُّ صلى الله عليه وسلم بِكَفَّيْهِ الأَرْضَ، وَنَفَخَ فِيهِمَا ثُمَّ مَسَحَ بِهِمَا وَجْهَهُ وَكَفَّيْهِ","src":"رواه البخاري ٣٣٨","pre":"عن عمار بن ياسر رضي الله عنه في قصة تمعكه في التراب قال:","links":[{"book":"mt_bukhari","num":338,"id":"h338"}]},{"t":"quote","text":"«إِنَّمَا كَانَ يَكْفِيكَ أَنْ تَقُولَ بِيَدَيْكَ هَكَذَا» ثُمَّ ضَرَبَ بِيَدَيْهِ الْأَرْضَ ضَرْبَةً وَاحِدَةً، ثُمَّ مَسَحَ الشِّمَالَ عَلَى الْيَمِينِ، وَظَاهِرَ كَفَّيْهِ، وَوَجْهَهُ","src":"رواه مسلم ٣٦٨","pre":"وفي رواية لمسلم:","links":[{"book":"mt_muslim","num":368,"id":"h368"}]},{"t":"h","text":"المسألة الأولى: حدّ اليدين"},{"t":"quote","text":"اخْتَلَفَ الْفُقَهَاءُ فِي حَدِّ الْأَيْدِي الَّتِي أَمَرَ اللَّهُ بِمَسْحِهَا فِي التَّيَمُّمِ فِي قَوْلِهِ: {فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُمْ مِنْهُ} المائدة: 6 عَلَى أَرْبَعَةِ أَقْوَالٍ: الْقَوْلُ الْأَوَّلُ: أَنَّ الْحَدَّ الْوَاجِبَ فِي ذَلِكَ هُوَ الْحَدُّ الْوَاجِبُ بِعَيْنِهِ فِي الْوُضُوءِ، وَهُوَ إِلَى الْمَرَافِقِ، وَهُوَ مَشْهُورُ الْمَذْهَبِ، وَبِهِ قَالَ فُقَهَاءُ الْأَمْصَارِ.","src":"بداية المجتهد","loc":"١/٧٤-٧٥","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: عدد الضربات"},{"t":"quote","text":"الْمَسْنُونُ عِنْدَ أَحْمَدَ التَّيَمُّمُ بِضَرْبَةٍ وَاحِدَةٍ. فَإِنْ تَيَمَّمَ بِضَرْبَتَيْنِ جَازَ. وَقَالَ الْقَاضِي: الْإِجْزَاءُ يَحْصُلُ بِضَرْبَةٍ، وَالْكَمَالُ ضَرْبَتَانِ. وَالْمَنْصُوصُ مَا ذَكَرْنَاهُ، قَالَ الْأَثْرَمُ: قُلْت لِأَبِي عَبْدِ اللَّهِ: التَّيَمُّمُ ضَرْبَةٌ وَاحِدَةٌ؟ فَقَالَ: نَعَمْ ضَرْبَةٌ لِلْوَجْهِ وَالْكَفَّيْنِ، وَمَنْ قَالَ ضَرْبَتَيْنِ، فَإِنَّمَا هُوَ شَيْءٌ زَادَهُ","src":"المغني","loc":"١/١٧٩","pre":"وقال ابن قدامة:"},{"t":"quote","text":"وَالتَّيَمُّمُ ضَرْبَةٌ لِلْوَجْهِ وَضَرْبَةٌ لِلْيَدَيْنِ","src":"المدونة","loc":"١/١٤٥","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المشروع ضربة واحدة للوجه والكفين","src":"مجموع فتاوى ابن باز","loc":"٤/٣٢٠","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"والأفضل في التيمم أن يضرب الأرض ضربة واحدة بيديه ثم يمسح بهما وجهه وكفيه","src":"فتاوى اللجنة الدائمة","loc":"٥/٣٨٦","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر ما دل عليه حديث عمار رضي الله عنه في الصحيحين: أن يضرب الأرض بكفيه ضربة واحدة، وينفخ فيهما أو ينفضهما إن كثر التراب، ثم يمسح وجهه، ثم يمسح ظاهر كفيه، كل واحدة بالأخرى. وهذا هو الثابت؛ وأحاديث الضربتين والمرفقين في أسانيدها مقال، ولذلك رجح ابن رشد المالكي أن الفرض الكفان. ومن تيمم بضربتين ومسح إلى المرفقين أجزأه بالاتفاق، لأنه زاد على الواجب، والأمر فيه واسع."},{"t":"tanbih","items":[{"t":"p","text":"تجب النية في التيمم عند جمهور العلماء، ومنهم أبو حنيفة؛ فإنه وإن لم يشترطها في الوضوء اشترطها في التيمم، ولم يخالف في ذلك إلا زفر."}]}],"refs":["البخاري ٣٣٨","مسلم ٣٦٨","بداية المجتهد (١/٧٤-٧٥)","بداية المجتهد (١/٧٥)","بداية المجتهد (١/٧٦)","المغني (١/١٧٩)","المدونة (١/١٤٥)","مجموع فتاوى ابن باز (٤/٣٢٠)","فتاوى اللجنة الدائمة (٥/٣٨٦)"],"related":["ما يجوز التيمم به"],"alts":["كيفية التيمم","التيمم ضربة واحدة","التيمم إلى المرفقين"]},{"n":56,"bab":"الطهارة","sub":"التيمم","title":"ما يجوز التيمم به: التراب وحده، أو كل ما على وجه الأرض؟","q":"هل يجوز التيمم على الرمل والحجر والجدار، أو لا بد من تراب له غبار؟","short":"اتفق العلماء على جواز التيمم بالتراب الطاهر، واختلفوا فيما سواه: فلم يجزه الشافعي وأحمد إلا بتراب له غبار، وأجازه مالك وأبو حنيفة بكل ما كان من جنس الأرض كالرمل والحجر. والأظهر جوازه بكل ما صعد على وجه الأرض من جنسها، والتراب أولى.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟ صَعِيدًا طَيِّبًا فَٱمْسَحُوا۟ بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ","ref":"المائدة: ٦"},{"t":"quote","text":"أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِيَ الأَرْضُ مَسْجِدًا وَطَهُورًا، فَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلاَةُ فَلْيُصَلِّ","src":"رواه البخاري ٣٣٥","pre":"عن جابر بن عبد الله رضي الله عنهما أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":335,"id":"h335"}]},{"t":"quote","text":"فُضِّلْنَا عَلَى النَّاسِ بِثَلَاثٍ: جُعِلَتْ صُفُوفُنَا كَصُفُوفِ الْمَلَائِكَةِ، وَجُعِلَتْ لَنَا الْأَرْضُ كُلُّهَا مَسْجِدًا، وَجُعِلَتْ تُرْبَتُهَا لَنَا طَهُورًا، إِذَا لَمْ نَجِدِ الْمَاءَ","src":"رواه مسلم ٥٢٢","pre":"وعن حذيفة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":522,"id":"h522"}]},{"t":"quote","text":"أَقْبَلَ النَّبِيُّ صلى الله عليه وسلم مِنْ نَحْوِ بِئْرِ جَمَلٍ، فَلَقِيَهُ رَجُلٌ فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ النَّبِيُّ صلى الله عليه وسلم حَتَّى أَقْبَلَ عَلَى الْجِدَارِ، فَمَسَحَ بِوَجْهِهِ وَيَدَيْهِ، ثُمَّ رَدَّ عَلَيْهِ السَّلاَمَ","src":"رواه البخاري ٣٣٧","pre":"وعن أبي الجهيم رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":337,"id":"h337"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجوز التيمم إلا بتراب طاهر له غبار يعلق باليد، وهو قول الشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"يجوز بكل ما صعد على وجه الأرض من أجزائها كالتراب والرمل والحصى، وهو قول مالك في المشهور عنه."},{"t":"qawl","label":"القول الثالث","text":"يجوز بكل ما كان من جنس الأرض ولو لم يكن عليه غبار، كالحجر والجص والنورة، وهو قول أبي حنيفة."},{"t":"quote","text":"وَأَمَّا بَيَانُ مَا يُتَيَمَّمُ بِهِ فَقَدْ اُخْتُلِفَ فِيهِ، قَالَ أَبُو حَنِيفَةَ وَمُحَمَّدٌ: يَجُوزُ التَّيَمُّمُ بِكُلِّ مَا هُوَ مِنْ جِنْسِ الْأَرْضِ وَعَنْ أَبِي يُوسُفَ رِوَايَتَانِ: فِي رِوَايَةٍ بِالتُّرَابِ وَالرَّمْلِ، وَفِي رِوَايَةٍ لَا يَجُوزُ إلَّا بِالتُّرَابِ","src":"بدائع الصنائع","loc":"١/٥٣","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر جواز التيمم بكل ما صعد على وجه الأرض من جنسها: التراب والرمل والحجر والجدار من طين أو حجر؛ لأن الصعيد في اللغة وجه الأرض، ولعموم قوله ﷺ: «جعلت لي الأرض مسجدا وطهورا»، ولأن النبي ﷺ تيمم على الجدار، وكان هو وأصحابه يسافرون في أرض الرمال ولم يُنقل أنهم كانوا يحملون التراب معهم. وذكر التربة في حديث حذيفة خرج مخرج الغالب، والتيمم بالتراب الذي له غبار أفضل وأحوط خروجًا من الخلاف."},{"t":"tanbih","items":[{"t":"p","text":"لا يتيمم بما ليس من جنس الأرض كالخشب والقماش والزجاج والسجاد، إلا إذا كان عليه غبار طاهر."},{"t":"p","text":"ومن لم يجد ماء ولا ترابًا، كالمحبوس أو المريض المربوط بالسرير، صلى على حاله في الوقت، ولا يترك الصلاة."}]}],"refs":["البخاري ٣٣٥","مسلم ٥٢٢","البخاري ٣٣٧","بداية المجتهد (١/٧٧)","بدائع الصنائع (١/٥٣)"],"related":["صفة التيمم: كم ضربة؟ وإلى أين يمسح اليدين؟"],"alts":["التيمم على الحجر","التيمم بالرمل","التيمم على الجدار","الصعيد الطيب"]},{"n":57,"bab":"الطهارة","sub":"التيمم","title":"هل يجب التيمم لكل صلاة، أم يصلي بالتيمم الواحد ما شاء؟","q":"تيممت لصلاة الظهر، فهل أصلي به العصر أيضًا والنوافل، أم أتيمم لكل فريضة؟","short":"ذهب مالك والشافعي وأحمد في المشهور عنه إلى أن التيمم لا يُصلى به إلا فريضة واحدة أو صلوات وقت واحد، وذهب أبو حنيفة وأصحابه والثوري وسعيد بن المسيب والحسن، وهو رواية عن أحمد، إلى أن التيمم كالوضوء يصلي به ما شاء من الفرائض والنوافل ما لم يحدث أو يجد الماء. وهذا القول أظهر دليلًا.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"إِنَّ الصَّعِيدَ الطَّيِّبَ طَهُورُ الْمُسْلِمِ وَإِنْ لَمْ يَجِدِ الْمَاءَ عَشْرَ سِنِينَ فَإِذَا وَجَدَ الْمَاءَ فَلْيُمِسَّهُ بَشَرَتَهُ فَإِنَّ ذَلِكَ خَيْرٌ","src":"رواه الترمذي ١٢٤","pre":"عن أبي ذر رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_tirmidhi","num":124,"id":"h124"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يتيمم لكل صلاة فريضة، أو يبطل التيمم بخروج الوقت، وروي عن علي وابن عمر وابن عباس رضي الله عنهم، وهو قول مالك والشافعي، والمشهور عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"التيمم طهارة كاملة كالوضوء، يصلي به ما شاء حتى يحدث أو يجد الماء، وهو قول سعيد بن المسيب والحسن والزهري والثوري، وأصحاب الرأي، ورواية عن أحمد."},{"t":"quote","text":"فَلَا يَجُوزُ أَنْ يُصَلِّيَ بِهِ صَلَاتَيْنِ فِي وَقْتَيْنِ، رُوِيَ ذَلِكَ عَنْ عَلِيٍّ، وَابْنِ عُمَرَ، وَابْنِ عَبَّاسٍ، - رَضِيَ اللَّهُ عَنْهُمْ -، وَالشَّعْبِيِّ، وَالنَّخَعِيِّ، وَقَتَادَةَ، وَيَحْيَى الْأَنْصَارِيِّ، وَرَبِيعَةَ، وَمَالِكٍ، وَالشَّافِعِيِّ، وَاللَّيْثِ، وَإِسْحَاقَ. وَرَوَى الْمَيْمُونِيُّ، عَنْ أَحْمَدَ فِي الْمُتَيَمِّمِ، قَالَ: إنَّهُ لَيُعْجِبُنِي أَنْ يَتَيَمَّمَ لِكُلِّ صَلَاةٍ، وَلَكِنَّ الْقِيَاسَ أَنَّهُ بِمَنْزِلَةِ الطَّهَارَةِ حَتَّى يَجِدَ الْمَاءَ، أَوْ يُحْدِثَ؛ لِحَدِيثِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي الْجُنُبِ. يَعْنِي قَوْلَ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: يَا أَبَا ذَرٍّ، «الصَّعِيدُ الطَّيِّبُ طَهُورُ الْمُسْلِمِ، وَإِنْ لَمْ يَجِدْ الْمَاءَ عَشْرَ سِنِينَ، فَإِذَا وَجَدْت الْمَاءَ فَأَمِسَّهُ بَشَرَتَك» . وَهُوَ مَذْهَبُ سَعِيدِ بْنِ الْمُسَيِّبِ، وَالْحَسَنِ، وَالزُّهْرِيِّ، وَالثَّوْرِيِّ، وَأَصْحَابِ الرَّأْيِ. وَرُوِيَ عَنْ ابْنِ عَبَّاسٍ، وَأَبِي جَعْفَرٍ؛ لِأَنَّهَا طَهَارَةٌ تُبِيحُ الصَّلَاةَ، فَلَمْ تَتَقَدَّرْ بِالْوَقْتِ كَطَهَارَةِ الْمَاءِ","src":"المغني","loc":"١/١٩٣","pre":"قال ابن قدامة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والصحيح أنه يقوم مقام الطهارة، يرفع الحدث إلى وجود الماء، فإذا تيمم للظهر صلى به العصر إذا كان على طهارة","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٣١٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وَأَصْلُ هَذَا الْخِلَافِ يَدُورُ عَلَى شَيْئَيْنِ: أَحَدُهُمَا: هَلْ فِي قَوْله تَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلاةِ} المائدة: 6 مَحْذُوفٌ مُقَدَّرٌ: أَعْنِي إِذَا قُمْتُمْ مِنَ النَّوْمِ، أَوْ قُمْتُمْ مُحْدِثِينَ، أَمْ لَيْسَ هُنَالِكَ مَحْذُوفٌ أَصْلًا؟","src":"بداية المجتهد","loc":"١/٧٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التيمم طهارة صحيحة تقوم مقام الماء، يُصلى بها ما شاء من الفرائض والنوافل ما لم يحدث أو يجد الماء؛ لأن النبي ﷺ سمى الصعيد «طهور المسلم» و«وضوء المسلم»، وجعل غاية ذلك وجود الماء، ولم يأت عنه ﷺ نص صحيح بتجديده لكل صلاة. وما روي عن علي وابن عمر رضي الله عنهم في أسانيده مقال، ويحمل على الاستحباب، ولذلك قال الإمام أحمد مع اختياره الأول: «ولكن القياس أنه بمنزلة الطهارة حتى يجد الماء أو يحدث»."},{"t":"tanbih","items":[{"t":"p","text":"من تيمم لصلاة ثم صلى بها غيرها على هذا القول فصلاته صحيحة، ومن أخذ بالقول الأول احتياطًا فتيمم لكل فريضة فقد أحسن."}]}],"refs":["الترمذي ١٢٤","المغني (١/١٩٣)","فتاوى نور على الدرب لابن باز (٥/٣١٩)","بداية المجتهد (١/٧٨)"],"related":["من صلى بالتيمم ثم وجد الماء"],"alts":["التيمم يبطل بخروج الوقت","صلاتان بتيمم واحد","تجديد التيمم"]},{"n":58,"bab":"الطهارة","sub":"التيمم","title":"من صلى بالتيمم ثم وجد الماء، أو وجده في أثناء الصلاة","q":"تيممت وصليت ثم وجدت الماء والوقت باقٍ، فهل أعيد الصلاة؟ وماذا لو وجدت الماء وأنا في الصلاة؟","short":"من صلى بالتيمم ثم وجد الماء بعد الفراغ لم تجب عليه الإعادة لا في الوقت ولا بعده عند جمهور العلماء، لكن يتوضأ أو يغتسل لما يستقبل. وإن وجده قبل الصلاة بطل تيممه بالاتفاق. وإن وجده في أثناء الصلاة بطلت صلاته عند أبي حنيفة وأحمد، وأتمها عند مالك والشافعي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"خَرَجَ رَجُلاَنِ فِي سَفَرٍ فَحَضَرَتِ الصَّلاَةُ وَلَيْسَ مَعَهُمَا مَاءٌ فَتَيَمَّمَا صَعِيدًا طَيِّبًا فَصَلَّيَا ثُمَّ وَجَدَا الْمَاءَ فِي الْوَقْتِ فَأَعَادَ أَحَدُهُمَا الصَّلاَةَ وَالْوُضُوءَ وَلَمْ يُعِدِ الآخَرُ ثُمَّ أَتَيَا رَسُولَ اللَّهِ صلى الله عليه وسلم فَذَكَرَا ذَلِكَ لَهُ فَقَالَ لِلَّذِي لَمْ يُعِدْ «أَصَبْتَ السُّنَّةَ وَأَجْزَأَتْكَ صَلاَتُكَ» . وَقَالَ لِلَّذِي تَوَضَّأَ وَأَعَادَ «لَكَ الأَجْرُ مَرَّتَيْنِ»","src":"رواه أبو داود ٣٣٨، والنسائي ٤٣٣","pre":"عن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":338,"id":"h338"},{"book":"mt_nasai","num":433,"id":"h433"}]},{"t":"p","text":"قال أبو داود: ذكر أبي سعيد فيه ليس بمحفوظ، وهو مرسل؛ وقد عضده عمل الصحابة وقول عامة أهل العلم."},{"t":"h","text":"نقض التيمم بوجود الماء"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الثَّانِيَةُ: فَإِنَّ الْجُمْهُورَ ذَهَبُوا إِلَى أَنَّ وُجُودَ الْمَاءِ يَنْقُضُهَا. وَذَهَبَ قَوْمٌ إِلَى أَنَّ النَّاقِضَ لَهَا هُوَ الْحَدَثُ، وَأَصْلُ هَذَا الْخِلَافِ هَلْ وُجُودُ الْمَاءِ يَرْفَعُ اسْتِصْحَابَ الطَّهَارَةِ الَّتِي كَانَتْ بِالتُّرَابِ، أَوْ يَرْفَعُ ابْتِدَاءَ الطَّهَارَةِ بِهِ؟","src":"بداية المجتهد","loc":"١/٧٨","pre":"قال ابن رشد:"},{"t":"h","text":"وجود الماء في أثناء الصلاة"},{"t":"qawl","label":"القول الأول","text":"يمضي في صلاته ولا تبطل، وهو قول مالك والشافعي وداود."},{"t":"qawl","label":"القول الثاني","text":"تبطل صلاته فيتطهر ويستأنفها، وهو قول أبي حنيفة وأحمد في المشهور عنه."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ويبطل التيمم بكل ما يبطل الوضوء، وبالقدرة على استعمال الماء أو وجوده إن كان معدوما","src":"فتاوى اللجنة الدائمة","loc":"٢٤/٤٠٧","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من صلى بالتيمم ثم وجد الماء بعد الفراغ لا يعيد؛ لقوله ﷺ للذي لم يعد: «أصبت السنة وأجزأتك صلاتك»، ولأنه أدى ما أُمر به. وأما من وجد الماء في أثناء الصلاة فالأقوى قول أبي حنيفة وأحمد: أنه يقطعها ويتطهر ويستأنف؛ لأن وجود الماء ناقض للتيمم، فلا فرق بين أن يطرأ في الصلاة أو خارجها، كما رجحه ابن رشد المالكي نفسه."},{"t":"tanbih","items":[{"t":"p","text":"من كان الماء قريبًا منه ويرجو وجوده قبل خروج الوقت، فالأفضل أن يؤخر الصلاة إلى آخر وقتها المختار ليصلي بالماء، ومن تيمم وصلى في أول الوقت جاز."}]}],"refs":["أبو داود ٣٣٨، والنسائي ٤٣٣","بداية المجتهد (١/٧٨)","بداية المجتهد (١/٧٩)","فتاوى اللجنة الدائمة (٢٤/٤٠٧)"],"related":["هل يجب التيمم لكل صلاة، أم يصلي بالتيمم الواحد ما شاء؟"],"alts":["إعادة الصلاة بعد التيمم","وجود الماء بعد التيمم","وجد الماء أثناء الصلاة"]},{"n":59,"bab":"الطهارة","sub":"الحيض والنفاس","title":"أقل الحيض وأكثره، وأقل الطهر بين الحيضتين","q":"عادتي في الحيض تختلف: مرة ثلاثة أيام ومرة عشرة ومرة أكثر، فما أقل الحيض وأكثره؟ ومتى أعدّ الدم استحاضة؟","short":"اختلف الفقهاء في تحديد أقل الحيض وأكثره: فأقله عند أبي حنيفة ثلاثة أيام وأكثره عشرة، وعند الشافعي وأحمد أقله يوم وليلة وأكثره خمسة عشر يومًا، ولا حد لأقله عند مالك. ولم يثبت في التحديد حديث صحيح، فالمرجع فيه إلى عادة المرأة: فما رأته من الدم المعروف في وقت عادتها فهو حيض، فإن استمر بها الدم أكثر الشهر فهي مستحاضة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قَالَتْ فَاطِمَةُ بِنْتُ أَبِي حُبَيْشٍ لِرَسُولِ اللَّهِ صلى الله عليه وسلم يَا رَسُولَ اللَّهِ إِنِّي لاَ أَطْهُرُ، أَفَأَدَعُ الصَّلاَةَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّمَا ذَلِكِ عِرْقٌ وَلَيْسَ بِالْحَيْضَةِ، فَإِذَا أَقْبَلَتِ الْحَيْضَةُ فَاتْرُكِي الصَّلاَةَ، فَإِذَا ذَهَبَ قَدْرُهَا فَاغْسِلِي عَنْكِ الدَّمَ وَصَلِّي»","src":"رواه البخاري ٣٠٦","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":306,"id":"h306"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أقل الحيض ثلاثة أيام، وأكثره عشرة أيام، وهو قول أبي حنيفة وأصحابه."},{"t":"qawl","label":"القول الثاني","text":"أقله يوم وليلة، وأكثره خمسة عشر يومًا، وهو قول الشافعي وأحمد."},{"t":"qawl","label":"القول الثالث","text":"لا حد لأقله، فقد تكون الدفعة الواحدة حيضًا، وأكثره خمسة عشر يومًا، وهو قول مالك."},{"t":"qawl","label":"القول الرابع","text":"لا حد لأقله ولا لأكثره، والمرجع إلى العادة، وهو اختيار ابن تيمية وجماعة من المحققين."},{"t":"quote","text":"اختلف العلماء في أكثر أيام الحيض وأقلها، وأقل أيام الطهر فروي عن مالك أن أكثر أيام الحيض خمسة عشر يوما، وبه قال الشافعي وقال أبو حنيفة: أكثره عشرة أيام، وأما أقل أيام الحيض فلا حد لها عند مالك، بل قد تكون الدفعة الواحدة عنده حيضا، إلا أنه لا يعتد بها في الأقراء في الطلاق، وقال الشافعي: أقله يوم وليلة وقال أبو حنيفة: أقله ثلاثة أيام.","src":"بداية المجتهد","loc":"١/٥٦","pre":"قال ابن رشد:"},{"t":"quote","text":"وَأَمَّا) الثَّانِي فَذَكَرَ فِي ظَاهِرِ الرِّوَايَةِ أَنَّ أَقَلَّ الْحَيْضِ ثَلَاثَةُ أَيَّامٍ، وَلَيَالِيهَا، وَحُكِيَ عَنْ أَبِي يُوسُفَ فِي النَّوَادِرِ يَوْمَانِ، وَأَكْثَرُ الْيَوْمِ الثَّالِثِ","src":"بدائع الصنائع","loc":"١/٤٠","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ليس لأقل الحيض ولا لأكثره حد بالأيام على الصحيح","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٧١","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله: هل لأقل الحيض وأكثره حد معلوم بالأيام؟ فقال:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"قال العلماء: إن أقل مدة الحيض وأكثرها ليس فيه المرفوع لأحد من المذاهب، ولنا أثر أنس، وللشوافع أثر عطاء بن أبي رباح","src":"العرف الشذي","loc":"١/١٥٠","pre":"وقال الشيخ محمد أنور شاه الكشميري الحنفي:"},{"t":"quote","text":"وَمِنْ ذَلِكَ اسْمُ الْحَيْضِ عَلَّقَ اللَّهُ بِهِ أَحْكَامًا مُتَعَدِّدَةً فِي الْكِتَابِ وَالسُّنَّةِ وَلَمْ يُقَدَّرْ لَا أَقَلُّهُ وَلَا أَكْثَرُهُ وَلَا الطُّهْرُ بَيْنَ الْحَيْضَتَيْنِ مَعَ عُمُومِ بَلْوَى الْأُمَّةِ بِذَلِكَ وَاحْتِيَاجِهِمْ إلَيْهِ وَاللُّغَةُ لَا تُفَرِّقُ بَيْنَ قَدْرٍ وَقَدْرٍ فَمَنْ قَدَّرَ فِي ذَلِكَ حَدًّا فَقَدْ خَالَفَ الْكِتَابَ وَالسُّنَّةَ وَالْعُلَمَاءُ مِنْهُمْ مَنْ يَحُدُّ أَكْثَرَهُ وَأَقَلَّهُ ثُمَّ يَخْتَلِفُونَ فِي التَّحْدِيدِ. وَمِنْهُمْ مَنْ يَحُدُّ أَكْثَرَهُ دُونَ أَقَلِّهِ وَالْقَوْلُ الثَّالِثُ أَصَحُّ: أَنَّهُ لَا حَدَّ لَا لِأَقَلِّهِ وَلَا لِأَكْثَرِهِ بَلْ مَا رَأَتْهُ الْمَرْأَةُ عَادَةً مُسْتَمِرَّةً فَهُوَ حَيْضٌ. وَإِنْ قُدِّرَ أَنَّهُ أَقَلُّ مِنْ يَوْمٍ اسْتَمَرَّ بِهَا عَلَى ذَلِكَ فَهُوَ حَيْضٌ. وَإِنْ قُدِّرَ أَنَّ أَكْثَرَهُ سَبْعَةَ عَشَرَ اسْتَمَرَّ بِهَا عَلَى ذَلِكَ فَهُوَ حَيْضٌ. وَأَمَّا إذَا اسْتَمَرَّ الدَّمُ بِهَا دَائِمًا فَهَذَا قَدْ عُلِمَ أَنَّهُ لَيْسَ بِحَيْضِ لِأَنَّهُ قَدْ عُلِمَ مِنْ الشَّرْعِ وَاللُّغَةِ أَنَّ الْمَرْأَةَ تَارَةً تَكُونُ طَاهِرًا وَتَارَةً تَكُونُ حَائِضًا وَلِطُهْرِهَا أَحْكَامٌ وَلِحَيْضِهَا أَحْكَامٌ","src":"مجموع الفتاوى","loc":"١٩/٢٣٧","pre":"وقال ابن تيمية:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه لم يثبت في تحديد أقل الحيض وأكثره نص من الكتاب ولا من السنة الصحيحة، كما صرح به الكشميري الحنفي وابن رشد المالكي وابن تيمية، وأن النبي ﷺ رد المرأة إلى «قدرها» وعادتها؛ فما رأته المرأة من الدم المعروف في وقت عادتها فهو حيض، قلّ أو كثر، فإن زاد على عادتها قليلًا وهو بصفته فهو حيض، فإذا استمر بها الدم كل الشهر أو أكثره فهي مستحاضة، ترجع إلى عادتها، فإن لم تكن لها عادة رجعت إلى صفة الدم وتمييزه."},{"t":"p","text":"ومن أخذت بتحديد مذهبها احتياطًا لدينها فلا حرج عليها؛ فإنه قول أئمة متبوعين، وإنما الكلام هنا في الأقرب إلى الدليل."},{"t":"tanbih","items":[{"t":"p","text":"أكثر الطهر بين الحيضتين لا حد له باتفاق العلماء؛ فمن النساء من تحيض في الشهر مرة، ومنهن من لا تحيض إلا بعد شهور."}]}],"refs":["البخاري ٣٠٦","بداية المجتهد (١/٥٦)","بدائع الصنائع (١/٤٠)","مجموع فتاوى ابن عثيمين (١١/٢٧١)","بداية المجتهد (١/٥٧)","العرف الشذي (١/١٥٠)","مجموع الفتاوى (١٩/٢٣٧)"],"related":["المستحاضة: كيف تعرف حيضها؟ وكيف تتطهر للصلاة؟"],"alts":["مدة الحيض","أكثر الحيض عشرة أيام","أقل الحيض","زيادة العادة"]},{"n":60,"bab":"الطهارة","sub":"الحيض والنفاس","title":"ما يحرم على الحائض، وهل تقضي الصلاة والصوم؟","q":"ما الذي يحرم على المرأة في أيام حيضها؟ وهل تقضي ما فاتها من الصلاة والصيام؟","short":"اتفق المسلمون على أن الحيض يمنع الصلاة والصوم والطواف بالبيت والجماع في الفرج، وأن الحائض تقضي الصوم ولا تقضي الصلاة.","body":[{"t":"h","text":"الدليل من الكتاب"},{"t":"aya","text":"وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ","ref":"البقرة: ٢٢٢"},{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَلَيْسَ إِذَا حَاضَتْ لَمْ تُصَلِّ وَلَمْ تَصُمْ","src":"رواه البخاري ٣٠٤","pre":"عن أبي سعيد الخدري رضي الله عنه أن النبي ﷺ قال للنساء:","links":[{"book":"mt_bukhari","num":304,"id":"h304"}]},{"t":"quote","text":"سَأَلْتُ عَائِشَةَ فَقُلْتُ: مَا بَالُ الْحَائِضِ تَقْضِي الصَّوْمَ، وَلَا تَقْضِي الصَّلَاةَ. فَقَالَتْ: أَحَرُورِيَّةٌ أَنْتِ؟ قُلْتُ: لَسْتُ بِحَرُورِيَّةٍ، وَلَكِنِّي أَسْأَلُ. قَالَتْ: «كَانَ يُصِيبُنَا ذَلِكَ، فَنُؤْمَرُ بِقَضَاءِ الصَّوْمِ، وَلَا نُؤْمَرُ بِقَضَاءِ الصَّلَاةِ»","src":"رواه مسلم ٣٣٥","pre":"وعن معاذة قالت:","links":[{"book":"mt_muslim","num":335,"id":"h335-3"}]},{"t":"quote","text":"افْعَلِي مَا يَفْعَلُ الْحَاجُّ، غَيْرَ أَنْ لاَ تَطُوفِي بِالْبَيْتِ حَتَّى تَطْهُرِي","src":"رواه البخاري ٣٠٥","pre":"وعن عائشة رضي الله عنها أن النبي ﷺ قال لها لما حاضت في الحج:","links":[{"book":"mt_bukhari","num":305,"id":"h305"}]},{"t":"h","text":"محل الاتفاق"},{"t":"p","text":"اتفق المسلمون على أن الحيض يمنع أربعة أشياء: فعل الصلاة ووجوبها فلا تقضيها الحائض، وفعل الصوم دون قضائه فتقضيه بعد طهرها، والطواف بالبيت، والجماع في الفرج؛ لحديث عائشة رضي الله عنها: كنا نؤمر بقضاء الصوم ولا نؤمر بقضاء الصلاة، ولقوله تعالى في آية المحيض بالأمر باعتزال النساء فيه. ولم يخالف في قضاء الصلاة إلا طائفة من الخوارج. واختلفوا في مس المصحف وقراءة القرآن واللبث في المسجد، وسيأتي تفصيلها."},{"t":"quote","text":"أجمع أهل السنة والجماعة على قضاء الصوم لها لا الصلاة، وأوجب الخوارج قضاء الصلاة أيضاً، ثم تكلم العلماء في حكمة عدم قضاء الصلاة والصوم، فقيل: لما هبطت حواء على الأرض حاضت فسألت آدم وسأل آدم الله تعالى فعفا الله عن الصلاة، ثم قاس آدم الصوم على الصلاة فعاتب الله تعالى، وأمر بالقضاء عتاباً، والله أعلم هذه القصة ثابتة أم لا وأقول: يمكن أن يقال: إن الطهارة شرط الصلاة لا الصوم، نعم عدم الطهارة مانعة من الصوم، وأيضاً في قضاء الصلوات مشقة لا في قضاء الصوم","src":"العرف الشذي","loc":"١/١٥٢","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يحرم على الحائض والنفساء: الصلاة فرضًا ونفلًا، والصوم، والطواف بالبيت، ويحرم على زوجها جماعها في الفرج؛ وتقضي الصوم دون الصلاة بإجماع أهل السنة، تيسيرًا من الله لتكرر الصلاة وكثرتها. ويجوز لها ما سوى ذلك: من الذكر والدعاء والاستغفار، وحضور مجالس العلم، وسائر مناسك الحج غير الطواف. وأما قراءتها القرآن ومسها المصحف ومكثها في المسجد ففيها خلاف يأتي."},{"t":"tanbih","items":[{"t":"p","text":"إذا طهرت الحائض قبل خروج وقت الصلاة بقدر ما تدرك فيه ركعة وجبت عليها تلك الصلاة؛ وألحق بها جمهور العلماء صلاة الظهر إذا طهرت في وقت العصر، والمغرب إذا طهرت في وقت العشاء، لأن وقتهما واحد عند العذر."}]}],"refs":["البخاري ٣٠٤","مسلم ٣٣٥","البخاري ٣٠٥","العرف الشذي (١/١٥٢)"],"related":["قراءة الحائض القرآن ومسها المصحف","مباشرة الحائض والاستمتاع بها"],"alts":["الحائض والصلاة","قضاء الصلاة للحائض","الحائض والصيام","طواف الحائض"]},{"n":61,"bab":"الطهارة","sub":"الحيض والنفاس","title":"قراءة الحائض القرآن ومسها المصحف","q":"أنا معلمة قرآن وطالبة حفظ، فهل يجوز لي أن أقرأ القرآن أيام الحيض؟ وهل أمس المصحف؟","short":"الجمهور (أبو حنيفة والشافعي وأحمد في المشهور) على منع الحائض من قراءة القرآن كالجنب، وأجازها مالك، وهو رواية عن أحمد واختيار ابن تيمية؛ لطول مدتها وخوف النسيان وضعف حديث المنع. وأما مس المصحف فيمنعه الجمهور، فتقرأ من حفظها أو تمسه بحائل.","body":[{"t":"h","text":"الدليل"},{"t":"p","text":"استدل المانعون بحديث ابن عمر: «لا تقرأ الحائض ولا الجنب شيئًا من القرآن» (رواه الترمذي ١٣١)، وبالقياس على الجنب."},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَتَّكِئُ فِي حِجْرِي وَأَنَا حَائِضٌ، فَيَقْرَأُ الْقُرْآنَ","src":"رواه مسلم ٣٠١","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":301,"id":"h301"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يحرم على الحائض قراءة القرآن كالجنب، وهو قول أبي حنيفة والشافعي وأحمد في المشهور عنه."},{"t":"qawl","label":"القول الثاني","text":"يجوز للحائض أن تقرأ القرآن دون الجنب، مطلقًا أو إذا خافت النسيان، وهو قول مالك، ورواية عن أحمد، واختيار ابن تيمية."},{"t":"quote","text":"وَلَا يَقْرَأُ الْقُرْآنَ جُنُبٌ وَلَا حَائِضٌ وَلَا نُفَسَاءُ رُوِيت الْكَرَاهِيَةُ لِذَلِكَ عَنْ عُمَرَ وَعَلِيٍّ وَالْحَسَنِ وَالنَّخَعِيِّ وَالزُّهْرِيِّ وَقَتَادَةِ وَالشَّافِعِيِّ وَأَصْحَابِ الرَّأْيِ. وَقَالَ الْأَوْزَاعِيُّ لَا يَقْرَأُ إلَّا آيَةَ الرُّكُوبِ وَالنُّزُولِ: {سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا} الزخرف: 13 ، {وَقُلْ رَبِّ أَنْزِلْنِي مُنْزَلا مُبَارَكًا} المؤمنون: 29 وَقَالَ ابْنُ عَبَّاسٍ يَقْرَأُ وِرْدَهُ. وَقَالَ سَعِيدُ بْنُ الْمُسَيِّبِ: يَقْرَأُ الْقُرْآنَ، أَلَيْسَ هُوَ فِي جَوْفِهِ، وَحُكِيَ عَنْ مَالِكٍ لِلْحَائِضِ الْقِرَاءَةُ دُونَ الْجُنُبِ؛ لِأَنَّ أَيَّامَهَا تَطُولُ، فَإِنْ مَنَعْنَاهَا مِنْ الْقِرَاءَةِ نَسِيَتْ. وَلَنَا: مَا رُوِيَ عَنْ عَلِيٍّ، - رَضِيَ اللَّهُ عَنْهُ - «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لَمْ يَكُنْ يَحْجُبُهُ، أَوْ قَالَ: يَحْجِزُهُ، عَنْ قِرَاءَةِ الْقُرْآنِ شَيْءٌ، لَيْسَ الْجَنَابَةُ.» رَوَاهُ أَبُو دَاوُد، وَالنَّسَائِيُّ، وَالتِّرْمِذِيُّ، وَقَالَ: حَدِيثٌ حَسَنٌ صَحِيحٌ. وَعَنْ ابْنِ عُمَرَ، «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: لَا تَقْرَأُ الْحَائِضُ وَلَا الْجُنُبُ شَيْئًا مِنْ الْقُرْآنِ.» رَوَاهُ أَبُو دَاوُد، وَالتِّرْمِذِيُّ. وَقَالَ: يَرْوِيهِ إسْمَاعِيلُ بْنُ عَيَّاشٍ عَنْ نَافِعٍ، وَقَدْ ضَعَّفَ، الْبُخَارِيُّ رِوَايَتَهُ عَنْ أَهْلِ الْحِجَازِ، وَقَالَ: إنَّمَا رِوَايَتُهُ عَنْ أَهْلِ الشَّامِ. وَإِذَا ثَبَتَ هَذَا فِي الْجُنُبِ فَفِي الْحَائِضِ أَوْلَى؛ لِأَنَّ حَدَثَهَا آكَدُ، وَلِذَلِكَ حَرَّمَ الْوَطْءَ، وَمَنَعَ الصِّيَامَ، وَأَسْقَطَ الصَّلَاةَ، وَسَاوَاهَا فِي سَائِرِ أَحْكَامِهَا","src":"المغني","loc":"١/١٠٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَقَوْمٌ جَعَلُوا الْحَائِضَ فِي هَذَا الِاخْتِلَافِ بِمَنْزِلَةِ الْجُنُبِ، وَقَوْمٌ فَرَّقُوا بَيْنَهُمَا، فَأَجَازُوا لِلْحَائِضِ الْقِرَاءَةَ الْقَلِيلَةَ اسْتِحْسَانًا؛ لِطُولِ مَقَامِهَا حَائِضًا، وَهُوَ مَذْهَبُ مَالِكٍ","src":"بداية المجتهد","loc":"١/٥٥","pre":"وقال ابن رشد:"},{"t":"quote","text":"فَإِنَّ قِرَاءَةَ الْحَائِضِ الْقُرْآنَ لَمْ يَثْبُتْ عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ شَيْءٌ غَيْرَ الْحَدِيثِ الْمَرْوِيِّ عَنْ إسْمَاعِيلَ بْنِ عَيَّاشٍ عَنْ مُوسَى بْنِ عُقْبَةَ عَنْ نَافِعٍ عَنْ ابْنِ عُمَرَ {لَا تَقْرَأْ الْحَائِضُ وَلَا الْجُنُبُ مِنْ الْقُرْآنِ شَيْئًا} رَوَاهُ أَبُو دَاوُد وَغَيْرُهُ. وَهُوَ حَدِيثٌ ضَعِيفٌ بِاتِّفَاقِ أَهْلِ الْمَعْرِفَةِ بِالْحَدِيثِ. وَإِسْمَاعِيلُ بْنُ عَيَّاشٍ مَا يَرْوِيهِ عَنْ الْحِجَازِيِّينَ أَحَادِيثُ ضَعِيفَةٌ؛ بِخِلَافِ رِوَايَتِهِ عَنْ الشَّامِيِّينَ وَلَمْ يَرْوِ هَذَا عَنْ نَافِعٍ أَحَدٌ مِنْ الثِّقَاتِ وَمَعْلُومٌ أَنَّ النِّسَاءَ كُنَّ يَحِضْنَ عَلَى عَهْدِ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَلَمْ يَكُنْ يَنْهَاهُنَّ عَنْ قِرَاءَةِ الْقُرْآنِ. كَمَا لَمْ يَكُنْ يَنْهَاهُنَّ عَنْ الذِّكْرِ وَالدُّعَاءِ بَلْ أَمَرَ الْحُيَّضَ أَنْ يَخْرُجْنَ يَوْمَ الْعِيدِ فَيُكَبِّرُونَ بِتَكْبِيرِ الْمُسْلِمِينَ. وَأَمَرَ الْحَائِضَ أَنْ تَقْضِيَ الْمَنَاسِكَ كُلَّهَا إلَّا الطَّوَافَ بِالْبَيْتِ: تُلَبِّي وَهِيَ حَائِضٌ وَكَذَلِكَ بمزدلفة وَمِنًى وَغَيْرِ ذَلِكَ مِنْ الْمَشَاعِرِ. وَأَمَّا الْجُنُبُ فَلَمْ يَأْمُرْهُ أَنْ يَشْهَدَ الْعِيدَ وَلَا يُصَلِّيَ وَلَا أَنْ يَقْضِيَ شَيْئًا مِنْ الْمَنَاسِكِ: لِأَنَّ الْجُنُبَ يُمْكِنُهُ أَنْ يَتَطَهَّرَ فَلَا عُذْرَ لَهُ فِي تَرْكِ الطَّهَارَةِ بِخِلَافِ الْحَائِضِ فَإِنَّ حَدَثَهَا قَائِمٌ لَا يُمْكِنُهَا مَعَ ذَلِكَ التَّطَهُّرُ. وَلِهَذَا ذَكَرَ الْعُلَمَاءُ لَيْسَ لِلْجُنُبِ أَنْ يَقِفَ بِعَرَفَةَ وَمُزْدَلِفَةَ وَمِنًى حَتَّى يَطَّهَّرَ وَإِنْ كَانَتْ الطَّهَارَةُ لَيْسَتْ شَرْطًا فِي ذَلِكَ. لَكِنَّ الْمَقْصُودَ أَنَّ الشَّارِعَ أَمَرَ الْحَائِضَ أَمْرَ إيجَابٍ أَوْ اسْتِحْبَابٍ بِذِكْرِ اللَّهِ وَدُعَائِهِ مَعَ كَرَاهَةِ ذَلِكَ لِلْجُنُبِ. فَعُلِمَ أَنَّ الْحَائِضَ يُرَخَّصُ لَهَا فِيمَا لَا يُرَخَّصُ لِلْجُنُبِ فِيهِ؛ لِأَجْلِ الْعُذْرِ","src":"مجموع الفتاوى","loc":"٢١/٤٦٠-٤٦١","pre":"وقال ابن تيمية:"},{"t":"h","text":"مس المصحف"},{"t":"p","text":"جمهور العلماء ومنهم الأئمة الأربعة على أن المحدث لا يمس المصحف، والحائض من باب أولى؛ لحديث عمرو بن حزم في الكتاب الذي كتبه له النبي ﷺ: «ألا يمس القرآن إلا طاهر»، رواه مالك في الموطأ."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"اختلف العلماء رحمة الله عليهم في قراءة الحائض والنفساء للقرآن الكريم: فذهب جماعة من أهل العلم إلى تحريم ذلك وألحقوهما بالجنب، وقالوا: ثبت عن النبي صلى الله عليه وسلم أن الجنب لا يقرأ القرآن، لأن الجنابة حدث أكبر، والحيض مثل ذلك، والنفاس مثل ذلك فقالوا: لا تقرأ الحائض ولا النفساء حتى تطهرا، واحتجوا أيضا بحديث رواه الترمذي عن ابن عمر رضي الله عنهما قال: «لا تقرأ الحائض ولا الجنب شيئا من القرآن»","src":"مجموع فتاوى ابن باز","loc":"٦/٣٦٠","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"وذهب آخرون من أهل العلم إلى أنه يجوز للحائض والنفساء قراءة القرآن عن ظهر قلب؛ لأن مدتهما تطول أياما كثيرة فلا يصح قياسهما على الجنب؛ لأن مدته قصيرة؛ لأن في إمكانه إذا فرغ من حاجته أن يغتسل ويقرأ، أما الحائض والنفساء فليس في إمكانها ذلك","src":"مجموع فتاوى ابن باز","loc":"٦/٣٦٠","pre":"ثم قال:"},{"t":"quote","text":"فأما قراءة الحائض القرآن الكريم بنفسها، فإن كان نظراً بالعين أو تأملاً بالقلب بدون نطق باللسان فلا بأس بذلك","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٣١٠","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الحائض يجوز لها أن تقرأ القرآن من حفظها، ولا سيما المعلمة والمتعلمة ومن تخاف النسيان؛ لأن حديث المنع ضعيف باتفاق أهل الحديث، والحيض يطول ولا تملك المرأة رفعه بخلاف الجنابة، وكان النساء يحضن على عهد النبي ﷺ ولم يُنقل أنه نهاهن عن القراءة. وأما مس المصحف فتتجنبه، وتقرأ من حفظها، أو تمسك المصحف بحائل منفصل كقفاز أو منديل، أو تقرأ من شاشة الهاتف والحاسوب."},{"t":"p","text":"ومن احتاطت فاقتصرت على الذكر والدعاء خروجًا من خلاف الجمهور فقد أخذت بالأحوط."}],"refs":["مسلم ٣٠١","المغني (١/١٠٦)","بداية المجتهد (١/٥٥)","مجموع الفتاوى (٢١/٤٦٠-٤٦١)","مجموع فتاوى ابن باز (٦/٣٦٠)","مجموع فتاوى ابن عثيمين (١١/٣١٠)"],"related":["قراءة القرآن للجنب","ما يحرم على الحائض، وهل تقضي الصلاة والصوم؟"],"alts":["الحائض تقرأ القرآن","مس المصحف للحائض","الحائض وحفظ القرآن","معلمة القرآن الحائض"]},{"n":62,"bab":"الطهارة","sub":"الحيض والنفاس","title":"مباشرة الحائض والاستمتاع بها فيما دون الفرج","q":"ما الذي يجوز للرجل من زوجته وهي حائض؟ وهل يجتنبها كلها؟","short":"يحرم الجماع في الفرج زمن الحيض بالإجماع، ويجوز الاستمتاع بما فوق السرة وتحت الركبة بالإجماع؛ واختلفوا فيما بين السرة والركبة: فمنعه أبو حنيفة ومالك والشافعي، وأجازه أحمد ومحمد بن الحسن والثوري مع اجتناب الفرج. والأحوط أن يكون ذلك من فوق إزار.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ الْيَهُودَ كَانُوا إِذَا حَاضَتِ الْمَرْأَةُ فِيهِمْ لَمْ يُؤَاكِلُوهَا، وَلَمْ يُجَامِعُوهُنَّ فِي الْبُيُوتِ فَسَأَلَ أَصْحَابُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَنْزَلَ اللهُ تَعَالَى {وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ} [البقرة: 222] إِلَى آخِرِ الْآيَةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «اصْنَعُوا كُلَّ شَيْءٍ إِلَّا النِّكَاحَ»","src":"رواه مسلم ٣٠٢","pre":"عن أنس رضي الله عنه:","links":[{"book":"mt_muslim","num":302,"id":"h302"}]},{"t":"quote","text":"كَانَتْ إِحْدَانَا إِذَا كَانَتْ حَائِضًا، فَأَرَادَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُبَاشِرَهَا، أَمَرَهَا أَنْ تَتَّزِرَ فِي فَوْرِ حَيْضَتِهَا ثُمَّ يُبَاشِرُهَا. قَالَتْ وَأَيُّكُمْ يَمْلِكُ إِرْبَهُ كَمَا كَانَ النَّبِيُّ صلى الله عليه وسلم يَمْلِكُ إِرْبَهُ","src":"رواه البخاري ٣٠٢","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":302,"id":"h302"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"له منها ما فوق الإزار فقط، ويجتنب ما بين السرة والركبة، وهو قول أبي حنيفة ومالك والشافعي."},{"t":"qawl","label":"القول الثاني","text":"يجتنب موضع الدم وحده، ويستمتع بما سواه، وهو قول الثوري وأحمد ومحمد بن الحسن وداود."},{"t":"quote","text":"اخْتَلَفَ الْفُقَهَاءُ فِي مُبَاشَرَةِ الْحَائِضِ وَمَا يُسْتَبَاحُ مِنْهَا، فَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو حَنِيفَةَ: لَهُ مِنْهَا مَا فَوْقَ الْإِزَارِ فَقَطْ. وَقَالَ سُفْيَانُ الثَّوْرِيُّ وَدَاوُدُ الظَّاهِرِيُّ: إِنَّمَا يَجِبُ عَلَيْهِ أَنْ يَجْتَنِبَ مَوْضِعَ الدَّمِ فَقَطْ","src":"بداية المجتهد","loc":"١/٦٢","pre":"قال ابن رشد:"},{"t":"quote","text":"مذهب أبي حنيفة والشافعي عدم جواز الاستمتاع من السرة إلى الركبة، ومذهب أحمد ومحمد أنه يتقي موضع الدم، وحديث الباب للجمهور، ويجوز لهما حمله على الاستحباب ولهما ما في مسلم: «اصنعوا كل شيء إلا النكاح» وقيل: إن الرجحان لمذهبهما","src":"العرف الشذي","loc":"١/١٥٤","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المحرم هو الجماع في الفرج وحده؛ لقوله ﷺ: «اصنعوا كل شيء إلا النكاح»، وهو نص صريح صحيح، والآية علّلت بالأذى وهو في موضع الدم؛ وأما أمره ﷺ لزوجاته بالاتزار فمحمول على الأكمل والأحوط، لا على التحريم، كما مال إليه من حكى الكشميري عنهم الرجحان. ومن لم يأمن على نفسه الوقوع في الحرام فالواجب عليه أن يبتعد عما بين السرة والركبة؛ لقول عائشة رضي الله عنها: «وأيكم يملك إربه»."},{"t":"tanbih","items":[{"t":"p","text":"الحائض طاهرة البدن، يجوز مؤاكلتها ومضاجعتها ولمسها وأن تطبخ وتعجن؛ وما كان يفعله اليهود من اعتزالها في البيت مخالف للسنة."}]}],"refs":["مسلم ٣٠٢","البخاري ٣٠٢","بداية المجتهد (١/٦٢)","العرف الشذي (١/١٥٤)","بداية المجتهد (١/٦٢-٦٣)"],"related":["كفارة وطء الحائض","وطء الحائض بعد انقطاع الدم وقبل الاغتسال"],"alts":["الاستمتاع بالحائض","ما يحل من الحائض","مضاجعة الحائض","فوق الإزار"]},{"n":63,"bab":"الطهارة","sub":"الحيض والنفاس","title":"وطء الحائض بعد انقطاع الدم وقبل الاغتسال","q":"انقطع دم زوجتي ولم تغتسل بعد، فهل يجوز لي جماعها قبل أن تغتسل؟","short":"لا يجوز جماع الحائض بعد انقطاع الدم حتى تغتسل عند جمهور العلماء: مالك والشافعي وأحمد؛ وأجازه أبو حنيفة إذا انقطع الدم لأكثر الحيض (عشرة أيام)، أو مضى عليها وقت صلاة كامل إذا انقطع لأقل من ذلك. والأحوط والأظهر قول الجمهور.","body":[{"t":"h","text":"الدليل من الكتاب"},{"t":"aya","text":"وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ","ref":"البقرة: ٢٢٢"},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجوز حتى تغتسل، فإن عجزت عن الماء تيممت، وهو قول مالك والشافعي وأحمد والجمهور."},{"t":"qawl","label":"القول الثاني","text":"يجوز إذا انقطع الدم لأكثر الحيض، أو انقطع لدونه ومضى عليها وقت صلاة، وهو قول أبي حنيفة وأصحابه."},{"t":"qawl","label":"القول الثالث","text":"يجوز إذا غسلت فرجها، وهو قول الأوزاعي وابن حزم."},{"t":"quote","text":"اخْتَلَفُوا فِي وَطْءِ الْحَائِضِ فِي طُهْرِهَا، وَقَبْلَ الِاغْتِسَالِ، فَذَهَبَ مَالِكٌ، وَالشَّافِعِيُّ وَالْجُمْهُورُ إِلَى أَنَّ ذَلِكَ لَا يَجُوزُ حَتَّى تَغْتَسِلَ، وَذَهَبَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ إِلَى أَنَّ ذَلِكَ جَائِزٌ إِذَا طَهُرَتْ لِأَكْثَرِ أَمَدِ الْحَيْضِ، وَهُوَ عِنْدَهُ عَشَرَةُ أَيَّامٍ، وَذَهَبَ الْأَوْزَاعِيُّ إِلَى أَنَّهَا إِنْ غَسَلَتْ فَرَجْهَا بِالْمَاءِ جَازَ وَطْؤُهَا (أَعْنِي كُلَّ حَائِضٍ طَهُرَتْ مَتَى طَهُرَتْ) وَبِهِ قَالَ أَبُو مُحَمَّدِ بْنُ حَزْمٍ","src":"بداية المجتهد","loc":"١/٦٣-٦٤","pre":"قال ابن رشد:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"أَمَّا الْمَرْأَةُ الْحَائِضُ إذَا انْقَطَعَ دَمُهَا فَلَا يَطَؤُهَا زَوْجُهَا حَتَّى تَغْتَسِلَ إذَا كَانَتْ قَادِرَةً عَلَى الِاغْتِسَالِ وَإِلَّا تَيَمَّمَتْ. كَمَا هُوَ مَذْهَبُ جُمْهُورِ الْعُلَمَاءِ كَمَالِكِ وَأَحْمَد وَالشَّافِعِيِّ. وَهَذَا مَعْنَى مَا يُرْوَى عَنْ الصَّحَابَةِ حَيْثُ رُوِيَ عَنْ بِضْعَةَ عَشَرَ مِنْ الصَّحَابَةِ - مِنْهُمْ الْخُلَفَاءُ - أَنَّهُمْ قَالُوا: فِي الْمُعْتَدَّةِ هُوَ أَحَقُّ بِهَا مَا لَمْ تَغْتَسِلْ مِنْ الْحَيْضَةِ الثَّالِثَةِ. وَالْقُرْآنُ يَدُلُّ عَلَى ذَلِكَ قَالَ اللَّهُ تَعَالَى: {وَلَا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ} قَالَ مُجَاهِدٌ: حَتَّى يَطْهُرْنَ يَعْنِي يَنْقَطِعُ الدَّمُ فَإِذَا تَطَهَّرْنَ اغْتَسَلْنَ بِالْمَاءِ وَهُوَ كَمَا قَالَ مُجَاهِدٌ","src":"مجموع الفتاوى","loc":"٢١/٦٢٤-٦٢٥","pre":"وقال ابن تيمية:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر قول الجمهور: أنه لا يجوز جماعها حتى تغتسل؛ لأن الله تعالى ذكر غايتين: ﴿حَتَّىٰ يَطْهُرْنَ﴾ وهو انقطاع الدم، ثم ﴿فَإِذَا تَطَهَّرْنَ﴾ وهو فعلها بالاغتسال، وصيغة التفعل تدل على فعل المكلفة، كما فسره مجاهد. ولقول أبي حنيفة وجه من اللغة كما بيّنه ابن رشد، لكن الأحوط في الفروج ألا يُقدم على الجماع إلا بعد الغسل، فإن عجزت عن الماء لمرض أو عدمه تيممت ثم حلت لزوجها."}],"refs":["بداية المجتهد (١/٦٣-٦٤)","بداية المجتهد (١/٦٤)","مجموع الفتاوى (٢١/٦٢٤-٦٢٥)"],"related":["مباشرة الحائض والاستمتاع بها فيما دون الفرج"],"alts":["الجماع قبل غسل الحيض","انقطاع الدم وعدم الاغتسال","وطء الحائض بعد الطهر"]},{"n":64,"bab":"الطهارة","sub":"الحيض والنفاس","title":"كفارة من جامع امرأته وهي حائض","q":"جامعت زوجتي وهي حائض، فما الواجب علي؟ وهل علي كفارة؟","short":"جماع الحائض في الفرج محرم بالإجماع، وعلى من فعله التوبة والاستغفار. واختلفوا في الكفارة: فلم يوجبها أبو حنيفة ومالك والشافعي في الجديد، وأوجبها أحمد في رواية: دينارًا أو نصف دينار. والأحوط أن يتصدق بذلك مع التوبة.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"فِي الَّذِي يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ قَالَ «يَتَصَدَّقُ بِدِينَارٍ أَوْ نِصْفِ دِينَارٍ»","src":"رواه أبو داود ٢٦٤","pre":"عن ابن عباس رضي الله عنهما عن النبي ﷺ:","links":[{"book":"mt_abudawud","num":264,"id":"h264"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يستغفر الله ولا كفارة عليه، وهو قول أبي حنيفة ومالك والشافعي."},{"t":"qawl","label":"القول الثاني","text":"يتصدق بدينار أو نصف دينار، وهو قول أحمد في رواية، والأوزاعي وإسحاق."},{"t":"quote","text":"اخْتَلَفَ الْفُقَهَاءُ فِي الَّذِي يَأْتِي امْرَأَتَهُ وَهِيَ حَائِضٌ، فَقَالَ مَالِكٌ، وَالشَّافِعِيُّ، وَأَبُو حَنِيفَةَ: يَسْتَغْفِرُ اللَّهَ وَلَا شَيْءَ عَلَيْهِ. وَقَالَ أَحْمَدُ بْنُ حَنْبَلٍ: يَتَصَدَّقُ بِدِينَارٍ أَوْ بِنِصْفِ دِينَارٍ. وَقَالَتْ فِرْقَةٌ مِنْ أَهْلِ الْحَدِيثِ: إِنْ وَطِئَ فِي الدَّمِ فَعَلَيْهِ دِينَارٌ، وَإِنْ وَطِئَ فِي انْقِطَاعِ الدَّمِ فَنِصْفُ دِينَارٍ","src":"بداية المجتهد","loc":"١/٦٥","pre":"قال ابن رشد:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"الحديث الأول منقطع، والحديث الثاني لم يحسنه أحد من المحدثين وفي سنده عبد الكريم بن أبي المخارق ضعيف، وأما المسألة فالكفارة مستحبة كما في الدر المختار والفتاوى الهندية","src":"العرف الشذي","loc":"١/١٥٧","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الواجب على من جامع زوجته وهي حائض أن يتوب إلى الله تعالى توبة صادقة، ويعزم ألا يعود؛ فإنه ارتكب ما حرمه الله في كتابه. والأحوط أن يتصدق بدينار (وهو نحو أربعة غرامات وربع من الذهب) أو نصفه؛ لحديث ابن عباس، وقد صحح وقفه ورفعه جماعة من أهل الحديث، وقد نص علماء الحنفية على استحبابه، فالعمل به جامع بين الأقوال. وعلى الزوجة مثل ذلك إن طاوعته مختارة."}],"refs":["أبو داود ٢٦٤","بداية المجتهد (١/٦٥)","العرف الشذي (١/١٥٧)"],"related":["مباشرة الحائض والاستمتاع بها فيما دون الفرج"],"alts":["جماع الحائض","كفارة الجماع في الحيض","الدينار ونصف الدينار"]},{"n":65,"bab":"الطهارة","sub":"الحيض والنفاس","title":"الصفرة والكدرة، وعلامة الطهر من الحيض","q":"أرى في آخر أيام حيضي إفرازات صفراء أو بنية، وأحيانًا بعد الطهر، فهل هي حيض؟ وكيف أعرف أني طهرت؟","short":"الصفرة والكدرة في أيام الحيض حيض عند جمهور العلماء، ومنهم أبو حنيفة ومالك والشافعي وأحمد؛ وما رأته بعد الطهر فليس بشيء، لحديث أم عطية. وعلامة الطهر: القَصّة البيضاء (سائل أبيض يخرج عند انتهاء الحيض)، أو الجفاف التام لمن لا ترى القصة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنَّا لاَ نَعُدُّ الْكُدْرَةَ وَالصُّفْرَةَ بَعْدَ الطُّهْرِ شَيْئًا","src":"رواه أبو داود ٣٠٧، والبخاري ٣٢٦","pre":"عن أم عطية رضي الله عنها، وكانت بايعت النبي ﷺ، قالت:","links":[{"book":"mt_abudawud","num":307,"id":"h307"},{"book":"mt_bukhari","num":326,"id":"h326"}]},{"t":"p","text":"وفي رواية البخاري: «كنا لا نعد الكدرة والصفرة شيئًا»، وقيدها أبو داود بقوله: «بعد الطهر»."},{"t":"p","text":"وذكر البخاري تعليقًا عن عائشة رضي الله عنها أن النساء كن يبعثن إليها بالدُّرجة فيها الكرسف فيه الصفرة، فتقول: «لا تعجلن حتى ترين القصة البيضاء»، تريد بذلك الطهر من الحيضة."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الصفرة والكدرة في أيام الحيض حيض، وبعد الطهر ليست بشيء، وهو قول أبي حنيفة ومالك والشافعي وأحمد والثوري والأوزاعي."},{"t":"qawl","label":"القول الثاني","text":"لا تكون الصفرة والكدرة حيضًا إلا إذا تقدمها دم، وهو قول أبي يوسف وأبي ثور وداود."},{"t":"qawl","label":"القول الثالث","text":"الصفرة والكدرة ليست حيضًا بحال، وهو مذهب ابن حزم."},{"t":"quote","text":"وَالصُّفْرَةُ وَالْكُدْرَةُ فِي أَيَّامِ الْحَيْضِ مِنْ الْحَيْضِ) يَعْنِي إذَا رَأَتْ فِي أَيَّامِ عَادَتِهَا صُفْرَةً أَوْ كُدْرَةً، فَهُوَ حَيْضٌ، وَإِنْ رَأَتْهُ بَعْدَ أَيَّامِ حَيْضِهَا، لَمْ يُعْتَدَّ بِهِ. نَصَّ عَلَيْهِ أَحْمَدُ. وَبِهِ قَالَ يَحْيَى الْأَنْصَارِيُّ، وَرَبِيعَةُ، وَمَالِكٌ، وَالثَّوْرِيُّ، وَالْأَوْزَاعِيُّ، وَعَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، وَالشَّافِعِيُّ، وَإِسْحَاقُ. وَقَالَ أَبُو يُوسُفَ، وَأَبُو ثَوْرٍ: لَا يَكُونُ حَيْضًا، إلَّا أَنْ يَتَقَدَّمَهُ دَمٌ أَسْوَدُ","src":"المغني","loc":"١/٢٤١","pre":"قال ابن قدامة:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فالصفرة والكدرة إن كانت في زمن العادة فحيض، وإن كانت في غير زمن العادة فليست بحيض","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٧٠","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"الصفرة والكدرة بعد الطهارة، لا يلتفت إليها، كالبول، تصلي وتصوم وتتوضأ لوقت كل صلاة، ولا تحسب حيضا","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٤٠٠","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر قول الجمهور: أن الصفرة والكدرة إذا كانت في زمن الحيض أو متصلة به قبل الطهر فهي حيض؛ لقول عائشة رضي الله عنها: «لا تعجلن حتى ترين القصة البيضاء»، وأما ما تراه المرأة بعد الطهر من صفرة أو كدرة فليس بشيء، تصلي وتصوم ولا تلتفت إليه، لحديث أم عطية؛ وبهذا يجتمع الحديثان. وعلامة الطهر القصة البيضاء لمن اعتادتها، والجفاف التام لمن لا تراها، بأن تحتشي بقطنة بيضاء فتخرج نقية."},{"t":"tanbih","items":[{"t":"p","text":"لا يلزم المرأة أن تقوم في جوف الليل لتنظر هل طهرت، لكن عليها أن تنظر عند أوقات الصلوات، فإذا رأت الطهر اغتسلت وصلت."}]}],"refs":["أبو داود ٣٠٧، والبخاري ٣٢٦","المغني (١/٢٤١)","مجموع فتاوى ابن عثيمين (١١/٢٧٠)","فتاوى نور على الدرب لابن باز (٥/٤٠٠)","بداية المجتهد (١/٥٩-٦٠)","بداية المجتهد (١/٦٠)"],"related":["أقل الحيض وأكثره، وأقل الطهر بين الحيضتين"],"alts":["الإفرازات بعد الحيض","القصة البيضاء","الكدرة البنية","علامة انتهاء الحيض"]},{"n":66,"bab":"الطهارة","sub":"الحيض والنفاس","title":"الدم الذي تراه الحامل، هل هو حيض؟","q":"أنا حامل ونزل مني دم في الشهر الثالث، فهل أترك الصلاة والصيام؟","short":"اختلف العلماء: فذهب أبو حنيفة وأحمد والثوري وجمهور التابعين إلى أن الحامل لا تحيض، وأن ما تراه دم فساد تصلي معه وتصوم؛ وذهب مالك والشافعي إلى أنه حيض إذا كان على صفة الحيض وفي وقته. والأظهر أن الدم إن كان بصفة الحيض المعتاد في وقته فهو حيض، وإلا فهو دم فساد. وما تراه قبيل الولادة مع الطلق فهو نفاس بالاتفاق.","body":[{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الحامل لا تحيض، وما تراه دم فساد وعلة لا يمنع الصلاة ولا الصوم، وهو قول أبي حنيفة وأحمد والثوري والأوزاعي، وجمهور التابعين."},{"t":"qawl","label":"القول الثاني","text":"الحامل قد تحيض، فما رأته من الدم في وقت عادتها وبصفة الحيض فهو حيض، وهو قول مالك والشافعي في أصح قوليه والليث، وروي عن عائشة رضي الله عنها."},{"t":"quote","text":"اختلف الفقهاء قديما وحديثا هل الدم الذي ترى الحامل هو حيض أم استحاضة؟ فذهب مالك والشافعي في أصح قوليه وغيرهما إلى أن الحامل تحيض وذهب أبو حنيفة وأحمد والثوري، وغيرهم إلى أَنَّ الْحَامِلَ لَا تَحِيضُ، وَأَنَّ الدَّمَ الظَّاهِرَ لَهَا دَمُ فَسَادٍ وَعِلَّةٍ، إِلَّا أَنْ يُصِيبَهَا الطَّلْقُ، فإنهم أَجْمَعُوا عَلَى أَنَّهُ دَمُ نِفَاسٍ، وَأَنَّ حُكْمَهُ حُكْمُ الْحَيْضِ فِي مَنْعِهِ الصَّلَاةَ وَغَيْرِ ذَلِكَ مِنْ أَحْكَامِهِ","src":"بداية المجتهد","loc":"١/٥٨-٥٩","pre":"قال ابن رشد:"},{"t":"quote","text":"مَذْهَبُ أَبِي عَبْدِ اللَّهِ - رَحِمَهُ اللَّهُ - أَنَّ الْحَامِلَ لَا تَحِيضُ، وَمَا تَرَاهُ مِنْ الدَّمِ فَهُوَ دَمُ فَسَادٍ وَهُوَ قَوْلُ جُمْهُورِ التَّابِعِينَ؛ مِنْهُمْ: سَعِيدُ بْنُ الْمُسَيِّبِ، وَعَطَاءٌ، وَالْحَسَنُ، وَجَابِرُ بْنُ زَيْدٍ وَعِكْرِمَةُ، وَمُحَمَّدُ بْنُ الْمُنْكَدِرِ، وَالشَّعْبِيُّ، وَمَكْحُولٌ وَحَمَّادٌ وَالثَّوْرِيُّ، وَالْأَوْزَاعِيُّ، وَأَبُو حَنِيفَةَ، وَابْنُ الْمُنْذِرِ وَأَبُو عُبَيْدٍ وَأَبُو ثَوْرٍ وَرُوِيَ عَنْ عَائِشَةَ - رَضِيَ اللَّهُ عَنْهَا - وَالصَّحِيحُ عَنْهَا أَنَّهَا إذَا رَأَتْ الدَّمَ لَا تُصَلِّي. وَقَالَ مَالِكٌ وَالشَّافِعِيُّ، وَاللَّيْثُ: مَا تَرَاهُ مِنْ الدَّمِ حَيْضٌ إذَا أَمْكَنَ وَرُوِيَ ذَلِكَ عَنْ الزُّهْرِيِّ، وَقَتَادَةَ، وَإِسْحَاقَ لِأَنَّهُ دَمٌ صَادَفَ عَادَةً، فَكَانَ حَيْضًا كَغَيْرِ الْحَامِلِ، وَلَنَا قَوْلُ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «لَا تُوطَأُ حَامِلٌ حَتَّى تَضَعَ وَلَا حَائِلٌ حَتَّى تُسْتَبْرَأَ بِحَيْضَةٍ» فَجَعَلَ وُجُودَ الْحَيْضِ عَلَمًا عَلَى بَرَاءَةِ الرَّحِمِ، فَدَلَّ ذَلِكَ عَلَى أَنَّهُ لَا يَجْتَمِعُ مَعَهُ","src":"المغني","loc":"١/٢٦١-٢٦٢","pre":"وقال ابن قدامة:"},{"t":"quote","text":"وَدَمُ الْحَامِلِ لَيْسَ بِحَيْضٍ، وَإِنْ كَانَ مُمْتَدًّا عِنْدَنَا وَقَالَ الشَّافِعِيُّ: هُوَ حَيْضٌ فِي حَقِّ تَرْكِ الصَّوْمِ، وَالصَّلَاةِ","src":"بدائع الصنائع","loc":"١/٤٢","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"quote","text":"وَقَدْ سَأَلْنَا مَالِكًا عَنْ الْحَامِلِ تَرَى الدَّمَ؟ قَالَ: هِيَ مِثْلُ غَيْرِ الْحَامِلَ تُمْسِكُ أَيَّامَ حَيْضَتِهَا كَمَا تُمْسِكُ الَّتِي هِيَ غَيْرُ حَامِلٍ قَالَ: ثُمَّ سَمِعْتُهُ بَعْدَ ذَلِكَ يَقُولُ: لَيْسَ أَوَّلُ الْحَمْلِ كَآخِرِهِ مِثْلُ رِوَايَةِ ابْنِ الْقَاسِمِ","src":"المدونة","loc":"١/١٥٥","pre":"وفي «المدونة» قال أشهب:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لأن دم الحامل يسمى نزيفًا، ليس بحيض على الصحيح؛ لأن الحامل لا تحيض","src":"فتاوى نور على الدرب لابن باز","loc":"٢٢/١٤٢","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الغالب في الحامل أنها لا تحيض، ولذلك جعل الشرع الحيض علامة على براءة الرحم في الاستبراء؛ فالأصل أن ما تراه الحامل من دم يسير متقطع أو نزيف عارض دم فساد، تتوضأ له وتصلي وتصوم. لكن إن رأت الحامل دمًا بصفة حيضها المعتاد، في وقت عادتها، بالمقدار المعتاد، فالأظهر أنه حيض؛ لأن الأصل في الدم الخارج من الرحم أنه حيض حتى يقوم دليل على خلافه، والوجود شاهد بذلك عند بعض النساء. وفي الحالين يحسن الرجوع إلى الطبيبة الثقة لمعرفة سبب الدم."},{"t":"tanbih","items":[{"t":"p","text":"الدم الذي تراه الحامل قبل الولادة بيوم أو يومين أو ثلاثة مع الطلق وعلامات الولادة نفاس، تترك له الصلاة والصوم؛ وأما الدم الخارج بسبب الإجهاض قبل أن يتبين في الجنين خلق الإنسان فليس بنفاس عند الجمهور، بل دم فساد أو حيض بحسب صفته."}]}],"refs":["بداية المجتهد (١/٥٨-٥٩)","المغني (١/٢٦١-٢٦٢)","بدائع الصنائع (١/٤٢)","المدونة (١/١٥٥)","فتاوى نور على الدرب لابن باز (٢٢/١٤٢)","بداية المجتهد (١/٥٩)"],"related":["أحكام النفاس: أكثره، والطهر قبل الأربعين"],"alts":["نزول الدم على الحامل","هل تحيض الحامل","الحامل والصلاة","الإجهاض والنفاس"]},{"n":67,"bab":"الطهارة","sub":"الحيض والنفاس","title":"أحكام النفاس: أكثره، والطهر قبل الأربعين، وعودة الدم","q":"وضعت مولودي وطهرت بعد خمسة وعشرين يومًا، فهل أصلي وأصوم؟ وما الحكم لو عاد الدم قبل الأربعين؟ وهل أنتظر الأربعين على كل حال؟","short":"أكثر النفاس أربعون يومًا عند أكثر أهل العلم، ومنهم أبو حنيفة وأحمد، وستون عند مالك والشافعي؛ ولا حد لأقله، فمتى طهرت النفساء قبل الأربعين اغتسلت وصلت وصامت وحلت لزوجها، ولا يلزمها انتظار الأربعين. فإن عاد الدم في الأربعين فهو نفاس عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَتِ النُّفَسَاءُ تَجْلِسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم أَرْبَعِينَ يَوْمًا فَكُنَّا نَطْلِي وُجُوهَنَا بِالْوَرْسِ مِنَ الْكَلَفِ","src":"رواه الترمذي ١٣٩","pre":"عن أم سلمة رضي الله عنها قالت:","links":[{"book":"mt_tirmidhi","num":139,"id":"h139"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"أكثر النفاس أربعون يومًا، وهو قول عمر وابن عباس وأنس وأم سلمة رضي الله عنهم، وبه قال أبو حنيفة وأحمد والثوري وإسحاق."},{"t":"qawl","label":"القول الثاني","text":"أكثره ستون يومًا، وهو قول مالك والشافعي."},{"t":"quote","text":"وَأَكْثَرُ النِّفَاسَ أَرْبَعُونَ يَوْمًا) هَذَا قَوْلُ أَكْثَرِ أَهْلِ الْعِلْمِ. قَالَ أَبُو عِيسَى التِّرْمِذِيُّ: أَجْمَعَ أَهْلُ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَمَنْ بَعْدَهُمْ عَلَى أَنَّ النُّفَسَاءَ تَدَعُ الصَّلَاةَ أَرْبَعِينَ يَوْمًا إلَّا أَنْ تَرَى الطُّهْرَ قَبْلَ ذَلِكَ، فَتَغْتَسِلَ وَتُصَلِّيَ. وَقَالَ أَبُو عُبَيْدٍ: وَعَلَى هَذَا جَمَاعَةُ النَّاسِ، وَرُوِيَ هَذَا عَنْ عُمَرَ، وَابْنِ عَبَّاسٍ، وَعُثْمَانَ بْنِ أَبِي الْعَاصِ، وَعَائِذِ بْنِ عَمْرٍو وَأَنَسٍ، وَأُمِّ سَلَمَةَ - رَضِيَ اللَّهُ عَنْهُمْ -. وَبِهِ قَالَ الثَّوْرِيُّ، وَإِسْحَاقُ، وَأَصْحَابُ الرَّأْيِ. وَقَالَ مَالِكٌ، وَالشَّافِعِيُّ: أَكْثَرُهُ سِتُّونَ يَوْمًا. وَحَكَى ابْنُ عَقِيلٍ، عَنْ أَحْمَدَ، رِوَايَةً مِثْلَ قَوْلِهِمَا لِأَنَّهُ رُوِيَ عَنْ الْأَوْزَاعِيِّ أَنَّهُ قَالَ: عِنْدَنَا امْرَأَةٌ تَرَى النِّفَاسَ شَهْرَيْنِ. وَرُوِيَ مِثْلُ ذَلِكَ عَنْ عَطَاءٍ أَنَّهُ وَجَدَهُ. وَالْمَرْجِعُ فِي ذَلِكَ إلَى الْوُجُودِ، قَالَ الشَّافِعِيُّ غَالِبُهُ أَرْبَعُونَ يَوْمًا","src":"المغني","loc":"١/٢٥٠-٢٥١","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَأَكْثَرُ النِّفَاسِ سِتُّونَ يَوْمًا وَقَالَ الْمُزَنِيّ أَرْبَعُونَ يَوْمًا","src":"المجموع","loc":"٢/٥٢٢","pre":"وقال الشيرازي في «المهذب» من كتب الشافعية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وأكثر النفاس أربعون يوما، وقال بعض أهل العلم: خمسون. وقال بعضهم: ستون. لكنها أقوال ضعيفة، فهي مخالفة للدليل","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٤٥١","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وسبب الخلاف عسر الوقوف على ذلك بالتجربة لاختلاف أحوال النساء في ذلك، ولأنه ليس هناك سنة يعمل عليها كالحال في اختلافهم في أيام الحيض والطهر","src":"بداية المجتهد","loc":"١/٥٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن أكثر النفاس أربعون يومًا؛ لحديث أم سلمة، ولأنه قول من سُمّي من الصحابة ولم يعرف لهم مخالف، وقد حكى الترمذي عليه إجماع أهل العلم من الصحابة ومن بعدهم. ولا حد لأقله، فمتى رأت النفساء الطهر ولو بعد أيام يسيرة اغتسلت وصلت وصامت، وجاز لزوجها جماعها، وإن كان الأحسن أن يتركها إلى تمام الأربعين احتياطًا. وأما ما اشتهر عند بعض العامة من أن النفساء لا تصلي حتى تتم الأربعين وإن طهرت، فخطأ مخالف لإجماع العلماء."},{"t":"tanbih","items":[{"t":"p","text":"إن عاد إليها الدم في مدة الأربعين بعد أن طهرت، فهو نفاس عند الجمهور، تترك له الصلاة والصوم، وما صامته وصلته في مدة الطهر صحيح لا تعيده."},{"t":"p","text":"وإن زاد الدم على الأربعين فإن وافق عادة حيضها فهو حيض، وإلا فهو استحاضة تغتسل وتصلي."}]}],"refs":["الترمذي ١٣٩","المغني (١/٢٥٠-٢٥١)","بداية المجتهد (١/٥٨)","المجموع (٢/٥٢٢)","فتاوى نور على الدرب لابن باز (٥/٤٥١)"],"related":["الدم الذي تراه الحامل، هل هو حيض؟","المستحاضة: كيف تعرف حيضها؟ وكيف تتطهر للصلاة؟"],"alts":["مدة النفاس","الطهر قبل الأربعين","النفساء تصلي","عودة دم النفاس"]},{"n":68,"bab":"الطهارة","sub":"الحيض والنفاس","title":"المستحاضة: كيف تعرف أيام حيضها من أيام استحاضتها؟","q":"ينزل مني الدم أكثر أيام الشهر بسبب مرض، فكيف أعرف أيام حيضي التي أترك فيها الصلاة؟","short":"المستحاضة التي استمر بها الدم: إن كانت لها عادة معروفة رجعت إليها، فتجلس قدر أيامها ثم تغتسل وتصلي؛ وإن لم تكن لها عادة وكان دمها يتميز رجعت إلى التمييز، فالأسود الثخين المنتن حيض وما سواه استحاضة؛ فإن لم يكن لها عادة ولا تمييز جلست غالب عادة النساء: ستة أيام أو سبعة من كل شهر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"امْكُثِي قَدْرَ مَا كَانَتْ تَحْبِسُكِ حَيْضَتُكِ، ثُمَّ اغْتَسِلِي وَصَلِّي","src":"رواه مسلم ٣٣٤","pre":"عن عائشة رضي الله عنها أن أم حبيبة بنت جحش سألت رسول الله ﷺ عن الدم، فقال لها:","links":[{"book":"mt_muslim","num":334,"id":"h334-3"}]},{"t":"quote","text":"إِنَّ دَمَ الْحَيْضِ دَمٌ أَسْوَدُ يُعْرَفُ فَإِذَا كَانَ ذَلِكِ فَأَمْسِكِي عَنِ الصَّلاَةِ وَإِذَا كَانَ الآخَرُ فَتَوَضَّئِي وَصَلِّي","src":"رواه النسائي ٢١٦","pre":"وعن عائشة رضي الله عنها أن فاطمة بنت أبي حبيش كانت تستحاض، فقال لها رسول الله ﷺ:","links":[{"book":"mt_nasai","num":216,"id":"h216"}]},{"t":"quote","text":"إِنَّمَا هِيَ رَكْضَةٌ مِنَ الشَّيْطَانِ فَتَحَيَّضِي سِتَّةَ أَيَّامٍ أَوْ سَبْعَةَ أَيَّامٍ فِي عِلْمِ اللَّهِ ثُمَّ اغْتَسِلِي فَإِذَا رَأَيْتِ أَنَّكِ قَدْ طَهُرْتِ وَاسْتَنْقَأْتِ فَصَلِّي أَرْبَعًا وَعِشْرِينَ لَيْلَةً أَوْ ثَلاَثًا وَعِشْرِينَ لَيْلَةً وَأَيَّامَهَا وَصُومِي وَصَلِّي فَإِنَّ ذَلِكِ يُجْزِئُكِ وَكَذَلِكِ فَافْعَلِي كَمَا تَحِيضُ النِّسَاءُ وَكَمَا يَطْهُرْنَ","src":"رواه الترمذي ١٢٨","pre":"وعن حمنة بنت جحش رضي الله عنها أن النبي ﷺ قال لها:","links":[{"book":"mt_tirmidhi","num":128,"id":"h128"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"تعمل على عادتها إن كانت معتادة، فإن كانت مبتدأة جلست أكثر الحيض (عشرة أيام)، وهو قول أبي حنيفة، ولا يعتبر التمييز باللون."},{"t":"qawl","label":"القول الثاني","text":"تعمل على التمييز إن كانت من أهل التمييز، وإلا فعلى العادة، وهو قول الشافعي، وقول مالك فيما حكاه عبد الوهاب."},{"t":"qawl","label":"القول الثالث","text":"تقدم العادة، ثم التمييز، ثم غالب عادة النساء ستًّا أو سبعًا، وهو مذهب أحمد، واختيار ابن تيمية."},{"t":"quote","text":"وَقَالَ أَبُو حَنِيفَةَ: تَقْعُدُ أَيَّامَ عَادَتِهَا إِنْ كَانَتْ لَهَا عَادَةٌ، وَإِنْ كَانَتْ مُبْتَدَأَةً قَعَدَتْ أَكْثَرَ الْحَيْضِ، وَذَلِكَ عِنْدَهُ عَشَرَةُ أَيَّامٍ. وَقَالَ الشَّافِعِيُّ: تَعْمَلُ عَلَى التَّمْيِيزِ إِنْ كَانَتْ مِنْ أَهْلِ التَّمْيِيزِ، وَإِنْ كَانَتْ مِنْ أَهْلِ الْعَادَةِ عَمِلَتْ عَلَى الْعَادَةِ، وَإِنْ كَانَتْ مِنْ أَهْلِهِمَا مَعًا فَلَهُ فِي ذَلِكَ قَوْلَانِ: أَحَدُهُمَا: تَعْمَلُ عَلَى التَّمْيِيزِ، وَالثَّانِي: عَلَى الْعَادَةِ","src":"بداية المجتهد","loc":"١/٦٠","pre":"قال ابن رشد:"},{"t":"quote","text":"وَقَالَ لِي مَالِكٌ: الْمُسْتَحَاضَةُ وَالسَّلِسُ الْبَوْلِ يَتَوَضَّآنِ لِكُلِّ صَلَاةٍ أَحَبُّ إلَيَّ مِنْ غَيْرِ أَنْ أُوجِبَ ذَلِكَ عَلَيْهِمَا","src":"المدونة","loc":"١/١٢٠","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"حديث عائشة - رضي الله عنها - في قصة المستحاضة حيث قال لها النبي - صلى الله عليه وسلم -: ثم توضئي لوقت كل صلاة","src":"مجموع فتاوى ابن باز","loc":"٢/٣٠٨","pre":"قال الشيخ عبد العزيز بن باز رحمه الله في أدلة الوضوء لكل صلاة لمن حدثه دائم:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وعندنا الاعتبار للألوان، ولنا ما روى عن عائشة: «حتى ترين القصة البيضاء» ، ولهم ما في أبي داود «فإنه دم أسود يعرف» وقال الطحاوي في مشكل الآثار: إنه مدرج من الراوي، وأشار النسائي إلى إعلاله في الموضعين في الحيض، ونقل المارديني إعلاله عن أبي حاتم","src":"العرف الشذي","loc":"١/١٤٦-١٤٧","pre":"وقال الكشميري الحنفي في توجيه مذهبه:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المستحاضة ترجع أولًا إلى عادتها إن كانت لها عادة معروفة؛ لقوله ﷺ: «امكثي قدر ما كانت تحبسك حيضتك»، فإن لم تكن لها عادة، أو نسيتها، وكان دمها يتميز بعضه عن بعض، عملت بالتمييز؛ لحديث فاطمة بنت أبي حبيش «إن دم الحيض دم أسود يعرف»، وقد تكلم بعض الحفاظ في هذه اللفظة، لكن معناها يؤيده الواقع وقول جماعة من الصحابة. فإن لم يكن لها عادة ولا تمييز جلست ستة أيام أو سبعة من كل شهر، من أول وقت رأت فيه الدم، لحديث حمنة. وبهذا تجتمع الأحاديث كلها، ويعمل بكل منها في موضعه."},{"t":"tanbih","items":[{"t":"p","text":"ما كان مذهب الحنفية فيه رد المستحاضة إلى العادة فهو موافق للأحاديث في المعتادة، وإنما الخلاف في اعتبار اللون عند عدم العادة."}]}],"refs":["مسلم ٣٣٤","النسائي ٢١٦","الترمذي ١٢٨","بداية المجتهد (١/٦٠)","المدونة (١/١٢٠)","مجموع فتاوى ابن باز (٢/٣٠٨)","بداية المجتهد (١/٦١)","العرف الشذي (١/١٤٦-١٤٧)"],"related":["طهارة المستحاضة للصلاة، وجماعها","أقل الحيض وأكثره، وأقل الطهر بين الحيضتين"],"alts":["الاستحاضة","النزيف المستمر","التمييز بين دم الحيض والاستحاضة","المتحيرة"]},{"n":69,"bab":"الطهارة","sub":"الحيض والنفاس","title":"طهارة المستحاضة للصلاة، وجماعها","q":"أنا مستحاضة، فهل أغتسل لكل صلاة أو أتوضأ؟ وهل يجوز لزوجي أن يجامعني في أيام الاستحاضة؟","short":"المستحاضة في أيام استحاضتها كالطاهرة: تصلي وتصوم، وتغتسل مرة واحدة عند انتهاء حيضها، ثم تتوضأ لوقت كل صلاة عند الجمهور (أبي حنيفة والشافعي وأحمد)، واستحبه مالك. ويجوز لزوجها جماعها عند جمهور الفقهاء.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَاءَتْ فَاطِمَةُ ابْنَةُ أَبِي حُبَيْشٍ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي امْرَأَةٌ أُسْتَحَاضُ فَلاَ أَطْهُرُ، أَفَأَدَعُ الصَّلاَةَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «لاَ، إِنَّمَا ذَلِكِ عِرْقٌ، وَلَيْسَ بِحَيْضٍ، فَإِذَا أَقْبَلَتْ حَيْضَتُكِ فَدَعِي الصَّلاَةَ، وَإِذَا أَدْبَرَتْ فَاغْسِلِي عَنْكِ الدَّمَ ثُمَّ صَلِّي». قَالَ وَقَالَ أَبِي «ثُمَّ تَوَضَّئِي لِكُلِّ صَلاَةٍ، حَتَّى يَجِيءَ ذَلِكَ الْوَقْتُ»","src":"رواه البخاري ٢٢٨","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":228,"id":"h228"}]},{"t":"h","text":"المسألة الأولى: ماذا يجب على المستحاضة من الطهارة؟"},{"t":"qawl","label":"القول الأول","text":"ليس عليها إلا غسل واحد عند انقطاع حيضها، ثم تتوضأ لكل صلاة، وهو قول أبي حنيفة والشافعي وأحمد وأكثر فقهاء الأمصار؛ إلا أن أبا حنيفة وأحمد يجعلان الوضوء لوقت كل صلاة، والشافعي لكل فريضة."},{"t":"qawl","label":"القول الثاني","text":"ليس عليها إلا غسل واحد، والوضوء لكل صلاة مستحب لا واجب، وهو قول مالك."},{"t":"qawl","label":"القول الثالث","text":"تغتسل لكل صلاة، أو تجمع بين الصلاتين بغسل، وروي عن بعض الصحابة، وحمله الجمهور على الاستحباب أو على المتحيرة."},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي الْمُسْتَحَاضَةِ، فَقَوْمٌ أَوْجَبُوا عَلَيْهَا طُهْرًا وَاحِدًا فَقَطْ، وَذَلِكَ عِنْدَمَا تَرَى أَنَّهُ قَدِ انْقَطَعَ حَيْضَهَا بِإِحْدَى تِلْكَ الْعَلَامَاتِ الَّتِي تَقَدَّمَتْ عَلَى حَسَبِ مَذْهَبِ هَؤُلَاءِ فِي تِلْكَ الْعَلَامَاتِ.","src":"بداية المجتهد","loc":"١/٦٥-٦٦","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المستحاضة تغتسل غسلًا واحدًا عند انتهاء أيام حيضها، ثم تغسل الدم وتتحفظ بخرقة أو فوطة، وتتوضأ لوقت كل صلاة، وتصلي بوضوئها الفرض وما شاءت من النوافل حتى يخرج الوقت؛ لقوله ﷺ: «ثم توضئي لكل صلاة حتى يجيء ذلك الوقت»، وهو في صحيح البخاري. وإن اغتسلت لكل صلاة، أو جمعت بين الظهر والعصر بغسل وبين المغرب والعشاء بغسل، فهو أفضل لمن قويت عليه، لحديث حمنة، وليس بواجب."},{"t":"p","text":"ويجوز لزوجها أن يجامعها في زمن الاستحاضة؛ لأن حكمها حكم الطاهرات في الصلاة والصوم، فكذلك في الجماع، وقد كانت أم حبيبة تستحاض فكان زوجها يغشاها، وكانت حمنة مستحاضة وكان زوجها يجامعها (رواه أبو داود ٣٠٩ و٣١٠)، ولم يُنقل أن النبي ﷺ نهى عن ذلك."},{"t":"tanbih","items":[{"t":"p","text":"من به سلس بول، أو خروج ريح مستمر، أو جرح لا يرقأ دمه، حكمه حكم المستحاضة: يتوضأ لوقت كل صلاة، ويصلي ولا يضره ما خرج منه في أثناء الوقت."}]}],"refs":["البخاري ٢٢٨","بداية المجتهد (١/٦٥-٦٦)","بداية المجتهد (١/٦٧)","بداية المجتهد (١/٦٩)"],"related":["المستحاضة: كيف تعرف أيام حيضها من أيام استحاضتها؟"],"alts":["وضوء المستحاضة","غسل المستحاضة","جماع المستحاضة","سلس البول والصلاة"]},{"n":70,"bab":"الطهارة","sub":"النجاسات","title":"حكم إزالة النجاسة للصلاة، ومن صلى بنجاسة لم يعلمها أو نسيها","q":"صليت ثم وجدت في ثوبي نجاسة لم أكن أعلم بها، أو كنت أعلم ونسيت، فهل أعيد الصلاة؟","short":"اتفق العلماء على الأمر بإزالة النجاسة عن البدن والثوب ومكان الصلاة، وجمهورهم (أبو حنيفة والشافعي وأحمد) على أنها شرط لصحة الصلاة. واختلفوا فيمن صلى بنجاسة جاهلًا بها أو ناسيًا: فأوجب عليه الإعادة أبو حنيفة والشافعي في الجديد، وهو رواية عن أحمد؛ ولم يوجبها مالك في الوقت ولا بعده إلا استحبابًا، وهو رواية عن أحمد اختارها جماعة. والأظهر أنه لا إعادة عليه.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَثِيَابَكَ فَطَهِّرْ","ref":"المدثر: ٤"},{"t":"quote","text":"إِنَّهُمَا لَيُعَذَّبَانِ، وَمَا يُعَذَّبَانِ فِي كَبِيرٍ أَمَّا أَحَدُهُمَا فَكَانَ لاَ يَسْتَتِرُ مِنَ الْبَوْلِ، وَأَمَّا الآخَرُ فَكَانَ يَمْشِي بِالنَّمِيمَةِ","src":"رواه البخاري ٢١٨","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ مر بقبرين فقال:","links":[{"book":"mt_bukhari","num":218,"id":"h218"}]},{"t":"quote","text":"بَيْنَمَا رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي بِأَصْحَابِهِ إِذْ خَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ فَلَمَّا رَأَى ذَلِكَ الْقَوْمُ أَلْقَوْا نِعَالَهُمْ فَلَمَّا قَضَى رَسُولُ اللَّهِ صلى الله عليه وسلم صَلاَتَهُ قَالَ «مَا حَمَلَكُمْ عَلَى إِلْقَائِكُمْ نِعَالَكُمْ» . قَالُوا رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا . فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «إِنَّ جِبْرِيلَ صلى الله عليه وسلم أَتَانِي فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا» . وَقَالَ «إِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ فَإِنْ رَأَى فِي نَعْلَيْهِ قَذَرًا أَوْ أَذًى فَلْيَمْسَحْهُ وَلْيُصَلِّ فِيهِمَا»","src":"رواه أبو داود ٦٥٠","pre":"وعن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":650,"id":"h650"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"إزالة النجاسة واجبة وشرط في صحة الصلاة، وهو قول أبي حنيفة والشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"إزالتها سنة مؤكدة، أو واجبة مع الذكر والقدرة ساقطة مع النسيان والعجز، وهما قولان عن مالك وأصحابه."},{"t":"quote","text":"وَاتَّفَقَ الْعُلَمَاءُ لِمَكَانِ هَذِهِ الْمَسْمُوعَاتِ عَلَى أَنَّ إِزَالَةَ النَّجَاسَةِ مَأْمُورٌ بِهَا فِي الشَّرْعِ وَاخْتَلَفُوا: هَلْ ذَلِكَ عَلَى الْوُجُوبِ أَوْ عَلَى النَّدْبِ الْمَذْكُورِ، وَهُوَ الَّذِي يُعَبَّرُ عَنْهُ بِالسُّنَّةِ؟ فَقَالَ قَوْمٌ: إِنَّ إِزَالَةَ النَّجَاسَاتِ وَاجِبَةٌ، وَبِهِ قَالَ أَبُو حَنِيفَةَ وَالشَّافِعِيُّ، وَقَالَ قَوْمٌ: إِزَالَتُهَا سُنَّةٌ مُؤَكَّدَةٌ وَلَيْسَتْ بِفَرْضٍ.","src":"بداية المجتهد","loc":"١/٨١","pre":"قال ابن رشد:"},{"t":"quote","text":"تَطْهِيرُ النَّجَاسَةِ وَاجِبٌ مِنْ بَدَنِ الْمُصَلِّي وَثَوْبِهِ وَالْمَكَانِ الَّذِي يُصَلِّي عَلَيْهِ","src":"الهداية مع فتح القدير","loc":"١/١٩٠","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن إزالة النجاسة عن البدن والثوب ومكان الصلاة واجبة، وأنها شرط لصحة الصلاة مع العلم والقدرة؛ لقوله تعالى: ﴿وَثِيَابَكَ فَطَهِّرْ﴾، ولأمره ﷺ بغسل دم الحيض من الثوب، وتعذيب من لا يستنزه من البول. لكن من صلى بنجاسة لم يعلمها، أو علمها ثم نسيها حتى فرغ من الصلاة، فصلاته صحيحة ولا إعادة عليه؛ لأن النبي ﷺ خلع نعليه في أثناء الصلاة لما أخبره جبريل بالقذر، وبنى على ما مضى من صلاته ولم يستأنفها، فدل على أن ما صلاه قبل العلم صحيح. ومن علم بالنجاسة في أثناء الصلاة وأمكنه إزالتها دون عمل كثير أزالها وأتم، وإلا قطع الصلاة وأزالها ثم استأنف."},{"t":"tanbih","items":[{"t":"p","text":"من لم يجد إلا ثوبًا نجسًا ولم يقدر على غسله صلى فيه، ولا إعادة عليه في أصح قولي العلماء، لأن الله لا يكلف نفسًا إلا وسعها."}]}],"refs":["البخاري ٢١٨","أبو داود ٦٥٠","بداية المجتهد (١/٨١)","الهداية مع فتح القدير (١/١٩٠)","بداية المجتهد (١/٨٢)"],"related":["يسير النجاسة المعفو عنه"],"alts":["الصلاة بثوب نجس","نسيان النجاسة في الصلاة","إعادة الصلاة بسبب النجاسة","شروط الصلاة الطهارة من النجس"]},{"n":71,"bab":"الطهارة","sub":"النجاسات","title":"ميتة ما لا دم له كالذباب والنمل، وميتة البحر","q":"وقعت ذبابة أو نملة أو صرصور في الطعام أو الماء وماتت فيه، فهل ينجس؟ وما حكم ميتة السمك؟","short":"ما لا نفس له سائلة (أي لا دم له يسيل) كالذباب والنمل والبعوض والصراصير لا ينجس بالموت، ولا ينجس ما مات فيه، عند جمهور العلماء ومنهم أبو حنيفة ومالك وأحمد، والشافعي في أحد قوليه. وميتة البحر من السمك وغيره طاهرة حلال عند الجمهور، واستثنى أبو حنيفة السمك الطافي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا وَقَعَ الذُّبَابُ فِي شَرَابِ أَحَدِكُمْ فَلْيَغْمِسْهُ، ثُمَّ لِيَنْزِعْهُ، فَإِنَّ فِي إِحْدَى جَنَاحَيْهِ دَاءً وَالأُخْرَى شِفَاءً","src":"رواه البخاري ٣٣٢٠","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":3320,"id":"h3320"}]},{"t":"quote","text":"هُوَ الطَّهُورُ مَاؤُهُ الْحِلُّ مَيْتَتُهُ","src":"رواه الترمذي ٦٩","pre":"وعنه رضي الله عنه أن النبي ﷺ قال في البحر:","links":[{"book":"mt_tirmidhi","num":69,"id":"h69"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"ميتة ما لا دم له طاهرة، وميتة البحر طاهرة، وهو مذهب مالك وأصحابه، وأحمد."},{"t":"qawl","label":"القول الثاني","text":"ميتة ما لا دم له نجسة كسائر الميتات إلا ما استثني، وميتة البحر طاهرة، وهو مذهب الشافعي في أحد قوليه."},{"t":"qawl","label":"القول الثالث","text":"ميتة ما لا دم له طاهرة، وأما ميتة البحر فلا يحل منها إلا السمك غير الطافي، وهو مذهب أبي حنيفة."},{"t":"quote","text":"وَمَوْتُ مَا لَيْسَ لَهُ نَفْسٌ سَائِلَةٌ فِي الْمَاءِ لَا يُنَجِّسُهُ كَالْبَقِّ وَالذُّبَابِ وَالزَّنَابِيرِ وَالْعَقْرَبِ وَنَحْوِهَا وَقَالَ الشَّافِعِيُّ - رَحِمَهُ اللَّهُ -: يُفْسِدُهُ لِأَنَّ التَّحْرِيمَ لَا بِطَرِيقِ الْكَرَامَةِ آيَةُ النَّجَاسَةِ، بِخِلَافِ دُودِ الْخَلِّ وَسُوسِ الثِّمَارِ لِأَنَّ فِيهِ ضَرُورَةً، وَلَنَا قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - فِيهِ «هَذَا هُوَ الْحَلَالُ أَكْلُهُ وَشُرْبُهُ وَالْوُضُوءُ مِنْهُ»","src":"الهداية مع فتح القدير","loc":"١/٨٢","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن ما لا دم له سائل لا ينجس بالموت، ولا ينجس الماء أو الطعام الذي يموت فيه؛ لأن النبي ﷺ أمر بغمس الذباب في الشراب، ومعلوم أنه قد يموت بالغمس لا سيما في الحار، ولو كان ينجسه لما أمر به؛ وعلة النجاسة احتقان الدم في الميتة، وهي منتفية فيما لا دم له. وميتة البحر طاهرة حلال؛ لقوله ﷺ: «الحل ميتته»، ولحديث جابر في الحوت الذي ألقاه البحر."},{"t":"tanbih","items":[{"t":"p","text":"طهارة هذه الحشرات لا تعني إباحة أكلها؛ فإنها من الخبائث عند الجمهور، فيُخرج ما وقع منها في الطعام ويُلقى، ويؤكل الطعام إن لم يستقذره صاحبه."}]}],"refs":["البخاري ٣٣٢٠","الترمذي ٦٩","الهداية مع فتح القدير (١/٨٢)"],"related":["الدم: قليله وكثيره، ودم الإنسان والسمك"],"alts":["الذباب في الطعام","النمل في الماء","ميتة الحشرات","السمك الميت"]},{"n":72,"bab":"الطهارة","sub":"النجاسات","title":"الدم: قليله وكثيره، ودم الإنسان، ودم السمك","q":"أصاب ثوبي قليل من الدم من جرح أو بعوضة، فهل يجب غسله؟ وهل دم الإنسان نجس؟","short":"اتفق العلماء على نجاسة الدم المسفوح من الحيوان البري، وعلى العفو عن يسيره عند الجمهور، ومنهم أبو حنيفة ومالك وأحمد. واختلفوا في دم السمك، فطهّره الشافعي وأحد قولي مالك. وما بقي في عروق المذكاة ولحمها بعد الذبح طاهر بالاتفاق.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً أَوْ دَمًا مَّسْفُوحًا أَوْ لَحْمَ خِنزِيرٍ فَإِنَّهُۥ رِجْسٌ","ref":"الأنعام: ١٤٥"},{"t":"quote","text":"جَاءَتِ امْرَأَةٌ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ أَرَأَيْتَ إِحْدَانَا تَحِيضُ فِي الثَّوْبِ كَيْفَ تَصْنَعُ قَالَ «تَحُتُّهُ، ثُمَّ تَقْرُصُهُ بِالْمَاءِ، وَتَنْضَحُهُ وَتُصَلِّي فِيهِ»","src":"رواه البخاري ٢٢٧","pre":"عن أسماء رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":227,"id":"h227"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ دَمَ الْحَيَوَانِ الْبَرِّيِّ نَجِسٌ، وَاخْتَلَفُوا فِي دَمِ السَّمَكِ، وَكَذَلِكَ اخْتَلَفُوا فِي الدَّمِ الْقَلِيلِ مِنْ دَمِ الْحَيَوَانِ غَيْرِ الْبَحْرِيِّ، فَقَالَ قَوْمٌ: دَمُ السَّمَكِ طَاهِرٌ، وَهُوَ أَحَدُ قَوْلَيْ مَالِكٍ، وَمَذْهَبُ الشَّافِعِيِّ.","src":"بداية المجتهد","loc":"١/٨٦","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"مع العلم أن الشيء اليسير من الدم المسفوح يعفى عنه عند أهل العلم","src":"فتاوى اللجنة الدائمة","loc":"٥/٤١٠","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الدم المسفوح نجس، ويعفى عن يسيره عرفًا، كنقطة الرعاف اليسيرة ودم البعوض والبراغيث وما يصيب الجزار والجريح؛ لأن الله حرم المسفوح، ولأن الصحابة كانوا يصلون في جراحاتهم، ولأن التحرز من اليسير شاق. وأما الدم الباقي في اللحم والعروق بعد الذبح فطاهر بالاتفاق، ودم السمك أخف، والأظهر طهارته تبعًا لميتته."},{"t":"tanbih","items":[{"t":"p","text":"ذهب بعض المحققين المتأخرين إلى طهارة دم الآدمي لعدم الدليل الصريح على نجاسته، والجمهور على نجاسته، والأحوط غسل ما كثر منه وتفاحش."},{"t":"p","text":"القيح والصديد حكمهما حكم الدم عند الجمهور، ويعفى عن يسيرهما."}]}],"refs":["البخاري ٢٢٧","بداية المجتهد (١/٨٦)","فتاوى اللجنة الدائمة (٥/٤١٠)","بداية المجتهد (١/٨٧)"],"related":["يسير النجاسة المعفو عنه"],"alts":["نجاسة الدم","دم الجرح على الثوب","دم البعوض","الدم القليل في الصلاة"]},{"n":73,"bab":"الطهارة","sub":"النجاسات","title":"بول وروث ما يؤكل لحمه كالإبل والغنم والدجاج","q":"أعمل في حظيرة غنم وإبل، فيصيب ثيابي من بولها وروثها، فهل يجب غسله قبل الصلاة؟","short":"بول الآدمي وغائطه نجسان بالإجماع. واختلفوا في بول وروث ما يؤكل لحمه: فهما طاهران عند مالك وأحمد ومحمد بن الحسن وزفر من الحنفية، ونجسان عند أبي حنيفة وأبي يوسف والشافعي. والأظهر طهارتهما.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قَدِمَ أُنَاسٌ مِنْ عُكْلٍ أَوْ عُرَيْنَةَ، فَاجْتَوَوُا الْمَدِينَةَ، فَأَمَرَهُمُ النَّبِيُّ صلى الله عليه وسلم بِلِقَاحٍ، وَأَنْ يَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا","src":"رواه البخاري ٢٣٣","pre":"عن أنس رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":233,"id":"h233"}]},{"t":"quote","text":"صَلُّوا فِي مَرَابِضِ الْغَنَمِ وَلاَ تُصَلُّوا فِي أَعْطَانِ الإِبِلِ","src":"رواه الترمذي ٣٤٨","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":348,"id":"h348"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"بول ما يؤكل لحمه وروثه طاهران، وهو قول مالك وأحمد، ومحمد بن الحسن وزفر من الحنفية، واختاره ابن تيمية."},{"t":"qawl","label":"القول الثاني","text":"الأبوال والأرواث كلها نجسة، وهو قول أبي حنيفة وأبي يوسف والشافعي."},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى نَجَاسَةِ بَوْلِ ابْنِ آدَمَ وَرَجِيعِهِ إِلَّا بَوْلَ الصَّبِيِّ الرَّضِيعِ، وَاخْتَلَفُوا فِيمَا سِوَاهُ مِنَ الْحَيَوَانِ، فَذَهَبَ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ إِلَى أَنَّهَا كُلَّهَا نَجِسَةٌ.","src":"بداية المجتهد","loc":"١/٨٧","pre":"قال ابن رشد:"},{"t":"quote","text":"بول ما يؤكل لحمه طاهر عند مالك، وكذلك مذهب أحمد ومذهب محمد وزفر، ونجس عند أبي حنيفة والشافعي وأبي يوسف، وفي طهارة أزبال ما يوكل لحمه رواية شاذة عن محمد بن حسن، وهو مذهب مالك، ولابن التيمية كلام مطنب في فتاواه","src":"العرف الشذي","loc":"١/١٠٧","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"أَمَّا) الْأَبْوَالُ فَلَا خِلَافَ فِي أَنَّ بَوْلَ كُلِّ مَا لَا يُؤْكَلُ لَحْمُهُ نَجِسٌ، وَاخْتُلِفَ فِي بَوْلِ مَا يُؤْكَلُ لَحْمُهُ قَالَ أَبُو حَنِيفَةَ وَأَبُو يُوسُفَ نَجِسٌ. وَقَالَ مُحَمَّدٌ طَاهِرٌ","src":"بدائع الصنائع","loc":"١/٦١","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"quote","text":"وَلَا يَتَوَضَّأُ بِشَيْءٍ مِنْ أَبْوَالِ الْإِبِلِ وَلَا مِنْ أَلْبَانِهَا","src":"المدونة","loc":"١/١١٤","pre":"وفي «المدونة» عن الإمام مالك:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"هذا هو الصواب: أن بول ما يؤكل لحمه وروثه كله طاهر، مثل الإبل والبقر والغنم والصيد كله طاهر","src":"مجموع فتاوى ابن باز","loc":"٢٩/١٠٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"أبوال الإبل وروثها طاهر","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/٣٨٢","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر طهارة بول وروث ما يؤكل لحمه من الإبل والبقر والغنم والدجاج ونحوها؛ لأن النبي ﷺ أذن للعرنيين في شرب أبوال الإبل، ولم يأمرهم بغسل أفواههم وأوانيهم، ولا يُتداوى بالنجس المحرم؛ ولأنه ﷺ أذن في الصلاة في مرابض الغنم وهي لا تخلو من أبوالها وأرواثها، وكان يطوف على بعيره في المسجد. وهو قول محمد بن الحسن صاحب أبي حنيفة كما حكاه الكشميري. ومن غسل ما أصابه منها تنظفًا واحتياطًا فحسن."},{"t":"tanbih","items":[{"t":"p","text":"بول وروث ما لا يؤكل لحمه كالحمار والكلب والسباع نجس عند عامة العلماء."}]}],"refs":["البخاري ٢٣٣","الترمذي ٣٤٨","بداية المجتهد (١/٨٧)","العرف الشذي (١/١٠٧)","بدائع الصنائع (١/٦١)","المدونة (١/١١٤)","مجموع فتاوى ابن باز (٢٩/١٠٥)","مجموع فتاوى ابن عثيمين (١٢/٣٨٢)"],"related":["يسير النجاسة المعفو عنه"],"alts":["بول الإبل","روث الغنم","زرق الدجاج","فضلات الحيوانات"]},{"n":74,"bab":"الطهارة","sub":"النجاسات","title":"يسير النجاسة المعفو عنه","q":"تصيب ثوبي أحيانًا نقطة يسيرة من بول أو نجاسة لا أراها إلا بتدقيق، فهل يعفى عنها؟","short":"اختلف العلماء: فلم يعف الشافعي عن شيء من النجاسة إلا ما لا يدركه الطرف ويسير الدم، وعفا أبو حنيفة عن قدر الدرهم من النجاسة المغلظة وعن ربع الثوب من المخففة، وعفا مالك وأحمد عن يسير الدم والقيح ونحوه. والأظهر العفو عما يشق التحرز منه من اليسير.","body":[{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"قليل النجاسة وكثيرها سواء، يجب غسله، إلا ما لا يدركه الطرف ويسير الدم، وهو قول الشافعي."},{"t":"qawl","label":"القول الثاني","text":"يعفى عن قدر الدرهم البغلي من النجاسة المغلظة، وعن ربع الثوب من المخففة، وهو قول أبي حنيفة."},{"t":"qawl","label":"القول الثالث","text":"قليل النجاسة وكثيرها سواء إلا الدم وما في معناه فيعفى عن يسيره، وهو قول مالك، وقريب منه قول أحمد."},{"t":"quote","text":"اخْتَلَفَ النَّاسُ فِي قَلِيلِ النَّجَاسَاتِ عَلَى ثَلَاثَةِ أَقْوَالٍ: فَقَوْمٌ رَأَوْا قَلِيلَهَا وَكَثِيرَهَا سَوَاءً، وَمِمَّنْ قَالَ بِهَذَا الْقَوْلِ الشَّافِعِيُّ.","src":"بداية المجتهد","loc":"١/٨٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الشريعة مبنية على رفع الحرج، فيعفى عن يسير النجاسة الذي يشق التحرز منه وتعم به البلوى: كيسير الدم والقيح، وأثر الاستجمار، وما يتطاير من رشاش يسير لا يُرى، وطين الشوارع، وما يصيب المرضى والمرضعات وأصحاب الأعمال من اليسير؛ وقد استحسن ابن رشد المالكي تقسيم الحنفية النجاسة إلى مغلظة ومخففة. وأما ما يمكن التحرز منه ولا مشقة في غسله كالبول والغائط إذا تحقق وقوعه فيُغسل."},{"t":"tanbih","items":[{"t":"p","text":"لا يجب على المسلم أن يفتش ثيابه بالوسوسة، والأصل في الأشياء الطهارة، فلا يحكم بالنجاسة إلا بيقين."}]}],"refs":["بداية المجتهد (١/٨٨)"],"related":["حكم إزالة النجاسة للصلاة، ومن صلى بنجاسة لم يعلمها أو نسيها"],"alts":["قدر الدرهم","النجاسة اليسيرة","رشاش البول","المعفو عنه من النجاسات"]},{"n":75,"bab":"الطهارة","sub":"النجاسات","title":"المني: هل هو نجس؟ وكيف يُطهّر الثوب منه؟","q":"أصاب ثوبي مني، فهل هو نجس يجب غسله، أم يكفي فركه؟","short":"اختلف العلماء: فالمني نجس عند أبي حنيفة ومالك، ويطهر عند أبي حنيفة بالفرك إذا كان يابسًا وبالغسل إذا كان رطبًا، ويجب غسله عند مالك؛ وهو طاهر عند الشافعي وأحمد، يستحب غسل رطبه وفرك يابسه. والأظهر طهارته، ومع ذلك يُزال تنظفًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنْتُ أَغْسِلُ الْجَنَابَةَ مِنْ ثَوْبِ النَّبِيِّ صلى الله عليه وسلم، فَيَخْرُجُ إِلَى الصَّلاَةِ، وَإِنَّ بُقَعَ الْمَاءِ فِي ثَوْبِهِ","src":"رواه البخاري ٢٢٩","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":229,"id":"h229"}]},{"t":"quote","text":"لَقَدْ رَأَيْتُنِي أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرْكًا فَيُصَلِّي فِيهِ","src":"رواه مسلم ٢٨٨","pre":"وعنها رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":288,"id":"h288"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"المني نجس، وهو قول أبي حنيفة ومالك؛ ويكفي عند أبي حنيفة فرك يابسه وغسل رطبه، ويجب غسله عند مالك."},{"t":"qawl","label":"القول الثاني","text":"المني طاهر، وهو قول الشافعي وأحمد وداود، وروي عن سعد بن أبي وقاص وابن عباس رضي الله عنهم."},{"t":"quote","text":"اخْتَلَفُوا فِي الْمَنِيِّ: هَلْ هُوَ نَجِسٌ أَمْ لَا؟ فَذَهَبَتْ طَائِفَةٌ، مِنْهُمْ مَالِكٌ وَأَبُو حَنِيفَةَ إِلَى أَنَّهُ نَجِسٌ، وَذَهَبَتْ طَائِفَةٌ إِلَى أَنَّهُ طَاهِرٌ، وَبِهَذَا قَالَ الشَّافِعِيُّ وَأَحْمَدُ وَدَاوُدُ","src":"بداية المجتهد","loc":"١/٨٨","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المني طاهر، فلو صلى الإنسان في ثوب فيه مني فصلاته صحيحه، سواء كان عمداً أو نسياناً","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/٣٧١","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"الصحيح أن المني طاهر","src":"فتاوى اللجنة الدائمة","loc":"٥/٣٤٧","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وأما الحديث فثبت فيه الفرك والغسل، ونعمل بهما بأن الفرك في اليابس، والغسل في الرطب","src":"العرف الشذي","loc":"١/١٤١","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المني طاهر؛ لأن عائشة رضي الله عنها كانت تفركه من ثوب رسول الله ﷺ فيصلي فيه، والفرك لا يزيل النجاسة عند أكثر من يقول بنجاسته، وأما الغسل فمحمول على التنظيف، كما يُغسل المخاط والبصاق؛ ولأنه أصل خلق الأنبياء والأولياء. ومع ذلك فالسنة أن يُغسل رطبه ويُفرك يابسه، وبهذا يُعمل بالحديثين جميعًا، وهو ما يقوله الحنفية في التطهير وإن خالفوا في الأصل؛ فالعمل متفق في الغالب، وإنما يظهر أثر الخلاف فيمن صلى وفي ثوبه أثر المني ناسيًا."},{"t":"tanbih","items":[{"t":"p","text":"المذي والودي نجسان باتفاق؛ يُغسل منهما الذكر، ويُنضح الثوب من المذي، ويجب منهما الوضوء دون الغسل."}]}],"refs":["البخاري ٢٢٩","مسلم ٢٨٨","بداية المجتهد (١/٨٨)","مجموع فتاوى ابن عثيمين (١٢/٣٧١)","فتاوى اللجنة الدائمة (٥/٣٤٧)","بداية المجتهد (١/٨٨-٨٩)","العرف الشذي (١/١٤١)"],"related":["خروج المني، ومتى يوجب الغسل؟ وهل على المرأة غسل إذا احتلمت؟"],"alts":["طهارة المني","فرك المني","المني على الثوب","المذي على الثوب"]},{"n":76,"bab":"الطهارة","sub":"النجاسات","title":"بول الطفل الرضيع: هل يُغسل أو يُرش؟","q":"بال ابني الرضيع على ثيابي، وكذلك ابنتي الرضيعة، فهل يجب غسله أم يكفي رشه بالماء؟","short":"بول الصبي الذكر الذي لم يأكل الطعام يكفي فيه النضح (رش الماء حتى يعمه دون عصر) عند الشافعي وأحمد وأهل الحديث، وأما بول الأنثى فيُغسل. وذهب أبو حنيفة ومالك إلى غسل بول الصبي والصبية جميعًا، وحمل الحنفية النضح على الغسل الخفيف. والأظهر التفريق كما جاءت به السنة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّهَا أَتَتْ بِابْنٍ لَهَا صَغِيرٍ، لَمْ يَأْكُلِ الطَّعَامَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، فَأَجْلَسَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي حِجْرِهِ، فَبَالَ عَلَى ثَوْبِهِ، فَدَعَا بِمَاءٍ فَنَضَحَهُ وَلَمْ يَغْسِلْهُ","src":"رواه البخاري ٢٢٣","pre":"عن أم قيس بنت محصن رضي الله عنها:","links":[{"book":"mt_bukhari","num":223,"id":"h223"}]},{"t":"quote","text":"كُنْتُ أَخْدُمُ النَّبِيَّ صلى الله عليه وسلم فَكَانَ إِذَا أَرَادَ أَنْ يَغْتَسِلَ قَالَ «وَلِّنِي قَفَاكَ» . فَأُوَلِّيهِ قَفَاىَ فَأَسْتُرُهُ بِهِ فَأُتِيَ بِحَسَنٍ أَوْ حُسَيْنٍ - رضى الله عنهما - فَبَالَ عَلَى صَدْرِهِ فَجِئْتُ أَغْسِلُهُ فَقَالَ «يُغْسَلُ مِنْ بَوْلِ الْجَارِيَةِ وَيُرَشُّ مِنْ بَوْلِ الْغُلاَمِ»","src":"رواه أبو داود ٣٧٦","pre":"وعن أبي السمح رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":376,"id":"h376"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يُنضح من بول الغلام الذي لم يطعم، ويُغسل من بول الجارية، وهو قول الشافعي وأحمد وإسحاق وأهل الحديث."},{"t":"qawl","label":"القول الثاني","text":"يُغسل من بول الغلام والجارية جميعًا، وهو قول أبي حنيفة ومالك."},{"t":"qawl","label":"القول الثالث","text":"يُنضح من بولهما جميعًا، وهو قول الأوزاعي."},{"t":"quote","text":"أَمَّا النَّضْحُ: فَإِنَّ قَوْمًا قَالُوا: هَذَا خَاصٌّ بِإِزَالَةِ بَوْلِ الطِّفْلِ الَّذِي لَمْ يَأْكُلِ الطَّعَامَ، وَقَوْمٌ فَرَّقُوا بَيْنَ بَوْلِ الذَّكَرِ وَالْأُنْثَى، فَقَالُوا: يُنْضَحُ بَوْلُ الذَّكَرِ وَيُغْسَلُ بَوْلُ الْأُنْثَى، وَقَوْمٌ قَالُوا: الْغَسْلُ طَهَارَةُ مَا يَتَيَقَّنُ بِنَجَاسَتِهِ، وَالنَّضْحُ طَهَارَةُ مَا شَكَّ فِيهِ، وَهُوَ مَذْهَبُ مَالِكِ بْنِ أَنَسٍ - رَضِيَ اللَّهُ عَنْهُ -","src":"بداية المجتهد","loc":"١/٩٢","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أتباع المذاهب الأربعة: إن بول الغلام نجس، والاختلاف في وجه التطهير؛ قلنا: إن في تطهيره تخفيفاً كما في موطأ محمد بن حسن ص (64) أن فيه رخصة أي تخفيفاً","src":"العرف الشذي","loc":"١/١٠٦","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"تمشى الشوافع على ظاهر حديث نضح بول الغلام ونحن حملنا النضح على الغسل الخفيف، وهو صب الماء شيئاً فشيئاً","src":"العرف الشذي","loc":"١/١٠٦"},{"t":"quote","text":"وَيَسْتَوِي الْجَوَابُ عِنْدَنَا بَيْنَ بَوْلِ الصَّبِيِّ وَالصَّبِيَّةِ","src":"بدائع الصنائع","loc":"١/٨٨","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ينضح بول الغلام ما لم يتغذ بالطعام، فإذا تغذى به فإنه يغسل، وأما الجارية فإنه يغسل بولها مطلقا طعمت أو لم تطعم","src":"فتاوى اللجنة الدائمة","loc":"٥/٤٠٣","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر ما دلت عليه السنة الصحيحة الصريحة: أن بول الغلام الذي لم يأكل الطعام يكفي فيه النضح، وهو أن يُرش عليه الماء حتى يغمره من غير عصر ولا دلك، وأن بول الجارية يُغسل. وهذا تخفيف ورخصة كما سماه الحنفية أنفسهم، وليس فيه أن بول الغلام طاهر؛ بل هو نجس بالاتفاق، وإنما خُفف في طريقة تطهيره."},{"t":"tanbih","items":[{"t":"p","text":"إذا صار الطفل يأكل الطعام ويشتهيه ويتغذى به، فبوله كبول الكبير يُغسل، ذكرًا كان أو أنثى."}]}],"refs":["البخاري ٢٢٣","أبو داود ٣٧٦","بداية المجتهد (١/٩٢)","العرف الشذي (١/١٠٦)","بدائع الصنائع (١/٨٨)","فتاوى اللجنة الدائمة (٥/٤٠٣)"],"related":["ما تُزال به النجاسة، وتطهير النعل والذيل والأرض"],"alts":["بول الرضيع","نضح بول الغلام","بول الطفلة","رش الماء على البول"]},{"n":77,"bab":"الطهارة","sub":"النجاسات","title":"ما تُزال به النجاسة، وتطهير النعل والذيل والأرض","q":"هل تزول النجاسة بغير الماء كالمنظفات والمطهرات؟ وكيف أطهر حذائي إذا داس نجاسة؟ وكيف تطهر الأرض إذا أصابها بول؟","short":"اتفق العلماء على أن الماء يزيل النجاسة، وعلى إزالتها من المخرجين بالحجارة. واختلفوا في غير الماء: فأجاز أبو حنيفة إزالتها بكل مائع طاهر قالع كالخل، ولم يجزه مالك والشافعي وأحمد في المشهور إلا بالماء. والأظهر أن النجاسة متى زالت عينها بأي مزيل طاهر طهر المحل. ويطهر النعل والخف بدلكهما بالأرض، والأرض بصب الماء عليها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا وَطِئَ أَحَدُكُمْ بِنَعْلَيْهِ الأَذَى فَإِنَّ التُّرَابَ لَهُ طَهُورٌ","src":"رواه أبو داود ٣٨٥","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_abudawud","num":385,"id":"h385"}]},{"t":"quote","text":"إِنِّي امْرَأَةٌ أُطِيلُ ذَيْلِي وَأَمْشِي فِي الْمَكَانِ الْقَذِرِ . فَقَالَتْ أُمُّ سَلَمَةَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «يُطَهِّرُهُ مَا بَعْدَهُ»","src":"رواه أبو داود ٣٨٣","pre":"وعن أم ولد لإبراهيم بن عبد الرحمن أنها سألت أم سلمة رضي الله عنها فقالت:","links":[{"book":"mt_abudawud","num":383,"id":"h383"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"تزول النجاسة بكل طاهر يزيل عينها، مائعًا كان أو جامدًا، وهو قول أبي حنيفة وأصحابه، ورواية عن أحمد اختارها ابن تيمية."},{"t":"qawl","label":"القول الثاني","text":"لا تزول النجاسة بغير الماء إلا في الاستجمار، وهو قول مالك والشافعي، والمشهور عن أحمد."},{"t":"quote","text":"فَإِنَّ الْمُسْلِمِينَ اتَّفَقُوا عَلَى أَنَّ الْمَاءَ الطَّاهِرَ الْمُطَهِّرَ يُزِيلُهَا مِنْ هَذِهِ الثَّلَاثَةِ الْمَحَالِّ، وَاتَّفَقُوا أَيْضًا عَلَى أَنَّ الْحِجَارَةَ تُزِيلُهَا مِنَ الْمَخْرَجَيْنِ، وَاخْتَلَفُوا فِيمَا سِوَى ذَلِكَ مِنَ الْمَائِعَاتِ وَالْجَامِدَاتِ الَّتِي تُزِيلُهَا.","src":"بداية المجتهد","loc":"١/٩٠","pre":"قال ابن رشد:"},{"t":"quote","text":"بِمَاءٍ لَوْ مُسْتَعْمَلًا بِهِ يُفْتَى وَبِكُلِّ مَائِعٍ طَاهِرٍ قَالِعٍ","src":"الدر المختار مع رد المحتار","loc":"١/٣٠٩","pre":"وقال في «الدر المختار» من كتب الحنفية في تطهير النجاسة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن النجاسة عين خبيثة، فمتى زالت بأي مزيل طاهر زال حكمها؛ ولهذا طهّر الشرع النعل بالتراب، والذيل بما بعده من الأرض، والمخرج بالحجارة، وهذا قول الحنفية ورواية عن أحمد. ومع ذلك فالماء هو الأصل في التطهير، وهو أبلغ في الإزالة، كما نبه ابن رشد. فالمنظفات الحديثة إذا أزالت عين النجاسة ولونها وريحها طهر المحل، والغسل بالماء أولى."},{"t":"p","text":"ويطهر النعل والخف إذا أصابتهما نجاسة بدلكهما بالأرض حتى تزول العين، ويصلي فيهما؛ وتطهر الأرض إذا أصابها بول بصب الماء عليها حتى يغمره، كما أمر النبي ﷺ بصب ذنوب من ماء على بول الأعرابي في المسجد، وتطهر أيضًا بالشمس والريح إذا زال أثر النجاسة عند أبي حنيفة، وهو اختيار ابن تيمية."},{"t":"tanbih","items":[{"t":"p","text":"الاستحالة: إذا تحولت النجاسة إلى عين أخرى طاهرة، كالخمر تصير خلًّا بنفسها، والنجاسة تحترق فتصير رمادًا، فإنها تطهر عند الحنفية والمالكية في الجملة، وهو رواية عن أحمد واختيار ابن تيمية، والخمر إذا تخللت بنفسها طاهرة بالاتفاق."}]}],"refs":["أبو داود ٣٨٥","أبو داود ٣٨٣","بداية المجتهد (١/٩٠)","الدر المختار مع رد المحتار (١/٣٠٩)","بداية المجتهد (١/٩١)"],"related":["عدد الغسلات في إزالة النجاسة"],"alts":["تطهير الحذاء","تطهير الأرض من البول","المنظفات وإزالة النجاسة","الاستحالة"]},{"n":78,"bab":"الطهارة","sub":"النجاسات","title":"عدد الغسلات في إزالة النجاسة، والنجاسة التي لا تُرى","q":"هل يشترط غسل النجاسة ثلاث مرات أو سبعًا؟ وماذا أفعل إذا بقي لون النجاسة بعد الغسل؟","short":"لا يشترط عدد في غسل النجاسات عند مالك وأبي حنيفة وأحمد في رواية، بل المعتبر إزالة العين، وإن كانت النجاسة غير مرئية غسلها الحنفية ثلاثًا؛ واشترط أحمد في المشهور السبع، واستثنى الجمهور ولوغ الكلب فيغسل سبعًا. والأظهر أن المعتبر زوال عين النجاسة، ولا يضر بقاء لون عسر زواله.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَاءَتِ امْرَأَةٌ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ أَرَأَيْتَ إِحْدَانَا تَحِيضُ فِي الثَّوْبِ كَيْفَ تَصْنَعُ قَالَ «تَحُتُّهُ، ثُمَّ تَقْرُصُهُ بِالْمَاءِ، وَتَنْضَحُهُ وَتُصَلِّي فِيهِ»","src":"رواه البخاري ٢٢٧","pre":"عن أسماء رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":227,"id":"h227"}]},{"t":"quote","text":"إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلْيُرِقْهُ ثُمَّ لِيَغْسِلْهُ سَبْعَ مِرَارٍ","src":"رواه مسلم ٢٧٩","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":279,"id":"h279"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"المعتبر في إزالة النجاسة زوال عينها وإنقاء المحل، من غير عدد محدد، إلا ما ورد فيه النص كولوغ الكلب، وهو قول مالك وأبي حنيفة، وقدّر الحنفية غسل النجاسة التي لا تُرى بثلاث غسلات، لأن غلبة الظن بالطهارة تحصل بها."},{"t":"qawl","label":"القول الثاني","text":"يُشترط العدد في الاستجمار بثلاثة أحجار، وفي غسل الإناء من ولوغ الكلب سبعًا، ولا يُشترط فيما سواه، وهو قول الشافعي."},{"t":"qawl","label":"القول الثالث","text":"يُشترط السبع في غسل سائر النجاسات قياسًا على ولوغ الكلب، وهو رواية عن أحمد."},{"t":"quote","text":"وَمَا لَيْسَ بِمَرْئِيٍّ فَطَهَارَتُهُ أَنْ يُغْسَلَ حَتَّى يَغْلِبَ عَلَى ظَنِّ الْغَاسِلِ أَنَّهُ قَدْ طَهُرَ لِأَنَّ التَّكْرَارَ لَا بُدَّ مِنْهُ لِلِاسْتِخْرَاجِ، وَلَا يُقْطَعُ بِزَوَالِهِ فَاعْتُبِرَ غَالِبُ الظَّنِّ كَمَا فِي أَمْرِ الْقِبْلَةِ وَإِنَّمَا قَدَّرُوا بِالثَّلَاثِ لِأَنَّ غَالِبَ الظَّنِّ يَحْصُلُ عِنْدَهُ","src":"الهداية مع فتح القدير","loc":"١/٢٠٩","pre":"جاء في «الهداية» للمرغيناني الحنفي مع شرحه «فتح القدير»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المقصود إزالة عين النجاسة، فلا يشترط عدد إلا فيما ورد فيه النص، وهو ولوغ الكلب، فيُغسل الإناء سبع مرات إحداهن بالتراب؛ لأن النبي ﷺ أمر بحتّ دم الحيض وقرصه بالماء ونضحه، ولم يذكر عددًا. فإن كانت النجاسة مرئية غُسلت حتى تزول عينها، ولا يضر بقاء لون أو ريح عسر زواله، كما جاء عن النبي ﷺ في دم الحيض: «يكفيك غسل الدم ولا يضرك أثره» (رواه أبو داود ٣٦٥). وإن كانت غير مرئية كالبول الجاف غسل موضعها حتى يغلب على الظن زوالها، والتثليث أحوط كما يقول الحنفية."}],"refs":["البخاري ٢٢٧","مسلم ٢٧٩","الهداية مع فتح القدير (١/٢٠٩)"],"related":["ما تُزال به النجاسة، وتطهير النعل والذيل والأرض"],"alts":["غسل النجاسة ثلاثا","بقاء أثر النجاسة","غسل ولوغ الكلب","النجاسة الحكمية"]},{"n":79,"bab":"الطهارة","sub":"النجاسات","title":"هل الخمر نجسة؟ وحكم العطور والمنظفات التي فيها كحول","q":"هل الخمر نجسة نجاسة حسية؟ وهل تجوز الصلاة بثوب فيه عطر كحولي أو معقم يدين؟","short":"الخمر محرمة شربًا بالإجماع، وهي نجسة نجاسة حسية عند المذاهب الأربعة وعامة العلماء، وذهب ربيعة والليث وبعض المحدثين وجماعة من المتأخرين إلى أن نجاستها معنوية لا حسية. والكحول المضاف إلى العطور والمعقمات لا تبطل به الصلاة على القول بطهارته، والأحوط اجتنابه في الثوب عند الصلاة.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّمَا ٱلْخَمْرُ وَٱلْمَيْسِرُ وَٱلْأَنصَابُ وَٱلْأَزْلَـٰمُ رِجْسٌ مِّنْ عَمَلِ ٱلشَّيْطَـٰنِ فَٱجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ","ref":"المائدة: ٩٠"},{"t":"quote","text":"كُنْتُ سَاقِيَ الْقَوْمِ فِي مَنْزِلِ أَبِي طَلْحَةَ، وَكَانَ خَمْرُهُمْ يَوْمَئِذٍ الْفَضِيخَ، فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم مُنَادِيًا يُنَادِي «أَلاَ إِنَّ الْخَمْرَ قَدْ حُرِّمَتْ». قَالَ فَقَالَ لِي أَبُو طَلْحَةَ اخْرُجْ فَأَهْرِقْهَا، فَخَرَجْتُ فَهَرَقْتُهَا، فَجَرَتْ فِي سِكَكِ الْمَدِينَةِ","src":"رواه البخاري ٢٤٦٤","pre":"عن أنس رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":2464,"id":"h2464"}]},{"t":"quote","text":"إِنَّ رَجُلًا أَهْدَى لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَاوِيَةَ خَمْرٍ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «هَلْ عَلِمْتَ أَنَّ اللهَ قَدْ حَرَّمَهَا؟» قَالَ: لَا، فَسَارَّ إِنْسَانًا، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «بِمَ سَارَرْتَهُ؟»، فَقَالَ: أَمَرْتُهُ بِبَيْعِهَا، فَقَالَ: «إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا»، قَالَ: فَفَتَحَ الْمَزَادَةَ حَتَّى ذَهَبَ مَا فِيهَا","src":"رواه مسلم ١٥٧٩","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_muslim","num":1579,"id":"h1579"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الخمر نجسة نجاسة حسية، يجب غسل ما أصابته، وهو قول أبي حنيفة ومالك والشافعي وأحمد وعامة العلماء."},{"t":"qawl","label":"القول الثاني","text":"الخمر طاهرة العين، ونجاستها معنوية، وهو قول ربيعة والليث بن سعد والمزني وبعض المحدثين، واختاره الشوكاني والصنعاني وابن عثيمين."},{"t":"quote","text":"وَأَكْثَرُهُمْ عَلَى نَجَاسَةِ الْخَمْرِ، وَفِي ذَلِكَ خِلَافٌ عَنْ بَعْضِ الْمُحَدِّثِينَ","src":"بداية المجتهد","loc":"١/٨٣","pre":"قال ابن رشد:"},{"t":"quote","text":"وَالْخَمْرُ نَجِسَةٌ. فِي قَوْلِ عَامَّة أَهْل الْعِلْمِ؛ لِأَنَّ اللَّهَ تَعَالَى حَرَّمَهَا لِعَيْنِهَا، فَكَانَتْ نَجِسَةً، كَالْخِنْزِيرِ","src":"المغني","loc":"٩/١٧١","pre":"وقال ابن قدامة:"},{"t":"h","text":"أدلة القول الثاني"},{"t":"quote","text":"وقالوا أيضا: إنه ثبت أنه لما نزل تحريم الخمر أراقها المسلمون في الأسواق، ولو كانت نجسة ما جازت إراقتها في الأسواق لأن تلويث الأسواق بالنجاسات محرم ولا يجوز","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٥١","pre":"قال ابن عثيمين في حكاية أدلتهم:"},{"t":"quote","text":"وبناء على ذلك نقول في الكولونيا وشبهها: إنها ليست بنجسة لأن الخمر ذاته ليس بنجس على هذا القول الذي ذكرناه أدلته، فتكون الكولونيا وشبهها ليست بنجسة أيضا، وإذا لم تكن نجسة فإنه لا يجب تطهير الثياب منها","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٥٢","pre":"ثم قال:"},{"t":"quote","text":"الخمر نجسة عِنْدَنَا وَعِنْدَ مَالِكٍ وَأَبِي حَنِيفَةَ وَأَحْمَدَ وَسَائِرِ الْعُلَمَاءِ إلَّا مَا حَكَاهُ الْقَاضِي أَبُو الطَّيِّبِ وَغَيْرُهُ عَنْ رَبِيعَةَ شَيْخِ مَالِكٍ وَدَاوُد أَنَّهُمَا قَالَا هِيَ طَاهِرَةٌ","src":"المجموع","loc":"٢/٥٦٣","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"هذه المسألة وهي نجاسة الخمر، إن أريد بالنجاسة النجاسة المعنوية، فإن العلماء مجمعون على ذلك، فإن الخمر نجس وخبيث، ومن أعمال الشيطان؛ وإن أريد بها النجاسة الحسية فإن المذاهب الأربعة وعامة الأمة على إنها نجسة","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢٥٠","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن نجاسة الخمر، فقال:"},{"t":"quote","text":"الأصل حل العطور والأطياب التي بين الناس إلا ما علم أن به ما يمنع استعماله؛ لكونه مسكرا أو يسكر كثيره، أو به نجاسة ونحو ذلك، وإلا فالأصل حل العطور التي بين الناس كالعود والعنبر والمسك","src":"مجموع فتاوى ابن باز","loc":"٣/٣٤٣","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن العطور التي فيها شيء من الكحول، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الخمر رجس محرم بنص القرآن، ولا خلاف في تحريم شربها وبيعها. وأما نجاسة عينها فقول الجمهور أحوط، وقول من قال بطهارتها الحسية أقوى من جهة الدليل؛ لأن الصحابة أراقوها في طرق المدينة، ولم يأمر النبي ﷺ بغسل الأواني منها، والرجس في الآية مقرون بالميسر والأنصاب والأزلام وهي ليست نجسة العين. وعليه فالعطور والمعقمات الكحولية لا تنجس الثوب ولا البدن، ولا تبطل بها الصلاة، ومن تورع عنها عند الصلاة خروجًا من خلاف الجمهور فقد أحسن، وأما شربها فحرام إن كانت تسكر."}],"refs":["البخاري ٢٤٦٤","مسلم ١٥٧٩","بداية المجتهد (١/٨٣)","المغني (٩/١٧١)","مجموع فتاوى ابن عثيمين (١١/٢٥١)","مجموع فتاوى ابن عثيمين (١١/٢٥٢)","المجموع (٢/٥٦٣)","مجموع فتاوى ابن عثيمين (١١/٢٥٠)","مجموع فتاوى ابن باز (٣/٣٤٣)"],"related":["ما تُزال به النجاسة، وتطهير النعل والذيل والأرض"],"alts":["نجاسة الخمر","العطر الكحولي","معقم اليدين والصلاة","الكولونيا"]},{"n":80,"bab":"الطهارة","sub":"قضاء الحاجة","title":"استقبال القبلة واستدبارها عند قضاء الحاجة","q":"المرحاض في بيتنا متجه إلى القبلة، فهل يجوز قضاء الحاجة فيه؟ وما الحكم في الصحراء؟","short":"اتفق العلماء على أن الأدب ترك استقبال القبلة واستدبارها عند قضاء الحاجة، واختلفوا في البنيان: فمنعه أبو حنيفة وأحمد في رواية في الصحراء والبنيان جميعًا، وأجازه مالك والشافعي وأحمد في رواية في البنيان دون الصحراء. والأحوط اجتنابه مطلقًا، ومن بُني مرحاضه إلى القبلة انحرف عنها ما استطاع، ولا إثم عليه في البنيان على قول الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا أَتَيْتُمُ الْغَائِطَ فَلاَ تَسْتَقْبِلُوا الْقِبْلَةَ وَلاَ تَسْتَدْبِرُوهَا، وَلَكِنْ شَرِّقُوا أَوْ غَرِّبُوا «. قَالَ أَبُو أَيُّوبَ فَقَدِمْنَا الشَّأْمَ فَوَجَدْنَا مَرَاحِيضَ بُنِيَتْ قِبَلَ الْقِبْلَةِ، فَنَنْحَرِفُ وَنَسْتَغْفِرُ اللَّهَ تَعَالَى»","src":"رواه البخاري ٣٩٤","pre":"عن أبي أيوب الأنصاري رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":394,"id":"h394"}]},{"t":"quote","text":"ارْتَقَيْتُ فَوْقَ ظَهْرِ بَيْتِ حَفْصَةَ لِبَعْضِ حَاجَتِي، فَرَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقْضِي حَاجَتَهُ مُسْتَدْبِرَ الْقِبْلَةِ مُسْتَقْبِلَ الشَّأْمِ","src":"رواه البخاري ١٤٨","pre":"وعن عبد الله بن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":148,"id":"h148"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجوز استقبال القبلة ولا استدبارها لا في الصحراء ولا في البنيان، وهو قول أبي حنيفة، ورواية عن أحمد، واختيار ابن تيمية."},{"t":"qawl","label":"القول الثاني","text":"يحرم في الصحراء ويجوز في البنيان، وهو قول مالك والشافعي، ورواية عن أحمد."},{"t":"qawl","label":"القول الثالث","text":"يجوز مطلقًا، وهو قول داود الظاهري ومن رأى التعارض."},{"t":"quote","text":"وَإِنَّمَا اخْتَلَفُوا مِنْ ذَلِكَ فِي مَسْأَلَةٍ وَاحِدَةٍ مَشْهُورَةٍ، وَهِيَ اسْتِقْبَالُ الْقِبْلَةِ لِلْغَائِطِ، وَالْبَوْلِ وَاسْتِدْبَارُهَا، فَإِنَّ لِلْعُلَمَاءِ فِيهَا ثَلَاثَةَ أَقْوَالٍ: إِنَّهُ لَا يَجُوزُ أَنْ تُسْتَقْبَلَ الْقِبْلَةُ لِغَائِطٍ، وَلَا بَوْلٍ أَصْلًا، وَلَا فِي مَوْضِعٍ مِنَ الْمَوَاضِعِ. وَقَوْلٌ: إِنَّ ذَلِكَ يَجُوزُ بِإِطْلَاقٍ. وَقَوْلٌ: إِنَّهُ يَجُوزُ فِي الْمَبَانِي وَالْمُدُنِ، وَلَا يَجُوزُ ذَلِكَ فِي الصَّحْرَاءِ وَفِي غَيْرِ الْمَبَانِي وَالْمُدُنِ","src":"بداية المجتهد","loc":"١/٩٤","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا يجوز استقبال القبلة واستدبارها عند قضاء الحاجة من بول أو غائط، إذا كان الإنسان في الصحراء؛ لما ثبت عن النبي - صلى الله عليه وسلم - من النهي عن ذلك، من حديث أبي أيوب الأنصاري - رضي الله عنه - وغيره","src":"مجموع فتاوى ابن باز","loc":"١٠/٣٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأحوط والأظهر ألا يستقبل القبلة ولا يستدبرها في الصحراء ولا في البنيان؛ لعموم حديث أبي أيوب، وهو قول صريح، ولأن أبا أيوب رضي الله عنه راوي الحديث كان ينحرف في مراحيض الشام ويستغفر، فدل على أنه فهم العموم. وأما حديث ابن عمر ففعل يحتمل الخصوصية أو العذر، وقد رآه ابن عمر اتفاقًا. لكن من كان في بنيان وشق عليه الانحراف فلا إثم عليه على قول الجمهور، ومن بنى بيتًا جديدًا فليجعل المرحاض إلى غير القبلة."}],"refs":["البخاري ٣٩٤","البخاري ١٤٨","بداية المجتهد (١/٩٤)","مجموع فتاوى ابن باز (١٠/٣٥)","بداية المجتهد (١/٩٥)"],"related":["الاستجمار بالحجارة: عددها وما يجوز به"],"alts":["المرحاض باتجاه القبلة","استقبال القبلة بالبول","قضاء الحاجة في البنيان"]},{"n":81,"bab":"الطهارة","sub":"قضاء الحاجة","title":"الاستجمار بالحجارة والمناديل: عددها وما يجوز به","q":"هل يكفي المسح بالمناديل الورقية بدل الماء؟ وهل يشترط ثلاث مسحات؟ وما الذي لا يجوز الاستنجاء به؟","short":"يجوز الاستجمار بالحجارة وكل جامد طاهر منقٍ كالمناديل الورقية بالاتفاق، ويجزئ عن الماء. واشترط الشافعي وأحمد ألا يقل عن ثلاث مسحات منقية، واكتفى أبو حنيفة ومالك بالإنقاء ولو بأقل. ولا يجوز بالعظم والروث وما له حرمة كالطعام والأوراق المحترمة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قِيلَ لَهُ: قَدْ عَلَّمَكُمْ نَبِيُّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّ شَيْءٍ حَتَّى الْخِرَاءَةَ قَالَ: فَقَالَ: أَجَلْ «لَقَدْ نَهَانَا أَنْ نَسْتَقْبِلَ الْقِبْلَةَ لِغَائِطٍ، أَوْ بَوْلٍ، أَوْ أَنْ نَسْتَنْجِيَ بِالْيَمِينِ، أَوْ أَنْ نَسْتَنْجِيَ بِأَقَلَّ مِنْ ثَلَاثَةِ أَحْجَارٍ، أَوْ أَنْ نَسْتَنْجِيَ بِرَجِيعٍ أَوْ بِعَظْمٍ»","src":"رواه مسلم ٢٦٢","pre":"عن سلمان الفارسي رضي الله عنه:","links":[{"book":"mt_muslim","num":262,"id":"h262"}]},{"t":"quote","text":"أَتَى النَّبِيُّ صلى الله عليه وسلم الْغَائِطَ، فَأَمَرَنِي أَنْ آتِيَهُ بِثَلاَثَةِ أَحْجَارٍ، فَوَجَدْتُ حَجَرَيْنِ، وَالْتَمَسْتُ الثَّالِثَ فَلَمْ أَجِدْهُ، فَأَخَذْتُ رَوْثَةً، فَأَتَيْتُهُ بِهَا، فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى الرَّوْثَةَ وَقَالَ «هَذَا رِكْسٌ»","src":"رواه البخاري ١٥٦","pre":"وعن عبد الله بن مسعود رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":156,"id":"h156"}]},{"t":"quote","text":"مَنْ تَوَضَّأَ فَلْيَسْتَنْثِرْ، وَمَنِ اسْتَجْمَرَ فَلْيُوتِرْ","src":"رواه البخاري ١٦١","pre":"وعن أبي هريرة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":161,"id":"h161"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يجزئ أقل من ثلاث مسحات منقية، وإن لم ينق بها زاد، ويستحب الإيتار، وهو قول الشافعي وأحمد وأهل الظاهر."},{"t":"qawl","label":"القول الثاني","text":"المعتبر الإنقاء، فإن حصل بأقل من ثلاث أجزأ، والعدد مستحب، وهو قول أبي حنيفة ومالك."},{"t":"quote","text":"أَمَّا مَنْ لَمْ يَشْتَرِطِ الْعَدَدَ لَا فِي غَسْلٍ وَلَا فِي مَسْحٍ فَمِنْهُمْ مَالِكٌ وَأَبُو حَنِيفَةَ. وَأَمَّا مَنِ اشْتَرَطَ فِي الِاسْتِجْمَارِ الْعَدَدَ: أَعْنِي ثَلَاثَةَ أَحْجَارٍ لَا أَقَلَّ مِنْ ذَلِكَ، فَمِنْهُمُ الشَّافِعِيُّ وَأَهْلُ الظَّاهِرِ","src":"بداية المجتهد","loc":"١/٩٣","pre":"قال ابن رشد:"},{"t":"quote","text":"استدل بعض الحنيفة بحديث الباب على عدم وجوب التثليث والإيتار بأنه ألقى الروثة، واستنجى بالحجرين، ولكنه في رواية: أنه ألقى الروثة، وقال: ائتني بثالث","src":"العرف الشذي","loc":"١/٦٠","pre":"وقال الكشميري الحنفي منصفًا:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه لا يجزئ في الاستجمار أقل من ثلاث مسحات منقية؛ لنهيه ﷺ الصريح: «أن نستنجي بأقل من ثلاثة أحجار»، ولما أتاه ابن مسعود بحجرين وروثة ألقى الروثة وطلب ثالثًا كما ذكر الكشميري الحنفي نفسه؛ فإن لم يحصل الإنقاء بالثلاث زاد حتى ينقي، ويستحب أن يقطع على وتر. ويجزئ كل جامد طاهر منقٍ غير محترم: كالحجر والمناديل الورقية والخرق، ولا يجوز بالعظم والروث والطعام، ولا بالورق المكتوب فيه ذكر الله أو العلم."}],"refs":["مسلم ٢٦٢","البخاري ١٥٦","البخاري ١٦١","بداية المجتهد (١/٩٣)","العرف الشذي (١/٦٠)","بداية المجتهد (١/٩٠)"],"related":["الاستنجاء بالماء، والجمع بينه وبين الحجارة، والاستنجاء باليمين"],"alts":["المناديل بدل الماء","ثلاث مسحات","الاستجمار بالعظم","الاستنجاء بالورق"]},{"n":82,"bab":"الطهارة","sub":"قضاء الحاجة","title":"الاستنجاء بالماء، والجمع بينه وبين الحجارة، والاستنجاء باليمين","q":"أيهما أفضل: الاستنجاء بالماء أو بالمناديل؟ وهل يجوز الاستنجاء باليد اليمنى؟","short":"يجوز الاستنجاء بالماء وحده، وبالحجارة وحدها، والجمع بينهما أفضل، ثم الماء أفضل من الحجارة عند عامة العلماء. ويكره الاستنجاء باليمين ومس الذكر بها عند قضاء الحاجة كراهة تنزيه عند الجمهور، ولا يبطل به الاستنجاء.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"فِيهِ رِجَالٌ يُحِبُّونَ أَن يَتَطَهَّرُوا۟ ۚ وَٱللَّهُ يُحِبُّ ٱلْمُطَّهِّرِينَ","ref":"التوبة: ١٠٨"},{"t":"quote","text":"نَزَلَتْ هَذِهِ الآيَةُ فِي أَهْلِ قُبَاءَ { فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا } قَالَ كَانُوا يَسْتَنْجُونَ بِالْمَاءِ فَنَزَلَتْ فِيهِمْ هَذِهِ الآيَةُ","src":"رواه أبو داود ٤٤","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":44,"id":"h44"}]},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْخُلُ الْخَلَاءَ فَأَحْمِلُ أَنَا، وَغُلَامٌ نَحْوِي، إِدَاوَةً مِنْ مَاءٍ، وَعَنَزَةً فَيَسْتَنْجِي بِالْمَاءِ","src":"رواه مسلم ٢٧١","pre":"وعن أنس رضي الله عنه قال:","links":[{"book":"mt_muslim","num":271,"id":"h271"}]},{"t":"quote","text":"إِذَا بَالَ أَحَدُكُمْ فَلاَ يَأْخُذَنَّ ذَكَرَهُ بِيَمِينِهِ، وَلاَ يَسْتَنْجِي بِيَمِينِهِ، وَلاَ يَتَنَفَّسْ فِي الإِنَاءِ","src":"رواه البخاري ١٥٤","pre":"وعن أبي قتادة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":154,"id":"h154"}]},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الاستنجاء بالماء أفضل من الحجارة؛ لأنه أبلغ في التطهير، وقد أثنى الله على أهل قباء، وكان النبي ﷺ يستنجي بالماء. والجمع بين المسح بالحجارة أو المناديل ثم الغسل بالماء أكمل الأحوال. ويكره الاستنجاء باليمين ومس الذكر بها حال البول؛ تكريمًا لليمين، فإن احتاج إليها لعذر فلا حرج."},{"t":"tanbih","items":[{"t":"p","text":"إذا تعدت النجاسة موضع الخروج تعديًا كثيرًا لم يجزئ فيها إلا الماء."},{"t":"p","text":"لا يجب الاستنجاء من الريح ولا من النوم، وإنما يجب من الخارج كالبول والغائط والمذي."}]}],"refs":["أبو داود ٤٤","مسلم ٢٧١","البخاري ١٥٤"],"related":["الاستجمار بالحجارة والمناديل: عددها وما يجوز به"],"alts":["الماء أم المناديل","الاستنجاء باليد اليمنى","الاستنجاء من الريح"]},{"n":83,"bab":"الطهارة","sub":"قضاء الحاجة","title":"البول قائمًا","q":"هل يجوز البول قائمًا في المراحيض الحديثة؟","short":"يجوز البول قائمًا إذا أمن أن يصيبه الرشاش وأن تنكشف عورته، وهو قول الجمهور؛ والأفضل البول قاعدًا، لأنه أكثر حال النبي ﷺ، وكرهه بعض العلماء ومنهم الحنفية كراهة تنزيه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَتَى النَّبِيُّ صلى الله عليه وسلم سُبَاطَةَ قَوْمٍ فَبَالَ قَائِمًا، ثُمَّ دَعَا بِمَاءٍ، فَجِئْتُهُ بِمَاءٍ فَتَوَضَّأَ","src":"رواه البخاري ٢٢٤","pre":"عن حذيفة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":224,"id":"h224"}]},{"t":"quote","text":"مَنْ حَدَّثَكُمْ أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَبُولُ قَائِمًا فَلاَ تُصَدِّقُوهُ مَا كَانَ يَبُولُ إِلاَّ قَاعِدًا","src":"رواه الترمذي ١٢","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_tirmidhi","num":12,"id":"h12"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يجوز البول قائمًا بلا كراهة إذا أمن الرشاش والنظر، وهو قول أحمد والشافعي في المشهور، وروي عن عمر وعلي وزيد بن ثابت وابن عمر رضي الله عنهم."},{"t":"qawl","label":"القول الثاني","text":"يكره البول قائمًا إلا لعذر، وهو قول الحنفية، وروي عن ابن مسعود رضي الله عنه."},{"t":"quote","text":"قيل: إن الصديقة تنفي عادته من البول قائماً، أي لم يكن يعتاده، أو يقال: إنها تذكر علمها، أو نقول: إن رواية حُذيفة في حال العذر، وأيضاً البول قائماً جائز، وخلاف الأدب، ويكره تنزيهاً","src":"العرف الشذي","loc":"١/٥٦","pre":"قال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن البول قائمًا جائز إذا أمن الرشاش وستر العورة؛ لحديث حذيفة في الصحيحين، وعائشة رضي الله عنها أخبرت بما رأت في البيوت، وحذيفة أخبر بما رأى خارجها، والمثبت مقدم. والأفضل البول قاعدًا؛ لأنه الغالب من فعله ﷺ، وأستر وأبعد عن الرشاش. وأما ما شاع في بعض الأماكن من مباول مكشوفة يقف فيها الناس متجاورين فينبغي تجنبها؛ لما فيها من كشف العورة وتطاير النجاسة."}],"refs":["البخاري ٢٢٤","الترمذي ١٢","العرف الشذي (١/٥٦)"],"related":["آداب الخلاء: الذكر والكلام ودخوله بما فيه ذكر الله"],"alts":["البول واقفا","المباول الحديثة","التبول قائما"]},{"n":84,"bab":"الطهارة","sub":"قضاء الحاجة","title":"آداب الخلاء: الذكر والكلام، ودخوله بما فيه ذكر الله","q":"هل يجوز الكلام في دورة المياه؟ وهل أدخلها بالهاتف وفيه القرآن، أو بخاتم أو قلادة فيها اسم الله؟","short":"آداب قضاء الحاجة أكثرها مستحبة عند الفقهاء: كالتسمية والتعوذ عند الدخول، وتقديم اليسرى، والاستتار، وترك الكلام والذكر حال قضاء الحاجة، وقول «غفرانك» عند الخروج. ويكره دخول الخلاء بما فيه ذكر الله إلا لحاجة أو خوف ضياعه، ويحرم إدخال المصحف إلا لضرورة. والهاتف الذي فيه القرآن ليس له حكم المصحف ما دام القرآن غير معروض على الشاشة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ قَالَ «اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ»","src":"رواه البخاري ١٤٢","pre":"عن أنس رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":142,"id":"h142"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا خَرَجَ مِنَ الْخَلاَءِ قَالَ «غُفْرَانَكَ»","src":"رواه الترمذي ٧","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_tirmidhi","num":7,"id":"h7"}]},{"t":"quote","text":"مَرَّ رَجُلٌ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَبُولُ فَسَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ","src":"رواه أبو داود ١٦","pre":"وعن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":16,"id":"h16"}]},{"t":"quote","text":"وَأَمَّا آدَابُ الِاسْتِنْجَاءِ وَدُخُولِ الْخَلَاءِ، فَأَكْثَرُهَا مَحْمُولَةٌ عِنْدَ الْفُقَهَاءِ عَلَى النَّدْبِ، وَهِيَ مَعْلُومَةٌ مِنَ السُّنَّةِ كَالْبُعْدِ فِي الْمَذْهَبِ إِذَا أَرَادَ الْحَاجَةَ، وَتَرْكِ الْكَلَامِ عَلَيْهَا، وَالنَّهْيِ عَنْ الِاسْتِنْجَاءِ بِالْيَمِينِ، وَأَلَّا يَمَسَّ ذَكَرَهُ بِيَمِينِهِ، وَغَيْرِ ذَلِكَ مِمَّا وَرَدَ فِي الْآثَارِ","src":"بداية المجتهد","loc":"١/٩٤","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يستحب لمن أراد دخول الخلاء أن يقول: «بسم الله، اللهم إني أعوذ بك من الخبث والخبائث»، ويقدم رجله اليسرى في الدخول واليمنى في الخروج، ويقول عند خروجه: «غفرانك»، ويستتر عن الناس، ولا يتكلم ولا يذكر الله بلسانه حال قضاء الحاجة إلا لحاجة كإرشاد أعمى أو تحذير من خطر؛ فإن النبي ﷺ لم يرد السلام وهو يبول."},{"t":"p","text":"ولا يُدخل المصحف الخلاء إلا لضرورة كخوف سرقته، ويكره دخوله بما فيه ذكر الله كالخاتم والقلادة إلا إذا خاف ضياعه أو أخفاه في جيبه. وأما الهاتف الذي فيه تطبيق القرآن فلا يأخذ حكم المصحف؛ لأن الحروف ليست ثابتة فيه، وإنما تظهر عند التشغيل، فلا بأس بإدخاله مغلقًا أو في الجيب، والأولى ألا يُفتح فيه القرآن هناك."}],"refs":["البخاري ١٤٢","الترمذي ٧","أبو داود ١٦","بداية المجتهد (١/٩٤)"],"related":["البول قائمًا"],"alts":["الكلام في الحمام","دخول الحمام بالجوال","دعاء دخول الخلاء","الخاتم فيه اسم الله"]},{"n":85,"bab":"الطهارة","sub":"ما تشترط له الطهارة","title":"مس المصحف لغير المتوضئ","q":"هل يجوز لي مس المصحف وأنا على غير وضوء؟ وهل يجوز للأطفال في المدارس مس المصحف بغير وضوء؟","short":"ذهب الأئمة الأربعة وجمهور العلماء من الصحابة والتابعين إلى أن المحدث لا يمس المصحف حتى يتوضأ، وأجازه أهل الظاهر. ويجوز للمحدث القراءة من حفظه، ومس المصحف بحائل منفصل، وتقليب أوراقه بعود ونحوه، ورخص مالك وغيره للصبيان في مسه للتعلم.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ","ref":"الواقعة: ٧٩"},{"t":"p","text":"وفي كتاب النبي ﷺ لعمرو بن حزم رضي الله عنه: «ألا يمس القرآن إلا طاهر»، رواه مالك في الموطأ وغيره، وتلقاه العلماء بالقبول."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يحرم على المحدث مس المصحف، وهو قول الأئمة الأربعة، وروي عن علي وابن مسعود وسعد بن أبي وقاص وابن عمر رضي الله عنهم."},{"t":"qawl","label":"القول الثاني","text":"يجوز للمحدث مس المصحف، وهو قول داود وابن حزم، وروي عن الحكم وحماد."},{"t":"quote","text":"هَلْ هَذِهِ الطَّهَارَةُ شَرْطٌ فِي مَسِّ الْمُصْحَفِ أَمْ لَا؟ فَذَهَبَ مَالِكٌ وَأَبُو حَنِيفَةَ وَالشَّافِعِيُّ إِلَى أَنَّهَا شَرْطٌ فِي مَسِّ الْمُصْحَفِ، وَذَهَبَ أَهْلُ الظَّاهِرِ إِلَى أَنَّهَا لَيْسَتْ بِشَرْطٍ فِي ذَلِكَ","src":"بداية المجتهد","loc":"١/٤٧","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا يجوز للحائض مس المصحف عند جمهور العلماء؛ لقوله تعالى: {لَا يَمَسُّهُ إِلَّا الْمُطَهَّرُونَ} ولقول النبي صلى الله عليه وسلم في كتاب عمرو بن حزم: «لا يمس القرآن إلا طاهر»","src":"فتاوى اللجنة الدائمة","loc":"٤/١٠٩","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"قراءة القرآن لمن عليه حدث أصغر لا بأس بها إذا لم يمس المصحف، لأنه ليس من شرط جواز القراءة أن يكون الإنسان على طهارة","src":"مجموع فتاوى ابن عثيمين","loc":"١١/٢١٢","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر قول الجمهور: أن المحدث لا يمس المصحف حتى يتوضأ؛ لكتاب عمرو بن حزم، وهو كتاب مشهور تلقته الأمة بالقبول، ولأنه قول من عُرف من الصحابة ولا يعرف لهم مخالف، وتعظيمًا لكلام الله. ويجوز للمحدث أن يقرأ القرآن من حفظه، أو ينظر في المصحف دون مسه، أو يمسه بحائل منفصل كالقفاز أو الكيس، ويجوز مس كتب التفسير التي أكثرها تفسير، ومس الهاتف والحاسوب الذي فيه القرآن. وأما الصبيان في التعليم فيُرخص لهم للحاجة كما قال مالك، ويُعوّدون الوضوء ما أمكن."}],"refs":["بداية المجتهد (١/٤٧)","فتاوى اللجنة الدائمة (٤/١٠٩)","مجموع فتاوى ابن عثيمين (١١/٢١٢)"],"related":["قراءة الحائض القرآن ومسها المصحف","قراءة القرآن للجنب"],"alts":["لمس القرآن بدون وضوء","المصحف والمحدث","مس كتب التفسير","الأطفال ومس المصحف"]},{"n":86,"bab":"الطهارة","sub":"ما تشترط له الطهارة","title":"الجنب ينام أو يأكل أو يعاود الجماع قبل أن يغتسل","q":"هل يجوز للجنب أن ينام قبل الغسل ويؤخره إلى الفجر؟ وماذا يُستحب له؟","short":"يجوز للجنب أن ينام ويأكل ويعاود الجماع قبل الغسل بالاتفاق، ويستحب له أن يغسل فرجه ويتوضأ وضوءه للصلاة قبل ذلك عند الجمهور، وأوجب الوضوء للنوم أهل الظاهر. ويجب عليه أن يغتسل قبل خروج وقت الصلاة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"ذَكَرَ عُمَرُ بْنُ الْخَطَّابِ لِرَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ تُصِيبُهُ الْجَنَابَةُ مِنَ اللَّيْلِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم «تَوَضَّأْ وَاغْسِلْ ذَكَرَكَ ثُمَّ نَمْ»","src":"رواه البخاري ٢٩٠","pre":"عن عبد الله بن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":290,"id":"h290"}]},{"t":"quote","text":"إِذَا أَتَى أَحَدُكُمْ أَهْلَهُ، ثُمَّ أَرَادَ أَنْ يَعُودَ، فَلْيَتَوَضَّأْ","src":"رواه مسلم ٣٠٨","pre":"وعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":308,"id":"h308"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يُستحب للجنب إذا أراد النوم أو الأكل أو معاودة الجماع أن يتوضأ، ولا يجب، وهو قول الجمهور، ومنهم الأئمة الأربعة."},{"t":"qawl","label":"القول الثاني","text":"يجب الوضوء على الجنب إذا أراد النوم، لأمر النبي ﷺ عمر رضي الله عنه بذلك، وهو قول أهل الظاهر."},{"t":"quote","text":"وَلَهُ أَنْ يَنَامَ قَبْلَ أَنْ يَتَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ لِمَا رُوِيَ عَنْ عَائِشَةَ - رَضِيَ اللَّهُ عَنْهَا - أَنَّهَا قَالَتْ «كَانَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يَنَامُ، وَهُوَ جُنُبٌ مِنْ غَيْرِ أَنْ يَمَسَّ مَاءً» ، وَلِأَنَّ الْوُضُوءَ لَيْسَ بِقُرْبَةٍ بِنَفْسِهِ، وَإِنَّمَا هُوَ لِأَدَاءِ الصَّلَاةِ، وَلَيْسَ فِي النَّوْمِ ذَلِكَ","src":"بدائع الصنائع","loc":"١/٣٨","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"مكروه، السنة أن يتوضأ، أقل شيء يتوضأ، السنة أن يتوضأ ثم ينام، كان النبي صلى الله عليه وسلم إذا أتى أهله يغسل فرجه ويتوضأ ثم ينام عليه الصلاة والسلام، وربما اغتسل قبل ذلك، فإذا اغتسل فهو أكمل","src":"فتاوى نور على الدرب لابن باز","loc":"٥/٣١١","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن الجنب ينام دون أن يغتسل أو يتوضأ، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يجوز للجنب أن يؤخر الغسل وينام، لكن السنة أن يغسل فرجه ويتوضأ وضوءه للصلاة قبل أن ينام، أو يأكل، أو يعاود الجماع؛ لأمره ﷺ بذلك، وحمله الجمهور على الاستحباب لما ثبت من أنه ﷺ كان أحيانًا ينام وهو جنب ثم يغتسل. ولا يجوز له أن يؤخر الغسل حتى يخرج وقت الصلاة."}],"refs":["البخاري ٢٩٠","مسلم ٣٠٨","بدائع الصنائع (١/٣٨)","فتاوى نور على الدرب لابن باز (٥/٣١١)"],"related":["قراءة القرآن للجنب","مكث الجنب في المسجد ومروره فيه"],"alts":["النوم على جنابة","تأخير غسل الجنابة","الوضوء قبل النوم للجنب"]},{"n":87,"bab":"الصلاة","sub":"وجوب الصلاة","title":"حكم تارك الصلاة","q":"ما حكم من يترك الصلاة تكاسلًا وهو مقر بوجوبها؟ هل هو كافر أم مسلم عاصٍ؟","short":"أجمع المسلمون على أن من جحد وجوب الصلاة كفر. واختلفوا فيمن تركها كسلًا وهو مقر بوجوبها: فذهب أحمد في المشهور عنه وإسحاق وابن المبارك وجماعة من الصحابة إلى أنه يكفر، وذهب مالك والشافعي إلى أنه لا يكفر ولكن يُقتل حدًّا إن أصر بعد الاستتابة، وذهب أبو حنيفة إلى أنه يُحبس ويعزّر حتى يصلي. وكلهم متفقون على أنه مرتكب لأعظم الكبائر بعد الشرك.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكَ الصَّلَاةِ","src":"رواه مسلم ٨٢","pre":"عن جابر رضي الله عنه قال: سمعت النبي ﷺ يقول:","links":[{"book":"mt_muslim","num":82,"id":"h82"}]},{"t":"quote","text":"الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلاَةُ فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ","src":"رواه الترمذي ٢٦٢١، والنسائي ٤٦٣، وابن ماجه ١٠٧٩","pre":"وعن بريدة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":2621,"id":"h2621"},{"book":"mt_nasai","num":463,"id":"h463"},{"book":"mt_ibnmajah","num":1079,"id":"h1079"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"تارك الصلاة كسلًا كافر كفرًا يخرج من الملة، ويُقتل ردة إن لم يتب، وهو قول أحمد في المشهور عنه، وإسحاق، وابن المبارك، وروي عن عمر وابن مسعود وجماعة من الصحابة."},{"t":"qawl","label":"القول الثاني","text":"لا يكفر، لكنه يُستتاب، فإن صلى وإلا قُتل حدًّا، وهو قول مالك والشافعي، ورواية عن أحمد."},{"t":"qawl","label":"القول الثالث","text":"لا يكفر ولا يُقتل، بل يُحبس ويعزّر حتى يصلي، وهو قول أبي حنيفة وأصحابه، والمزني، وأهل الظاهر."},{"t":"quote","text":"وَأَمَّا مَا الْوَاجِبُ عَلَى مَنْ تَرَكَهَا عَمْدًا، وَأُمِرَ بِهَا فَأَبَى أَنْ يُصَلِّيَهَا لَا جُحُودًا لِفَرْضِهَا، فَإِنَّ قَوْمًا قَالُوا: يُقْتَلُ، وَقَوْمًا قَالُوا: يُعَزَّرُ وَيُحْبَسُ، وَالَّذِينَ قَالُوا يُقْتَلُ مِنْهُمْ مَنْ أَوْجَبَ قَتْلَهُ كُفْرًا، وَهُوَ مَذْهَبُ أَحْمَدَ وَإِسْحَاقَ وَابْنِ الْمُبَارَكِ، وَمِنْهُمْ مَنْ أَوْجَبَهُ حَدًّا وَهُوَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو حَنِيفَةَ، وَأَصْحَابُهُ، وَأَهْلُ الظَّاهِرِ مِمَّنْ رَأَى حَبْسَهُ وَتَعْزِيرَهُ حَتَّى يُصَلِّيَ","src":"بداية المجتهد","loc":"١/٩٧-٩٨","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وتارك الصلاة كافر كفرا أكبر يستحق به الخلود في النار كسائر الكفار","src":"فتاوى اللجنة الدائمة","loc":"١/٧٣١","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"إلى غير ذلك من الآيات والأحاديث الدالة على كفر تارك الصلاة","src":"مجموع فتاوى ابن باز","loc":"٥/٣٤٦","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله بعد أن ساق الأدلة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"ترك الصلاة من أعظم الذنوب وأخطرها، وقد سماه النبي ﷺ كفرًا وشركًا، وقال عبد الله بن شقيق: «كان أصحاب محمد ﷺ لا يرون شيئًا من الأعمال تركه كفر غير الصلاة» (رواه الترمذي ٢٦٢٢). فمن تركها بالكلية تركًا مستمرًا لا يصلي أبدًا فقوله خطير جدًّا، والقول بكفره قوي من جهة الأدلة. وأما من يصلي أحيانًا ويترك أحيانًا، أو يؤخرها عن وقتها، فهو فاسق مرتكب لكبيرة عظيمة عند جمهور العلماء، يجب نصحه وتذكيره بالله."},{"t":"p","text":"والمسألة من مسائل الاجتهاد بين الأئمة، فلا يُضلَّل فيها المخالف؛ لكن الواجب على كل مسلم أن يحافظ على الصلوات الخمس في أوقاتها، وأن يخاف على نفسه من هذا الوعيد الشديد، فإنه لا حظ في الإسلام لمن ترك الصلاة."},{"t":"tanbih","items":[{"t":"p","text":"الحكم بالكفر أو القتل من شأن القضاء والحاكم الشرعي بعد الاستتابة وإقامة الحجة، وليس لآحاد الناس أن يرتبوا على أقاربهم أحكامًا بأنفسهم، بل عليهم النصح والدعوة بالحكمة."}]}],"refs":["مسلم ٨٢","الترمذي ٢٦٢١، والنسائي ٤٦٣، وابن ماجه ١٠٧٩","بداية المجتهد (١/٩٧-٩٨)","فتاوى اللجنة الدائمة (١/٧٣١)","مجموع فتاوى ابن باز (٥/٣٤٦)","بداية المجتهد (١/٩٨)"],"related":["أوقات الصلوات الخمس"],"alts":["ترك الصلاة","تارك الصلاة كافر","من لا يصلي","التهاون بالصلاة"]},{"n":88,"bab":"الصلاة","sub":"مواقيت الصلاة","title":"وقت الظهر والعصر، والإبراد بالظهر","q":"متى يدخل وقت العصر: إذا صار ظل الشيء مثله أو مثليه؟ وهل الأفضل تعجيل الظهر أو تأخيرها؟","short":"يبدأ وقت الظهر بزوال الشمس بالإجماع، وينتهي إذا صار ظل كل شيء مثله سوى ظل الزوال عند الجمهور ومنهم أبو يوسف ومحمد، فيدخل وقت العصر؛ وجعله أبو حنيفة في المشهور عنه المثلين. ويمتد وقت العصر المختار إلى اصفرار الشمس، ووقت الضرورة إلى غروبها. والأفضل تعجيل الصلاة في أول وقتها إلا الظهر في شدة الحر فيُبرد بها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَمَّنِي جِبْرِيلُ عَلَيْهِ السَّلاَمُ عِنْدَ الْبَيْتِ مَرَّتَيْنِ فَصَلَّى الظُّهْرَ فِي الأُولَى مِنْهُمَا حِينَ كَانَ الْفَىْءُ مِثْلَ الشِّرَاكِ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ كُلُّ شَيْءٍ مِثْلَ ظِلِّهِ ثُمَّ صَلَّى الْمَغْرِبَ حِينَ وَجَبَتِ الشَّمْسُ وَأَفْطَرَ الصَّائِمُ ثُمَّ صَلَّى الْعِشَاءَ حِينَ غَابَ الشَّفَقُ ثُمَّ صَلَّى الْفَجْرَ حِينَ بَرَقَ الْفَجْرُ وَحَرُمَ الطَّعَامُ عَلَى الصَّائِمِ . وَصَلَّى الْمَرَّةَ الثَّانِيَةَ الظُّهْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ لِوَقْتِ الْعَصْرِ بِالأَمْسِ ثُمَّ صَلَّى الْعَصْرَ حِينَ كَانَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ ثُمَّ صَلَّى الْمَغْرِبَ لِوَقْتِهِ الأَوَّلِ ثُمَّ صَلَّى الْعِشَاءَ الآخِرَةَ حِينَ ذَهَبَ ثُلُثُ اللَّيْلِ ثُمَّ صَلَّى الصُّبْحَ حِينَ أَسْفَرَتِ الأَرْضُ ثُمَّ الْتَفَتَ إِلَىَّ جِبْرِيلُ فَقَالَ يَا مُحَمَّدُ هَذَا وَقْتُ الأَنْبِيَاءِ مِنْ قَبْلِكَ . وَالْوَقْتُ فِيمَا بَيْنَ هَذَيْنِ الْوَقْتَيْنِ","src":"رواه الترمذي ١٤٩، وأبو داود ٣٩٣","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":149,"id":"h149"},{"book":"mt_abudawud","num":393,"id":"h393"}]},{"t":"quote","text":"وَقْتُ الظُّهْرِ مَا لَمْ يَحْضُرِ الْعَصْرُ، وَوَقْتُ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ الْمَغْرِبِ مَا لَمْ يَسْقُطْ ثَوْرُ الشَّفَقِ، وَوَقْتُ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ، وَوَقْتُ الْفَجْرِ مَا لَمْ تَطْلُعِ الشَّمْسُ","src":"رواه مسلم ٦١٢","pre":"وعن عبد الله بن عمرو رضي الله عنهما أن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":612,"id":"h612-2"}]},{"t":"quote","text":"إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا عَنِ الصَّلاَةِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ","src":"رواه البخاري ٥٣٣","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":533,"id":"h533"}]},{"t":"h","text":"أقوال العلماء في آخر وقت الظهر وأول العصر"},{"t":"qawl","label":"القول الأول","text":"آخر وقت الظهر وأول وقت العصر إذا صار ظل كل شيء مثله، وهو قول مالك والشافعي وأحمد، وأبي يوسف ومحمد بن الحسن."},{"t":"qawl","label":"القول الثاني","text":"آخر وقت الظهر إذا صار ظل كل شيء مثليه، وهو أول وقت العصر، وهو قول أبي حنيفة في المشهور عنه."},{"t":"quote","text":"فَأَمَّا آخِرُ وَقْتِهَا الْمُوَسَّعِ، فَقَالَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو ثَوْرٍ وَدَاوُدُ هُوَ أَنْ يَكُونَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ وَقَالَ أَبُو حَنِيفَةَ: آخِرُ الْوَقْتِ أَنْ يَكُونَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ فِي إِحْدَى الرِّوَايَتَيْنِ عَنْهُ، وَهُوَ عِنْدَهُ أَوَّلُ وَقْتِ الْعَصْرِ.","src":"بداية المجتهد","loc":"١/١٠٠","pre":"قال ابن رشد:"},{"t":"quote","text":"وَأَوَّلُ وَقْتِ الظُّهْرِ إذَا زَالَتْ الشَّمْسُ لِإِمَامَةِ جِبْرِيلَ - عَلَيْهِ السَّلَامُ - فِي الْيَوْمِ الْأَوَّلِ حِينَ زَالَتْ الشَّمْسُ وَآخِرُ وَقْتِهَا عِنْدَ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ - إذَا صَارَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ سِوَى فَيْءِ الزَّوَالِ وَقَالَا: إذَا صَارَ الظِّلُّ مِثْلَهُ وَهُوَ رِوَايَةٌ عَنْ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ -","src":"الهداية مع فتح القدير","loc":"١/٢١٩","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن وقت الظهر من زوال الشمس إلى أن يصير ظل كل شيء مثله بعد ظل الزوال، ثم يدخل وقت العصر؛ لحديث إمامة جبريل الصريح في أنه صلى العصر في اليوم الأول حين صار ظل الشيء مثله، ولحديث عبد الله بن عمرو: «وقت الظهر ما لم يحضر العصر»؛ وهو قول صاحبي أبي حنيفة. ويمتد وقت العصر المختار إلى اصفرار الشمس، ويكره تأخيرها إليه بلا عذر، ومن صلاها قبل الغروب أداها في وقت الضرورة."},{"t":"p","text":"ومن صلى العصر عند المثلين احتياطًا لمذهبه فصلاته صحيحة بالاتفاق، لأنه وقت العصر عند الجميع، وإنما الخلاف فيمن صلاها عند المثل."},{"t":"tanbih","items":[{"t":"p","text":"السنة تعجيل الصلوات في أول أوقاتها؛ لقوله ﷺ لما سئل: أي العمل أحب إلى الله؟ قال: «الصلاة على وقتها» (رواه البخاري ٥٢٧)، إلا الظهر في شدة الحر، والعشاء إذا لم يشق على الناس."}]}],"refs":["الترمذي ١٤٩، وأبو داود ٣٩٣","مسلم ٦١٢","البخاري ٥٣٣","بداية المجتهد (١/١٠٠)","الهداية مع فتح القدير (١/٢١٩)","بداية المجتهد (١/١٠٠-١٠١)","بداية المجتهد (١/١٠٢)"],"related":["وقت المغرب والعشاء","التغليس والإسفار بصلاة الفجر"],"alts":["المثل والمثلين","أول وقت العصر","الإبراد بالظهر","آخر وقت العصر"]},{"n":89,"bab":"الصلاة","sub":"مواقيت الصلاة","title":"وقت المغرب والعشاء","q":"هل لصلاة المغرب وقت واحد أم وقت موسع؟ ومتى يدخل وقت العشاء ومتى ينتهي؟","short":"يدخل وقت المغرب بغروب الشمس بالإجماع، ويمتد إلى مغيب الشفق عند أبي حنيفة وأحمد، وهو قول للشافعي ومالك، والمشهور عنهما أن وقتها واحد مضيق. ويدخل وقت العشاء بمغيب الشفق الأحمر عند الجمهور، والأبيض عند أبي حنيفة، ويمتد وقتها المختار إلى ثلث الليل أو نصفه، ووقت الضرورة إلى طلوع الفجر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَقْتُ الظُّهْرِ مَا لَمْ يَحْضُرِ الْعَصْرُ، وَوَقْتُ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ، وَوَقْتُ الْمَغْرِبِ مَا لَمْ يَسْقُطْ ثَوْرُ الشَّفَقِ، وَوَقْتُ الْعِشَاءِ إِلَى نِصْفِ اللَّيْلِ، وَوَقْتُ الْفَجْرِ مَا لَمْ تَطْلُعِ الشَّمْسُ","src":"رواه مسلم ٦١٢","pre":"عن عبد الله بن عمرو رضي الله عنهما أن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":612,"id":"h612-2"}]},{"t":"quote","text":"لَوْلاَ أَنْ أَشُقَّ عَلَى أُمَّتِي لأَمَرْتُهُمْ أَنْ يُؤَخِّرُوا الْعِشَاءَ إِلَى ثُلُثِ اللَّيْلِ أَوْ نِصْفِهِ","src":"رواه الترمذي ١٦٧","pre":"وعن أبي هريرة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":167,"id":"h167"}]},{"t":"h","text":"وقت المغرب"},{"t":"quote","text":"اخْتَلَفُوا فِي الْمَغْرِبِ هَلْ لَهَا وَقْتٌ مُوَسَّعٌ كَسَائِرِ الصَّلَوَاتِ أَمْ لَا؟ فَذَهَبَ قَوْمٌ إِلَى أَنَّ وَقْتَهَا وَاحِدٌ غَيْرُ مُوَسَّعٍ، وَهَذَا هُوَ أَشْهَرُ الرِّوَايَاتِ عَنْ مَالِكٍ وَعَنِ الشَّافِعِيِّ. وَذَهَبَ قَوْمٌ إِلَى أَنَّ وَقْتَهَا مُوَسَّعٌ، وَهُوَ مَا بَيْنَ غُرُوبِ الشَّمْسِ إِلَى غُرُوبِ الشَّفَقِ، وَبِهِ قَالَ أَبُو حَنِيفَةَ، وَأَحْمَدُ، وَأَبُو ثَوْرٍ، وَدَاوُدُ، وَقَدْ رُوِيَ هَذَا الْقَوْلُ عَنْ مَالِكٍ وَالشَّافِعِيِّ","src":"بداية المجتهد","loc":"١/١٠٣","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن وقت المغرب يمتد من غروب الشمس إلى مغيب الشفق الأحمر؛ لحديث عبد الله بن عمرو وبريدة في صحيح مسلم، وهما متأخران بالمدينة، وحديث جبريل كان بمكة أول الفرض؛ لكن السنة تعجيلها. ويدخل وقت العشاء بمغيب الشفق الأحمر، وهو قول الجمهور وصاحبي أبي حنيفة؛ لأن الشفق في لغة العرب الحمرة غالبًا، ومن أخّر إلى مغيب البياض احتياطًا فلا حرج. ووقت العشاء المختار إلى نصف الليل، ويستحب تأخيرها إلى ثلث الليل إن لم يشق على الناس، ولا يؤخرها بعد نصف الليل إلا لعذر، فإن فعل صلاها أداءً قبل الفجر."},{"t":"tanbih","items":[{"t":"p","text":"في البلاد التي لا يغيب فيها الشفق في بعض فصول السنة، أو يتأخر غيابه جدًّا، يُقدَّر وقت العشاء بأقرب البلاد إليها التي تتميز فيها الأوقات، أو بقرار الهيئات الشرعية المعتمدة هناك."}]}],"refs":["مسلم ٦١٢","الترمذي ١٦٧","بداية المجتهد (١/١٠٣)","بداية المجتهد (١/١٠٣-١٠٤)"],"related":["وقت الظهر والعصر، والإبراد بالظهر"],"alts":["الشفق الأحمر","آخر وقت العشاء","وقت المغرب مضيق","تأخير العشاء"]},{"n":90,"bab":"الصلاة","sub":"مواقيت الصلاة","title":"التغليس والإسفار بصلاة الفجر","q":"أيهما أفضل: صلاة الفجر في أول الوقت في الظلمة، أم تأخيرها إلى الإسفار؟","short":"يدخل وقت الفجر بطلوع الفجر الصادق وينتهي بطلوع الشمس بالإجماع. واختلفوا في الأفضل: فالتغليس (الصلاة في أول الوقت مع بقاء الظلمة) أفضل عند مالك والشافعي وأحمد، والإسفار أفضل عند أبي حنيفة وأبي يوسف والثوري، واختار محمد بن الحسن والطحاوي أن يبدأ في الغلس وينتهي في الإسفار بإطالة القراءة. والأمر في ذلك واسع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنَّ نِسَاءُ الْمُؤْمِنَاتِ يَشْهَدْنَ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم صَلاَةَ الْفَجْرِ مُتَلَفِّعَاتٍ بِمُرُوطِهِنَّ، ثُمَّ يَنْقَلِبْنَ إِلَى بُيُوتِهِنَّ حِينَ يَقْضِينَ الصَّلاَةَ، لاَ يَعْرِفُهُنَّ أَحَدٌ مِنَ الْغَلَسِ","src":"رواه البخاري ٥٧٨، ومسلم ٦٤٥","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":578,"id":"h578"},{"book":"mt_muslim","num":645,"id":"h645"}]},{"t":"quote","text":"أَسْفِرُوا بِالْفَجْرِ فَإِنَّهُ أَعْظَمُ لِلأَجْرِ","src":"رواه الترمذي ١٥٤","pre":"وعن رافع بن خديج رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_tirmidhi","num":154,"id":"h154"}]},{"t":"p","text":"قال الترمذي: حديث رافع بن خديج حديث حسن صحيح."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي وَقْتِهَا الْمُخْتَارِ، فَذَهَبَ الْكُوفِيُّونَ، وَأَبُو حَنِيفَةَ، وَأَصْحَابُهُ، وَالثَّوْرِيُّ، وَأَكْثَرُ الْعِرَاقِيِّينَ إِلَى أَنَّ الْإِسْفَارَ بِهَا أَفْضَلُ، وَذَهَبَ مَالِكٌ، وَالشَّافِعِيُّ، وَأَصْحَابُهُ، وَأَحْمَدُ بْنُ حَنْبَلٍ، وَأَبُو ثَوْرٍ، وَدَاوُدُ إِلَى أَنَّ التَّغْلِيسَ بِهَا أَفْضَلُ","src":"بداية المجتهد","loc":"١/١٠٥","pre":"قال ابن رشد:"},{"t":"quote","text":"مذهب الشافعي ومالك وأحمد: استحباب التغليس بداية ونهاية، ومذهب أبي حنيفة وأبي يوسف وسفيان الثوري: أفضلية الإسفار بداية ونهاية، ومذهب محمد واختاره الطحاوي: البداية في الغلس والنهاية في الإسفار","src":"العرف الشذي","loc":"١/١٧٤","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وَأَمَّا) بَيَانُ الْأَوْقَاتِ الْمُسْتَحَبَّةِ فَالسَّمَاءُ لَا تَخْلُو إمَّا أَنْ كَانَتْ مُصْحِيَةً أَوْ مُغَيِّمَةً فَإِنْ كَانَتْ مُصْحِيَةً فَفِي الْفَجْرِ الْمُسْتَحَبُّ آخِرُ الْوَقْتِ، وَالْأَسْفَارُ بِصَلَاةِ الْفَجْرِ أَفْضَلُ","src":"بدائع الصنائع","loc":"١/١٢٤","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأفضل الغالب من فعله ﷺ أن يصلي الفجر بغلس بعد تحقق طلوع الفجر، ويطيل فيها القراءة؛ لحديث عائشة في الصحيحين، وهو عمله المستمر وعمل خلفائه. وحديث رافع «أسفروا بالفجر» صحيح، ويُحمل على تحقق طلوع الفجر وتبيّنه، أو على إطالة القراءة حتى يخرج منها مسفرًا؛ وبهذا يجتمع الحديثان، وهو قريب مما اختاره محمد بن الحسن والطحاوي من الحنفية. ولا ينبغي التشديد في هذه المسألة، فكلا الأمرين في الوقت بالإجماع."},{"t":"tanbih","items":[{"t":"p","text":"الفجر الكاذب: بياض مستطيل يظهر في السماء ثم تعقبه ظلمة، ولا تحل به الصلاة ولا يحرم به الطعام على الصائم؛ والصادق: بياض معترض في الأفق يزداد انتشارًا حتى تطلع الشمس."}]}],"refs":["البخاري ٥٧٨، ومسلم ٦٤٥","الترمذي ١٥٤","بداية المجتهد (١/١٠٥)","العرف الشذي (١/١٧٤)","بدائع الصنائع (١/١٢٤)"],"related":["وقت الظهر والعصر، والإبراد بالظهر"],"alts":["التغليس","الإسفار بالفجر","أول وقت الفجر","الفجر الصادق"]},{"n":91,"bab":"الصلاة","sub":"مواقيت الصلاة","title":"من أدرك ركعة من الوقت، وصلاة أصحاب الأعذار إذا زال عذرهم في آخر الوقت","q":"طهرت الحائض قبيل غروب الشمس، أو أسلم الكافر أو بلغ الصبي في آخر الوقت، فما الذي يلزمهم من الصلوات؟","short":"من أدرك ركعة من الصلاة قبل خروج وقتها فقد أدركها أداءً بالاتفاق. ومن زال عذره (كالحائض تطهر، والصبي يبلغ، والكافر يسلم) قبل خروج الوقت بقدر ركعة لزمته تلك الصلاة؛ ويلزمه معها التي قبلها إن كانت تجمع إليها (الظهر مع العصر، والمغرب مع العشاء) عند مالك والشافعي وأحمد، ولا يلزمه عند أبي حنيفة إلا صلاة الوقت.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ أَدْرَكَ مِنَ الصُّبْحِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ، وَمَنْ أَدْرَكَ رَكْعَةً مِنَ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ","src":"رواه البخاري ٥٧٩، ومسلم ٦٠٨","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":579,"id":"h579"},{"book":"mt_muslim","num":608,"id":"h608"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اتَّفَقَ مَالِكٌ، وَالشَّافِعِيُّ عَلَى أَنَّ هَذَا الْوَقْتَ هُوَ لِأَرْبَعِ صَلَوَاتٍ: لِلظُّهْرِ، وَالْعَصْرِ مُشْتَرَكًا بَيْنَهُمَا، وَالْمَغْرِبُ وَالْعِشَاءُ كَذَلِكَ، وَإِنَّمَا اخْتَلَفُوا فِي جِهَةِ اشْتِرَاكِهِمَا عَلَى مَا سَيَأْتِي بَعْدُ، وَخَالَفَهُمْ أَبُو حَنِيفَةَ فَقَالَ: إِنَّ هَذَا الْوَقْتَ إِنَّمَا هُوَ لِلْعَصْرِ فَقَطْ، وَإِنَّهُ لَيْسَ هَاهُنَا وَقْتٌ مُشْتَرَكٌ","src":"بداية المجتهد","loc":"١/١٠٦","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من أدرك من آخر الوقت قدر ركعة كاملة وهو من أهل الوجوب لزمته صلاة ذلك الوقت؛ لحديث أبي هريرة. وأما الصلاة التي قبلها فالأحوط أن يصليها معها إذا كانت مما يُجمع إليها، فإذا طهرت الحائض قبل غروب الشمس صلت الظهر والعصر، وإذا طهرت قبل الفجر صلت المغرب والعشاء؛ لأن وقت الثانية وقت للأولى في حال العذر، وهو مروي عن عبد الرحمن بن عوف وابن عباس رضي الله عنهم، وقول جمهور العلماء."},{"t":"tanbih","items":[{"t":"p","text":"وإن طرأ العذر بعد دخول الوقت، كأن حاضت المرأة بعد الزوال ولم تكن صلت الظهر، فالأحوط أن تقضي تلك الصلاة إذا طهرت إن كان قد مضى من الوقت ما يتسع لها، وهو قول الشافعي وأحمد."}]}],"refs":["البخاري ٥٧٩، ومسلم ٦٠٨","بداية المجتهد (١/١٠٦)","بداية المجتهد (١/١٠٧)"],"related":["وقت الظهر والعصر، والإبراد بالظهر","ما يحرم على الحائض، وهل تقضي الصلاة والصوم؟"],"alts":["إدراك ركعة قبل خروج الوقت","الحائض تطهر قبل المغرب","صلاة من أسلم آخر الوقت"]},{"n":92,"bab":"الصلاة","sub":"مواقيت الصلاة","title":"الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب","q":"هل يجوز أن أصلي تحية المسجد أو سنة الوضوء أو أقضي فائتة بعد العصر أو بعد الفجر؟","short":"اتفق العلماء على النهي عن الصلاة عند طلوع الشمس وعند غروبها وبعد صلاة الصبح، واختلفوا في وقت الزوال وبعد العصر. ويجوز قضاء الفرائض الفائتة في أوقات النهي عند مالك والشافعي وأحمد، ومنعه أبو حنيفة إلا عصر يومه. وأما ذوات الأسباب كتحية المسجد وصلاة الجنازة وسنة الوضوء فيجيزها الشافعي ورواية عن أحمد، ويمنعها أبو حنيفة ومالك. والأظهر جواز ذوات الأسباب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ صَلاَةَ بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ، وَلاَ صَلاَةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ","src":"رواه البخاري ٥٨٦","pre":"عن أبي سعيد الخدري رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_bukhari","num":586,"id":"h586"}]},{"t":"quote","text":"ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ، أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا: «حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ، وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ حَتَّى تَغْرُبَ»","src":"رواه مسلم ٨٣١","pre":"وعن عقبة بن عامر رضي الله عنه قال:","links":[{"book":"mt_muslim","num":831,"id":"h831"}]},{"t":"quote","text":"مَنْ نَسِيَ صَلاَةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لاَ كَفَّارَةَ لَهَا إِلاَّ ذَلِكَ","src":"رواه البخاري ٥٩٧","pre":"وعن أنس رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":597,"id":"h597"}]},{"t":"quote","text":"شَغَلُونِي عَنِ الرَّكْعَتَيْنِ اللَّتَيْنِ بَعْدَ الظُّهْرِ فَهُمَا هَاتَانِ","src":"رواه البخاري ١٢٣٣","pre":"وفي حديث أم سلمة رضي الله عنها لما صلى النبي ﷺ ركعتين بعد العصر قال:","links":[{"book":"mt_bukhari","num":1233,"id":"h1233"}]},{"t":"h","text":"عدد أوقات النهي"},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ ثَلَاثَةً مِنَ الْأَوْقَاتِ مَنْهِيٌّ عَنِ الصَّلَاةِ فِيهَا وَهِيَ: وَقْتُ طُلُوعِ الشَّمْسِ، وَوَقْتُ غُرُوبِهَا، وَمِنْ لَدُنْ تُصَلَّى صَلَاةُ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ.","src":"بداية المجتهد","loc":"١/١٠٨-١٠٩","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا يجوز للمسلم أن يصلي قبل الظهر في وقت وقوف الشمس؛ لأنه من أوقات النهي","src":"مجموع فتاوى ابن باز","loc":"١١/٢٨٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"عند وقوف الشمس هذا وقت نهي لا يصلى فيه الصلاة العادية إلا ذوات الأسباب","src":"فتاوى نور على الدرب لابن باز","loc":"١٠/٣٠٦","pre":"وقال:"},{"t":"quote","text":"قراءة القرآن تجوز في أوقات النهي المذكورة في السؤال؛ لعدم النهي عنها","src":"فتاوى اللجنة الدائمة","loc":"٤/١٤٦","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن النهي في هذه الأوقات خاص بالنوافل المطلقة التي لا سبب لها؛ وأما الفرائض الفائتة فتُقضى في أي وقت؛ لقوله ﷺ: «من نسي صلاة فليصل إذا ذكرها». وكذلك ذوات الأسباب كتحية المسجد، وصلاة الجنازة، وسجود التلاوة، وركعتي الطواف، وصلاة الكسوف، وسنة الوضوء؛ لأن النبي ﷺ قضى سنة الظهر بعد العصر، ولعموم أحاديث الأسباب؛ وهو مذهب الشافعي واختيار ابن تيمية. ومن احتاط فترك ذوات الأسباب في الأوقات الثلاثة المضيقة (عند الطلوع والزوال والغروب) خروجًا من الخلاف فقد أحسن."},{"t":"tanbih","items":[{"t":"p","text":"أوقات النهي خمسة على التفصيل: من بعد صلاة الفجر حتى تطلع الشمس، ومن طلوعها حتى ترتفع قدر رمح (نحو ربع ساعة)، وعند قيامها في وسط السماء حتى تزول (دقائق قبل الظهر)، ومن بعد صلاة العصر حتى تصفر، ومن اصفرارها حتى تغرب."}]}],"refs":["البخاري ٥٨٦","مسلم ٨٣١","البخاري ٥٩٧","البخاري ١٢٣٣","بداية المجتهد (١/١٠٨-١٠٩)","بداية المجتهد (١/١١٠)","مجموع فتاوى ابن باز (١١/٢٨٥)","فتاوى نور على الدرب لابن باز (١٠/٣٠٦)","فتاوى اللجنة الدائمة (٤/١٤٦)","بداية المجتهد (١/١١١)"],"related":["من أدرك ركعة من الوقت، وصلاة أصحاب الأعذار إذا زال عذرهم في آخر الوقت"],"alts":["الصلاة بعد العصر","تحية المسجد وقت النهي","قضاء الفائتة بعد الفجر","أوقات الكراهة"]},{"n":93,"bab":"الصلاة","sub":"الأذان والإقامة","title":"صفة الأذان: التكبير في أوله، والترجيع، و«الصلاة خير من النوم»","q":"هل يكبّر المؤذن في أول الأذان أربعًا أم مرتين؟ وما الترجيع؟ وهل «الصلاة خير من النوم» سنة؟","short":"وردت في الأذان صفات صحيحة: أذان بلال الذي رآه عبد الله بن زيد بتربيع التكبير في أوله بلا ترجيع، وهو قول أبي حنيفة وأحمد؛ وأذان أبي محذورة بالترجيع (أن يقول الشهادتين خفيًّا ثم يرفع بهما صوته)، وهو قول الشافعي، وبتثنية التكبير في أوله مع الترجيع عند مالك. والأظهر أن هذه الصفات كلها سنة، يجوز الأخذ بأيها. ويقال في أذان الفجر: «الصلاة خير من النوم» مرتين عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَمَّا أَصْبَحْنَا أَتَيْنَا رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ بِالرُّؤْيَا فَقَالَ «إِنَّ هَذِهِ لَرُؤْيَا حَقٍّ فَقُمْ مَعَ بِلاَلٍ فَإِنَّهُ أَنْدَى وَأَمَدُّ صَوْتًا مِنْكَ فَأَلْقِ عَلَيْهِ مَا قِيلَ لَكَ وَلْيُنَادِ بِذَلِكَ» . قَالَ فَلَمَّا سَمِعَ عُمَرُ بْنُ الْخَطَّابِ نِدَاءَ بِلاَلٍ بِالصَّلاَةِ خَرَجَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ يَجُرُّ إِزَارَهُ وَهُوَ يَقُولُ يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ رَأَيْتُ مِثْلَ الَّذِي قَالَ . قَالَ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «فَلِلَّهِ الْحَمْدُ فَذَلِكَ أَثْبَتُ»","src":"رواه الترمذي ١٨٩","pre":"عن عبد الله بن زيد رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":189,"id":"h189"}]},{"t":"quote","text":"قُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي سُنَّةَ الأَذَانِ . قَالَ فَمَسَحَ مُقَدَّمَ رَأْسِي وَقَالَ «تَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ تَرْفَعُ بِهَا صَوْتَكَ ثُمَّ تَقُولُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ تَخْفِضُ بِهَا صَوْتَكَ ثُمَّ تَرْفَعُ صَوْتَكَ بِالشَّهَادَةِ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَىَّ عَلَى الصَّلاَةِ حَىَّ عَلَى الصَّلاَةِ حَىَّ عَلَى الْفَلاَحِ حَىَّ عَلَى الْفَلاَحِ فَإِنْ كَانَ صَلاَةَ الصُّبْحِ قُلْتَ الصَّلاَةُ خَيْرٌ مِنَ النَّوْمِ الصَّلاَةُ خَيْرٌ مِنَ النَّوْمِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لاَ إِلَهَ إِلاَّ اللَّهُ»","src":"رواه أبو داود ٥٠٠","pre":"وعن أبي محذورة رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":500,"id":"h500"}]},{"t":"quote","text":"عَلَّمَهُ هَذَا الْأَذَانَ: «اللهُ أَكْبَرُ اللهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ»، ثُمَّ يَعُودُ فَيَقُولُ: «أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، حَيَّ عَلَى الصَّلَاةِ مَرَّتَيْنِ، حَيَّ عَلَى الْفَلَاحِ مَرَّتَيْنِ»","src":"رواه مسلم ٣٧٩","pre":"وعنه رضي الله عنه أن نبي الله ﷺ:","links":[{"book":"mt_muslim","num":379,"id":"h379"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي الْأَذَانِ عَلَى أَرْبَعِ صِفَاتٍ مَشْهُورَةٍ: إِحْدَاهَا: تَثْنِيَةُ التَّكْبِيرِ فِيهِ وَتَرْبِيعُ الشَّهَادَتَيْنِ وَبَاقِيهِ مُثَنًّى، وَهُوَ مَذْهَبُ أَهْلِ الْمَدِينَةِ مَالِكٍ وَغَيْرِهِ، وَاخْتَارَ الْمُتَأَخِّرُونَ مِنْ أَصْحَابِ مَالِكٍ التَّرْجِيعَ، وَهُوَ أَنْ يُثَنِّيَ الشَّهَادَتَيْنِ أَوَّلًا خَفِيًّا، ثُمَّ يُثَنِّيَهُمَا مَرَّةً ثَانِيَةً مَرْفُوعَ الصَّوْتِ.","src":"بداية المجتهد","loc":"١/١١٢-١١٣","pre":"قال ابن رشد:"},{"t":"quote","text":"وَلَا تَرْجِيعَ فِيهِ وَهُوَ أَنْ يَرْجِعَ فَيَرْفَعَ صَوْتَهُ بِالشَّهَادَتَيْنِ بَعْدَ مَا خَفَضَ بِهِمَا. وَقَالَ الشَّافِعِيُّ - رَحِمَهُ اللَّهُ -: فِيهِ ذَلِكَ لِحَدِيثِ أَبِي مَحْذُورَةَ - رَضِيَ اللَّهُ عَنْهُ - «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَمَرَ بِالتَّرْجِيعِ» . وَلَنَا أَنَّهُ لَا تَرْجِيعَ فِي الْمَشَاهِيرِ وَكَانَ مَا رَوَاهُ تَعْلِيمًا فَظَنَّهُ تَرْجِيعًا","src":"الهداية مع فتح القدير","loc":"١/٢٤١","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر ما ذهب إليه أحمد بن حنبل وداود: أن هذه الصفات كلها ثابتة عن النبي ﷺ، فهي من اختلاف التنوع لا التضاد، والأذان بأيها صحيح؛ والأولى أن يؤذن المؤذن بما اعتاده أهل بلده حتى لا يشوش عليهم، ولا يُنكر على من أذن بغيره. وأما «الصلاة خير من النوم» فثابتة في حديث أبي محذورة في الأذان الأول للفجر، فيقولها المؤذن مرتين بعد «حي على الفلاح»."},{"t":"tanbih","items":[{"t":"p","text":"ألفاظ الأذان توقيفية، فلا يُزاد فيها ما لم يرد، كالجهر بالصلاة على النبي ﷺ متصلة بالأذان، أو زيادة ألفاظ أخرى؛ والسنة أن يصلي المؤذن والسامع على النبي ﷺ بعد الأذان سرًّا."}]}],"refs":["الترمذي ١٨٩","أبو داود ٥٠٠","مسلم ٣٧٩","بداية المجتهد (١/١١٢-١١٣)","الهداية مع فتح القدير (١/٢٤١)","بداية المجتهد (١/١١٣-١١٤)","بداية المجتهد (١/١١٤)"],"related":["صفة الإقامة: إفرادها وتثنيتها","ما يقوله سامع الأذان، والدعاء بعده"],"alts":["الترجيع في الأذان","عدد التكبير في الأذان","التثويب","ألفاظ الأذان"]},{"n":94,"bab":"الصلاة","sub":"الأذان والإقامة","title":"صفة الإقامة: إفرادها وتثنيتها","q":"هل تُقال الإقامة مثل الأذان مثنى مثنى، أم مفردة؟","short":"الإقامة عند مالك والشافعي وأحمد مفردة إلا التكبير و«قد قامت الصلاة» فمثنى (ويفرد مالك «قد قامت الصلاة»)، وعند أبي حنيفة مثنى مثنى كالأذان مع زيادة «قد قامت الصلاة». وخيّر أحمد بين الإفراد والتثنية. والأظهر أن الكل جائز، والإفراد هو الذي استقر عليه أذان بلال.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أُمِرَ بِلاَلٌ أَنْ يَشْفَعَ، الأَذَانَ وَأَنْ يُوتِرَ الإِقَامَةَ إِلاَّ الإِقَامَةَ","src":"رواه البخاري ٦٠٥، ومسلم ٣٧٨","pre":"عن أنس رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":605,"id":"h605"},{"book":"mt_muslim","num":378,"id":"h378"}]},{"t":"p","text":"ومعنى «إلا الإقامة»: إلا قوله «قد قامت الصلاة» فإنه يثنيها."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا صِفَةُ الْإِقَامَةِ: فَإِنَّهَا عِنْدَ مَالِكٍ وَالشَّافِعِيِّ أَمَّا التَّكْبِيرُ الَّذِي فِي أَوَّلِهَا فَمَثْنَى، وَأَمَّا مَا بَعْدَ ذَلِكَ فَمَرَّةً وَاحِدَةً إِلَّا قَوْلَهُ: قَدْ قَامَتِ الصَّلَاةُ، فَإِنَّهَا عِنْدَ مَالِكٍ مَرَّةً وَاحِدَةً، وَعِنْدَ الشَّافِعِيِّ مَرَّتَيْنِ. وَأَمَّا الْحَنَفِيَّةُ فَإِنَّ الْإِقَامَةَ عِنْدَهُمْ مَثْنَى مَثْنَى، وَخَيَّرَ أَحْمَدُ بْنُ حَنْبَلٍ بَيْنَ الْإِفْرَادِ وَالتَّثْنِيَةِ عَلَى رَأْيِهِ فِي التَّخْيِيرِ فِي النِّدَاءِ","src":"بداية المجتهد","loc":"١/١١٨","pre":"قال ابن رشد:"},{"t":"quote","text":"وَالْإِقَامَةُ مِثْلُ الْأَذَانِ إلَّا أَنَّهُ يَزِيدُ فِيهَا بَعْدَ الْفَلَاحِ قَدْ قَامَتْ الصَّلَاةُ مَرَّتَيْنِ هَكَذَا فَعَلَ الْمَلَكُ النَّازِلُ مِنْ السَّمَاءِ وَهُوَ الْمَشْهُورُ","src":"الهداية مع فتح القدير","loc":"١/٢٤٣","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الإقامة مفردة إلا التكبير و«قد قامت الصلاة»؛ لحديث أنس في الصحيحين، وهو آخر الأمرين من أذان بلال بالمدينة. وتثنية الإقامة ثابتة أيضًا في حديث أبي محذورة الذي علّمه النبي ﷺ، فمن أقام مثنى كما هو مذهب الحنفية فقد أقام بسنة ثابتة، ولا ينكر بعضهم على بعض."},{"t":"tanbih","items":[{"t":"p","text":"السنة أن تكون الإقامة أسرع من الأذان (الحدر)، وأن يقيم من أذّن إن تيسر، ويجوز أن يقيم غيره عند أكثر الفقهاء."}]}],"refs":["البخاري ٦٠٥، ومسلم ٣٧٨","بداية المجتهد (١/١١٨)","الهداية مع فتح القدير (١/٢٤٣)"],"related":["صفة الأذان: التكبير في أوله، والترجيع، و«الصلاة خير من النوم»"],"alts":["إفراد الإقامة","تثنية الإقامة","ألفاظ الإقامة"]},{"n":95,"bab":"الصلاة","sub":"الأذان والإقامة","title":"حكم الأذان والإقامة، وأذان المنفرد والمرأة","q":"هل الأذان واجب أم سنة؟ وهل يؤذن من يصلي وحده في بيته أو في البرية؟ وهل على النساء أذان؟","short":"الأذان والإقامة سنتان مؤكدتان عند أبي حنيفة والشافعي ومالك في رواية، وفرض كفاية على أهل البلد عند أحمد وبعض أصحاب مالك. ويُسنّ الأذان والإقامة للمنفرد ولو في البرية، والإقامة آكد. وليس على النساء أذان ولا إقامة عند الجمهور، وإن أقمن فحسن.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا حَضَرَتِ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ، ثُمَّ لِيَؤُمَّكُمْ أَكْبَرُكُمْ","src":"رواه مسلم ٦٧٤","pre":"عن مالك بن الحويرث رضي الله عنه أن النبي ﷺ قال له ولصاحبه:","links":[{"book":"mt_muslim","num":674,"id":"h674"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي حُكْمِ الْأَذَانِ: هَلْ هُوَ وَاجِبٌ أَوْ سُنَّةٌ مُؤَكَّدَةٌ؟ وَإِنْ كَانَ وَاجِبًا، فَهَلْ هُوَ مِنْ فُرُوضِ الْأَعْيَانِ أَوْ مِنْ فُرُوضِ الْكِفَايَةِ؟ فَقِيلَ عَنْ مَالِكٍ: إِنَّ الْأَذَانَ هُوَ فَرْضٌ عَلَى مَسَاجِدِ الْجَمَاعَاتِ، وَقِيلَ: سُنَّةٌ مُؤَكَّدَةٌ، وَلَمْ يَرَهُ عَلَى الْمُنْفَرِدِ لَا فَرْضًا وَلَا سُنَّةً.","src":"بداية المجتهد","loc":"١/١١٤","pre":"قال ابن رشد:"},{"t":"quote","text":"الْأَذَانُ سُنَّةٌ لِلصَّلَوَاتِ الْخَمْسِ وَالْجُمُعَةِ دُونَ مَا سِوَاهَا لِلنَّقْلِ الْمُتَوَاتِرِ","src":"الهداية مع فتح القدير","loc":"١/٢٤٠","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأذان والإقامة فرض كفاية على أهل كل بلد وحي، يقاتَل أهل البلد على تركهما؛ لأمره ﷺ بهما، ولأنهما من شعائر الإسلام الظاهرة، وكان ﷺ يستدل بالأذان على إسلام أهل البلد. وأما في حق المنفرد ومن فاتته الجماعة فسنة مؤكدة، يؤذن ويقيم ولو كان وحده في البرية، فإن اكتفى بأذان البلد أو بالإقامة أجزأه، وصلاته صحيحة بالاتفاق."},{"t":"p","text":"وليس على المرأة أذان، وإن صلت النساء جماعة فأقامت إحداهن فحسن، بلا رفع صوت يُسمع الرجال."}],"refs":["مسلم ٦٧٤","بداية المجتهد (١/١١٤)","الهداية مع فتح القدير (١/٢٤٠)","بداية المجتهد (١/١١٤-١١٥)","بداية المجتهد (١/١١٧)","بداية المجتهد (١/١١٨)"],"related":["الأذان قبل دخول الوقت، والأذان الأول للفجر"],"alts":["هل الأذان واجب","الأذان للمنفرد","أذان المرأة","الصلاة بدون إقامة"]},{"n":96,"bab":"الصلاة","sub":"الأذان والإقامة","title":"الأذان قبل دخول الوقت، والأذان الأول للفجر","q":"هل يجوز الأذان قبل دخول الوقت؟ وما حكم الأذان الأول قبل الفجر؟","short":"اتفق العلماء على أنه لا يؤذن لصلاة قبل وقتها إلا الفجر، فإن مالكًا والشافعي وأحمد أجازوا الأذان لها قبل طلوع الفجر، ومنعه أبو حنيفة والثوري. والسنة أن يكون للفجر أذانان: أذان قبل الفجر للتنبيه، وأذان بعد طلوعه للصلاة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ بِلاَلاً يُؤَذِّنُ بِلَيْلٍ، فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ابْنُ أُمِّ مَكْتُومٍ «. ثُمَّ قَالَ وَكَانَ رَجُلاً أَعْمَى لاَ يُنَادِي حَتَّى يُقَالَ لَهُ أَصْبَحْتَ أَصْبَحْتَ»","src":"رواه البخاري ٦١٧","pre":"عن ابن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":617,"id":"h617"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اتفق العلماء على أنه لا يؤذَّن لصلاة قبل دخول وقتها، إلا الفجر؛ فقد اختلفوا فيها:"},{"t":"qawl","label":"القول الأول","text":"يجوز الأذان للفجر قبل طلوعه، وهو قول مالك والشافعي وأحمد، لحديث: «إن بلالًا يؤذن بليل»."},{"t":"qawl","label":"القول الثاني","text":"لا يجوز الأذان للفجر قبل وقته، فإن أُذّن قبله أُعيد بعد طلوع الفجر، وهو قول أبي حنيفة ومحمد بن الحسن والثوري."},{"t":"qawl","label":"القول الثالث","text":"يجوز الأذان قبل الفجر بشرط أن يُؤذَّن له أيضًا بعد طلوعه، وهو قول بعض أهل العلم، واختاره ابن حزم."},{"t":"quote","text":"قَوْلُهُ: خِلَافًا لِلثَّانِي هَذَا رَاجِعٌ إلَى الْأَذَانِ فَقَطْ، فَإِنَّ أَبَا يُوسُفَ يُجَوِّزُ الْأَذَانَ قَبْلَ الْفَجْرِ بَعْدَ نِصْفِ اللَّيْلِ","src":"الدر المختار مع رد المحتار","loc":"١/٣٨٥","pre":"وقال ابن عابدين الحنفي في «رد المحتار»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الصلوات الخمس يؤذن لها بعد دخول وقتها، إلا الفجر، فيجوز تقديم الأذان قبل الوقت ليتمكن الناس من أداء الصلاة جماعة وعليه أن يعيده بعد دخول الوقت","src":"فتاوى اللجنة الدائمة","loc":"٦/٨٢","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأذان قبل الفجر مشروع، لكنه لا يكفي عن الأذان بعد طلوع الفجر الصادق؛ لأن النبي ﷺ جعل لصلاة الفجر مؤذنين: بلالًا يؤذن بليل ليرجع القائم ويوقظ النائم، وابن أم مكتوم يؤذن عند طلوع الفجر. وعليه يحمل ما رواه الكوفيون من أمر بلال بالإعادة: أن ذلك إذا لم يكن بعده أذان، وبه يجتمع قول الحنفية والجمهور. ومن أذن لغير الفجر قبل الوقت لم يجزئه، وعليه الإعادة بعد دخوله."},{"t":"tanbih","items":[{"t":"p","text":"ينبغي أن يتميز الأذان الأول عن الثاني بصوت المؤذن أو بوقت معروف، حتى لا يغتر الناس فيصلوا قبل الوقت أو يمسكوا عن السحور قبل وقته."}]}],"refs":["البخاري ٦١٧","الدر المختار مع رد المحتار (١/٣٨٥)","فتاوى اللجنة الدائمة (٦/٨٢)"],"related":["حكم الأذان والإقامة، وأذان المنفرد والمرأة"],"alts":["الأذان الأول","الأذان قبل الوقت","أذان بلال بالليل"]},{"n":97,"bab":"الصلاة","sub":"الأذان والإقامة","title":"ما يقوله سامع الأذان، والدعاء بعده","q":"ماذا أقول إذا سمعت الأذان؟ وهل أقول «حي على الصلاة» مثل المؤذن؟ وما الدعاء بعد الأذان؟","short":"يُسنّ لمن سمع المؤذن أن يقول مثل ما يقول، إلا عند «حي على الصلاة» و«حي على الفلاح» فيقول: «لا حول ولا قوة إلا بالله» عند الجمهور، ثم يصلي على النبي ﷺ، ثم يسأل الله له الوسيلة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا سَمِعْتُمُ الْمُؤَذِّنَ، فَقُولُوا مِثْلَ مَا يَقُولُ ثُمَّ صَلُّوا عَلَيَّ، فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى الله عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللهَ لِيَ الْوَسِيلَةَ، فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ، لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ، فَمَنْ سَأَلَ لِي الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ","src":"رواه مسلم ٣٨٤","pre":"عن عبد الله بن عمرو رضي الله عنهما أنه سمع النبي ﷺ يقول:","links":[{"book":"mt_muslim","num":384,"id":"h384"}]},{"t":"quote","text":"إِذَا قَالَ الْمُؤَذِّنُ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، فَقَالَ أَحَدُكُمْ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، ثُمَّ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، ثُمَّ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ قَالَ: أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ، ثُمَّ قَالَ: حَيَّ عَلَى الصَّلَاةِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، ثُمَّ قَالَ: حَيَّ عَلَى الْفَلَاحِ، قَالَ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، ثُمَّ قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، قَالَ: اللهُ أَكْبَرُ اللهُ أَكْبَرُ، ثُمَّ قَالَ: لَا إِلَهَ إِلَّا اللهُ، قَالَ: لَا إِلَهَ إِلَّا اللهُ مِنْ قَلْبِهِ دَخَلَ الْجَنَّةَ","src":"رواه مسلم ٣٨٥","pre":"وعن عمر بن الخطاب رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":385,"id":"h385"}]},{"t":"quote","text":"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ","src":"رواه البخاري ٦١٤","pre":"وعن جابر بن عبد الله رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":614,"id":"h614"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِيمَا يَقُولُهُ السَّامِعُ لِلْمُؤَذِّنِ: فَذَهَبَ قَوْمٌ إِلَى أَنَّهُ يَقُولُ مَا يَقُولُ الْمُؤَذِّنُ كَلِمَةً بِكَلِمَةٍ إِلَى آخِرِ النِّدَاءِ، وَذَهَبَ آخَرُونَ إِلَى أَنَّهُ يَقُولُ مِثْلَ مَا يَقُولُ الْمُؤَذِّنُ إِلَّا إِذَا قَالَ حَيِّ عَلَى الصَّلَاةِ حَيِّ عَلَى الْفَلَاحِ، فَإِنَّهُ يَقُولُ: لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.","src":"بداية المجتهد","loc":"١/١١٧","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"السنة لمن سمع الأذان أن يقول مثل ما يقول المؤذن، فإذا قال «حي على الصلاة» أو «حي على الفلاح» قال: «لا حول ولا قوة إلا بالله»؛ جمعًا بين حديث أبي سعيد العام وحديث عمر المفصل، فالمفصّل يبيّن العام. وإذا قال المؤذن في الفجر «الصلاة خير من النوم» قالها السامع مثله. ثم إذا فرغ صلى على النبي ﷺ، وقال: «اللهم رب هذه الدعوة التامة، والصلاة القائمة، آت محمدًا الوسيلة والفضيلة، وابعثه مقامًا محمودًا الذي وعدته»، ثم يدعو لنفسه بما شاء، فإن الدعاء بين الأذان والإقامة لا يُرد."},{"t":"tanbih","items":[{"t":"p","text":"من كان في الصلاة لا يجيب المؤذن، ومن كان في الخلاء أجاب بقلبه، فإذا خرج قال مثله؛ ومن كان يقرأ القرآن قطع القراءة وأجاب ثم عاد إليها."}]}],"refs":["مسلم ٣٨٤","مسلم ٣٨٥","البخاري ٦١٤","بداية المجتهد (١/١١٧)"],"related":["صفة الأذان: التكبير في أوله، والترجيع، و«الصلاة خير من النوم»"],"alts":["إجابة المؤذن","دعاء بعد الأذان","الحوقلة عند حي على الصلاة","الوسيلة والفضيلة"]},{"n":98,"bab":"الصلاة","sub":"الأذان والإقامة","title":"آداب المؤذن وشروطه، وأخذ الأجرة على الأذان","q":"هل يشترط أن يكون المؤذن متوضئًا مستقبل القبلة؟ وهل يجوز له أخذ راتب على الأذان؟","short":"يشترط في المؤذن أن يكون مسلمًا عاقلًا مميزًا، والأذان صحيح من المحدث مع الكراهة، ويستحب أن يكون متطهرًا قائمًا مستقبل القبلة صيّتًا أمينًا عالمًا بالوقت. والأفضل أن يؤذن احتسابًا، ويجوز أن يُعطى من بيت المال أو من الأوقاف رزقًا عند عامة العلماء، واختلفوا في الأجرة المشروطة: فكرهها أو منعها الحنفية والحنابلة، وأجازها مالك والشافعي، وأفتى متأخرو الحنفية بجوازها للحاجة.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"يَا رَسُولَ اللَّهِ اجْعَلْنِي إِمَامَ قَوْمِي . قَالَ «أَنْتَ إِمَامُهُمْ وَاقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لاَ يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا»","src":"رواه أبو داود ٥٣١، والنسائي ٦٧٢","pre":"عن عثمان بن أبي العاص رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":531,"id":"h531"},{"book":"mt_nasai","num":672,"id":"h672"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا اخْتِلَافُهُمْ فِي الْأُجْرَةِ عَلَى الْأَذَانِ فَلِمَكَانِ اخْتِلَافِهِمْ فِي تَصْحِيحِ الْخَبَرِ الْوَارِدِ فِي ذَلِكَ: أَعْنِي حَدِيثَ عُثْمَانَ بْنِ أَبِي الْعَاصِ أَنَّهُ قَالَ: «إِنَّ مِنْ آخِرِ مَا عَهِدَ إِلَيَّ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنْ أَتَّخِذَ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا» . وَمَنْ مَنَعَهُ قَاسَ الْأَذَانَ فِي ذَلِكَ عَلَى الصَّلَاةِ","src":"بداية المجتهد","loc":"١/١١٦","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ثبت عن النبي صلى الله عليه وسلم أنه قال لعثمان بن العاص رضي الله عنه لما سأله أن يكون إمام قومه، قال: «أنت إمامهم واقتد بأضعفهم، واتخذ مؤذنا لا يأخذ على أذانه أجرا » فدل ذلك على أن المؤذن الذي يتبرع بالأذان يتطوع به يريد ما عند الله أنه أفضل وأولى من غيره","src":"فتاوى نور على الدرب لابن باز","loc":"٦/٣٤٨","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن المؤذن يأخذ راتبًا من الأوقاف، فقال:"},{"t":"quote","text":"لا يجوز أخذ الأجرة على الأذان لأنه قربة من القرب وعبادة من العبادات، والعبادات لا يجوز أخذ الأجرة عليها","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/١٦٣","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأفضل أن يؤذن المسلم احتسابًا، ولا يشترط أجرًا؛ لحديث عثمان بن أبي العاص، وللمؤذنين المحتسبين فضل عظيم. لكن إذا خُصص للمؤذن راتب من بيت المال أو من الوقف أو من جماعة المسجد ليتفرغ للأذان ويحافظ على الأوقات، فلا حرج في أخذه، وهو رزق وإعانة لا معاوضة، وعليه عمل المسلمين اليوم. ويستحب أن يؤذن متطهرًا قائمًا مستقبل القبلة، ويلتفت يمينًا عند «حي على الصلاة» وشمالًا عند «حي على الفلاح»، ويضع إصبعيه في أذنيه، ويحسّن صوته بلا تمطيط ولا تلحين يغيّر المعنى."}],"refs":["أبو داود ٥٣١، والنسائي ٦٧٢","بداية المجتهد (١/١١٦)","بداية المجتهد (١/١١٦-١١٧)","فتاوى نور على الدرب لابن باز (٦/٣٤٨)","مجموع فتاوى ابن عثيمين (١٢/١٦٣)"],"related":["حكم الأذان والإقامة، وأذان المنفرد والمرأة"],"alts":["راتب المؤذن","أذان غير المتوضئ","آداب الأذان","الأجرة على الأذان"]},{"n":99,"bab":"الصلاة","sub":"شروط الصلاة","title":"استقبال القبلة: هل الواجب عين الكعبة أو جهتها؟ ومن أخطأ القبلة بعد الاجتهاد","q":"إذا كنت بعيدًا عن مكة فهل يجب أن أصيب عين الكعبة بالضبط؟ وإذا صليت بالاجتهاد ثم تبين أني أخطأت القبلة فهل أعيد؟","short":"استقبال القبلة شرط لصحة الصلاة بالإجماع. فمن يرى الكعبة فعليه استقبال عينها، ومن بعد عنها فالواجب عليه استقبال جهتها عند الجمهور ومنهم أبو حنيفة ومالك وأحمد، وأوجب الشافعي في الأظهر قصد العين. ومن اجتهد فصلى ثم تبين خطؤه فلا إعادة عليه عند الجمهور، وأوجبها الشافعي.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ ۗ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا يَعْمَلُونَ","ref":"البقرة: ١٤٤"},{"t":"quote","text":"مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ قِبْلَةٌ","src":"رواه الترمذي ٣٤٢","pre":"عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":342,"id":"h342"}]},{"t":"quote","text":"كُنَّا مَعَ النَّبِيِّ صلى الله عليه وسلم فِي سَفَرٍ فِي لَيْلَةٍ مُظْلِمَةٍ فَلَمْ نَدْرِ أَيْنَ الْقِبْلَةُ فَصَلَّى كُلُّ رَجُلٍ مِنَّا عَلَى حِيَالِهِ فَلَمَّا أَصْبَحْنَا ذَكَرْنَا ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَنَزَلَ: (فَأَيْنَمَا تُولُّوا فَثَمَّ وَجْهُ الله","src":"رواه الترمذي ٣٤٥","pre":"وعن عامر بن ربيعة رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":345,"id":"h345"}]},{"t":"p","text":"قال الترمذي: ليس إسناده بذاك، وقد ذهب أكثر أهل العلم إلى هذا، قالوا: إذا صلى في الغيم لغير القبلة ثم استبان له بعدما صلى فصلاته جائزة."},{"t":"h","text":"المسألة الأولى: العين أو الجهة"},{"t":"quote","text":"وَأَمَّا إِذَا غَابَتِ الْكَعْبَةُ عَنِ الْأَبْصَارِ فَاخْتَلَفُوا مِنْ ذَلِكَ فِي مَوْضِعَيْنِ: أَحَدُهُمَا: هَلِ الْفَرْضُ هُوَ الْعَيْنُ أَوِ الْجِهَةُ؟ وَالثَّانِي: هَلْ فَرْضُهُ الْإِصَابَةُ أَوْ الِاجْتِهَادُ: أَعْنِي إِصَابَةَ الْجِهَةِ أَوِ الْعَيْنِ عِنْدَ مَنْ أَوْجَبَ الْعَيْنَ؟ فَذَهَبَ قَوْمٌ إِلَى أَنَّ الْفَرْضَ هُوَ الْعَيْنُ، وَذَهَبَ آخَرُونَ إِلَى أَنَّهُ الْجِهَةُ.","src":"بداية المجتهد","loc":"١/١١٨-١١٩","pre":"قال ابن رشد:"},{"t":"h","text":"المسألة الثانية: من أخطأ القبلة"},{"t":"quote","text":"كَذَا ذَكَرَ الْكَرْخِيُّ وَالرَّازِي، وَهُوَ قَوْلُ عَامَّةِ مَشَايِخِنَا بِمَا وَرَاءَ النَّهْرِ وَقَالَ بَعْضُهُمْ: الْمَفْرُوضُ إصَابَةُ عَيْنِ الْكَعْبَةِ بِالِاجْتِهَادِ وَالتَّحَرِّي","src":"بدائع الصنائع","loc":"١/١١٨","pre":"وقال الكاساني الحنفي في «بدائع الصنائع» في فرض من بَعُد عن الكعبة: إنه إصابة الجهة،"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فدل هذا على أن قبلة أهل المدينة الجنوب كل الجنوب من طرفه إلى طرفه فيكون فرضهم استقبال الجهة، وهكذا أيضاً من لم تمكنه مشاهدة الكعبة فإنه يجب عليه استقبال جهتها","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/١٤٨","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الواجب على البعيد عن الكعبة استقبال جهتها؛ لقوله ﷺ: «ما بين المشرق والمغرب قبلة» لأهل المدينة ومن في جهتهم، ولأن الصف الطويل يصلي خلف الإمام وبعضه يخرج عن مسامتة الكعبة قطعًا، ولأن إيجاب إصابة العين حرج منفي، كما قال ابن رشد. فالانحراف اليسير عن القبلة لا يضر، ولا يلزم الناس تكلف الأجهزة الدقيقة، وإن استعملوها في بناء المساجد فحسن."},{"t":"p","text":"ومن اجتهد في معرفة القبلة بالأمارات أو بسؤال أهل المكان أو بالبوصلة، ثم صلى، ثم تبين له الخطأ بعد الصلاة، فصلاته صحيحة ولا إعادة عليه، وإن تبين له في أثنائها استدار إلى القبلة وأتم. وأما من صلى بلا اجتهاد ولا سؤال مع القدرة فأخطأ فعليه الإعادة."},{"t":"tanbih","items":[{"t":"p","text":"تسقط القبلة عن العاجز كالمريض المربوط لغير القبلة، وعن الخائف، وفي النافلة على الراحلة والسيارة في السفر، فيصلي حيث توجهت به؛ كما كان النبي ﷺ يفعل."}]}],"refs":["الترمذي ٣٤٢","الترمذي ٣٤٥","بداية المجتهد (١/١١٨-١١٩)","بداية المجتهد (١/١١٩)","بداية المجتهد (١/١١٩-١٢٠)","بدائع الصنائع (١/١١٨)","مجموع فتاوى ابن عثيمين (١٢/١٤٨)"],"related":["السترة والمرور بين يدي المصلي"],"alts":["اتجاه القبلة","الخطأ في القبلة","الانحراف عن القبلة","الصلاة لغير القبلة"]},{"n":100,"bab":"الصلاة","sub":"شروط الصلاة","title":"السترة، والمرور بين يدي المصلي","q":"هل السترة واجبة؟ وما حكم المرور بين يدي المصلي في المسجد؟","short":"اتفق العلماء على استحباب السترة للإمام والمنفرد، وأوجبها بعض أهل العلم؛ وسترة الإمام سترة لمن خلفه. ويحرم المرور بين يدي المصلي وبين سترته، أو قريبًا منه إن لم يكن له سترة، ويُشرع للمصلي أن يدفع المار.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا وَضَعَ أَحَدُكُمْ بَيْنَ يَدَيْهِ مِثْلَ مُؤْخِرَةِ الرَّحْلِ فَلْيُصَلِّ، وَلَا يُبَالِ مَنْ مَرَّ وَرَاءَ ذَلِكَ","src":"رواه مسلم ٤٩٩","pre":"عن طلحة بن عبيد الله رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":499,"id":"h499"}]},{"t":"quote","text":"لَوْ يَعْلَمُ الْمَارُّ بَيْنَ يَدَىِ الْمُصَلِّي مَاذَا عَلَيْهِ لَكَانَ أَنْ يَقِفَ أَرْبَعِينَ خَيْرًا لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ","src":"رواه البخاري ٥١٠","pre":"وعن أبي جهيم رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":510,"id":"h510"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقَ الْعُلَمَاءُ بِأَجْمَعِهِمْ عَلَى اسْتِحْبَابِ السُّتْرَةِ بَيْنَ الْمُصَلِّي وَالْقِبْلَةِ إِذَا صَلَّى مُنْفَرِدًا كَانَ أَوْ إِمَامًا، وَذَلِكَ لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «إِذَا وَضَعَ أَحَدُكُمْ بَيْنَ يَدَيْهِ مِثْلَ مُؤَخَّرَةِ الرَّحْلِ فَلْيُصَلِّ» وَاخْتَلَفُوا فِي الْخَطِّ إِذَا لَمْ يَجِدْ سُتْرَةً، فَقَالَ الْجُمْهُورُ: لَيْسَ عَلَيْهِ أَنْ يَخُطَّ.","src":"بداية المجتهد","loc":"١/١٢١","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لقوله صلى الله عليه وسلم عندما سئل عن سترة المصلي فقال: «مثل مؤخرة الرحل»","src":"فتاوى نور على الدرب لابن باز","loc":"٩/٣٠٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله في قدر السترة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"السنة المؤكدة أن يصلي المصلي إلى سترة، جدار أو عمود أو عصا أو حقيبة ونحوها بقدر مؤخرة الرحل (نحو ذراع)، ويدنو منها؛ فإن لم يجد فليخط خطًّا عند من صحح حديثه. وسترة الإمام سترة للمأمومين، فلا يضر المرور بين الصفوف عند الحاجة. ويحرم المرور بين يدي المصلي وسترته؛ للوعيد الشديد في حديث أبي جهيم، فإن لم تكن له سترة حرم المرور في موضع سجوده وما قاربه. ويُشرع للمصلي أن يرد المار بلطف، ويُعفى عن ذلك في الزحام الشديد وفي المسجد الحرام عند كثير من أهل العلم للحاجة."}],"refs":["مسلم ٤٩٩","البخاري ٥١٠","بداية المجتهد (١/١٢١)","فتاوى نور على الدرب لابن باز (٩/٣٠٥)"],"related":["استقبال القبلة: هل الواجب عين الكعبة أو جهتها؟ ومن أخطأ القبلة بعد الاجتهاد"],"alts":["سترة المصلي","المرور أمام المصلي","المرور بين الصفوف","الخط بدل السترة"]},{"n":101,"bab":"الصلاة","sub":"شروط الصلاة","title":"عورة الرجل في الصلاة، وستر العاتق، والصلاة في الثوب الواحد","q":"هل الفخذ من العورة؟ وهل تصح صلاة الرجل مكشوف الكتفين أو بثوب قصير كالشورت؟","short":"ستر العورة شرط لصحة الصلاة عند الجمهور. وعورة الرجل ما بين السرة والركبة عند الأئمة الأربعة، ومنها الفخذ، وقال بعض أهل العلم: العورة السوأتان فقط. ويجزئ الرجل الثوب الواحد يستر عورته، والسنة أن يستر عاتقيه، وأوجبه أحمد في الفريضة. فلا تصح الصلاة بلباس يكشف الفخذ عند الجمهور.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"يَـٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ","ref":"الأعراف: ٣١"},{"t":"quote","text":"الْفَخِذُ عَوْرَةٌ","src":"رواه الترمذي ٢٧٩٦","pre":"عن ابن عباس رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":2796,"id":"h2796"}]},{"t":"quote","text":"ثُمَّ حَسَرَ الإِزَارَ عَنْ فَخِذِهِ حَتَّى إِنِّي أَنْظُرُ إِلَى بَيَاضِ فَخِذِ نَبِيِّ اللَّهِ صلى الله عليه وسلم","src":"رواه البخاري ٣٧١","pre":"وعن أنس رضي الله عنه في غزوة خيبر قال:","links":[{"book":"mt_bukhari","num":371,"id":"h371"}]},{"t":"quote","text":"لَا يُصَلِّي أَحَدُكُمْ فِي الثَّوْبِ الْوَاحِدِ لَيْسَ عَلَى عَاتِقَيْهِ مِنْهُ شَيْءٌ","src":"رواه مسلم ٥١٦","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":516,"id":"h516"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ سَتْرَ الْعَوْرَةِ فَرْضٌ بِإِطْلَاقٍ، وَاخْتَلَفُوا هَلْ هُوَ شَرْطٌ مِنْ شُرُوطِ صِحَّةِ الصَّلَاةِ أَمْ لَا؟ وَكَذَلِكَ اخْتَلَفُوا فِي حَدِّ الْعَوْرَةِ مِنَ الرَّجُلِ وَالْمَرْأَةِ وَظَاهِرُ مَذْهَبِ مَالِكٍ أَنَّهَا مِنْ سُنَنِ الصَّلَاةِ، وَذَهَبَ أَبُو حَنِيفَةَ وَالشَّافِعِيُّ إِلَى أَنَّهَا مِنْ فُرُوضِ الصَّلَاةِ","src":"بداية المجتهد","loc":"١/١٢١-١٢٢","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ما بين السرة والركبة عورة الرجل، ويكون على كتفيه رداء","src":"فتاوى نور على الدرب لابن باز","loc":"٧/٢٣٦","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن عورة الرجل في الصلاة ما بين السرة والركبة، وأن الفخذ عورة؛ لأحاديث «الفخذ عورة»، وهي أحوط كما قال البخاري، وحديث أنس في كشف الفخذ حكاية حال في غير صلاة. فلا يصلي الرجل بلباس قصير يكشف فخذيه. والسنة أن يستر عاتقيه أو أحدهما ما استطاع، وأن يأخذ زينته للصلاة بلبس الثياب الحسنة الساترة؛ لقوله تعالى: ﴿خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ﴾. ومن لم يجد إلا ما يستر عورته صلى فيه بلا كراهة."},{"t":"tanbih","items":[{"t":"p","text":"من انكشف شيء يسير من عورته في الصلاة بغير قصد فستره سريعًا لم تبطل صلاته عند الجمهور، وكذا من لم يجد ما يستر به عورته يصلي على حاله ولا إعادة عليه."}]}],"refs":["الترمذي ٢٧٩٦","البخاري ٣٧١","مسلم ٥١٦","بداية المجتهد (١/١٢١-١٢٢)","بداية المجتهد (١/١٢٢)","بداية المجتهد (١/١٢٣-١٢٤)","فتاوى نور على الدرب لابن باز (٧/٢٣٦)"],"related":["عورة المرأة في الصلاة، ولباسها"],"alts":["الفخذ عورة","الصلاة بالشورت","كشف الكتفين في الصلاة","عورة الرجل"]},{"n":102,"bab":"الصلاة","sub":"شروط الصلاة","title":"عورة المرأة في الصلاة، ولباسها","q":"ما الذي يجب على المرأة ستره في الصلاة؟ وهل يجب ستر القدمين والكفين والوجه وهي تصلي في بيتها؟","short":"المرأة الحرة كلها عورة في الصلاة إلا الوجه والكفين عند الجمهور (مالك والشافعي وأحمد في رواية)، وزاد أبو حنيفة القدمين فلم يجعلهما عورة، وجعل أحمد في المشهور كلها عورة إلا الوجه. ولباسها المجزئ في الصلاة: خمار يستر رأسها وعنقها، وثوب سابغ يستر بدنها. ويجوز لها كشف وجهها في الصلاة إذا لم يكن عندها رجال أجانب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ يَقْبَلُ اللَّهُ صَلاَةَ حَائِضٍ إِلاَّ بِخِمَارٍ","src":"رواه أبو داود ٦٤١، والترمذي ٣٧٧، وابن ماجه ٦٥٥","pre":"عن عائشة رضي الله عنها عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":641,"id":"h641"},{"book":"mt_tirmidhi","num":377,"id":"h377"},{"book":"mt_ibnmajah","num":655,"id":"h655"}]},{"t":"p","text":"والمراد بالحائض: البالغة التي جرى عليها الحيض."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَهِيَ حَدُّ الْعَوْرَةِ مِنَ الْمَرْأَةِ، فَأَكْثَرُ الْعُلَمَاءِ عَلَى أَنَّ بَدَنَهَا كُلَّهُ عَوْرَةٌ مَا خَلَا الْوَجْهَ وَالْكَفَّيْنِ، وَذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّ قَدَمَهَا لَيْسَتْ بِعَوْرَةٍ، وَذَهَبَ أَبُو بَكْرِ بْنُ عَبْدِ الرَّحْمَنِ، وَأَحْمَدُ إِلَى أَنَّ الْمَرْأَةَ كُلَّهَا عَوْرَةٌ","src":"بداية المجتهد","loc":"١/١٢٣","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"العورة في الصلاة ليس فيها عندي نص قاطع أعتمد عليه وأنا فيها مقلد، والمعروف عند الحنابلة أن المرأة الحرة البالغة يجب عليها أن تستر جميع بدنها ما عدا الوجه، والصواب أيضاً أن الكفين ليسا بعورة وكذلك القدمان، وأما إذا كانت دون البلوغ فإنه على ما ذهب هؤلاء إليه فإنه لا يجب عليها إلا أن تستر ما بين السرة والركبة، والمسألة عندي لم تتحرر ولم أصل فيها إلى شيء قاطع، والله أعلم","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/٢٩٥","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن عورة المرأة في الصلاة، فقال بتواضع العلماء:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الواجب على المرأة في الصلاة أن تستر جميع بدنها إلا وجهها وكفيها، وأما قدماها فالأحوط سترهما بالثوب السابغ أو الجوارب، ولا تبطل صلاتها بانكشاف شيء يسير منهما على قول الحنفية وهو قول قوي. وإذا صلت في بيتها أو بين النساء كشفت وجهها، وأما إذا كان عندها رجال أجانب فتستر وجهها. ولا يجوز لها أن تصلي بثوب رقيق يشف عن البشرة، أو ضيق يصف حجم العورة وصفًا فاحشًا."},{"t":"tanbih","items":[{"t":"p","text":"لا يلزم المرأة لبس ثوب خاص بالصلاة، بل يجزئها كل ثوب طاهر ساتر، والمهم الستر لا اللون ولا الهيئة."}]}],"refs":["أبو داود ٦٤١، والترمذي ٣٧٧، وابن ماجه ٦٥٥","بداية المجتهد (١/١٢٣)","مجموع فتاوى ابن عثيمين (١٢/٢٩٥)","بداية المجتهد (١/١٢٤)"],"related":["عورة الرجل في الصلاة، وستر العاتق، والصلاة في الثوب الواحد"],"alts":["لباس المرأة في الصلاة","كشف القدمين في الصلاة","الخمار في الصلاة","كشف الوجه في الصلاة"]},{"n":103,"bab":"الصلاة","sub":"شروط الصلاة","title":"المواضع المنهي عن الصلاة فيها: المقبرة والحمام وأعطان الإبل والكنائس","q":"هل تجوز الصلاة في المقبرة أو إليها؟ وفي الحمام ومعاطن الإبل؟ وهل يجوز للمسافر أن يصلي في كنيسة أو معبد عند الحاجة؟","short":"الأرض كلها مسجد إلا ما استثناه الدليل. والصلاة في المقبرة وإلى القبور منهي عنها بالاتفاق، فيبطلها أحمد والظاهرية ويكرهها الجمهور؛ وكذلك الحمام ومعاطن الإبل. والصلاة في الكنائس مكروهة عند جماعة، وأجازها آخرون، وكرهها ابن عباس إذا كان فيها تماثيل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الأَرْضُ كُلُّهَا مَسْجِدٌ إِلاَّ الْمَقْبُرَةَ وَالْحَمَّامَ","src":"رواه الترمذي ٣١٧، وابن ماجه ٧٤٥","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":317,"id":"h317"},{"book":"mt_ibnmajah","num":745,"id":"h745"}]},{"t":"quote","text":"لَا تَجْلِسُوا عَلَى الْقُبُورِ، وَلَا تُصَلُّوا إِلَيْهَا","src":"رواه مسلم ٩٧٢","pre":"وعن أبي مرثد الغنوي رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":972,"id":"h972"}]},{"t":"quote","text":"صَلُّوا فِي مَرَابِضِ الْغَنَمِ وَلاَ تُصَلُّوا فِي أَعْطَانِ الإِبِلِ","src":"رواه الترمذي ٣٤٨","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":348,"id":"h348"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"تجوز الصلاة في كل موضع طاهر، ويُكره في المواضع المنهي عنها مع صحة الصلاة، وهو قول أكثر أهل العلم، ومنهم أبو حنيفة والشافعي ومالك في رواية."},{"t":"qawl","label":"القول الثاني","text":"لا تصح الصلاة في المقبرة والحمام وأعطان الإبل، للنهي الصريح عنها، وهو المشهور من مذهب أحمد."},{"t":"qawl","label":"القول الثالث","text":"استثنى بعضهم سبعة مواضع: المزبلة، والمجزرة، والمقبرة، وقارعة الطريق، والحمام، ومعاطن الإبل، وظهر الكعبة."},{"t":"quote","text":"وَقَالَ مَالِكٌ فِي الصَّلَاةِ فِي الْحَمَّامَاتِ، قَالَ: إذَا كَانَ مَوْضِعُهُ طَاهِرًا فَلَا بَأْسَ بِذَلِكَ","src":"المدونة","loc":"١/١٨٢","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ورد في ذلك حديث عن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أخرجه الترمذي أن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قال: ((الأرض كلها مسجد إلا المقبرة والحمام))","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/٣٧٥","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن الصلاة في المقبرة، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه لا تجوز الصلاة في المقبرة ولا إلى القبور؛ لنهيه الصريح، وسدًّا لذريعة الشرك وتعظيم القبور، ويستثنى من ذلك صلاة الجنازة على القبر لثبوتها عن النبي ﷺ. ولا يُصلى في الحمام ولا في معاطن الإبل للنهي الخاص، وتجوز الصلاة في مرابض الغنم. وأما الكنائس والمعابد فالأولى ألا يصلي فيها المسلم إلا لحاجة، كمسافر لم يجد غيرها، فيصلي في موضع ليس فيه صور ولا تماثيل."},{"t":"tanbih","items":[{"t":"p","text":"المسجد الذي بني على قبر، أو أُدخل فيه قبر، لا ينبغي الصلاة فيه إذا كان القبر في قبلة المصلي؛ لعموم النهي، والواجب على المسلمين ألا يبنوا المساجد على القبور."}]}],"refs":["الترمذي ٣١٧، وابن ماجه ٧٤٥","مسلم ٩٧٢","الترمذي ٣٤٨","المدونة (١/١٨٢)","مجموع فتاوى ابن عثيمين (١٢/٣٧٥)"],"related":["استقبال القبلة: هل الواجب عين الكعبة أو جهتها؟ ومن أخطأ القبلة بعد الاجتهاد"],"alts":["الصلاة في المقبرة","الصلاة في الكنيسة","المسجد فيه قبر","معاطن الإبل"]},{"n":104,"bab":"الصلاة","sub":"شروط الصلاة","title":"الكلام في الصلاة: عمدًا وسهوًا ولمصلحتها","q":"تكلمت في الصلاة ناسيًا أو جاهلًا بالحكم، أو لتنبيه الإمام، فهل بطلت صلاتي؟","short":"الكلام عمدًا لغير مصلحة الصلاة يبطلها بالإجماع. واختلفوا في كلام الناسي والجاهل: فلا يبطلها عند مالك والشافعي وأحمد في رواية، ويبطلها عند أبي حنيفة. واختلفوا في الكلام عمدًا لإصلاح الصلاة: فأجازه مالك في المشهور، ومنعه الشافعي وأبو حنيفة. والسنة لمن نابه شيء أن يسبّح الرجل وتصفّق المرأة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ هَذِهِ الصَّلَاةَ لَا يَصْلُحُ فِيهَا شَيْءٌ مِنْ كَلَامِ النَّاسِ، إِنَّمَا هُوَ التَّسْبِيحُ وَالتَّكْبِيرُ وَقِرَاءَةُ الْقُرْآنِ","src":"رواه مسلم ٥٣٧","pre":"عن معاوية بن الحكم السلمي رضي الله عنه أن رسول الله ﷺ قال له لما تكلم في الصلاة جاهلًا:","links":[{"book":"mt_muslim","num":537,"id":"h537"}]},{"t":"quote","text":"فَأُمِرْنَا بِالسُّكُوتِ، وَنُهِينَا عَنِ الْكَلَامِ","src":"رواه مسلم ٥٣٩","pre":"وعن زيد بن أرقم رضي الله عنه قال: كنا نتكلم في الصلاة حتى نزلت ﴿وَقُومُوا۟ لِلَّهِ قَـٰنِتِينَ﴾","links":[{"book":"mt_muslim","num":539,"id":"h539"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم انْصَرَفَ مِنِ اثْنَتَيْنِ فَقَالَ لَهُ ذُو الْيَدَيْنِ أَقُصِرَتِ الصَّلاَةُ أَمْ نَسِيتَ يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «أَصَدَقَ ذُو الْيَدَيْنِ». فَقَالَ النَّاسُ نَعَمْ. فَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَصَلَّى اثْنَتَيْنِ أُخْرَيَيْنِ ثُمَّ سَلَّمَ","src":"رواه البخاري ١٢٢٨","pre":"وعن أبي هريرة رضي الله عنه في قصة ذي اليدين:","links":[{"book":"mt_bukhari","num":1228,"id":"h1228"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اتفق العلماء على أن من تكلم في صلاته عامدًا بكلام الناس لغير مصلحتها، عالمًا بالتحريم، بطلت صلاته؛ لحديث زيد بن أرقم ومعاوية بن الحكم رضي الله عنهما. واختلفوا في موضعين:"},{"t":"qawl","label":"الموضع الأول","text":"من تكلم ناسيًا أو جاهلًا بالتحريم: لا تبطل صلاته عند مالك والشافعي وأحمد في رواية، وتبطل عند أبي حنيفة وأصحابه."},{"t":"qawl","label":"الموضع الثاني","text":"من تكلم عامدًا لمصلحة الصلاة، كتنبيه الإمام: لا تبطل في المشهور من مذهب مالك، وتبطل عند أبي حنيفة والشافعي."},{"t":"quote","text":"وَمَنْ تَكَلَّمَ فِي صَلَاتِهِ عَامِدًا أَوْ سَاهِيًا بَطَلَتْ صَلَاتُهُ خِلَافًا لِلشَّافِعِيِّ - رَحِمَهُ اللَّهُ - فِي الْخَطَإِ وَالنِّسْيَانِ، وَمَفْزَعُهُ الْحَدِيثُ الْمَعْرُوفُ","src":"الهداية مع فتح القدير","loc":"١/٣٩٥","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"p","text":"واستدل الحنفية بعموم حديث معاوية بن الحكم: «إن صلاتنا هذه لا يصلح فيها شيء من كلام الناس»، واستدل الجمهور بحديث ذي اليدين، وفيه أن النبي ﷺ تكلم وهو يظن أنه أتم الصلاة ثم بنى عليها."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"إذا تكلم المسلم في الصلاة ناسيا أو جاهلا لم تبطل صلاته بذلك فرضا كانت أم نفلا","src":"مجموع فتاوى ابن باز","loc":"١١/١٥٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من تكلم في الصلاة ناسيًا أو جاهلًا بالتحريم لم تبطل صلاته؛ لأن النبي ﷺ لم يأمر معاوية بن الحكم بالإعادة وقد تكلم جاهلًا، ولحديث ذي اليدين، ولقوله تعالى: ﴿رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا﴾. وأما من تكلم عامدًا عالمًا بالتحريم فصلاته باطلة ولو كان لمصلحة الصلاة، والمشروع حينئذ التسبيح للرجال والتصفيق للنساء، كما أرشد النبي ﷺ."},{"t":"tanbih","items":[{"t":"p","text":"الحركة اليسيرة للحاجة كفتح الباب، وحمل الصغير، ودفع المار، وقتل الحية والعقرب، لا تبطل الصلاة؛ والكثيرة المتوالية لغير ضرورة تبطلها."}]}],"refs":["مسلم ٥٣٧","مسلم ٥٣٩","البخاري ١٢٢٨","الهداية مع فتح القدير (١/٣٩٥)","مجموع فتاوى ابن باز (١١/١٥٧)"],"related":["نية الإمام والمأموم: صلاة المفترض خلف المتنفل"],"alts":["الكلام ناسيا في الصلاة","التنبيه في الصلاة","الحركة في الصلاة","التسبيح والتصفيق"]},{"n":105,"bab":"الصلاة","sub":"شروط الصلاة","title":"نية الإمام والمأموم: صلاة المفترض خلف المتنفل، ومن يصلي الظهر خلف من يصلي العصر","q":"دخلت المسجد وأنا لم أصلِّ الظهر والجماعة تصلي العصر، فهل أدخل معهم بنية الظهر؟ وهل يجوز أن أصلي الفريضة خلف من يصلي نافلة؟","short":"النية شرط لصحة الصلاة بالاتفاق. واختلفوا في اشتراط موافقة نية المأموم لنية الإمام: فاشترطها أبو حنيفة ومالك وأحمد في المشهور، فلا يصح الفرض خلف النفل ولا الظهر خلف العصر، ولم يشترطها الشافعي وأحمد في رواية، فيصح ذلك. والأظهر عدم الاشتراط.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ مُعَاذَ بْنَ جَبَلٍ ـ رضى الله عنه ـ كَانَ يُصَلِّي مَعَ النَّبِيِّ صلى الله عليه وسلم ثُمَّ يَأْتِي قَوْمَهُ فَيُصَلِّي بِهِمُ الصَّلاَةَ","src":"رواه البخاري ٦١٠٦","pre":"عن جابر بن عبد الله رضي الله عنهما:","links":[{"book":"mt_bukhari","num":6106,"id":"h6106"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا هَلْ مِنْ شَرْطِ نِيَّةِ الْمَأْمُومِ أَنْ تُوَافِقَ نِيَّةَ الْإِمَامِ فِي تَعْيِينِ الصَّلَاةِ وَفِي الْوُجُوبِ حَتَّى لَا يَجُوزَ أَنْ يُصَلِّيَ الْمَأْمُومُ ظُهْرًا بِإِمَامٍ يُصَلِّي عَصْرًا؟ وَلَا يَجُوزَ أَنْ يُصَلِّيَ الْإِمَامُ ظُهْرًا يَكُونُ فِي حَقِّهِ نَفْلًا، وَفِي حَقِّ الْمَأْمُومِ فَرْضًا؟ . فَذَهَبَ مَالِكٌ وَأَبُو حَنِيفَةَ إِلَى أَنَّهُ يَجِبُ أَنْ تُوَافِقَ نِيَّةُ الْمَأْمُومِ نِيَّةَ الْإِمَامِ. وَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ لَيْسَ يَجِبُ","src":"بداية المجتهد","loc":"١/١٢٨","pre":"قال ابن رشد:"},{"t":"quote","text":"وَلَا يُصَلِّي الْمُفْتَرِضُ خَلْفَ الْمُتَنَفِّلِ لِأَنَّ الِاقْتِدَاءَ بِنَاءٌ، وَوَصْفُ الْفَرْضِيَّةِ وَمَعْدُومٌ فِي حَقِّ الْإِمَامِ فَلَا يَتَحَقَّقُ الْبِنَاءُ عَلَى الْمَعْدُومِ","src":"الهداية مع فتح القدير","loc":"١/٣٧١","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه لا يشترط اتحاد نية الإمام والمأموم؛ لأن معاذًا رضي الله عنه كان يصلي الفريضة مع النبي ﷺ ثم يصلي بقومه فتكون له نافلة ولهم فريضة، وكان ذلك بعلم النبي ﷺ؛ وقوله ﷺ: «إنما جعل الإمام ليؤتم به» المراد به الاقتداء في الأفعال الظاهرة كما فسرها في الحديث نفسه. فيجوز أن يصلي الظهر خلف من يصلي العصر، والفريضة خلف من يصلي التراويح، فإذا سلم الإمام قام المأموم فأتم ما بقي عليه. ومن احتاط فصلى وحده خروجًا من الخلاف فلا حرج عليه، إلا أن الجماعة أولى."},{"t":"tanbih","items":[{"t":"p","text":"محل النية القلب، ولا يشرع التلفظ بها في الصلاة، ويكفي أن يقصد بقلبه الصلاة المعينة."}]}],"refs":["البخاري ٦١٠٦","بداية المجتهد (١/١٢٨)","الهداية مع فتح القدير (١/٣٧١)"],"related":["الكلام في الصلاة: عمدًا وسهوًا ولمصلحتها"],"alts":["الظهر خلف العصر","الفرض خلف النفل","اختلاف نية الإمام والمأموم","التلفظ بالنية"]},{"n":106,"bab":"الصلاة","sub":"صفة الصلاة","title":"تكبيرة الإحرام ولفظها، وتكبيرات الانتقال","q":"هل يجزئ في افتتاح الصلاة غير لفظ «الله أكبر»؟ وما حكم تكبيرات الانتقال إذا نسيها المصلي؟","short":"تكبيرة الإحرام ركن لا تنعقد الصلاة إلا بها عند الجمهور، ولفظها «الله أكبر» عند مالك وأحمد، وأجاز الشافعي «الله الأكبر»، وأجاز أبو حنيفة كل لفظ فيه تعظيم الله كـ«الله أجل». وتكبيرات الانتقال سنة عند الجمهور، وواجبة عند أحمد يُجبر تركها سهوًا بسجود السهو.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مِفْتَاحُ الصَّلاَةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ","src":"رواه الترمذي ٢٣٨، وأبو داود ٦١","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":238,"id":"h238"},{"book":"mt_abudawud","num":61,"id":"h61"}]},{"t":"quote","text":"أَنَّهُ كَانَ يُصَلِّي بِهِمْ، فَيُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ، فَإِذَا انْصَرَفَ قَالَ إِنِّي لأَشْبَهُكُمْ صَلاَةً بِرَسُولِ اللَّهِ صلى الله عليه وسلم","src":"رواه البخاري ٧٨٥","pre":"وعن أبي سلمة عن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":785,"id":"h785"}]},{"t":"h","text":"المسألة الأولى: حكم التكبير"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي التَّكْبِيرِ عَلَى ثَلَاثَةِ مَذَاهِبَ: فَقَوْمٌ قَالُوا: إِنَّ التَّكْبِيرَ كُلَّهُ وَاجِبٌ فِي الصَّلَاةِ. وَقَوْمٌ قَالُوا: إِنَّهُ كُلَّهُ لَيْسَ بِوَاجِبٍ وَهُوَ شَاذٌّ. وَقَوْمٌ أَوْجَبُوا تَكْبِيرَةَ الْإِحْرَامِ فَقَطْ، وَهُمُ الْجُمْهُورُ","src":"بداية المجتهد","loc":"١/١٢٩","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن تكبيرة الإحرام ركن، ولا تنعقد الصلاة إلا بلفظ «الله أكبر»؛ لأنه اللفظ الذي داوم عليه النبي ﷺ وقال: «صلوا كما رأيتموني أصلي»، ولم يُنقل عنه ولا عن أصحابه الافتتاح بغيره، فالاحتياط في الركن ألا يُعدل عنه. وتكبيرات الانتقال سنة مؤكدة، ومن تركها عمدًا فقد ترك سنة عظيمة، ومن نسي شيئًا منها سجد للسهو احتياطًا على قول من أوجبها."},{"t":"tanbih","items":[{"t":"p","text":"يُسن رفع اليدين مع تكبيرة الإحرام حذو المنكبين أو إلى فروع الأذنين، بالاتفاق؛ واختلفوا في الرفع عند الركوع والرفع منه، ويأتي في موضعه إن شاء الله."}]}],"refs":["الترمذي ٢٣٨، وأبو داود ٦١","البخاري ٧٨٥","بداية المجتهد (١/١٢٩)","بداية المجتهد (١/١٢٩-١٣٠)","بداية المجتهد (١/١٣١)"],"related":["دعاء الاستفتاح والتعوذ"],"alts":["تكبيرة الإحرام","لفظ التكبير","تكبيرات الانتقال","نسيان التكبير"]},{"n":107,"bab":"الصلاة","sub":"صفة الصلاة","title":"دعاء الاستفتاح والتعوذ","q":"ماذا أقول بعد تكبيرة الإحرام وقبل الفاتحة؟ وهل الاستفتاح واجب؟","short":"دعاء الاستفتاح سنة عند الجمهور (أبي حنيفة والشافعي وأحمد)، ولم يره مالك في الفريضة. واختار أبو حنيفة وأحمد «سبحانك اللهم وبحمدك...»، واختار الشافعي «وجهت وجهي...»، وثبت في الصحيحين «اللهم باعد بيني وبين خطاياي...». والتعوذ قبل القراءة سنة عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَسْكُتُ بَيْنَ التَّكْبِيرِ وَبَيْنَ الْقِرَاءَةِ إِسْكَاتَةً ـ قَالَ أَحْسِبُهُ قَالَ هُنَيَّةً ـ فَقُلْتُ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ، إِسْكَاتُكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ مَا تَقُولُ قَالَ «أَقُولُ اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْ خَطَايَاىَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ»","src":"رواه البخاري ٧٤٤، ومسلم ٥٩٨","pre":"عن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":744,"id":"h744"},{"book":"mt_muslim","num":598,"id":"h598"}]},{"t":"quote","text":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلاَ إِلَهَ غَيْرُكَ","src":"رواه الترمذي ٢٤٢، وأبو داود ٧٧٥","pre":"وعن أبي سعيد الخدري رضي الله عنه أن رسول الله ﷺ كان إذا قام إلى الصلاة بالليل كبر ثم يقول:","links":[{"book":"mt_tirmidhi","num":242,"id":"h242"},{"book":"mt_abudawud","num":775,"id":"h775"}]},{"t":"p","text":"تكلم الإمام أحمد وغيره في إسناده، لكن صح عن عمر رضي الله عنه أنه كان يستفتح به ويجهر به ليعلّمه الناس (رواه مسلم ٣٩٩)."},{"t":"p","text":"وثبت في صحيح مسلم (٧٧١) من حديث علي رضي الله عنه أنه ﷺ كان يقول إذا قام إلى الصلاة: «وجهت وجهي للذي فطر السماوات والأرض حنيفًا...»."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"ذَهَبَ قَوْمٌ إِلَى أَنَّ التَّوْجِيهَ فِي الصَّلَاةِ وَاجِبٌ، وَهُوَ أَنْ يَقُولَ بَعْدَ التَّكْبِيرِ: إِمَّا «وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ» وَهُوَ مَذْهَبُ الشَّافِعِيِّ، وَإِمَّا أَنْ يُسَبِّحَ، وَهُوَ مَذْهَبُ أَبِي حَنِيفَةَ، وَإِمَّا أَنْ يَجْمَعَ بَيْنَهُمَا، وَهُوَ مَذْهَبُ أَبِي يُوسُفَ صَاحِبِهِ، وَقَالَ مَالِكٌ: لَيْسَ التَّوْجِيهُ بِوَاجِبٍ فِي الصَّلَاةِ وَلَا بِسُنَّةٍ","src":"بداية المجتهد","loc":"١/١٣١","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن دعاء الاستفتاح سنة في الفريضة والنافلة؛ لثبوته عن النبي ﷺ بألفاظ متعددة، وهي من اختلاف التنوع: فيقول المصلي أحيانًا «سبحانك اللهم وبحمدك، وتبارك اسمك، وتعالى جدك، ولا إله غيرك» وهو الذي اختاره أبو حنيفة وأحمد وكان عمر يجهر به يعلّمه الناس، وأحيانًا «اللهم باعد بيني وبين خطاياي...» وهو أصحها سندًا، وأحيانًا «وجهت وجهي...» ولا سيما في صلاة الليل. ثم يتعوذ سرًّا، ثم يبسمل، ثم يقرأ الفاتحة. ومن ترك الاستفتاح فصلاته صحيحة بالإجماع."}],"refs":["البخاري ٧٤٤، ومسلم ٥٩٨","الترمذي ٢٤٢، وأبو داود ٧٧٥","بداية المجتهد (١/١٣١)"],"related":["البسملة في الصلاة: هل تُقرأ؟ وهل يُجهر بها؟","تكبيرة الإحرام ولفظها، وتكبيرات الانتقال"],"alts":["الاستفتاح","سبحانك اللهم وبحمدك","دعاء بعد التكبير","التعوذ في الصلاة"]},{"n":108,"bab":"الصلاة","sub":"صفة الصلاة","title":"البسملة في الصلاة: هل تُقرأ؟ وهل يُجهر بها؟","q":"هل البسملة آية من الفاتحة؟ وهل يجهر بها الإمام في الصلاة الجهرية؟","short":"اختلف العلماء: فيقرأ البسملة سرًّا مع الفاتحة في كل ركعة أبو حنيفة وأحمد والثوري، ويجهر بها في الجهرية الشافعي ويعدها آية من الفاتحة، ولا يقرأها مالك في الفريضة. والأظهر أنها تُقرأ سرًّا، ويجوز الجهر بها أحيانًا للتعليم أو تأليف القلوب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبِي بَكْرٍ، وَعُمَرَ، وَعُثْمَانَ، فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقْرَأُ {بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ}","src":"رواه مسلم ٣٩٩","pre":"عن أنس رضي الله عنه قال:","links":[{"book":"mt_muslim","num":399,"id":"h399"}]},{"t":"p","text":"وروى النسائي (٩٠٥) عن نعيم المجمر قال: صليت وراء أبي هريرة فقرأ «بسم الله الرحمن الرحيم» ثم قرأ بأم القرآن... ثم قال: «والذي نفسي بيده إني لأشبهكم صلاة برسول الله ﷺ»."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي قِرَاءَةِ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ فِي افْتِتَاحِ الْقِرَاءَةِ فِي الصَّلَاةِ، فَمَنَعَ ذَلِكَ مَالِكٌ فِي الصَّلَاةِ الْمَكْتُوبَةِ جَهْرًا كَانَتْ أَوْ سِرًّا، لَا فِي اسْتِفْتَاحِ أُمِّ الْقُرْآنِ، وَلَا فِي غَيْرِهَا مِنَ السِّوَرِ، وَأَجَازَ ذَلِكَ فِي النَّافِلَةِ.","src":"بداية المجتهد","loc":"١/١٣٢","pre":"قال ابن رشد:"},{"t":"quote","text":"التسمية من القرآن عند أبي حنيفة وليست جزء سورة، وفي رواية عنه أنها جزء الفاتحة، وعند الشوافع جزء الفاتحة قطعاً، وفي جزئيتها لسائر السور قولان، وعند مالك إنما هي نازلة للفصل بين السورتين، وقال الأحناف: يخفي ببسم الله، وقال الشوافع: يجهر به، ومالك وأحمد موافقان لنا","src":"العرف الشذي","loc":"١/٢٥٠","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"قال الشافعي ولاصحاب وَيُسَنُّ الْجَهْرُ بِالْبَسْمَلَةِ","src":"المجموع","loc":"٣/٣٣٣","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الصحيح من أقوال العلماء أن المصلي يقرأ البسملة سرا قبل قراءة الفاتحة في كل ركعة من صلاته، سواء كانت الصلاة سرية أم جهرية","src":"فتاوى اللجنة الدائمة","loc":"٦/٣٨١","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن البسملة آية من القرآن أنزلت للفصل بين السور، وأن السنة قراءتها سرًّا قبل الفاتحة وقبل السورة في كل ركعة؛ لحديث أنس في صحيح مسلم، وهو موافق لقول أبي حنيفة وأحمد وعمل أكثر أهل العلم. وما ورد من الجهر بها فمحمول على الأحيان والتعليم، كما وجهه الكشميري الحنفي وغيره، فلا يُنكر على من جهر بها اقتداءً بمذهب الشافعي، ولا على من أسر، والأمر واسع، وتأليف القلوب واجتماع الكلمة أهم منه."}],"refs":["مسلم ٣٩٩","بداية المجتهد (١/١٣٢)","العرف الشذي (١/٢٥٠)","المجموع (٣/٣٣٣)","فتاوى اللجنة الدائمة (٦/٣٨١)"],"related":["قراءة الفاتحة في الصلاة"],"alts":["الجهر بالبسملة","البسملة آية من الفاتحة","الإسرار بالبسملة"]},{"n":109,"bab":"الصلاة","sub":"صفة الصلاة","title":"قراءة الفاتحة في الصلاة","q":"هل تصح الصلاة بغير الفاتحة؟ وهل تجب الفاتحة في كل ركعة؟ وماذا يقرأ في الركعتين الأخيرتين؟","short":"اتفق العلماء على وجوب القراءة في الصلاة. والفاتحة ركن في كل ركعة عند مالك والشافعي وأحمد، لا تصح الصلاة بدونها؛ وهي واجبة عند أبي حنيفة يأثم تاركها وتلزمه الإعادة أو سجود السهو، والفرض عنده قراءة ما تيسر في الركعتين الأوليين. ويستحب عند الحنفية في الأخيرتين الفاتحة أو التسبيح، وعند الجمهور الفاتحة.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ","ref":"المزمل: ٢٠"},{"t":"quote","text":"لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ","src":"رواه البخاري ٧٥٦، ومسلم ٣٩٤","pre":"عن عبادة بن الصامت رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":756,"id":"h756"},{"book":"mt_muslim","num":394,"id":"h394"}]},{"t":"quote","text":"«مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ» ثَلَاثًا غَيْرُ تَمَامٍ","src":"رواه مسلم ٣٩٥","pre":"وعن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":395,"id":"h395"}]},{"t":"quote","text":"إِذَا قُمْتَ إِلَى الصَّلاَةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا، وَافْعَلْ ذَلِكَ فِي صَلاَتِكَ كُلِّهَا","src":"رواه البخاري ٧٥٧","pre":"وقال ﷺ للمسيء صلاته:","links":[{"book":"mt_bukhari","num":757,"id":"h757"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اختلف العلماء في القراءة الواجبة في الصلاة على قولين مشهورين:"},{"t":"qawl","label":"القول الأول","text":"قراءة الفاتحة ركن لا تصح الصلاة إلا بها في كل ركعة، لمن حفظها، وهو قول الشافعي وأحمد وأشهر الروايتين عن مالك."},{"t":"qawl","label":"القول الثاني","text":"الفرض قراءة ما تيسر من القرآن، وأقله عند أبي حنيفة آية، وعند صاحبيه ثلاث آيات قصار أو آية طويلة، وقراءة الفاتحة واجبة عندهم يأثم تاركها وتُجبر بسجود السهو إن تركها ساهيًا، وتجب القراءة في الركعتين الأوليين."},{"t":"quote","text":"وَأَدْنَى مَا يُجْزِئُ مِنْ الْقِرَاءَةِ فِي الصَّلَاةِ آيَةٌ عِنْدَ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ -","src":"الهداية مع فتح القدير","loc":"١/٣٣١","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"quote","text":"وَقَالَا: ثَلَاثُ آيَاتٍ قِصَارٍ أَوْ آيَةٌ طَوِيلَةٌ لِأَنَّهُ لَا يُسَمَّى قَارِئًا بِدُونِهِ فَأَشْبَة قِرَاءَةَ مَا دُونَ الْآيَةِ","src":"الهداية مع فتح القدير","loc":"١/٣٣٢"},{"t":"quote","text":"وَاعْلَمْ أَنَّ الشَّافِعِيَّةَ يُثْبِتُونَ رُكْنِيَّةَ الْفَاتِحَةِ عَلَى مَعْنَى الْوُجُوبِ عِنْدَنَا، فَإِنَّهُمْ لَا يَقُولُونَ بِوُجُوبِهَا قَطْعًا بَلْ ظَنًّا","src":"الهداية مع فتح القدير","loc":"١/٢٩٤","pre":"وقال الكمال ابن الهمام الحنفي رحمه الله مبينًا أن الخلاف بين المذهبين أقرب مما يُظن:"},{"t":"quote","text":"ههنا مسألتان: مسألة حكم الفاتحة فقال أبو حنيفة بوجوبها، وقال الثلاثة بركنيتها، وفي رواية للمالكية وجوب الفاتحة كما في العيني","src":"العرف الشذي","loc":"١/٢٥٣","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وقال بعض الأحناف: إن النفي في «لا صلاة» نفي الكمال وعندي أنه مدخول فيه فإن الفاتحة واجبة عندنا","src":"العرف الشذي","loc":"١/٢٥٤","pre":"وقال أيضًا منصفًا:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن قراءة الفاتحة ركن في كل ركعة للإمام والمنفرد؛ لقوله ﷺ: «لا صلاة لمن لم يقرأ بفاتحة الكتاب»، والنفي فيه لنفي الصحة كما هو الأصل، وقد ردّ الكشميري الحنفي نفسه تأويله بنفي الكمال؛ ولقوله ﷺ للمسيء صلاته بعد أن علّمه الركعة الأولى: «وافعل ذلك في صلاتك كلها»، وفي رواية: «ثم اقرأ بأم القرآن». وأما قوله: «اقرأ ما تيسر معك» فمحمول على ما زاد على الفاتحة، أو على من لا يحسنها. ويقرأ في الركعتين الأخيرتين الفاتحة، وتجوز الزيادة عليها أحيانًا."},{"t":"tanbih","items":[{"t":"p","text":"من لا يحسن الفاتحة كالمسلم الجديد يتعلمها وجوبًا، وإلى أن يتعلمها يقرأ ما يحسن من القرآن، فإن لم يحسن شيئًا قال: «سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله» كما أرشد النبي ﷺ."},{"t":"p","text":"وأما قراءة المأموم خلف الإمام فتأتي في باب صلاة الجماعة إن شاء الله."}]}],"refs":["البخاري ٧٥٦، ومسلم ٣٩٤","مسلم ٣٩٥","البخاري ٧٥٧","الهداية مع فتح القدير (١/٣٣١)","الهداية مع فتح القدير (١/٣٣٢)","الهداية مع فتح القدير (١/٢٩٤)","العرف الشذي (١/٢٥٣)","العرف الشذي (١/٢٥٤)"],"related":["البسملة في الصلاة: هل تُقرأ؟ وهل يُجهر بها؟"],"alts":["حكم الفاتحة","الصلاة بدون الفاتحة","القراءة في الركعتين الأخيرتين","نسيان الفاتحة"]},{"n":110,"bab":"الصلاة","sub":"صفة الصلاة","title":"أذكار الركوع والسجود، والدعاء فيهما، وقراءة القرآن فيهما","q":"ماذا أقول في الركوع والسجود؟ وهل يجوز الدعاء في السجود بغير العربية أو بحاجات الدنيا؟ وهل أقرأ آية في السجود؟","short":"يقول في الركوع «سبحان ربي العظيم» وفي السجود «سبحان ربي الأعلى» ثلاثًا، وهو سنة عند الجمهور وواجب عند أحمد. ويُنهى عن قراءة القرآن في الركوع والسجود عند عامة الفقهاء. ويُستحب الدعاء في السجود، وأجاز مالك والشافعي الدعاء بكل خير من أمور الدين والدنيا، وقصره أبو حنيفة على ما يشبه ألفاظ القرآن والسنة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَمَّا نَزَلَتْ { فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ } قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «اجْعَلُوهَا فِي رُكُوعِكُمْ» . فَلَمَّا نَزَلَتْ { سَبِّحِ اسْمَ رَبِّكَ الأَعْلَى } قَالَ «اجْعَلُوهَا فِي سُجُودِكُمْ»","src":"رواه أبو داود ٨٦٩","pre":"عن عقبة بن عامر رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":869,"id":"h869"}]},{"t":"quote","text":"أَلَا وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ الْقُرْآنَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ عَزَّ وَجَلَّ، وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ، فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ","src":"رواه مسلم ٤٧٩","pre":"وعن ابن عباس رضي الله عنهما أن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":479,"id":"h479"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ «سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي»","src":"رواه البخاري ٧٩٤","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":794,"id":"h794"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اتفق جمهور العلماء على النهي عن قراءة القرآن في الركوع والسجود، لحديث علي وابن عباس رضي الله عنهم. واختلفوا في ذكر الركوع والسجود:"},{"t":"qawl","label":"القول الأول","text":"يقول في ركوعه: سبحان ربي العظيم، وفي سجوده: سبحان ربي الأعلى، ثلاثًا، وهو أدنى الكمال، وهو قول أبي حنيفة والشافعي وأحمد والجمهور، وأوجبه أحمد مرة واحدة."},{"t":"qawl","label":"القول الثاني","text":"ليس في الركوع والسجود قول محدود، فيعظّم الرب في الركوع، ويجتهد في الدعاء في السجود، وهو قول مالك."},{"t":"quote","text":"وَيَقُولُ سُبْحَانَ رَبِّي الْعَظِيمِ ثَلَاثًا وَذَلِكَ أَدْنَاهُ لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - «إذَا رَكَعَ أَحَدُكُمْ فَلْيَقُلْ فِي رُكُوعِهِ سُبْحَانَ رَبِّي الْعَظِيمِ ثَلَاثًا وَذَلِكَ أَدْنَاهُ» أَيْ أَدْنَى كَمَالِ الْجَمْعِ","src":"الهداية مع فتح القدير","loc":"١/٢٩٨","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المصلي يقول في ركوعه «سبحان ربي العظيم» وفي سجوده «سبحان ربي الأعلى»، وأقل الكمال ثلاث، ويزيد ما ورد كقوله: «سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي». ويعظّم الرب في الركوع، ويجتهد في الدعاء في السجود؛ فإن أقرب ما يكون العبد من ربه وهو ساجد. ويجوز في الفريضة والنافلة الدعاء بكل خير من أمر الدين والدنيا، والأولى أن يكون بالأدعية المأثورة، وأن يكون بالعربية لمن يحسنها؛ ومن لا يحسنها فالأحوط أن يدعو بلغته في النافلة، أو في سجوده بعد الصلاة. ولا يقرأ القرآن في الركوع والسجود، إلا ما كان من آيات الدعاء على قصد الدعاء لا التلاوة، كقوله: ﴿رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً﴾."}],"refs":["أبو داود ٨٦٩","مسلم ٤٧٩","البخاري ٧٩٤","الهداية مع فتح القدير (١/٢٩٨)"],"related":["التشهد وصيغته، والصلاة على النبي ﷺ، والدعاء قبل السلام"],"alts":["تسبيح الركوع والسجود","الدعاء في السجود","الدعاء بغير العربية في الصلاة","قراءة القرآن في السجود"]},{"n":111,"bab":"الصلاة","sub":"صفة الصلاة","title":"التشهد وصيغته، والصلاة على النبي ﷺ، والدعاء قبل السلام","q":"هل التشهد واجب؟ وأي صيغة أختار؟ وهل الصلاة على النبي ﷺ في التشهد الأخير واجبة؟","short":"التشهد الأخير ركن عند الشافعي وأحمد، وواجب عند أبي حنيفة، وسنة عند مالك؛ والتشهد الأول واجب عند أبي حنيفة وأحمد، سنة عند مالك والشافعي، ويُجبر بسجود السهو. واختار أبو حنيفة وأحمد وأكثر أهل الحديث تشهد ابن مسعود، والشافعي تشهد ابن عباس، ومالك تشهد عمر، وكلها جائزة. والصلاة على النبي ﷺ في التشهد الأخير ركن عند الشافعي وأحمد، سنة عند أبي حنيفة ومالك.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَإِذَا صَلَّى أَحَدُكُمْ فَلْيَقُلِ التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. فَإِنَّكُمْ إِذَا قُلْتُمُوهَا أَصَابَتْ كُلَّ عَبْدٍ لِلَّهِ صَالِحٍ فِي السَّمَاءِ وَالأَرْضِ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ","src":"رواه البخاري ٨٣١، ومسلم ٤٠٢","pre":"عن عبد الله بن مسعود رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":831,"id":"h831"},{"book":"mt_muslim","num":402,"id":"h402"}]},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ فَكَانَ يَقُولُ: «التَّحِيَّاتُ الْمُبَارَكَاتُ، الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللهِ»","src":"رواه مسلم ٤٠٣","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_muslim","num":403,"id":"h403"}]},{"t":"quote","text":"إِذَا تَشَهَّدَ أَحَدُكُمْ فَلْيَسْتَعِذْ بِاللهِ مِنْ أَرْبَعٍ يَقُولُ: اللهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","src":"رواه مسلم ٥٨٨","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":588,"id":"h588"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي وُجُوبِ التَّشَهُّدِ، وَفِي الْمُخْتَارِ مِنْهُ، فَذَهَبَ مَالِكٌ، وَأَبُو حَنِيفَةَ، وَجَمَاعَةٌ إِلَى أَنَّ التَّشَهُّدَ لَيْسَ بِوَاجِبٍ، وَذَهَبَتْ طَائِفَةٌ إِلَى وُجُوبِهِ، وَبِهِ قَالَ الشَّافِعِيُّ، وَأَحْمَدُ، وَدَاوُدُ","src":"بداية المجتهد","loc":"١/١٣٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التشهد الأخير لا بد منه، وأن التشهد الأول واجب يُجبر بسجود السهو إذا نُسي، كما سجد النبي ﷺ لما قام عنه؛ وصيغ التشهد الثابتة كلها جائزة، وأصحها تشهد ابن مسعود في الصحيحين، وهو مختار أبي حنيفة وأحمد. والصلاة على النبي ﷺ في التشهد الأخير من آكد السنن، والأحوط ألا يتركها المصلي؛ لأمره ﷺ أصحابه بها لما سألوه كيف يصلون عليه في الصلاة، وأتمها الصلاة الإبراهيمية. ثم يستعيذ من الأربع، ويدعو بما أحب قبل السلام."}],"refs":["البخاري ٨٣١، ومسلم ٤٠٢","مسلم ٤٠٣","مسلم ٥٨٨","بداية المجتهد (١/١٣٨)","بداية المجتهد (١/١٣٩)"],"related":["التسليم من الصلاة: حكمه وعدده"],"alts":["صيغة التشهد","التحيات","الصلاة الإبراهيمية","التشهد الأول"]},{"n":112,"bab":"الصلاة","sub":"صفة الصلاة","title":"التسليم من الصلاة: حكمه وعدده","q":"هل السلام في آخر الصلاة فرض؟ وهل يكفي تسليمة واحدة؟","short":"التسليم ركن لا يخرج من الصلاة إلا به عند الجمهور (مالك والشافعي وأحمد)، وهو واجب عند أبي حنيفة يخرج من الصلاة بكل فعل ينافيها مع الإثم. والواجب تسليمة واحدة عند الجمهور، وأوجب أحمد في المشهور التسليمتين في الفريضة، والسنة تسليمتان عن اليمين والشمال.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مِفْتَاحُ الصَّلاَةِ الطُّهُورُ وَتَحْرِيمُهَا التَّكْبِيرُ وَتَحْلِيلُهَا التَّسْلِيمُ","src":"رواه الترمذي ٢٣٨","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":238,"id":"h238"}]},{"t":"quote","text":"أَنَّهُ كَانَ يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ «السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ»","src":"رواه الترمذي ٢٩٥","pre":"وعن عبد الله بن مسعود رضي الله عنه عن النبي ﷺ:","links":[{"book":"mt_tirmidhi","num":295,"id":"h295"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"الخروج من الصلاة بلفظ السلام فرض لا تصح الصلاة إلا به، وهو قول الجمهور: مالك والشافعي وأحمد؛ لحديث علي رضي الله عنه: «وتحليلها التسليم». ثم منهم من أوجب تسليمة واحدة، وهو قول مالك والشافعي، ومنهم من أوجب التسليمتين، وهو المشهور عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"لفظ السلام واجب وليس بفرض، فمن تركه أساء وصحت صلاته، وهو قول أبي حنيفة وأصحابه."},{"t":"quote","text":"ثُمَّ إصَابَةُ لَفْظِ السَّلَامِ وَاجِبَةٌ عِنْدَنَا وَلَيْسَتْ بِفَرْضٍ خِلَافًا لِلشَّافِعِيِّ - رَحِمَهُ اللَّهُ -","src":"الهداية مع فتح القدير","loc":"١/٣٢١","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التسليم ركن لا يخرج المصلي من صلاته إلا به؛ لقوله ﷺ: «وتحليلها التسليم»، ولمداومته ﷺ عليه. والسنة أن يسلم تسليمتين عن يمينه وعن شماله، والأحوط ألا يقتصر على واحدة في الفريضة خروجًا من خلاف من أوجبهما، وهو مذهب الحنفية في السنية أيضًا."}],"refs":["الترمذي ٢٣٨","الترمذي ٢٩٥","الهداية مع فتح القدير (١/٣٢١)"],"related":["التشهد وصيغته، والصلاة على النبي ﷺ، والدعاء قبل السلام"],"alts":["السلام في الصلاة","التسليمة الواحدة","الخروج من الصلاة"]},{"n":113,"bab":"الصلاة","sub":"صفة الصلاة","title":"القنوت في صلاة الفجر، وقنوت النوازل","q":"هل القنوت في صلاة الفجر سنة دائمة؟ وما حكم القنوت عند نزول المصائب بالمسلمين؟","short":"اختلف العلماء: فالقنوت في الفجر سنة دائمة عند الشافعي، ومستحب عند مالك، ولا يُشرع دائمًا عند أبي حنيفة وأحمد والثوري، وإنما يُشرع عند النوازل. وقنوت النوازل ثابت باتفاق أهل العلم. والأظهر أن القنوت الدائم في الفجر غير مسنون، وأن قنوت النوازل مشروع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"قُلْتُ لأَبِي يَا أَبَةِ إِنَّكَ قَدْ صَلَّيْتَ خَلْفَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَبِي بَكْرٍ وَعُمَرَ وَعُثْمَانَ وَعَلِيِّ بْنِ أَبِي طَالِبٍ هَا هُنَا بِالْكُوفَةِ نَحْوًا مِنْ خَمْسِ سِنِينَ أَكَانُوا يَقْنُتُونَ قَالَ أَىْ بُنَىَّ مُحْدَثٌ","src":"رواه الترمذي ٤٠٢، وابن ماجه ١٢٤١","pre":"عن أبي مالك الأشجعي قال:","links":[{"book":"mt_tirmidhi","num":402,"id":"h402"},{"book":"mt_ibnmajah","num":1241,"id":"h1241"}]},{"t":"p","text":"قال الترمذي: هذا حديث حسن صحيح، والعمل عليه عند أكثر أهل العلم."},{"t":"quote","text":"كَانَ إِذَا أَرَادَ أَنْ يَدْعُوَ عَلَى أَحَدٍ أَوْ يَدْعُوَ لأَحَدٍ قَنَتَ بَعْدَ الرُّكُوعِ، فَرُبَّمَا قَالَ إِذَا قَالَ «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، اللَّهُمَّ أَنْجِ الْوَلِيدَ بْنَ الْوَلِيدِ، وَسَلَمَةَ بْنَ هِشَامٍ، وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ، اللَّهُمَّ اشْدُدْ وَطْأَتَكَ عَلَى مُضَرَ وَاجْعَلْهَا سِنِينَ كَسِنِي يُوسُفَ». يَجْهَرُ بِذَلِكَ وَكَانَ يَقُولُ فِي بَعْضِ صَلاَتِهِ فِي صَلاَةِ الْفَجْرِ «اللَّهُمَّ الْعَنْ فُلاَنًا وَفُلاَنًا». لأَحْيَاءٍ مِنَ الْعَرَبِ، حَتَّى أَنْزَلَ اللَّهُ {لَيْسَ لَكَ مِنَ الأَمْرِ شَىْءٌ}","src":"رواه البخاري ٤٥٦٠","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":4560,"id":"h4560"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي الْقُنُوتِ، فَذَهَبَ مَالِكٌ إِلَى أَنَّ الْقُنُوتَ فِي صَلَاةِ الصُّبْحِ مُسْتَحَبٌّ، وَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ سُنَّةٌ، وَذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّهُ لَا يَجُوزُ الْقُنُوتُ فِي صَلَاةِ الصُّبْحِ، وَأَنَّ الْقُنُوتَ إِنَّمَا مَوْضِعُهُ الْوَتْرُ، وَقَالَ قَوْمٌ: بَلْ يَقْنُتُ فِي كُلِّ صَلَاةٍ. وَقَالَ قَوْمٌ: لَا قُنُوتَ إِلَّا فِي رَمَضَانَ، وَقَالَ قَوْمٌ: بَلْ فِي النِّصْفِ الْأَخِيرِ مِنْهُ، وَقَالَ قَوْمٌ: بَلْ فِي النِّصْفِ الْأَوَّلِ مِنْهُ","src":"بداية المجتهد","loc":"١/١٤٠","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الشافعي: إن القنوت في صلاة الفجر في السنة كلها، ولا قنوت في الوتر إلا في النصف الثاني من رمضان، ومذهبنا أن القنوت في السنة كلها في الوتر، وأما إذا نزلت نازلة على المسلمين فمفهوم فتح القدير أن قنوت النازلة نسخت ولا يؤخذ بمفهومه، قال فإن العيني نقل في شرح الهداية","src":"العرف الشذي","loc":"١/٣٨١","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وإذا أتينا إلى فعل الأئمة - أئمة المسلمين - الإمام أحمد بن حنبل - رحمه الله - كان يرى أن القنوت في صلاة الفجر بدعة، ومع ذلك يقول: من صلى خلف إمام يقنت في صلاة الفجر فليتابعه وليؤمن على دعائه، ولم يقل ينصرف عنه","src":"مجموع فتاوى ابن عثيمين","loc":"١٤/١٢٧","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله في الحرص على الاجتماع وترك الخلاف:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المداومة على القنوت في صلاة الفجر ليست من السنة؛ لقول طارق الأشجعي رضي الله عنه وقد صلى خلف النبي ﷺ وخلفائه: «أي بني محدث»، ولأن الذي ثبت عنه ﷺ القنوت في النوازل يدعو لقوم أو على قوم ثم يتركه، وهو قول أبي حنيفة وأحمد. ويُشرع قنوت النوازل إذا نزلت بالمسلمين مصيبة عامة، في الفجر أو في الصلوات الجهرية أو في الخمس، بعد الرفع من الركوع. ومن صلى خلف إمام يقنت في الفجر تابعه وأمّن على دعائه، فإن الخلاف شر، والمسألة اجتهادية."},{"t":"tanbih","items":[{"t":"p","text":"القنوت في الوتر مشروع عند الجمهور، وأوجبه أبو حنيفة، ويأتي في باب الوتر إن شاء الله."}]}],"refs":["الترمذي ٤٠٢، وابن ماجه ١٢٤١","البخاري ٤٥٦٠","بداية المجتهد (١/١٤٠)","العرف الشذي (١/٣٨١)","مجموع فتاوى ابن عثيمين (١٤/١٢٧)"],"related":["التسليم من الصلاة: حكمه وعدده"],"alts":["قنوت الفجر","قنوت النازلة","دعاء القنوت","القنوت بعد الركوع"]},{"n":114,"bab":"الصلاة","sub":"صفة الصلاة","title":"رفع اليدين عند الركوع والرفع منه","q":"هل يرفع المصلي يديه عند الركوع وعند الرفع منه؟ ورأيت بعض المصلين يرفعون وبعضهم لا يرفعون، فأيهما الصواب؟","short":"اتفق العلماء على مشروعية رفع اليدين عند تكبيرة الإحرام. واختلفوا في الرفع عند الركوع والرفع منه: فهو سنة عند الشافعي وأحمد وجمهور أهل الحديث، ورواية عن مالك؛ ولا يرفع إلا في تكبيرة الإحرام عند أبي حنيفة والثوري وأهل الكوفة، وهي رواية ابن القاسم عن مالك. وكلا الأمرين ثابت معمول به عند السلف، والأمر واسع، والرفع أكثر حديثًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَرْفَعُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ إِذَا افْتَتَحَ الصَّلاَةَ، وَإِذَا كَبَّرَ لِلرُّكُوعِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ أَيْضًا وَقَالَ «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ». وَكَانَ لاَ يَفْعَلُ ذَلِكَ فِي السُّجُودِ","src":"رواه البخاري ٧٣٥، ومسلم ٣٩٠","pre":"عن عبد الله بن عمر رضي الله عنهما:","links":[{"book":"mt_bukhari","num":735,"id":"h735"},{"book":"mt_muslim","num":390,"id":"h390"}]},{"t":"quote","text":"أَلاَ أُصَلِّي بِكُمْ صَلاَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَصَلَّى فَلَمْ يَرْفَعْ يَدَيْهِ إِلاَّ فِي أَوَّلِ مَرَّةٍ","src":"رواه الترمذي ٢٥٧","pre":"وعن علقمة قال: قال عبد الله بن مسعود رضي الله عنه:","links":[{"book":"mt_tirmidhi","num":257,"id":"h257"}]},{"t":"p","text":"قال الترمذي: حديث ابن مسعود حديث حسن، وبه يقول غير واحد من أهل العلم من أصحاب النبي ﷺ والتابعين، وهو قول سفيان الثوري وأهل الكوفة."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"لا يرفع المصلي يديه إلا عند تكبيرة الإحرام، وهو قول أبي حنيفة وأصحابه والثوري وأهل الكوفة، ورواية ابن القاسم عن مالك."},{"t":"qawl","label":"القول الثاني","text":"يرفع يديه عند تكبيرة الإحرام، وعند الركوع، وعند الرفع منه، وهو قول الشافعي وأحمد وجمهور أهل الحديث، ورواية عن مالك، وزاد بعضهم الرفع عند القيام من التشهد الأول."},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"الثالث: تواتر التعامل: وهو أن يعمل به أهل العمل بحيث يستحيل تكذيبهم، وهذا التواتر قريب من التواتر الثاني، ومثال هذا التواتر العمل برفع اليدين عند الركوع وتركه فإنه عمل به غير واحد في القرون الثلاثة","src":"العرف الشذي","loc":"١/٤١","pre":"وقال الشيخ محمد أنور شاه الكشميري الحنفي في أقسام التواتر:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن رفع اليدين عند الركوع وعند الرفع منه وعند القيام من التشهد الأول سنة ثابتة؛ لحديث ابن عمر في الصحيحين، ورواه عن النبي ﷺ جمع كثير من الصحابة. وترك الرفع ثابت أيضًا في حديث ابن مسعود الذي حسّنه الترمذي، وعليه عمل أهل الكوفة من الصحابة والتابعين، وقد قرر الكشميري الحنفي أن الرفع والترك كليهما من التواتر العملي في القرون الثلاثة الأولى."},{"t":"p","text":"فالمسألة من سنن الهيئات لا من الأركان، ولا تبطل الصلاة بفعل ولا ترك بالإجماع، ولا يجوز أن تكون سببًا للتنازع والتفرق بين المسلمين في المساجد؛ فمن رفع فقد أخذ بسنة، ومن ترك فقد أخذ بسنة عمل بها جماعة من السلف، والرفع أكثر أحاديث."},{"t":"tanbih","items":[{"t":"p","text":"يرفع اليدين حذو المنكبين، أو إلى فروع الأذنين، وكلاهما ثابت؛ وهو مذهب الجمهور في الأول، والحنفية في الثاني."}]}],"refs":["البخاري ٧٣٥، ومسلم ٣٩٠","الترمذي ٢٥٧","العرف الشذي (١/٤١)"],"related":["تكبيرة الإحرام ولفظها، وتكبيرات الانتقال","وضع اليد اليمنى على اليسرى في القيام، وموضعهما"],"alts":["رفع اليدين في الصلاة","ترك رفع اليدين","الرفع عند الركوع"]},{"n":115,"bab":"الصلاة","sub":"صفة الصلاة","title":"الطمأنينة والاعتدال في الركوع والسجود والرفع منهما","q":"أرى بعض الناس يصلون بسرعة، لا يعتدلون بعد الركوع ولا يجلسون بين السجدتين إلا لحظة، فهل تصح صلاتهم؟","short":"الطمأنينة في الركوع والسجود والاعتدال منهما ركن عند الشافعي وأحمد وأبي يوسف، لا تصح الصلاة بدونها؛ وهي واجبة عند أبي حنيفة ومحمد يأثم تاركها وتجب عليه الإعادة. فالجميع متفقون على أن من نقر صلاته ولم يطمئن فقد أساء إساءة عظيمة، وأن صلاته إما باطلة وإما ناقصة يجب إعادتها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا قُمْتَ إِلَى الصَّلاَةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا، وَافْعَلْ ذَلِكَ فِي صَلاَتِكَ كُلِّهَا","src":"رواه البخاري ٧٥٧","pre":"عن أبي هريرة رضي الله عنه أن النبي ﷺ قال للمسيء صلاته بعد أن قال له ثلاثًا «ارجع فصل فإنك لم تصل»:","links":[{"book":"mt_bukhari","num":757,"id":"h757"}]},{"t":"quote","text":"لاَ تُجْزِئُ صَلاَةُ الرَّجُلِ حَتَّى يُقِيمَ ظَهْرَهُ فِي الرُّكُوعِ وَالسُّجُودِ","src":"رواه أبو داود ٨٥٥","pre":"وعن أبي مسعود البدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":855,"id":"h855"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"ذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّ الِاعْتِدَالَ مِنَ الرُّكُوعِ وَفِي الرُّكُوعِ غَيْرُ وَاجِبٍ، وَقَالَ الشَّافِعِيُّ: هُوَ وَاجِبٌ، وَاخْتَلَفَ أَصْحَابُ مَالِكٍ: هَلْ ظَاهِرُ مَذْهَبِهِ يَقْتَضِي أَنْ يَكُونَ سُنَّةً أَوْ وَاجِبًا إِذْ لَمْ يُنْقَلْ عَنْهُ نَصٌّ فِي ذَلِكَ","src":"بداية المجتهد","loc":"١/١٤٣","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الطمأنينة ركن في كل ركن فعلي؛ لأن النبي ﷺ قال للمسيء صلاته: «ارجع فصل فإنك لم تصل»، ونفى عنه الصلاة وأمره بالإعادة، ثم علّمه الطمأنينة في كل ركن، ولقوله: «لا تجزئ صلاة الرجل حتى يقيم ظهره في الركوع والسجود». والطمأنينة أن يستقر كل عضو في موضعه بقدر ما يقول الذكر الواجب. وقد اتفق الحنفية مع الجمهور على وجوب الإعادة على من تركها، فالخلاف في التسمية أكثر منه في العمل. ومن صلى خلف إمام يسرع إسراعًا يُخلّ بالطمأنينة فلينصحه برفق."}],"refs":["البخاري ٧٥٧","أبو داود ٨٥٥","بداية المجتهد (١/١٤٣)","بداية المجتهد (١/١٤٣-١٤٤)"],"related":["السجود على الأعضاء السبعة، والسجود على حائل"],"alts":["الطمأنينة في الصلاة","نقر الصلاة","السرعة في الصلاة","المسيء صلاته"]},{"n":116,"bab":"الصلاة","sub":"صفة الصلاة","title":"وضع اليد اليمنى على اليسرى في القيام، وموضعهما","q":"هل يضع المصلي يده اليمنى على اليسرى؟ وأين يضعهما: على الصدر أم تحت السرة؟ وما حكم إرسال اليدين؟","short":"وضع اليمنى على اليسرى في القيام سنة عند جمهور العلماء ومنهم أبو حنيفة والشافعي وأحمد، وهو رواية عن مالك، والمشهور عن مالك الإرسال في الفريضة. واختلفوا في موضعهما: فتحت السرة عند أبي حنيفة وأحمد في رواية، وتحت الصدر فوق السرة عند الشافعي، وخيّر أحمد. والأمر في الموضع واسع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ النَّاسُ يُؤْمَرُونَ أَنْ يَضَعَ الرَّجُلُ الْيَدَ الْيُمْنَى عَلَى ذِرَاعِهِ الْيُسْرَى فِي الصَّلاَةِ. قَالَ أَبُو حَازِمٍ لاَ أَعْلَمُهُ إِلاَّ يَنْمِي ذَلِكَ إِلَى النَّبِيِّ صلى الله عليه وسلم","src":"رواه البخاري ٧٤٠","pre":"عن سهل بن سعد رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":740,"id":"h740"}]},{"t":"quote","text":"ثُمَّ الْتَحَفَ بِثَوْبِهِ، ثُمَّ وَضَعَ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ أَخْرَجَ يَدَيْهِ مِنَ الثَّوْبِ، ثُمَّ رَفَعَهُمَا، ثُمَّ كَبَّرَ فَرَكَعَ، فَلَمَّا قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ رَفَعَ يَدَيْهِ فَلَمَّا، سَجَدَ سَجَدَ بَيْنَ كَفَّيْهِ","src":"رواه مسلم ٤٠١","pre":"وعن وائل بن حجر رضي الله عنه أنه رأى النبي ﷺ رفع يديه حين دخل في الصلاة كبر:","links":[{"book":"mt_muslim","num":401,"id":"h401"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي وَضْعِ الْيَدَيْنِ إِحْدَاهُمَا عَلَى الْأُخْرَى فِي الصَّلَاةِ، فَكَرِهَ ذَلِكَ مَالِكٌ فِي الْفَرْضِ، وَأَجَازَهُ فِي النَّفْلِ. وَرَأَى قَوْمٌ أَنَّ هَذَا الْفِعْلَ مِنْ سُنَنِ الصَّلَاةِ وَهُمُ الْجُمْهُورُ.","src":"بداية المجتهد","loc":"١/١٤٦","pre":"قال ابن رشد:"},{"t":"quote","text":"خلافاً لمالك فإنه يقول بإرسال اليدين خلاف الثلاثة، ومذهب أبي حنيفة في وضع اليدين وضعهما تحت السرة، ومذهب الشافعي تحت الصدر فوق السرة، وخيّر أحمد في الوضع بأنه يضعهما حيث شاء من تحت الصدر أو عند الصدر أو تحت السرة، وكذلك خير ابن المنذر، وقال: لا نص في المسألة","src":"العرف الشذي","loc":"١/٢٦١","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وَفِي رِوَايَةٍ وَضْعُ الْيَمِينِ عَلَى الشِّمَالِ تَحْتَ السُّرَّةِ فِي الصَّلَاةِ","src":"بدائع الصنائع","loc":"١/٢٠١","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن السنة وضع اليد اليمنى على اليسرى في القيام؛ لحديث سهل بن سعد في البخاري ووائل بن حجر في مسلم، وهي هيئة خضوع واستكانة كما قال ابن رشد. وأما موضعهما فلم يثبت فيه نص صريح متفق على صحته، كما قال ابن المنذر ونقله الكشميري الحنفي، فمن وضعهما على صدره أو تحته أو تحت سرته فقد عمل بما ورد، ولا ينكر بعضهم على بعض. ومن أرسل يديه على مذهب مالك فصلاته صحيحة بالإجماع."}],"refs":["البخاري ٧٤٠","مسلم ٤٠١","بداية المجتهد (١/١٤٦)","العرف الشذي (١/٢٦١)","بدائع الصنائع (١/٢٠١)"],"related":["رفع اليدين عند الركوع والرفع منه"],"alts":["القبض في الصلاة","وضع اليدين على الصدر","تحت السرة","السدل"]},{"n":117,"bab":"الصلاة","sub":"صفة الصلاة","title":"هيئة الجلوس في الصلاة: الافتراش والتورك، والإشارة بالإصبع","q":"كيف أجلس في التشهد الأول والأخير؟ وهل أحرك السبابة أم أشير بها فقط؟","short":"اختلفوا في هيئة الجلوس: فيفترش في الجلستين عند أبي حنيفة، ويتورك فيهما عند مالك، ويفترش في الأول ويتورك في الأخير عند الشافعي وأحمد (وأحمد في الثنائية يفترش). وكل ذلك ثابت. ويضع يديه على فخذيه ويشير بالسبابة في التشهد بالاتفاق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَإِذَا جَلَسَ فِي الرَّكْعَتَيْنِ جَلَسَ عَلَى رِجْلِهِ الْيُسْرَى وَنَصَبَ الْيُمْنَى، وَإِذَا جَلَسَ فِي الرَّكْعَةِ الآخِرَةِ قَدَّمَ رِجْلَهُ الْيُسْرَى وَنَصَبَ الأُخْرَى وَقَعَدَ عَلَى مَقْعَدَتِهِ","src":"رواه البخاري ٨٢٨","pre":"عن أبي حميد الساعدي رضي الله عنه في صفة صلاة النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":828,"id":"h828"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْفُقَهَاءُ فِي هَيْئَةِ الْجُلُوسِ، فَقَالَ مَالِكٌ وَأَصْحَابُهُ يُفْضِي بِأَلْيَتَيْهِ إِلَى الْأَرْضِ، وَيَنْصُبُ رِجْلَهُ الْيُمْنَى وَيَثْنِي الْيُسْرَى، وَجُلُوسُ الْمَرْأَةِ عِنْدَهُ كَجُلُوسِ الرَّجُلِ. وَقَالَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ: يَنْصُبُ رجْلَه الْيُمْنَى وَيَقْعُدُ عَلَى الْيُسْرَى. وَفَرَّقَ الشَّافِعِيُّ بَيْنَ الْجَلْسَةِ الْوُسْطَى وَالْأَخِيرَةِ، فَقَالَ فِي الْوُسْطَى بِمِثْلِ قَوْلِ أَبِي حَنِيفَةَ، وَفِي الْأَخِيرَةِ بِمِثْلِ قَوْلِ مَالِكٍ","src":"بداية المجتهد","loc":"١/١٤٤","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر ما ذهب إليه الطبري واستحسنه ابن رشد: أن هذه الهيئات كلها ثابتة عن النبي ﷺ، والأكمل الجمع بينها على حديث أبي حميد: الافتراش في التشهد الأول، والتورك في التشهد الأخير من الصلاة ذات التشهدين؛ ومن افترش فيهما كما يقول الحنفية لحديث وائل فقد أصاب سنة. ويشير بالسبابة في التشهد، ويرفعها عند ذكر الله، والثابت الإشارة، والتحريك ورد في حديث وائل عند النسائي (٨٨٩): «فرأيته يحركها يدعو بها»، فمن حرّكها تحريكًا يسيرًا فلا حرج."}],"refs":["البخاري ٨٢٨","بداية المجتهد (١/١٤٤)","بداية المجتهد (١/١٤٤-١٤٥)","بداية المجتهد (١/١٤٦)"],"related":["جلسة الاستراحة، والنزول إلى السجود بالركبتين أو اليدين"],"alts":["التورك","الافتراش","تحريك السبابة","الجلوس في التشهد"]},{"n":118,"bab":"الصلاة","sub":"صفة الصلاة","title":"جلسة الاستراحة، والنزول إلى السجود بالركبتين أو اليدين","q":"هل يجلس المصلي جلسة خفيفة قبل القيام إلى الركعة الثانية والرابعة؟ وهل ينزل إلى السجود على ركبتيه أم على يديه؟","short":"جلسة الاستراحة سنة عند الشافعي، ولا تُسن عند أبي حنيفة ومالك وأحمد في المشهور إلا لحاجة. والنزول إلى السجود على الركبتين قبل اليدين قول الحنفية والشافعية والحنابلة، وعلى اليدين قبل الركبتين قول مالك والأوزاعي ورواية عن أحمد. والأمر في الجميع واسع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّهُ رَأَى النَّبِيَّ صلى الله عليه وسلم يُصَلِّي، فَإِذَا كَانَ فِي وِتْرٍ مِنْ صَلاَتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا","src":"رواه البخاري ٨٢٣","pre":"عن مالك بن الحويرث رضي الله عنه:","links":[{"book":"mt_bukhari","num":823,"id":"h823"}]},{"t":"quote","text":"رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم إِذَا سَجَدَ وَضَعَ رُكْبَتَيْهِ قَبْلَ يَدَيْهِ وَإِذَا نَهَضَ رَفَعَ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ","src":"رواه أبو داود ٨٣٨","pre":"وعن وائل بن حجر رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":838,"id":"h838"}]},{"t":"quote","text":"إِذَا سَجَدَ أَحَدُكُمْ فَلاَ يَبْرُكْ كَمَا يَبْرُكُ الْبَعِيرُ وَلْيَضَعْ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ","src":"رواه أبو داود ٨٤٠","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":840,"id":"h840"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَارَ قَوْمٌ إِذَا كَانَ الرَّجُلُ فِي وَتْرٍ مِنْ صَلَاتِهِ أَنْ لَا يَنْهَضَ حَتَّى يَسْتَوِيَ قَاعِدًا، وَاخْتَارَ آخَرُونَ أَنْ يَنْهَضَ مِنْ سُجُودِهِ نَفْسِهِ، وَبِالْأَوَّلِ قَالَ الشَّافِعِيُّ وَجَمَاعَةٌ، وَبِالثَّانِي قَالَ مَالِكٌ وَجَمَاعَةٌ.","src":"بداية المجتهد","loc":"١/١٤٦-١٤٧","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ويجلس جلسة خفيفة كالجلسة بين السجدتين، وتسمى جلسة الاستراحة، وهي مستحبة وإن تركها فلا حرج","src":"مجموع فتاوى ابن باز","loc":"١١/١٢","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"أما تقديم الركبتين قبل اليدين في السجود فهو الأفضل لحديث وائل بن حجر رضي الله عنه في ذلك وما جاء في معناه. وهو قول أكثر أهل العلم. وقال بعضهم: يقدم يديه قبل ركبتيه لما ورد في ذلك من حديث أبي هريرة رضي الله عنه، والأمر في هذا واسع سواء قدم ركبتيه أو قدم يديه فالصلاة صحيحة، وإنما الخلاف في الأفضل","src":"مجموع فتاوى ابن باز","loc":"١١/١٥١","pre":"وقال في النزول إلى السجود:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن جلسة الاستراحة ثابتة من فعله ﷺ في حديث مالك بن الحويرث، وقد حملها كثير من العلماء على حال الحاجة لكبر سنه ﷺ في آخر عمره، فمن فعلها فقد أصاب، ومن تركها فلا حرج، والإمام الذي لا يجلسها يتابعه المأموم. وأما النزول إلى السجود ففي المسألة حديثان متقابلان، تكلم أهل الحديث في كل منهما، فالأمر فيه واسع: فمن نزل على ركبتيه كما في حديث وائل، أو على يديه كما في حديث أبي هريرة، فقد عمل بحديث، والأرفق بالكبير والمريض ما تيسر له."}],"refs":["البخاري ٨٢٣","أبو داود ٨٣٨","أبو داود ٨٤٠","بداية المجتهد (١/١٤٦-١٤٧)","مجموع فتاوى ابن باز (١١/١٢)","مجموع فتاوى ابن باز (١١/١٥١)"],"related":["هيئة الجلوس في الصلاة: الافتراش والتورك، والإشارة بالإصبع"],"alts":["جلسة الاستراحة","النزول للسجود","تقديم الركبتين","تقديم اليدين"]},{"n":119,"bab":"الصلاة","sub":"صفة الصلاة","title":"السجود على الأعضاء السبعة، والسجود على حائل كالعمامة وطرف الثوب","q":"هل يجب أن يمس الأنف الأرض في السجود؟ وهل يصح السجود على العمامة أو القلنسوة أو طرف الثوب أو السجادة؟","short":"السجود على الأعضاء السبعة مأمور به: الجبهة مع الأنف، واليدين، والركبتين، وأطراف القدمين. والجبهة ركن عند الجمهور، وأجزأ عند أبي حنيفة السجود على الأنف وحده مع الكراهة، وأوجب أحمد في المشهور الأنف مع الجبهة. ويجوز السجود على السجادة والحصير بالاتفاق، وعلى كَور العمامة وطرف الثوب المتصل عند أبي حنيفة ومالك وأحمد، ومنعه الشافعي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ عَلَى الْجَبْهَةِ ـ وَأَشَارَ بِيَدِهِ عَلَى أَنْفِهِ ـ وَالْيَدَيْنِ، وَالرُّكْبَتَيْنِ وَأَطْرَافِ الْقَدَمَيْنِ، وَلاَ نَكْفِتَ الثِّيَابَ وَالشَّعَرَ","src":"رواه البخاري ٨١٢، ومسلم ٤٩٠","pre":"عن ابن عباس رضي الله عنهما قال: قال النبي ﷺ:","links":[{"book":"mt_bukhari","num":812,"id":"h812"},{"book":"mt_muslim","num":490,"id":"h490"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اتَّفَقَ الْعُلَمَاءُ عَلَى أَنَّ السُّجُودَ يَكُونُ عَلَى سَبْعَةِ أَعْضَاءٍ: الْوَجْهِ، وَالْيَدَيْنِ، وَالرُّكْبَتَيْنِ، وَأَطْرَافِ الْقَدَمَيْنِ، لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْضَاءٍ» ، وَاخْتَلَفُوا فِيمَنْ سَجَدَ عَلَى وَجْهِهِ وَنَقَصَهُ السُّجُودُ عَلَى عُضْوٍ مِنْ تِلْكَ الْأَعْضَاءِ هَلْ تَبْطُلُ صَلَاتُهُ أَمْ لَا؟","src":"بداية المجتهد","loc":"١/١٤٧","pre":"قال ابن رشد:"},{"t":"quote","text":"وَسَجَدَ عَلَى أَنْفِهِ وَجَبْهَتِهِ لِأَنَّ النَّبِيَّ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - وَاظَبَ عَلَيْهِ فَإِنْ اقْتَصَرَ عَلَى أَحَدِهِمَا جَازَ عِنْدَ أَبِي حَنِيفَةَ - رَحِمَهُ اللَّهُ -. وَقَالَا: لَا يَجُوزُ الِاقْتِصَارُ عَلَى الْأَنْفِ إلَّا مِنْ عُذْرٍ","src":"الهداية مع فتح القدير","loc":"١/٣٠٣","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الواجب السجود على الأعضاء السبعة كلها، وأن يمكّن جبهته وأنفه من الأرض؛ لأن النبي ﷺ أشار إلى أنفه لما ذكر الجبهة، فهما عضو واحد. ويجوز السجود على السجاد والفرش والحصير، وعلى طرف العمامة أو الثوب للحاجة كالحر والبرد، كما كان الصحابة يفعلون، والأولى مباشرة المصلى بالجبهة عند عدم الحاجة. ومن عجز عن السجود على بعض الأعضاء لمرض سجد على ما قدر عليه."}],"refs":["البخاري ٨١٢، ومسلم ٤٩٠","بداية المجتهد (١/١٤٧)","بداية المجتهد (١/١٤٨-١٤٩)","الهداية مع فتح القدير (١/٣٠٣)"],"related":["الطمأنينة والاعتدال في الركوع والسجود والرفع منهما"],"alts":["السجود على الأنف","السجود على العمامة","الأعضاء السبعة","السجود على السجادة"]},{"n":120,"bab":"الصلاة","sub":"صلاة الجماعة","title":"حكم صلاة الجماعة للرجال","q":"هل صلاة الجماعة في المسجد واجبة على الرجل، أم يجوز له أن يصلي في بيته بلا عذر؟","short":"صلاة الجماعة سنة مؤكدة عند أبي حنيفة ومالك وأكثر الشافعية، وعبّر الحنفية عنها بأنها واجبة أو سنة مؤكدة قريبة من الواجب يأثم بتركها بلا عذر، وهي فرض كفاية عند بعض الشافعية، وفرض عين على الرجال القادرين عند أحمد وأهل الظاهر، لا شرط لصحة الصلاة. والجميع متفقون على أن المحافظة عليها من آكد شعائر الإسلام.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلاَةُ الْجَمَاعَةِ تَفْضُلُ صَلاَةَ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً","src":"رواه البخاري ٦٤٥","pre":"عن عبد الله بن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":645,"id":"h645"}]},{"t":"quote","text":"أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ أَعْمَى، فَقَالَ: يَا رَسُولَ اللهِ، إِنَّهُ لَيْسَ لِي قَائِدٌ يَقُودُنِي إِلَى الْمَسْجِدِ، فَسَأَلَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُرَخِّصَ لَهُ، فَيُصَلِّيَ فِي بَيْتِهِ، فَرَخَّصَ لَهُ، فَلَمَّا وَلَّى، دَعَاهُ، فَقَالَ: «هَلْ تَسْمَعُ النِّدَاءَ بِالصَّلَاةِ؟» قَالَ: نَعَمْ، قَالَ: «فَأَجِبْ»","src":"رواه مسلم ٦٥٣","pre":"وعن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_muslim","num":653,"id":"h653"}]},{"t":"quote","text":"وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ هَمَمْتُ أَنْ آمُرَ بِحَطَبٍ فَيُحْطَبَ، ثُمَّ آمُرَ بِالصَّلاَةِ فَيُؤَذَّنَ لَهَا، ثُمَّ آمُرَ رَجُلاً فَيَؤُمَّ النَّاسَ، ثُمَّ أُخَالِفَ إِلَى رِجَالٍ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ","src":"رواه البخاري ٦٤٤","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":644,"id":"h644"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْمَسْأَلَةُ الأُولَى فَإِنَّ الْعُلَمَاءَ اخْتَلَفُوا فِيهَا، فَذَهَبَ الْجُمْهُورُ إِلَى أَنَّهَا سُنَّةٌ أَوْ فَرْضٌ عَلَى الْكِفَايَةِ. وَذَهَبَتِ الظَّاهِرِيَّةُ إِلَى أَنَّ صَلَاةَ الْجَمَاعَةِ فَرْضٌ مُتَعَيَّنٌ عَلَى كُلِّ مُكَلَّفٍ","src":"بداية المجتهد","loc":"١/١٥٠","pre":"قال ابن رشد:"},{"t":"quote","text":"بَقِيَ هُنَا شَيْءٌ، وَهُوَ أَنَّ صَلَاةَ الْجَمَاعَةِ وَاجِبَةٌ عَلَى الرَّاجِحِ فِي الْمَذْهَبِ أَوْ سُنَّةٌ مُؤَكَّدَةٌ فِي حُكْمِ الْوَاجِبِ","src":"الدر المختار مع رد المحتار","loc":"١/٤٥٧","pre":"وقال ابن عابدين الحنفي في «رد المحتار»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صلاة الجماعة اتفق العلماء على أنها من أجل الطاعات , وأوكدها , وأفضلها , وقد ذكرها الله تعالى في كتابه , وأمر بها حتى في صلاة الخوف","src":"مجموع فتاوى ابن عثيمين","loc":"١٥/١٧","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن حكم صلاة الجماعة، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة الجماعة واجبة على الرجال القادرين الذين يسمعون النداء، يأثم من تركها بلا عذر، وتصح صلاته منفردًا مع الإثم؛ لأن النبي ﷺ لم يرخص للأعمى الذي يسمع النداء، وهمّ بتحريق بيوت المتخلفين، ولا يُهَمّ بذلك على ترك سنة. وحديث التفضيل يدل على صحة صلاة المنفرد لا على جواز ترك الجماعة. وهذا قريب من قول الحنفية الذين جعلوها واجبة أو سنة مؤكدة لا يُترك إلا لعذر."},{"t":"tanbih","items":[{"t":"p","text":"من أعذار ترك الجماعة: المرض، والمطر الشديد والوحل، والبرد الشديد، والخوف على النفس أو المال، ومدافعة الأخبثين، وحضور الطعام والنفس تتوق إليه؛ فمن تركها لعذر وكان من عادته شهودها كُتب له أجرها إن شاء الله."}]}],"refs":["البخاري ٦٤٥","مسلم ٦٥٣","البخاري ٦٤٤","بداية المجتهد (١/١٥٠)","الدر المختار مع رد المحتار (١/٤٥٧)","مجموع فتاوى ابن عثيمين (١٥/١٧)"],"related":["من صلى ثم أدرك الجماعة: هل يعيد معهم؟","من أحق بالإمامة؟"],"alts":["الصلاة في البيت","وجوب الجماعة","التخلف عن الجماعة","أعذار ترك الجماعة"]},{"n":121,"bab":"الصلاة","sub":"صلاة الجماعة","title":"من صلى ثم أدرك الجماعة: هل يعيد معهم؟","q":"صليت الظهر في بيتي ثم ذهبت إلى المسجد فوجدتهم يصلون، فهل أصلي معهم؟ وهل تعاد المغرب والعصر؟","short":"يُشرع لمن صلى منفردًا ثم أدرك الجماعة أن يصلي معهم، وتكون الثانية نافلة. واستثنى مالك المغرب، واستثنى أبو حنيفة المغرب والعصر والفجر لأنها لا يُتنفل بعدها، وأجاز الشافعي وأحمد إعادة الكل، ويشفع أحمد المغرب بركعة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"شَهِدْتُ مَعَ النَّبِيِّ صلى الله عليه وسلم حَجَّتَهُ فَصَلَّيْتُ مَعَهُ صَلاَةَ الصُّبْحِ فِي مَسْجِدِ الْخَيْفِ . قَالَ فَلَمَّا قَضَى صَلاَتَهُ وَانْحَرَفَ إِذَا هُوَ بِرَجُلَيْنِ فِي أُخْرَى الْقَوْمِ لَمْ يُصَلِّيَا مَعَهُ فَقَالَ «عَلَىَّ بِهِمَا» . فَجِيءَ بِهِمَا تُرْعَدُ فَرَائِصُهُمَا فَقَالَ «مَا مَنَعَكُمَا أَنْ تُصَلِّيَا مَعَنَا» . فَقَالاَ يَا رَسُولَ اللَّهِ إِنَّا كُنَّا قَدْ صَلَّيْنَا فِي رِحَالِنَا . قَالَ فَلاَ تَفْعَلاَ إِذَا صَلَّيْتُمَا فِي رِحَالِكُمَا ثُمَّ أَتَيْتُمَا مَسْجِدَ جَمَاعَةٍ فَصَلِّيَا مَعَهُمْ فَإِنَّهَا لَكُمَا نَافِلَةٌ","src":"رواه الترمذي ٢١٩، والنسائي ٨٥٨","pre":"عن يزيد بن الأسود رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":219,"id":"h219"},{"book":"mt_nasai","num":858,"id":"h858"}]},{"t":"p","text":"قال الترمذي: حديث حسن صحيح."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الثَّانِيَةُ فَإِنَّ الَّذِي دَخَلَ الْمَسْجِدَ، وَقَدْ صَلَّى لَا يَخْلُو مِنْ أَحَدِ وَجْهَيْنِ: إِمَّا أَنْ يَكُونَ صَلَّى مُنْفَرِدًا، وَإِمَّا أَنْ يَكُونَ صَلَّى فِي جَمَاعَةٍ.","src":"بداية المجتهد","loc":"١/١٥٢","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من صلى ثم حضر الجماعة صلى معهم أي صلاة كانت، وتكون له نافلة؛ لعموم قوله ﷺ: «فصليا معهم فإنها لكما نافلة»، وكان ذلك في صلاة الصبح، وهي وقت نهي، فدل على أن النهي لا يتناول هذه الصلاة ذات السبب. وفي المغرب يتمها أربعًا بأن يأتي بركعة بعد سلام الإمام عند من رأى ذلك، أو يصليها معهم ثلاثًا؛ والأمر فيه واسع. والقصد من ذلك اجتماع الكلمة وألا يُظن به الرغبة عن الجماعة."}],"refs":["الترمذي ٢١٩، والنسائي ٨٥٨","بداية المجتهد (١/١٥٢)"],"related":["حكم صلاة الجماعة للرجال"],"alts":["إعادة الصلاة في جماعة","صليت في البيت ثم أقيمت الصلاة","الصلاة مرتين"]},{"n":122,"bab":"الصلاة","sub":"صلاة الجماعة","title":"من أحق بالإمامة؟ وإمامة الصبي والفاسق والمرأة","q":"من يُقدَّم للإمامة: الأحفظ للقرآن أم الأفقه؟ وهل تصح الصلاة خلف الصبي المميز، وخلف الفاسق، وهل تؤم المرأة النساء؟","short":"يُقدم الأقرأ عند أبي حنيفة وأحمد والثوري، والأفقه عند مالك والشافعي، مع اتفاقهم على تقديم صاحب البيت والإمام الراتب. وتصح إمامة الصبي المميز في النفل، وفي الفرض عند الشافعي، ومنعها الجمهور. وتصح الصلاة خلف الفاسق مع الكراهة عند الجمهور. ولا تؤم المرأة الرجال بالاتفاق، وتؤم النساء عند الشافعي وأحمد، وكرهه أبو حنيفة ومنعه مالك.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللهِ، فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً، فَأَعْلَمُهُمْ بِالسُّنَّةِ، فَإِنْ كَانُوا فِي السُّنَّةِ سَوَاءً، فَأَقْدَمُهُمْ هِجْرَةً، فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً، فَأَقْدَمُهُمْ سِلْمًا","src":"رواه مسلم ٦٧٣","pre":"عن أبي مسعود الأنصاري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":673,"id":"h673"}]},{"t":"quote","text":"فَقَدَّمُونِي بَيْنَ أَيْدِيهِمْ، وَأَنَا ابْنُ سِتٍّ أَوْ سَبْعِ، سِنِينَ","src":"رواه البخاري ٤٣٠٢","pre":"وعن عمرو بن سلمة رضي الله عنه في إمامته قومه:","links":[{"book":"mt_bukhari","num":4302,"id":"h4302"}]},{"t":"quote","text":"وَأَمَرَهَا أَنْ تَؤُمَّ أَهْلَ دَارِهَا","src":"رواه أبو داود ٥٩٢","pre":"وعن أم ورقة رضي الله عنها أن النبي ﷺ:","links":[{"book":"mt_abudawud","num":592,"id":"h592"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِيمَنْ أَوْلَى بِالْإِمَامَةِ، فَقَالَ مَالِكٌ: يَؤُمُّ الْقَوْمَ أَفْقَهُهُمْ لَا أَقْرَؤُهُمْ، وَبِهِ قَالَ الشَّافِعِيُّ، وَقَالَ أَبُو حَنِيفَةَ، وَالثَّوْرِيُّ، وَأَحْمَدُ: يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ.","src":"بداية المجتهد","loc":"١/١٥٣-١٥٤","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأحق بالإمامة الأقرأ لكتاب الله إذا كان عالمًا بأحكام الصلاة، ثم الأعلم بالسنة؛ لنص الحديث، وفي زماننا ينبغي أن يُجمع بين حسن القراءة والفقه. والإمام الراتب وصاحب البيت أحق من غيرهما إلا أن يأذنا. وتصح إمامة الصبي المميز الذي يحسن الصلاة؛ لحديث عمرو بن سلمة، والأولى تقديم البالغ. وتصح الصلاة خلف الفاسق الذي لا يُخل بشروط الصلاة، وقد صلى الصحابة خلف بعض أمراء الجور، لكن لا ينبغي توليته الإمامة الراتبة. وتؤم المرأة النساء وتقف وسطهن، كما فعلت عائشة وأم سلمة رضي الله عنهما، ولا تؤم الرجال."}],"refs":["مسلم ٦٧٣","البخاري ٤٣٠٢","أبو داود ٥٩٢","بداية المجتهد (١/١٥٣-١٥٤)","بداية المجتهد (١/١٥٤)","بداية المجتهد (١/١٥٥)"],"related":["موقف المأموم من الإمام، والصلاة خلف الصف منفردًا"],"alts":["الأحق بالإمامة","إمامة الصبي","الصلاة خلف الفاسق","إمامة المرأة للنساء"]},{"n":123,"bab":"الصلاة","sub":"صلاة الجماعة","title":"موقف المأموم من الإمام، والصلاة خلف الصف منفردًا","q":"أين يقف المأموم إذا كان واحدًا؟ وإذا جئت والصف تام فهل أصلي خلفه وحدي؟","short":"يقف المأموم الواحد عن يمين الإمام، والاثنان فأكثر خلفه، والمرأة خلف الرجال بالاتفاق. وتسوية الصفوف وإتمامها مشروعة بالإجماع. ومن صلى خلف الصف وحده بلا عذر صحت صلاته عند الجمهور مع الكراهة، وأبطلها أحمد وإسحاق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَ بِرَأْسِي فَأَقَامَنِي عَنْ يَمِينِهِ","src":"رواه البخاري ٦٩٩","pre":"عن ابن عباس رضي الله عنهما قال: بت عند خالتي، فقام النبي ﷺ يصلي من الليل،","links":[{"book":"mt_bukhari","num":699,"id":"h699"}]},{"t":"quote","text":"سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ إِقَامَةِ الصَّلاَةِ","src":"رواه البخاري ٧٢٣","pre":"وعن أنس رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":723,"id":"h723"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم رَأَى رَجُلاً يُصَلِّي خَلْفَ الصَّفِّ وَحْدَهُ فَأَمَرَهُ أَنْ يُعِيدَ","src":"رواه أبو داود ٦٨٢","pre":"وعن وابصة بن معبد رضي الله عنه:","links":[{"book":"mt_abudawud","num":682,"id":"h682"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَجْمَعَ الْعُلَمَاءُ عَلَى أَنَّ الصَّفَّ الْأَوَّلَ مُرَغَّبٌ فِيهِ، وَكَذَلِكَ تَرَاصُّ الصُّفُوفِ وَتَسْوِيَتُهَا لِثُبُوتِ الْأَمْرِ بِذَلِكَ عَنْ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَاخْتَلَفُوا إِذَا صَلَّى إِنْسَانٌ خَلْفَ الصَّفِّ وَحْدَهُ، فَالْجُمْهُورُ عَلَى أَنَّ صَلَاتَهُ تُجْزِي. وَقَالَ أَحْمَدُ، وَأَبُو ثَوْرٍ، وَجَمَاعَةٌ: صَلَاتُهُ فَاسِدَةٌ","src":"بداية المجتهد","loc":"١/١٥٩","pre":"قال ابن رشد:"},{"t":"quote","text":"فِي مَذَاهِبِ الْعُلَمَاءِ فِي صَلَاةِ الْمُنْفَرِدِ خَلْفَ الصَّفِّ: قَدْ ذَكَرْنَا أَنَّهَا صَحِيحَةٌ عِنْدَنَا مَعَ الْكَرَاهَةِ وَحَكَاهُ ابْنُ الْمُنْذِرِ عَنْ الْحَسَنِ الْبَصْرِيِّ وَمَالِكٍ وَالْأَوْزَاعِيِّ وَأَصْحَابِ الرَّأْيِ","src":"المجموع","loc":"٤/٢٩٨","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وصلاة المنفرد خلف الصف غير صحيحة؛ لقول النبي صلى الله عليه وسلم: «لا صلاة لمنفرد خلف الصف»","src":"فتاوى اللجنة الدائمة","loc":"٣/١٣١","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من جاء والصف تام فإنه يحاول الدخول في الصف إن وجد فرجة، أو يقف عن يمين الإمام إن أمكن، فإن لم يجد صلى خلف الصف وحده وصحت صلاته؛ لأن الواجبات تسقط بالعجز، ولحديث أبي بكرة الذي ركع دون الصف ولم يُؤمر بالإعادة. وأما من صلى خلف الصف منفردًا مع وجود فرجة في الصف فقد خالف الأمر، والأحوط له الإعادة لحديث وابصة. ولا يجذب أحدًا من الصف لضعف حديثه وما فيه من إفساد الصف."},{"t":"tanbih","items":[{"t":"p","text":"تسوية الصفوف: بإقامتها على خط واحد، والتراص فيها، وسد الفرج، وإتمام الأول فالأول، ومحاذاة المناكب والأقدام، وهو مما ينبغي للإمام أن يعتني به قبل التكبير."}]}],"refs":["البخاري ٦٩٩","البخاري ٧٢٣","أبو داود ٦٨٢","بداية المجتهد (١/١٥٩)","المجموع (٤/٢٩٨)","فتاوى اللجنة الدائمة (٣/١٣١)"],"related":["آداب المشي إلى الصلاة، والركوع دون الصف لإدراك الركعة"],"alts":["الصلاة خلف الصف","موقف المأموم الواحد","تسوية الصفوف","المرأة في الصف"]},{"n":124,"bab":"الصلاة","sub":"صلاة الجماعة","title":"آداب المشي إلى الصلاة، والركوع دون الصف لإدراك الركعة، وبم تُدرك الركعة؟","q":"إذا سمعت الإقامة فهل أسرع لإدراك الركعة؟ وإذا وجدت الإمام راكعًا فهل أركع قبل أن أصل إلى الصف؟ وهل أكون أدركت الركعة؟","short":"السنة أن يأتي إلى الصلاة بسكينة ووقار ولا يسرع، وهو قول فقهاء الأمصار. وأجاز مالك وجماعة الركوع دون الصف ثم الدبيب إليه لمن خاف فوت الركعة، وكرهه الشافعي، وفرّق أبو حنيفة بين الواحد والجماعة. ومن أدرك الإمام راكعًا فكبّر وركع واطمأن قبل رفعه فقد أدرك الركعة عند الأئمة الأربعة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا سَمِعْتُمُ الإِقَامَةَ فَامْشُوا إِلَى الصَّلاَةِ، وَعَلَيْكُمْ بِالسَّكِينَةِ وَالْوَقَارِ وَلاَ تُسْرِعُوا، فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا","src":"رواه البخاري ٦٣٦","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":636,"id":"h636"}]},{"t":"quote","text":"أَنَّهُ انْتَهَى إِلَى النَّبِيِّ صلى الله عليه وسلم وَهْوَ رَاكِعٌ، فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ، فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَقَالَ «زَادَكَ اللَّهُ حِرْصًا وَلاَ تَعُدْ»","src":"رواه البخاري ٧٨٣","pre":"وعن أبي بكرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":783,"id":"h783"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الصَّدْرُ الْأَوَّلُ فِي الرَّجُلِ يُرِيدُ الصَّلَاةَ فَيَسْمَعُ الْإِقَامَةَ هَلْ يُسْرِعُ الْمَشْيَ إِلَى الْمَسْجِدِ أَمْ لَا مَخَافَةَ أَنْ يَفُوتَهُ جُزْءٌ مِنَ الصَّلَاةِ؟","src":"بداية المجتهد","loc":"١/١٥٩-١٦٠","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن يمشي المصلي إلى الصلاة بسكينة ووقار ولو سمع الإقامة؛ للنهي الصريح عن الإسراع. ومن أدرك الإمام راكعًا كبّر للإحرام قائمًا ثم ركع، فإن اطمأن راكعًا قبل أن يرفع الإمام فقد أدرك الركعة؛ وهو قول جماهير العلماء. والأولى ألا يركع دون الصف ثم يمشي إليه؛ لقوله ﷺ لأبي بكرة: «ولا تعد»، ومن فعل ذلك فصلاته صحيحة."}],"refs":["البخاري ٦٣٦","البخاري ٧٨٣","بداية المجتهد (١/١٥٩-١٦٠)","بداية المجتهد (١/١٦٠)"],"related":["موقف المأموم من الإمام، والصلاة خلف الصف منفردًا"],"alts":["الإسراع إلى الصلاة","إدراك الركعة بالركوع","الركوع قبل الصف","المسبوق"]},{"n":125,"bab":"الصلاة","sub":"صلاة الجماعة","title":"متابعة الإمام: التسميع والتحميد، ومسابقة الإمام","q":"هل يقول المأموم «سمع الله لمن حمده» أم «ربنا ولك الحمد» فقط؟ وما حكم من يرفع رأسه أو يسجد قبل الإمام؟","short":"يقول الإمام «سمع الله لمن حمده»، ويقول المأموم «ربنا ولك الحمد» فقط عند أبي حنيفة ومالك وأحمد، ويجمع بينهما الإمام والمأموم عند الشافعي، ويجمع الإمام بينهما عند الصاحبين والشافعي وأحمد. ومسابقة الإمام محرمة بالاتفاق، وتبطل بها الصلاة عند بعض العلماء إن تعمّدها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّمَا جُعِلَ الإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، فَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فَارْفَعُوا، وَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. فَقُولُوا رَبَّنَا وَلَكَ الْحَمْدُ. وَإِذَا صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعُونَ","src":"رواه البخاري ٦٨٩","pre":"عن أنس رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":689,"id":"h689"}]},{"t":"quote","text":"أَمَا يَخْشَى الَّذِي يَرْفَعُ رَأْسَهُ قَبْلَ الْإِمَامِ، أَنْ يُحَوِّلَ اللهُ رَأْسَهُ رَأْسَ حِمَارٍ","src":"رواه مسلم ٤٢٧","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":427,"id":"h427"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا اخْتِلَافُهُمْ فِي قَوْلِهِ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، فَإِنَّ طَائِفَةً ذَهَبَتْ إِلَى أَنَّ الْإِمَامَ يَقُولُ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقَطْ، وَيَقُولُ الْمَأْمُومُ: رَبَّنَا وَلَكَ الْحَمْدُ فَقَطْ، وَمِمَّنْ قَالَ بِهَذَا الْقَوْلِ مَالِكٌ وَأَبُو حَنِيفَةَ وَغَيْرُهُمَا.","src":"بداية المجتهد","loc":"١/١٦٠","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الإمام يجمع بين التسميع والتحميد؛ لحديث ابن عمر، وأن المأموم يقول «ربنا ولك الحمد» فقط؛ لقوله ﷺ: «وإذا قال سمع الله لمن حمده فقولوا ربنا ولك الحمد»، ومن جمع بينهما من المأمومين على قول الشافعي فلا حرج. والواجب على المأموم أن يتابع إمامه فيأتي بأفعاله بعده مباشرة، لا يسابقه ولا يوافقه ولا يتأخر عنه كثيرًا؛ فإن سبقه عمدًا فقد عرّض نفسه لوعيد شديد، وعليه أن يرجع فيأتي بذلك بعده."}],"refs":["البخاري ٦٨٩","مسلم ٤٢٧","بداية المجتهد (١/١٦٠)","بداية المجتهد (١/١٦١)","بداية المجتهد (١/١٦٣)"],"related":["صلاة القائم خلف الإمام القاعد"],"alts":["سمع الله لمن حمده للمأموم","مسابقة الإمام","متابعة الإمام"]},{"n":126,"bab":"الصلاة","sub":"صلاة الجماعة","title":"صلاة القائم خلف الإمام القاعد","q":"إمامنا مريض يصلي جالسًا، فهل نصلي خلفه قيامًا أم جلوسًا؟","short":"تصح إمامة القاعد للمرض عند الجمهور، ويصلي المأمومون خلفه قيامًا عند أبي حنيفة والشافعي وجماعة فقهاء الأمصار، وقعودًا عند أحمد وإسحاق إذا ابتدأ الصلاة قاعدًا، ومنع مالك في المشهور إمامة القاعد.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَمَّا ثَقُلَ رَسُولُ اللَّهِ صلى الله عليه وسلم جَاءَ بِلاَلٌ يُؤْذِنُهُ بِالصَّلاَةِ فَقَالَ «مُرُوا أَبَا بَكْرٍ أَنْ يُصَلِّيَ بِالنَّاسِ». فَقُلْتُ يَا رَسُولَ اللَّهِ، إِنَّ أَبَا بَكْرٍ رَجُلٌ أَسِيفٌ، وَإِنَّهُ مَتَى مَا يَقُمْ مَقَامَكَ لاَ يُسْمِعُ النَّاسَ، فَلَوْ أَمَرْتَ عُمَرَ. فَقَالَ «مُرُوا أَبَا بَكْرٍ يُصَلِّي بِالنَّاسِ». فَقُلْتُ لِحَفْصَةَ قُولِي لَهُ إِنَّ أَبَا بَكْرٍ رَجُلٌ أَسِيفٌ، وَإِنَّهُ مَتَى يَقُمْ مَقَامَكَ لاَ يُسْمِعِ النَّاسَ، فَلَوْ أَمَرْتَ عُمَرَ. قَالَ «إِنَّكُنَّ لأَنْتُنَّ صَوَاحِبُ يُوسُفَ، مُرُوا أَبَا بَكْرٍ أَنْ يُصَلِّيَ بِالنَّاسِ». فَلَمَّا دَخَلَ فِي الصَّلاَةِ وَجَدَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي نَفْسِهِ خِفَّةً، فَقَامَ يُهَادَى بَيْنَ رَجُلَيْنِ، وَرِجْلاَهُ يَخُطَّانِ فِي الأَرْضِ حَتَّى دَخَلَ الْمَسْجِدَ، فَلَمَّا سَمِعَ أَبُو بَكْرٍ حِسَّهُ ذَهَبَ أَبُو بَكْرٍ يَتَأَخَّرُ، فَأَوْمَأَ إِلَيْهِ رَسُولُ اللَّهِ صلى الله عليه وسلم، فَجَاءَ رَسُولُ اللَّهِ صلى الله عليه وسلم حَتَّى جَلَسَ عَنْ يَسَارِ أَبِي بَكْرٍ، فَكَانَ أَبُو بَكْرٍ يُصَلِّي قَائِمًا، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي قَاعِدًا، يَقْتَدِي أَبُو بَكْرٍ بِصَلاَةِ رَسُولِ اللَّهِ صلى الله عليه وسلم وَالنَّاسُ مُقْتَدُونَ بِصَلاَةِ أَبِي بَكْرٍ رضى الله عنه","src":"رواه البخاري ٧١٣","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":713,"id":"h713"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا إِذَا كَانَ الْمَأْمُومُ صَحِيحًا، فَصَلَّى خَلْفَ إِمَامٍ مَرِيضٍ يُصَلِّي قَاعِدًا عَلَى ثَلَاثَةِ أَقْوَالٍ: أَحَدُهَا: أَنَّ الْمَأْمُومَ يُصَلِّي خَلْفَهُ قَاعِدًا، وَمِمَّنْ قَالَ بِهَذَا الْقَوْلِ أَحْمَدُ، وَإِسْحَاقُ، وَالْقَوْلُ الثَّانِي: أَنَّهُمْ يُصَلُّونَ خَلْفَهُ قِيَامًا.","src":"بداية المجتهد","loc":"١/١٦١-١٦٢","pre":"قال ابن رشد:"},{"t":"quote","text":"وَيُصَلِّي الْقَائِمُ خَلْفَ الْقَاعِدِ وَقَالَ مُحَمَّدٌ - رَحِمَهُ اللَّهُ -: لَا يَجُوزُ، وَهُوَ الْقِيَاسُ لِقُوَّةِ حَالِ الْقَائِمِ وَنَحْنُ تَرَكْنَاهُ بِالنَّصِّ","src":"الهداية مع فتح القدير","loc":"١/٣٦٨","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المأمومين يصلون خلف الإمام القاعد قيامًا إذا قدروا؛ لأن آخر الأمرين من رسول الله ﷺ في مرض موته أنه صلى قاعدًا والناس خلفه قيام، فيكون ناسخًا لأمره المتقدم بالجلوس، وهو قول أبي حنيفة والشافعي. ومن جمع بين الحديثين كأحمد فقال: إن ابتدأ الإمام الصلاة قاعدًا صلوا قعودًا، وإن ابتدأها قائمًا ثم اعتلّ صلوا قيامًا، فقوله وجيه. والأولى ألا يؤم المريض العاجز عن القيام إذا وُجد من يقوم مقامه."}],"refs":["البخاري ٧١٣","بداية المجتهد (١/١٦١-١٦٢)","الهداية مع فتح القدير (١/٣٦٨)","بداية المجتهد (١/١٦٢)"],"related":["متابعة الإمام: التسميع والتحميد، ومسابقة الإمام"],"alts":["إمامة الجالس","الصلاة خلف إمام مريض"]},{"n":127,"bab":"الصلاة","sub":"صلاة الجماعة","title":"القراءة خلف الإمام","q":"هل يقرأ المأموم الفاتحة خلف الإمام في الصلاة الجهرية والسرية؟","short":"للعلماء في المسألة أقوال: لا يقرأ المأموم خلف الإمام شيئًا لا في السرية ولا في الجهرية عند أبي حنيفة وأصحابه؛ ويقرأ في السرية دون الجهرية عند مالك وأحمد، ويقرأ إذا لم يسمع قراءة الإمام عند أحمد؛ ويقرأ الفاتحة في كل صلاة عند الشافعي في الجديد. وكلٌّ له أدلة معتبرة، والراجح أن المأموم يقرأ الفاتحة في السرية والجهرية، ويقرؤها في الجهرية سرًّا في سكتات الإمام أو معه.","body":[{"t":"h","text":"الدليل"},{"t":"aya","text":"وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ","ref":"الأعراف: ٢٠٤"},{"t":"quote","text":"صَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم الصُّبْحَ فَثَقُلَتْ عَلَيْهِ الْقِرَاءَةُ فَلَمَّا انْصَرَفَ قَالَ «إِنِّي أَرَاكُمْ تَقْرَءُونَ وَرَاءَ إِمَامِكُمْ» . قَالَ قُلْنَا يَا رَسُولَ اللَّهِ إِي وَاللَّهِ . قَالَ «فَلاَ تَفْعَلُوا إِلاَّ بِأُمِّ الْقُرْآنِ فَإِنَّهُ لاَ صَلاَةَ لِمَنْ لَمْ يَقْرَأْ بِهَا»","src":"رواه الترمذي ٣١١","pre":"عن عبادة بن الصامت رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":311,"id":"h311"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم انْصَرَفَ مِنْ صَلاَةٍ جَهَرَ فِيهَا بِالْقِرَاءَةِ فَقَالَ «هَلْ قَرَأَ مَعِي أَحَدٌ مِنْكُمْ آنِفًا» . فَقَالَ رَجُلٌ نَعَمْ يَا رَسُولَ اللَّهِ . قَالَ «إِنِّي أَقُولُ مَا لِي أُنَازَعُ الْقُرْآنَ» . قَالَ فَانْتَهَى النَّاسُ عَنِ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِيمَا جَهَرَ فِيهِ النَّبِيُّ صلى الله عليه وسلم بِالْقِرَاءَةِ مِنَ الصَّلَوَاتِ حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم","src":"رواه أبو داود ٨٢٦، والترمذي ٣١٢","pre":"وعن أبي هريرة رضي الله عنه:","links":[{"book":"mt_abudawud","num":826,"id":"h826"},{"book":"mt_tirmidhi","num":312,"id":"h312"}]},{"t":"quote","text":"وَإِذَا قَرَأَ فَأَنْصِتُوا","src":"رواه مسلم ٤٠٤","pre":"وعن أبي موسى رضي الله عنه في حديث تعليم الصلاة:","links":[{"book":"mt_muslim","num":404,"id":"h404-2"}]},{"t":"p","text":"وصححه الإمام مسلم، وقال: هو عندي صحيح."},{"t":"quote","text":"مَنْ كَانَ لَهُ إِمَامٌ فَإِنَّ قِرَاءَةَ الإِمَامِ لَهُ قِرَاءَةٌ","src":"رواه ابن ماجه ٨٥٠","pre":"وعن جابر رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_ibnmajah","num":850,"id":"h850"}]},{"t":"p","text":"وفي إسناده كلام عند المحدثين، وقواه جماعة من علماء الحنفية بمجموع طرقه وبآثار الصحابة رضي الله عنهم."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّهُ لَا يَحْمِلُ الْإِمَامُ عَنِ الْمَأْمُومِ شَيْئًا مِنْ فَرَائِضِ الصَّلَاةِ مَا عَدَا الْقِرَاءَةَ، فَإِنَّهُمُ اخْتَلَفُوا فِي ذَلِكَ عَلَى ثَلَاثَةِ أَقْوَالٍ: أَحَدُهَا: أَنَّ الْمَأْمُومَ يَقْرَأُ مَعَ الْإِمَامِ فِيمَا أَسَرَّ فِيهِ وَلَا يَقْرَأُ مَعَهُ فِيمَا جَهَرَ بِهِ. وَالثَّانِي: أَنَّهُ لَا يَقْرَأُ مَعَهُ أَصْلًا.","src":"بداية المجتهد","loc":"١/١٦٤","pre":"قال ابن رشد:"},{"t":"quote","text":"والمسألة الثانية: قراءة الفاتحة خلف الإمام، والمذكورة هاهنا الأولى، وأما الثانية فمذهب أبي حنيفة وأحمد ومالك والجمهور نفي القراءة خلف الإمام في الجهرية، واختلفوا في السرية، قيل: سنة، وقيل: مستحبة، وقيل: مباحة، وقال الشافعي بوجوبها في السرية والجهرية، وكان قول الشافعي: القديم عدم وجوبها في الجهرية، وقوله الجديد وجوبها كما قال المزني في مختصره","src":"العرف الشذي","loc":"١/٢٥٤","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وَلَا يَقْرَأُ الْمُؤْتَمُّ خَلْفَ الْإِمَامِ خِلَافًا لِلشَّافِعِيِّ - رَحِمَهُ اللَّهُ - فِي الْفَاتِحَةِ. لَهُ أَنَّ الْقِرَاءَةَ رُكْنٌ مِنْ الْأَرْكَانِ فَيَشْتَرِكَانِ فِيهِ. وَلَنَا قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - «مَنْ كَانَ لَهُ إمَامٌ فَقِرَاءَةُ الْإِمَامِ لَهُ قِرَاءَةٌ»","src":"الهداية مع فتح القدير","loc":"١/٣٣٨","pre":"وقال في «الهداية» من كتب الحنفية:"},{"t":"quote","text":"مَسْأَلَةٌ: قَالَ: وَالْمَأْمُومُ إذَا سَمِعَ قِرَاءَةَ الْإِمَامِ فَلَا يَقْرَأُ بِالْحَمْدِ، وَلَا بِغَيْرِهَا، لِقَوْلِ اللَّهِ تَعَالَى: {وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ} الأعراف: 204 . وَلِمَا رَوَى أَبُو هُرَيْرَةَ - رَضِيَ اللَّهُ عَنْهُ - «أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: مَا لِي أُنَازَعُ الْقُرْآنَ؟ ، قَالَ: فَانْتَهَى النَّاسُ أَنْ يَقْرَءُوا فِيمَا جَهَرَ فِيهِ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -»","src":"المغني","loc":"١/٤٠٣","pre":"وقال ابن قدامة الحنبلي في «المغني»:"},{"t":"quote","text":"فِي مَذَاهِبِ الْعُلَمَاءِ فِي قِرَاءَةِ الْمَأْمُومِ خَلْفَ الْإِمَامِ: قَدْ ذَكَرْنَا أَنَّ مَذْهَبَنَا وُجُوبُ قِرَاءَةِ الْفَاتِحَةِ عَلَى الْمَأْمُومِ فِي كُلِّ الرَّكَعَاتِ مِنْ الصَّلَاةِ السِّرِّيَّةِ والجهرية وهذا هُوَ الصَّحِيحُ عِنْدَنَا كَمَا سَبَقَ وَبِهِ قَالَ أَكْثَرُ الْعُلَمَاءِ","src":"المجموع","loc":"٣/٣٦٥","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والمأموم يقرأ الفاتحة في سكتات إمامه، فإن لم يكن له سكتة قرأ المأموم الفاتحة ولو في حالة قراءة الإمام، ثم ينصت للإمام","src":"مجموع فتاوى ابن باز","loc":"١١/٨٤","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"والذي يظهر لي من الأدلة أن قراءة الإمام لا تسقط القراءة عن المأموم لا في السرية ولا في الجهرية، وأن الواجب على المأموم أن يقرأ الفاتحة في الصلاة السرية والجهرية، لعموم الأدلة الدالة على ذلك التي ذكرناها آنفاً","src":"مجموع فتاوى ابن عثيمين","loc":"١٢/٤٩٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"الواجب أن يقرأ المأموم الفاتحة سواء قرأها والإمام يقرأ الفاتحة جهرا أوفي قراءة الإمام السورة، أو وقت سكتة الإمام، إن سكت بين الفاتحة والسورة، والأمر في ذلك واسع والأفضل قراءتها في السكتة إن سكت الإمام، جمعا بين الأدلة","src":"فتاوى اللجنة الدائمة","loc":"٦/٤١٣","pre":"وجاء في فتاوى اللجنة الدائمة للبحوث العلمية والإفتاء:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"المسألة من أشهر مسائل الخلاف وأدقها، ولكل قول أدلة معتبرة: فالقائلون بالإنصات يستدلون بآية الأعراف المذكورة في الأمر بالاستماع والإنصات، وقد نزلت في الصلاة، وبحديث «وإذا قرأ فأنصتوا» الذي صححه مسلم، وبانتهاء الناس عن القراءة فيما جهر فيه النبي ﷺ؛ والقائلون بالقراءة يستدلون بحديث عبادة: «فلا تفعلوا إلا بأم القرآن فإنه لا صلاة لمن لم يقرأ بها»."},{"t":"p","text":"والراجح، والله أعلم، أن المأموم يقرأ الفاتحة في الصلاة السرية والجهرية جميعًا؛ لعموم قوله ﷺ: «لا صلاة لمن لم يقرأ بفاتحة الكتاب»، ولحديث عبادة رضي الله عنه، فإنه ورد في صلاة جهرية، ونهاهم فيه عن القراءة خلف الإمام إلا بأم القرآن، فخص الفاتحة من عموم الإنصات. ويقرؤها في الجهرية سرًّا في سكتات الإمام إن سكت، وإلا قرأها معه سرًّا بحيث لا ينازعه، ثم ينصت لما زاد عليها. وهذا قول الشافعي في الجديد وجماعة من أهل الحديث، وفيه جمع بين حديث عبادة وآية الإنصات وحديث «وإذا قرأ فأنصتوا» بحمل الإنصات على ما عدا الفاتحة."},{"t":"p","text":"ومن أخذ بقول الحنفية فأنصت في الجهرية والسرية، أو بقول مالك وأحمد فقرأ في السرية وأنصت في الجهرية، فصلاته صحيحة، وله سلف من أئمة الهدى وأدلة معتبرة، ولا يُنكر عليه؛ فالمسألة اجتهادية والأدلة فيها متجاذبة، وكل الأئمة رحمهم الله قصدوا اتباع السنة."}],"refs":["الترمذي ٣١١","أبو داود ٨٢٦، والترمذي ٣١٢","مسلم ٤٠٤","ابن ماجه ٨٥٠","بداية المجتهد (١/١٦٤)","العرف الشذي (١/٢٥٤)","الهداية مع فتح القدير (١/٣٣٨)","المغني (١/٤٠٣)","المجموع (٣/٣٦٥)","مجموع فتاوى ابن باز (١١/٨٤)","مجموع فتاوى ابن عثيمين (١٢/٤٩٦)","فتاوى اللجنة الدائمة (٦/٤١٣)","بداية المجتهد (١/١٦٤-١٦٥)"],"related":["قراءة الفاتحة في الصلاة"],"alts":["قراءة الفاتحة خلف الإمام","الإنصات للإمام","القراءة في الجهرية للمأموم"]},{"n":128,"bab":"الصلاة","sub":"صلاة الجماعة","title":"التأمين: هل يقوله الإمام؟ وهل يُجهر به؟","q":"هل يقول الإمام «آمين» بعد الفاتحة؟ وهل يجهر بها الإمام والمأمومون أم يسرّون؟","short":"يؤمّن الإمام والمأموم والمنفرد عند الجمهور، ولا يؤمن الإمام في رواية ابن القاسم عن مالك. ويجهر بالتأمين الإمام والمأموم في الجهرية عند الشافعي وأحمد، ويسرّ به عند أبي حنيفة ومالك. وكلا الأمرين مأثور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا أَمَّنَ الإِمَامُ فَأَمِّنُوا فَإِنَّهُ مَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلاَئِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","src":"رواه البخاري ٧٨٠، ومسلم ٤١٠","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":780,"id":"h780"},{"book":"mt_muslim","num":410,"id":"h410"}]},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِذَا قَرَأَ { وَلاَ الضَّالِّينَ } قَالَ «آمِينَ» . وَرَفَعَ بِهَا صَوْتَهُ","src":"رواه أبو داود ٩٣٢","pre":"وعن وائل بن حجر رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":932,"id":"h932"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا هَلْ يُؤَمِّنُ الْإِمَامُ إِذَا فَرَغَ مِنْ قِرَاءَةِ أُمِّ الْكِتَابِ، فَإِنَّ مَالِكًا ذَهَبَ فِي رِوَايَةِ ابْنِ الْقَاسِمِ عَنْهُ، وَالْمِصْرِيِّينَ أَنَّهُ لَا يُؤَمِّنُ، وَذَهَبَ جُمْهُورُ الْفُقَهَاءِ إِلَى أَنَّهُ يُؤَمِّنُ كَالْمَأْمُومِ سَوَاءً، وَهِيَ رِوَايَةُ الْمَدَنِيِّينَ عَنْ مَالِكٍ","src":"بداية المجتهد","loc":"١/١٥٥","pre":"قال ابن رشد:"},{"t":"quote","text":"وَقَالَ مَالِكٌ: إذَا فَرَغَ الْإِمَامُ مِنْ قِرَاءَةِ أُمِّ الْقُرْآنِ فَلَا يَقُلْ هُوَ آمِينَ وَلَكِنْ يَقُولُ ذَلِكَ مَنْ خَلْفَهُ","src":"المدونة","loc":"١/١٦٧","pre":"وفي «المدونة» عن الإمام مالك:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الإمام يؤمّن؛ لقوله ﷺ: «إذا أمّن الإمام فأمّنوا»، وأن الجهر بالتأمين في الصلاة الجهرية سنة للإمام والمأموم؛ لحديث وائل بن حجر «ورفع بها صوته». وقد روى بعض الرواة في حديث وائل «وخفض بها صوته»، وأخذ به الحنفية ومن وافقهم، فمن أسرّ بها فقد عمل بما روي، ولا ينبغي التنازع في ذلك، ولا الإنكار على من جهر أو أسر."}],"refs":["البخاري ٧٨٠، ومسلم ٤١٠","أبو داود ٩٣٢","بداية المجتهد (١/١٥٥)","بداية المجتهد (١/١٥٦)","المدونة (١/١٦٧)"],"related":["القراءة خلف الإمام"],"alts":["الجهر بآمين","تأمين الإمام","آمين في الصلاة"]},{"n":129,"bab":"الصلاة","sub":"صلاة الجماعة","title":"من صلى خلف إمام تبيّن بعد الصلاة أنه كان محدثًا أو جنبًا","q":"صلى بنا الإمام ثم أخبرنا بعد الصلاة أنه كان على غير وضوء ناسيًا، فهل نعيد الصلاة؟","short":"إذا لم يعلم المأمومون بحدث الإمام حتى فرغوا فصلاتهم صحيحة عند الشافعي وأحمد ومالك (إذا كان الإمام ناسيًا عند مالك)، ويعيد الإمام وحده؛ وتبطل صلاتهم عند أبي حنيفة لارتباط صلاة المأموم بصلاة الإمام.","body":[{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّهُ إِذَا طَرَأَ عَلَيْهِ الْحَدَثُ فِي الصَّلَاةِ فَقَطَعَ أَنَّ صَلَاةَ الْمَأْمُومِينَ لَيْسَتْ تَفْسُدُ.","src":"بداية المجتهد","loc":"١/١٦٦","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة المأمومين صحيحة إذا لم يعلموا بحدث إمامهم إلا بعد الفراغ، وعلى الإمام أن يعيد صلاته؛ لأن المأموم أدّى ما عليه ولا تكليف عليه فيما غاب عنه، وقد صح عن عمر رضي الله عنه أنه صلى بالناس وهو جنب فأعاد ولم يأمر الناس بالإعادة، وكذا عن عثمان رضي الله عنه. وإن علم الإمام بحدثه في أثناء الصلاة انصرف واستخلف من يتم بهم، ولا يستمر في الصلاة وهو محدث."}],"refs":["بداية المجتهد (١/١٦٦)"],"related":["متابعة الإمام: التسميع والتحميد، ومسابقة الإمام"],"alts":["الإمام على غير وضوء","إعادة الصلاة خلف المحدث","استخلاف الإمام"]},{"n":130,"bab":"الصلاة","sub":"صلاة الجمعة","title":"حكم صلاة الجمعة، ومن تجب عليه","q":"هل الجمعة فرض على كل مسلم؟ وهل تجب على المرأة والمسافر والمريض والطالب المقيم مؤقتًا؟","short":"الجمعة فرض عين على كل مسلم ذكر بالغ عاقل حر مقيم غير معذور، بإجماع الأئمة الأربعة. ولا تجب على المرأة والصبي والمريض والمسافر بالاتفاق إلا عند أهل الظاهر في المسافر، ومن حضرها منهم أجزأته عن الظهر. والمقيم مدة طويلة للدراسة أو العمل تلزمه الجمعة.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ","ref":"الجمعة: ٩"},{"t":"quote","text":"لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ وَدْعِهِمُ الْجُمُعَاتِ، أَوْ لَيَخْتِمَنَّ اللهُ عَلَى قُلُوبِهِمْ، ثُمَّ لَيَكُونُنَّ مِنَ الْغَافِلِينَ","src":"رواه مسلم ٨٦٥","pre":"عن عبد الله بن عمر وأبي هريرة رضي الله عنهم أنهما سمعا رسول الله ﷺ يقول على أعواد منبره:","links":[{"book":"mt_muslim","num":865,"id":"h865"}]},{"t":"quote","text":"الْجُمُعَةُ حَقٌّ وَاجِبٌ عَلَى كُلِّ مُسْلِمٍ فِي جَمَاعَةٍ إِلاَّ أَرْبَعَةً عَبْدٌ مَمْلُوكٌ أَوِ امْرَأَةٌ أَوْ صَبِيٌّ أَوْ مَرِيضٌ","src":"رواه أبو داود ١٠٦٧","pre":"وعن طارق بن شهاب رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":1067,"id":"h1067"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"صلاة الجمعة فرض عين على كل مسلم ذكر حر بالغ عاقل مقيم لا عذر له، وهو قول جمهور العلماء ومنهم الأئمة الأربعة؛ لأمر الله تعالى بالسعي إليها في سورة الجمعة، ولوعيد النبي ﷺ لمن تركها."},{"t":"qawl","label":"القول الثاني","text":"هي فرض كفاية، وهو قول قليل من أهل العلم، وعن مالك رواية شاذة أنها سنة، والصواب ما عليه الجمهور."},{"t":"quote","text":"وَلَا تَجِبُ الْجُمُعَةُ عَلَى مُسَافِرٍ وَلَا امْرَأَةٍ وَلَا مَرِيضٍ وَلَا عَبْدٍ وَلَا أَعْمَى ؛ لِأَنَّ الْمُسَافِرَ يَخْرُجُ فِي الْحُضُورِ، وَكَذَا الْمَرِيضُ وَالْأَعْمَى، وَالْعَبْدُ مَشْغُولٌ بِخِدْمَةِ الْمَوْلَى، وَالْمَرْأَةُ بِخِدْمَةِ الزَّوْجِ فَعُذِرُوا","src":"الهداية مع فتح القدير","loc":"٢/٦٢","pre":"جاء في «الهداية» للمرغيناني الحنفي فيمن لا تجب عليه:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الجمعة فرض عين على الرجال المقيمين القادرين؛ لقوله تعالى: ﴿فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ﴾، وللوعيد الشديد على تاركها. ولا تجب على المرأة والمسافر والمريض والصبي، فإن حضروها صحت منهم وأجزأتهم عن الظهر. ومن أقام في بلد للدراسة أو العمل مدة طويلة فهو في حكم المقيم تلزمه الجمعة، ومن تركها لغير عذر صلى الظهر أربعًا وهو آثم."},{"t":"tanbih","items":[{"t":"p","text":"من فاتته الجمعة صلى الظهر أربعًا، ولا يصلي الجمعة منفردًا بالإجماع."}]}],"refs":["مسلم ٨٦٥","أبو داود ١٠٦٧","الهداية مع فتح القدير (٢/٦٢)"],"related":["شروط صحة الجمعة: العدد والمكان والإذن"],"alts":["فرضية الجمعة","الجمعة للمرأة","الجمعة للمسافر","ترك الجمعة"]},{"n":131,"bab":"الصلاة","sub":"صلاة الجمعة","title":"وقت الجمعة، والأذان الأول والثاني لها","q":"هل يجوز أن تصلى الجمعة قبل الزوال؟ وما حكم الأذان الأول يوم الجمعة؟","short":"وقت الجمعة وقت الظهر عند الجمهور (أبي حنيفة ومالك والشافعي)، فلا تصح قبل الزوال، وأجازها أحمد قبل الزوال بقليل. والأذان الذي كان على عهد النبي ﷺ واحد إذا جلس الإمام على المنبر، وزاد عثمان رضي الله عنه أذانًا قبله لما كثر الناس، وعليه عمل أكثر المسلمين.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يُصَلِّي الْجُمُعَةَ حِينَ تَمِيلُ الشَّمْسُ","src":"رواه البخاري ٩٠٤","pre":"عن أنس بن مالك رضي الله عنه:","links":[{"book":"mt_bukhari","num":904,"id":"h904"}]},{"t":"quote","text":"مَا كُنَّا نَقِيلُ وَلاَ نَتَغَدَّى إِلاَّ بَعْدَ الْجُمُعَةِ","src":"رواه البخاري ٩٣٩","pre":"وعن سهل بن سعد رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":939,"id":"h939"}]},{"t":"quote","text":"كَانَ النِّدَاءُ يَوْمَ الْجُمُعَةِ أَوَّلُهُ إِذَا جَلَسَ الإِمَامُ عَلَى الْمِنْبَرِ عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم وَأَبِي بَكْرٍ وَعُمَرَ ـ رضى الله عنهما ـ فَلَمَّا كَانَ عُثْمَانُ ـ رضى الله عنه ـ وَكَثُرَ النَّاسُ زَادَ النِّدَاءَ الثَّالِثَ عَلَى الزَّوْرَاءِ","src":"رواه البخاري ٩١٢","pre":"وعن السائب بن يزيد رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":912,"id":"h912"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْوَقْتُ فَإِنَّ الْجُمْهُورَ عَلَى أَنَّ وَقْتَهَا وَقْتُ الظُّهْرِ بِعَيْنِهِ (أَعْنِي وَقْتَ الزَّوَالِ، وَأَنَّهَا لَا تَجُوزُ قَبْلَ الزَّوَالِ) وَذَهَبَ قَوْمٌ إِلَى أَنَّهُ يَجُوزُ أَنْ تُصَلَّى قَبْلَ الزَّوَالِ وَهُوَ قَوْلُ أَحْمَدَ بْنِ حَنْبَلٍ.","src":"بداية المجتهد","loc":"١/١٦٧-١٦٨","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ثم إن عثمان رضي الله عنه اعتمد على أصل، وهو أن بلالا يؤذن قبل الفجر في عهد النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لا لصلاة الفجر، ولكن ليرجع القائم ويوقظ النائم","src":"مجموع فتاوى ابن عثيمين","loc":"٨/٦٣٩","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله في الأذان الأول يوم الجمعة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الجمعة تصلى بعد زوال الشمس كالظهر، وهو الأحوط والموافق لعمل الأمة؛ وأحاديث التبكير محمولة على المبادرة بعد الزوال. وأما الأذان الأول الذي زاده عثمان رضي الله عنه فهو سنة خليفة راشد أقرها الصحابة، فلا بأس به عند الحاجة لتنبيه الناس، والأذان الذي يحرم به البيع ويجب به السعي هو الأذان الذي بين يدي الخطيب."},{"t":"tanbih","items":[{"t":"p","text":"يحرم البيع والشراء وسائر ما يشغل عن السعي بعد الأذان الثاني على من تلزمه الجمعة؛ لقوله تعالى: ﴿وَذَرُوا۟ ٱلْبَيْعَ﴾."}]}],"refs":["البخاري ٩٠٤","البخاري ٩٣٩","البخاري ٩١٢","بداية المجتهد (١/١٦٧-١٦٨)","بداية المجتهد (١/١٦٨)","مجموع فتاوى ابن عثيمين (٨/٦٣٩)"],"related":["حكم صلاة الجمعة، ومن تجب عليه"],"alts":["الجمعة قبل الزوال","الأذان الأول للجمعة","أذان عثمان","البيع وقت الجمعة"]},{"n":132,"bab":"الصلاة","sub":"صلاة الجمعة","title":"شروط صحة الجمعة: العدد والمكان والإذن، وتعدد الجمعة في البلد الواحد","q":"نحن جالية صغيرة في بلد غير مسلم، عددنا قليل، فهل نقيم الجمعة في مصلى صغير؟ وهل يشترط إذن الحاكم أو أربعون رجلًا؟","short":"اتفقوا على اشتراط الجماعة والاستيطان، واختلفوا في العدد: فاشترط الشافعي وأحمد أربعين، وأبو حنيفة ثلاثة سوى الإمام، ومالك جماعة تتقرى بهم قرية بلا حد. واشترط أبو حنيفة المصر وإذن السلطان، ومالك المسجد الجامع. والأظهر صحتها بثلاثة فأكثر من أهل الاستيطان في أي مكان مناسب، ويجوز تعددها للحاجة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ أَوَّلَ جُمُعَةٍ جُمِّعَتْ بَعْدَ جُمُعَةٍ فِي مَسْجِدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي مَسْجِدِ عَبْدِ الْقَيْسِ بِجُوَاثَى مِنَ الْبَحْرَيْنِ","src":"رواه البخاري ٨٩٢","pre":"عن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":892,"id":"h892"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا شُرُوطُ الْوُجُوبِ وَالصِّحَّةِ الْمُخْتَصَّةُ بِيَوْمِ الْجُمُعَةِ فَاتَّفَقَ الْكُلُّ عَلَى أَنَّ مِنْ شَرْطِهَا الْجَمَاعَةَ، وَاخْتَلَفُوا فِي مِقْدَارِ الْجَمَاعَةِ، فَمِنْهُمْ مَنْ قَالَ: وَاحِدٌ مَعَ الْإِمَامِ وَهُوَ الطَّبَرِيُّ. وَمِنْهُمْ مَنْ قَالَ: اثْنَانِ سِوَى الْإِمَامِ. وَمِنْهُمْ مَنْ قَالَ: ثَلَاثَةٌ دُونَ الْإِمَامِ، وَهُوَ قَوْلُ أَبِي حَنِيفَةَ.","src":"بداية المجتهد","loc":"١/١٦٩","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الجمعة تصح بجماعة من المقيمين المستوطنين أقلهم ثلاثة مع الإمام أو سواه، كما يقول الحنفية في العدد، ولا يشترط الأربعون لعدم الدليل الصحيح على التحديد؛ ولا يشترط المسجد الجامع ولا إذن السلطان إذا تعذر، فإن جمعة جواثى أقيمت في قرية، والمسلمون في البلاد غير الإسلامية يقيمونها في المراكز والمصليات. فإذا كانت هناك هيئة إسلامية منظمة فيُرجع إليها تحقيقًا لمقصود الإذن."},{"t":"p","text":"وأما تعدد الجمعة في البلد الواحد فالأصل أن تُجمع في مكان واحد ما أمكن، ويجوز التعدد للحاجة كسعة البلد وضيق المساجد وكثرة الناس، وهو المفتى به عند متأخري الحنفية، وعليه عمل المسلمين اليوم."}],"refs":["البخاري ٨٩٢","بداية المجتهد (١/١٦٩)","بداية المجتهد (١/١٧٠)"],"related":["حكم صلاة الجمعة، ومن تجب عليه"],"alts":["عدد الجمعة","الجمعة في القرية","الجمعة في المصلى","تعدد الجمعة","الجمعة في بلاد غير المسلمين"]},{"n":133,"bab":"الصلاة","sub":"صلاة الجمعة","title":"خطبة الجمعة: حكمها، وأقل ما يجزئ منها، والجلوس بينهما، وخطبتها بغير العربية","q":"هل الخطبتان شرط لصحة الجمعة؟ وما أقل ما يجزئ؟ وهل يجوز أن يخطب الإمام بلغة القوم كالبشتو أو الدرية أو الإنجليزية؟","short":"الخطبة شرط لصحة الجمعة عند الجمهور. ويجزئ عند أبي حنيفة ذكر الله ولو بتسبيحة، ويشترط الشافعي وأحمد أركانًا: الحمد والصلاة على النبي ﷺ والوصية بالتقوى وقراءة آية والدعاء للمؤمنين، والجلوس بين الخطبتين سنة عند الجمهور وشرط عند الشافعي. واشترط الجمهور العربية في أركان الخطبة لمن يحسنها، وأجاز أبو حنيفة بغيرها. والأظهر أن يأتي بأركانها بالعربية ويترجم الموعظة بلغة الحاضرين.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَتْ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خُطْبَتَانِ يَجْلِسُ بَيْنَهُمَا يَقْرَأُ الْقُرْآنَ، وَيُذَكِّرُ النَّاسَ","src":"رواه مسلم ٨٦٢","pre":"عن جابر بن سمرة رضي الله عنه قال:","links":[{"book":"mt_muslim","num":862,"id":"h862"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"هَلْ هِيَ شَرْطٌ فِي صِحَّةِ الصَّلَاةِ، وَرُكْنٌ مِنْ أَرْكَانِهَا أَمْ لَا؟ فَذَهَبَ الْجُمْهُورُ إِلَى أَنَّهَا شَرْطٌ وَرُكْنٌ، وَقَالَ قَوْمٌ: إِنَّهَا لَيْسَتْ بِفَرْضٍ، وَجُمْهُورُ أَصْحَابِ مَالِكٍ عَلَى أَنَّهَا فَرْضٌ إِلَّا ابْنَ الْمَاجِشُونِ","src":"بداية المجتهد","loc":"١/١٧٠","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن خطبتي الجمعة شرط لصحتها؛ لمداومة النبي ﷺ عليهما، ولقوله تعالى: ﴿فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ﴾ والذكر هو الخطبة. وينبغي أن تشتمل الخطبة على حمد الله، والشهادتين، والصلاة على النبي ﷺ، والوصية بتقوى الله، وقراءة شيء من القرآن، والدعاء للمسلمين، وأن يجلس الخطيب بينهما جلسة خفيفة."},{"t":"p","text":"والمقصود الأعظم من الخطبة الوعظ والتعليم، فإذا كان الحاضرون لا يفهمون العربية فالأولى أن يأتي الخطيب بالأركان والآيات والأحاديث بالعربية ثم يشرح ويعظ بلغة الحاضرين، فيجمع بين الاتباع وتحقيق المقصود، وهذا ما عليه كثير من المجامع الفقهية، ويوافق قول أبي حنيفة في جواز الخطبة بغير العربية. وما جرت به عادة بعض البلاد من موعظة طويلة بلغة القوم قبل الأذان ثم خطبة عربية قصيرة لا بأس به."},{"t":"tanbih","items":[{"t":"p","text":"يُسن تقصير الخطبة وإطالة الصلاة؛ فقد قال النبي ﷺ: «إن طول صلاة الرجل وقصر خطبته مئنة من فقهه» (رواه مسلم ٨٦٩)."}]}],"refs":["مسلم ٨٦٢","بداية المجتهد (١/١٧٠)","بداية المجتهد (١/١٧١)"],"related":["الإنصات للخطبة، ورد السلام، وتحية المسجد والإمام يخطب"],"alts":["أركان خطبة الجمعة","الخطبة بغير العربية","الجلوس بين الخطبتين","خطبة الجمعة بالبشتو"]},{"n":134,"bab":"الصلاة","sub":"صلاة الجمعة","title":"الإنصات للخطبة، ورد السلام، وتحية المسجد والإمام يخطب","q":"دخلت المسجد والإمام يخطب، فهل أصلي تحية المسجد أم أجلس؟ وهل يجوز رد السلام أو تشميت العاطس أثناء الخطبة؟","short":"الإنصات للخطبة واجب عند جمهور العلماء، والكلام أثناءها لغو لا يبطل الصلاة. واختلفوا في تحية المسجد والإمام يخطب: فلا يصليها عند أبي حنيفة ومالك، ويصليها ركعتين خفيفتين عند الشافعي وأحمد وأهل الحديث. والأظهر أنه يصليهما خفيفتين لنص الحديث.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا قُلْتَ لِصَاحِبِكَ يَوْمَ الْجُمُعَةِ أَنْصِتْ. وَالإِمَامُ يَخْطُبُ فَقَدْ لَغَوْتَ","src":"رواه البخاري ٩٣٤","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":934,"id":"h934"}]},{"t":"quote","text":"جَاءَ سُلَيْكٌ الْغَطَفَانِيُّ يَوْمَ الْجُمُعَةِ، وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ عَلَى الْمِنْبَرِ، فَقَعَدَ سُلَيْكٌ قَبْلَ أَنْ يُصَلِّيَ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: «أَرَكَعْتَ رَكْعَتَيْنِ؟» قَالَ: لَا، قَالَ: «قُمْ فَارْكَعْهُمَا»","src":"رواه مسلم ٨٧٥","pre":"وعن جابر بن عبد الله رضي الله عنهما قال:","links":[{"book":"mt_muslim","num":875,"id":"h875-5"}]},{"t":"quote","text":"إِذَا جَاءَ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ، وَقَدْ خَرَجَ الْإِمَامُ، فَلْيُصَلِّ رَكْعَتَيْنِ","src":"رواه مسلم ٨٧٥","pre":"وفي رواية لمسلم قال ﷺ:","links":[{"book":"mt_muslim","num":875,"id":"h875-4"}]},{"t":"h","text":"الإنصات"},{"t":"p","text":"اتفق الأئمة الأربعة وجمهور فقهاء الأمصار على وجوب الإنصات للخطبة، ثم اختلفوا في رد السلام وتشميت العاطس أثناءها على ثلاثة أقوال:"},{"t":"qawl","label":"القول الأول","text":"يجوز رد السلام وتشميت العاطس، وبه قال الثوري والأوزاعي وغيرهما."},{"t":"qawl","label":"القول الثاني","text":"لا يرد السلام ولا يشمّت العاطس؛ لعموم الأمر بالإنصات."},{"t":"qawl","label":"القول الثالث","text":"يرد السلام ولا يشمّت العاطس."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"نعم، إذا دخلت المسجد يوم الجمعة والإمام يخطب فصل الركعتين وتجوز فيهما، ثم اجلس واستمع","src":"فتاوى نور على الدرب لابن باز","loc":"١٣/٣٠٨","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله عن تحية المسجد والإمام يخطب، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الواجب على من حضر الخطبة أن ينصت، ولا يتكلم ولا يعبث، ولا يرد السلام باللسان ولا يشمت العاطس، بل يشير إن احتاج، فإن تكلم لغت جمعته أي نقص أجرها وصحت صلاته. ومن دخل والإمام يخطب صلى ركعتين خفيفتين ثم جلس؛ لأمر النبي ﷺ سليكًا بذلك وهو على المنبر، ولقوله في رواية مسلم: «إذا جاء أحدكم يوم الجمعة وقد خرج الإمام فليصل ركعتين»، وهو نص في محل الخلاف كما قال ابن رشد. ومن أخذ بقول الحنفية والمالكية فجلس احترامًا للخطبة فلا يُنكر عليه."}],"refs":["البخاري ٩٣٤","مسلم ٨٧٥","فتاوى نور على الدرب لابن باز (١٣/٣٠٨)"],"related":["خطبة الجمعة: حكمها، وأقل ما يجزئ منها، والجلوس بينهما، وخطبتها بغير العربية"],"alts":["تحية المسجد يوم الجمعة","الكلام أثناء الخطبة","رد السلام في الخطبة"]},{"n":135,"bab":"الصلاة","sub":"صلاة الجمعة","title":"غسل الجمعة وآدابها، والتبكير إليها، والقراءة في صلاتها","q":"هل غسل الجمعة واجب؟ وما آداب يوم الجمعة؟ وماذا يقرأ الإمام في صلاة الجمعة؟","short":"غسل الجمعة سنة مؤكدة عند جمهور العلماء، وأوجبه أهل الظاهر، وهو ليس شرطًا للصلاة بالاتفاق. ومن آدابها: التطيب، والسواك، ولبس أحسن الثياب، والتبكير، وكثرة الصلاة على النبي ﷺ، وقراءة سورة الكهف. ويستحب أن يقرأ في الصلاة بالجمعة والمنافقين، أو بسبح والغاشية.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الْغُسْلُ يَوْمَ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ","src":"رواه البخاري ٨٥٨","pre":"عن أبي سعيد الخدري رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":858,"id":"h858"}]},{"t":"quote","text":"مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا وَنِعْمَتْ وَمَنِ اغْتَسَلَ فَالْغُسْلُ أَفْضَلُ","src":"رواه الترمذي ٤٩٧","pre":"وعن سمرة بن جندب رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":497,"id":"h497"}]},{"t":"quote","text":"مَنِ اغْتَسَلَ يَوْمَ الْجُمُعَةِ غُسْلَ الْجَنَابَةِ ثُمَّ رَاحَ فَكَأَنَّمَا قَرَّبَ بَدَنَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّانِيَةِ فَكَأَنَّمَا قَرَّبَ بَقَرَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الثَّالِثَةِ فَكَأَنَّمَا قَرَّبَ كَبْشًا أَقْرَنَ، وَمَنْ رَاحَ فِي السَّاعَةِ الرَّابِعَةِ فَكَأَنَّمَا قَرَّبَ دَجَاجَةً، وَمَنْ رَاحَ فِي السَّاعَةِ الْخَامِسَةِ فَكَأَنَّمَا قَرَّبَ بَيْضَةً","src":"رواه البخاري ٨٨١","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":881,"id":"h881"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي طُهْرِ الْجُمُعَةِ ; فَذَهَبَ الْجُمْهُورُ إِلَى أَنَّهُ سُنَّةٌ، وَذَهَبَ أَهْلُ الظَّاهِرِ إِلَى أَنَّهُ فَرْضٌ وَلَا خِلَافَ فِيمَا أَعْلَمُ أَنَّهُ لَيْسَ شَرْطًا فِي صِحَّةِ الصَّلَاةِ.","src":"بداية المجتهد","loc":"١/١٧٤-١٧٥","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الغسل يوم الجمعة سنة مؤكدة؛ لما ورد في ذلك من الأحاديث الصحيحة عن النبي صلى الله عليه وسلم","src":"مجموع فتاوى ابن باز","loc":"٢/٤٢٤","pre":"وسئل الشيخ عبد العزيز بن باز رحمه الله: هل غسل الجمعة واجب أم مستحب؟ فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن غسل الجمعة سنة مؤكدة جدًّا، يُخشى الإثم على من تركه بلا عذر مع قدرته؛ لقوله ﷺ: «واجب على كل محتلم»، وحمله الجمهور على تأكد الاستحباب لحديث «من توضأ فبها ونعمت» ولقصة عثمان مع عمر. ويستحب التبكير إلى الجمعة، والتطيب، ولبس أحسن الثياب، وقراءة سورة الكهف، والإكثار من الصلاة على النبي ﷺ والدعاء آخر ساعة من العصر. ويقرأ الإمام بالجمعة والمنافقين، أو بسبح والغاشية، وهو قول أكثر الفقهاء، ولم يعيّن أبو حنيفة سورة حتى لا يُظن وجوبها، فمن قرأ بغيرها أحيانًا فلا حرج."}],"refs":["البخاري ٨٥٨","الترمذي ٤٩٧","البخاري ٨٨١","بداية المجتهد (١/١٧٤-١٧٥)","بداية المجتهد (١/١٧٤)","مجموع فتاوى ابن باز (٢/٤٢٤)"],"related":["من أدرك ركعة من الجمعة، وسنة الجمعة"],"alts":["غسل الجمعة","آداب الجمعة","التبكير إلى الجمعة","سورة الكهف يوم الجمعة"]},{"n":136,"bab":"الصلاة","sub":"صلاة الجمعة","title":"من أدرك ركعة من الجمعة، وسنة الجمعة القبلية والبعدية","q":"جئت إلى الجمعة والإمام في التشهد، فهل أصلي ركعتين أم أربعًا؟ وهل للجمعة سنة قبلها وبعدها؟","short":"من أدرك ركعة مع الإمام أتمها جمعة بالاتفاق، ومن أدرك أقل من ركعة صلى ظهرًا أربعًا عند الجمهور (مالك والشافعي وأحمد ومحمد بن الحسن)، وأتمها جمعة عند أبي حنيفة وأبي يوسف. ويُسن بعد الجمعة ركعتان أو أربع بالاتفاق، وأما قبلها فيصلي ما شاء نفلًا مطلقًا، وجعل الحنفية قبلها أربعًا سنة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ أَدْرَكَ مِنَ الصَّلاَةِ رَكْعَةً فَقَدْ أَدْرَكَ الصَّلاَةَ","src":"رواه الترمذي ٥٢٤","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":524,"id":"h524"}]},{"t":"p","text":"قال الترمذي: والعمل على هذا عند أكثر أهل العلم من أصحاب النبي ﷺ وغيرهم، قالوا: من أدرك ركعة من الجمعة صلى إليها أخرى، ومن أدركهم جلوسًا صلى أربعًا."},{"t":"p","text":"وفي صحيح مسلم (٨٨١) قال ﷺ: «إذا صلى أحدكم الجمعة فليصل بعدها أربعًا»، وفي الصحيحين أنه ﷺ كان يصلي بعد الجمعة ركعتين في بيته."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الجمعة لا تُدرك إلا بإدراك ركعة كاملة مع الإمام، فمن أدرك الركوع من الركعة الثانية أتمها جمعة، ومن جاء بعد ذلك دخل معهم بنية الظهر وصلاها أربعًا؛ لمفهوم حديث «من أدرك ركعة» وهو قول الجمهور ومحمد بن الحسن. وبعد الجمعة يصلي في المسجد أربعًا أو في بيته ركعتين. وأما قبلها فلم يثبت عن النبي ﷺ سنة راتبة، فيصلي الداخل ما شاء من النوافل حتى يخرج الإمام، كما كان الصحابة يفعلون."}],"refs":["الترمذي ٥٢٤"],"related":["غسل الجمعة وآدابها، والتبكير إليها، والقراءة في صلاتها"],"alts":["المسبوق في الجمعة","سنة الجمعة","أربع قبل الجمعة","إدراك الجمعة"]},{"n":137,"bab":"الصلاة","sub":"صلاة المسافر","title":"حكم قصر الصلاة في السفر: واجب أم رخصة؟","q":"سافرت فهل يجب علي قصر الرباعية؟ وإذا صليت أربعًا خلف إمام مقيم أو منفردًا فهل صلاتي صحيحة؟","short":"اتفق العلماء على مشروعية قصر الرباعية في السفر. والقصر فرض متعين عند أبي حنيفة وأصحابه، فلو أتم المسافر عمدًا أساء، وتصح صلاته إن قعد في الثانية قدر التشهد؛ وسنة مؤكدة عند مالك، ورخصة يجوز تركها عند الشافعي وأحمد. ويلزم المسافر الإتمام إذا صلى خلف مقيم بالاتفاق.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَإِذَا ضَرَبْتُمْ فِى ٱلْأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَقْصُرُوا۟ مِنَ ٱلصَّلَوٰةِ","ref":"النساء: ١٠١"},{"t":"quote","text":"قُلْتُ لِعُمَرَ بْنِ الْخَطَّابِ: {لَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا مِنَ الصَّلَاةِ، إِنْ خِفْتُمْ أَنْ يَفْتِنَكُمُ الَّذِينَ كَفَرُوا} فَقَدْ أَمِنَ النَّاسُ، فَقَالَ: عَجِبْتُ مِمَّا عَجِبْتُ مِنْهُ، فَسَأَلْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ذَلِكَ، فَقَالَ «صَدَقَةٌ تَصَدَّقَ اللهُ بِهَا عَلَيْكُمْ، فَاقْبَلُوا صَدَقَتَهُ»","src":"رواه مسلم ٦٨٦","pre":"عن يعلى بن أمية قال:","links":[{"book":"mt_muslim","num":686,"id":"h686"}]},{"t":"quote","text":"الصَّلاَةُ أَوَّلُ مَا فُرِضَتْ رَكْعَتَيْنِ فَأُقِرَّتْ صَلاَةُ السَّفَرِ، وَأُتِمَّتْ صَلاَةُ الْحَضَرِ","src":"رواه البخاري ١٠٩٠، ومسلم ٦٨٥","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1090,"id":"h1090"},{"book":"mt_muslim","num":685,"id":"h685"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا حُكْمُ الْقَصْرِ، فَإِنَّهُمُ اخْتَلَفُوا فِيهِ عَلَى أَرْبَعَةِ أَقْوَالٍ: فَمِنْهُمْ مَنْ رَأَى أَنَّ الْقَصْرَ هُوَ فَرْضُ الْمُسَافِرِ الْمُتَعَيَّنُ عَلَيْهِ. وَمِنْهُمْ مَنْ رَأَى أَنَّ الْقَصْرَ وَالْإِتْمَامَ كِلَاهُمَا فَرْضٌ مُخَيَّرٌ لَهُ كَالْخِيَارِ فِي وَاجِبِ الْكَفَّارَةِ. وَمِنْهُمْ مَنْ رَأَى أَنَّ الْقَصْرَ سُنَّةٌ.","src":"بداية المجتهد","loc":"١/١٧٦-١٧٧","pre":"قال ابن رشد:"},{"t":"quote","text":"وَفَرْضُ الْمُسَافِرِ فِي الرُّبَاعِيَّةِ رَكْعَتَانِ لَا يَزِيدُ عَلَيْهِمَا وَقَالَ الشَّافِعِيُّ - رَحِمَهُ اللَّهُ - فَرْضُهُ الْأَرْبَعُ وَالْقَصْرُ رُخْصَةٌ اعْتِبَارًا بِالصَّوْمِ. وَلَنَا أَنَّ الشَّفْعَ الثَّانِيَ لَا يُقْضَى وَلَا يُؤْثَمُ عَلَى تَرْكِهِ، وَهَذَا آيَةُ النَّافِلَةِ","src":"الهداية مع فتح القدير","loc":"٢/٣١","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن القصر في السفر سنة مؤكدة جدًّا، لا ينبغي تركها؛ لأن النبي ﷺ داوم عليه في جميع أسفاره ولم يثبت عنه أنه أتم، ولحديث عائشة «فأقرت صلاة السفر»؛ ومن أتم فصلاته صحيحة على قول الجمهور، لأن عثمان وعائشة رضي الله عنهما أتما في السفر، وصلى الصحابة خلف عثمان بمنى أربعًا. والقول بوجوبه كما يقول الحنفية قوي من جهة المداومة وحديث عائشة، فالأحوط ألا يتم المسافر إلا إذا صلى خلف مقيم."},{"t":"tanbih","items":[{"t":"p","text":"القصر خاص بالرباعية: الظهر والعصر والعشاء، ولا قصر في الفجر والمغرب بالإجماع."},{"t":"p","text":"إذا صلى المسافر خلف مقيم لزمه الإتمام، وإذا صلى المقيم خلف مسافر أتم بعد سلام إمامه."}]}],"refs":["مسلم ٦٨٦","البخاري ١٠٩٠، ومسلم ٦٨٥","بداية المجتهد (١/١٧٦-١٧٧)","الهداية مع فتح القدير (٢/٣١)","بداية المجتهد (١/١٧٧)","بداية المجتهد (١/١٧٧-١٧٨)"],"related":["مسافة القصر","مدة الإقامة التي ينقطع بها حكم السفر"],"alts":["قصر الصلاة","الإتمام في السفر","صلاة المسافر خلف المقيم"]},{"n":138,"bab":"الصلاة","sub":"صلاة المسافر","title":"مسافة القصر، ومتى يبدأ المسافر بالقصر","q":"كم المسافة التي يقصر فيها المسافر؟ وهل أقصر في سفر ساعة بالسيارة أو الطائرة؟ ومتى أبدأ القصر؟","short":"المسافة عند مالك والشافعي وأحمد أربعة برد (نحو ٨٠–٨٥ كيلومترًا)، وعند أبي حنيفة مسيرة ثلاثة أيام (قدّرها متأخرو الحنفية بنحو ٧٧–٩٠ كيلومترًا)، وعند أهل الظاهر وبعض المحققين كل ما يسمى سفرًا عرفًا. ولا عبرة بسرعة الوسيلة. ويبدأ القصر إذا فارق بيوت بلده بالاتفاق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ مَسِيرَةَ ثَلَاثَةِ أَمْيَالٍ، أَوْ ثَلَاثَةِ فَرَاسِخَ - شُعْبَةُ الشَّاكُّ - صَلَّى رَكْعَتَيْنِ","src":"رواه مسلم ٦٩١","pre":"عن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_muslim","num":691,"id":"h691"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا اخْتِلَافُهُمْ فِي الْمَوْضِعِ الثَّانِي، (وَهِيَ الْمَسَافَةُ الَّتِي يَجُوزُ فِيهَا الْقَصْرُ) ، فَإِنَّ الْعُلَمَاءَ اخْتَلَفُوا فِي ذَلِكَ أَيْضًا اخْتِلَافًا كَثِيرًا، فَذَهَبَ مَالِكٌ، وَالشَّافِعِيُّ، وَأَحْمَدُ، وَجَمَاعَةٌ كَثِيرَةٌ إِلَى أَنَّ الصَّلَاةَ تُقْصَرُ فِي أَرْبَعَةِ بُرُدٍ، وَذَلِكَ مَسِيرَةَ يَوْمٍ بِالسَّيْرِ الْوَسَطِ.","src":"بداية المجتهد","loc":"١/١٧٨","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وقد تقرر لدينا بعد الدراسة أن مسافة القصر المعتبرة هي ثمانون كيلو تقريبا فأكثر","src":"مجموع فتاوى ابن باز","loc":"١٢/٢٦٨","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"من العلماء من يرى أن مسافة القصر بالمساحة, فمتى بلغ خروجه بضعاً وثمانين كيلو فهو مسافر يحل له القصر والجمع, ومن العلماء من يرى أن المعتبر العرف, فما عده الناس سفراً يستعدون له استعداد السفر ويودع عند خروجه ويستقبل عند قدومه فهو سفر, وما لا فلا","src":"مجموع فتاوى ابن عثيمين","loc":"١٥/٢٦٢","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"لم يرد في تحديد مسافة القصر نص صريح من النبي ﷺ، وإنما وردت آثار عن الصحابة مختلفة، فالأحوط للمسلم أن يأخذ بقول الجمهور فلا يقصر إلا في سفر يبلغ نحو ثمانين كيلومترًا فأكثر، وهو قريب من تقدير متأخري الحنفية، فتجتمع الأقوال. والعبرة بالمسافة لا بالزمن، فمن سافر بالطائرة ألف كيلومتر في ساعة قصر، ومن ذهب إلى بلد قريب داخل المدينة لم يقصر وإن طال زمن الزحام."},{"t":"p","text":"ويبدأ القصر إذا خرج من عمران بلده وفارق آخر بيوته، ولا يقصر في بيته قبل الخروج وإن عزم على السفر، ويستمر القصر حتى يرجع إلى بلده."}],"refs":["مسلم ٦٩١","بداية المجتهد (١/١٧٨)","مجموع فتاوى ابن باز (١٢/٢٦٨)","مجموع فتاوى ابن عثيمين (١٥/٢٦٢)","بداية المجتهد (١/١٧٩)"],"related":["حكم قصر الصلاة في السفر: واجب أم رخصة؟","مدة الإقامة التي ينقطع بها حكم السفر"],"alts":["مسافة القصر بالكيلو","القصر في سفر الطائرة","متى يبدأ القصر"]},{"n":139,"bab":"الصلاة","sub":"صلاة المسافر","title":"مدة الإقامة التي ينقطع بها حكم السفر، وسفر المعصية","q":"سافرت إلى بلد للدراسة أو العلاج وسأبقى أسبوعًا أو شهرًا، فهل أقصر الصلاة طوال المدة؟","short":"إذا نوى المسافر إقامة أربعة أيام فأكثر أتم عند مالك والشافعي، وأكثر من أربعة أيام (أكثر من عشرين صلاة) عند أحمد، وخمسة عشر يومًا عند أبي حنيفة والثوري. وإذا لم ينو إقامة محددة وبقي ينتظر حاجة لا يدري متى تنقضي قصر أبدًا بالاتفاق. ويقصر في كل سفر عند أبي حنيفة، ولا يقصر في سفر المعصية عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَقَامَ النَّبِيُّ صلى الله عليه وسلم تِسْعَةَ عَشَرَ يَقْصُرُ، فَنَحْنُ إِذَا سَافَرْنَا تِسْعَةَ عَشَرَ قَصَرْنَا، وَإِنْ زِدْنَا أَتْمَمْنَا","src":"رواه البخاري ١٠٨٠","pre":"عن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1080,"id":"h1080"}]},{"t":"quote","text":"أَقَمْنَا مَعَ النَّبِيِّ صلى الله عليه وسلم عَشْرًا نَقْصُرُ الصَّلاَةَ","src":"رواه البخاري ٤٢٩٧","pre":"وعن أنس رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":4297,"id":"h4297"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اختلف العلماء في مدة الإقامة التي إذا نواها المسافر أتمّ الصلاة، وحكى ابن عبد البر فيها نحوًا من أحد عشر قولًا، وأشهرها ثلاثة:"},{"t":"qawl","label":"القول الأول","text":"إذا نوى إقامة أربعة أيام أتمّ، وهو قول مالك والشافعي."},{"t":"qawl","label":"القول الثاني","text":"إذا نوى إقامة خمسة عشر يومًا أتمّ، وما دونها يقصر، وهو قول أبي حنيفة والثوري، ورُوي عن ابن عمر وابن عباس رضي الله عنهم."},{"t":"qawl","label":"القول الثالث","text":"إذا نوى إقامة أكثر من أربعة أيام (أكثر من عشرين صلاة) أتمّ، وهو قول أحمد وداود."},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المسافر الذي نوى الإقامة ببلد أكثر من أربعة أيام لا يقصر الصلاة، وإذا كانت الإقامة دون هذه المدة فإنه يقصر الصلاة","src":"فتاوى اللجنة الدائمة","loc":"٥/٣٨١","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر والأحوط أن المسافر إذا نوى الإقامة في بلد أكثر من أربعة أيام أتم الصلاة من أول إقامته، وهو قول الجمهور؛ لأن الأصل الإتمام، وأقصى ما ثبت أن النبي ﷺ أقامه مقصرًا وهو عازم على الإقامة إقامته بمكة في حجة الوداع أربعة أيام قبل الخروج إلى منى. ومن أخذ بمذهب الحنفية فقصر ما دون خمسة عشر يومًا فله سلف من الصحابة كابن عمر. وأما من لم يعزم على مدة، بل يقول: أسافر غدًا أو بعد غد إذا قضيت حاجتي، فإنه يقصر ولو طالت المدة، كما أقام النبي ﷺ بمكة عام الفتح تسعة عشر يومًا يقصر."},{"t":"p","text":"والطالب أو العامل المقيم في بلد مدة طويلة مقيم يتم الصلاة ويصوم، وتلزمه الجمعة."}],"refs":["البخاري ١٠٨٠","البخاري ٤٢٩٧","فتاوى اللجنة الدائمة (٥/٣٨١)"],"related":["مسافة القصر، ومتى يبدأ المسافر بالقصر"],"alts":["مدة القصر","المسافر يقيم أسبوعا","القصر للطالب المغترب","سفر المعصية"]},{"n":140,"bab":"الصلاة","sub":"صلاة المسافر","title":"الجمع بين الصلاتين في السفر","q":"هل يجوز للمسافر أن يجمع الظهر والعصر، والمغرب والعشاء، جمع تقديم أو تأخير؟","short":"أجمعوا على الجمع بعرفة ومزدلفة في الحج. وأجاز الجمهور (مالك والشافعي وأحمد) الجمع في السفر تقديمًا وتأخيرًا، ومنعه أبو حنيفة في غير عرفة ومزدلفة، وحمل أحاديثه على الجمع الصوري: تأخير الأولى إلى آخر وقتها وتعجيل الثانية في أول وقتها. والأظهر جوازه للمسافر عند الحاجة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا ارْتَحَلَ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ إِلَى وَقْتِ الْعَصْرِ، ثُمَّ يَجْمَعُ بَيْنَهُمَا، وَإِذَا زَاغَتْ صَلَّى الظُّهْرَ ثُمَّ رَكِبَ","src":"رواه البخاري ١١١١، ومسلم ٧٠٤","pre":"عن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1111,"id":"h1111"},{"book":"mt_muslim","num":704,"id":"h704"}]},{"t":"quote","text":"مَا رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم صَلَّى صَلاَةً بِغَيْرِ مِيقَاتِهَا إِلاَّ صَلاَتَيْنِ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ، وَصَلَّى الْفَجْرَ قَبْلَ مِيقَاتِهَا","src":"رواه البخاري ١٦٨٢","pre":"وعن عبد الله بن مسعود رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1682,"id":"h1682"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا جَوَازُهُ فَإِنَّهُمْ أَجْمَعُوا عَلَى أَنَّ الْجَمْعَ بَيْنَ الظُّهْرِ، وَالْعَصْرِ فِي وَقْتِ الظُّهْرِ بِعَرَفَةَ سُنَّةٌ، وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ بِالْمُزْدَلِفَةِ أَيْضًا فِي وَقْتِ الْعِشَاءِ سُنَّةٌ أَيْضًا. وَاخْتَلَفُوا فِي الْجَمْعِ فِي غَيْرِ هَذَيْنِ الْمَكَانَيْنِ، فَأَجَازَهُ الْجُمْهُورُ عَلَى اخْتِلَافٍ بَيْنَهُمْ فِي الْمَوَاضِعِ الَّتِي يَجُوزُ فِيهَا مِنَ الَّتِي لَا يَجُوزُ، وَمَنَعَهُ أَبُو حَنِيفَةَ، وَأَصْحَابُهُ بِإِطْلَاقٍ","src":"بداية المجتهد","loc":"١/١٨١","pre":"قال ابن رشد:"},{"t":"quote","text":"قَالَ مَالِكٌ: وَعَلَى ذَلِكَ الْأَمْرُ عِنْدَنَا فِي الْجَمْعِ بَيْنَ الصَّلَاتَيْنِ لِمَنْ جَدَّ بِهِ السَّيْرُ","src":"المدونة","loc":"١/٢٠٥","pre":"وفي «المدونة»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الجمع بين الظهر والعصر، وبين المغرب والعشاء، جائز للمسافر تقديمًا وتأخيرًا عند الحاجة؛ لحديث أنس الصريح في أنه ﷺ أخر الظهر إلى وقت العصر ثم جمع بينهما، وفي رواية مسلم: «حتى يدخل أول وقت العصر»، وهذا لا يحتمل الجمع الصوري. وحديث ابن مسعود نفى ما رآه هو، والمثبت مقدم على النافي. ومع ذلك فالحنفية لهم في الاحتياط للوقت وجه معتبر، فالأفضل للمسافر النازل المستقر أن يصلي كل صلاة في وقتها قصرًا، ويجمع إذا جدّ به السير أو احتاج إليه."}],"refs":["البخاري ١١١١، ومسلم ٧٠٤","البخاري ١٦٨٢","بداية المجتهد (١/١٨١)","المدونة (١/٢٠٥)","بداية المجتهد (١/١٨٢)"],"related":["الجمع في الحضر للمطر والمرض والحاجة"],"alts":["جمع التقديم","جمع التأخير","الجمع في السفر","الجمع الصوري"]},{"n":141,"bab":"الصلاة","sub":"صلاة المسافر","title":"الجمع في الحضر للمطر والمرض والحاجة","q":"هل يجوز الجمع بين المغرب والعشاء في المسجد ليلة المطر؟ وهل يجمع المريض والطبيب الجراح والمرأة المستحاضة؟","short":"منع أبو حنيفة الجمع في الحضر مطلقًا إلا الصوري. وأجاز مالك الجمع بين المغرب والعشاء للمطر والطين، والشافعي للمطر في الظهرين والعشاءين، وأحمد للمطر والوحل والريح الشديدة والمرض ونحوها. وأجاز بعض أهل العلم الجمع في الحضر للحاجة العارضة ما لم يتخذه عادة، لحديث ابن عباس.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ وَالْعَصْرَ جَمِيعًا، وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، فِي غَيْرِ خَوْفٍ، وَلَا سَفَرٍ","src":"رواه مسلم ٧٠٥","pre":"عن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_muslim","num":705,"id":"h705"}]},{"t":"p","text":"وفي رواية لمسلم: «في غير خوف ولا مطر»، قيل لابن عباس: ما أراد إلى ذلك؟ قال: «أراد ألا يحرج أمته»."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْجَمْعُ فِي الْحَضَرِ لِغَيْرِ عُذْرٍ، فَإِنَّ مَالِكًا وَأَكْثَرَ الْفُقَهَاءِ لَا يُجِيزُونَهُ، وَأَجَازَ ذَلِكَ جَمَاعَةٌ مِنْ أَهْلِ الظَّاهِرِ وَأَشْهَبُ مِنْ أَصْحَابِ مَالِكٍ. وَسَبَبُ اخْتِلَافِهِمْ: اخْتِلَافُهُمْ فِي مَفْهُومِ حَدِيثِ ابْنِ عَبَّاسٍ، فَمِنْهُمْ مَنْ تَأَوَّلَهُ عَلَى أَنَّهُ كَانَ فِي مَطَرٍ كَمَا قَالَ مَالِكٌ. وَمِنْهُمْ مَنْ أَخَذَ بِعُمُومِهِ مُطْلَقًا.","src":"بداية المجتهد","loc":"١/١٨٤","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"لا حرج في الجمع بين المغرب والعشاء ولا بين الظهر والعصر في أصح قولي العلماء للمطر الذي يشق معه الخروج إلى المساجد، وهكذا الدحض والسيول الجارية في الأسواق لما في ذلك من المشقة","src":"مجموع فتاوى ابن باز","loc":"١٢/٢٩١","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر جواز الجمع في الحضر عند الحاجة والحرج: كالمطر الشديد الذي يشق معه الرجوع إلى المسجد، والمرض الذي يشق معه أداء كل صلاة في وقتها، والمستحاضة، والطبيب في عملية طويلة، والعامل الذي لا يتمكن من الصلاة في الوقت؛ لحديث ابن عباس، وعلته رفع الحرج عن الأمة. ولا يجوز اتخاذ الجمع عادة بلا حاجة؛ لأن المواقيت فرض. وأهل المسجد يجمعون للمطر المغرب والعشاء تقديمًا إذا كان يشق عليهم الرجوع، والأولى ألا يُتوسع فيه."}],"refs":["مسلم ٧٠٥","بداية المجتهد (١/١٨٤)","بداية المجتهد (١/١٨٥)","مجموع فتاوى ابن باز (١٢/٢٩١)"],"related":["الجمع بين الصلاتين في السفر"],"alts":["الجمع للمطر","الجمع للمريض","الجمع في الحضر للحاجة"]},{"n":142,"bab":"الصلاة","sub":"صلاة المسافر","title":"صلاة الخوف وصفتها","q":"هل صلاة الخوف مشروعة بعد النبي ﷺ؟ وكيف تُصلى في حال القتال أو الحراسة؟","short":"صلاة الخوف مشروعة بعد النبي ﷺ عند جمهور العلماء ومنهم أبو حنيفة ومحمد، وشذ أبو يوسف فخصها بالنبي ﷺ. ووردت لها صفات صحيحة متعددة: اختار مالك والشافعي صفة ذات الرقاع، واختار أبو حنيفة صفة حديث ابن عمر وابن مسعود، واختار أحمد جواز كل ما صح. وإذا اشتد الخوف صلوا رجالًا وركبانًا إلى القبلة وغيرها يومئون.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَإِذَا كُنتَ فِيهِمْ فَأَقَمْتَ لَهُمُ ٱلصَّلَوٰةَ فَلْتَقُمْ طَآئِفَةٌ مِّنْهُم مَّعَكَ وَلْيَأْخُذُوٓا۟ أَسْلِحَتَهُمْ","ref":"النساء: ١٠٢"},{"t":"quote","text":"أَنَّ طَائِفَةً صَفَّتْ مَعَهُ وَطَائِفَةٌ وِجَاهَ الْعَدُوِّ، فَصَلَّى بِالَّذِينَ مَعَهُ رَكْعَةً، ثُمَّ ثَبَتَ قَائِمًا، وَأَتَمُّوا لِأَنْفُسِهِمْ، ثُمَّ انْصَرَفُوا فَصَفُّوا وِجَاهَ الْعَدُوِّ، وَجَاءَتِ الطَّائِفَةُ الْأُخْرَى فَصَلَّى بِهِمِ الرَّكْعَةَ الَّتِي بَقِيَتْ، ثُمَّ ثَبَتَ جَالِسًا وَأَتَمُّوا لِأَنْفُسِهِمْ، ثُمَّ سَلَّمَ بِهِمْ","src":"رواه مسلم ٨٤٢","pre":"عن صالح بن خوات عمن صلى مع رسول الله ﷺ يوم ذات الرقاع صلاة الخوف:","links":[{"book":"mt_muslim","num":842,"id":"h842"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ فِي جَوَازِ صَلَاةِ الْخَوْفِ بَعْدَ النَّبِيِّ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - وَفِي صِفَتِهَا. ; فَأَكْثَرُ الْعُلَمَاءِ عَلَى أَنَّ صَلَاةَ الْخَوْفِ جَائِزَةٌ لِعُمُومِ قَوْله تَعَالَى: {وَإِذَا ضَرَبْتُمْ فِي الأَرْضِ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَنْ تَقْصُرُوا} النساء: 101 الْآيَةَ.","src":"بداية المجتهد","loc":"١/١٨٥","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة الخوف مشروعة إلى يوم القيامة، وأن صفاتها الثابتة كلها جائزة، يختار الإمام منها ما هو أحوط للصلاة وأبلغ في الحراسة بحسب موقع العدو: فإن كان العدو في جهة القبلة صلى بهم صلاة عسفان، وإن كان في غيرها صلى صلاة ذات الرقاع أو صفة ابن عمر. وإذا اشتد الخوف والتحم القتال صلى كل واحد بحسب حاله ماشيًا أو راكبًا، مستقبل القبلة أو غير مستقبلها، يومئ بالركوع والسجود، ولا يؤخر الصلاة عن وقتها."},{"t":"tanbih","items":[{"t":"p","text":"يلحق بصلاة الخوف من خاف على نفسه من عدو أو سبع أو سيل أو حريق وهو هارب، فيصلي على حاله مومئًا."}]}],"refs":["مسلم ٨٤٢","بداية المجتهد (١/١٨٥)","بداية المجتهد (١/١٨٨)"],"related":["صلاة المريض"],"alts":["صلاة الخوف","الصلاة في القتال","صلاة الهارب"]},{"n":143,"bab":"الصلاة","sub":"صلاة المسافر","title":"صلاة المريض: القعود، والإيماء، والصلاة على الكرسي","q":"أنا مريض لا أستطيع القيام أو السجود على الأرض، فكيف أصلي؟ وهل يجوز الصلاة على الكرسي؟","short":"أجمع العلماء على أن المريض يصلي حسب استطاعته، ويسقط عنه القيام إذا عجز عنه أو شق عليه مشقة ظاهرة، فيصلي قاعدًا، فإن عجز عن الركوع والسجود أومأ بهما وجعل السجود أخفض، فإن عجز عن القعود صلى على جنبه، فإن عجز صلى مستلقيًا. ولا تسقط الصلاة عنه ما دام عقله ثابتًا.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ","ref":"التغابن: ١٦"},{"t":"quote","text":"كَانَتْ بِي بَوَاسِيرُ فَسَأَلْتُ النَّبِيَّ صلى الله عليه وسلم عَنِ الصَّلاَةِ فَقَالَ «صَلِّ قَائِمًا، فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِدًا، فَإِنْ لَمْ تَسْتَطِعْ فَعَلَى جَنْبٍ»","src":"رواه البخاري ١١١٧","pre":"عن عمران بن حصين رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1117,"id":"h1117"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أجمع العلماء على أن المريض لا تسقط عنه الصلاة ما دام عقله ثابتًا، وأنه يسقط عنه القيام إذا عجز عنه فيصلي جالسًا، ويسقط عنه الركوع والسجود إذا عجز عنهما فيومئ بهما. واختلفوا في مسائل:"},{"t":"qawl","label":"المسألة الأولى","text":"حدّ العجز المبيح للجلوس: قال بعضهم: هو من لا يستطيع القيام أصلًا، وقال الجمهور، ومنهم أبو حنيفة ومالك: هو من يشق عليه القيام مشقة ظاهرة، أو يخاف زيادة المرض أو تأخر البرء."},{"t":"qawl","label":"المسألة الثانية","text":"هيئة الجلوس بدل القيام: قال بعضهم: يجلس متربعًا، وكره ابن مسعود رضي الله عنه التربع، والأمر في ذلك واسع."},{"t":"qawl","label":"المسألة الثالثة","text":"من عجز عن القيام والجلوس: قال الجمهور: يصلي على جنبه، فإن لم يستطع فمستلقيًا ورجلاه إلى القبلة، وقدّم الحنفية الاستلقاء على الجنب."},{"t":"quote","text":"إذَا عَجَزَ الْمَرِيضُ عَنْ الْقِيَامِ صَلَّى قَاعِدًا يَرْكَعُ وَيَسْجُدُ «لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - لِعِمْرَانَ بْنِ حُصَيْنٍ - رَضِيَ اللَّهُ عَنْهُ - صَلِّ قَائِمًا، فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِدًا، فَإِنْ لَمْ تَسْتَطِعْ فَعَلَى الْجَنْبِ تُومِئُ إيمَاءً» ؛ وَلِأَنَّ الطَّاعَةَ بِحَسَبِ الطَّاقَةِ","src":"الهداية مع فتح القدير","loc":"٢/٣","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"quote","text":"وَأَصَحُّ الْأَقَاوِيلِ فِي تَفْسِيرِ الْعَجْزِ أَنْ يَلْحَقَهُ بِالْقِيَامِ ضَرَرٌ وَعَلَيْهِ الْفَتْوَى، كَذَا فِي مِعْرَاجِ الدِّرَايَةِ، وَكَذَلِكَ إذَا خَافَ زِيَادَةَ الْمَرَضِ أَوْ إبْطَاءَ الْبُرْءِ بِالْقِيَامِ أَوْ دَوَرَانِ الرَّأْسِ، كَذَا فِي التَّبْيِينِ أَوْ يَجِدُ وَجَعًا لِذَلِكَ","src":"الفتاوى الهندية","loc":"١/١٣٦","pre":"وفي «الفتاوى الهندية»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"هذا هو الواجب على المريض ذكرا كان أو أنثى يصلي قاعدا إذا عجز عن القيام سواء كان قاعدا مستوفزا أو متربعا أو كجلسته بين السجدتين كل ذلك جائز، فإن عجز عن القعود صلى على جنبه الأيمن أو الأيسر والأيمن أفضل إن استطاع","src":"مجموع فتاوى ابن باز","loc":"١٢/٢٤٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المريض يصلي قائمًا ما استطاع، فإن شق عليه القيام مشقة ظاهرة أو خاف زيادة المرض صلى قاعدًا، ويجلس متربعًا في موضع القيام إن شاء، ويركع ويسجد إن قدر، فإن لم يقدر على السجود على الأرض أومأ برأسه وجعل سجوده أخفض من ركوعه، ولا يرفع شيئًا يسجد عليه. فإن لم يستطع القعود صلى على جنبه الأيمن مستقبل القبلة، فإن لم يستطع صلى مستلقيًا ورجلاه إلى القبلة."},{"t":"p","text":"والصلاة على الكرسي جائزة لمن عجز عن القيام أو الجلوس على الأرض أو السجود عليها، ولا يجوز لمن قدر على القيام أن يجلس على الكرسي في الفريضة؛ فإن كان يستطيع القيام دون السجود صلى قائمًا ثم جلس على الكرسي للسجود مومئًا. ويوضع الكرسي في طرف الصف أو آخره حتى لا يقطع الصف ولا يؤذي المصلين."},{"t":"tanbih","items":[{"t":"p","text":"المريض الذي يشق عليه أداء كل صلاة في وقتها يجوز له الجمع، ولا تسقط عنه الصلاة إلا إذا زال عقله."}]}],"refs":["البخاري ١١١٧","الهداية مع فتح القدير (٢/٣)","الفتاوى الهندية (١/١٣٦)","مجموع فتاوى ابن باز (١٢/٢٤٩)"],"related":["الجمع في الحضر للمطر والمرض والحاجة"],"alts":["صلاة المريض جالسا","الصلاة على الكرسي","الإيماء في الصلاة","صلاة المريض على جنبه"]},{"n":144,"bab":"الصلاة","sub":"مفسدات الصلاة","title":"هل يقطع الصلاةَ مرورُ المرأة والحمار والكلب الأسود؟","q":"مرت امرأة أو مر كلب بين يدي وأنا أصلي بلا سترة، فهل بطلت صلاتي ويلزمني أن أعيدها؟","short":"ذهب الجمهور، ومنهم أبو حنيفة ومالك والشافعي، إلى أن الصلاة لا يقطعها مرور شيء، وأن المراد بالقطع في الحديث نقص الصلاة وقطع الخشوع. وذهب أحمد في المشهور عنه إلى أنه يقطعها الكلب الأسود، وتوقف في المرأة والحمار، وذهبت طائفة من أهل الحديث إلى أن الثلاثة يقطعونها لظاهر حديث أبي ذر. والمرور بين يدي المصلي محرم على كل حال.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا قَامَ أَحَدُكُمْ يُصَلِّي، فَإِنَّهُ يَسْتُرُهُ إِذَا كَانَ بَيْنَ يَدَيْهِ مِثْلُ آخِرَةِ الرَّحْلِ، فَإِذَا لَمْ يَكُنْ بَيْنَ يَدَيْهِ مِثْلُ آخِرَةِ الرَّحْلِ، فَإِنَّهُ يَقْطَعُ صَلَاتَهُ الْحِمَارُ، وَالْمَرْأَةُ، وَالْكَلْبُ الْأَسْوَدُ","src":"رواه مسلم ٥١٠","pre":"عن أبي ذر رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":510,"id":"h510"}]},{"t":"quote","text":"شَبَّهْتُمُونَا بِالْحُمُرِ وَالْكِلاَبِ، وَاللَّهِ لَقَدْ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يُصَلِّي، وَإِنِّي عَلَى السَّرِيرِ ـ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ـ مُضْطَجِعَةً فَتَبْدُو لِي الْحَاجَةُ، فَأَكْرَهُ أَنْ أَجْلِسَ فَأُوذِيَ النَّبِيَّ صلى الله عليه وسلم فَأَنْسَلُّ مِنْ عِنْدِ رِجْلَيْهِ","src":"رواه البخاري ٥١٤","pre":"وعن عائشة رضي الله عنها لما ذُكر عندها ما يقطع الصلاة: الكلب والحمار والمرأة، قالت:","links":[{"book":"mt_bukhari","num":514,"id":"h514"}]},{"t":"quote","text":"أَقْبَلْتُ رَاكِبًا عَلَى حِمَارٍ أَتَانٍ، وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الاِحْتِلاَمَ، وَرَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي بِالنَّاسِ بِمِنًى إِلَى غَيْرِ جِدَارٍ، فَمَرَرْتُ بَيْنَ يَدَىْ بَعْضِ الصَّفِّ، فَنَزَلْتُ وَأَرْسَلْتُ الأَتَانَ تَرْتَعُ، وَدَخَلْتُ فِي الصَّفِّ، فَلَمْ يُنْكِرْ ذَلِكَ عَلَىَّ أَحَدٌ","src":"رواه البخاري ٤٩٣","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":493,"id":"h493"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: لا يقطع الصلاةَ شيء، وإنما ينقص ثوابها","text":"وهو قول الجمهور: أبي حنيفة ومالك والشافعي، ورواية عن أحمد."},{"t":"qawl","label":"القول الثاني: يقطعها الكلب الأسود وحده","text":"وهو المشهور عن أحمد؛ لأن حديث الكلب لا معارض له، وأما المرأة والحمار فعارضهما حديث عائشة وابن عباس."},{"t":"qawl","label":"القول الثالث: يقطعها الثلاثة","text":"وهو قول طائفة من أهل الحديث أخذًا بظاهر حديث أبي ذر."},{"t":"quote","text":"اخْتَلَفَ الْعُلَمَاءُ هَلْ يَقْطَعُ الصَّلَاةَ مُرُورُ شَيْءٍ بَيْنَ يَدَيِ الْمُصَلِّي إِذَا صَلَّى لِغَيْرِ سُتْرَةٍ أَوْ مَرَّ بَيْنَهُ وَبَيْنَ السُّتْرَةِ؟ فَذَهَبَ الْجُمْهُورُ إِلَى أَنَّهُ لَا يَقْطَعُ الصَّلَاةَ شَيْءٌ، وَأَنَّهُ لَيْسَ عَلَيْهِ إِعَادَة، وَذَهَبَتْ طَائِفَةٌ إِلَى أَنَّهُ يَقْطَعُ الصَّلَاةَ: الْمَرْأَةُ وَالْحِمَارُ وَالْكَلْبُ الْأَسْوَدُ","src":"بداية المجتهد","loc":"١/١٩٠","pre":"قال ابن رشد:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"قوله: (في نفسي شيء) لأن حديث قطع الصلاة بالمرأة والحمار يعارضه حديث نوم عائشة بين يدي النبي - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - وحديث ابن عباس، وأما حديث قطعها بمرور الكلب فلا معارض له، ثم لما كان حديث الباب خلاف الأئمة الثلاثة تأول الناس بأن المراد من القطع قطع الخشوع، وأقول: إن المراد من القطع قطع الوصلة التي أخبر الشارع بها الغائبة منا، ولأن القطع إنما يكون في المتصل وهو الوصلة، وأقول: إن حديث نوم عائشة لا يعارض حديث الباب فإنها كانت لا تمر والحديث في المرور","src":"العرف الشذي","loc":"١/٣٣٥","pre":"وقال العلامة محمد أنور شاه الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن مرور المرأة أو الحمار أو الكلب بين يدي المصلي لا يُبطل صلاته ولا يلزمه إعادتها، وهو قول جمهور الأئمة، ويُحمل القطع في حديث أبي ذر على نقص الصلاة وشغل القلب عنها؛ جمعًا بينه وبين حديث عائشة وابن عباس. ومن احتاط فأعاد صلاته إذا مر الكلب الأسود بينه وبين سترته أو قريبًا منه فقد أخذ بقول معتبر عند أحمد وطائفة من أهل الحديث."},{"t":"p","text":"والمقصود الأعظم من الحديث: أن يتخذ المصلي سترة، وأن يمنع من يمر بين يديه، وأن يحذر المسلم من المرور بين يدي المصلي؛ فإنه من الكبائر لما ورد فيه من الوعيد."},{"t":"tanbih","items":[{"t":"p","text":"المرور بين يدي المأموم لا بأس به؛ لأن سترة الإمام سترة لمن خلفه، كما في حديث ابن عباس."}]}],"refs":["مسلم ٥١٠","البخاري ٥١٤","البخاري ٤٩٣","بداية المجتهد (١/١٩٠)","العرف الشذي (١/٣٣٥)"],"related":["السترة، والمرور بين يدي المصلي"],"alts":["مرور المرأة أمام المصلي","الكلب الأسود يقطع الصلاة","ما يبطل الصلاة من المرور"]},{"n":145,"bab":"الصلاة","sub":"مفسدات الصلاة","title":"من أحدث في الصلاة أو رعف: هل يبني على ما مضى أو يستأنف؟","q":"خرج مني ريح وأنا في الصلاة، أو نزل الدم من أنفي، فهل أذهب فأتوضأ ثم أكمل صلاتي من حيث وقفت، أو أبدأ الصلاة من جديد؟","short":"اتفقوا على أن الحدث يقطع الصلاة. ثم ذهب الشافعي وأحمد في المشهور إلى أنه يستأنف الصلاة ولا يبني، وأجاز مالك البناء في الرعاف وحده لأنه ليس حدثًا عنده، وأجاز أبو حنيفة البناء في الحدث الذي يغلبه (الذي يسبقه بغير اختياره) والرعاف ما لم يتكلم أو يفعل ما ينافي الصلاة، والاستئناف عنده أفضل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا فَسَا أَحَدُكُمْ فِي الصَّلاَةِ فَلْيَنْصَرِفْ فَلْيَتَوَضَّأْ وَلْيُعِدِ الصَّلاَةَ","src":"رواه أبو داود ٢٠٥","pre":"عن علي بن طلق رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":205,"id":"h205"}]},{"t":"quote","text":"مَنْ أَصَابَهُ قَىْءٌ أَوْ رُعَافٌ أَوْ قَلَسٌ أَوْ مَذْىٌ، فَلْيَنْصَرِفْ، فَلْيَتَوَضَّأْ. ثُمَّ لْيَبْنِ عَلَى صَلاَتِهِ، وَهُوَ فِي ذَلِكَ لاَ يَتَكَلَّمُ","src":"رواه ابن ماجه ١٢٢١","pre":"وعن عائشة رضي الله عنها قالت: قال رسول الله ﷺ:","links":[{"book":"mt_ibnmajah","num":1221,"id":"h1221"}]},{"t":"p","text":"وحديث عائشة هذا ضعيف عند أكثر المحدثين، والصواب فيه أنه مرسل، وبه احتج الحنفية مع آثار عن الصحابة، منها ما صح عن ابن عمر رضي الله عنهما أنه رعف في الصلاة فانصرف فغسل الدم ثم رجع فبنى على ما صلى."},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: يستأنف الصلاة ولا يبني في حدث ولا رعاف","text":"وهو قول الشافعي في الجديد، والمشهور عن أحمد."},{"t":"qawl","label":"القول الثاني: يبني في الرعاف وحده","text":"وهو قول مالك؛ لأن الرعاف عنده ليس بحدث."},{"t":"qawl","label":"القول الثالث: يبني في الحدث الذي يسبقه وفي الرعاف","text":"وهو قول أبي حنيفة وأصحابه (الكوفيين)، والاستئناف عندهم أفضل."},{"t":"quote","text":"الْجُمْهُورُ إِلَى أَنَّهُ لَا يَبْنِي لَا فِي حَدَثٍ، وَلَا فِي غَيْرِهِ مِمَّا يَقْطَعُ الصَّلَاةَ إِلَّا فِي الرُّعَافِ فَقَطْ. وَمِنْهُمْ مَنْ رَأَى أَنَّهُ لَا يَبْنِي لَا فِي الْحَدَثِ وَلَا فِي الرُّعَافِ، وَهُوَ الشَّافِعِيُّ، وَذَهَبَ الْكُوفِيُّونَ إِلَى أَنَّهُ يَبْنِي فِي الْأَحْدَاثِ كُلِّهَا","src":"بداية المجتهد","loc":"١/١٩٠","pre":"قال ابن رشد في الحدث يطرأ على المصلي: ذهب"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر والأحوط أن من أحدث في صلاته أو رعف فإنه ينصرف فيتوضأ أو يغسل الدم ثم يستأنف الصلاة من أولها؛ لحديث علي بن طلق: «فلينصرف فليتوضأ وليعد الصلاة»، ولأن الانصراف عن القبلة والمشي الكثير ينافي الصلاة، وهذا القول لا يختلف أحد في صحة الصلاة معه، والحنفية أنفسهم يرون الاستئناف أفضل. ومن بنى على صلاته في الحدث الذي غلبه أو الرعاف آخذًا بمذهب أبي حنيفة أو مالك فله سلف من الصحابة، ولا يُنكر عليه."},{"t":"tanbih","items":[{"t":"p","text":"من أحدث وهو إمام استخلف من يتم بالناس، فيقدم رجلًا من خلفه؛ كما فعل عمر رضي الله عنه لما طُعن فقدم عبد الرحمن بن عوف. ومن تذكر في الصلاة أنه على غير وضوء انصرف وتوضأ واستأنف بلا خلاف."}]}],"refs":["أبو داود ٢٠٥","ابن ماجه ١٢٢١","بداية المجتهد (١/١٩٠)"],"related":["الكلام في الصلاة: عمدًا وسهوًا ولمصلحتها"],"alts":["الحدث في الصلاة","الرعاف في الصلاة","خروج الريح في الصلاة","البناء على الصلاة"]},{"n":146,"bab":"الصلاة","sub":"مفسدات الصلاة","title":"الصلاة بحضرة الطعام، ومع مدافعة البول والغائط","q":"أُقيمت الصلاة وأنا أحتاج إلى قضاء الحاجة، أو قُدِّم الطعام وأنا جائع، فهل أبدأ بالصلاة أو بالخلاء والطعام؟ وإن صليت كذلك فهل تصح صلاتي؟","short":"أكثر العلماء على كراهة الصلاة مع مدافعة الأخبثين وبحضرة الطعام الذي تتوق إليه النفس، وأن الصلاة صحيحة مع الكراهة. وذهب بعضهم، ومنهم رواية عن مالك وقول أهل الظاهر، إلى بطلانها إذا اشتدت المدافعة حتى أذهبت الخشوع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَا صَلَاةَ بِحَضْرَةِ الطَّعَامِ، وَلَا هُوَ يُدَافِعُهُ الْأَخْبَثَانِ","src":"رواه مسلم ٥٦٠","pre":"عن عائشة رضي الله عنها قالت: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_muslim","num":560,"id":"h560"}]},{"t":"quote","text":"إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَذْهَبَ الْخَلاَءَ وَقَامَتِ الصَّلاَةُ فَلْيَبْدَأْ بِالْخَلاَءِ","src":"رواه أبو داود ٨٨","pre":"وعن عبد الله بن الأرقم رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_abudawud","num":88,"id":"h88"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: الصلاة صحيحة مع الكراهة","text":"وهو قول الجمهور: أبي حنيفة والشافعي وأحمد، والمشهور عن مالك."},{"t":"qawl","label":"القول الثاني: تبطل الصلاة إذا شغلته المدافعة","text":"وهو رواية ابن القاسم عن مالك، وقول أهل الظاهر."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من حضرته الصلاة وهو يدافع البول أو الغائط، أو قُدّم إليه طعام تتوق إليه نفسه، فالسنة أن يبدأ بقضاء حاجته أو بالطعام ثم يصلي بقلب حاضر، ولو فاتته الجماعة؛ لأن هذا عذر من أعذار ترك الجماعة. فإن صلى كذلك صحت صلاته مع الكراهة، إلا إذا اشتدت المدافعة حتى لم يعقل صلاته ولم يدر ما يقول، فالأحوط أن يعيد."},{"t":"tanbih","items":[{"t":"p","text":"لا يجوز أن يؤخر الصلاة لذلك حتى يخرج وقتها، ولا أن يتخذ الطعام عادة عند كل إقامة؛ وإنما الرخصة لمن حضره الطعام عرضًا وهو محتاج إليه."}]}],"refs":["مسلم ٥٦٠","أبو داود ٨٨","بداية المجتهد (١/١٩١)"],"related":["حكم صلاة الجماعة للرجال"],"alts":["الصلاة مع حبس البول","صلاة الحاقن","الصلاة بحضرة الطعام","مدافعة الأخبثين"]},{"n":147,"bab":"الصلاة","sub":"مفسدات الصلاة","title":"رد السلام في الصلاة، والإشارة فيها","q":"سلّم عليّ رجل وأنا أصلي، فهل أرد عليه بلساني أو بالإشارة؟ وهل تبطل الصلاة بالإشارة؟","short":"أجمعوا على أن رد السلام باللفظ في الصلاة عمدًا يبطلها بعد نسخ الكلام فيها، إلا قولًا شاذًا لبعض التابعين. ثم ذهب مالك والشافعي وأحمد إلى أن المصلي يرد بالإشارة، وذهب أبو حنيفة إلى أنه لا يرد بلفظ ولا إشارة، ويرد بعد الفراغ إن شاء، والإشارة لا تبطل الصلاة عنده بل تُكره.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنَّا نُسَلِّمُ عَلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ فِي الصَّلاَةِ فَيَرُدُّ عَلَيْنَا، فَلَمَّا رَجَعْنَا مِنْ عِنْدِ النَّجَاشِيِّ سَلَّمْنَا عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْنَا وَقَالَ «إِنَّ فِي الصَّلاَةِ شُغْلاً»","src":"رواه البخاري ١١٩٩","pre":"عن عبد الله بن مسعود رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1199,"id":"h1199"}]},{"t":"quote","text":"مَرَرْتُ بِرَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ يُصَلِّي فَسَلَّمْتُ عَلَيْهِ فَرَدَّ إِشَارَةً","src":"رواه أبو داود ٩٢٥، والترمذي ٣٦٧","pre":"وعن صهيب رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":925,"id":"h925"},{"book":"mt_tirmidhi","num":367,"id":"h367"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: يرد بالإشارة","text":"وهو قول مالك والشافعي وأحمد وأكثر أهل الحديث."},{"t":"qawl","label":"القول الثاني: لا يرد بلفظ ولا إشارة","text":"وهو قول أبي حنيفة، ويرد بعد السلام من الصلاة."},{"t":"qawl","label":"القول الثالث: يرد باللفظ","text":"وهو قول شاذ لبعض التابعين كسعيد بن المسيب والحسن وقتادة، وهو منسوخ بحديث ابن مسعود."},{"t":"quote","text":"اخْتَلَفُوا فِي رَدِّ سَلَامِ الْمُصَلِّي عَلَى مَنْ سَلَّمَ عَلَيْهِ، فَرَخَّصَتْ فِيهِ طَائِفَةٌ مِنْهُمْ سَعِيدُ بْنُ الْمُسَيَّبِ، وَالْحَسَنُ بْنُ أَبِي الْحَسَنِ الْبَصْرِيُّ وَقَتَادَةُ، وَمَنَعَ ذَلِكَ قَوْمٌ بِالْقَوْلِ، وَأَجَازُوا الرَّدَّ بِالْإِشَارَةِ، وَهُوَ مَذْهَبُ مَالِكٍ وَالشَّافِعِيِّ، وَمَنَعَ آخَرُونَ رَدَّهُ بِالْقَوْلِ وَالْإِشَارَةِ، وَهُوَ مَذْهَبُ النُّعْمَانِ، وَأَجَازَ قَوْمٌ الرَّدَّ فِي نَفْسِهِ، وَقَوْمٌ قَالُوا يَرُدُّ إِذَا فَرَغَ مِنَ الصَّلَاةِ","src":"بداية المجتهد","loc":"١/١٩٢","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المصلي إذا سُلّم عليه رد بالإشارة بيده أو بإصبعه، ولا يرد بلسانه؛ لحديث صهيب، وحديث ابن عمر في رد النبي ﷺ على الأنصار بقباء بالإشارة. ولا تبطل الصلاة بالإشارة اليسيرة المفهمة لحاجة، ومن لم يُشر وأخّر الرد إلى ما بعد الصلاة فلا حرج عليه، وهو قول الحنفية."},{"t":"tanbih","items":[{"t":"p","text":"لا ينبغي لمن رأى رجلًا يصلي أن يشغله بالسلام إذا كان يعلم أنه يشوش عليه، وإن سلّم فلا بأس؛ لأن الصحابة كانوا يسلمون على النبي ﷺ وهو يصلي فيرد عليهم بالإشارة."}]}],"refs":["البخاري ١١٩٩","أبو داود ٩٢٥، والترمذي ٣٦٧","بداية المجتهد (١/١٩٢)"],"related":["الكلام في الصلاة: عمدًا وسهوًا ولمصلحتها","الإنصات للخطبة، ورد السلام، وتحية المسجد والإمام يخطب"],"alts":["رد السلام بالإشارة","السلام على المصلي","الإشارة في الصلاة"]},{"n":148,"bab":"الصلاة","sub":"القضاء","title":"قضاء الصلاة الفائتة: الناسي والنائم والمتعمد والمغمى عليه","q":"تركت الصلاة سنوات ثم تبت، فهل يجب علي قضاء ما فاتني؟ وما حكم من نام عن صلاة أو نسيها، ومن أغمي عليه أيامًا؟","short":"أجمعوا على وجوب القضاء على النائم والناسي. وذهب الأئمة الأربعة وجماهير العلماء إلى أن من ترك الصلاة عمدًا حتى خرج وقتها فهو آثم ويجب عليه القضاء، وذهب ابن حزم وطائفة، واختاره ابن تيمية، إلى أنه لا يصح منه القضاء وإنما عليه التوبة والإكثار من النوافل. وأما المغمى عليه فأسقط عنه الشافعي ومالك القضاء، وأوجبه أحمد مطلقًا، وأوجبه أبو حنيفة إذا كانت الفوائت خمسًا فما دونها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ نَسِيَ صَلاَةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لاَ كَفَّارَةَ لَهَا إِلاَّ ذَلِكَ","src":"رواه البخاري ٥٩٧، ومسلم ٦٨٤","pre":"عن أنس بن مالك رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":597,"id":"h597"},{"book":"mt_muslim","num":684,"id":"h684"}]},{"t":"quote","text":"أَمَا إِنَّهُ لَيْسَ فِيَّ النَّوْمِ تَفْرِيطٌ، إِنَّمَا التَّفْرِيطُ عَلَى مَنْ لَمْ يُصَلِّ الصَّلَاةَ حَتَّى يَجِيءَ وَقْتُ الصَّلَاةَ الْأُخْرَى، فَمَنْ فَعَلَ ذَلِكَ فَلْيُصَلِّهَا حِينَ يَنْتَبِهُ لَهَا","src":"رواه مسلم ٦٨١","pre":"وعن أبي قتادة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":681,"id":"h681"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَاتَّفَقَ الْمُسْلِمُونَ عَلَى أَنَّهُ يَجِبُ عَلَى النَّاسِي وَالنَّائِمِ، وَاخْتَلَفُوا فِي الْعَامِدِ وَالْمُغْمَى عَلَيْهِ","src":"بداية المجتهد","loc":"١/١٩٢","pre":"قال ابن رشد في القضاء:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن النائم والناسي يقضيان الصلاة فور الذكر والاستيقاظ ولا إثم عليهما. وأما من ترك الصلاة عمدًا ثم تاب فالأحوط والذي عليه الأئمة الأربعة وجمهور الأمة أن يقضي ما فاته بحسب استطاعته، فيصلي مع كل فريضة فريضة أو أكثر من الفوائت حتى يغلب على ظنه أنه أدى ما عليه؛ لأنها دَين في ذمته، و«دين الله أحق أن يقضى»، ولأن الناسي إذا وجب عليه القضاء وهو معذور فالعامد أولى. ومن أخذ بقول من لا يرى القضاء فعليه أن يكثر من التوبة والنوافل."},{"t":"p","text":"وأما المغمى عليه فإن كان إغماؤه يومًا وليلة فما دون قضى ما فاته احتياطًا، وإن طال إغماؤه أيامًا فالأظهر أنه لا يلزمه القضاء؛ لأنه كالمجنون في زوال العقل، وقد صح عن ابن عمر أنه أغمي عليه فلم يقض، وعن عمار أنه قضى، فيُحمل على الاستحباب."},{"t":"tanbih","items":[{"t":"p","text":"لا تُسقط الفدية ولا الكفارة الصلاةَ عن الحي، ولا يصلي أحد عن أحد، وإنما يقضي كل إنسان ما فاته بنفسه."}]}],"refs":["البخاري ٥٩٧، ومسلم ٦٨٤","مسلم ٦٨١","بداية المجتهد (١/١٩٢)","بداية المجتهد (١/١٩٣)"],"related":["حكم تارك الصلاة","ترتيب الفوائت في القضاء"],"alts":["قضاء الصلوات الفائتة","قضاء الصلاة المتروكة عمدا","قضاء المغمى عليه","نام عن الصلاة"]},{"n":149,"bab":"الصلاة","sub":"القضاء","title":"ترتيب الفوائت في القضاء، وترتيبها مع الحاضرة","q":"فاتتني صلاة العصر فذكرتها وقت المغرب، فهل أصلي العصر أولًا ثم المغرب؟ وإذا كانت علي صلوات كثيرة فهل يجب ترتيبها؟","short":"ذهب أبو حنيفة ومالك وأحمد إلى وجوب الترتيب بين الفوائت، وبينها وبين الحاضرة، ويسقط عند الحنفية بالنسيان وضيق وقت الحاضرة وكثرة الفوائت إذا بلغت ستًّا، ويسقط عند مالك بالنسيان وفيما زاد على خمس صلوات. وذهب الشافعي إلى أن الترتيب مستحب لا واجب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَاءَ يَوْمَ الْخَنْدَقِ بَعْدَ مَا غَرَبَتِ الشَّمْسُ، فَجَعَلَ يَسُبُّ كُفَّارَ قُرَيْشٍ قَالَ يَا رَسُولَ اللَّهِ مَا كِدْتُ أُصَلِّي الْعَصْرَ حَتَّى كَادَتِ الشَّمْسُ تَغْرُبُ. قَالَ النَّبِيُّ صلى الله عليه وسلم «وَاللَّهِ مَا صَلَّيْتُهَا». فَقُمْنَا إِلَى بُطْحَانَ، فَتَوَضَّأَ لِلصَّلاَةِ، وَتَوَضَّأْنَا لَهَا فَصَلَّى الْعَصْرَ بَعْدَ مَا غَرَبَتِ الشَّمْسُ، ثُمَّ صَلَّى بَعْدَهَا الْمَغْرِبَ","src":"رواه البخاري ٥٩٦","pre":"عن جابر بن عبد الله رضي الله عنهما أن عمر بن الخطاب رضي الله عنه","links":[{"book":"mt_bukhari","num":596,"id":"h596"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: الترتيب واجب ويسقط بالنسيان وضيق الوقت وكثرة الفوائت","text":"وهو قول أبي حنيفة ومالك، وقريب منه قول أحمد إلا أنه لا يسقطه بالكثرة."},{"t":"qawl","label":"القول الثاني: الترتيب مستحب","text":"وهو قول الشافعي، فإن قدّم الحاضرة صحت."},{"t":"quote","text":"فَذَهَبَ مَالِكٌ إِلَى أَنَّ التَّرْتِيبَ وَاجِبٌ فِيهَا فِي الْخَمْسِ صَلَوَاتٍ فَمَا دُونَهَا، وَأَنَّهُ يَبْدَأُ بِالْمَنْسِيَّةِ وَإِنْ فَاتَ وَقْتُ الْحَاضِرَةِ حَتَّى إنَّهُ قَالَ: إِنْ ذَكَرَ الْمَنْسِيَّةَ وَهُوَ فِي الْحَاضِرَةِ فَسَدَتِ الْحَاضِرَةُ عَلَيْهِ، وَبِمِثْلِ ذَلِكَ قَالَ أَبُو حَنِيفَةَ وَالثَّوْرِيُّ إِلَّا أَنَّهُمْ رَأَوُا التَّرْتِيبَ وَاجِبًا مَعَ اتِّسَاعِ وَقْتِ الْحَاضِرَةِ، وَاتَّفَقَ هَؤُلَاءِ عَلَى سُقُوطِ وُجُوبِ التَّرْتِيبِ مَعَ النِّسْيَانِ، وَقَالَ الشَّافِعِيُّ لَا يَجِبُ التَّرْتِيبُ، وَإِنْ فَعَلَ ذَلِكَ إِذَا كَانَ فِي الْوَقْتِ مُتَّسَعٌ فَحَسَنٌ","src":"بداية المجتهد","loc":"١/١٩٤","pre":"قال ابن رشد:"},{"t":"quote","text":"الترتيب في قضاء الفوائت واجب عند أبي حنيفة ومالك، ويستحب عند الشافعي وأحمد، وقد ثبت ترتيبه في واقعة الباب غزوة الخندق، والخلاف في أنه باعتبار الوجوب أو الاستحباب","src":"العرف الشذي","loc":"١/١٩٣-١٩٤","pre":"وقال الكشميري:"},{"t":"p","text":"والمعروف من مذهب أحمد وجوب الترتيب أيضًا."},{"t":"quote","text":"فِي مَذَاهِبِ الْعُلَمَاءِ فِي قَضَاءِ الْفَوَائِتِ قَدْ ذَكَرْنَا أَنَّ مَذْهَبَنَا أَنَّهُ لَا يَجِبُ ترتيبها ولكن يستحب","src":"المجموع","loc":"٣/٧٠","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"قضاء الفوائت يجب أن يكون على الفور وأن تكون مرتبة كما فرضها الله سبحانه بحيث يصلي الفجر ثم يصلي الظهر ثم يصلي العصر","src":"فتاوى اللجنة الدائمة","loc":"٦/١٦٢","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الترتيب بين الفوائت، وبينها وبين الحاضرة، واجب ما دامت الفوائت قليلة ووقت الحاضرة متسعًا؛ لأن النبي ﷺ قضى العصر يوم الخندق ثم صلى المغرب بعدها، وقد قال: «صلوا كما رأيتموني أصلي». فمن فاتته العصر وذكرها في وقت المغرب صلى العصر ثم المغرب. ويسقط الترتيب بثلاثة أمور: النسيان، وضيق وقت الحاضرة بحيث لو قدم الفائتة خرج وقت الحاضرة، وكثرة الفوائت كمن عليه صلوات سنين فيقضيها بحسب الطاقة ولا يلزمه ترتيبها على الأيام."},{"t":"tanbih","items":[{"t":"p","text":"من دخل مع الإمام في صلاة العشاء ثم تذكر أن عليه المغرب، فالأظهر أنه يتم مع الإمام ثم يقضي المغرب، ولا يعيد العشاء؛ لأن الترتيب يسقط بخوف فوت الجماعة عند جمع من أهل العلم، ومن أعاد العشاء احتياطًا لقول من أوجب الترتيب فحسن."}]}],"refs":["البخاري ٥٩٦","بداية المجتهد (١/١٩٤)","العرف الشذي (١/١٩٣-١٩٤)","المجموع (٣/٧٠)","فتاوى اللجنة الدائمة (٦/١٦٢)"],"related":["قضاء الصلاة الفائتة: الناسي والنائم والمتعمد والمغمى عليه"],"alts":["ترتيب قضاء الصلوات","تذكر الفائتة وقت الحاضرة","الترتيب بين الفوائت"]},{"n":150,"bab":"الصلاة","sub":"القضاء","title":"المسبوق: هل ما أدركه مع الإمام أول صلاته أو آخرها؟ وكيف يقضي ما فاته؟","q":"أدركت مع الإمام ركعة من المغرب، فكيف أقضي الركعتين الباقيتين؟ وهل أجلس للتشهد بعد الأولى منهما؟ وهل أقرأ فيهما سورة مع الفاتحة؟","short":"ذهب الشافعي وأحمد في رواية وجماعة إلى أن ما أدركه المسبوق مع الإمام أول صلاته وما يأتي به بعده آخرها. وذهب أبو حنيفة وأحمد في المشهور إلى أن ما يقضيه أول صلاته في القراءة، وفرّق مالك فقال: يقضي في الأقوال (القراءة) ويبني في الأفعال (الجلوس). واتفقوا في المغرب أن من أدرك منها ركعة يأتي بركعة ثم يجلس للتشهد ثم يأتي بالثالثة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا أَتَيْتُمُ الصَّلاَةَ فَعَلَيْكُمْ بِالسَّكِينَةِ، فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَأَتِمُّوا","src":"رواه البخاري ٦٣٥","pre":"عن أبي قتادة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":635,"id":"h635"}]},{"t":"quote","text":"إِذَا أَتَيْتُمُ الصَّلاَةَ فَلاَ تَأْتُوهَا وَأَنْتُمْ تَسْعَوْنَ وَأْتُوهَا تَمْشُونَ وَعَلَيْكُمُ السَّكِينَةُ فَمَا أَدْرَكْتُمْ فَصَلُّوا وَمَا فَاتَكُمْ فَاقْضُوا","src":"رواه النسائي ٨٦١","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_nasai","num":861,"id":"h861"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: ما أدركه أول صلاته، وما يأتي به آخرها","text":"وهو قول الشافعي ورواية عن أحمد."},{"t":"qawl","label":"القول الثاني: ما يقضيه أول صلاته","text":"وهو قول أبي حنيفة والمشهور عن أحمد، فيقضي ما فاته بالفاتحة وسورة."},{"t":"qawl","label":"القول الثالث: يقضي في الأقوال ويبني في الأفعال","text":"وهو الصحيح عن مالك."},{"t":"quote","text":"هَلْ إِتْيَانُ الْمَأْمُومِ بِمَا فَاتَهُ مِنَ الصَّلَاةِ مَعَ الْإِمَامِ أَدَاءٌ أَوْ قَضَاءٌ؟ فَإِنَّ فِي ذَلِكَ ثَلَاثَةَ مَذَاهِبَ، قَوْمٌ قَالُوا: إِنَّ مَا يَأْتِي بَعْدَ سَلَامِ الْإِمَامِ هُوَ قَضَاءٌ وَإِنَّ مَا أَدْرَكَ لَيْسَ هُوَ أَوَّلَ صَلَاتِهِ. وَقَوْمٌ قَالُوا: إِنَّ الَّذِي يَأْتِي بِهِ بَعْدَ سَلَامِ الْإِمَامِ هُوَ أَدَاءٌ، وَإِنَّ مَا أَدْرَكَ هُوَ أَوَّلُ صَلَاتِهِ.","src":"بداية المجتهد","loc":"١/١٩٨","pre":"قال ابن رشد:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"اختلف أهل المذهبين فيما يقضي المسبوق بعد الفراغ عن صلاة الإمام، فأكثر الحجازيين على أن ما أدرك مع إمامه أول صلاته، وما يأتي به بعد فراغ الإمام آخر صلاته وأخذوا بالترتيب الحسي، والعراقيون على أن المدرك ما يأتي مع إمامه آخر صلاته، وما يأتي به بعد فراغ الإمام أول صلاته، وكذلك اختلف الصحابة أيضاً، ومذهب ابن مسعود مذهب العراقيين، فتمسك الحجازيون بلفظ: «ما فاتكم فأتموا» وتمسك العراقيون بما في الحديث: «وما فاتكم فاقضوا» أقول: لا تمسك لأحد في الحديث، فإن القضاء يطلق على الأداء وبالعكس أيضاً، وينبغي إحالة المسألة إلى مدارك الاجتهاد","src":"العرف الشذي","loc":"١/٣٢٨","pre":"قال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن ما يدركه المسبوق مع الإمام هو أول صلاته في الأفعال، فيجلس للتشهد على ترتيب صلاته هو، وأما القراءة فالأحسن أن يقرأ في الركعتين اللتين يقضيهما الفاتحة وسورة إذا كانتا مما فاته من الأوليين؛ جمعًا بين روايتي «فأتموا» و«فاقضوا»، وهذا معنى قول مالك، وفيه خروج من الخلاف."},{"t":"p","text":"فمن أدرك ركعة من المغرب قام بعد سلام الإمام فأتى بركعة يقرأ فيها الفاتحة وسورة ثم جلس للتشهد الأول، ثم قام فأتى بالثالثة يقرأ فيها الفاتحة، ثم تشهد وسلم. ومن أدرك ركعتين من الرباعية قام فأتى بركعتين يقرأ فيهما الفاتحة وسورة، ولو اقتصر على الفاتحة صحت صلاته."},{"t":"tanbih","items":[{"t":"p","text":"لا يقوم المسبوق لقضاء ما فاته حتى يسلم الإمام التسليمتين، ومن قام قبل سلام الإمام عمدًا بلا عذر فقد أساء، وعليه أن يرجع إذا تذكر."}]}],"refs":["البخاري ٦٣٥","النسائي ٨٦١","بداية المجتهد (١/١٩٨)","العرف الشذي (١/٣٢٨)"],"related":["آداب المشي إلى الصلاة، والركوع دون الصف لإدراك الركعة، وبم تُدرك الركعة؟","من أدرك ركعة من الجمعة، وسنة الجمعة القبلية والبعدية"],"alts":["قضاء المسبوق","كيف يصلي المسبوق","ما فات المسبوق","المسبوق في المغرب"]},{"n":151,"bab":"الصلاة","sub":"سجود السهو","title":"حكم سجود السهو، وما يُسجد له","q":"ما حكم سجود السهو؟ وهل أسجد لكل خطأ في الصلاة ولو ترك سنة؟ وما الذي لا يجبر بالسجود؟","short":"ذهب أبو حنيفة إلى أن سجود السهو واجب، وأحمد إلى وجوبه فيما يبطل عمده الصلاة، ومالك إلى وجوبه للنقص في المشهور، والشافعي إلى أنه سنة. واتفقوا على أن الأركان لا يجبرها سجود السهو بل لا بد من الإتيان بها، وأن السجود يكون لزيادة أو نقص سهوًا أو شك، وأنه لا سجود لترك المستحبات اليسيرة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّى لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم رَكْعَتَيْنِ مِنْ بَعْضِ الصَّلَوَاتِ ثُمَّ قَامَ فَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ، فَلَمَّا قَضَى صَلاَتَهُ وَنَظَرْنَا تَسْلِيمَهُ كَبَّرَ قَبْلَ التَّسْلِيمِ فَسَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ثُمَّ سَلَّمَ","src":"رواه البخاري ١٢٢٤","pre":"عن عبد الله ابن بحينة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1224,"id":"h1224"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم صَلَّى الظُّهْرَ خَمْسًا فَقِيلَ لَهُ أَزِيدَ فِي الصَّلاَةِ فَقَالَ «وَمَا ذَاكَ». قَالَ صَلَّيْتَ خَمْسًا. فَسَجَدَ سَجْدَتَيْنِ بَعْدَ مَا سَلَّمَ","src":"رواه البخاري ١٢٢٦","pre":"وعن عبد الله بن مسعود رضي الله عنه:","links":[{"book":"mt_bukhari","num":1226,"id":"h1226"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي سُجُودِ السَّهْوِ هَلْ هُوَ فَرْضٌ أَوْ سُنَّةٌ؟ فَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ سُنَّةٌ. وَذَهَبَ أَبُو حَنِيفَةَ إِلَى أَنَّهُ فَرْضٌ لَكِنْ مِنْ شُرُوطِ صِحَّةِ الصَّلَاةِ.","src":"بداية المجتهد","loc":"١/٢٠١","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سجود السهو واجب فيما شُرع له؛ لأمر النبي ﷺ به في قوله: «فليسجد سجدتين»، ومواظبته عليه، فمن تركه عمدًا فيما يجب له فقد أساء، والأحوط أن يعيد الصلاة إن طال الفصل، وإن تركه سهوًا سجد إذا ذكر قريبًا."},{"t":"p","text":"ويُشرع سجود السهو في ثلاثة أحوال: الزيادة سهوًا كمن زاد ركعة أو ركوعًا أو سجودًا أو سلم قبل التمام، والنقص كمن ترك واجبًا كالتشهد الأول، والشك في عدد الركعات. فأما الركن كالركوع والسجود وقراءة الفاتحة فلا يجبره السجود، بل يأتي به ثم يسجد للسهو. وأما السنن اليسيرة كدعاء الاستفتاح ورفع اليدين فلا يجب لها سجود، ومن سجد لترك سنة مؤكدة كالقنوت عند من يراه فلا حرج."}],"refs":["البخاري ١٢٢٤","البخاري ١٢٢٦","بداية المجتهد (١/٢٠١)","بداية المجتهد (١/٢٠٤)"],"related":["موضع سجود السهو: قبل السلام أو بعده؟","الشك في عدد الركعات: البناء على اليقين أو التحري؟"],"alts":["سجود السهو واجب أم سنة","متى يسجد للسهو","نسيان ركن في الصلاة"]},{"n":152,"bab":"الصلاة","sub":"سجود السهو","title":"موضع سجود السهو: قبل السلام أو بعده؟","q":"متى أسجد للسهو: قبل أن أسلّم أو بعد أن أسلّم؟ وإذا سجدت بعد السلام فهل أتشهد وأسلم مرة أخرى؟","short":"ذهب الشافعي إلى أن سجود السهو قبل السلام دائمًا، وأبو حنيفة إلى أنه بعد السلام دائمًا، ومالك إلى أنه قبل السلام للنقص وبعده للزيادة، وأحمد إلى أنه يُسجد في كل موضع كما سجد النبي ﷺ، وما سوى ذلك قبل السلام. والخلاف عند المحققين من المذاهب في الأفضل لا في الجواز، فمن سجد قبل السلام أو بعده أجزأه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّى لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم رَكْعَتَيْنِ مِنْ بَعْضِ الصَّلَوَاتِ ثُمَّ قَامَ فَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ، فَلَمَّا قَضَى صَلاَتَهُ وَنَظَرْنَا تَسْلِيمَهُ كَبَّرَ قَبْلَ التَّسْلِيمِ فَسَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ثُمَّ سَلَّمَ","src":"رواه البخاري ١٢٢٤","pre":"عن عبد الله ابن بحينة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1224,"id":"h1224"}]},{"t":"quote","text":"صَلَّى النَّبِيُّ صلى الله عليه وسلم إِحْدَى صَلاَتَىِ الْعَشِيِّ ـ قَالَ مُحَمَّدٌ وَأَكْثَرُ ظَنِّي الْعَصْرَ ـ رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ قَامَ إِلَى خَشَبَةٍ فِي مُقَدَّمِ الْمَسْجِدِ فَوَضَعَ يَدَهُ عَلَيْهَا وَفِيهِمْ أَبُو بَكْرٍ وَعُمَرُ ـ رضى الله عنهما ـ فَهَابَا أَنْ يُكَلِّمَاهُ وَخَرَجَ سَرَعَانُ النَّاسِ فَقَالُوا أَقَصُرَتِ الصَّلاَةُ وَرَجُلٌ يَدْعُوهُ النَّبِيُّ صلى الله عليه وسلم ذُو الْيَدَيْنِ فَقَالَ أَنَسِيتَ أَمْ قَصُرَتْ فَقَالَ «لَمْ أَنْسَ وَلَمْ تُقْصَرْ». قَالَ بَلَى قَدْ نَسِيتَ. فَصَلَّى رَكْعَتَيْنِ ثُمَّ سَلَّمَ ثُمَّ كَبَّرَ فَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ فَكَبَّرَ، ثُمَّ وَضَعَ رَأْسَهُ فَكَبَّرَ فَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ رَأْسَهُ وَكَبَّرَ","src":"رواه البخاري ١٢٢٩","pre":"وعن أبي هريرة رضي الله عنه في قصة ذي اليدين قال:","links":[{"book":"mt_bukhari","num":1229,"id":"h1229"}]},{"t":"quote","text":"إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ، فَلَمْ يَدْرِ كَمْ صَلَّى ثَلَاثًا أَمْ أَرْبَعًا، فَلْيَطْرَحِ الشَّكَّ وَلْيَبْنِ عَلَى مَا اسْتَيْقَنَ، ثُمَّ يَسْجُدُ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ، فَإِنْ كَانَ صَلَّى خَمْسًا شَفَعْنَ لَهُ صَلَاتَهُ، وَإِنْ كَانَ صَلَّى إِتْمَامًا لِأَرْبَعٍ كَانَتَا تَرْغِيمًا لِلشَّيْطَانِ","src":"رواه مسلم ٥٧١","pre":"وعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":571,"id":"h571"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي مَوَاضِعِ سُجُودِ السَّهْوِ عَلَى خَمْسَةِ أَقْوَالٍ: فَذَهَبَتِ الشَّافِعِيَّةُ إِلَى أَنَّ سُجُودَ السَّهْوِ مَوْضِعُهُ أَبَدًا قَبْلَ السَّلَامِ. وَذَهَبَتِ الْحَنَفِيَّةُ إِلَى أَنَّ مَوْضِعَهُ أَبَدًا بَعْدَ السَّلَامِ. وَفَرَّقَتِ الْمَالِكِيَّةُ فَقَالَتْ: إِنْ كَانَ السُّجُودُ لِنُقْصَانٍ كَانَ قَبْلَ السَّلَامِ، وَإِنْ كَانَ لِزِيَادَةٍ كَانَ بَعْدَ السَّلَامِ.","src":"بداية المجتهد","loc":"١/٢٠٢","pre":"قال ابن رشد:"},{"t":"quote","text":"قال المحدثون الرجحان لقول أحمد، وفي كتب المذاهب الأربعة إن خلاف السجدة قبل السلام وبعده خلاف الأولوية من كتب الأحناف ما في الهداية وكذلك في كتب الثلاثة إلا في تجريد القدوري في رواية شاذة عدم جواز السجدة قبل السلام","src":"العرف الشذي","loc":"١/٣٧٠","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"قوله: (قبل أن يسلم. . إلخ) تأول بعض الأحناف أن السلام هذا هو السلام الذي بعد سجدتي السهو لا سلام الصلاة التي هي قبلهما، أقول: إن التأويل خلاف مراد الراوي ولا يجري التأويل ولا بد من تسليم الجواز قبل السلام","src":"العرف الشذي","loc":"١/٣٧٠","pre":"وقال أيضًا منصفًا:"},{"t":"quote","text":"وَقَالَ مَالِكٌ: مَنْ وَجَبَ عَلَيْهِ سُجُودُ السَّهْوِ بَعْدَ السَّلَامِ فَتَرَكَ أَنْ يَسْجُدَهُمَا نَسِيَ ذَلِكَ فَلْيَسْجُدْهُمَا وَلَوْ بَعْدَ شَهْرٍ","src":"المدونة","loc":"١/٢٢١","pre":"وفي «المدونة» عن الإمام مالك:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ثم إذا أكمل صلاته يسجد للسهو سجدتين، هذا هو المشروع، وإن أخر سجود السهو بعد السلام فلا حرج في ذلك","src":"فتاوى نور على الدرب لابن باز","loc":"٩/٣٦٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأمر واسع، وأن سجود السهو قبل السلام وبعده جائز كله، والأفضل اتباع ما ورد: فمن ترك التشهد الأول أو نقص واجبًا سجد قبل السلام كما في حديث ابن بحينة، ومن سلم قبل تمام صلاته ثم أتمها سجد بعد السلام كما في حديث ذي اليدين، ومن زاد ركعة سهوًا ولم يعلم إلا بعد السلام سجد بعد السلام كما في حديث ابن مسعود، ومن شك فبنى على اليقين سجد قبل السلام كما في حديث أبي سعيد، ومن شك فتحرى وبنى على غالب ظنه سجد بعد السلام كما في حديث ابن مسعود. وما سوى ذلك فالأمر فيه واسع، وهذا قول أحمد الذي رجحه المحدثون."},{"t":"p","text":"ومن سجد بعد السلام كبّر وسجد سجدتين ثم سلم، وأما التشهد بعدهما ففيه خلاف، والأظهر أنه لا يلزم؛ لأن حديث ذي اليدين ليس فيه تشهد، ومن تشهد أخذًا بمذهب الحنفية ورواية في حديث عمران فلا حرج."},{"t":"tanbih","items":[{"t":"p","text":"من نسي سجود السهو حتى سلم ثم ذكر قريبًا سجد وسلم، وإن طال الفصل أو خرج من المسجد سقط عنه عند كثير من العلماء، وصلاته صحيحة."}]}],"refs":["البخاري ١٢٢٤","البخاري ١٢٢٩","مسلم ٥٧١","بداية المجتهد (١/٢٠٢)","العرف الشذي (١/٣٧٠)","المدونة (١/٢٢١)","فتاوى نور على الدرب لابن باز (٩/٣٦٩)","بداية المجتهد (١/٢٠٣)"],"related":["حكم سجود السهو، وما يُسجد له"],"alts":["سجود السهو قبل السلام","سجود السهو بعد السلام","التشهد بعد سجود السهو","نسيان سجود السهو"]},{"n":153,"bab":"الصلاة","sub":"سجود السهو","title":"من نسي التشهد الأول وقام: هل يرجع إليه؟","q":"نسيت الجلوس للتشهد الأول في صلاة الظهر وقمت للثالثة، فهل أرجع فأجلس؟ وماذا لو رجعت بعدما استتممت قائمًا؟","short":"اتفقوا على السجود لترك التشهد الأول سهوًا. واختلفوا في الرجوع: فذهب الجمهور إلى أنه يرجع ما لم يستتم قائمًا، فإذا استتم قائمًا لم يرجع وسجد للسهو، وقال بعضهم: يرجع ما لم يشرع في القراءة، وقال بعضهم: لا يرجع إذا فارق الأرض. فإن رجع بعدما استتم قائمًا ففي بطلان صلاته خلاف، والجمهور على صحتها مع الكراهة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّى لَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم رَكْعَتَيْنِ مِنْ بَعْضِ الصَّلَوَاتِ ثُمَّ قَامَ فَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ، فَلَمَّا قَضَى صَلاَتَهُ وَنَظَرْنَا تَسْلِيمَهُ كَبَّرَ قَبْلَ التَّسْلِيمِ فَسَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ثُمَّ سَلَّمَ","src":"رواه البخاري ١٢٢٤","pre":"عن عبد الله ابن بحينة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1224,"id":"h1224"}]},{"t":"quote","text":"إِذَا قَامَ الإِمَامُ فِي الرَّكْعَتَيْنِ فَإِنْ ذَكَرَ قَبْلَ أَنْ يَسْتَوِيَ قَائِمًا فَلْيَجْلِسْ فَإِنِ اسْتَوَى قَائِمًا فَلاَ يَجْلِسْ وَيَسْجُدُ سَجْدَتَىِ السَّهْوِ","src":"رواه أبو داود ١٠٣٦","pre":"وعن المغيرة بن شعبة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1036,"id":"h1036"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا مِنْ هَذَا الْبَابِ عَلَى سُجُودِ السَّهْوِ لِتَرْكِ الْجَلْسَةِ الْوُسْطَى، وَاخْتَلَفُوا فِيهَا هَلْ هِيَ فَرْضٌ أَوْ سُنَّةٌ، وَكَذَلِكَ اخْتَلَفُوا هَلْ يَرْجِعُ الْإِمَامُ إِذَا سُبِّحَ بِهِ إِلَيْهَا أَوْ لَيْسَ يَرْجِعُ؟ وَإِنْ رَجَعَ فَمَتَى يَرْجِعُ؟ قَالَ الْجُمْهُورُ: يَرْجِعُ مَا لَمْ يَسْتَوِ قَائِمًا. وَقَالَ قَوْمٌ: يَرْجِعُ مَا لَمْ يَعْقِدِ الرَّكْعَةَ الثَّالِثَةَ.","src":"بداية المجتهد","loc":"١/٢٠٥","pre":"قال ابن رشد:"},{"t":"quote","text":"وَمَنْ سَهَا عَنْ الْقَعْدَةِ الْأُولَى ثُمَّ تَذَكَّرَ وَهُوَ إلَى حَالَةِ الْقُعُودِ أَقْرَبُ عَادَ وَقَعَدَ وَتَشَهَّدَ لِأَنَّ مَا يَقْرُبُ مِنْ الشَّيْءِ يَأْخُذُ حُكْمَهُ","src":"الهداية مع فتح القدير","loc":"١/٥٠٧","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من قام عن التشهد الأول ناسيًا فذكر قبل أن يستتم قائمًا رجع فجلس وتشهد، وإن استتم قائمًا لم يرجع، بل يمضي في صلاته ويسجد للسهو؛ لحديث المغيرة، وفعل النبي ﷺ في حديث ابن بحينة، فإنه مضى ولم يرجع. فإن رجع بعدما استتم قائمًا جاهلًا أو ناسيًا لم تبطل صلاته، ويسجد للسهو، وأما إن رجع عامدًا عالمًا بعد شروعه في القراءة فالأحوط أن يعيد."},{"t":"p","text":"والمأموم يتابع إمامه في القيام وفي ترك الرجوع، ولا يجلس وحده للتشهد؛ لأن الناس قاموا مع النبي ﷺ حين قام. وإذا سبّحوا بالإمام قبل أن يستتم قائمًا رجع، وإن استتم لم يرجع، ويشير إليهم بالقيام."}],"refs":["البخاري ١٢٢٤","أبو داود ١٠٣٦","بداية المجتهد (١/٢٠٥)","الهداية مع فتح القدير (١/٥٠٧)"],"related":["حكم سجود السهو، وما يُسجد له","موضع سجود السهو: قبل السلام أو بعده؟"],"alts":["نسيان التشهد الأول","القيام للثالثة دون تشهد","الرجوع إلى التشهد"]},{"n":154,"bab":"الصلاة","sub":"سجود السهو","title":"الشك في عدد الركعات: البناء على اليقين أو التحري؟","q":"شككت وأنا أصلي: هل صليت ثلاثًا أو أربعًا؟ فماذا أفعل؟ وما حكم من يكثر عليه الشك في الصلاة؟","short":"ذهب مالك والشافعي وأحمد في رواية إلى أن الشاك يبني على اليقين وهو الأقل ثم يسجد للسهو، وذهب أبو حنيفة إلى أنه إن كان الشك يعرض له أول مرة استأنف الصلاة، وإن كثر منه تحرى وعمل بغالب ظنه، فإن لم يكن له ظن بنى على الأقل، والمشهور عن أحمد أن الإمام يتحرى والمنفرد يبني على اليقين. ومن كثر عليه الشك حتى صار وسواسًا لم يلتفت إليه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ، فَلَمْ يَدْرِ كَمْ صَلَّى ثَلَاثًا أَمْ أَرْبَعًا، فَلْيَطْرَحِ الشَّكَّ وَلْيَبْنِ عَلَى مَا اسْتَيْقَنَ، ثُمَّ يَسْجُدُ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ، فَإِنْ كَانَ صَلَّى خَمْسًا شَفَعْنَ لَهُ صَلَاتَهُ، وَإِنْ كَانَ صَلَّى إِتْمَامًا لِأَرْبَعٍ كَانَتَا تَرْغِيمًا لِلشَّيْطَانِ","src":"رواه مسلم ٥٧١","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":571,"id":"h571"}]},{"t":"quote","text":"وَإِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلْيَتَحَرَّ الصَّوَابَ، فَلْيُتِمَّ عَلَيْهِ، ثُمَّ لِيَسْجُدْ سَجْدَتَيْنِ","src":"رواه مسلم ٥٧٢","pre":"وعن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":572,"id":"h572"}]},{"t":"quote","text":"إِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي جَاءَ الشَّيْطَانُ فَلَبَسَ عَلَيْهِ حَتَّى لاَ يَدْرِيَ كَمْ صَلَّى، فَإِذَا وَجَدَ ذَلِكَ أَحَدُكُمْ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ","src":"رواه البخاري ١٢٣٢","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1232,"id":"h1232"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَإِنَّ الْفُقَهَاءَ اخْتَلَفُوا فِيمَنْ شَكَّ فِي صَلَاتِهِ فَلَمْ يَدْرِ كَمْ صَلَّى وَاحِدَةً أَوِ اثْنَتَيْنِ أَوْ ثَلَاثًا أَوْ أَرْبَعًا عَلَى ثَلَاثَةِ مَذَاهِبَ: فَقَالَ قَوْمٌ: يَبْنِي عَلَى الْيَقِينِ وَهُوَ الْأَقَلُّ وَلَا يُجْزِيهِ التَّحَرِّي، وَيَسْجُدُ سَجْدَتَيِ السَّهْوِ، وَهُوَ قَوْلُ مَالِكٍ وَالشَّافِعِيِّ وَدَاوُدَ.","src":"بداية المجتهد","loc":"١/٢٠٧-٢٠٨","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الشافعي: من شك يبني على اليقين أي على الأقل ويتشهد على ركعة فيها يتوهم القعدة، وقال أبو حنيفة: إن عرضه أولاً يستقبل الصلاة ويستأنفها، وإن كثر فبنى على أكبرِ رأيه وغالبِ ظنه وإلا فعلى الأقل، ويقعد على ما يتوهم فيه القعدة الأخيرة","src":"العرف الشذي","loc":"١/٣٧٤","pre":"وقال الكشميري في تحرير مذهب الحنفية:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"وأما دليل البناء على أكبر رأيه فما أخرجه مسلم من ابن مسعود: «من سها في الصلاة فليتحر الصواب» ، وحمله الشافعية على البناء على الأقل، وقالوا: إن التحري الأخذ بالأحرى، نقول: إنه لا يساعده اللغة أصلاً","src":"العرف الشذي","loc":"١/٣٧٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر الجمع بين حديثي أبي سعيد وابن مسعود: فمن شك في عدد الركعات وترجح عنده أحد الأمرين عمل بغالب ظنه وأتم عليه، ثم سجد للسهو بعد السلام، كما في حديث ابن مسعود. ومن لم يترجح عنده شيء بنى على الأقل لأنه المتيقن، فأتى بركعة، ثم سجد للسهو قبل السلام، كما في حديث أبي سعيد. وهذا الجمع قريب من مذهب أبي حنيفة في البناء على غالب الظن، ومن قول أحمد، وفيه عمل بالأحاديث كلها."},{"t":"p","text":"ومن كثر عليه الشك حتى صار يعتريه في كل صلاة فإنه لا يلتفت إليه، ويبني على ما يقع في نفسه أولًا، أو على الأكثر؛ دفعًا للوسواس، كما نص عليه أهل العلم. وأما الشك بعد الفراغ من الصلاة فلا يلتفت إليه إلا إذا تيقن النقص."},{"t":"tanbih","items":[{"t":"p","text":"القول باستئناف الصلاة لمن عرض له الشك أول مرة هو مذهب الحنفية، وعمدتهم آثار عن ابن عمر وغيره، ومن أخذ به فقد أحسن الاحتياط، والسنة الصحيحة الصريحة في البناء والتحري أولى بالاتباع."}]}],"refs":["مسلم ٥٧١","مسلم ٥٧٢","البخاري ١٢٣٢","بداية المجتهد (١/٢٠٧-٢٠٨)","العرف الشذي (١/٣٧٤)","بداية المجتهد (١/٢٠٨)","بداية المجتهد (١/٢٠٨-٢٠٩)","العرف الشذي (١/٣٧٥)"],"related":["موضع سجود السهو: قبل السلام أو بعده؟","حكم سجود السهو، وما يُسجد له"],"alts":["الشك في الصلاة","نسيت كم صليت","البناء على اليقين","التحري في الصلاة","الوسواس في عدد الركعات"]},{"n":155,"bab":"الصلاة","sub":"سجود السهو","title":"سهو المأموم والمسبوق، وتنبيه الإمام بالتسبيح والتصفيق","q":"سهوت خلف الإمام فهل علي سجود؟ وإذا كنت مسبوقًا وسجد الإمام للسهو فهل أسجد معه؟ وكيف ننبه الإمام إذا أخطأ، وكيف تنبهه المرأة؟","short":"اتفقوا على أن المأموم يتابع إمامه في سجود السهو، وذهب الجمهور إلى أن الإمام يتحمل عن المأموم سهوه فلا يسجد له. والمسبوق يسجد مع إمامه عند الحنفية وأحمد وجماعة ثم يقوم للقضاء، وقال مالك: إن كان السجود بعد السلام قضى ثم سجد. واتفقوا على أن الرجل ينبه الإمام بالتسبيح، وذهب الجمهور إلى أن المرأة تصفق، وقال مالك: تسبح كالرجل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَا لِي رَأَيْتُكُمْ أَكْثَرْتُمُ التَّصْفِيقَ مَنْ رَابَهُ شَىْءٌ فِي صَلاَتِهِ فَلْيُسَبِّحْ، فَإِنَّهُ إِذَا سَبَّحَ الْتُفِتَ إِلَيْهِ، وَإِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ","src":"رواه البخاري ٦٨٤","pre":"عن سهل بن سعد رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":684,"id":"h684"}]},{"t":"quote","text":"التَّسْبِيحُ لِلرِّجَالِ وَالتَّصْفِيقُ لِلنِّسَاءِ","src":"رواه البخاري ١٢٠٣، ومسلم ٤٢٢","pre":"وعن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1203,"id":"h1203"},{"book":"mt_muslim","num":422,"id":"h422"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اتَّفَقُوا عَلَى أَنَّ سُجُودَ السَّهْوِ مِنْ سُنَّةِ الْمُنْفَرِدِ وَالْإِمَامِ. وَاخْتَلَفُوا فِي الْمَأْمُومِ يَسْهُو وَرَاءَ الْإِمَامِ هَلْ عَلَيْهِ سُجُودٌ أَمْ لَا؟ فَذَهَبَ الْجُمْهُورُ إِلَى أَنَّ الْإِمَامَ يَحْمِلُ عَنْهُ السَّهْوَ، وَشَذَّ مَكْحُولٌ فَأَلْزَمَهُ السُّجُودَ فِي خَاصَّةِ نَفْسِهِ","src":"بداية المجتهد","loc":"١/٢٠٦","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المأموم إذا سها خلف إمامه فلا سجود عليه؛ لأن الإمام يتحمله عنه، إلا أن يكون مسبوقًا فسها فيما يقضيه بعد سلام إمامه فإنه يسجد لنفسه. وإذا سها الإمام تابعه المأموم في السجود ولو لم يسه هو. والمسبوق يسجد مع إمامه إذا سجد قبل السلام، فإن سجد بعد السلام قام المسبوق لقضاء ما فاته ثم سجد في آخر صلاته؛ لأنه لا يسلم مع الإمام."},{"t":"p","text":"والسنة إذا نابه شيء في الصلاة أن يسبّح الرجل فيقول: «سبحان الله»، وأن تصفق المرأة بضرب ظهر كفها على باطن الأخرى، لا بالتصفيق المعتاد في اللهو؛ لظاهر الحديث، وهو قول الجمهور. ولا تبطل صلاة المرأة إن سبّحت، وصلاة الرجل إن صفق مع الكراهة."}],"refs":["البخاري ٦٨٤","البخاري ١٢٠٣، ومسلم ٤٢٢","بداية المجتهد (١/٢٠٦)","بداية المجتهد (١/٢٠٧)"],"related":["حكم سجود السهو، وما يُسجد له","المسبوق: هل ما أدركه مع الإمام أول صلاته أو آخرها؟ وكيف يقضي ما فاته؟"],"alts":["سهو المأموم","سجود المسبوق مع الإمام","تنبيه الإمام","تصفيق المرأة في الصلاة"]},{"n":156,"bab":"الصلاة","sub":"صلاة الوتر","title":"حكم صلاة الوتر: واجبة أم سنة مؤكدة؟","q":"هل الوتر واجب يأثم تاركه، أو سنة مؤكدة؟ وما حكم من داوم على تركه؟","short":"ذهب الجمهور، ومنهم مالك والشافعي وأحمد وصاحبا أبي حنيفة، إلى أن الوتر سنة مؤكدة ليس بفرض. وذهب أبو حنيفة إلى أنه واجب (دون الفرض)، لا يكفر جاحده ولكن يأثم تاركه. واتفقوا على أنه آكد النوافل، وأنه لا ينبغي للمسلم تركه، حتى قال أحمد: من ترك الوتر عمدًا فهو رجل سوء لا ينبغي أن تقبل له شهادة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الْوِتْرُ لَيْسَ بِحَتْمٍ كَصَلاَتِكُمُ الْمَكْتُوبَةِ وَلَكِنْ سَنَّ رَسُولُ اللَّهِ صلى الله عليه وسلم وَقَالَ «إِنَّ اللَّهَ وِتْرٌ يُحِبُّ الْوِتْرَ فَأَوْتِرُوا يَا أَهْلَ الْقُرْآنِ»","src":"رواه الترمذي ٤٥٣","pre":"عن علي بن أبي طالب رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":453,"id":"h453"}]},{"t":"quote","text":"خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ «. فَقَالَ هَلْ عَلَىَّ غَيْرُهَا قَالَ» لاَ، إِلاَّ أَنْ تَطَوَّعَ","src":"رواه البخاري ٤٦","pre":"وعن طلحة بن عبيد الله رضي الله عنه في حديث الأعرابي الذي سأل عن الإسلام، قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":46,"id":"h46"}]},{"t":"quote","text":"الْوِتْرُ حَقٌّ فَمَنْ لَمْ يُوتِرْ فَلَيْسَ مِنَّا","src":"رواه أبو داود ١٤١٩","pre":"وعن بريدة رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_abudawud","num":1419,"id":"h1419"}]},{"t":"quote","text":"إِنَّ اللَّهَ أَمَدَّكُمْ بِصَلاَةٍ هِيَ خَيْرٌ لَكُمْ مِنْ حُمْرِ النَّعَمِ الْوِتْرُ جَعَلَهُ اللَّهُ لَكُمْ فِيمَا بَيْنَ صَلاَةِ الْعِشَاءِ إِلَى أَنْ يَطْلُعَ الْفَجْرُ","src":"رواه الترمذي ٤٥٢","pre":"وعن خارجة بن حذافة رضي الله عنه قال: خرج علينا رسول الله ﷺ فقال:","links":[{"book":"mt_tirmidhi","num":452,"id":"h452"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: الوتر سنة مؤكدة","text":"وهو قول الجمهور: مالك والشافعي وأحمد، وأبي يوسف ومحمد بن الحسن."},{"t":"qawl","label":"القول الثاني: الوتر واجب","text":"وهو قول أبي حنيفة، والواجب عنده دون الفرض، فلا يكفر جاحده."},{"t":"quote","text":"وَأَمَّا عَدَدُ الْوَاجِبِ مِنْهَا فَفِيهِ قَوْلَانِ: أَحَدُهُمَا: قَوْلُ مَالِكٍ وَالشَّافِعِيِّ وَالْأَكْثَرِ، وَهُوَ أَنَّ الْوَاجِبَ هِيَ الْخَمْسُ صَلَوَاتٍ فَقَطْ لَا غَيْرُ. وَالثَّانِي: قَوْلُ أَبِي حَنِيفَةَ وَأَصْحَابِهِ، وَهُوَ أَنَّ الْوِتْرَ وَاجِبٌ مَعَ الْخَمْسِ، وَاخْتِلَافُهُمْ هَلْ يُسَمَّى مَا ثَبَتَ بِالسُّنَّةِ وَاجِبًا أَوْ فَرْضًا لَا مَعْنًى لَهُ. وَسَبَبُ اخْتِلَافِهِمْ الْأَحَادِيثُ الْمُتَعَارِضَةُ","src":"بداية المجتهد","loc":"١/٩٦","pre":"قال ابن رشد:"},{"t":"quote","text":"لا نقول: إن الوتر كالمكتوبة فإن منكر الخمسة كافر ومنكر الوتر ليس بكافر، وكذلك في الخمسة والوتر فرق اعتقاداً","src":"العرف الشذي","loc":"١/٤٢٥","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وأما أدلة وجوب الوتر فكثيرة وأذكر نبذة منها، ومنها: أنه لم يثبت منه ترك الوتر سفراً ولا حضراً ولا من الصحابة ولا التابعين، وعدم تركه كاف للوجوب","src":"العرف الشذي","loc":"١/٤٢٥","pre":"وقال:"},{"t":"quote","text":"فِي مَذَاهِبِ الْعُلَمَاءِ فِي حُكْمِ الْوِتْرِ مَذْهَبُنَا أَنَّهُ لَيْسَ بِوَاجِبٍ بَلْ هُوَ سُنَّةٌ مُتَأَكِّدَةٌ وَبِهِ قَالَ جُمْهُورُ الْعُلَمَاءِ","src":"المجموع","loc":"٤/١٩","pre":"وقال النووي الشافعي في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صلاة الوتر سنة مؤكدة، ينبغي أن يحافظ المؤمن عليها، ومن يصليها يوما ويتركها يوما لا يؤاخذ","src":"فتاوى اللجنة الدائمة","loc":"٧/١٧٢","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"الوتر سنة مؤكدة في رمضان وغيره، حتى إن الإمام أحمد وغيره يقول: \"من ترك الوتر فهو رجل سوء لا ينبغي أن تقبل شهادته\" فهو سنة مؤكدة لا ينبغي للمسلم تركه لا في رمضان ولا في غيره","src":"مجموع فتاوى ابن عثيمين","loc":"١٤/١١٤","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الوتر سنة مؤكدة ليس بفرض كالصلوات الخمس؛ لقول علي رضي الله عنه: «الوتر ليس بحتم كصلاتكم المكتوبة»، ولحديث الأعرابي: «هل علي غيرها؟ قال: لا، إلا أن تطوع»، ولأن النبي ﷺ كان يوتر على راحلته، ولا يصلي المكتوبة عليها. ولكنه آكد السنن وأحبها إلى الله، وقد واظب عليه النبي ﷺ سفرًا وحضرًا، وقال: «الوتر حق»، فلا ينبغي لمسلم أن يتركه، ومن داوم على تركه فقد أساء ورغب عن سنة مؤكدة، وقول أبي حنيفة بوجوبه احتياط له وجه من الأدلة."},{"t":"tanbih","items":[{"t":"p","text":"من كان يتبع مذهب الحنفية فالوتر عنده واجب يأثم بتركه ويلزمه قضاؤه، ومن اتبع الجمهور فهو سنة مؤكدة يستحب قضاؤه، والفريقان متفقان على المحافظة عليه."}]}],"refs":["الترمذي ٤٥٣","البخاري ٤٦","أبو داود ١٤١٩","الترمذي ٤٥٢","بداية المجتهد (١/٩٦)","العرف الشذي (١/٤٢٥)","المجموع (٤/١٩)","فتاوى اللجنة الدائمة (٧/١٧٢)","مجموع فتاوى ابن عثيمين (١٤/١١٤)","بداية المجتهد (١/٩٧)"],"related":["عدد ركعات الوتر وصفته: الوصل والفصل","وقت الوتر، والوتر بعد طلوع الفجر، وقضاؤه"],"alts":["هل الوتر واجب","ترك الوتر","الوتر سنة مؤكدة"]},{"n":157,"bab":"الصلاة","sub":"صلاة الوتر","title":"عدد ركعات الوتر وصفته: الوصل والفصل","q":"كم ركعة الوتر؟ وهل يجوز أن أوتر بركعة واحدة؟ وإذا أوترت بثلاث فهل أصليها بتسليمة واحدة وتشهدين كالمغرب، أو أسلم بعد ركعتين ثم أوتر بواحدة؟","short":"ذهب أبو حنيفة إلى أن الوتر ثلاث ركعات بتسليمة واحدة وتشهدين، لا يُزاد عليها ولا يُنقص. واستحب مالك أن يوتر بثلاث يفصل بينها بسلام، ولا يوتر بواحدة ليس قبلها شفع. وذهب الشافعي وأحمد إلى أن أقل الوتر ركعة، وأدنى الكمال ثلاث، ويجوز بخمس وسبع وتسع وإحدى عشرة، موصولة ومفصولة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلاَةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً، تُوتِرُ لَهُ مَا قَدْ صَلَّى","src":"رواه البخاري ٩٩٠","pre":"عن ابن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":990,"id":"h990"}]},{"t":"quote","text":"مَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَزِيدُ فِي رَمَضَانَ وَلاَ فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلاَثًا","src":"رواه البخاري ١١٤٧","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1147,"id":"h1147"}]},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ إِلَّا فِي آخِرِهَا","src":"رواه مسلم ٧٣٧","pre":"وعنها رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":737,"id":"h737"}]},{"t":"quote","text":"الْوِتْرُ حَقٌّ عَلَى كُلِّ مُسْلِمٍ فَمَنْ أَحَبَّ أَنْ يُوتِرَ بِخَمْسٍ فَلْيَفْعَلْ وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِثَلاَثٍ فَلْيَفْعَلْ وَمَنْ أَحَبَّ أَنْ يُوتِرَ بِوَاحِدَةٍ فَلْيَفْعَلْ","src":"رواه أبو داود ١٤٢٢","pre":"وعن أبي أيوب الأنصاري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1422,"id":"h1422"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: الوتر ثلاث ركعات موصولة بتشهدين وتسليمة","text":"وهو قول أبي حنيفة وأصحابه، ومروي عن عمر وابن مسعود وأنس."},{"t":"qawl","label":"القول الثاني: الوتر ثلاث يفصل بينها بسلام، ولا يوتر بواحدة إلا بعد شفع","text":"وهو قول مالك."},{"t":"qawl","label":"القول الثالث: أقل الوتر ركعة، ويجوز بثلاث وخمس وأكثر، موصولة ومفصولة","text":"وهو قول الشافعي وأحمد، ومروي عن عثمان وسعد ومعاوية."},{"t":"quote","text":"وَأَمَّا صِفَتُهُ: فَإِنَّ مَالِكًا - رَحِمَهُ اللَّهُ - اسْتَحَبَّ أَنْ يُوتِرَ بِثَلَاثٍ يَفْصِلُ بَيْنَهَا بِسَلَامٍ. وَقَالَ أَبُو حَنِيفَةَ: الْوِتْرُ ثَلَاثُ رَكَعَاتٍ مِنْ غَيْرِ أَنْ يَفْصِلَ بَيْنَهَا بِسَلَامٍ، وَقَالَ الشَّافِعِيُّ: الْوِتْرُ رَكْعَةٌ وَاحِدَةٌ. وَلِكُلِّ قَوْلٍ مِنْ هَذِهِ سَلَفٌ مِنَ الصَّحَابَةِ وَالتَّابِعِينَ","src":"بداية المجتهد","loc":"١/٢٠٩","pre":"قال ابن رشد:"},{"t":"quote","text":"لا بد من قول وتسليم أن بعض الصحابة قائلون بوحدة ركعة الوتر، وأن بعضهم قائلون بثلاث ركعات بتسليمتين","src":"العرف الشذي","loc":"١/٤٣٥","pre":"وقال الكشميري الحنفي منصفًا:"},{"t":"quote","text":"كونه ثلاث ركعات متعين، وأما التسليم الواحد فهو المتبادر وليس بمتعين","src":"العرف الشذي","loc":"١/٤٣٥","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأمر في صفة الوتر واسع، وأن كل ما ثبت عن النبي ﷺ جائز: الركعة الواحدة بعد شفع، والثلاث، والخمس، والسبع، والتسع، والإحدى عشرة؛ لحديث أبي أيوب وأحاديث عائشة وابن عمر. والأفضل أن يصلي ما تيسر من الليل مثنى مثنى ثم يوتر بواحدة، كما في حديث ابن عمر، أو يوتر بثلاث."},{"t":"p","text":"فإن أوتر بثلاث فله أن يصليها بتسليمتين: ركعتين ثم ركعة، وله أن يصليها موصولة بتسليمة واحدة، والأحسن حينئذ ألا يجلس للتشهد إلا في آخرها؛ حتى لا يشبهها بالمغرب، وإن صلاها كالمغرب بتشهدين وتسليمة كما يفعله الحنفية فصلاته صحيحة، ولهم سلف من الصحابة. ومن صلى خلف إمام يرى الوصل تابعه ولم يخالفه."},{"t":"tanbih","items":[{"t":"p","text":"السنة أن يقرأ في الثلاث: بـ«سبح اسم ربك الأعلى» في الأولى، و«قل يا أيها الكافرون» في الثانية، و«قل هو الله أحد» في الثالثة، وزاد في بعض الروايات المعوذتين."}]}],"refs":["البخاري ٩٩٠","البخاري ١١٤٧","مسلم ٧٣٧","أبو داود ١٤٢٢","بداية المجتهد (١/٢٠٩)","العرف الشذي (١/٤٣٥)","بداية المجتهد (١/٢١١)"],"related":["حكم صلاة الوتر: واجبة أم سنة مؤكدة؟","القنوت في الوتر: حكمه وموضعه ودعاؤه"],"alts":["الوتر بركعة واحدة","الوتر ثلاث ركعات","الوتر كصلاة المغرب","صفة صلاة الوتر","كم ركعة الوتر"]},{"n":158,"bab":"الصلاة","sub":"صلاة الوتر","title":"وقت الوتر، والوتر بعد طلوع الفجر، وقضاؤه","q":"متى يبدأ وقت الوتر ومتى ينتهي؟ وهل الأفضل أن أوتر قبل النوم أو آخر الليل؟ وإذا نمت ولم أستيقظ إلا بعد الفجر فهل أوتر أو أقضيه؟","short":"اتفقوا على أن وقت الوتر من بعد صلاة العشاء إلى طلوع الفجر. ثم أجاز مالك والشافعي وأحمد صلاته بعد طلوع الفجر ما لم يصل الصبح، لمن فاته، ومنعه أبو يوسف ومحمد والثوري. ويُقضى الوتر عند أبي حنيفة وجوبًا، ويستحب قضاؤه عند الشافعي وأحمد، وقال أحمد في رواية: يقضيه شفعًا بالنهار.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ خَافَ أَنْ لَا يَقُومَ مِنْ آخِرِ اللَّيْلِ فَلْيُوتِرْ أَوَّلَهُ، وَمَنْ طَمِعَ أَنْ يَقُومَ آخِرَهُ فَلْيُوتِرْ آخِرَ اللَّيْلِ، فَإِنَّ صَلَاةَ آخِرِ اللَّيْلِ مَشْهُودَةٌ، وَذَلِكَ أَفْضَلُ","src":"رواه مسلم ٧٥٥","pre":"عن جابر رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":755,"id":"h755"}]},{"t":"quote","text":"كُلَّ اللَّيْلِ أَوْتَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ","src":"رواه البخاري ٩٩٦","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":996,"id":"h996"}]},{"t":"quote","text":"أَوْتِرُوا قَبْلَ أَنْ تُصْبِحُوا","src":"رواه مسلم ٧٥٤","pre":"وعن أبي سعيد الخدري رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":754,"id":"h754"}]},{"t":"quote","text":"مَنْ نَامَ عَنْ وِتْرِهِ أَوْ نَسِيَهُ فَلْيُصَلِّهِ إِذَا ذَكَرَهُ","src":"رواه أبو داود ١٤٣١","pre":"وعنه رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1431,"id":"h1431"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا وَقْتُهُ: فَإِنَّ الْعُلَمَاءَ اتَّفَقُوا عَلَى أَنَّ وَقْتَهُ مِنْ بَعْدِ صَلَاةِ الْعِشَاءِ إِلَى طُلُوعِ الْفَجْرِ، لِوُرُودِ ذَلِكَ مِنْ طُرُقٍ شَتَّى عَنْهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ","src":"بداية المجتهد","loc":"١/٢١١","pre":"قال ابن رشد:"},{"t":"quote","text":"ثبت وتره عليه الصلاة والسلام في كل جزء من أجزاء الليل واستقر أمره آخرة إلى آخر الليل","src":"العرف الشذي","loc":"١/٤٢٧","pre":"وقال الكشميري:"},{"t":"quote","text":"في كتب فقهنا أن من يثق بالانتباه يؤخر الوتر إلى آخر الليل، ومن لا فلا","src":"العرف الشذي","loc":"١/٤٢٦","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن وقت الوتر يبدأ بعد صلاة العشاء ولو جمعت جمع تقديم، ويمتد إلى طلوع الفجر الصادق. والأفضل لمن وثق بالاستيقاظ أن يجعله آخر الليل، ومن خاف ألا يقوم أوتر قبل أن ينام؛ لحديث جابر، وقد أوصى النبي ﷺ أبا هريرة وأبا الدرداء بالوتر قبل النوم."},{"t":"p","text":"ومن نام عن وتره أو نسيه حتى طلع الفجر فالأظهر أنه يقضيه إذا ذكره؛ لحديث أبي سعيد عند أبي داود، والأحسن أن يقضيه في النهار شفعًا؛ لما ثبت في صحيح مسلم عن عائشة أن النبي ﷺ كان إذا غلبه نوم أو وجع عن قيام الليل صلى من النهار ثنتي عشرة ركعة. ومن أوتر بعد الفجر قبل صلاة الصبح فله سلف من الصحابة كابن مسعود وابن عباس وعبادة."}],"refs":["مسلم ٧٥٥","البخاري ٩٩٦","مسلم ٧٥٤","أبو داود ١٤٣١","بداية المجتهد (١/٢١١)","بداية المجتهد (١/٢١٢)","العرف الشذي (١/٤٢٧)","العرف الشذي (١/٤٢٦)","بداية المجتهد (١/٢١٣)"],"related":["حكم صلاة الوتر: واجبة أم سنة مؤكدة؟","من أوتر أول الليل ثم قام: نقض الوتر، ولا وتران في ليلة"],"alts":["متى وقت الوتر","الوتر قبل النوم","قضاء الوتر","الوتر بعد الفجر"]},{"n":159,"bab":"الصلاة","sub":"صلاة الوتر","title":"القنوت في الوتر: حكمه وموضعه ودعاؤه","q":"هل أقنت في الوتر كل ليلة أو في رمضان فقط؟ وهل القنوت قبل الركوع أو بعده؟ وهل أرفع يدي وأكبر له؟","short":"ذهب أبو حنيفة إلى أن القنوت في الوتر واجب في السنة كلها قبل الركوع، يكبّر له رافعًا يديه. وذهب أحمد إلى استحبابه في السنة كلها بعد الركوع، ويجوز قبله. وذهب الشافعي في المشهور إلى أنه يقنت في النصف الأخير من رمضان بعد الركوع. ومنعه مالك في المشهور عنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"عَلَّمَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم كَلِمَاتٍ أَقُولُهُنَّ فِي الْوِتْرِ قَالَ ابْنُ جَوَّاسٍ فِي قُنُوتِ الْوِتْرِ «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ إِنَّكَ تَقْضِي وَلاَ يُقْضَى عَلَيْكَ وَإِنَّهُ لاَ يَذِلُّ مَنْ وَالَيْتَ وَلاَ يَعِزُّ مَنْ عَادَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ»","src":"رواه أبو داود ١٤٢٥، والترمذي ٤٦٤","pre":"عن الحسن بن علي رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":1425,"id":"h1425"},{"book":"mt_tirmidhi","num":464,"id":"h464"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: يقنت في السنة كلها قبل الركوع","text":"وهو قول أبي حنيفة وأصحابه، والقنوت عندهم واجب."},{"t":"qawl","label":"القول الثاني: يقنت في السنة كلها، والأفضل بعد الركوع","text":"وهو قول أحمد في المشهور، وجوّزه قبل الركوع."},{"t":"qawl","label":"القول الثالث: يقنت في النصف الأخير من رمضان","text":"وهو قول الشافعي في المشهور."},{"t":"quote","text":"وَأَمَّا اخْتِلَافُهُمْ فِي الْقُنُوتِ فِيهِ: فَذَهَبَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ إِلَى أَنَّهُ يَقْنُتُ فِيهِ، وَمَنَعَهُ مَالِكٌ، وَأَجَازَهُ الشَّافِعِيُّ فِي أَحَدِ قَوْلَيْهِ فِي النِّصْفِ الْآخِرِ مِنْ رَمَضَانَ، وَأَجَازَهُ قَوْمٌ فِي النِّصْفِ الْأَوَّلِ مِنْ رَمَضَانَ، وَقَوْمٌ فِي رَمَضَانَ كُلِّهِ","src":"بداية المجتهد","loc":"١/٢١٣","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الشافعية: إن القنوت في الوتر في نصف شهر بعد الركوع، ونقول: إن القنوت في السنة كلها قبل الركوع ووافقنا مالك بن أنس فإنه يقول: يقنت قبل الركوع، وأما أحمد فرجح القنوت بعد الركوع، ولنا ما روى ابن مسعود","src":"العرف الشذي","loc":"١/٤٣٧","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والقنوت في الوتر سنة، من فعله فهو أفضل، ومن ترك فلا حرج","src":"فتاوى نور على الدرب لابن باز","loc":"٨/١٨٠","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"أما القنوت في الوتر فمستحب لحديث الحسن بن علي","src":"فتاوى اللجنة الدائمة","loc":"٧/٤٥","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن القنوت في الوتر مشروع في السنة كلها؛ لحديث الحسن بن علي رضي الله عنهما في تعليمه دعاء القنوت في الوتر دون تقييد برمضان، والأحسن ألا يداوم عليه كل ليلة، بل يقنت أحيانًا ويتركه أحيانًا، ويكثر منه في رمضان؛ جمعًا بين الأقوال. ويجوز قبل الركوع وبعده، وقد ثبت هذا وهذا عن الصحابة، فمن قنت قبل الركوع كبّر رافعًا يديه ثم قنت، كما يفعله الحنفية، ومن قنت بعد الركوع رفع يديه ودعا."},{"t":"p","text":"ويدعو بدعاء الحسن: «اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولني فيمن توليت، وبارك لي فيما أعطيت، وقني شر ما قضيت، إنك تقضي ولا يقضى عليك، وإنه لا يذل من واليت، تباركت ربنا وتعاليت»، وإن دعا بدعاء عمر رضي الله عنه: «اللهم إنا نستعينك ونستغفرك...» الذي يقنت به الحنفية فحسن، وله أن يجمع بينهما، ولا يطيل الإمام إطالة تشق على الناس."},{"t":"tanbih","items":[{"t":"p","text":"من صلى خلف إمام يقنت في الوتر تابعه وأمّن على دعائه، سواء قنت قبل الركوع أو بعده؛ فإن الخلاف فيه خلاف في الأفضل."}]}],"refs":["أبو داود ١٤٢٥، والترمذي ٤٦٤","بداية المجتهد (١/٢١٣)","العرف الشذي (١/٤٣٧)","فتاوى نور على الدرب لابن باز (٨/١٨٠)","فتاوى اللجنة الدائمة (٧/٤٥)"],"related":["القنوت في صلاة الفجر، وقنوت النوازل","عدد ركعات الوتر وصفته: الوصل والفصل"],"alts":["دعاء القنوت","القنوت قبل الركوع أو بعده","قنوت الوتر في رمضان","رفع اليدين في القنوت"]},{"n":160,"bab":"الصلاة","sub":"صلاة الوتر","title":"صلاة الوتر على الراحلة والسيارة في السفر","q":"أنا مسافر في سيارة أو حافلة أو طائرة، فهل يجوز أن أصلي الوتر وأنا جالس على المقعد إلى غير القبلة؟","short":"أجاز الجمهور، ومنهم مالك والشافعي وأحمد، الوتر على الراحلة في السفر حيث توجهت به، كسائر النوافل، لثبوت ذلك من فعل النبي ﷺ. ومنعه أبو حنيفة لأن الوتر واجب عنده، والواجب لا يصلى على الراحلة إلا لعذر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ يُوتِرُ عَلَى الْبَعِيرِ","src":"رواه البخاري ٩٩٩، ومسلم ٧٠٠","pre":"عن ابن عمر رضي الله عنهما أن رسول الله ﷺ","links":[{"book":"mt_bukhari","num":999,"id":"h999"},{"book":"mt_muslim","num":700,"id":"h700"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"يجوز الوتر على الراحلة في السفر حيث توجهت به، لثبوت ذلك من فعل النبي ﷺ في الصحيحين، وهو قول الجمهور: مالك والشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"لا يُصلّى الوتر على الراحلة إلا لعذر، وهو قول أبي حنيفة وأصحابه، بناءً على أن الوتر واجب عندهم، والواجبات لا تُصلّى على الراحلة مع القدرة على النزول، كما اتفق الجميع على أن الفريضة لا تُصلّى عليها."},{"t":"quote","text":"يجوز الوتر على الراحلة عند الجمهور لا عند أبي حنيفة، والسلف أيضاً مختلفون وجماعة قليلة قائلة بالوجوب منهم الحسن البصري، والجواب من جانب أبي حنيفة أن ابن عمر من الذين يطلقون لفظ الوتر على تمام صلاة الليل فلعل ابن عمر مراده أن صلاة الليل كانت على الراحلة، وأما الوتر بخصوصه فعلى الأرض","src":"العرف الشذي","loc":"١/٤٤١","pre":"وقال الكشميري في بيان وجه مذهب الحنفية:"},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"سبب الخلاف هو الخلاف في حكم الوتر: فمن رآه سنة أجازه على الراحلة كسائر النوافل لحديث ابن عمر، ومن رآه واجبًا ألحقه بالفرائض فلم يجزه على الراحلة، وتأول حديث ابن عمر بأن المراد به صلاة الليل."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر جواز صلاة الوتر على الراحلة وفي السيارة والحافلة والطائرة في السفر، إلى جهة سيره، يومئ بالركوع والسجود ويجعل السجود أخفض؛ لحديث ابن عمر الصريح في الصحيحين، والأفضل أن يستقبل القبلة عند تكبيرة الإحرام إن تيسر. ومن كان على مذهب الحنفية فالأحوط له أن ينزل فيوتر على الأرض إذا أمكنه ذلك بلا مشقة."},{"t":"tanbih","items":[{"t":"p","text":"لا تصح الفريضة على الراحلة والسيارة لغير عذر، فإن خاف خروج الوقت ولم يمكنه النزول صلى على حسب حاله، وصلاة الفريضة في الطائرة والقطار جائزة مع استقبال القبلة والقيام إن استطاع."}]}],"refs":["البخاري ٩٩٩، ومسلم ٧٠٠","العرف الشذي (١/٤٤١)"],"related":["حكم صلاة الوتر: واجبة أم سنة مؤكدة؟","صلاة المريض: القعود، والإيماء، والصلاة على الكرسي"],"alts":["الوتر في السيارة","الوتر في الطائرة","النافلة على الراحلة"]},{"n":161,"bab":"الصلاة","sub":"صلاة الوتر","title":"من أوتر أول الليل ثم قام: نقض الوتر، ولا وتران في ليلة","q":"أوترت قبل النوم ثم استيقظت آخر الليل، فهل يجوز أن أصلي؟ وهل أعيد الوتر، أو أصلي ركعة أشفع بها وتري الأول؟","short":"ذهب الأئمة الأربعة وأكثر العلماء إلى أن من أوتر أول الليل ثم قام يصلي ما شاء شفعًا شفعًا ولا يعيد الوتر؛ لحديث «لا وتران في ليلة». وذهب بعض السلف منهم ابن عمر إلى نقض الوتر: أن يصلي ركعة يشفع بها وتره الأول، ثم يتنفل، ثم يوتر آخر صلاته.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"اجْعَلُوا آخِرَ صَلاَتِكُمْ بِاللَّيْلِ وِتْرًا","src":"رواه البخاري ٩٩٨","pre":"عن ابن عمر رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":998,"id":"h998"}]},{"t":"quote","text":"لاَ وِتْرَانِ فِي لَيْلَةٍ «. قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ . وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي الَّذِي يُوتِرُ مِنْ أَوَّلِ اللَّيْلِ ثُمَّ يَقُومُ مِنْ آخِرِهِ فَرَأَى بَعْضُ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَمَنْ بَعْدَهُمْ نَقْضَ الْوِتْرِ وَقَالُوا يُضِيفُ إِلَيْهَا رَكْعَةً وَيُصَلِّي مَا بَدَا لَهُ ثُمَّ يُوتِرُ فِي آخِرِ صَلاَتِهِ لأَنَّهُ» لاَ وِتْرَانِ فِي لَيْلَةٍ «. وَهُوَ الَّذِي ذَهَبَ إِلَيْهِ إِسْحَاقُ . وَقَالَ بَعْضُ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَغَيْرِهِمْ إِذَا أَوْتَرَ مِنْ أَوَّلِ اللَّيْلِ ثُمَّ نَامَ ثُمَّ قَامَ مِنْ آخِرِ اللَّيْلِ فَإِنَّهُ يُصَلِّي مَا بَدَا لَهُ وَلاَ يَنْقُضُ وِتْرَهُ وَيَدَعُ وِتْرَهُ عَلَى مَا كَانَ . وَهُوَ قَوْلُ سُفْيَانَ الثَّوْرِيِّ وَمَالِكِ بْنِ أَنَسٍ وَابْنِ الْمُبَارَكِ وَالشَّافِعِيِّ وَأَهْلِ الْكُوفَةِ وَأَحْمَدَ . وَهَذَا أَصَحُّ لأَنَّهُ قَدْ رُوِيَ مِنْ غَيْرِ وَجْهٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَدْ صَلَّى بَعْدَ الْوِتْرِ»","src":"رواه الترمذي ٤٧٠","pre":"وعن طلق بن علي رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_tirmidhi","num":470,"id":"h470"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَذَهَبَ أَكْثَرُ الْعُلَمَاءِ إِلَى أَنَّ الْمَرْءَ إِذَا أَوْتَرَ ثُمَّ نَامَ فَقَامَ يَتَنَفَّلُ أَنَّهُ لَا يُوتِرُ ثَانِيَةً، لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «لَا وَتَرَانِ فِي لَيْلَةٍ» .","src":"بداية المجتهد","loc":"١/٢١٤","pre":"قال ابن رشد:"},{"t":"quote","text":"بعض السلف ذهبوا إلى نقض الوتر وليس مذهب أحد من الأئمة الأربعة","src":"العرف الشذي","loc":"١/٤٤٠","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من أوتر ثم قام من الليل صلى ما كتب الله له ركعتين ركعتين، ولا يعيد الوتر ولا ينقضه؛ لحديث «لا وتران في ليلة»، وهو قول الأئمة الأربعة. والأمر بجعل آخر صلاة الليل وترًا للاستحباب، وقد ثبت أن النبي ﷺ صلى ركعتين بعد الوتر وهو جالس."},{"t":"tanbih","items":[{"t":"p","text":"من أراد أن يقوم آخر الليل وخاف ألا يستيقظ فالأولى أن يوتر قبل نومه، فإن استيقظ صلى شفعًا ولا يوتر ثانية، وإن وثق بالقيام أخّر الوتر إلى آخر الليل فهو أفضل."}]}],"refs":["البخاري ٩٩٨","الترمذي ٤٧٠","بداية المجتهد (١/٢١٤)","العرف الشذي (١/٤٤٠)"],"related":["وقت الوتر، والوتر بعد طلوع الفجر، وقضاؤه"],"alts":["الصلاة بعد الوتر","نقض الوتر","لا وتران في ليلة","التهجد بعد الوتر"]},{"n":162,"bab":"الصلاة","sub":"ركعتا الفجر","title":"سنة الفجر: فضلها، وتخفيفها، وما يُقرأ فيها","q":"ما فضل سنة الفجر؟ وما الذي أقرؤه فيها؟ وهل الأفضل تطويلها أو تخفيفها؟","short":"اتفقوا على أن ركعتي الفجر سنة، وهي آكد السنن الرواتب، بل أوجبها بعض الحنفية في رواية عن أبي حنيفة. واستحب مالك أن يقرأ فيهما بالفاتحة فقط، واستحب الشافعي وأحمد أن يقرأ مع الفاتحة «قل يا أيها الكافرون» و«قل هو الله أحد»، وقال أبو حنيفة: لا توقيت فيهما، فيقرأ ما شاء. والسنة تخفيفهما.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا","src":"رواه مسلم ٧٢٥","pre":"عن عائشة رضي الله عنها عن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":725,"id":"h725"}]},{"t":"quote","text":"لَمْ يَكُنِ النَّبِيُّ صلى الله عليه وسلم عَلَى شَىْءٍ مِنَ النَّوَافِلِ أَشَدَّ مِنْهُ تَعَاهُدًا عَلَى رَكْعَتَىِ الْفَجْرِ","src":"رواه البخاري ١١٦٣","pre":"وعنها رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1163,"id":"h1163"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم يُخَفِّفُ الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَ صَلاَةِ الصُّبْحِ حَتَّى إِنِّي لأَقُولُ هَلْ قَرَأَ بِأُمِّ الْكِتَابِ","src":"رواه البخاري ١١٦٥","pre":"وعنها رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1165,"id":"h1165"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي رَكْعَتَيِ الْفَجْرِ: قُلْ يَا أَيُّهَا الْكَافِرُونَ، وَقُلْ هُوَ اللهُ أَحَدٌ","src":"رواه مسلم ٧٢٦","pre":"وعن أبي هريرة رضي الله عنه:","links":[{"book":"mt_muslim","num":726,"id":"h726"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّ رَكْعَتَيِ الْفَجْرِ سُنَّةٌ لِمُعَاهَدَتِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - عَلَى فِعْلِهَا أَكْثَرَ مِنْهُ عَلَى سَائِرِ النَّوَافِلِ، وَلِتَرْغِيبِهِ فِيهَا، وَلِأَنَّهُ قَضَاهَا بَعْدَ طُلُوعِ الشَّمْسِ حِينَ نَامَ عَنِ الصَّلَاةِ.","src":"بداية المجتهد","loc":"١/٢١٤","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سنة الفجر آكد السنن الرواتب، فلا ينبغي تركها في حضر ولا سفر؛ لأن النبي ﷺ لم يدعها في سفره. والسنة تخفيفها، وأن يقرأ فيها بعد الفاتحة «قل يا أيها الكافرون» في الأولى، و«قل هو الله أحد» في الثانية، أو يقرأ في الأولى «قولوا آمنا بالله وما أنزل إلينا» من سورة البقرة، وفي الثانية «قل يا أهل الكتاب تعالوا إلى كلمة سواء» من سورة آل عمران، كما ثبت في صحيح مسلم. ومن اقتصر على الفاتحة أو قرأ غير ذلك صحت صلاته."},{"t":"tanbih","items":[{"t":"p","text":"يستحب أن يضطجع بعدها على شقه الأيمن قليلًا، إن تيسر له ذلك في بيته؛ لفعل النبي ﷺ، وليس ذلك بواجب."}]}],"refs":["مسلم ٧٢٥","البخاري ١١٦٣","البخاري ١١٦٥","مسلم ٧٢٦","بداية المجتهد (١/٢١٤)","بداية المجتهد (١/٢١٤-٢١٥)"],"related":["من أقيمت الصلاة ولم يصل سنة الفجر، وقضاؤها"],"alts":["فضل سنة الفجر","القراءة في سنة الفجر","تخفيف ركعتي الفجر","الضجعة بعد سنة الفجر"]},{"n":163,"bab":"الصلاة","sub":"ركعتا الفجر","title":"من أقيمت الصلاة ولم يصل سنة الفجر، وقضاؤها","q":"دخلت المسجد والإمام يصلي الفجر أو أقيمت الصلاة ولم أصل السنة، فهل أصليها ثم ألحق بالإمام؟ وإذا فاتتني فهل أقضيها بعد صلاة الصبح أو بعد طلوع الشمس؟","short":"ذهب الشافعي وأحمد إلى أنه إذا أقيمت الصلاة لم يشتغل بالسنة بل يدخل مع الإمام. وقال مالك: إن كان خارج المسجد ولم يخف فوت ركعة صلاها خارجه، وإلا دخل مع الإمام. وقال أبو حنيفة: يصليها خارج المسجد أو في ناحية منه بعيدًا عن الصفوف ما ظن أنه يدرك ركعة مع الإمام. وفي قضائها قولان: بعد الصبح، أو بعد طلوع الشمس.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا أُقِيمَتِ الصَّلَاةُ فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةُ","src":"رواه مسلم ٧١٠","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":710,"id":"h710"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم رَأَى رَجُلاً وَقَدْ أُقِيمَتِ الصَّلاَةُ يُصَلِّي رَكْعَتَيْنِ، فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صلى الله عليه وسلم لاَثَ بِهِ النَّاسُ، وَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم «الصُّبْحَ أَرْبَعًا، الصُّبْحَ أَرْبَعًا»","src":"رواه البخاري ٦٦٣","pre":"وعن عبد الله ابن بحينة رضي الله عنه:","links":[{"book":"mt_bukhari","num":663,"id":"h663"}]},{"t":"quote","text":"خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَأُقِيمَتِ الصَّلاَةُ فَصَلَّيْتُ مَعَهُ الصُّبْحَ ثُمَّ انْصَرَفَ النَّبِيُّ صلى الله عليه وسلم فَوَجَدَنِي أُصَلِّي فَقَالَ «مَهْلاً يَا قَيْسُ أَصَلاَتَانِ مَعًا» . قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي لَمْ أَكُنْ رَكَعْتُ رَكْعَتَىِ الْفَجْرِ . قَالَ «فَلاَ إِذًا»","src":"رواه الترمذي ٤٢٢","pre":"وعن قيس بن عمرو رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":422,"id":"h422"}]},{"t":"quote","text":"مَنْ لَمْ يُصَلِّ رَكْعَتَىِ الْفَجْرِ فَلْيُصَلِّهِمَا بَعْدَ مَا تَطْلُعُ الشَّمْسُ «. قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ هَذَا الْوَجْهِ . وَقَدْ رُوِيَ عَنِ ابْنِ عُمَرَ أَنَّهُ فَعَلَهُ . وَالْعَمَلُ عَلَى هَذَا عِنْدَ بَعْضِ أَهْلِ الْعِلْمِ وَبِهِ يَقُولُ سُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ وَالشَّافِعِيُّ وَأَحْمَدُ وَإِسْحَاقُ . قَالَ وَلاَ نَعْلَمُ أَحَدًا رَوَى هَذَا الْحَدِيثَ عَنْ هَمَّامٍ بِهَذَا الإِسْنَادِ نَحْوَ هَذَا إِلاَّ عَمْرَو بْنَ عَاصِمٍ الْكِلاَبِيَّ . وَالْمَعْرُوفُ مِنْ حَدِيثِ قَتَادَةَ عَنِ النَّضْرِ بْنِ أَنَسٍ عَنْ بَشِيرِ بْنِ نَهِيكٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ» مَنْ أَدْرَكَ رَكْعَةً مِنْ صَلاَةِ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ","src":"رواه الترمذي ٤٢٣","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":423,"id":"h423"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول","text":"إذا أقيمت الصلاة فلا يصلي سنة الفجر ولا غيرها، بل يدخل مع الإمام، ويقضي السنة بعد الصلاة أو بعد طلوع الشمس؛ لحديث: «إذا أقيمت الصلاة فلا صلاة إلا المكتوبة»، وهو قول الشافعي وأحمد."},{"t":"qawl","label":"القول الثاني","text":"إن كان خارج المسجد وطمع في إدراك ركعة مع الإمام صلاهما خارج المسجد أو عند بابه ثم دخل، وإن خشي فوت الصلاة دخل مع الإمام، وهو قول أبي حنيفة، وقريب منه قول مالك؛ لأن سنة الفجر آكد السنن."},{"t":"quote","text":"وَمَنْ انْتَهَى إلَى الْإِمَامِ فِي صَلَاةِ الْفَجْرِ وَهُوَ لَمْ يُصَلِّ رَكْعَتَيْ الْفَجْرِ إنْ خَشِيَ أَنْ يَفُوتَهُ رَكْعَةٌ وَيُدْرِكُ الْأُخْرَى يُصَلِّي رَكْعَتَيْ الْفَجْرِ عِنْدَ بَابِ الْمَسْجِدِ ثُمَّ يَدْخُلُ وَإِنْ خَشِيَ فَوْتَهُمَا دَخَلَ مَعَ الْإِمَامِ","src":"الفتاوى الهندية","loc":"١/١٢٠","pre":"جاء في «الفتاوى الهندية» نقلًا عن «الهداية»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه إذا أقيمت صلاة الفجر لم يشتغل المصلي بالسنة، بل يدخل مع الإمام في الفريضة؛ لحديث «إذا أقيمت الصلاة فلا صلاة إلا المكتوبة»، وإنكار النبي ﷺ على من صلى السنة والإقامة قائمة. ومن أخذ بقول الحنفية فصلاها في بيته أو خارج المسجد قبل أن يدخل، وهو يرجو إدراك الإمام، فله سلف من الصحابة كابن مسعود، وأما صلاتها داخل المسجد والإمام في الفريضة فلا ينبغي."},{"t":"p","text":"ومن فاتته سنة الفجر صلاها بعد صلاة الصبح، أو أخرها إلى ما بعد ارتفاع الشمس، والأمر في ذلك واسع؛ لحديث قيس بن عمرو، وحديث أبي هريرة، وتأخيرها إلى ارتفاع الشمس أحوط وفيه خروج من الخلاف."},{"t":"tanbih","items":[{"t":"p","text":"من شرع في سنة الفجر ثم أقيمت الصلاة، فإن كان في آخرها أتمها خفيفة، وإن كان في أولها قطعها ودخل مع الإمام، على أرجح أقوال أهل العلم."}]}],"refs":["مسلم ٧١٠","البخاري ٦٦٣","الترمذي ٤٢٢","الترمذي ٤٢٣","الفتاوى الهندية (١/١٢٠)"],"related":["سنة الفجر: فضلها، وتخفيفها، وما يُقرأ فيها","الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب"],"alts":["سنة الفجر بعد الإقامة","قضاء سنة الفجر","الصلاة والإمام يصلي","فاتتني سنة الفجر"]},{"n":164,"bab":"الصلاة","sub":"صلاة التطوع","title":"صلاة النافلة: ركعتين ركعتين، أو أربعًا بتسليمة واحدة؟","q":"هل يجوز أن أصلي النافلة أربع ركعات بتسليمة واحدة، كأربع قبل الظهر؟ أو لا بد أن أسلم من كل ركعتين؟","short":"ذهب مالك والشافعي وأحمد إلى أن الأفضل في صلاة الليل والنهار أن تكون مثنى مثنى، ويُسلم من كل ركعتين، وأجاز الشافعي وأحمد الأربع في النهار بتسليمة. وذهب أبو حنيفة إلى أن الأفضل في النهار أربع بتسليمة، وفي الليل أربع عنده وركعتان عند صاحبيه، ويجوز ما زاد على ذلك مع الكراهة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلاَةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً، تُوتِرُ لَهُ مَا قَدْ صَلَّى","src":"رواه البخاري ٩٩٠","pre":"عن ابن عمر رضي الله عنهما أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":990,"id":"h990"}]},{"t":"quote","text":"صَلاَةُ اللَّيْلِ وَالنَّهَارِ مَثْنَى مَثْنَى","src":"رواه أبو داود ١٢٩٥، والترمذي ٥٩٧","pre":"وعنه رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":1295,"id":"h1295"},{"book":"mt_tirmidhi","num":597,"id":"h597"}]},{"t":"quote","text":"مَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَزِيدُ فِي رَمَضَانَ وَلاَ فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلاَثًا","src":"رواه البخاري ١١٤٧","pre":"وعن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1147,"id":"h1147"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي النَّوَافِلِ هَلْ تُثَنَّى أَوْ تُرَبَّعَ أَوْ تُثَلَّثُ؟ فَقَالَ مَالِكٌ وَالشَّافِعِيُّ: صَلَاةُ التَّطَوُّعِ بِاللَّيْلِ وَالنَّهَارِ مَثْنَى مَثْنَى يُسَلِّمُ فِي رَكْعَتَيْنِ. وَقَالَ أَبُو حَنِيفَةَ: إِنْ شَاءَ ثَنَّى أَوْ ثَلَّثَ أَوْ رَبَّعَ أَوْ سَدَّسَ أَوْ ثَمَّنَ دُونَ أَنْ يَفْصِلَ بَيْنَهَا بِسَلَامٍ. وَفَرَّقَ قَوْمٌ بَيْنَ صَلَاةِ اللَّيْلِ وَصَلَاةِ النَّهَارِ فَقَالُوا: صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى، وَصَلَاةُ النَّهَارِ أَرْبَعٌ","src":"بداية المجتهد","loc":"١/٢١٧","pre":"قال ابن رشد:"},{"t":"quote","text":"وتمسك الأحناف في مذهب أبي حنيفة بحديث عائشة حديث الصحيحين: كان يصلي أربعاً فلا تسأل عن حسنهن وطولهن. إلخ، وأقول: إنه ليس بحجة لنا، فإن الحديث مبهم ولا يدل على أنها بتسليمة واحدة بل هي محمولة عندي على هيأة التراويح في زماننا أي التسليمة على ركعتين ركعتين والترويحة على أربعة","src":"العرف الشذي","loc":"١/٤١٠","pre":"وقال الكشميري الحنفي منصفًا:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأفضل في النافلة ليلًا ونهارًا أن تُصلى ركعتين ركعتين، يسلم من كل ركعتين؛ لحديث ابن عمر: «صلاة الليل والنهار مثنى مثنى»، ولأن أكثر ما نُقل من صلاة النبي ﷺ كان كذلك. ومن صلى أربعًا بتسليمة واحدة في النهار، كالأربع قبل الظهر، فصلاته صحيحة وهو مذهب الحنفية، ولهم في ذلك آثار عن الصحابة. وأما في الليل فالأولى ألا يزيد على ركعتين بتسليمة إلا في الوتر."}],"refs":["البخاري ٩٩٠","أبو داود ١٢٩٥، والترمذي ٥٩٧","البخاري ١١٤٧","بداية المجتهد (١/٢١٧)","العرف الشذي (١/٤١٠)"],"related":["السنن الرواتب: عددها، وأربع قبل الظهر، وسنة العصر","عدد ركعات الوتر وصفته: الوصل والفصل"],"alts":["النافلة أربع ركعات بتسليمة","صلاة الليل مثنى مثنى","التسليم في النافلة"]},{"n":165,"bab":"الصلاة","sub":"صلاة التطوع","title":"السنن الرواتب: عددها، وأربع قبل الظهر، وسنة العصر","q":"كم عدد السنن المؤكدة مع الفرائض؟ وهل سنة الظهر القبلية ركعتان أو أربع؟ وهل للعصر سنة؟","short":"اتفق العلماء على مشروعية السنن الرواتب مع الفرائض، واختلفوا في عددها: فعند الحنفية اثنتا عشرة ركعة: ركعتان قبل الفجر، وأربع قبل الظهر بتسليمة وركعتان بعدها، وركعتان بعد المغرب، وركعتان بعد العشاء. وعند الشافعية والحنابلة عشر ركعات مؤكدة كحديث ابن عمر، والأربع قبل الظهر مستحبة. وأما الأربع قبل العصر فمستحبة غير مؤكدة عند الجميع.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَا مِنْ عَبْدٍ مُسْلِمٍ يُصَلِّي لِلَّهِ كُلَّ يَوْمٍ ثِنْتَيْ عَشْرَةَ رَكْعَةً تَطَوُّعًا، غَيْرَ فَرِيضَةٍ، إِلَّا بَنَى اللهُ لَهُ بَيْتًا فِي الْجَنَّةِ، أَوْ إِلَّا بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ","src":"رواه مسلم ٧٢٨","pre":"عن أم حبيبة رضي الله عنها قالت: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_muslim","num":728,"id":"h728-3"}]},{"t":"quote","text":"مَنْ ثَابَرَ عَلَى ثِنْتَىْ عَشْرَةَ رَكْعَةً مِنَ السُّنَّةِ بَنَى اللَّهُ لَهُ بَيْتًا فِي الْجَنَّةِ أَرْبَعِ رَكَعَاتٍ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ","src":"رواه الترمذي ٤١٤","pre":"وعن عائشة رضي الله عنها قالت: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":414,"id":"h414"}]},{"t":"quote","text":"حَفِظْتُ مِنَ النَّبِيِّ صلى الله عليه وسلم عَشْرَ رَكَعَاتٍ رَكْعَتَيْنِ قَبْلَ الظُّهْرِ، وَرَكْعَتَيْنِ بَعْدَهَا، وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ، وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ فِي بَيْتِهِ، وَرَكْعَتَيْنِ قَبْلَ صَلاَةِ الصُّبْحِ","src":"رواه البخاري ١١٨٠","pre":"وعن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1180,"id":"h1180"}]},{"t":"quote","text":"كَانَ لاَ يَدَعُ أَرْبَعًا قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ قَبْلَ الْغَدَاةِ. تَابَعَهُ ابْنُ أَبِي عَدِيٍّ وَعَمْرٌو عَنْ شُعْبَةَ","src":"رواه البخاري ١١٨٢","pre":"وعن عائشة رضي الله عنها أن النبي ﷺ","links":[{"book":"mt_bukhari","num":1182,"id":"h1182"}]},{"t":"quote","text":"رَحِمَ اللَّهُ امْرَأً صَلَّى قَبْلَ الْعَصْرِ أَرْبَعًا","src":"رواه أبو داود ١٢٧١، والترمذي ٤٣٠","pre":"وعن ابن عمر رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1271,"id":"h1271"},{"book":"mt_tirmidhi","num":430,"id":"h430"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: الرواتب المؤكدة اثنتا عشرة ركعة، منها أربع قبل الظهر","text":"وهو قول الحنفية، واختاره كثير من المحققين لحديثي أم حبيبة وعائشة."},{"t":"qawl","label":"القول الثاني: الرواتب المؤكدة عشر ركعات، منها ركعتان قبل الظهر","text":"وهو المشهور عند الشافعية والحنابلة لحديث ابن عمر، والزيادة عليها مستحبة."},{"t":"p","text":"وأما المالكية فلا يحددون للرواتب عددًا معينًا سوى ركعتي الفجر، ويستحبون التنفل قبل الظهر وبعدها وقبل العصر وبعد المغرب."},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"سبب الخلاف اختلاف الأحاديث في عدد ما قبل الظهر: ففي حديث ابن عمر ركعتان، وفي حديثي عائشة وأم حبيبة أربع، ويجمع بينهما بأن النبي ﷺ كان يصلي في بيته أربعًا، وربما صلى ركعتين، فحدّث كل صحابي بما رأى."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن السنن الرواتب المؤكدة اثنتا عشرة ركعة: أربع قبل الظهر، وركعتان بعدها، وركعتان بعد المغرب، وركعتان بعد العشاء، وركعتان قبل الفجر؛ لحديث أم حبيبة وعائشة، وفيه زيادة على حديث ابن عمر، والزيادة من الثقة مقبولة. ومن صلى قبل الظهر ركعتين فقد أتى بأصل السنة. ويستحب أن يصلي قبل العصر أربعًا؛ لحديث «رحم الله امرأ صلى قبل العصر أربعًا»، وليست من الرواتب المؤكدة."},{"t":"p","text":"والأفضل أن تُصلى الرواتب في البيت؛ لقوله ﷺ: «أفضل الصلاة صلاة المرء في بيته إلا المكتوبة»، ومن صلاها في المسجد فلا حرج. وتسقط الرواتب في السفر إلا سنة الفجر والوتر عند كثير من العلماء."}],"refs":["مسلم ٧٢٨","الترمذي ٤١٤","البخاري ١١٨٠","البخاري ١١٨٢","أبو داود ١٢٧١، والترمذي ٤٣٠"],"related":["صلاة النافلة: ركعتين ركعتين، أو أربعًا بتسليمة واحدة؟","سنة الفجر: فضلها، وتخفيفها، وما يُقرأ فيها","من أدرك ركعة من الجمعة، وسنة الجمعة القبلية والبعدية"],"alts":["عدد السنن الرواتب","سنة الظهر أربع أو ركعتان","سنة العصر","السنن المؤكدة"]},{"n":166,"bab":"الصلاة","sub":"صلاة التطوع","title":"تحية المسجد: حكمها، وفي أوقات النهي، وبعد سنة الفجر","q":"دخلت المسجد بعد صلاة العصر أو بعد الفجر، فهل أصلي تحية المسجد؟ وإذا صليت سنة الفجر في البيت ثم دخلت المسجد فهل أصلي التحية؟ وإذا جلست ناسيًا فهل أقوم لها؟","short":"الجمهور على أن تحية المسجد سنة مؤكدة ليست بواجبة، وأوجبها أهل الظاهر. واختلفوا في فعلها في أوقات النهي: فأجازها الشافعي وأحمد في رواية لأنها ذات سبب، ومنعها أبو حنيفة ومالك وأحمد في المشهور. وتجزئ عنها الفريضة والسنة الراتبة عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَرْكَعْ رَكْعَتَيْنِ قَبْلَ أَنْ يَجْلِسَ","src":"رواه البخاري ٤٤٤، ومسلم ٧١٤","pre":"عن أبي قتادة السلمي رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":444,"id":"h444"},{"book":"mt_muslim","num":714,"id":"h714"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَالْجُمْهُورُ عَلَى أَنَّ رَكْعَتَيْ دُخُولِ الْمَسْجِدِ مَنْدُوبٌ إِلَيْهَا مِنْ غَيْرِ إِيجَابٍ، وَذَهَبَ أَهْلُ الظَّاهِرِ إِلَى وُجُوبِهَا","src":"بداية المجتهد","loc":"١/٢١٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن تحية المسجد سنة مؤكدة لكل من دخل المسجد وأراد الجلوس، ولا ينبغي تركها؛ للأمر بها في الحديث، والصارف عن الوجوب حديث الأعرابي: «هل علي غيرها؟ قال: لا، إلا أن تطوع». والأقرب أنها تُصلى في أوقات النهي أيضًا؛ لأنها ذات سبب، والأمر بها خاص بها، وقد أمر النبي ﷺ الداخل يوم الجمعة والإمام يخطب أن يصليها، ومن تركها في وقت النهي احتياطًا لمذهب الحنفية والمالكية فقد أخذ بقول معتبر، وله أن يذكر الله ولا يجلس إن شاء."},{"t":"p","text":"ومن دخل وقد أقيمت الصلاة دخل مع الإمام وأجزأته الفريضة عن التحية، ومن صلى الراتبة أجزأته عنها، ومن جلس ناسيًا أو جاهلًا قام فصلاها إن لم يطل الفصل."},{"t":"tanbih","items":[{"t":"p","text":"لا تُشرع تحية المسجد للمسجد الحرام لمن أراد الطواف، فتحيته الطواف، فإن لم يرد الطواف صلى ركعتين."}]}],"refs":["البخاري ٤٤٤، ومسلم ٧١٤","بداية المجتهد (١/٢١٨)","بداية المجتهد (١/٢١٨-٢١٩)"],"related":["الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب","الإنصات للخطبة، ورد السلام، وتحية المسجد والإمام يخطب"],"alts":["تحية المسجد بعد العصر","حكم تحية المسجد","تحية المسجد في وقت النهي"]},{"n":167,"bab":"الصلاة","sub":"قيام رمضان","title":"قيام رمضان (التراويح): فضله، وعدد ركعاته","q":"كم عدد ركعات التراويح: ثمان أو عشرون؟ وهل يجوز أن أصلي ثماني ركعات فقط؟ وهل يُنكر على من صلى عشرين؟","short":"أجمع العلماء على استحباب قيام رمضان. واختار أبو حنيفة والشافعي وأحمد ومالك في أحد قوليه عشرين ركعة سوى الوتر، وهو ما استقر عليه العمل في عهد عمر رضي الله عنه، واختار مالك في قوله الآخر ستًّا وثلاثين، وهو عمل أهل المدينة. وثبت عن النبي ﷺ أنه لم يزد في رمضان ولا غيره على إحدى عشرة ركعة. والصحيح أنه لا حدّ لعدد ركعاته.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ «. قَالَ ابْنُ شِهَابٍ فَتُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَالأَمْرُ عَلَى ذَلِكَ، ثُمَّ كَانَ الأَمْرُ عَلَى ذَلِكَ فِي خِلاَفَةِ أَبِي بَكْرٍ وَصَدْرًا مِنْ خِلاَفَةِ عُمَرَ ـ رضى الله عنهما»","src":"رواه البخاري ٢٠٠٩","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":2009,"id":"h2009"}]},{"t":"quote","text":"سَأَلَ عَائِشَةَ ـ رضى الله عنها ـ كَيْفَ كَانَتْ صَلاَةُ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي رَمَضَانَ فَقَالَتْ مَا كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَزِيدُ فِي رَمَضَانَ وَلاَ فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلاَثًا","src":"رواه البخاري ١١٤٧","pre":"عن أبي سلمة بن عبد الرحمن أنه","links":[{"book":"mt_bukhari","num":1147,"id":"h1147"}]},{"t":"quote","text":"خَرَجْتُ مَعَ عُمَرَ بْنِ الْخَطَّابِ ـ رضى الله عنه ـ لَيْلَةً فِي رَمَضَانَ، إِلَى الْمَسْجِدِ، فَإِذَا النَّاسُ أَوْزَاعٌ مُتَفَرِّقُونَ يُصَلِّي الرَّجُلُ لِنَفْسِهِ، وَيُصَلِّي الرَّجُلُ فَيُصَلِّي بِصَلاَتِهِ الرَّهْطُ فَقَالَ عُمَرُ إِنِّي أَرَى لَوْ جَمَعْتُ هَؤُلاَءِ عَلَى قَارِئٍ وَاحِدٍ لَكَانَ أَمْثَلَ. ثُمَّ عَزَمَ فَجَمَعَهُمْ عَلَى أُبَىِّ بْنِ كَعْبٍ، ثُمَّ خَرَجْتُ مَعَهُ لَيْلَةً أُخْرَى، وَالنَّاسُ يُصَلُّونَ بِصَلاَةِ قَارِئِهِمْ، قَالَ عُمَرُ نِعْمَ الْبِدْعَةُ هَذِهِ، وَالَّتِي يَنَامُونَ عَنْهَا أَفْضَلُ مِنَ الَّتِي يَقُومُونَ. يُرِيدُ آخِرَ اللَّيْلِ، وَكَانَ النَّاسُ يَقُومُونَ أَوَّلَهُ","src":"رواه البخاري ٢٠١٠","pre":"وعن عبد الرحمن بن عبد القاري قال:","links":[{"book":"mt_bukhari","num":2010,"id":"h2010"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَجْمَعُوا عَلَى أَنَّ قِيَامَ شَهْرِ رَمَضَانَ مُرَغَّبٌ فِيهِ أَكْثَرُ مِنْ سَائِرِ الْأَشْهُرِ لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ» . وَأَنَّ التَّرَاوِيحَ الَّتِي جَمَعَ عَلَيْهَا عُمَرُ بْنُ الْخَطَّابِ النَّاسَ مُرَغَّبٌ فِيهَا، وَإِنْ كَانُوا اخْتَلَفُوا أَيٌّ أَفْضَلُ: أَهِيَ أَوِ الصَّلَاةُ آخِرَ اللَّيْلِ؟","src":"بداية المجتهد","loc":"١/٢١٩","pre":"قال ابن رشد:"},{"t":"quote","text":"وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي قِيَامِ رَمَضَانَ فَرَأَى بَعْضُهُمْ أَنْ يُصَلِّيَ إِحْدَى وَأَرْبَعِينَ رَكْعَةً مَعَ الْوِتْرِ . وَهُوَ قَوْلُ أَهْلِ الْمَدِينَةِ وَالْعَمَلُ عَلَى هَذَا عِنْدَهُمْ بِالْمَدِينَةِ . وَأَكْثَرُ أَهْلِ الْعِلْمِ عَلَى مَا رُوِيَ عَنْ عُمَرَ وَعَلِيٍّ وَغَيْرِهِمَا مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم عِشْرِينَ رَكْعَةً . وَهُوَ قَوْلُ سُفْيَانَ الثَّوْرِيِّ وَابْنِ الْمُبَارَكِ وَالشَّافِعِيِّ . وَقَالَ الشَّافِعِيُّ وَهَكَذَا أَدْرَكْتُ بِبَلَدِنَا بِمَكَّةَ يُصَلُّونَ عِشْرِينَ رَكْعَةً . وَقَالَ أَحْمَدُ رُوِيَ فِي هَذَا أَلْوَانٌ . وَلَمْ يَقْضِ فِيهِ بِشَيْءٍ","src":"رواه الترمذي ٨٠٦","pre":"وقال الإمام الترمذي:","links":[{"book":"mt_tirmidhi","num":806,"id":"h806"}]},{"t":"quote","text":"لم يقل أحد من الأئمة الأربعة بأقل من عشرين ركعة في التراويح، وإليه جمهور الصحابة رضوان الله عنهم، وقال مالك بن أنس: بستة وثلاثين ركعة فإن تعامل أهل المدينة أنهم كانوا يركعون أربع ركعات انفراداً في الترويحة، وأما أهل مكة فكانوا يطوفون بالبيت في الترويحات، ثم إن حديث: «يصلي أربعاً فلا تسأل عن حسنهن وطولهن» فيه تصريح أنه حال رمضان، فإن السائل سأل عن حال رمضان وغيره كما عند الترمذي ومسلم ص (254) ، ولا مناص من تسليم أن تراويحه كانت ثمانية ركعات ولم يثبت في رواية من الروايات أنه صلى التراويح والتهجد على حدة في رمضان بل طول التراويح، وبين التراويح والتهجد في عهده لم يكن فرق في الركعات بل في الوقت والصفة أي التراويح تكون بالجماعة في المسجد بخلاف التهجد، وإن الشروع في التراويح يكون في أول الليل وفي التهجد في آخر الليل نعم ثبت عن بعض التابعين الجمع بين التراويح والتهجد في رمضان، ثم مأخوذ الأئمة الأربعة من عشرين ركعة هو عمل الفاروق الأعظم، وأما النبي - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - فصح عنه ثمان ركعات، وأما عشرون ركعة فهو عنه بسند ضعيف وعلى ضعفه اتفاق، وأما فعل الفاروق فقد تلقاه الأمة بالقبول","src":"العرف الشذي","loc":"٢/٢٠٨-٢٠٩","pre":"وقال العلامة الكشميري الحنفي، وهو من أنصف ما قيل في المسألة:"},{"t":"quote","text":"أقول: إن سنة الخلفاء الراشدين أيضاً تكون سنة الشريعة لما في الأصول أن السنة سنة الخلفاء وسنته، وقد صح في الحديث: «عليكم بسنتي وسنة الخلفاء الراشدين المهديين» فيكون فعل الفاروق الأعظم أيضاً سنة","src":"العرف الشذي","loc":"٢/٢٠٩","pre":"وقال:"},{"t":"quote","text":"مَذْهَبُنَا أَنَّهَا عِشْرُونَ رَكْعَةً بِعَشْرِ تَسْلِيمَاتٍ غَيْرَ الْوِتْرِ وَذَلِكَ خَمْسُ تَرْوِيحَاتٍ وَالتَّرْوِيحَةُ أَرْبَعُ رَكَعَاتٍ بِتَسْلِيمَتَيْنِ","src":"المجموع","loc":"٤/٣٢","pre":"وقال النووي الشافعي في «المجموع» في مذاهب العلماء في عدد ركعات التراويح:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فدل ذلك على أنه لا حرج في الزيادة على ثلاث عشرة في رمضان وفي غيره، فمن صلى عشرين ركعة أو أكثر من ذلك فلا بأس","src":"مجموع فتاوى ابن باز","loc":"٦/١٢٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن قيام رمضان لا حدّ لعدد ركعاته، فمن صلى إحدى عشرة أو ثلاث عشرة ركعة فقد وافق ما ثبت من فعل النبي ﷺ، ومن صلى عشرين ركعة مع الوتر فقد وافق ما استقر عليه العمل في عهد عمر رضي الله عنه بمحضر الصحابة، وهو قول جمهور الأئمة، ومن صلى ستًّا وثلاثين فقد وافق عمل أهل المدينة؛ فكل ذلك سنة حسنة، والأفضل ما كان أخشع وأطول قيامًا وأحسن قراءة."},{"t":"p","text":"ولا يجوز أن يُنكر بعض المسلمين على بعض في هذه المسألة، ولا أن يُبدَّع من صلى عشرين، ولا أن يُعاب من صلى ثمانيًا، فإنها مسألة اجتهادية للسلف فيها سعة. ومن صلى خلف إمام يصلي عشرين فالأفضل أن يتم معه حتى ينصرف؛ لقوله ﷺ: «إنه من قام مع الإمام حتى ينصرف كتب له قيام ليلة»."}],"refs":["البخاري ٢٠٠٩","البخاري ١١٤٧","البخاري ٢٠١٠","بداية المجتهد (١/٢١٩)","الترمذي ٨٠٦","العرف الشذي (٢/٢٠٨-٢٠٩)","العرف الشذي (٢/٢٠٩)","المجموع (٤/٣٢)","مجموع فتاوى ابن باز (٦/١٢٩)"],"related":["صلاة التراويح جماعة في المسجد، وقيام آخر الليل","صلاة النافلة: ركعتين ركعتين، أو أربعًا بتسليمة واحدة؟"],"alts":["عدد ركعات التراويح","التراويح ثمان أو عشرون","صلاة التراويح","قيام الليل في رمضان"]},{"n":168,"bab":"الصلاة","sub":"قيام رمضان","title":"صلاة التراويح جماعة في المسجد، وقيام آخر الليل","q":"هل الأفضل أن أصلي التراويح مع الإمام في المسجد أو في بيتي وحدي؟ وإذا صليت مع الإمام والوتر معه، فهل أقوم آخر الليل؟","short":"اتفقوا على مشروعية صلاة التراويح جماعة في المسجد، وهي سنة عمر رضي الله عنه وأصلها من فعل النبي ﷺ ليالي. واختار أبو حنيفة وأحمد وابن المبارك وجمهور أصحاب الشافعي أن صلاتها مع الإمام أفضل، واختار مالك والشافعي في قول أن صلاتها في البيت أفضل لمن كان قارئًا ولا تتعطل الجماعة بتخلفه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّهُ مَنْ قَامَ مَعَ الإِمَامِ حَتَّى يَنْصَرِفَ كُتِبَ لَهُ قِيَامُ لَيْلَةٍ","src":"رواه الترمذي ٨٠٦","pre":"عن أبي ذر رضي الله عنه أن رسول الله ﷺ لما صلى بهم ليلة في رمضان قال:","links":[{"book":"mt_tirmidhi","num":806,"id":"h806"}]},{"t":"quote","text":"صَلُّوا أَيُّهَا النَّاسُ فِي بُيُوتِكُمْ، فَإِنَّ أَفْضَلَ الصَّلاَةِ صَلاَةُ الْمَرْءِ فِي بَيْتِهِ إِلاَّ الْمَكْتُوبَةَ","src":"رواه البخاري ٧٣١","pre":"وعن زيد بن ثابت رضي الله عنه لما اجتمع الناس لصلاة النبي ﷺ في رمضان قال:","links":[{"book":"mt_bukhari","num":731,"id":"h731"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَارَ ابْنُ الْمُبَارَكِ وَأَحْمَدُ وَإِسْحَاقُ الصَّلاَةَ مَعَ الإِمَامِ فِي شَهْرِ رَمَضَانَ . وَاخْتَارَ الشَّافِعِيُّ أَنْ يُصَلِّيَ الرَّجُلُ وَحْدَهُ إِذَا كَانَ قَارِئًا","src":"رواه الترمذي ٨٠٦","pre":"قال الإمام الترمذي:","links":[{"book":"mt_tirmidhi","num":806,"id":"h806"}]},{"t":"quote","text":"وأقول: إن مراد قول عمر إنكم اخترتم النوم آخر الليل ولو كنتم أطلتم التراويح إلى آخر الليل لكان أولى وأفضل، ويشرعون من أول الليل ولا كلفة في هذا الشرح أصلاً","src":"العرف الشذي","loc":"٢/٢٠٩","pre":"وقال الكشميري في معنى قول عمر: «والتي تنامون عنها أفضل»:"},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"سبب الخلاف معارضة فضل الجماعة وإحياء الشعيرة، وما استقر عليه عمل الصحابة في عهد عمر، لعموم قوله ﷺ: «أفضل الصلاة صلاة المرء في بيته إلا المكتوبة»، وقد ترك النبي ﷺ الخروج إليهم خشية أن تفرض عليهم، فلما زالت الخشية بوفاته جمعهم عمر."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة التراويح مع الإمام في المسجد أفضل؛ لحديث أبي ذر: «من قام مع الإمام حتى ينصرف كتب له قيام ليلة»، ولأنها صارت من شعائر رمضان الظاهرة التي أجمع عليها الصحابة، والعلة التي ترك النبي ﷺ لأجلها الجماعة قد زالت. ومن صلاها في بيته لعذر أو لأنه يطيل القراءة ويخشع أكثر فلا حرج عليه."},{"t":"p","text":"ومن أوتر مع الإمام ثم قام آخر الليل صلى ما شاء ركعتين ركعتين ولا يعيد الوتر، ومن أراد أن يجعل وتره آخر الليل فله أن يشفع وتر الإمام بركعة يقوم بها بعد سلامه، ثم يوتر آخر الليل، وكلاهما حسن."}],"refs":["الترمذي ٨٠٦","البخاري ٧٣١","العرف الشذي (٢/٢٠٩)"],"related":["قيام رمضان (التراويح): فضله، وعدد ركعاته","من أوتر أول الليل ثم قام: نقض الوتر، ولا وتران في ليلة"],"alts":["التراويح في البيت","التراويح مع الإمام","قيام آخر الليل في رمضان","التهجد في رمضان"]},{"n":169,"bab":"الصلاة","sub":"صلاة الكسوف","title":"صلاة الكسوف: حكمها وصفتها، وهل في كل ركعة ركوعان؟","q":"كسفت الشمس، فكيف نصلي صلاة الكسوف؟ وهل نركع في كل ركعة ركوعين، أو نصليها ركعتين كسائر الصلوات؟","short":"اتفقوا على أن صلاة كسوف الشمس سنة مؤكدة، وأنها تُصلى جماعة. ثم ذهب مالك والشافعي وأحمد وجمهور أهل الحجاز إلى أنها ركعتان، في كل ركعة قيامان وقراءتان وركوعان وسجدتان، وذهب أبو حنيفة والكوفيون إلى أنها ركعتان كهيئة النافلة بركوع واحد في كل ركعة، مع تطويل القراءة والدعاء حتى تنجلي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"خَسَفَتِ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَصَلَّى رَسُولُ اللَّهِ صلى الله عليه وسلم بِالنَّاسِ، فَقَامَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ وَهْوَ دُونَ الْقِيَامِ الأَوَّلِ، ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ، وَهْوَ دُونَ الرُّكُوعِ الأَوَّلِ، ثُمَّ سَجَدَ فَأَطَالَ السُّجُودَ، ثُمَّ فَعَلَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ مَا فَعَلَ فِي الأُولَى، ثُمَّ انْصَرَفَ وَقَدِ انْجَلَتِ الشَّمْسُ، فَخَطَبَ النَّاسَ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ «إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَادْعُوا اللَّهَ وَكَبِّرُوا، وَصَلُّوا وَتَصَدَّقُوا»","src":"رواه البخاري ١٠٤٤","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1044,"id":"h1044"}]},{"t":"quote","text":"كُنَّا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَانْكَسَفَتِ الشَّمْسُ، فَقَامَ النَّبِيُّ صلى الله عليه وسلم يَجُرُّ رِدَاءَهُ حَتَّى دَخَلَ الْمَسْجِدَ، فَدَخَلْنَا فَصَلَّى بِنَا رَكْعَتَيْنِ، حَتَّى انْجَلَتِ الشَّمْسُ فَقَالَ صلى الله عليه وسلم «إِنَّ الشَّمْسَ وَالْقَمَرَ لاَ يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ، فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا، وَادْعُوا، حَتَّى يُكْشَفَ مَا بِكُمْ»","src":"رواه البخاري ١٠٤٠","pre":"وعن أبي بكرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1040,"id":"h1040"}]},{"t":"quote","text":"كُسِفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَجَعَلَ يُصَلِّي رَكْعَتَيْنِ رَكْعَتَيْنِ وَيَسْأَلُ عَنْهَا حَتَّى انْجَلَتْ","src":"رواه أبو داود ١١٩٣","pre":"وعن النعمان بن بشير رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":1193,"id":"h1193"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: ركعتان، في كل ركعة ركوعان","text":"وهو قول مالك والشافعي وأحمد وجمهور أهل الحجاز، لحديث عائشة وابن عباس في الصحيحين."},{"t":"qawl","label":"القول الثاني: ركعتان كسائر النوافل بركوع واحد","text":"وهو قول أبي حنيفة والكوفيين، لحديث أبي بكرة والنعمان بن بشير وسمرة."},{"t":"qawl","label":"القول الثالث: يتخير بين الصفات الواردة كلها","text":"وهو قول الطبري وطائفة من المحققين."},{"t":"quote","text":"اتَّفَقُوا عَلَى أَنَّ صَلَاةَ كُسُوفِ الشَّمْسِ سُنَّةٌ، وَأَنَّهَا فِي جَمَاعَةٍ، وَاخْتَلَفُوا فِي صِفَتِهَا، وَفِي صِفَةِ الْقِرَاءَةِ فِيهَا، وَفِي الْأَوْقَاتِ الَّتِي تَجُوزُ فِيهَا، وَهَلْ مِنْ شُرُوطِهَا الْخُطْبَةُ أَمْ لَا؟ وَهَلْ كُسُوفُ الْقَمَرِ فِي ذَلِكَ كَكُسُوفِ الشَّمْسِ؟ فَفِي ذَلِكَ خَمْسُ مَسَائِلَ أَصُولٌ فِي هَذَا الْبَابِ.","src":"بداية المجتهد","loc":"١/٢٢٠","pre":"قال ابن رشد:"},{"t":"quote","text":"الجماعة في كسوف الشمس سنة عندنا، ويقيم الجماعة مقيم الجمعة، وإن كانوا في القرى صلوا وحداناً، وقال القاضي شمس الدين السروجي الحنفي في شرح الهداية: إن الصلاة في كسوف الشمس واجبة، ثم صلاة الكسوف عندنا كسائر الصلوات بركوع واحد في ركعة، وقال الشافعية والمالكية والحنابلة بركوعين في ركعة","src":"العرف الشذي","loc":"٢/٥٧","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة الكسوف ركعتان، في كل ركعة قيامان وقراءتان وركوعان وسجدتان؛ لأن هذه الصفة هي الأصح والأشهر، رواها في الصحيحين عائشة وابن عباس وجابر وغيرهم، وفيها زيادة علم على من روى ركوعًا واحدًا، والمثبت مقدم. ومن صلاها ركعتين بركوع واحد في كل ركعة، كما يقول الحنفية، فقد أجزأته وله دليل من حديث أبي بكرة والنعمان، ولا ينكر عليه."},{"t":"p","text":"وصفتها على الأظهر: يكبر للإحرام، ويستفتح، ويقرأ الفاتحة وسورة طويلة، ثم يركع ركوعًا طويلًا، ثم يرفع فيقول: سمع الله لمن حمده، ربنا ولك الحمد، ثم يقرأ الفاتحة وسورة أقصر من الأولى، ثم يركع ركوعًا أقصر من الأول، ثم يرفع ثم يسجد سجدتين طويلتين، ثم يقوم إلى الثانية فيفعل مثل ذلك، ثم يتشهد ويسلم. ويُنادى لها: «الصلاة جامعة»، ولا أذان لها ولا إقامة."},{"t":"tanbih","items":[{"t":"p","text":"يستحب عند الكسوف الإكثار من الدعاء والتكبير والاستغفار والصدقة والعتق؛ لأمر النبي ﷺ بذلك، وإذا انجلت الشمس وهم في الصلاة أتموها خفيفة."}]}],"refs":["البخاري ١٠٤٤","البخاري ١٠٤٠","أبو داود ١١٩٣","بداية المجتهد (١/٢٢٠)","العرف الشذي (٢/٥٧)","بداية المجتهد (١/٢٢١)"],"related":["القراءة في صلاة الكسوف، ووقتها، والخطبة بعدها","خسوف القمر، والصلاة للزلازل والآيات"],"alts":["كيفية صلاة الكسوف","صلاة الخسوف","ركوعان في كل ركعة","كسوف الشمس"]},{"n":170,"bab":"الصلاة","sub":"صلاة الكسوف","title":"القراءة في صلاة الكسوف، ووقتها، والخطبة بعدها","q":"هل يجهر الإمام بالقراءة في صلاة الكسوف؟ وإذا حدث الكسوف بعد صلاة العصر فهل نصلي؟ وهل يخطب الإمام بعدها؟","short":"ذهب أبو حنيفة ومالك والشافعي إلى الإسرار بالقراءة في كسوف الشمس، وذهب أحمد وأبو يوسف ومحمد بن الحسن وإسحاق إلى الجهر. وأجاز الشافعي صلاتها في أوقات النهي لأنها ذات سبب، ومنعها أبو حنيفة ومالك. واستحب الشافعي الخطبة بعدها، ولم يرها أبو حنيفة ومالك سنة لها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"جَهَرَ النَّبِيُّ صلى الله عليه وسلم فِي صَلاَةِ الْخُسُوفِ بِقِرَاءَتِهِ، فَإِذَا فَرَغَ مِنْ قِرَاءَتِهِ كَبَّرَ فَرَكَعَ، وَإِذَا رَفَعَ مِنَ الرَّكْعَةِ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ. ثُمَّ يُعَاوِدُ الْقِرَاءَةَ فِي صَلاَةِ الْكُسُوفِ، أَرْبَعَ رَكَعَاتٍ فِي رَكْعَتَيْنِ وَأَرْبَعَ سَجَدَاتٍ","src":"رواه البخاري ١٠٦٥","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1065,"id":"h1065"}]},{"t":"quote","text":"ثُمَّ انْصَرَفَ وَقَدِ انْجَلَتِ الشَّمْسُ، فَخَطَبَ النَّاسَ، فَحَمِدَ اللَّهَ، وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ «إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَادْعُوا اللَّهَ وَكَبِّرُوا، وَصَلُّوا وَتَصَدَّقُوا»","src":"رواه البخاري ١٠٤٤","pre":"وعنها رضي الله عنها في صفة صلاته ﷺ:","links":[{"book":"mt_bukhari","num":1044,"id":"h1044"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي الْقِرَاءَةِ فِيهَا، فَذَهَبَ مَالِكٌ وَالشَّافِعِيُّ إِلَى أَنَّ الْقِرَاءَةَ فِيهَا سِرٌّ. وَقَالَ أَبُو يُوسُفَ وَمُحَمَّدُ بْنُ الْحَسَنِ وأحمد وَإِسْحَاقُ بْنُ رَاهَوَيْهِ: يَجْهَرُ بِالْقِرَاءَةِ فِيهَا","src":"بداية المجتهد","loc":"١/٢٢١","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أحمد وصاحبا أبي حنيفة: يجهر بالقراءة، وقال الشافعي وأبو حنيفة: بالإسرار في القراءة، وللقائلين بالجهر رواية عائشة، وللقائلين بالإسرار رواية سمرة","src":"العرف الشذي","loc":"٢/٦٢","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الإمام يجهر بالقراءة في صلاة الكسوف؛ لحديث عائشة الصريح في البخاري: «جهر النبي ﷺ في صلاة الخسوف بقراءته»، والمثبت مقدم على النافي، ومن أسرّ فلا حرج عليه، فقد قال به جمهور الأئمة."},{"t":"p","text":"والأظهر أنها تُصلى متى وُجد الكسوف ولو في وقت النهي؛ لأنها ذات سبب، وقد قال النبي ﷺ: «فإذا رأيتموهما فصلوا»، ومن أخذ بقول المانعين فاشتغل في وقت النهي بالدعاء والذكر والاستغفار حتى ينجلي فله ذلك. ويستحب للإمام أن يعظ الناس بعد الصلاة ويذكّرهم؛ لفعل النبي ﷺ، سواء سُمّيت خطبة أو موعظة."}],"refs":["البخاري ١٠٦٥","البخاري ١٠٤٤","بداية المجتهد (١/٢٢١)","العرف الشذي (٢/٦٢)","بداية المجتهد (١/٢٢٣)","بداية المجتهد (١/٢٢٢)"],"related":["صلاة الكسوف: حكمها وصفتها، وهل في كل ركعة ركوعان؟","الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب"],"alts":["الجهر في صلاة الكسوف","صلاة الكسوف بعد العصر","خطبة الكسوف"]},{"n":171,"bab":"الصلاة","sub":"صلاة الكسوف","title":"خسوف القمر، والصلاة للزلازل والآيات","q":"خسف القمر ليلًا، فهل نصلي له جماعة في المسجد كالكسوف؟ وهل تشرع الصلاة عند الزلازل والعواصف الشديدة؟","short":"ذهب الشافعي وأحمد وداود إلى أن خسوف القمر يصلى له جماعة كصلاة كسوف الشمس، وذهب أبو حنيفة ومالك إلى أنه لا يُجمع له، بل يصلي الناس فرادى ركعتين ركعتين. وأما الزلزلة ونحوها من الآيات فاستحب أبو حنيفة الصلاة لها فرادى، وصلى لها أحمد جماعة في رواية، ولم يرها مالك والشافعي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ، لاَ يَنْخَسِفَانِ لِمَوْتِ أَحَدٍ وَلاَ لِحَيَاتِهِ، فَإِذَا رَأَيْتُمْ ذَلِكَ فَادْعُوا اللَّهَ وَكَبِّرُوا، وَصَلُّوا وَتَصَدَّقُوا","src":"رواه البخاري ١٠٤٤","pre":"عن عائشة رضي الله عنها أن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1044,"id":"h1044"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي كُسُوفِ الْقَمَرِ: فَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ يُصَلَّى لَهُ فِي جَمَاعَةٍ، وَعَلَى نَحْوِ مَا يُصَلَّى فِي كُسُوفِ الشَّمْسِ، وَبِهِ قَالَ أَحْمَدُ وَدَاوُدُ وَجَمَاعَةٌ. وَذَهَبَ مَالِكٌ وَأَبُو حَنِيفَةَ إِلَى أَنَّهُ لَا يُصَلَّى لَهُ فِي جَمَاعَةٍ، وَاسْتَحَبّوا أَنْ يُصَلِّيَ النَّاسُ لَهُ أَفْذَاذًا رَكْعَتَيْنِ كَسَائِرِ الصَّلَوَاتِ النَّافِلَةِ","src":"بداية المجتهد","loc":"١/٢٢٣-٢٢٤","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أبو حنيفة ومالك لا جماعة في كسوف القمر وقال الشافعي: إن في خسوف القمر أيضاً جماعة، وتمسك بالعموم","src":"العرف الشذي","loc":"٢/٦١","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن خسوف القمر يُصلى له كما يصلى لكسوف الشمس، جماعة في المسجد؛ لأن النبي ﷺ قرن بينهما في الأمر بالصلاة فقال: «إن الشمس والقمر آيتان... فإذا رأيتم ذلك فصلوا»، ولم يفرق بينهما. ومن صلى له فرادى، كما يقول الحنفية والمالكية، فقد أتى بالمشروع."},{"t":"p","text":"وأما الزلازل والعواصف والظلمة الشديدة فيشرع عندها الفزع إلى الذكر والدعاء والاستغفار والصدقة، ومن صلى لها فرادى أو جماعة فله سلف من الصحابة، فقد صح عن ابن عباس رضي الله عنهما أنه صلى للزلزلة بالبصرة، ولا ينبغي أن يُتخذ ذلك عادة ثابتة لكل حادث."}],"refs":["البخاري ١٠٤٤","بداية المجتهد (١/٢٢٣-٢٢٤)","العرف الشذي (٢/٦١)","بداية المجتهد (١/٢٢٤)"],"related":["صلاة الكسوف: حكمها وصفتها، وهل في كل ركعة ركوعان؟"],"alts":["صلاة خسوف القمر","الصلاة عند الزلزال","صلاة الآيات"]},{"n":172,"bab":"الصلاة","sub":"صلاة الاستسقاء","title":"صلاة الاستسقاء: هل هي سنة؟ وهل فيها خطبة، وقبل الصلاة أو بعدها؟","q":"تأخر المطر في بلدنا، فهل نخرج لصلاة الاستسقاء؟ وكيف تكون؟ وهل يكفي الدعاء في خطبة الجمعة؟","short":"أجمعوا على أن الخروج للاستسقاء والدعاء والتضرع سنة. ثم ذهب الجمهور، ومنهم مالك والشافعي وأحمد وصاحبا أبي حنيفة، إلى أن من سنته صلاة ركعتين جماعة، وقال أبو حنيفة: الاستسقاء دعاء واستغفار، والصلاة فيه جائزة غير مسنونة سنة مؤكدة. واختلفوا في الخطبة: فقال مالك والشافعي: بعد الصلاة كالعيد، وقال الليث وابن المنذر وأحمد في رواية: قبلها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم خَرَجَ إِلَى الْمُصَلَّى فَاسْتَسْقَى، فَاسْتَقْبَلَ الْقِبْلَةَ، وَقَلَبَ رِدَاءَهُ، وَصَلَّى رَكْعَتَيْنِ","src":"رواه البخاري ١٠١٢","pre":"عن عبد الله بن زيد رضي الله عنه:","links":[{"book":"mt_bukhari","num":1012,"id":"h1012"}]},{"t":"quote","text":"خَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم مُتَبَذِّلاً مُتَوَاضِعًا مُتَضَرِّعًا حَتَّى أَتَى الْمُصَلَّى - زَادَ عُثْمَانُ فَرَقِيَ عَلَى الْمِنْبَرِ ثُمَّ اتَّفَقَا - وَلَمْ يَخْطُبْ خُطَبَكُمْ هَذِهِ وَلَكِنْ لَمْ يَزَلْ فِي الدُّعَاءِ وَالتَّضَرُّعِ وَالتَّكْبِيرِ ثُمَّ صَلَّى رَكْعَتَيْنِ كَمَا يُصَلِّي فِي الْعِيدِ","src":"رواه أبو داود ١١٦٥","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":1165,"id":"h1165"}]},{"t":"quote","text":"أَنَّ رَجُلاً، دَخَلَ يَوْمَ الْجُمُعَةِ مِنْ باب كَانَ وُجَاهَ الْمِنْبَرِ، وَرَسُولُ اللَّهِ صلى الله عليه وسلم قَائِمٌ يَخْطُبُ فَاسْتَقْبَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم قَائِمًا فَقَالَ يَا رَسُولَ اللَّهِ، هَلَكَتِ الْمَوَاشِي وَانْقَطَعَتِ السُّبُلُ، فَادْعُ اللَّهَ يُغِيثُنَا. قَالَ فَرَفَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَيْهِ فَقَالَ «اللَّهُمَّ اسْقِنَا، اللَّهُمَّ اسْقِنَا، اللَّهُمَّ اسْقِنَا»","src":"رواه البخاري ١٠١٣","pre":"وعن أنس بن مالك رضي الله عنه:","links":[{"book":"mt_bukhari","num":1013,"id":"h1013"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَجْمَعَ الْعُلَمَاءُ عَلَى أَنَّ الْخُرُوجَ إِلَى الِاسْتِسْقَاءِ، وَالْبُرُوزَ عَنِ الْمِصْرِ، وَالدُّعَاءَ إِلَى اللَّهِ - تَعَالَى - وَالتَّضَرُّعَ إِلَيْهِ فِي نُزُولِ الْمَطَرِ سُنَّةٌ سَنَّهَا رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، وَاخْتَلَفُوا فِي الصَّلَاةِ فِي الِاسْتِسْقَاءِ، فَالْجُمْهُورُ عَلَى أَنَّ ذَلِكَ مِنْ سُنَّةِ الْخُرُوجِ إِلَى الِاسْتِسْقَاءِ إِلَّا أَبَا حَنِيفَةَ فَإِنَّهُ قَالَ: لَيْسَ مِنْ سُنَّتِهِ الصَّلَاةُ","src":"بداية المجتهد","loc":"١/٢٢٤-٢٢٥","pre":"قال ابن رشد:"},{"t":"quote","text":"وأما الأحناف ففي مختصر القدوري: والصلاة ليست بسنة، قال في الهداية: لأنه - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - صلى مرة لا أخرى فلا تكون سنة إلخ، أقول لا تكون سنة مؤكدة وإلا فمطلق السنة والاستحباب لا يمكن إنكاره لما قال صاحب الهداية: إنه - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - صلى مرة، وقال المحقق ابن أمير الحاج: نسب البعض إلينا أن الصلاة عندنا منفية وهذا غلط، والصحيح أن الصلاة عندنا مستحبة","src":"العرف الشذي","loc":"٢/٥٤","pre":"وقال الكشميري الحنفي في تحرير مذهبهم:"},{"t":"h","text":"سبب الخلاف"},{"t":"quote","text":"واعلم أن الشافعي حكم بسنة الصلاة في الاستسقاء، لأنه لم يلاحظ القسمين الآخرين للاستسقاء، وأما أبو حنيفة فلاحظ القسمين الآخرين فحكم باستحباب الصلاة بعكس ما في الوتر وهذا من مدارك الاجتهاد","src":"العرف الشذي","loc":"٢/٥٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الاستسقاء يكون على ثلاث صفات كلها مشروعة: أكملها أن يخرج الإمام بالناس إلى المصلى متبذلين متواضعين متضرعين، فيصلي بهم ركعتين ويخطب ويدعو ويحول رداءه، كما في حديث عبد الله بن زيد وابن عباس. والثانية: الدعاء بالسقيا في خطبة الجمعة، كما في حديث أنس. والثالثة: الدعاء والاستغفار من غير صلاة ولا خطبة، كما فعل عمر رضي الله عنه. والخطبة يجوز أن تكون قبل الصلاة أو بعدها، وكلاهما ورد."},{"t":"p","text":"ويستحب قبل الخروج التوبة من المعاصي، ورد المظالم، والصدقة، والصيام، والإكثار من الاستغفار؛ فإن الذنوب سبب منع القطر، والاستغفار سبب نزوله، كما دلّ عليه قول نوح عليه السلام لقومه في سورة نوح."}],"refs":["البخاري ١٠١٢","أبو داود ١١٦٥","البخاري ١٠١٣","بداية المجتهد (١/٢٢٤-٢٢٥)","العرف الشذي (٢/٥٤)","بداية المجتهد (١/٢٢٥-٢٢٦)","بداية المجتهد (١/٢٢٥)","العرف الشذي (٢/٥٥)"],"related":["صفة صلاة الاستسقاء: التكبير فيها، والقراءة، وتحويل الرداء"],"alts":["صلاة الاستسقاء","طلب المطر","خطبة الاستسقاء","الدعاء بالمطر في الجمعة"]},{"n":173,"bab":"الصلاة","sub":"صلاة الاستسقاء","title":"صفة صلاة الاستسقاء: التكبير فيها، والقراءة، وتحويل الرداء","q":"هل نكبر في صلاة الاستسقاء تكبيرات زوائد كصلاة العيد؟ وهل يجهر فيها بالقراءة؟ وما معنى تحويل الرداء، ومتى يكون؟ وهل يحوّل المأمومون أرديتهم؟","short":"اتفق القائلون بصلاة الاستسقاء على الجهر فيها بالقراءة، وقال أبو حنيفة بالإسرار في رواية. واختلفوا في التكبير: فقال الشافعي وأحمد في رواية: يكبر فيها كالعيد، وقال مالك وأحمد في رواية ومحمد بن الحسن: كسائر الصلوات. واتفقوا على أن من سننها أن يستقبل الإمام القبلة ويدعو ويحوّل رداءه، ولم ير أبو حنيفة التحويل، ورآه صاحباه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"خَرَجَ النَّبِيُّ صلى الله عليه وسلم يَسْتَسْقِي فَتَوَجَّهَ إِلَى الْقِبْلَةِ يَدْعُو، وَحَوَّلَ رِدَاءَهُ، ثُمَّ صَلَّى رَكْعَتَيْنِ جَهَرَ فِيهِمَا بِالْقِرَاءَةِ","src":"رواه البخاري ١٠٢٤","pre":"عن عبد الله بن زيد رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1024,"id":"h1024"}]},{"t":"quote","text":"وَلَمْ يَخْطُبْ خُطَبَكُمْ هَذِهِ وَلَكِنْ لَمْ يَزَلْ فِي الدُّعَاءِ وَالتَّضَرُّعِ وَالتَّكْبِيرِ ثُمَّ صَلَّى رَكْعَتَيْنِ كَمَا يُصَلِّي فِي الْعِيدِ","src":"رواه أبو داود ١١٦٥","pre":"وعن ابن عباس رضي الله عنهما في صفة استسقائه ﷺ:","links":[{"book":"mt_abudawud","num":1165,"id":"h1165"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّ الْقِرَاءَةَ فِيهَا جَهْرا، وَاخْتَلَفُوا هَلْ يُكَبِّرُ فِيهَا كَمَا يُكَبِّرُ فِي الْعِيدَيْنِ؟ فَذَهَبَ مَالِكٌ إِلَى أَنَّهُ يُكَبِّرُ فِيهَا كَمَا يُكَبِّرُ فِي سَائِرِ الصَّلَوَاتِ، وَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّهُ يُكَبِّرُ فِيهَا كَمَا يُكَبِّرُ فِي الْعِيدَيْنِ","src":"بداية المجتهد","loc":"١/٢٢٦","pre":"قال ابن رشد:"},{"t":"quote","text":"وأما القراءة في الاستسقاء فقال أبو حنيفة بالإسرار، وقال الشافعي وصاحبا أبي حنيفة بالجهر، وهو مذهب مالك وأحمد، وقال محمد بالخطبتين بعد الصلاة وتحويل الرداء وتحويل الرداء مذكور في مختصر القدوري والهداية","src":"العرف الشذي","loc":"٢/٥٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة الاستسقاء ركعتان يجهر فيهما بالقراءة؛ لحديث عبد الله بن زيد في البخاري، وأن له أن يكبر فيهما التكبيرات الزوائد كالعيد؛ لقول ابن عباس: «كما يصلي في العيد»، وإن لم يكبر فلا حرج. ويستقبل الإمام القبلة في أثناء الخطبة أو بعدها فيدعو رافعًا يديه مبالغًا في الرفع، ويحول رداءه فيجعل ما على يمينه على شماله؛ تفاؤلًا بتحول الحال من الجدب إلى الخصب، ويحول الناس أرديتهم معه عند الجمهور."},{"t":"p","text":"ومن أدعية الاستسقاء الثابتة: «اللهم اسقنا، اللهم أغثنا»، و«اللهم اسق عبادك وبهائمك، وانشر رحمتك، وأحي بلدك الميت». ويجوز التوسل إلى الله بدعاء الرجل الصالح الحي الحاضر، كما توسل عمر رضي الله عنه بالعباس رضي الله عنه."}],"refs":["البخاري ١٠٢٤","أبو داود ١١٦٥","بداية المجتهد (١/٢٢٦)","العرف الشذي (٢/٥٥)"],"related":["صلاة الاستسقاء: هل هي سنة؟ وهل فيها خطبة، وقبل الصلاة أو بعدها؟"],"alts":["تحويل الرداء","التكبير في صلاة الاستسقاء","دعاء الاستسقاء"]},{"n":174,"bab":"الصلاة","sub":"صلاة العيدين","title":"حكم صلاة العيد، ومن تجب عليه، وخروج النساء إليها","q":"ما حكم صلاة العيد؟ وهل تجب على أهل القرى والمسافرين؟ وهل تخرج النساء إلى مصلى العيد؟","short":"ذهب أبو حنيفة إلى أن صلاة العيد واجبة على من تجب عليه الجمعة من أهل الأمصار، وذهب مالك والشافعي إلى أنها سنة مؤكدة، وذهب أحمد في المشهور إلى أنها فرض كفاية. واختلفوا فيمن يُخاطب بها: فقاسها الحنفية على الجمعة فخصوها بأهل المصر، ورأى الشافعي أنه يصليها الحاضر والمسافر وأهل البوادي والمرأة في بيتها. وثبت أمر النبي ﷺ النساء بالخروج إليها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَخْرُجُ يَوْمَ الْفِطْرِ وَالأَضْحَى إِلَى الْمُصَلَّى، فَأَوَّلُ شَىْءٍ يَبْدَأُ بِهِ الصَّلاَةُ ثُمَّ يَنْصَرِفُ، فَيَقُومُ مُقَابِلَ النَّاسِ، وَالنَّاسُ جُلُوسٌ عَلَى صُفُوفِهِمْ، فَيَعِظُهُمْ وَيُوصِيهِمْ وَيَأْمُرُهُمْ، فَإِنْ كَانَ يُرِيدُ أَنْ يَقْطَعَ بَعْثًا قَطَعَهُ، أَوْ يَأْمُرَ بِشَىْءٍ أَمَرَ بِهِ، ثُمَّ يَنْصَرِفُ","src":"رواه البخاري ٩٥٦","pre":"عن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":956,"id":"h956"}]},{"t":"quote","text":"أُمِرْنَا أَنْ نُخْرِجَ، الْعَوَاتِقَ وَذَوَاتِ الْخُدُورِ. وَعَنْ أَيُّوبَ عَنْ حَفْصَةَ بِنَحْوِهِ. وَزَادَ فِي حَدِيثِ حَفْصَةَ قَالَ أَوْ قَالَتِ الْعَوَاتِقَ وَذَوَاتِ الْخُدُورِ، وَيَعْتَزِلْنَ الْحُيَّضُ الْمُصَلَّى","src":"رواه البخاري ٩٧٤","pre":"وعن أم عطية رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":974,"id":"h974"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: صلاة العيد واجبة على الأعيان","text":"وهو قول أبي حنيفة، ورواية عن أحمد، واختاره ابن تيمية."},{"t":"qawl","label":"القول الثاني: سنة مؤكدة","text":"وهو قول مالك والشافعي."},{"t":"qawl","label":"القول الثالث: فرض كفاية","text":"وهو المشهور من مذهب أحمد."},{"t":"quote","text":"وَاخْتَلَفُوا فِيمَنْ تَجِبُ عَلَيْهِ صَلَاةُ الْعِيدِ - أَعْنِي: وُجُوبَ السُّنَّةِ - فَقَالَتْ طَائِفَةٌ: يُصَلِّيهَا الْحَاضِرُ وَالْمُسَافِرُ، وَبِهِ قَالَ الشَّافِعِيُّ وَالْحَسَنُ الْبَصْرِيُّ، وَكَذَلِكَ قَالَ الشَّافِعِيُّ: إِنَّهُ يُصَلِّيهَا أَهْلُ الْبَوَادِي، وَمَنْ لَا يُجَمِّعُ حَتَّى الْمَرْأَةَ فِي بَيْتِهَا.","src":"بداية المجتهد","loc":"١/٢٢٩","pre":"قال ابن رشد:"},{"t":"quote","text":"أصل مذهبنا جواز خروج النسوان للعيدين، ونهى أرباب الفتوى، وفي مذهب غيرنا تضييق مما في مذهبنا","src":"العرف الشذي","loc":"٢/٤٠","pre":"وقال الكشميري الحنفي في خروج النساء:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صلاة العيد فرض كفاية عند كثير من أهل العلم، ويجوز التخلف من بعض الأفراد عنها، لكن حضوره لها ومشاركته لإخوانه المسلمين سنة مؤكدة لا ينبغي تركها إلا لعذر شرعي، وذهب بعض أهل العلم إلى أن صلاة العيد فرض عين كصلاة الجمعة","src":"مجموع فتاوى ابن باز","loc":"١٣/٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"ولا شك أن هذا يدل على تأكيد خروج النساء لصلاة العيدين ليشهدن الخير ودعوة المسلمين","src":"مجموع فتاوى ابن باز","loc":"١٣/٨","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة العيد واجبة على الرجال القادرين، أو هي آكد السنن التي لا ينبغي تركها؛ لمواظبة النبي ﷺ عليها، وأمره بها النساء حتى العواتق والحيّض، فالرجال أولى. ويصليها أهل المدن والقرى المستوطنون جماعة، وأما المسافر فلا تلزمه، وإن صلاها مع الناس فحسن."},{"t":"p","text":"ويستحب للنساء الخروج إليها متسترات غير متطيبات ولا متبرجات؛ لأمر النبي ﷺ بذلك، وتعتزل الحائض المصلى وتشهد الخير ودعوة المسلمين. ومنع بعض فقهاء الحنفية المتأخرين خروجهن إنما كان لفساد الزمان، وأصل مذهبهم الجواز، فإن أُمنت الفتنة فالسنة خروجهن."}],"refs":["البخاري ٩٥٦","البخاري ٩٧٤","بداية المجتهد (١/٢٢٩)","العرف الشذي (٢/٤٠)","مجموع فتاوى ابن باز (١٣/٧)","مجموع فتاوى ابن باز (١٣/٨)"],"related":["التكبيرات الزوائد في صلاة العيد، ورفع اليدين معها","اجتماع العيد والجمعة في يوم واحد"],"alts":["حكم صلاة العيد","خروج المرأة لصلاة العيد","صلاة العيد للمسافر","هل صلاة العيد واجبة"]},{"n":175,"bab":"الصلاة","sub":"صلاة العيدين","title":"التكبيرات الزوائد في صلاة العيد، ورفع اليدين معها","q":"كم تكبيرة في صلاة العيد؟ وهل تكون قبل القراءة أو بعدها؟ وهل أرفع يدي مع كل تكبيرة؟ وماذا أقول بين التكبيرات؟","short":"ذهب مالك وأحمد إلى أن الزوائد سبع في الأولى بتكبيرة الإحرام، وخمس في الثانية سوى تكبيرة القيام، قبل القراءة في الركعتين، وقال الشافعي: سبع في الأولى سوى تكبيرة الإحرام وخمس في الثانية. وذهب أبو حنيفة إلى أنها ثلاث في الأولى بعد تكبيرة الإحرام قبل القراءة، وثلاث في الثانية بعد القراءة قبل الركوع، وهو مروي عن ابن مسعود.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"التَّكْبِيرُ فِي الْفِطْرِ سَبْعٌ فِي الأُولَى وَخَمْسٌ فِي الآخِرَةِ وَالْقِرَاءَةُ بَعْدَهُمَا كِلْتَيْهِمَا","src":"رواه أبو داود ١١٥١","pre":"عن عبد الله بن عمرو بن العاص رضي الله عنهما قال: قال نبي الله ﷺ:","links":[{"book":"mt_abudawud","num":1151,"id":"h1151"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم كَبَّرَ فِي الْعِيدَيْنِ فِي الأُولَى سَبْعًا قَبْلَ الْقِرَاءَةِ وَفِي الآخِرَةِ خَمْسًا قَبْلَ الْقِرَاءَةِ","src":"رواه الترمذي ٥٣٦","pre":"وعن كثير بن عبد الله عن أبيه عن جده:","links":[{"book":"mt_tirmidhi","num":536,"id":"h536"}]},{"t":"quote","text":"كَيْفَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُكَبِّرُ فِي الأَضْحَى وَالْفِطْرِ فَقَالَ أَبُو مُوسَى كَانَ يُكَبِّرُ أَرْبَعًا تَكْبِيرَهُ عَلَى الْجَنَائِزِ . فَقَالَ حُذَيْفَةُ صَدَقَ . فَقَالَ أَبُو مُوسَى كَذَلِكَ كُنْتُ أُكَبِّرُ فِي الْبَصْرَةِ حَيْثُ كُنْتُ عَلَيْهِمْ","src":"رواه أبو داود ١١٥٣","pre":"وعن أبي عائشة أن سعيد بن العاص سأل أبا موسى الأشعري وحذيفة رضي الله عنهما:","links":[{"book":"mt_abudawud","num":1153,"id":"h1153"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"ذَهَبَ مَالِكٌ إِلَى أَنَّ التَّكْبِيرَ فِي الْأُولَى مِنْ رَكْعَتَيِ الْعِيدَيْنِ: سَبْعٌ مَعَ تَكْبِيرَةِ الْإِحْرَامِ قَبْلَ الْقِرَاءَةِ، وَفِي الثَّانِيَةِ: سِتٌّ مَعَ تَكْبِيرَةِ الْقِيَامِ مِنَ السُّجُودِ. وَقَالَ الشَّافِعِيُّ: فِي الْأُولَى: ثَمَان، وَفِي الثَّانِيَةِ: سِتٌّ مَعَ تَكْبِيرَةِ الْقِيَامِ مِنَ السُّجُودِ.","src":"بداية المجتهد","loc":"١/٢٢٨","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أئمتنا الثلاثة وسفيان الثوري: إن التكبيرات الزوائد ستة: ثلاثة في الأولى قبل القراءة، وثلاثة في الثانية بعدها، وقال مالك وأحمد والشافعي: الزوائد اثنتي عشر تكبيرة قبل القراءة، سبعة في الأولى، خمسة في الثانية","src":"العرف الشذي","loc":"٢/٣٧","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التكبيرات الزوائد سبع في الركعة الأولى مع تكبيرة الإحرام، وخمس في الثانية سوى تكبيرة القيام، كلها قبل القراءة؛ لحديث عبد الله بن عمرو، وهو أحسن ما في الباب عند البخاري وغيره، وعليه عمل أهل المدينة وأكثر الصحابة. ومن كبر ثلاثًا في كل ركعة كما يقول الحنفية، فله سلف من الصحابة كابن مسعود وأبي موسى وحذيفة، والأمر في ذلك واسع، ولا ينبغي التنازع فيه."},{"t":"p","text":"ويستحب أن يرفع يديه مع كل تكبيرة، وهو قول الشافعي وأحمد وأبي حنيفة، ويحمد الله ويثني عليه ويصلي على النبي ﷺ بين كل تكبيرتين، كما صح عن ابن مسعود، وإن سكت فلا حرج. والتكبيرات الزوائد سنة، فمن نسيها حتى شرع في القراءة لم يرجع إليها، وصلاته صحيحة."},{"t":"tanbih","items":[{"t":"p","text":"المأموم يتابع إمامه في عدد التكبيرات، ولو كان مذهبه خلاف مذهب الإمام، فلا يزيد عليه ولا ينقص عنه."}]}],"refs":["أبو داود ١١٥١","الترمذي ٥٣٦","أبو داود ١١٥٣","بداية المجتهد (١/٢٢٨)","العرف الشذي (٢/٣٧)","بداية المجتهد (١/٢٢٩)"],"related":["حكم صلاة العيد، ومن تجب عليه، وخروج النساء إليها","خطبة العيد وتقديم الصلاة عليها، والقراءة فيها، وأنها بلا أذان ولا إقامة"],"alts":["عدد تكبيرات العيد","التكبيرات الزوائد","رفع اليدين في تكبيرات العيد","صفة صلاة العيد"]},{"n":176,"bab":"الصلاة","sub":"صلاة العيدين","title":"خطبة العيد وتقديم الصلاة عليها، والقراءة فيها، وأنها بلا أذان ولا إقامة","q":"هل لصلاة العيد أذان وإقامة؟ وهل الخطبة قبل الصلاة أو بعدها؟ وهل يجب الجلوس لسماعها؟ وما السور التي تقرأ فيها؟","short":"أجمعوا على أن صلاة العيدين بلا أذان ولا إقامة، وأن السنة تقديم الصلاة على الخطبة، وأنه لا توقيت في القراءة فيها. واستحب أكثرهم أن يقرأ في الأولى بـ«سبح» وفي الثانية بـ«الغاشية»، واستحب الشافعي «ق» و«اقتربت». والخطبة سنة، وحضورها غير واجب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَأَبُو بَكْرٍ وَعُمَرُ ـ رضى الله عنهما ـ يُصَلُّونَ الْعِيدَيْنِ قَبْلَ الْخُطْبَةِ","src":"رواه البخاري ٩٦٣","pre":"عن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":963,"id":"h963"}]},{"t":"quote","text":"صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعِيدَيْنِ، غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ، بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ","src":"رواه مسلم ٨٨٧","pre":"وعن جابر بن سمرة رضي الله عنه قال:","links":[{"book":"mt_muslim","num":887,"id":"h887"}]},{"t":"quote","text":"كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْعِيدَيْنِ، وَفِي الْجُمُعَةِ بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى، وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ","src":"رواه مسلم ٨٧٨","pre":"وعن النعمان بن بشير رضي الله عنهما قال:","links":[{"book":"mt_muslim","num":878,"id":"h878"}]},{"t":"quote","text":"إِنَّا نَخْطُبُ فَمَنْ أَحَبَّ أَنْ يَجْلِسَ لِلْخُطْبَةِ فَلْيَجْلِسْ وَمَنْ أَحَبَّ أَنْ يَذْهَبَ فَلْيَذْهَبْ","src":"رواه أبو داود ١١٥٥","pre":"وعن عبد الله بن السائب رضي الله عنه قال: شهدت مع رسول الله ﷺ العيد، فلما قضى الصلاة قال:","links":[{"book":"mt_abudawud","num":1155,"id":"h1155"}]},{"t":"p","text":"قال أبو داود: هذا يُروى مرسلًا عن عطاء."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَجْمَعَ الْعُلَمَاءُ عَلَى اسْتِحْسَانِ الْغُسْلِ لِصَلَاةِ الْعِيدَيْنِ، وَأَنَّهُمَا بِلَا أَذَانٍ وَلَا إِقَامَةٍ، لِثُبُوتِ ذَلِكَ عَنْ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إِلَّا مَا أَحْدَثَ مِنْ ذَلِكَ مُعَاوِيَةُ فِي أَصَحِّ الْأَقَاوِيلِ، قَالَهُ أَبُو عُمَرَ.","src":"بداية المجتهد","loc":"١/٢٢٧","pre":"قال ابن رشد:"},{"t":"quote","text":"السنة الخطبة بعد العيدين، وتلقاه الأمة بالقبول","src":"العرف الشذي","loc":"٢/٣٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صلاة العيد بلا أذان ولا إقامة ولا نداء، وأنها تُقدم على الخطبة؛ لفعل النبي ﷺ وخلفائه. ويقرأ فيها جهرًا بعد الفاتحة بـ«سبح اسم ربك الأعلى» و«الغاشية»، أو بـ«ق» و«اقتربت الساعة»، فكلاهما ثابت في صحيح مسلم."},{"t":"p","text":"والخطبة بعد الصلاة سنة، ويستحب للمصلي أن يجلس لسماعها؛ لما فيها من الموعظة والتعليم، ومن انصرف بعد الصلاة فلا إثم عليه؛ لحديث عبد الله بن السائب المتقدم. ويستحب الاغتسال للعيد والتطيب ولبس أحسن الثياب."}],"refs":["البخاري ٩٦٣","مسلم ٨٨٧","مسلم ٨٧٨","أبو داود ١١٥٥","بداية المجتهد (١/٢٢٧)","العرف الشذي (٢/٣٥)"],"related":["التكبيرات الزوائد في صلاة العيد، ورفع اليدين معها"],"alts":["أذان صلاة العيد","خطبة العيد","القراءة في صلاة العيد","الانصراف قبل خطبة العيد"]},{"n":177,"bab":"الصلاة","sub":"صلاة العيدين","title":"اجتماع العيد والجمعة في يوم واحد","q":"وافق العيد يوم الجمعة، فهل تسقط الجمعة عمن صلى العيد؟ وإذا لم أصل الجمعة فهل أصلي الظهر؟","short":"ذهب أبو حنيفة ومالك إلى أن الجمعة لا تسقط بصلاة العيد، فكل منهما مخاطَب به. وذهب الشافعي إلى أن الرخصة لأهل القرى والبوادي الذين حضروا العيد في المصر خاصة. وذهب أحمد إلى أن من صلى العيد سقط عنه وجوب حضور الجمعة ويصلي الظهر، إلا الإمام فيقيمها لمن شاء. وروي عن عطاء وابن الزبير أنه يسقط عنه الظهر أيضًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَشَهِدْتَ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم عِيدَيْنِ اجْتَمَعَا فِي يَوْمٍ قَالَ نَعَمْ . قَالَ فَكَيْفَ صَنَعَ قَالَ صَلَّى الْعِيدَ ثُمَّ رَخَّصَ فِي الْجُمُعَةِ فَقَالَ «مَنْ شَاءَ أَنْ يُصَلِّيَ فَلْيُصَلِّ»","src":"رواه أبو داود ١٠٧٠","pre":"عن إياس بن أبي رملة قال: شهدت معاوية يسأل زيد بن أرقم رضي الله عنه:","links":[{"book":"mt_abudawud","num":1070,"id":"h1070"}]},{"t":"quote","text":"قَدِ اجْتَمَعَ فِي يَوْمِكُمْ هَذَا عِيدَانِ فَمَنْ شَاءَ أَجْزَأَهُ مِنَ الْجُمُعَةِ وَإِنَّا مُجَمِّعُونَ","src":"رواه أبو داود ١٠٧٣","pre":"وعن أبي هريرة رضي الله عنه عن رسول الله ﷺ أنه قال:","links":[{"book":"mt_abudawud","num":1073,"id":"h1073"}]},{"t":"quote","text":"وَإِذَا اجْتَمَعَ الْعِيدُ وَالْجُمُعَةُ، فِي يَوْمٍ وَاحِدٍ، يَقْرَأُ بِهِمَا أَيْضًا فِي الصَّلَاتَيْنِ","src":"رواه مسلم ٨٧٨","pre":"وعن النعمان بن بشير رضي الله عنهما قال:","links":[{"book":"mt_muslim","num":878,"id":"h878"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا إِذَا اجْتَمَعَ فِي يَوْمٍ وَاحِدٍ عِيدٌ وَجُمُعَةٌ، هَلْ يُجْزِئُ الْعِيدُ عَنِ الْجُمُعَةِ؟ . فَقَالَ قَوْمٌ: يُجْزِئُ الْعِيدُ عَنِ الْجُمُعَةِ، وَلَيْسَ عَلَيْهِ فِي ذَلِكَ الْيَوْمِ إِلَّا الْعَصْرُ فَقَطْ، وَبِهِ قَالَ عَطَاءٌ، وَرُوِيَ ذَلِكَ عَنِ ابْنِ الزُّبَيْرِ وَعَلِيٍّ.","src":"بداية المجتهد","loc":"١/٢٣٠","pre":"قال ابن رشد:"},{"t":"quote","text":"وأما ما في البخاري عن عثمان أنه صلى العيد ثم قال للناس من أراد أن يذهب فليذهب فليس مراده العفو عن أهل المِصر، بل الإجازة لأهل القرى الذين اجتمعوا","src":"العرف الشذي","loc":"٢/٣٧","pre":"وقال الكشميري في توجيه مذهب الحنفية:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من صلى العيد مع الإمام رُخّص له في ترك حضور الجمعة؛ لحديث زيد بن أرقم وأبي هريرة، ولكن يصلي الظهر في وقتها، ولا تسقط عنه الظهر؛ لأنها فرض الوقت، والجمعة بدل عنها. وعلى الإمام أن يقيم الجمعة ليشهدها من شاء ومن لم يصل العيد؛ لقوله ﷺ: «وإنا مجمعون»."},{"t":"p","text":"والأفضل لمن صلى العيد أن يشهد الجمعة أيضًا؛ خروجًا من خلاف من أوجبها، وهم أبو حنيفة ومالك، وعملًا بحديث النعمان في قراءة النبي ﷺ في الصلاتين، ومن اتبع مذهب الحنفية أو المالكية في وجوب الجمعة فقد احتاط لدينه."}],"refs":["أبو داود ١٠٧٠","أبو داود ١٠٧٣","مسلم ٨٧٨","بداية المجتهد (١/٢٣٠)","العرف الشذي (٢/٣٧)"],"related":["حكم صلاة الجمعة، ومن تجب عليه"],"alts":["العيد يوم الجمعة","سقوط الجمعة بالعيد","صلاة الظهر يوم العيد"]},{"n":178,"bab":"الصلاة","sub":"صلاة العيدين","title":"وقت صلاة العيد، ومن فاتته، والتنفل قبلها وبعدها","q":"متى يبدأ وقت صلاة العيد؟ وإذا فاتتني مع الإمام فهل أقضيها؟ وهل أصلي تحية المسجد أو نافلة قبلها في المصلى؟ وإذا لم يُعلم بالعيد إلا بعد الزوال فماذا يُصنع؟","short":"اتفقوا على أن وقتها من ارتفاع الشمس إلى الزوال. ومن لم يعلم بالعيد إلا بعد الزوال صلوها من الغد عند أبي حنيفة وأحمد والأوزاعي، ولم يقضوها عند مالك والشافعي في قول. ومن فاتته مع الإمام قضاها ركعتين كصفتها عند الشافعي ومالك في رواية، وأربعًا عند أحمد في رواية والثوري، ولا قضاء عليه عند أبي حنيفة. وكره أبو حنيفة وأحمد التنفل قبلها وبعدها في المصلى.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم خَرَجَ يَوْمَ الْفِطْرِ، فَصَلَّى رَكْعَتَيْنِ لَمْ يُصَلِّ قَبْلَهَا وَلاَ بَعْدَهَا وَمَعَهُ بِلاَلٌ","src":"رواه البخاري ٩٨٩","pre":"عن ابن عباس رضي الله عنهما:","links":[{"book":"mt_bukhari","num":989,"id":"h989"}]},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ لاَ يُصَلِّي قَبْلَ الْعِيدِ شَيْئًا فَإِذَا رَجَعَ إِلَى مَنْزِلِهِ صَلَّى رَكْعَتَيْنِ","src":"رواه ابن ماجه ١٢٩٣","pre":"وعن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_ibnmajah","num":1293,"id":"h1293"}]},{"t":"quote","text":"أَنَّ رَكْبًا جَاءُوا إِلَى النَّبِيِّ صلى الله عليه وسلم يَشْهَدُونَ أَنَّهُمْ رَأَوُا الْهِلاَلَ بِالأَمْسِ فَأَمَرَهُمْ أَنْ يُفْطِرُوا وَإِذَا أَصْبَحُوا أَنْ يَغْدُوا إِلَى مُصَلاَّهُمْ","src":"رواه أبو داود ١١٥٧","pre":"وعن أبي عمير بن أنس عن عمومة له من أصحاب النبي ﷺ:","links":[{"book":"mt_abudawud","num":1157,"id":"h1157"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنَّ وَقْتَهَا مِنْ شُرُوقِ الشَّمْسِ إِلَى الزَّوَالِ. وَاخْتَلَفُوا فِيمَنْ لَمْ يَأْتِهِمْ عِلْمٌ بِأَنَّهُ الْعِيدُ إِلَّا بَعْدَ الزَّوَالِ، فَقَالَتْ طَائِفَةٌ: لَيْسَ عَلَيْهِمْ أَنْ يُصَلُّوا يَوْمَهُمْ وَلَا مِنَ الْغَدِ، وَبِهِ قَالَ مَالِكٌ وَالشَّافِعِيُّ وَأَبُو ثَوْرٍ.","src":"بداية المجتهد","loc":"١/٢٢٩-٢٣٠","pre":"قال ابن رشد:"},{"t":"quote","text":"عندنا تكره الصلاة قبل العيدين في البيت والمصلى، وفي البحر: لا يصلي الإشراق أيضاً من يعتادها، وأما بعد العيد فيصلي في البيت ما شاء من النافلة","src":"العرف الشذي","loc":"٢/٣٩","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن وقت صلاة العيد يبدأ بارتفاع الشمس قيد رمح، ويمتد إلى الزوال، والسنة تعجيل الأضحى ليتفرغ الناس لذبح أضاحيهم، وتأخير الفطر قليلًا ليتمكنوا من إخراج زكاة الفطر. فإن لم يعلموا بالعيد إلا بعد الزوال صلوها من الغد في وقتها؛ لحديث الركب."},{"t":"p","text":"ومن فاتته صلاة العيد مع الإمام استُحب له أن يقضيها على صفتها ركعتين بتكبيراتها؛ لأن القضاء يحكي الأداء، وقد روي أن أنس بن مالك رضي الله عنه كان إذا فاتته جمع أهله وصلى بهم. ولا يتنفل في المصلى قبلها ولا بعدها؛ اقتداءً بالنبي ﷺ، وإن صُليت في المسجد صلى تحية المسجد إذا دخل؛ لعموم الأمر بها."}],"refs":["البخاري ٩٨٩","ابن ماجه ١٢٩٣","أبو داود ١١٥٧","بداية المجتهد (١/٢٢٩-٢٣٠)","بداية المجتهد (١/٢٣٠-٢٣١)","العرف الشذي (٢/٣٩)","بداية المجتهد (١/٢٣١)"],"related":["تحية المسجد: حكمها، وفي أوقات النهي، وبعد سنة الفجر"],"alts":["وقت صلاة العيد","قضاء صلاة العيد","الصلاة قبل العيد","تحية المسجد يوم العيد"]},{"n":179,"bab":"الصلاة","sub":"صلاة العيدين","title":"التكبير في العيدين: وقته وصفته، وآداب يوم العيد","q":"متى يبدأ التكبير في عيد الفطر وعيد الأضحى ومتى ينتهي؟ وما صيغته؟ وهل يأكل قبل الصلاة؟","short":"أجمع الجمهور على استحباب التكبير في العيدين. فقال مالك وأحمد وجمهور العلماء: يكبر في الفطر عند الغدو إلى الصلاة حتى يخرج الإمام، وقال الشافعي: من رؤية الهلال، وقال أبو حنيفة: يكبر في الأضحى جهرًا وفي الفطر سرًّا في رواية. واتفقوا على التكبير في أدبار الصلوات أيام التشريق، واختلفوا في توقيته: فقال أحمد وأبو يوسف ومحمد: من صبح عرفة إلى عصر آخر أيام التشريق، وقال مالك والشافعي: من ظهر يوم النحر إلى صبح آخر أيام التشريق.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ","ref":"البقرة: ١٨٥"},{"t":"aya","text":"وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ","ref":"البقرة: ٢٠٣"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم لاَ يَغْدُو يَوْمَ الْفِطْرِ حَتَّى يَأْكُلَ تَمَرَاتٍ. وَقَالَ مُرَجَّى بْنُ رَجَاءٍ حَدَّثَنِي عُبَيْدُ اللَّهِ قَالَ حَدَّثَنِي أَنَسٌ عَنِ النَّبِيِّ صلى الله عليه وسلم وَيَأْكُلُهُنَّ وِتْرًا","src":"رواه البخاري ٩٥٣","pre":"عن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":953,"id":"h953"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم لاَ يَخْرُجُ يَوْمَ الْفِطْرِ حَتَّى يَطْعَمَ وَلاَ يَطْعَمُ يَوْمَ الأَضْحَى حَتَّى يُصَلِّيَ","src":"رواه الترمذي ٥٤٢","pre":"وعن بريدة رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":542,"id":"h542"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا كَانَ يَوْمُ عِيدٍ خَالَفَ الطَّرِيقَ. تَابَعَهُ يُونُسُ بْنُ مُحَمَّدٍ عَنْ فُلَيْحٍ. وَحَدِيثُ جَابِرٍ أَصَحُّ","src":"رواه البخاري ٩٨٦","pre":"وعن جابر رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":986,"id":"h986"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أجمع العلماء على استحباب التكبير في العيدين؛ لأمر الله تعالى بالتكبير عند إكمال عدة رمضان في آية الصيام، واختلفوا في وقته:"},{"t":"qawl","label":"في عيد الفطر","text":"قال الجمهور، ومنهم مالك وأحمد: يكبّر عند الغدو إلى المصلى حتى يخرج الإمام، وقال آخرون، ومنهم الشافعي: يبدأ من ليلة العيد إذا رُئي الهلال."},{"t":"qawl","label":"في عيد الأضحى","text":"التكبير المقيد أدبار الصلوات: قال أبو يوسف ومحمد من الحنفية، وأحمد، وجماعة: من فجر يوم عرفة إلى عصر آخر أيام التشريق، وعليه الفتوى عند الحنفية، وقال مالك والشافعي: من ظهر يوم النحر إلى صبح آخر أيام التشريق، وفي المسألة أقوال أخرى كثيرة حكى ابن المنذر منها عشرة."},{"t":"quote","text":"وَأَمَّا وَقْتُهُ فَأَوَّلُهُ عَقِيبَ صَلَاةِ الْفَجْرِ مِنْ يَوْمِ عَرَفَةَ وَآخِرُهُ فِي قَوْلِ أَبِي يُوسُفَ وَمُحَمَّدٍ - رَحِمَهُمَا اللَّهُ تَعَالَى - عَقِيبَ صَلَاةِ الْعَصْرِ مِنْ آخِرِ أَيَّامِ التَّشْرِيقِ، هَكَذَا فِي التَّبْيِينِ، وَالْفَتْوَى وَالْعَمَلُ فِي عَامَّةِ الْأَمْصَارِ وَكَافَّةِ الْأَعْصَارِ عَلَى قَوْلِهِمَا","src":"الفتاوى الهندية","loc":"١/١٥٢","pre":"جاء في «الفتاوى الهندية» من كتب الحنفية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"أما التكبير في الأضحى فمشروع من أول الشهر إلى نهاية اليوم الثالث عشر من شهر ذي الحجة","src":"مجموع فتاوى ابن باز","loc":"١٣/١٨","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التكبير في عيد الفطر يبدأ من غروب شمس آخر يوم من رمضان أو رؤية الهلال، ويتأكد عند الخروج إلى المصلى، وينتهي بشروع الإمام في الصلاة؛ لقوله تعالى: ﴿وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ﴾. وفي عيد الأضحى يكبر تكبيرًا مطلقًا من أول ذي الحجة، وتكبيرًا مقيدًا بأدبار الصلوات من فجر يوم عرفة إلى عصر آخر أيام التشريق، وهو قول جمهور الصحابة كعمر وعلي وابن مسعود، وعليه العمل."},{"t":"p","text":"وصيغته الثابتة عن ابن مسعود وغيره: «الله أكبر، الله أكبر، لا إله إلا الله، والله أكبر، الله أكبر، ولله الحمد»، وإن كبّر ثلاثًا فحسن. ويجهر به الرجال في المساجد والبيوت والأسواق، وتخفضه النساء. ويستحب أن يأكل يوم الفطر تمرات وترًا قبل الخروج، وألا يأكل يوم الأضحى حتى يرجع فيأكل من أضحيته، وأن يذهب من طريق ويرجع من آخر."},{"t":"tanbih","items":[{"t":"p","text":"التكبير الجماعي بصوت واحد يرددونه معًا لم يكن من عمل السلف المعروف، والسنة أن يكبر كل واحد بنفسه، ولا يُنكر على من كبّر مع غيره إذا لم يتخذه شعارًا لازمًا."}]}],"refs":["البخاري ٩٥٣","الترمذي ٥٤٢","البخاري ٩٨٦","الفتاوى الهندية (١/١٥٢)","مجموع فتاوى ابن باز (١٣/١٨)"],"related":["حكم صلاة العيد، ومن تجب عليه، وخروج النساء إليها"],"alts":["تكبيرات العيد","التكبير المقيد والمطلق","صيغة التكبير","الأكل قبل صلاة العيد","آداب العيد"]},{"n":180,"bab":"الصلاة","sub":"سجود التلاوة","title":"حكم سجود التلاوة على القارئ والمستمع والسامع","q":"هل سجود التلاوة واجب يأثم تاركه؟ وإذا سمعت آية السجدة من إذاعة أو من شخص يقرأ ولم أكن أستمع إليه فهل يلزمني السجود؟","short":"ذهب أبو حنيفة وأصحابه إلى أن سجود التلاوة واجب على القارئ والسامع. وذهب مالك والشافعي وأحمد إلى أنه سنة مؤكدة وليس بواجب. وأجمعوا على أنه يتوجه إلى القارئ في الصلاة وخارجها، واختلفوا في السامع: فأوجبه عليه أبو حنيفة، واشترط مالك وأحمد أن يكون مستمعًا قاصدًا للسماع، وأن يكون القارئ ممن يصلح إمامًا له وقد سجد.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم يَقْرَأُ السَّجْدَةَ وَنَحْنُ عِنْدَهُ فَيَسْجُدُ وَنَسْجُدُ مَعَهُ فَنَزْدَحِمُ حَتَّى مَا يَجِدُ أَحَدُنَا لِجَبْهَتِهِ مَوْضِعًا يَسْجُدُ عَلَيْهِ","src":"رواه البخاري ١٠٧٦","pre":"عن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1076,"id":"h1076"}]},{"t":"quote","text":"فَزَعَمَ أَنَّهُ قَرَأَ عَلَى النَّبِيِّ صلى الله عليه وسلم {وَالنَّجْمِ} فَلَمْ يَسْجُدْ فِيهَا","src":"رواه البخاري ١٠٧٢","pre":"وعن عطاء بن يسار أنه سأل زيد بن ثابت رضي الله عنه","links":[{"book":"mt_bukhari","num":1072,"id":"h1072"}]},{"t":"quote","text":"قَرَأَ يَوْمَ الْجُمُعَةِ عَلَى الْمِنْبَرِ بِسُورَةِ النَّحْلِ حَتَّى إِذَا جَاءَ السَّجْدَةَ نَزَلَ فَسَجَدَ وَسَجَدَ النَّاسُ، حَتَّى إِذَا كَانَتِ الْجُمُعَةُ الْقَابِلَةُ قَرَأَ بِهَا حَتَّى إِذَا جَاءَ السَّجْدَةَ قَالَ يَا أَيُّهَا النَّاسُ إِنَّا نَمُرُّ بِالسُّجُودِ فَمَنْ سَجَدَ فَقَدْ أَصَابَ، وَمَنْ لَمْ يَسْجُدْ فَلاَ إِثْمَ عَلَيْهِ. وَلَمْ يَسْجُدْ عُمَرُ ـ رضى الله عنه. وَزَادَ نَافِعٌ عَنِ ابْنِ عُمَرَ ـ رضى الله عنهما إِنَّ اللَّهَ لَمْ يَفْرِضِ السُّجُودَ إِلاَّ أَنْ نَشَاءَ","src":"رواه البخاري ١٠٧٧","pre":"وعن ربيعة بن عبد الله بن الهدير عن عمر بن الخطاب رضي الله عنه أنه","links":[{"book":"mt_bukhari","num":1077,"id":"h1077"}]},{"t":"quote","text":"إِذَا قَرَأَ ابْنُ آدَمَ السَّجْدَةَ فَسَجَدَ اعْتَزَلَ الشَّيْطَانُ يَبْكِي، يَقُولُ: يَا وَيْلَهُ - وَفِي رِوَايَةِ أَبِي كُرَيْبٍ: يَا وَيْلِي - أُمِرَ ابْنُ آدَمَ بِالسُّجُودِ فَسَجَدَ فَلَهُ الْجَنَّةُ، وَأُمِرْتُ بِالسُّجُودِ فَأَبَيْتُ فَلِيَ النَّارُ","src":"رواه مسلم ٨١","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":81,"id":"h81"}]},{"t":"h","text":"أقوال العلماء"},{"t":"qawl","label":"القول الأول: سجود التلاوة واجب","text":"وهو قول أبي حنيفة وأصحابه، ورواية عن أحمد، واختاره ابن تيمية."},{"t":"qawl","label":"القول الثاني: سنة مؤكدة","text":"وهو قول مالك والشافعي، والمشهور عن أحمد."},{"t":"quote","text":"فَأَمَّا حُكْمُ سُجُودِ التِّلَاوَةِ: فَإِنَّ أَبَا حَنِيفَةَ وَأَصْحَابَهُ قَالُوا: هُوَ وَاجِبٌ، وَقَالَ مَالِكٌ وَالشَّافِعِيُّ: هُوَ مَسْنُونٌ وَلَيْسَ بِوَاجِبٍ","src":"بداية المجتهد","loc":"١/٢٣٣","pre":"قال ابن رشد:"},{"t":"quote","text":"إن أبا حنيفة قائل بوجوب سجدة التلاوة، والشافعي يقول بسنتها، والصحابة أيضاً مختلفون في الوجوب والسنية، وتمسك بحديث زيد بن ثابت مرفوعاً وبفعل عمر بن الخطاب حين قال: إنها لم تكتب علينا، وسيجيء الكلام فيه، وما أجاب الأحناف شافياً عن فعل عمر بن الخطاب","src":"العرف الشذي","loc":"٢/٦٦","pre":"وقال الكشميري الحنفي منصفًا:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"سجود التلاوة سنة مؤكدة لا ينبغي تركها، فإذا مر الإنسان بآيت سجدة فليسجد سواء كان يقرأ في المصحف، أو عن ظهر قلب، أو في الصلاة، أو خارج الصلاة","src":"مجموع فتاوى ابن عثيمين","loc":"١٤/٣٠٩","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سجود التلاوة سنة مؤكدة، لا يأثم تاركه؛ لقول عمر رضي الله عنه على المنبر بمحضر الصحابة: «من سجد فقد أصاب، ومن لم يسجد فلا إثم عليه»، ولم ينكر عليه أحد، ولترك النبي ﷺ السجود في النجم حين قرأها زيد بن ثابت. ولكن لا ينبغي للمسلم أن يتركه، لا سيما مع القدرة، وقول الحنفية بوجوبه احتياط، ومن أخذ به فقد أحسن."},{"t":"p","text":"ويتأكد السجود على القارئ وعلى المستمع الذي يقصد الاستماع إذا سجد القارئ، وأما السامع الذي مرت به الآية من غير قصد فلا يتأكد في حقه، وإن سجد فحسن. والقراءة من الإذاعة والتسجيل يسجد لها من استمع إليها استحبابًا، ولا يلزمه."}],"refs":["البخاري ١٠٧٦","البخاري ١٠٧٢","البخاري ١٠٧٧","مسلم ٨١","بداية المجتهد (١/٢٣٣)","العرف الشذي (٢/٦٦)","بداية المجتهد (١/٢٣٦-٢٣٧)","مجموع فتاوى ابن عثيمين (١٤/٣٠٩)","بداية المجتهد (١/٢٣٤)"],"related":["عدد سجدات التلاوة في القرآن: سجدة ص، وثانية الحج، وسجدات المفصل","صفة سجود التلاوة: الطهارة، والتكبير، والتسليم، وما يقال فيه"],"alts":["سجدة التلاوة واجبة أم سنة","السجود عند سماع آية السجدة","سجدة التلاوة للمستمع"]},{"n":181,"bab":"الصلاة","sub":"سجود التلاوة","title":"عدد سجدات التلاوة في القرآن: سجدة ص، وثانية الحج، وسجدات المفصل","q":"كم عدد سجدات التلاوة في القرآن؟ وهل في سورة ص سجدة؟ وهل في الحج سجدتان؟ وهل في المفصل (النجم والانشقاق والعلق) سجود؟","short":"ذهب أحمد في المشهور إلى أنها خمس عشرة سجدة، وذهب الشافعي إلى أنها أربع عشرة، أسقط سجدة ص وجعلها سجدة شكر، وذهب أبو حنيفة إلى أنها أربع عشرة أيضًا، أثبت ص وأسقط الثانية من الحج، وذهب مالك في المشهور إلى أنها إحدى عشرة، ليس في المفصل منها شيء.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا السَّمَاءُ انْشَقَّتْ فَسَجَدَ فِيهَا","src":"رواه مسلم ٥٧٨","pre":"عن أبي سلمة أن أبا هريرة رضي الله عنه قرأ لهم:","links":[{"book":"mt_muslim","num":578,"id":"h578"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم سَجَدَ بِالنَّجْمِ وَسَجَدَ مَعَهُ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْجِنُّ وَالإِنْسُ","src":"رواه البخاري ١٠٧١","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_bukhari","num":1071,"id":"h1071"}]},{"t":"quote","text":"{ص} لَيْسَ مِنْ عَزَائِمِ السُّجُودِ، وَقَدْ رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم يَسْجُدُ فِيهَا","src":"رواه البخاري ١٠٦٩","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1069,"id":"h1069"}]},{"t":"quote","text":"قَرَأَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهُوَ عَلَى الْمِنْبَرِ { ص } فَلَمَّا بَلَغَ السَّجْدَةَ نَزَلَ فَسَجَدَ وَسَجَدَ النَّاسُ مَعَهُ فَلَمَّا كَانَ يَوْمٌ آخَرُ قَرَأَهَا فَلَمَّا بَلَغَ السَّجْدَةَ تَشَزَّنَ النَّاسُ لِلسُّجُودِ فَقَالَ النَّبِيُّ صلى الله عليه وسلم «إِنَّمَا هِيَ تَوْبَةُ نَبِيٍّ وَلَكِنِّي رَأَيْتُكُمْ تَشَزَّنْتُمْ لِلسُّجُودِ» . فَنَزَلَ فَسَجَدَ وَسَجَدُوا","src":"رواه أبو داود ١٤١٠","pre":"وعن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":1410,"id":"h1410"}]},{"t":"quote","text":"فُضِّلَتْ سُورَةُ الْحَجِّ بِأَنَّ فِيهَا سَجْدَتَيْنِ قَالَ «نَعَمْ وَمَنْ لَمْ يَسْجُدْهُمَا فَلاَ يَقْرَأْهُمَا»","src":"رواه الترمذي ٥٧٨","pre":"وعن عقبة بن عامر رضي الله عنه قال: قلت: يا رسول الله،","links":[{"book":"mt_tirmidhi","num":578,"id":"h578"}]},{"t":"quote","text":"هَذَا حَدِيثٌ لَيْسَ إِسْنَادُهُ بِذَاكَ الْقَوِيِّ . وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي هَذَا فَرُوِيَ عَنْ عُمَرَ بْنِ الْخَطَّابِ وَابْنِ عُمَرَ أَنَّهُمَا قَالاَ فُضِّلَتْ سُورَةُ الْحَجِّ بِأَنَّ فِيهَا سَجْدَتَيْنِ","src":"رواه الترمذي ٥٧٨","pre":"قال الترمذي:","links":[{"book":"mt_tirmidhi","num":578,"id":"h578"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا عَدَدُ عَزَائِمِ سُجُودِ الْقُرْآنِ: فَإِنَّ مَالِكًا قَالَ فِي الْمُوَطَّأ: الْأَمْرُ عِنْدَنَا أَنَّ عَزَائِمَ سُجُودِ الْقُرْآنِ إِحْدَى عَشْرَةَ سَجْدَةً، لَيْسَ فِي الْمُفَصَّلِ مِنْهَا شَيْءٌ","src":"بداية المجتهد","loc":"١/٢٣٤","pre":"قال ابن رشد:"},{"t":"p","text":"والمعتمد في كتب الحنفية أن السجدات أربع عشرة، وما حكاه بعضهم عن أبي حنيفة من غير ذلك خلاف المعروف في مذهبه، وهي: الأعراف، والرعد، والنحل، والإسراء، ومريم، وأولى الحج، والفرقان، والنمل، والسجدة، وص، وفصلت، والنجم، والانشقاق، والعلق."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سجدات التلاوة خمس عشرة سجدة: في الأعراف، والرعد، والنحل، والإسراء، ومريم، والحج سجدتان، والفرقان، والنمل، والسجدة، وص، وفصلت، والنجم، والانشقاق، والعلق؛ لثبوت السجود فيها عن النبي ﷺ أو عن الصحابة، والسجود في المفصل ثابت في الصحيحين من حديث أبي هريرة وابن عباس، وأبو هريرة إنما صحب النبي ﷺ بالمدينة. وسجدة ص سجدها النبي ﷺ وقال: «سجدها داود توبة، ونسجدها شكرًا»، فيسجد فيها خارج الصلاة، والأحوط ألا يسجدها في الصلاة عند من لا يراها من العزائم."},{"t":"tanbih","items":[{"t":"p","text":"المأموم يتابع إمامه في السجود وفي تركه، ولو كان مذهبه يخالف مذهب الإمام في موضع السجدة."}]}],"refs":["مسلم ٥٧٨","البخاري ١٠٧١","البخاري ١٠٦٩","أبو داود ١٤١٠","الترمذي ٥٧٨","بداية المجتهد (١/٢٣٤)","بداية المجتهد (١/٢٣٥)","بداية المجتهد (١/٢٣٦)"],"related":["حكم سجود التلاوة على القارئ والمستمع والسامع"],"alts":["عدد سجدات القرآن","سجدة ص","سجدة الحج الثانية","سجود التلاوة في المفصل"]},{"n":182,"bab":"الصلاة","sub":"سجود التلاوة","title":"صفة سجود التلاوة: الطهارة، والتكبير، والتسليم، وما يقال فيه","q":"هل يشترط لسجود التلاوة الوضوء واستقبال القبلة؟ وهل أكبر وأسلم؟ وماذا أقول فيه؟ وهل أسجد في وقت النهي؟","short":"الجمهور على أن سجود التلاوة يشترط له ما يشترط للصلاة من الطهارة واستقبال القبلة، وأنه يكبر إذا سجد وإذا رفع، وفي التسليم خلاف: فلا تسليم فيه عند أبي حنيفة ومالك، ويسلم عند الشافعي وأحمد. وذهب بعض السلف كابن عمر والشعبي، واختاره البخاري وابن تيمية، إلى أنه لا تشترط له الطهارة. ومنعه أبو حنيفة ومالك في الموطأ في أوقات النهي، وأجازه الشافعي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَقُولُ فِي سُجُودِ الْقُرْآنِ بِاللَّيْلِ يَقُولُ فِي السَّجْدَةِ مِرَارًا «سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ»","src":"رواه أبو داود ١٤١٤","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_abudawud","num":1414,"id":"h1414"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم سَجَدَ بِالنَّجْمِ وَسَجَدَ مَعَهُ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْجِنُّ وَالإِنْسُ","src":"رواه البخاري ١٠٧١","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_bukhari","num":1071,"id":"h1071"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا صِفَةُ السُّجُودِ: فَإِنَّ جُمْهُورَ الْفُقَهَاءِ قَالُوا: إِذَا سَجَدَ الْقَارِئُ كَبَّرَ إِذَا خَفَضَ وَإِذَا رَفَعَ، وَاخْتَلَفَ قَوْلُ مَالِكٍ فِي ذَلِكَ إِذَا كَانَ فِي غَيْرِ صَلَاةٍ، وَأَمَّا إِذَا كَانَ فِي الصَّلَاةِ فَإِنَّهُ يُكَبِّرُ قَوْلًا وَاحِدًا","src":"بداية المجتهد","loc":"١/٢٣٧","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سجود التلاوة سجدة واحدة، يكبر لها إذا سجد، ويكبر إذا رفع إن كان في الصلاة، ويقول فيها: «سبحان ربي الأعلى»، و«سجد وجهي للذي خلقه وشق سمعه وبصره بحوله وقوته»، ونحو ذلك. ولا يشترط له تشهد ولا تسليم خارج الصلاة؛ لأنه لم يُنقل عن النبي ﷺ، ومن سلّم أخذًا بقول الشافعي وأحمد فلا حرج."},{"t":"p","text":"والأحوط أن يكون على طهارة مستقبل القبلة؛ لأنه قول جمهور الأئمة الأربعة، ومن سجد على غير طهارة أخذًا بقول ابن عمر والبخاري فله سلف، وقد سجد المشركون مع النبي ﷺ في النجم وليسوا على طهارة. ويسجد في أوقات النهي؛ لأنه ذو سبب، وليس صلاة تامة، ومن أخّره احتياطًا لمذهب الحنفية إلى خروج وقت النهي فقد أحسن، فإن السجود عندهم على التراخي."},{"t":"tanbih","items":[{"t":"p","text":"من قرأ آية سجدة في الصلاة السرية، فالأولى للإمام ألا يسجد إلا إذا أمن التشويش على المأمومين، فإن سجد تابعوه. ومن كرر آية السجدة في مجلس واحد كفته سجدة واحدة."}]}],"refs":["أبو داود ١٤١٤","البخاري ١٠٧١","بداية المجتهد (١/٢٣٧)","بداية المجتهد (١/٢٣٦)"],"related":["حكم سجود التلاوة على القارئ والمستمع والسامع","الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب"],"alts":["كيفية سجود التلاوة","دعاء سجود التلاوة","سجود التلاوة بغير وضوء","التسليم في سجود التلاوة"]},{"n":183,"bab":"الجنائز","sub":"الاحتضار والموت","title":"ما يُفعل بالمحتضر وبعد موته: التلقين، والتوجيه إلى القبلة، وتعجيل الدفن","q":"أبي في حالة الاحتضار، فماذا نفعل عنده؟ وهل نوجهه إلى القبلة؟ وإذا مات فما الذي نفعله أولًا؟ وهل نؤخر دفنه حتى يحضر أقاربه من السفر؟","short":"اتفقوا على استحباب تلقين المحتضر «لا إله إلا الله»، وعلى إغماض عينيه بعد موته، وعلى استحباب تعجيل تجهيزه ودفنه. واختلفوا في توجيهه إلى القبلة: فاستحبه أبو حنيفة والشافعي وأحمد وأكثر العلماء، ولم يره مالك من الأمر القديم، وأنكره سعيد بن المسيب.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللهُ","src":"رواه مسلم ٩١٦","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":916,"id":"h916"}]},{"t":"quote","text":"مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ","src":"رواه أبو داود ٣١١٦","pre":"وعن معاذ بن جبل رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":3116,"id":"h3116"}]},{"t":"quote","text":"دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي سَلَمَةَ وَقَدْ شَقَّ بَصَرُهُ، فَأَغْمَضَهُ، ثُمَّ قَالَ: «إِنَّ الرُّوحَ إِذَا قُبِضَ تَبِعَهُ الْبَصَرُ»، فَضَجَّ نَاسٌ مِنْ أَهْلِهِ، فَقَالَ: «لَا تَدْعُوا عَلَى أَنْفُسِكُمْ إِلَّا بِخَيْرٍ، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ»","src":"رواه مسلم ٩٢٠","pre":"وعن أم سلمة رضي الله عنها قالت:","links":[{"book":"mt_muslim","num":920,"id":"h920"}]},{"t":"quote","text":"أَسْرِعُوا بِالْجِنَازَةِ، فَإِنْ تَكُ صَالِحَةً فَخَيْرٌ تُقَدِّمُونَهَا {إِلَيْهِ}، وَإِنْ يَكُ سِوَى ذَلِكَ فَشَرٌّ تَضَعُونَهُ عَنْ رِقَابِكُمْ","src":"رواه البخاري ١٣١٥","pre":"وعن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1315,"id":"h1315"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَيُسْتَحَبُّ أَنْ يُلَقَّنَ الْمَيِّتُ عِنْدَ الْمَوْتِ: شَهَادَةَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «لَقِّنُوا مَوْتَاكُمْ شَهَادَةَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ» . وَقَوْلِهِ: «مَنْ كَانَ آخِرَ قَوْلِهِ لَا إِلَهَ إِلَّا اللَّهُ دَخَلَ الْجَنَّةَ» . وَاخْتَلَفُوا فِي اسْتِحْبَابِ تَوْجِيهِهِ إِلَى الْقِبْلَةِ: فَرَأَى ذَلِكَ قَوْمٌ وَلَمْ يَرَهُ الآخَرُونَ.","src":"بداية المجتهد","loc":"١/٢٣٨","pre":"قال ابن رشد:"},{"t":"quote","text":"التلقين مستحب للمحتضر يقرأ عنده ولا يؤمر، فإنه في حال السكرات فيحتمل أن يتكلم بكلام خلاف الشريعة، وقال الفقهاء: إن المستحضر لو تكلم بكلمة الكفر حالة السكرات لا يعمل بها ولا يحكم عليه بالكفر","src":"العرف الشذي","loc":"٢/٣٠٤","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"أن أهل العلم قالوا: يسن تلقين المحتضر لا إله إلا الله، لكن بدون قول قل؛ لأنه ربما مع الضجر يقول: لا؛ لضيق صدره مع نزول الموت","src":"مجموع فتاوى ابن عثيمين","loc":"٩/٣٤٧","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه يستحب أن يُلقَّن المحتضر «لا إله إلا الله» برفق، فيُذكَر عنده بها ولا يُلحّ عليه ولا يقال له: قل، إلا أن يكون كافرًا فيُعرض عليه الإسلام، فإذا قالها مرة لم تُكرر عليه إلا أن يتكلم بغيرها. ويستحب توجيهه إلى القبلة على جنبه الأيمن إن تيسر، وهو قول الجمهور، ومن لم يفعله فلا حرج. ويقرأ عنده من حضر من القرآن، ويدعون له، ولا يقولون إلا خيرًا."},{"t":"p","text":"فإذا مات أُغمضت عيناه، وشُدّ لحياه، ولُيّنت مفاصله، وغُطي بثوب، وبودر بقضاء دينه وتنفيذ وصيته، ثم يُعجَّل بتجهيزه ودفنه؛ لقوله ﷺ: «أسرعوا بالجنازة». ولا بأس بتأخيره يسيرًا لانتظار وليّه أو اجتماع الناس للصلاة عليه ما لم يُخش عليه التغير، وأما إذا شُك في موته، كالغريق والمصعوق ومن مات فجأة، فيُنتظر به حتى يُتيقن موته بقول الأطباء."},{"t":"tanbih","items":[{"t":"p","text":"تلقين الميت بعد دفنه لم يثبت فيه حديث صحيح، وفي كتب الحنفية: لا يُؤمر به ولا يُنهى عنه، والأولى الاقتصار على الدعاء له بالتثبيت عند قبره كما أمر النبي ﷺ."}]}],"refs":["مسلم ٩١٦","أبو داود ٣١١٦","مسلم ٩٢٠","البخاري ١٣١٥","بداية المجتهد (١/٢٣٨)","بداية المجتهد (١/٢٣٨-٢٣٩)","العرف الشذي (٢/٣٠٤)","مجموع فتاوى ابن عثيمين (٩/٣٤٧)"],"related":["حكم غسل الميت، وغسل الشهيد والصلاة عليه"],"alts":["تلقين المحتضر","توجيه المحتضر إلى القبلة","تعجيل دفن الميت","تأخير الدفن","ما يفعل بالميت بعد موته"]},{"n":184,"bab":"الجنائز","sub":"غسل الميت","title":"حكم غسل الميت، وغسل الشهيد والصلاة عليه","q":"ما حكم غسل الميت؟ ومن قُتل في سبيل الله في المعركة، هل يُغسل ويُصلى عليه؟ وما حكم من مات بحادث أو غرق أو هدم؟ وهل يغسل المسلم قريبه الكافر؟","short":"غسل الميت المسلم فرض كفاية عند الجمهور. والشهيد الذي قتله الكفار في المعركة لا يُغسل عند الأئمة الأربعة، ويُدفن في ثيابه ودمائه. واختلفوا في الصلاة عليه: فقال أبو حنيفة: يُصلى عليه وجوبًا، وقال مالك والشافعي: لا يُصلى عليه، وقال أحمد: الصلاة مستحبة ويجوز تركها. وأما شهداء غير المعركة كالغريق والمبطون وصاحب الهدم فيُغسلون ويُصلى عليهم بالاتفاق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"دَخَلَ عَلَيْنَا رَسُولُ اللَّهِ صلى الله عليه وسلم حِينَ تُوُفِّيَتِ ابْنَتُهُ فَقَالَ «اغْسِلْنَهَا ثَلاَثًا أَوْ خَمْسًا أَوْ أَكْثَرَ مَنْ ذَلِكَ إِنْ رَأَيْتُنَّ ذَلِكَ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا أَوْ شَيْئًا مِنْ كَافُورٍ»","src":"رواه البخاري ١٢٥٣","pre":"عن أم عطية رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1253,"id":"h1253"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ فِي ثَوْبٍ وَاحِدٍ ثُمَّ يَقُولُ «أَيُّهُمْ أَكْثَرُ أَخْذًا لِلْقُرْآنِ». فَإِذَا أُشِيرَ لَهُ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ وَقَالَ «أَنَا شَهِيدٌ عَلَى هَؤُلاَءِ يَوْمَ الْقِيَامَةِ». وَأَمَرَ بِدَفْنِهِمْ فِي دِمَائِهِمْ، وَلَمْ يُغَسَّلُوا وَلَمْ يُصَلَّ عَلَيْهِمْ","src":"رواه البخاري ١٣٤٣","pre":"وعن جابر بن عبد الله رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1343,"id":"h1343"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم خَرَجَ يَوْمًا فَصَلَّى عَلَى أَهْلِ أُحُدٍ صَلاَتَهُ عَلَى الْمَيِّتِ، ثُمَّ انْصَرَفَ إِلَى الْمِنْبَرِ","src":"رواه البخاري ١٣٤٤","pre":"وعن عقبة بن عامر رضي الله عنه:","links":[{"book":"mt_bukhari","num":1344,"id":"h1344"}]},{"t":"quote","text":"إِنَّ عَمَّكَ الشَّيْخَ الضَّالَّ قَدْ مَاتَ . قَالَ «اذْهَبْ فَوَارِ أَبَاكَ ثُمَّ لاَ تُحْدِثَنَّ شَيْئًا حَتَّى تَأْتِيَنِي» . فَذَهَبْتُ فَوَارَيْتُهُ وَجِئْتُهُ فَأَمَرَنِي فَاغْتَسَلْتُ وَدَعَا لِي","src":"رواه أبو داود ٣٢١٤","pre":"وعن علي رضي الله عنه قال: قلت للنبي ﷺ:","links":[{"book":"mt_abudawud","num":3214,"id":"h3214"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا حُكْمُ الْغُسْلِ: فَإِنَّهُ قِيلَ فِيهِ إِنَّهُ فَرْضٌ عَلَى الْكِفَايَةِ. وَقِيلَ سُنَّةٌ عَلَى الْكِفَايَةِ. وَالْقَوْلَانِ كِلَاهُمَا فِي الْمَذْهَبِ. وَالسَّبَبُ فِي ذَلِكَ: أَنَّهُ نُقِلَ بِالْعَمَلِ لَا بِالْقَوْلِ، وَالْعَمَلُ لَيْسَ لَهُ صِيغَةٌ تُفْهِمُ الْوُجُوبَ أَوْ لَا تُفْهِمُهُ.","src":"بداية المجتهد","loc":"١/٢٣٩","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الشافعي: لا يصلى على الشهيد، وجاء بعض المتأخرين منهم وقال بعدم جواز الصلاة عليه، وأما غسل الشهيد فلهم فيه وجهان: الغسل، وحرمة الغسل، والمستحب عدم الغسل، وأما الموالك ففي عامة كتبهم عدم الصلاة، وفي حاشية المدونة رواية ابن القاسم أن ابتداء الحرب إن كان من الكفار وجاء الكفار حاربين علينا فلا يصلى، وإن كان البداية منا، وذهبنا مجاهدين عليهم فيصلى، وقال أحمد: الصلاة مستحبة ويجوز تركها، ومذهب الحنفية إن الصلاة واجبة","src":"العرف الشذي","loc":"٢/٣٢١-٣٢٢","pre":"وقال الكشميري في الصلاة على الشهيد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن غسل الميت المسلم فرض كفاية، إذا قام به بعض المسلمين سقط عن الباقين. وأما الشهيد الذي قُتل في معركة الكفار فلا يُغسل، ويُدفن في ثيابه التي قُتل فيها بعد نزع السلاح والجلود عنه؛ لأن النبي ﷺ أمر بدفن شهداء أحد في دمائهم ولم يغسلهم. والصلاة عليه جائزة مشروعة، فإن صُلّي عليه كما يقول الحنفية فحسن، لحديث عقبة بن عامر، وإن تُرك كما في حديث جابر فلا حرج، وهذا قول أحمد، وفيه جمع بين الأحاديث."},{"t":"p","text":"وأما من مات بغرق أو حريق أو هدم أو حادث سير أو وباء أو في نفاس، فهؤلاء شهداء في الآخرة إن شاء الله، ولكنهم يُغسلون ويُكفنون ويُصلى عليهم كسائر الموتى بالاتفاق. ولا يجب على المسلم غسل قريبه الكافر، ولا يُصلى عليه، ولكن إن لم يوجد من يدفنه من أهل دينه واراه في التراب؛ لحديث علي في أبي طالب."}],"refs":["البخاري ١٢٥٣","البخاري ١٣٤٣","البخاري ١٣٤٤","أبو داود ٣٢١٤","بداية المجتهد (١/٢٣٩)","العرف الشذي (٢/٣٢١-٣٢٢)","بداية المجتهد (١/٢٤٠)"],"related":["من يغسل الميت: غسل الرجال للنساء والعكس، وغسل أحد الزوجين صاحبه","صفة غسل الميت: الوضوء، والعدد، والسدر، وستر العورة"],"alts":["حكم غسل الميت","غسل الشهيد","الصلاة على الشهيد","غسل الكافر"]},{"n":185,"bab":"الجنائز","sub":"غسل الميت","title":"من يغسل الميت: غسل الرجال للنساء والعكس، وغسل أحد الزوجين صاحبه","q":"ماتت امرأة ولا توجد نساء يغسلنها، أو مات رجل بين نساء ليس فيهن محرم له، فماذا يُصنع؟ وهل يجوز للزوج أن يغسل زوجته؟","short":"اتفقوا على أن الرجال يغسلون الرجال والنساء يغسلن النساء، وعلى جواز غسل المرأة زوجها. واختلفوا في غسل الرجل زوجته: فأجازه الجمهور، ومنعه أبو حنيفة. وإذا ماتت المرأة بين رجال أجانب أو الرجل بين نساء أجنبيات، فقال أبو حنيفة والشافعي وجمهور العلماء: يُيمَّم، وقال قوم: يغسل من فوق الثياب، وقال الليث: يدفن بلا غسل ولا تيمم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَا ضَرَّكِ لَوْ مِتِّ قَبْلِي فَقُمْتُ عَلَيْكِ فَغَسَّلْتُكِ وَكَفَّنْتُكِ وَصَلَّيْتُ عَلَيْكِ وَدَفَنْتُكِ","src":"رواه ابن ماجه ١٤٦٥","pre":"عن عائشة رضي الله عنها أن رسول الله ﷺ قال لها:","links":[{"book":"mt_ibnmajah","num":1465,"id":"h1465"}]},{"t":"quote","text":"وَكَانَتْ عَائِشَةُ تَقُولُ لَوِ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا غَسَّلَهُ إِلاَّ نِسَاؤُهُ","src":"رواه أبو داود ٣١٤١","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_abudawud","num":3141,"id":"h3141"}]},{"t":"p","text":"وصح أن عليًّا رضي الله عنه غسّل فاطمة رضي الله عنها، وأن أسماء بنت عميس غسّلت زوجها أبا بكر رضي الله عنه."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا مَنْ يَجُوزُ أَنْ يُغَسِّلَ الْمَيِّتَ، فَإِنَّهُمُ اتَّفَقُوا عَلَى أَنَّ الرِّجَالَ يُغَسِّلُونَ الرِّجَالَ، وَالنِّسَاءَ يُغَسِّلْنَ النِّسَاءَ. وَاخْتَلَفُوا فِي الْمَرْأَةِ تَمُوتُ مَعَ الرِّجَالِ، أَوِ الرَّجُلِ يَمُوتُ مَعَ النِّسَاءِ مَا لَمْ يَكُونَا زَوْجَيْنِ عَلَى ثَلَاثَةِ أَقْوَالٍ: فَقَالَ قَوْمٌ: يُغَسِّلُ كُلُّ وَاحِدٍ مِنْهُمَا صَاحِبَهُ مِنْ فَوْقِ الثِّيَابِ.","src":"بداية المجتهد","loc":"١/٢٤٠-٢٤١","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه يجوز لكل واحد من الزوجين أن يغسل صاحبه؛ لقول النبي ﷺ لعائشة: «ما ضرك لو مت قبلي فغسلتك»، ولغسل علي فاطمة، وغسل أسماء أبا بكر رضي الله عنهم، وهو قول الجمهور. ومن أخذ بقول الحنفية فترك الزوج غسل زوجته عند وجود النساء فلا حرج، والزوجة تغسل زوجها بالاتفاق."},{"t":"p","text":"ويغسل الرجالُ الرجالَ والنساءُ النساءَ، والأولى بغسل الميت من أوصى به، ثم الأقرب فالأقرب ممن يحسن الغسل. فإن ماتت امرأة بين رجال ليس فيهم زوج ولا محرم، أو مات رجل بين نساء ليس فيهن زوجة ولا محرم، يُمّم بحائل على اليد ولا يُغسل؛ لأن النظر واللمس محرم، والتيمم يقوم مقام الغسل عند العجز، وهذا قول الجمهور. ويجوز للرجال والنساء غسل الصبي والصبية الصغيرين اللذين لم يبلغا حد الشهوة."},{"t":"tanbih","items":[{"t":"p","text":"يجب على الغاسل أن يستر ما رأى من عيب في الميت، وأن يكون أمينًا. ويستحب لمن غسّل ميتًا أن يغتسل، وليس ذلك بواجب عند الجمهور."}]}],"refs":["ابن ماجه ١٤٦٥","أبو داود ٣١٤١","بداية المجتهد (١/٢٤٠-٢٤١)","بداية المجتهد (١/٢٤١)","بداية المجتهد (١/٢٤١-٢٤٢)"],"related":["حكم غسل الميت، وغسل الشهيد والصلاة عليه","صفة غسل الميت: الوضوء، والعدد، والسدر، وستر العورة"],"alts":["غسل الزوج زوجته","غسل الزوجة زوجها","تيمم الميت","من يغسل المرأة الميتة"]},{"n":186,"bab":"الجنائز","sub":"غسل الميت","title":"صفة غسل الميت: الوضوء، والعدد، والسدر، وستر العورة","q":"كيف يُغسَّل الميت؟ وهل يُوضّأ قبل الغسل؟ وكم مرة يُغسل؟ وهل تُقص أظفاره وشعره؟ وماذا نفعل إذا خرج منه شيء بعد الغسل؟","short":"ذهب الشافعي وأحمد ومالك في قول إلى أن الميت يُوضّأ في أول غسله، وقال أبو حنيفة: يوضأ ولكن لا يُمضمض ولا يُستنشق، ونقل ابن رشد عنه: لا يوضأ. والسنة أن يغسل وترًا: ثلاثًا أو خمسًا أو أكثر، بماء وسدر، ويجعل في الأخيرة كافورًا. ويُنزع قميصه وتستر عورته عند مالك وأبي حنيفة، ويُغسل في قميصه عند الشافعي.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"اغْسِلْنَهَا ثَلاَثًا أَوْ خَمْسًا أَوْ أَكْثَرَ مَنْ ذَلِكَ إِنْ رَأَيْتُنَّ ذَلِكَ بِمَاءٍ وَسِدْرٍ، وَاجْعَلْنَ فِي الآخِرَةِ كَافُورًا أَوْ شَيْئًا مِنْ كَافُورٍ، فَإِذَا فَرَغْتُنَّ فَآذِنَّنِي «. فَلَمَّا فَرَغْنَا آذَنَّاهُ فَأَعْطَانَا حِقْوَهُ فَقَالَ» أَشْعِرْنَهَا إِيَّاهُ","src":"رواه البخاري ١٢٥٣","pre":"عن أم عطية رضي الله عنها أن رسول الله ﷺ قال حين توفيت ابنته:","links":[{"book":"mt_bukhari","num":1253,"id":"h1253"}]},{"t":"quote","text":"ابْدَأْنَ بِمَيَامِنِهَا وَمَوَاضِعِ الْوُضُوءِ مِنْهَا","src":"رواه البخاري ١٢٥٥","pre":"وعنها رضي الله عنها قالت: قال رسول الله ﷺ في غسل ابنته:","links":[{"book":"mt_bukhari","num":1255,"id":"h1255"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"إِحْدَاهَا: هَلْ يُنْزَعُ عَنِ الْمَيِّتِ قَمِيصُهُ إِذَا غُسِّلَ؟ أَمْ يُغَسَّلُ فِي قَمِيصِهِ؟ اخْتَلَفُوا فِي ذَلِكَ: فَقَالَ مَالِكٌ: إِذَا غُسِّلَ الْمَيِّتُ تُنْزَعُ ثِيَابُهُ وَتُسْتَرُ عَوْرَتُهُ، وَبِهِ قَالَ أَبُو حَنِيفَةَ، وَقَالَ الشَّافِعِيُّ: يُغَسَّلُ فِي قَمِيصِهِ","src":"بداية المجتهد","loc":"١/٢٤٣","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر في صفة غسل الميت: أن يُستر عورته ما بين السرة والركبة، ثم يُجرّد من ثيابه، ويُرفع رأسه قليلًا ويُعصر بطنه برفق، ثم يلف الغاسل على يده خرقة فينجّيه، ثم يوضئه وضوء الصلاة، ويُدخل الماء فمه وأنفه بخرقة مبلولة دون أن يُدخل الماء جوفه، ثم يغسل رأسه ولحيته بماء وسدر، ثم يغسل شقه الأيمن ثم الأيسر، ثم يفيض الماء على سائر بدنه، يفعل ذلك ثلاثًا أو خمسًا أو أكثر وترًا حتى ينقى، ويجعل في الغسلة الأخيرة كافورًا، ثم ينشّفه."},{"t":"p","text":"والواجب غسلة واحدة تعمّ البدن مع النية، وما زاد سنة. وإن خرج منه شيء بعد الغسل غُسل الموضع وسُدّ بقطن ونحوه، ولا تُعاد الطهارة على الأظهر. ولا تُقص أظفاره ولا شعره عند الحنفية والمالكية، ورخص فيه بعض الشافعية والحنابلة إذا طالت، والأولى تركها. وشعر المرأة يُضفر ثلاثة قرون ويُلقى خلفها؛ لحديث أم عطية."}],"refs":["البخاري ١٢٥٣","البخاري ١٢٥٥","بداية المجتهد (١/٢٤٣)","بداية المجتهد (١/٢٤٤)"],"related":["من يغسل الميت: غسل الرجال للنساء والعكس، وغسل أحد الزوجين صاحبه","كفن الميت: عدده للرجل والمرأة، وكفن المحرم"],"alts":["كيفية غسل الميت","وضوء الميت","عدد غسلات الميت","قص أظافر الميت"]},{"n":187,"bab":"الجنائز","sub":"تكفين الميت","title":"كفن الميت: عدده للرجل والمرأة، وكفن المحرم","q":"كم ثوبًا يُكفن فيه الرجل؟ وكم المرأة؟ وما صفته ولونه؟ وإذا مات المحرم في الحج فهل يُغطى رأسه ويُطيب؟","short":"السنة عند الشافعي وأحمد أن يُكفن الرجل في ثلاث لفائف بيض، والمرأة في خمسة أثواب: إزار وخمار وقميص ولفافتين. وعند أبي حنيفة: السنة للرجل إزار وقميص ولفافة، وأقل ما يجزئ ثوبان، وللمرأة خمسة، وأقلها ثلاثة. وقال مالك: لا حدّ، ويجزئ ثوب واحد، ويستحب الوتر. واختلفوا في المحرم: فقال الشافعي وأحمد: لا يغطى رأسه ولا يطيب، وقال أبو حنيفة ومالك: هو كغير المحرم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كُفِّنَ فِي ثَلاَثَةِ أَثْوَابٍ يَمَانِيَةٍ بِيضٍ سَحُولِيَّةٍ مِنْ كُرْسُفٍ، لَيْسَ فِيهِنَّ قَمِيصٌ وَلاَ عِمَامَةٌ","src":"رواه البخاري ١٢٦٤","pre":"عن عائشة رضي الله عنها:","links":[{"book":"mt_bukhari","num":1264,"id":"h1264"}]},{"t":"quote","text":"الْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ","src":"رواه الترمذي ٩٩٤","pre":"وعن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":994,"id":"h994"}]},{"t":"quote","text":"بَيْنَمَا رَجُلٌ وَاقِفٌ بِعَرَفَةَ إِذْ وَقَعَ عَنْ رَاحِلَتِهِ فَوَقَصَتْهُ ـ أَوْ قَالَ فَأَوْقَصَتْهُ ـ قَالَ النَّبِيُّ صلى الله عليه وسلم «اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ، وَكَفِّنُوهُ فِي ثَوْبَيْنِ، وَلاَ تُحَنِّطُوهُ وَلاَ تُخَمِّرُوا رَأْسَهُ، فَإِنَّهُ يُبْعَثُ يَوْمَ الْقِيَامَةِ مُلَبِّيًا»","src":"رواه البخاري ١٢٦٥","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1265,"id":"h1265"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَمِنَ الْعُلَمَاءِ مَنْ أَخَذَ بِظَاهِرِ هَذَيْنِ الْأَثَرَيْنِ فَقَالَ: يُكَفَّنُ الرَّجُلُ فِي ثَلَاثَةِ أَثْوَابٍ، وَالْمَرْأَةُ فِي خَمْسَةِ أَثْوَابٍ، وَبِهِ قَالَ الشَّافِعِيُّ وَأَحْمَدُ وَجَمَاعَةٌ. وَقَالَ أَبُو حَنِيفَةَ: أَقَلُّ مَا تُكَفَّنُ فِيهِ الْمَرْأَةُ ثَلَاثَةُ أَثْوَابٍ، وَالسُّنَّةُ خَمْسَةُ أَثْوَابٍ، وَأَقَلُّ مَا يُكَفَّنُ فِيهِ الرَّجُلُ ثَوْبَانِ، وَالسُّنَّةُ فِيهِ ثَلَاثَةُ أَثْوَابٍ.","src":"بداية المجتهد","loc":"١/٢٤٥","pre":"قال ابن رشد:"},{"t":"quote","text":"في الصحيحين وغيرهما: أن كفنه ثلاث أردية، وهو مختار الشافعية، والخلاف في الأولوية لا الجواز","src":"العرف الشذي","loc":"٢/٣١٢","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن السنة أن يُكفن الرجل في ثلاث لفائف بيض، يُدرج فيها إدراجًا؛ لأن هذا كفن النبي ﷺ، ومن كفّنه في إزار وقميص ولفافة على مذهب الحنفية فلا حرج، فإن الخلاف في الأفضل لا في الجواز. وتكفن المرأة في خمسة أثواب: إزار، وخمار، وقميص، ولفافتين. والواجب ثوب واحد يستر جميع البدن. ويستحب أن يكون الكفن أبيض نظيفًا ساترًا، من غير إسراف ولا مغالاة، ويُطيَّب بالحنوط."},{"t":"p","text":"والمحرم إذا مات يُغسل بماء وسدر، ويُكفن في إحرامه، ولا يُغطى رأسه، ولا يُطيّب؛ لحديث ابن عباس الصريح في الصحيحين: «ولا تخمروا رأسه، فإنه يبعث يوم القيامة ملبيًا»، وهو قول الشافعي وأحمد، والمرأة المحرمة يُغطى رأسها ولا يُغطى وجهها."},{"t":"tanbih","items":[{"t":"p","text":"يُكفّن الميت من تركته مقدَّمًا على الدين والوصية والميراث، فإن لم يكن له مال فعلى من تلزمه نفقته، فإن لم يوجد فمن بيت المال أو من المسلمين."}]}],"refs":["البخاري ١٢٦٤","الترمذي ٩٩٤","البخاري ١٢٦٥","بداية المجتهد (١/٢٤٥)","العرف الشذي (٢/٣١٢)","بداية المجتهد (١/٢٤٦)"],"related":["صفة غسل الميت: الوضوء، والعدد، والسدر، وستر العورة"],"alts":["كفن الرجل","كفن المرأة","كم ثوبا الكفن","كفن المحرم","لون الكفن"]},{"n":188,"bab":"الجنائز","sub":"حمل الجنازة واتباعها","title":"اتباع الجنازة: المشي أمامها أو خلفها، والركوب، والقيام لها، واتباع النساء","q":"إذا خرجت مع الجنازة، فهل أمشي أمامها أو خلفها؟ وهل أركب السيارة؟ وإذا مرت جنازة فهل أقوم لها؟ وهل يجوز للنساء اتباع الجنائز؟","short":"اتفقوا على فضل اتباع الجنائز. واختلفوا في الأفضل: فقال أهل المدينة ومالك والشافعي وأحمد: المشي أمامها أفضل، وقال أبو حنيفة والكوفيون: المشي خلفها أفضل، والخلاف في الأفضل لا في الجواز. والراكب يسير خلفها. وأكثر العلماء على أن القيام للجنازة منسوخ، وذهب بعضهم إلى استحبابه. ويُكره للنساء اتباع الجنائز.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ شَهِدَ الْجَنَازَةَ حَتَّى يُصَلِّيَ عَلَيْهَا فَلَهُ قِيرَاطٌ، وَمَنْ شَهِدَ حَتَّى تُدْفَنَ كَانَ لَهُ قِيرَاطَانِ","src":"رواه البخاري ١٣٢٥","pre":"عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1325,"id":"h1325"}]},{"t":"quote","text":"رَأَيْتُ النَّبِيَّ صلى الله عليه وسلم وَأَبَا بَكْرٍ وَعُمَرَ يَمْشُونَ أَمَامَ الْجَنَازَةِ","src":"رواه أبو داود ٣١٧٩","pre":"وعن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":3179,"id":"h3179"}]},{"t":"quote","text":"الرَّاكِبُ يَسِيرُ خَلْفَ الْجَنَازَةِ وَالْمَاشِي يَمْشِي خَلْفَهَا وَأَمَامَهَا وَعَنْ يَمِينِهَا وَعَنْ يَسَارِهَا قَرِيبًا مِنْهَا","src":"رواه أبو داود ٣١٨٠","pre":"وعن المغيرة بن شعبة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":3180,"id":"h3180"}]},{"t":"quote","text":"إِذَا رَأَيْتُمُ الْجَنَازَةَ فَقُومُوا حَتَّى تُخَلِّفَكُمْ «. قَالَ سُفْيَانُ قَالَ الزُّهْرِيُّ أَخْبَرَنِي سَالِمٌ عَنْ أَبِيهِ قَالَ أَخْبَرَنَا عَامِرُ بْنُ رَبِيعَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم. زَادَ الْحُمَيْدِيُّ» حَتَّى تُخَلِّفَكُمْ أَوْ تُوضَعَ","src":"رواه البخاري ١٣٠٧","pre":"وعن عامر بن ربيعة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1307,"id":"h1307"}]},{"t":"quote","text":"قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَعَدَ","src":"رواه مسلم ٩٦٢","pre":"وعن علي بن أبي طالب رضي الله عنه قال:","links":[{"book":"mt_muslim","num":962,"id":"h962"}]},{"t":"quote","text":"نُهِينَا عَنِ اتِّبَاعِ الْجَنَائِزِ، وَلَمْ يُعْزَمْ عَلَيْنَا","src":"رواه البخاري ١٢٧٨","pre":"وعن أم عطية رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1278,"id":"h1278"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي سُنَّةِ الْمَشْيِ مَعَ الْجَنَازَةِ. فَذَهَبَ أَهْلُ الْمَدِينَةِ إِلَى أَنَّ مِنْ سُنَّتِهَا الْمَشْيَ أَمَامَهَا. وَقَالَ الْكُوفِيُّونَ وَأَبُو حَنِيفَةَ وَسَائِرُهُمْ: إِنَّ الْمَشْيَ خَلْفَهَا أَفْضَلُ","src":"بداية المجتهد","loc":"١/٢٤٦","pre":"قال ابن رشد:"},{"t":"quote","text":"الأفضل عندنا المشي خلف الجنازة لأنهم مودعوا الجنازة، والأفضل عند الشافعية المشي أمام الجنازة لأنهم شافعوه، والخلاف في الأولوية لا الجواز","src":"العرف الشذي","loc":"٢/٣١٨","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الماشي مع الجنازة يمشي حيث شاء: أمامها أو خلفها أو عن يمينها أو عن يسارها قريبًا منها؛ لحديث المغيرة، وكل ذلك ثابت عن السلف، فالمشي أمامها فعل النبي ﷺ وأبي بكر وعمر، والمشي خلفها اختيار علي رضي الله عنه وقول الحنفية، ولا ينبغي التنازع في ذلك. والراكب يسير خلفها، فمن ركب السيارة سار خلف الجنازة."},{"t":"p","text":"والقيام للجنازة إذا مرت مستحب غير واجب، وتركه جائز؛ لأن النبي ﷺ قام ثم قعد، فدل قعوده على أن الأمر للاستحباب، وهو أعدل الأقوال، ومن قال بالنسخ فله سلف. ويُكره للنساء اتباع الجنائز كراهة لا تبلغ التحريم؛ لقول أم عطية: «ولم يُعزم علينا». ويستحب لمتبع الجنازة الخشوع والتفكر وترك الحديث في أمور الدنيا ورفع الصوت."}],"refs":["البخاري ١٣٢٥","أبو داود ٣١٧٩","أبو داود ٣١٨٠","البخاري ١٣٠٧","مسلم ٩٦٢","البخاري ١٢٧٨","بداية المجتهد (١/٢٤٦)","العرف الشذي (٢/٣١٨)","بداية المجتهد (١/٢٤٧)"],"related":["حكم غسل الميت، وغسل الشهيد والصلاة عليه"],"alts":["المشي أمام الجنازة","القيام للجنازة","اتباع النساء للجنائز","الركوب مع الجنازة","فضل اتباع الجنازة"]},{"n":189,"bab":"الجنائز","sub":"صلاة الجنازة","title":"عدد التكبيرات في صلاة الجنازة، ورفع اليدين معها","q":"كم تكبيرة في صلاة الجنازة؟ وإذا كبّر الإمام خمسًا فهل أتابعه؟ وهل أرفع يدي في كل تكبيرة أو في الأولى فقط؟","short":"اختلف الصحابة في عدد التكبير على الجنازة من ثلاث إلى سبع، ثم استقر عمل فقهاء الأمصار والأئمة الأربعة على أنها أربع تكبيرات، وكان ابن أبي ليلى وجابر بن زيد يكبران خمسًا. وأجمعوا على رفع اليدين في التكبيرة الأولى، واختلفوا في سائرها: فقال الشافعي وأحمد: يرفع في كل تكبيرة، وقال أبو حنيفة ومالك في المشهور: لا يرفع إلا في الأولى.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَعَى النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، خَرَجَ إِلَى الْمُصَلَّى، فَصَفَّ بِهِمْ وَكَبَّرَ أَرْبَعًا","src":"رواه البخاري ١٢٤٥","pre":"عن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":1245,"id":"h1245"}]},{"t":"quote","text":"كَانَ زَيْدٌ يُكَبِّرُ عَلَى جَنَائِزِنَا أَرْبَعًا، وَإِنَّهُ كَبَّرَ عَلَى جَنَازَةٍ خَمْسًا، فَسَأَلْتُهُ فَقَالَ: «كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكَبِّرُهَا»","src":"رواه مسلم ٩٥٧","pre":"وعن عبد الرحمن بن أبي ليلى قال:","links":[{"book":"mt_muslim","num":957,"id":"h957"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهُ صلى الله عليه وسلم كَبَّرَ عَلَى جَنَازَةٍ فَرَفَعَ يَدَيْهِ فِي أَوَّلِ تَكْبِيرَةٍ وَوَضَعَ الْيُمْنَى عَلَى الْيُسْرَى","src":"رواه الترمذي ١٠٧٧","pre":"وعن أبي هريرة رضي الله عنه:","links":[{"book":"mt_tirmidhi","num":1077,"id":"h1077"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفُوا فِي عَدَدِ التَّكْبِيرِ فِي الصَّدْرِ الْأَوَّلِ اخْتِلَافًا كَثِيرًا مِنْ ثَلَاثٍ إِلَى سَبْعٍ - أَعْنِي: الصَّحَابَةَ - رَضِيَ اللَّهُ عَنْهُمْ -، وَلَكِنَّ فُقَهَاءَ الْأَمْصَارِ عَلَى أَنَّ التَّكْبِيرَ فِي الْجَنَازَةِ أَرْبَعٌ، إِلَّا ابْنَ أَبِي لَيْلَى وَجَابِرَ بْنَ زَيْدٍ فَإِنَّهُمَا كَانَا يَقُولان إِنَّها خَمْسٌ","src":"بداية المجتهد","loc":"١/٢٤٨","pre":"قال ابن رشد:"},{"t":"quote","text":"أثبتت التكبيرات من ثلاثة أو أربعة إلى تسعة، وعمل الفقهاء الأربعة بأربع تكبيرات، واستقر عليه الأمر في عهد عمر وقالوا: إن منتهى فعله أربع تكبيرات، وفي بعض كتبنا أنه لا يتبع من كبر خمس تكبيرات أقول: إن الاتباع في ما هو مجتهد فيه جائز سيما إذا كان خمس تكبيرات مروية عن أبي يوسف في مبسوط السرخسي","src":"العرف الشذي","loc":"٢/٣٢٥","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"وَاخْتَلَفَ أَهْلُ الْعِلْمِ فِي هَذَا فَرَأَى أَكْثَرُ أَهْلِ الْعِلْمِ مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم وَغَيْرِهِمْ أَنْ يَرْفَعَ الرَّجُلُ يَدَيْهِ فِي كُلِّ تَكْبِيرَةٍ عَلَى الْجَنَازَةِ . وَهُوَ قَوْلُ ابْنِ الْمُبَارَكِ وَالشَّافِعِيِّ وَأَحْمَدَ وَإِسْحَاقَ . وَقَالَ بَعْضُ أَهْلِ الْعِلْمِ لاَ يَرْفَعُ يَدَيْهِ إِلاَّ فِي أَوَّلِ مَرَّةٍ . وَهُوَ قَوْلُ الثَّوْرِيِّ وَأَهْلِ الْكُوفَةِ","src":"رواه الترمذي ١٠٧٧","pre":"وقال الترمذي في رفع اليدين:","links":[{"book":"mt_tirmidhi","num":1077,"id":"h1077"}]},{"t":"quote","text":"من قال برفع اليدين في الصلاة المكتوبة قال بالرفع في الجنازة، ومن لم يقل به فيها، لم يقل به فيها، وذهب مشائخنا البلخية إلى ما قال الشافعي، والخلاف في الأفضلية وليس المرفوع لأحد","src":"العرف الشذي","loc":"٢/٣٥٢","pre":"وقال الكشميري:"},{"t":"quote","text":"ثُمَّ يُكَبِّرُ أَرْبَعَ تَكْبِيرَاتٍ وَكَانَ ابْنُ أَبِي لَيْلَى يَقُولُ: خَمْسُ تَكْبِيرَاتٍ وَهُوَ رِوَايَةٌ عَنْ أَبِي يُوسُفَ","src":"بدائع الصنائع","loc":"١/٣١٢","pre":"وقال الكاساني الحنفي في «بدائع الصنائع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"المشروع في الصلاة على الجنازة أن يكبر أربع تكبيرات؛ يقرأ الفاتحة بعد التكبيرة الأولى، ويصلي على النبي صلى الله عليه وسلم بعد الثانية","src":"فتاوى اللجنة الدائمة","loc":"٨/٣٧٦","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التكبير على الجنازة أربع تكبيرات، وهو الذي استقر عليه العمل، وعليه الأئمة الأربعة، وثبت في الصحيحين في صلاة النبي ﷺ على النجاشي. وقد ثبت أنه ﷺ كبر خمسًا أحيانًا، فمن صلى خلف إمام يكبر خمسًا تابعه؛ لأنه أمر مجتهد فيه ثابت عن النبي ﷺ، كما قال الكشميري وغيره."},{"t":"p","text":"ورفع اليدين في التكبيرة الأولى سنة بالإجماع، وأما في سائر التكبيرات فالأمر واسع: فمن رفع فله سلف من الصحابة كابن عمر، وهو قول أكثر أهل العلم كما ذكر الترمذي، ومن لم يرفع فهو قول الحنفية والمالكية، وليس في المسألة حديث مرفوع صحيح صريح."}],"refs":["البخاري ١٢٤٥","مسلم ٩٥٧","الترمذي ١٠٧٧","بداية المجتهد (١/٢٤٨)","العرف الشذي (٢/٣٢٥)","العرف الشذي (٢/٣٥٢)","بدائع الصنائع (١/٣١٢)","فتاوى اللجنة الدائمة (٨/٣٧٦)","بداية المجتهد (١/٢٢٦-٢٤٨)"],"related":["القراءة والدعاء في صلاة الجنازة","صفة صلاة الجنازة: التسليم، وموقف الإمام من الرجل والمرأة"],"alts":["عدد تكبيرات الجنازة","التكبير خمسا على الجنازة","رفع اليدين في صلاة الجنازة"]},{"n":190,"bab":"الجنائز","sub":"صلاة الجنازة","title":"القراءة والدعاء في صلاة الجنازة","q":"هل أقرأ الفاتحة في صلاة الجنازة؟ وما الذي أقوله بعد كل تكبيرة؟ وما الدعاء المأثور للميت؟","short":"ذهب الشافعي وأحمد إلى أن قراءة الفاتحة بعد التكبيرة الأولى ركن في صلاة الجنازة. وذهب أبو حنيفة ومالك إلى أنه ليس فيها قراءة، وإنما هي ثناء ودعاء، ولو قرأ الفاتحة بنية الثناء والدعاء فلا بأس. واتفقوا على أن الدعاء للميت هو مقصود الصلاة، وعلى مشروعية الصلاة على النبي ﷺ فيها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّيْتُ خَلْفَ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ عَلَى جَنَازَةٍ فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ قَالَ لِيَعْلَمُوا أَنَّهَا سُنَّةٌ","src":"رواه البخاري ١٣٣٥","pre":"عن طلحة بن عبد الله بن عوف قال:","links":[{"book":"mt_bukhari","num":1335,"id":"h1335"}]},{"t":"quote","text":"السُّنَّةُ فِي الصَّلاَةِ عَلَى الْجَنَازَةِ أَنْ يَقْرَأَ فِي التَّكْبِيرَةِ الأُولَى بِأُمِّ الْقُرْآنِ مُخَافَتَةً ثُمَّ يُكَبِّرَ ثَلاَثًا وَالتَّسْلِيمُ عِنْدَ الآخِرَةِ","src":"رواه النسائي ١٩٨٩","pre":"وعن أبي أمامة رضي الله عنه قال:","links":[{"book":"mt_nasai","num":1989,"id":"h1989"}]},{"t":"quote","text":"إِذَا صَلَّيْتُمْ عَلَى الْمَيِّتِ فَأَخْلِصُوا لَهُ الدُّعَاءَ","src":"رواه أبو داود ٣١٩٩","pre":"وعن أبي هريرة رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_abudawud","num":3199,"id":"h3199"}]},{"t":"quote","text":"اللهُمَّ، اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ - أَوْ مِنْ عَذَابِ النَّارِ","src":"رواه مسلم ٩٦٣","pre":"وعن عوف بن مالك رضي الله عنه قال: صلى رسول الله ﷺ على جنازة، فحفظت من دعائه وهو يقول:","links":[{"book":"mt_muslim","num":963,"id":"h963"}]},{"t":"quote","text":"اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا وَشَاهِدِنَا وَغَائِبِنَا اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الإِيمَانِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِسْلاَمِ اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ وَلاَ تُضِلَّنَا بَعْدَهُ","src":"رواه أبو داود ٣٢٠١","pre":"وعن أبي هريرة رضي الله عنه قال: صلى رسول الله ﷺ على جنازة فقال:","links":[{"book":"mt_abudawud","num":3201,"id":"h3201"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"اخْتَلَفَ النَّاسُ فِي الْقِرَاءَةِ فِي صَلَاةِ الْجَنَازَةِ: فَقَالَ مَالِكٌ وَأَبُو حَنِيفَةَ: لَيْسَ فِيهَا قِرَاءَةٌ إِنَّمَا هُوَ الدُّعَاءُ.","src":"بداية المجتهد","loc":"١/٢٤٩","pre":"قال ابن رشد:"},{"t":"quote","text":"لا يجب الفاتحة في صلاة الجنازة، وعند مالك وأبي حنيفة ولو قرأها فلا بأس، وقال الشافعي: إن قراءة الفاتحة فريضة، وفي رسالة الأتباع في مسألة الاستماع للشرنبلالي في استحباب سورة الفاتحة في الجنازة بنية الثناء، وفي فتاوى ابن تيمية أن السلف كان يقرأ بها بعضهم لا بعضهم","src":"العرف الشذي","loc":"٢/٣٢٨","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن يقرأ المصلي الفاتحة سرًّا بعد التكبيرة الأولى؛ لقول ابن عباس: «ليعلموا أنها سنة»، وقول أبي أمامة، وقول الصحابي: «من السنة» له حكم الرفع، وفي ذلك خروج من خلاف من أوجبها، والحنفية لا يمنعون قراءتها بنية الثناء. ثم يكبر الثانية ويصلي على النبي ﷺ بالصلاة الإبراهيمية، ثم يكبر الثالثة ويدعو للميت ويخلص له الدعاء بما ورد، ثم يكبر الرابعة ويقف قليلًا يدعو، ثم يسلم."},{"t":"p","text":"ومن الدعاء المأثور: «اللهم اغفر له وارحمه، وعافه واعف عنه، وأكرم نزله، ووسع مدخله، واغسله بالماء والثلج والبرد، ونقه من الخطايا كما نقيت الثوب الأبيض من الدنس، وأبدله دارًا خيرًا من داره، وأهلًا خيرًا من أهله، وأدخله الجنة، وأعذه من عذاب القبر ومن عذاب النار». ويدعو للطفل بأن يجعله الله فرطًا وذخرًا لوالديه، وشفيعًا مجابًا."}],"refs":["البخاري ١٣٣٥","النسائي ١٩٨٩","أبو داود ٣١٩٩","مسلم ٩٦٣","أبو داود ٣٢٠١","بداية المجتهد (١/٢٤٩)","العرف الشذي (٢/٣٢٨)"],"related":["عدد التكبيرات في صلاة الجنازة، ورفع اليدين معها"],"alts":["قراءة الفاتحة في صلاة الجنازة","دعاء صلاة الجنازة","كيفية صلاة الجنازة","الدعاء للميت"]},{"n":191,"bab":"الجنائز","sub":"صلاة الجنازة","title":"صفة صلاة الجنازة: التسليم، وموقف الإمام من الرجل والمرأة","q":"هل يسلّم في صلاة الجنازة تسليمة واحدة أو تسليمتين؟ وأين يقف الإمام من الميت إذا كان رجلًا أو امرأة؟","short":"الجمهور على أن التسليم في صلاة الجنازة تسليمة واحدة عن اليمين، وقال أبو حنيفة والشافعي في أحد قوليه: تسليمتان. واختلفوا في موقف الإمام: فقال الشافعي وأحمد: يقف عند رأس الرجل ووسط المرأة، وقال أبو حنيفة في المشهور: يقف حذاء الصدر منهما، وروي عنه مثل قول الشافعي، وقال مالك: يقف وسط الرجل وعند منكبي المرأة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صَلَّيْتُ وَرَاءَ النَّبِيِّ صلى الله عليه وسلم عَلَى امْرَأَةٍ مَاتَتْ فِي نِفَاسِهَا فَقَامَ عَلَيْهَا وَسَطَهَا","src":"رواه البخاري ١٣٣٢","pre":"عن سمرة بن جندب رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1332,"id":"h1332"}]},{"t":"quote","text":"صَلَّيْتُ مَعَ أَنَسِ بْنِ مَالِكٍ عَلَى جَنَازَةِ رَجُلٍ فَقَامَ حِيَالَ رَأْسِهِ ثُمَّ جَاءُوا بِجَنَازَةِ امْرَأَةٍ مِنْ قُرَيْشٍ فَقَالُوا يَا أَبَا حَمْزَةَ صَلِّ عَلَيْهَا . فَقَامَ حِيَالَ وَسَطِ السَّرِيرِ . فَقَالَ لَهُ الْعَلاَءُ بْنُ زِيَادٍ هَكَذَا رَأَيْتَ النَّبِيَّ صلى الله عليه وسلم قَامَ عَلَى الْجَنَازَةِ مُقَامَكَ مِنْهَا وَمِنَ الرَّجُلِ مُقَامَكَ مِنْهُ قَالَ نَعَمْ","src":"رواه الترمذي ١٠٣٤","pre":"وعن أبي غالب قال:","links":[{"book":"mt_tirmidhi","num":1034,"id":"h1034"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي التَّسْلِيمِ مِنَ الْجَنَازَةِ هَلْ هُوَ وَاحِدٌ أَوِ اثْنَانِ؟ فَالْجُمْهُورُ عَلَى أَنَّهُ وَاحِدٌ، وَقَالَتْ طَائِفَةٌ وَأَبُو حَنِيفَةَ: يُسَلِّمُ تَسْلِيمَتَيْنِ، وَاخْتَارَهُ الْمُزَنِيُّ مِنْ أَصْحَابِ الشَّافِعِيِّ، وَهُوَ أَحَدُ قَوْلَيِ الشَّافِعِيِّ","src":"بداية المجتهد","loc":"١/٢٥٠","pre":"قال ابن رشد:"},{"t":"quote","text":"المشهور عندنا أن يقوم حذاء الصدر، وقال الشافعي: يقوم حذاء رأسه وحذاء عجيزتها، وللشافعي ما أخرجه الترمذي وأبو داود، وأقول: روي عن أبي حنيفة مثل ما قال الشافعي كما في الهداية ص (161) ، ونقل الطحاوي هذه الرواية عن أبي يوسف وتعرض صاحب الهداية إلى حديث أبي داود، أقول: لا احتياج إلى التأويل بعد ثبوت الروايتين عن الإمامين","src":"العرف الشذي","loc":"٢/٣٣٢","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الإمام يقف عند رأس الرجل وعند وسط المرأة؛ لحديث أنس وسمرة، وفيه زيادة على حديث سمرة، ولا تعارض بينهما، وهو رواية عن أبي حنيفة أيضًا. ومن وقف عند صدر الميت كما هو المشهور عند الحنفية فصلاته صحيحة. ويسلم تسليمة واحدة عن يمينه، وهو قول الجمهور، ومن سلم تسليمتين فلا حرج."},{"t":"tanbih","items":[{"t":"p","text":"إذا اجتمعت جنائز رجال ونساء وصبيان صُلّي عليها صلاة واحدة، ويجعل الرجال مما يلي الإمام، ثم الصبيان، ثم النساء مما يلي القبلة، وهو قول أكثر أهل العلم."}]}],"refs":["البخاري ١٣٣٢","الترمذي ١٠٣٤","بداية المجتهد (١/٢٥٠)","العرف الشذي (٢/٣٣٢)","بداية المجتهد (١/٢٥١)"],"related":["القراءة والدعاء في صلاة الجنازة"],"alts":["التسليم في صلاة الجنازة","أين يقف الإمام في صلاة الجنازة","اجتماع الجنائز"]},{"n":192,"bab":"الجنائز","sub":"صلاة الجنازة","title":"المسبوق في صلاة الجنازة، والصلاة على القبر، والصلاة على الغائب","q":"جئت والإمام قد كبر بعض التكبيرات على الجنازة فماذا أفعل؟ وإذا فاتتني الصلاة على الميت فهل أصلي على قبره؟ وهل يصلى صلاة الغائب على من مات في بلد آخر؟","short":"اتفق مالك وأبو حنيفة والشافعي على أن المسبوق يقضي ما فاته من التكبير، واختلفوا: هل يكبر حين يدخل، أو ينتظر تكبيرة الإمام؟ وأجاز الشافعي وأحمد الصلاة على القبر لمن فاتته الصلاة، ومنعها مالك وأبو حنيفة إن كان قد صُلّي عليه، إلا للولي عند أبي حنيفة. وأجاز الشافعي وأحمد الصلاة على الغائب، ومنعها أبو حنيفة ومالك، وقالوا: صلاة النبي ﷺ على النجاشي خاصة به.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ أَسْوَدَ ـ رَجُلاً أَوِ امْرَأَةً ـ كَانَ يَقُمُّ الْمَسْجِدَ فَمَاتَ، وَلَمْ يَعْلَمِ النَّبِيُّ صلى الله عليه وسلم بِمَوْتِهِ فَذَكَرَهُ ذَاتَ يَوْمٍ فَقَالَ «مَا فَعَلَ ذَلِكَ الإِنْسَانُ». قَالُوا مَاتَ يَا رَسُولَ اللَّهِ. قَالَ «أَفَلاَ آذَنْتُمُونِي». فَقَالُوا إِنَّهُ كَانَ كَذَا وَكَذَا قِصَّتَهُ. قَالَ فَحَقَرُوا شَأْنَهُ. قَالَ «فَدُلُّونِي عَلَى قَبْرِهِ». فَأَتَى قَبْرَهُ فَصَلَّى عَلَيْهِ","src":"رواه البخاري ١٣٣٧","pre":"عن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":1337,"id":"h1337"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم نَعَى النَّجَاشِيَّ فِي الْيَوْمِ الَّذِي مَاتَ فِيهِ، خَرَجَ إِلَى الْمُصَلَّى، فَصَفَّ بِهِمْ وَكَبَّرَ أَرْبَعًا","src":"رواه البخاري ١٢٤٥","pre":"وعن أبي هريرة رضي الله عنه:","links":[{"book":"mt_bukhari","num":1245,"id":"h1245"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَرَوَى أَشْهَبُ عَنْ مَالِكٍ أَنَّهُ يُكَبَّرُ أَوَّلَ دُخُولِهِ، وَهُوَ أَحَدُ قَوْلَيِ الشَّافِعِيِّ. وَقَالَ أَبُو حَنِيفَةَ: يَنْتَظِرُ حَتَّى يُكَبِّرَ الْإِمَامُ وَحِينَئِذٍ يُكَبِّرُ، وَهِيَ رِوَايَةُ ابْنِ الْقَاسِمِ عَنْ مَالِكٍ، وَالْقِيَاسُ التَّكْبِيرُ قِيَاسًا عَلَى مَنْ دَخَلَ فِي الْمَفْرُوضَةِ.","src":"بداية المجتهد","loc":"١/٢٥٢","pre":"قال ابن رشد في المسبوق:"},{"t":"quote","text":"قال مالك وأبو حنيفة: لا يصلى على القبر إن صلي عليه قبلُ، وإن دفن بلا صلاة يصلى عليه ما لم يتفسخ، وقال الشافعي وأحمد: يجوز الصلاة على القبر لمن كان يريد الصلاة من أهل الجنازة وإن صلي عليه مرة، ثم قال أحمد: يجوز الصلاة إلى شهر لا بعده لأن صلاته على القبر ثبتت إلى شهر لا بعده","src":"العرف الشذي","loc":"٢/٣٣٤","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"الصلاة على الغائب فيها تفصيل: بعض أهل العلم يرى أنه لا يصلى على الغائب، وبعضهم يرى الصلاة عليه، لكن إذا كان الغائب له شأن في الإسلام، كالنجاشي رحمه الله، فإن النبي صلى الله عليه وسلم صلى على النجاشي، لما مات في بلاده","src":"فتاوى نور على الدرب لابن باز","loc":"١٤/٣٢","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"أما الصلاة على الغائب فالصحيح أنها ليست بسنة إلا من لم يصل عليه؛ مثل أن يموت في بر، أو في دار كفر ولا يُعلم أنه صُلي عليه؛ فالصلاة عليه واجبة","src":"مجموع فتاوى ابن عثيمين","loc":"١٧/١٤٦","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"قد يكون سبب الاختلاف بين أئمة الفقه الاختلاف في فهم الحديث، وقد يكون لعدم بلوغ الحديث لبعضهم، وقد يكون لاختلافهم في الترجيح عند تعارض الأدلة، وقد يكون لاختلافهم في نسخ النص، وقد يكون لغير ذلك وإذا أردت التوسع فاقرأ كتاب (رفع الملام عن الأئمة الأعلام) لشيخ الإسلام أحمد بن تيمية رحمه الله، تجد ما يشفي إن شاء الله","src":"فتاوى اللجنة الدائمة","loc":"٥/٢٨","pre":"وسئلت اللجنة الدائمة عن الحكمة في اختلاف الأئمة، كاختلافهم في الصلاة على الغائب، فأجابت:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن المسبوق في صلاة الجنازة يدخل مع الإمام حين يأتي فيكبر ويتابعه، ويجعل ما أدركه أول صلاته، فإذا سلم الإمام قضى ما فاته من التكبيرات، فإن خشي أن تُرفع الجنازة تابع التكبير متواليًا ثم سلم، وإن انتظر حتى يكبر الإمام كما يقول الحنفية فلا حرج."},{"t":"p","text":"ومن فاتته الصلاة على الميت صلى على قبره، ولو كان قد صُلّي عليه؛ لصلاة النبي ﷺ على قبر المرأة التي كانت تقم المسجد، والأحسن ألا يتجاوز ذلك شهرًا، كما قال أحمد. والصلاة على الغائب مشروعة لمن مات في بلد لم يُصلّ عليه فيه، كالنجاشي، أو لمن كان له شأن في الإسلام من العلماء والصالحين؛ جمعًا بين الأقوال، وأما الصلاة على كل غائب فلم يكن من هديه ﷺ، فقد مات خلق كثير من الصحابة غائبين فلم يصل عليهم."}],"refs":["البخاري ١٣٣٧","البخاري ١٢٤٥","بداية المجتهد (١/٢٥٢)","العرف الشذي (٢/٣٣٤)","بداية المجتهد (١/٢٥٦)","فتاوى نور على الدرب لابن باز (١٤/٣٢)","مجموع فتاوى ابن عثيمين (١٧/١٤٦)","فتاوى اللجنة الدائمة (٥/٢٨)"],"related":["عدد التكبيرات في صلاة الجنازة، ورفع اليدين معها","من يُصلّى عليه: أهل الكبائر، وقاتل نفسه، والسقط والطفل"],"alts":["المسبوق في صلاة الجنازة","الصلاة على القبر","صلاة الغائب","فاتتني صلاة الجنازة"]},{"n":193,"bab":"الجنائز","sub":"صلاة الجنازة","title":"من يُصلّى عليه: أهل الكبائر، وقاتل نفسه، والسقط والطفل","q":"هل يُصلى على تارك الصلاة وشارب الخمر وصاحب الكبيرة؟ وعلى من قتل نفسه؟ والسقط الذي ولد ميتًا، هل يغسل ويصلى عليه ويسمى؟","short":"أجمع أكثر أهل العلم على الصلاة على كل من قال: لا إله إلا الله، وإن كان من أهل الكبائر، وكره مالك لأهل الفضل الصلاة على أهل البدع. واختلفوا فيمن قتل نفسه: فصلى عليه الجمهور، وقال أحمد: لا يصلي عليه الإمام ويصلي عليه سائر الناس، وروي عن أبي حنيفة وأبي يوسف وعمر بن عبد العزيز والأوزاعي أنه لا يُصلّى عليه. وأما السقط: فقال مالك والشافعي: لا يصلى عليه حتى يستهل صارخًا، وقال أحمد: يصلى عليه إذا نفخت فيه الروح، أي بعد أربعة أشهر، وقال أبو حنيفة: إن عُلمت حياته صُلّي عليه، وإلا غُسّل ودُفن بلا صلاة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أُتِيَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِرَجُلٍ قَتَلَ نَفْسَهُ بِمَشَاقِصَ، فَلَمْ يُصَلِّ عَلَيْهِ","src":"رواه مسلم ٩٧٨","pre":"عن جابر بن سمرة رضي الله عنه قال:","links":[{"book":"mt_muslim","num":978,"id":"h978"}]},{"t":"quote","text":"كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صلى الله عليه وسلم إِذْ أُتِيَ بِجَنَازَةٍ، فَقَالُوا صَلِّ عَلَيْهَا. فَقَالَ «هَلْ عَلَيْهِ دَيْنٌ». قَالُوا لاَ. قَالَ «فَهَلْ تَرَكَ شَيْئًا». قَالُوا لاَ. فَصَلَّى عَلَيْهِ ثُمَّ أُتِيَ بِجَنَازَةٍ أُخْرَى، فَقَالُوا يَا رَسُولَ اللَّهِ، صَلِّ عَلَيْهَا. قَالَ «هَلْ عَلَيْهِ دَيْنٌ». قِيلَ نَعَمْ. قَالَ «فَهَلْ تَرَكَ شَيْئًا». قَالُوا ثَلاَثَةَ دَنَانِيرَ. فَصَلَّى عَلَيْهَا","src":"رواه البخاري ٢٢٨٩","pre":"وعن سلمة بن الأكوع رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":2289,"id":"h2289"}]},{"t":"quote","text":"وَالسِّقْطُ يُصَلَّى عَلَيْهِ وَيُدْعَى لِوَالِدَيْهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ","src":"رواه أبو داود ٣١٨٠","pre":"وعن المغيرة بن شعبة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":3180,"id":"h3180"}]},{"t":"quote","text":"الطِّفْلُ لاَ يُصَلَّى عَلَيْهِ وَلاَ يَرِثُ وَلاَ يُورَثُ حَتَّى يَسْتَهِلَّ «. قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ قَدِ اضْطَرَبَ النَّاسُ فِيهِ فَرَوَاهُ بَعْضُهُمْ عَنْ أَبِي الزُّبَيْرِ عَنْ جَابِرٍ عَنِ النَّبِيِّ صلى الله عليه وسلم مَرْفُوعًا . وَرَوَى أَشْعَثُ بْنُ سَوَّارٍ وَغَيْرُ وَاحِدٍ عَنْ أَبِي الزُّبَيْرِ عَنْ جَابِرٍ مَوْقُوفًا . وَرَوَى مُحَمَّدُ بْنُ إِسْحَاقَ عَنْ عَطَاءِ بْنِ أَبِي رَبَاحٍ عَنْ جَابِرٍ مَوْقُوفًا . وَكَأَنَّ هَذَا أَصَحُّ مِنَ الْحَدِيثِ الْمَرْفُوعِ . وَقَدْ ذَهَبَ بَعْضُ أَهْلِ الْعِلْمِ إِلَى هَذَا قَالُوا لاَ يُصَلَّى عَلَى الطِّفْلِ حَتَّى يَسْتَهِلَّ . وَهُوَ قَوْلُ سُفْيَانَ الثَّوْرِيِّ وَالشَّافِعِيِّ»","src":"رواه الترمذي ١٠٣٢","pre":"وعن جابر رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":1032,"id":"h1032"}]},{"t":"p","text":"قال الترمذي: هذا حديث قد اضطرب الناس فيه، رواه بعضهم مرفوعًا، وبعضهم موقوفًا."},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أكثر أهل العلم على أنه يُصلّى على كل من قال: لا إله إلا الله، ولو كان من أهل الكبائر، إلا أن مالكًا كره لأهل الفضل أن يصلوا على أهل البدع، ورأى ألا يصلي الإمام على من قتله حدًّا. واختلفوا في قاتل نفسه: فقال الجمهور: يُصلّى عليه كسائر العصاة، وقال بعضهم: لا يُصلّى عليه، وتوسط آخرون فقالوا: لا يصلي عليه الإمام وأهل الفضل زجرًا، ويصلي عليه سائر الناس."},{"t":"quote","text":"قال الفقهاء: يصلى على كل من يدعي الإسلام وإن كان فاسقاً فاجراً إلا على قاتل نفسه وقاتل أبويه عند أبي حنيفة، وروي عن أبي يوسف لا يصلى على الباغي، ولم يرو عن أبي حنيفة","src":"العرف الشذي","loc":"٢/٣٤٨","pre":"وقال الكشميري:"},{"t":"quote","text":"قال أبو حنيفة: إن علم علامة حياة الولد فيغسل ويكفن ويصلى عليه وإن لم يعلم حياته فَسِقْط فيغسل ويدفن بلا صلاة","src":"العرف الشذي","loc":"٢/٣٣٠","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"يصلي عليه بعض المسلمين كسائر العصاة؛ لأنه لا يزال في حكم الإسلام عند أهل السنة","src":"مجموع فتاوى ابن باز","loc":"١٣/١٦٢","pre":"سئل الشيخ عبد العزيز بن باز رحمه الله عمن قتل نفسه فقال:"},{"t":"quote","text":"القاتل نفسه يصلى عليه، ولكن لا يصلي عليه السلطان العام؛ لأن النبي صلى الله عليه وسلم لم يصل على قاتل نفسه تعظيما لهذه الجريمة، وتحذيرا منها","src":"فتاوى اللجنة الدائمة","loc":"٨/٣٩٤","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن كل مسلم يُصلّى عليه وإن كان من أهل الكبائر؛ لأنه لا يخرج بكبيرته من الإسلام، وهو أحوج ما يكون إلى الدعاء. ويُستحب للإمام وأهل الفضل أن يتركوا الصلاة على المجاهر بالكبائر وقاتل نفسه زجرًا لغيره، كما ترك النبي ﷺ الصلاة على قاتل نفسه، وعلى المدين في أول الأمر، وأمر الناس أن يصلوا عليه، فيصلي عليه سائر المسلمين."},{"t":"p","text":"وأما السقط، فإن استهل صارخًا أو ظهرت عليه علامة الحياة غُسّل وكُفّن وصُلّي عليه وورث وورث بالاتفاق، وإن لم يستهل وقد تم له أربعة أشهر فالأظهر أنه يغسل ويصلى عليه ويسمى؛ لحديث المغيرة، ولأنه نفخت فيه الروح، وهو قول أحمد، ومن لم يصل عليه أخذًا بقول الجمهور فلا حرج. وإن سقط قبل أربعة أشهر لُفّ في خرقة ودُفن بلا غسل ولا صلاة."},{"t":"tanbih","items":[{"t":"p","text":"من أخذ بقول من لا يرى الصلاة على تارك الصلاة كسلًا، بناءً على تكفيره، فقد تقدمت المسألة في حكم تارك الصلاة، والأحوط لعامة الناس الصلاة على من مات منتسبًا إلى الإسلام، وأمره إلى الله."}]}],"refs":["مسلم ٩٧٨","البخاري ٢٢٨٩","أبو داود ٣١٨٠","الترمذي ١٠٣٢","العرف الشذي (٢/٣٤٨)","العرف الشذي (٢/٣٣٠)","مجموع فتاوى ابن باز (١٣/١٦٢)","فتاوى اللجنة الدائمة (٨/٣٩٤)"],"related":["حكم تارك الصلاة","المسبوق في صلاة الجنازة، والصلاة على القبر، والصلاة على الغائب"],"alts":["الصلاة على المنتحر","الصلاة على صاحب الكبيرة","الصلاة على السقط","تسمية السقط","الصلاة على تارك الصلاة"]},{"n":194,"bab":"الجنائز","sub":"صلاة الجنازة","title":"الصلاة على الجنازة في المسجد والمقبرة، وفي أوقات النهي، وشروطها","q":"هل تجوز الصلاة على الجنازة داخل المسجد؟ وهل نصلي عليها في المقبرة؟ وإذا حضرت الجنازة بعد العصر أو عند طلوع الشمس فهل نصلي عليها؟ وهل يتيمم لها من خاف فوتها؟","short":"أجاز الشافعي وأحمد الصلاة على الجنازة في المسجد بلا كراهة، وكرهها أبو حنيفة ومالك في رواية إذا كانت الجنازة خارجه والناس فيه أو داخله. وأجمعوا على جوازها بعد الصبح وبعد العصر، واختلفوا في أوقات الطلوع والزوال والغروب: فمنعها أبو حنيفة ومالك وأحمد، وأجازها الشافعي في كل وقت. واتفق الأكثر على أن من شرطها الطهارة واستقبال القبلة، وأجاز أبو حنيفة التيمم لها لمن خاف فوتها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَاللهِ، لَقَدْ صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى ابْنَيْ بَيْضَاءَ فِي الْمَسْجِدِ سُهَيْلٍ وَأَخِيهِ","src":"رواه مسلم ٩٧٣","pre":"عن عائشة رضي الله عنها أنها لما أمرت أن يُمر بجنازة سعد بن أبي وقاص في المسجد فأنكر الناس ذلك عليها، قالت:","links":[{"book":"mt_muslim","num":973,"id":"h973-3"}]},{"t":"quote","text":"مَنْ صَلَّى عَلَى جَنَازَةٍ فِي الْمَسْجِدِ فَلاَ شَىْءَ عَلَيْهِ","src":"رواه أبو داود ٣١٩١","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":3191,"id":"h3191"}]},{"t":"p","text":"وفي رواية: «فلا شيء له»، وفي إسناده صالح مولى التوأمة وقد تكلم فيه."},{"t":"quote","text":"ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ، أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا: «حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ، وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ حَتَّى تَغْرُبَ»","src":"رواه مسلم ٨٣١","pre":"وعن عقبة بن عامر الجهني رضي الله عنه قال:","links":[{"book":"mt_muslim","num":831,"id":"h831"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي الصَّلَاةِ عَلَى الْجَنَازَةِ فِي الْمَسْجِدِ: فَأَجَازَهَا الْعُلَمَاءُ وَكَرِهَهَا بَعْضُهُمْ مِنْهُمْ أَبُو حَنِيفَةَ وَبَعْضُ أَصْحَابِ مَالِكٍ، وَقَدْ رُوِيَ كَرَاهِيَةُ ذَلِكَ عَنْ مَالِكٍ، وَتَحْقِيقُهُ: إِذَا كَانَتِ الْجَنَازَةُ خَارِجَ الْمَسْجِدِ وَالنَّاسُ فِي الْمَسْجِدِ","src":"بداية المجتهد","loc":"١/٢٥٦","pre":"قال ابن رشد:"},{"t":"quote","text":"تكره الصلاة على الجنازة في المسجد عندنا وإن كان الميت خارج المسجد، واختار العلامة قاسم بن قطلوبغا الكراهة تحريماً وشيخه ابن همام تنزيهاً، ولعل هذه الكراهة بين التحريمية والتنزيهية وتسمى بالإساءة كما قال صدر الإسلام أبو اليسر، والأفضل عند الحجازيين أيضاً خارج المسجد ويجوز في داخل المسجد بلا كراهة","src":"العرف الشذي","loc":"٢/٣٣١","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الصلاة على الجنازة في المسجد جائزة بلا كراهة؛ لحديث عائشة الصحيح في صلاة النبي ﷺ على ابني بيضاء في المسجد، وقد صُلّي على أبي بكر وعمر رضي الله عنهما في المسجد، والأفضل أن يكون لها مصلى خارج المسجد إن تيسر، كما كان على عهد النبي ﷺ غالبًا، وفي ذلك مراعاة لقول الحنفية. وتجوز الصلاة عليها في المقبرة."},{"t":"p","text":"ويُصلى على الجنازة بعد الصبح وبعد العصر بالإجماع، وأما أوقات الطلوع والزوال والغروب فالأولى تأخيرها حتى يخرج الوقت إن لم يُخش عليها؛ لحديث عقبة، إلا إذا حضرت في الوقت نفسه فيجوز أداؤها فيه عند الحنفية، فإن خيف عليها التغير صُلّي عليها في أي وقت. ويشترط لها الطهارة واستقبال القبلة، ومن خاف فوتها ولم يجد ماء أو كان في الوضوء فواتها تيمم وصلى عند الحنفية، وهو قول قوي."}],"refs":["مسلم ٩٧٣","أبو داود ٣١٩١","مسلم ٨٣١","بداية المجتهد (١/٢٥٦)","العرف الشذي (٢/٣٣١)","بداية المجتهد (١/٢٥٧)"],"related":["الأوقات المنهي عن الصلاة فيها، والصلاة ذات السبب"],"alts":["صلاة الجنازة في المسجد","صلاة الجنازة بعد العصر","التيمم لصلاة الجنازة","صلاة الجنازة في المقبرة"]},{"n":195,"bab":"الجنائز","sub":"الدفن والقبور","title":"الدفن: اللحد والشق، ورفع القبر وتجصيصه والبناء عليه، والجلوس عليه","q":"هل الأفضل في القبر اللحد أو الشق؟ وكم يُرفع القبر عن الأرض؟ وما حكم البناء على القبور وتجصيصها والكتابة عليها؟ وهل يجوز الجلوس على القبر والمشي بين القبور؟","short":"أجمعوا على وجوب دفن الميت. واتفقوا على أن اللحد أفضل من الشق إن كانت الأرض صلبة. ورفع القبر قدر شبر سنة. واختلفوا في التسطيح والتسنيم: فالتسنيم عند أبي حنيفة ومالك وأحمد، والتسطيح عند الشافعي. وكره مالك والشافعي وأحمد تجصيص القبور والبناء عليها، ونقل ابن رشد عن أبي حنيفة إجازة التجصيص، والمعروف في كتب الحنفية كراهته. وكره الجمهور الجلوس على القبر، وتأوله مالك على الجلوس لقضاء الحاجة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الْحَدُوا لِي لَحْدًا، وَانْصِبُوا عَلَيَّ اللَّبِنَ نَصْبًا، كَمَا صُنِعَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ","src":"رواه مسلم ٩٦٦","pre":"عن سعد بن أبي وقاص رضي الله عنه أنه قال في مرضه الذي هلك فيه:","links":[{"book":"mt_muslim","num":966,"id":"h966"}]},{"t":"quote","text":"اللَّحْدُ لَنَا وَالشَّقُّ لِغَيْرِنَا","src":"رواه أبو داود ٣٢٠٨","pre":"وعن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":3208,"id":"h3208"}]},{"t":"quote","text":"نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُجَصَّصَ الْقَبْرُ، وَأَنْ يُقْعَدَ عَلَيْهِ، وَأَنْ يُبْنَى عَلَيْهِ","src":"رواه مسلم ٩٧٠","pre":"وعن جابر رضي الله عنه قال:","links":[{"book":"mt_muslim","num":970,"id":"h970"}]},{"t":"quote","text":"أَلَا أَبْعَثُكَ عَلَى مَا بَعَثَنِي عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ «أَنْ لَا تَدَعَ تِمْثَالًا إِلَّا طَمَسْتَهُ وَلَا قَبْرًا مُشْرِفًا إِلَّا سَوَّيْتَهُ»","src":"رواه مسلم ٩٦٩","pre":"وعن أبي الهياج الأسدي قال: قال لي علي بن أبي طالب رضي الله عنه:","links":[{"book":"mt_muslim","num":969,"id":"h969"}]},{"t":"quote","text":"لَا تَجْلِسُوا عَلَى الْقُبُورِ، وَلَا تُصَلُّوا إِلَيْهَا","src":"رواه مسلم ٩٧٢","pre":"وعن أبي مرثد الغنوي رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":972,"id":"h972"}]},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا فَرَغَ مِنْ دَفْنِ الْمَيِّتِ وَقَفَ عَلَيْهِ فَقَالَ «اسْتَغْفِرُوا لأَخِيكُمْ وَسَلُوا لَهُ التَّثْبِيتَ فَإِنَّهُ الآنَ يُسْأَلُ»","src":"رواه أبو داود ٣٢٢١","pre":"وعن عثمان بن عفان رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":3221,"id":"h3221"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَجْمَعُوا عَلَى وُجُوبِ الدَّفْنِ، وَالْأَصْلُ فِيهِ قَوْله تَعَالَى: {أَلَمْ نَجْعَلِ الأَرْضَ كِفَاتًا} المرسلات: 25 {أَحْيَاءً وَأَمْوَاتًا} المرسلات: 26 ) ، وَقَوْلُهُ {فَبَعَثَ اللَّهُ غُرَابًا يَبْحَثُ فِي الأَرْضِ} المائدة: 31 وَكَرِهَ مَالِكٌ وَالشَّافِعِيُّ تَجْصِيصَ الْقُبُورِ، وَأَجَازَ ذَلِكَ أَبُو حَنِيفَةَ","src":"بداية المجتهد","loc":"١/٢٥٨","pre":"قال ابن رشد:"},{"t":"quote","text":"لا يجوز التجصيص عند أحد ولا البناء، وأما ما ذكر الشيخ الدهلوي في المدارج جوازه عن بعض مشائخنا أي محمد بن سلمة فينبغي أن تراجع عبارة ابن سلمة مشافهة","src":"العرف الشذي","loc":"٢/٣٤٠","pre":"وقال الكشميري الحنفي:"},{"t":"quote","text":"قال الشافعية: الأفضل التربيع والتسطيح، وقلت: الأفضل التسنيم، وذكر ابن الهمام أن يرفع القبر قدر شبر واحد","src":"العرف الشذي","loc":"٢/٣٣٩","pre":"وقال:"},{"t":"quote","text":"يكره الوطئ أي المشي على القبر، واختار الطحاوي الكراهة، واختار الشيخ الكمال الكراهة تنزيهاً، والجلوس على القبر. قيل: معناه قضاء الحاجة من البول والغائط على القبر، وقيل: الجلوس المعروف، وهذا أيضاً مكروه، وثبت بسند صحيح عن علي الاتكاء على القبر لا الجلوس، وبين الجلوس والاتكاء فرق ظاهر","src":"العرف الشذي","loc":"٢/٣٤٠","pre":"وقال في الجلوس على القبر:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن اللحد أفضل من الشق؛ لأنه الذي صُنع بالنبي ﷺ، والشق جائز ولا سيما في الأرض الرخوة. ويُدخل الميت من قِبل رجلي القبر، ويوضع على شقه الأيمن مستقبل القبلة، ويقول واضعه: «بسم الله وعلى ملة رسول الله»، ويُرفع القبر عن الأرض قدر شبر ويُسنّم ليُعرف أنه قبر فيُحترم."},{"t":"p","text":"ويحرم البناء على القبور وتجصيصها ورفعها فوق ذلك، وإيقاد السرج عليها، واتخاذها مساجد؛ لنهي النبي ﷺ عن ذلك، وأمره عليًّا بتسوية القبور المشرفة، وهذا لا خلاف فيه بين المحققين من المذاهب الأربعة. ولا بأس بوضع حجر أو علامة يُعرف بها القبر، والكتابة اليسيرة للتعريف بالاسم فيها خلاف، والأحوط تركها. ويُكره الجلوس على القبور والمشي عليها والاتكاء عليها، ويحرم قضاء الحاجة عليها. ويستحب بعد الدفن أن يقف الحاضرون على القبر فيستغفرون للميت ويسألون له التثبيت."},{"t":"tanbih","items":[{"t":"p","text":"لا يُدفن في القبر الواحد أكثر من ميت إلا لضرورة كضيق المكان أو كثرة الموتى، فيُقدّم إلى القبلة أفضلهم، كما فعل النبي ﷺ بشهداء أحد."}]}],"refs":["مسلم ٩٦٦","أبو داود ٣٢٠٨","مسلم ٩٧٠","مسلم ٩٦٩","مسلم ٩٧٢","أبو داود ٣٢٢١","بداية المجتهد (١/٢٥٨)","العرف الشذي (٢/٣٤٠)","العرف الشذي (٢/٣٣٩)"],"related":["ما يُفعل بالمحتضر وبعد موته: التلقين، والتوجيه إلى القبلة، وتعجيل الدفن"],"alts":["اللحد والشق","البناء على القبور","تجصيص القبر","الجلوس على القبر","الكتابة على القبر","رفع القبر"]},{"n":196,"bab":"الجنائز","sub":"التعزية","title":"التعزية: حكمها، وصيغتها، ومدتها، والجلوس لها، وصنع الطعام لأهل الميت","q":"ما حكم التعزية؟ وماذا أقول للمصاب؟ وهل يجوز لأهل الميت أن يجلسوا ثلاثة أيام لاستقبال المعزين؟ وهل يصنع أهل الميت الطعام للناس؟","short":"التعزية مستحبة بلا خلاف، إلا أن الثوري لم يستحبها بعد الدفن. وليس فيها لفظ محدود. وكره بعض الحنابلة والشافعية الجلوس لها، ورخص فيه بعض الحنفية والمالكية ما لم يقترن بمنكر. واتفقوا على استحباب صنع الطعام لأهل الميت، وكراهة صنع أهل الميت الطعام للناس.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَا مِنْ مُؤْمِنٍ يُعَزِّي أَخَاهُ بِمُصِيبَةٍ إِلاَّ كَسَاهُ اللَّهُ سُبْحَانَهُ مِنْ حُلَلِ الْكَرَامَةِ يَوْمَ الْقِيَامَةِ","src":"رواه ابن ماجه ١٦٠١","pre":"عن عمرو بن حزم رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_ibnmajah","num":1601,"id":"h1601"}]},{"t":"quote","text":"إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ","src":"رواه البخاري ١٢٨٤","pre":"وعن أسامة بن زيد رضي الله عنهما أن النبي ﷺ أرسل إلى ابنته لما مات ابنها:","links":[{"book":"mt_bukhari","num":1284,"id":"h1284"}]},{"t":"quote","text":"اصْنَعُوا لآلِ جَعْفَرٍ طَعَامًا فَإِنَّهُ قَدْ أَتَاهُمْ أَمْرٌ شَغَلَهُمْ","src":"رواه أبو داود ٣١٣٢","pre":"وعن عبد الله بن جعفر رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":3132,"id":"h3132"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَيُسْتَحَبُّ تَعْزِيَةُ أَهْلِ الْمَيِّتِ) لَا نَعْلَمُ فِي هَذِهِ الْمَسْأَلَةِ خِلَافًا، إلَّا أَنَّ الثَّوْرِيَّ قَالَ: لَا تُسْتَحَبُّ التَّعْزِيَةُ بَعْدَ الدَّفْنِ؛ لِأَنَّهُ خَاتِمَةُ أَمْرِهِ","src":"المغني","loc":"٢/٤٠٥","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَلَا نَعْلَمُ فِي التَّعْزِيَةِ شَيْئًا مَحْدُودًا، إلَّا أَنَّهُ يُرْوَى أَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «عَزَّى رَجُلًا، فَقَالَ: رَحِمَكَ اللَّهُ وَآجَرَكَ.» رَوَاهُ الْإِمَامُ أَحْمَدُ. وَعَزَّى أَحْمَدُ أَبَا طَالِبٍ، فَوَقَفَ عَلَى بَابِ الْمَسْجِدِ فَقَالَ: أَعْظَمَ اللَّهُ أَجْرَكُمْ، وَأَحْسَنَ عَزَاءَكُمْ","src":"المغني","loc":"٢/٤٠٥","pre":"وقال:"},{"t":"quote","text":"قَالَ أَبُو الْخَطَّابِ: يُكْرَهُ الْجُلُوسُ لِلتَّعْزِيَةِ. وَقَالَ ابْنُ عَقِيلٍ: يُكْرَهُ الِاجْتِمَاعُ بَعْدَ خُرُوجِ الرُّوحِ؛ لِأَنَّ فِيهِ تَهْيِيجًا لِلْحُزْنِ","src":"المغني","loc":"٢/٤٠٦","pre":"وقال في الجلوس لها:"},{"t":"quote","text":"وَجُمْلَتُهُ أَنَّهُ يُسْتَحَبُّ إصْلَاحُ طَعَامٍ لِأَهْلِ الْمَيِّتِ، يَبْعَثُ بِهِ إلَيْهِمْ، إعَانَةً لَهُمْ، وَجَبْرًا لِقُلُوبِهِمْ؛ فَإِنَّهُمْ رُبَّمَا اشْتَغَلُوا بِمُصِيبَتِهِمْ وَبِمَنْ يَأْتِي إلَيْهِمْ عَنْ إصْلَاحِ طَعَامٍ لَأَنْفُسِهِمْ. وَقَدْ رَوَى أَبُو دَاوُد، فِي \" سُنَنِهِ \"، بِإِسْنَادِهِ عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ، قَالَ: لَمَّا جَاءَ نَعْيُ جَعْفَرٍ، قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «اصْنَعُوا لِآلِ جَعْفَرٍ طَعَامًا؛ فَإِنَّهُ قَدْ أَتَاهُمْ أَمْرٌ شَغَلَهُمْ» . وَرُوِيَ عَنْ عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، أَنَّهُ قَالَ: فَمَازَالَتْ السُّنَّةُ فِينَا، حَتَّى تَرَكَهَا مَنْ تَرَكَهَا. فَأَمَّا صُنْعُ أَهْلِ الْمَيِّتِ طَعَامًا لِلنَّاسِ، فَمَكْرُوهٌ؛ لِأَنَّ فِيهِ زِيَادَةً عَلَى مُصِيبَتِهِمْ، وَشُغْلًا لَهُمْ إلَى شُغْلِهِمْ، وَتَشَبُّهًا بِصُنْعِ أَهْلِ الْجَاهِلِيَّةِ","src":"المغني","loc":"٢/٤١٠","pre":"وقال في الطعام:"},{"t":"quote","text":"يستحب للجيران والأقرباء صنع الطعام لأهل الميت","src":"العرف الشذي","loc":"٢/٣١٣","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وإنما السنة أن يصنع الطعام لأهل الميت من أقاربهم أو جيرانهم فيبعث إليهم","src":"مجموع فتاوى ابن باز","loc":"١٣/٣٨٤","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"وأما صنع الطعام لأهل الميت، فهذا فيه تفصيل، أما صنع الطعام من أجل المصيبة، وجمع الناس فهذا ليس من المشروع، بل من عمل الجاهلية","src":"فتاوى نور على الدرب لابن باز","loc":"١٤/٦٠","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن التعزية سنة مؤكدة لجميع أهل الميت كبارهم وصغارهم، قبل الدفن وبعده، بما تيسر من الكلام الذي يخفف المصيبة ويحث على الصبر، وأحسنه ما ورد: «إن لله ما أخذ وله ما أعطى، وكل عنده بأجل مسمى، فلتصبر ولتحتسب»، أو «أعظم الله أجرك، وأحسن عزاءك، وغفر لميتك». وليس لها مدة محدودة، والغالب أن تكون في الأيام الثلاثة الأولى، ولا بأس بها بعدها لمن لم يتمكن."},{"t":"p","text":"ولا بأس أن يجلس أهل الميت في بيتهم ليعزيهم الناس من غير تكلف ولا إسراف ولا منكرات، وأما نصب الخيام والسرادقات وإنفاق الأموال، واستئجار القراء، والاجتماع للطعام في بيت الميت، فهو من البدع المحدثة والنياحة المذمومة. والسنة أن يصنع الجيران والأقارب طعامًا لأهل الميت؛ لأنهم مشغولون بمصابهم، وأما صنع أهل الميت الطعام للناس فمكروه، إلا لضيف قادم من بعيد يحتاج إلى الطعام."}],"refs":["ابن ماجه ١٦٠١","البخاري ١٢٨٤","أبو داود ٣١٣٢","المغني (٢/٤٠٥)","المغني (٢/٤٠٦)","المغني (٢/٤١٠)","العرف الشذي (٢/٣١٣)","مجموع فتاوى ابن باز (١٣/٣٨٤)","فتاوى نور على الدرب لابن باز (١٤/٦٠)"],"related":["البكاء على الميت، والنياحة، وتعذيب الميت ببكاء أهله"],"alts":["صيغة التعزية","العزاء ثلاثة أيام","الجلوس للعزاء","طعام أهل الميت","سرادق العزاء"]},{"n":197,"bab":"الجنائز","sub":"التعزية","title":"البكاء على الميت، والنياحة، وتعذيب الميت ببكاء أهله","q":"هل يجوز البكاء على الميت؟ وما النياحة المحرمة؟ وهل صحيح أن الميت يعذب ببكاء أهله عليه، وما ذنبه؟","short":"اتفق العلماء على جواز البكاء على الميت بدمع العين وحزن القلب من غير صوت مرتفع ولا ندب ولا نياحة، وكرهه الشافعي بعد خروج الروح في قول. وأجمعوا على تحريم النياحة ولطم الخدود وشق الجيوب والدعاء بالويل. واختلفوا في معنى حديث «إن الميت ليعذب ببكاء أهله عليه»: فحمله الجمهور على من أوصى بالنوح أو كان من عادته ولم ينه عنه، وأنكرته عائشة على ظاهره، وحمله بعضهم على تألم الميت بذلك.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ الْعَيْنَ تَدْمَعُ، وَالْقَلْبَ يَحْزَنُ، وَلاَ نَقُولُ إِلاَّ مَا يَرْضَى رَبُّنَا، وَإِنَّا بِفِرَاقِكَ يَا إِبْرَاهِيمُ لَمَحْزُونُونَ","src":"رواه البخاري ١٣٠٣","pre":"عن أنس بن مالك رضي الله عنه أن رسول الله ﷺ قال لما مات ابنه إبراهيم:","links":[{"book":"mt_bukhari","num":1303,"id":"h1303"}]},{"t":"quote","text":"لَيْسَ مِنَّا مَنْ لَطَمَ الْخُدُودَ، وَشَقَّ الْجُيُوبَ، وَدَعَا بِدَعْوَى الْجَاهِلِيَّةِ","src":"رواه البخاري ١٢٩٤","pre":"وعن عبد الله بن مسعود رضي الله عنه قال: قال النبي ﷺ:","links":[{"book":"mt_bukhari","num":1294,"id":"h1294"}]},{"t":"quote","text":"النَّائِحَةُ إِذَا لَمْ تَتُبْ قَبْلَ مَوْتِهَا، تُقَامُ يَوْمَ الْقِيَامَةِ وَعَلَيْهَا سِرْبَالٌ مِنْ قَطِرَانٍ، وَدِرْعٌ مِنْ جَرَبٍ","src":"رواه مسلم ٩٣٤","pre":"وعن أبي مالك الأشعري رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_muslim","num":934,"id":"h934"}]},{"t":"quote","text":"مَنْ نِيحَ عَلَيْهِ يُعَذَّبُ بِمَا نِيحَ عَلَيْهِ","src":"رواه البخاري ١٢٩١","pre":"وعن المغيرة بن شعبة رضي الله عنه قال: سمعت النبي ﷺ يقول:","links":[{"book":"mt_bukhari","num":1291,"id":"h1291"}]},{"t":"quote","text":"رَحِمَ اللَّهُ عُمَرَ، وَاللَّهِ مَا حَدَّثَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِنَّ اللَّهَ لَيُعَذِّبُ الْمُؤْمِنَ بِبُكَاءِ أَهْلِهِ عَلَيْهِ. وَلَكِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ «إِنَّ اللَّهَ لَيَزِيدُ الْكَافِرَ عَذَابًا بِبُكَاءِ أَهْلِهِ عَلَيْهِ»","src":"رواه البخاري ١٢٨٨","pre":"وعن عائشة رضي الله عنها لما بلغها حديث عمر رضي الله عنه قالت:","links":[{"book":"mt_bukhari","num":1288,"id":"h1288"}]},{"t":"p","text":"وقالت عائشة رضي الله عنها: «حسبكم القرآن: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ﴾»."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَالْبُكَاءُ غَيْرُ مَكْرُوهٍ، إذَا لَمْ يَكُنْ مَعَهُ نَدْبٌ وَلَا نِيَاحَةٌ) أَمَّا الْبُكَاءُ بِمُجَرَّدِهِ فَلَا يُكْرَهُ فِي حَالٍ. وَقَالَ الشَّافِعِيُّ: يُبَاحُ إلَى أَنْ تَخْرُجَ الرُّوحُ، وَيُكْرَهُ بَعْدَ ذَلِكَ","src":"المغني","loc":"٢/٤٠٦","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَظَاهِرُ الْأَخْبَارِ تَدُلُّ عَلَى تَحْرِيمِ النَّوْحِ، وَهَذِهِ الْأَشْيَاءِ الْمَذْكُورَة؛ لِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - نَهَى عَنْهَا فِي حَدِيثِ جَابِرٍ؛ لِقَوْلِ اللَّهِ تَعَالَى: {وَلا يَعْصِينَكَ فِي مَعْرُوفٍ} الممتحنة: 12 . قَالَ أَحْمَدُ: هُوَ النَّوْحُ","src":"المغني","loc":"٢/٤٠٨","pre":"وقال:"},{"t":"quote","text":"بعض البكاء جائز ولكنه غير منضبط","src":"العرف الشذي","loc":"٢/٣١٧","pre":"وقال الكشميري:"},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"اختلف أهل العلم في معنى حديث تعذيب الميت ببكاء أهله: فحمله قوم على ظاهره وقالوا: يتصرف الله في خلقه بما شاء، وأنكرته عائشة وابن عباس على ظاهره، وحمله آخرون على من كان النوح من عادته ولم ينه أهله عنه، أو أوصى به في حياته، وحمله بعضهم على أن الميت يتألم ويتأذى بما يسمع من النياحة."},{"t":"quote","text":"وَلَا بُدَّ مِنْ حَمْلِ الْبُكَاءِ فِي هَذِهِ الْأَحَادِيثِ عَلَى الْبُكَاءِ غَيْرِ الْمَشْرُوعِ، وَهُوَ الَّذِي مَعَهُ نَدْبٌ وَنِيَاحَةٌ وَنَحْوُ هَذَا، بِدَلِيلِ مَا قَدَّمْنَاهُ مِنْ الْأَحَادِيثِ فِي صَدْرِ الْمَسْأَلَةِ","src":"المغني","loc":"٢/٤٠٩","pre":"قال ابن قدامة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن البكاء على الميت بدمع العين وحزن القلب جائز، وهو رحمة يجعلها الله في قلوب عباده، وقد بكى النبي ﷺ على ابنه إبراهيم وغيره. وأما النياحة، وهي رفع الصوت بالندب وتعداد محاسن الميت على وجه التسخط، ولطم الخدود، وشق الجيوب، وحلق الشعر، والدعاء بالويل والثبور، فهي محرمة بالإجماع، ومن كبائر الذنوب."},{"t":"p","text":"وأما تعذيب الميت ببكاء أهله فمحمول على البكاء المحرم، وهو النياحة، إذا كان الميت قد أوصى بها، أو كان يعلم أن أهله ينوحون فلم ينههم؛ لأنه بذلك متسبب فيه، ولا يعارض قوله تعالى: ﴿وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ﴾؛ لأنه عُذب بفعله هو. ولهذا ينبغي للمسلم أن يوصي أهله بترك النياحة. ومن لم يوصِ ولم يرض فالأرجى أنه لا يعذب، أو أنه يتألم بذلك تألمًا لا عقوبة فيه."},{"t":"tanbih","items":[{"t":"p","text":"من السنة عند المصيبة أن يقول المصاب: «إنا لله وإنا إليه راجعون، اللهم أجرني في مصيبتي واخلف لي خيرًا منها»، وأن يصبر عند الصدمة الأولى، فإنما الصبر عند الصدمة الأولى."}]}],"refs":["البخاري ١٣٠٣","البخاري ١٢٩٤","مسلم ٩٣٤","البخاري ١٢٩١","البخاري ١٢٨٨","المغني (٢/٤٠٦)","المغني (٢/٤٠٨)","العرف الشذي (٢/٣١٧)","المغني (٢/٤٠٩)"],"related":["التعزية: حكمها، وصيغتها، ومدتها، والجلوس لها، وصنع الطعام لأهل الميت"],"alts":["البكاء على الميت","النياحة على الميت","الميت يعذب ببكاء أهله","لطم الخدود"]},{"n":198,"bab":"الجنائز","sub":"زيارة القبور","title":"زيارة القبور للرجال والنساء، وما يقال عند زيارتها","q":"ما حكم زيارة القبور؟ وهل يجوز للمرأة أن تزور قبر أبيها أو زوجها؟ وماذا يقول الزائر؟ وهل يجوز السفر لزيارة القبور؟","short":"أجمع العلماء على استحباب زيارة القبور للرجال. واختلفوا في زيارة النساء: فكرهها أحمد في رواية والشافعية في وجه، وحرمها بعضهم لحديث «لعن زوارات القبور»، وأجازها أبو حنيفة في رواية ومالك وأحمد في رواية أخرى من غير إكثار ولا جزع، لعموم الإذن ولزيارة عائشة قبر أخيها.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"نَهَيْتُكُمْ عَنْ زِيَارَةِ الْقُبُورِ فَزُورُوهَا","src":"رواه مسلم ٩٧٧","pre":"عن بريدة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":977,"id":"h977"}]},{"t":"quote","text":"السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا، إِنْ شَاءَ اللهُ لَلَاحِقُونَ، أَسْأَلُ اللهَ لَنَا وَلَكُمُ الْعَافِيَةَ","src":"رواه مسلم ٩٧٥","pre":"وعنه رضي الله عنه قال: كان رسول الله ﷺ يعلمهم إذا خرجوا إلى المقابر أن يقول قائلهم:","links":[{"book":"mt_muslim","num":975,"id":"h975"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَعَنَ زَوَّارَاتِ الْقُبُورِ","src":"رواه الترمذي ١٠٥٦","pre":"وعن أبي هريرة رضي الله عنه:","links":[{"book":"mt_tirmidhi","num":1056,"id":"h1056"}]},{"t":"quote","text":"وَقَدْ رَأَى بَعْضُ أَهْلِ الْعِلْمِ أَنَّ هَذَا كَانَ قَبْلَ أَنْ يُرَخِّصَ النَّبِيُّ صلى الله عليه وسلم فِي زِيَارَةِ الْقُبُورِ فَلَمَّا رَخَّصَ دَخَلَ فِي رُخْصَتِهِ الرِّجَالُ وَالنِّسَاءُ . وَقَالَ بَعْضُهُمْ إِنَّمَا كُرِهَ زِيَارَةُ الْقُبُورِ لِلنِّسَاءِ لِقِلَّةِ صَبْرِهِنَّ وَكَثْرَةِ جَزَعِهِنَّ","src":"رواه الترمذي ١٠٥٦","pre":"قال الترمذي:","links":[{"book":"mt_tirmidhi","num":1056,"id":"h1056"}]},{"t":"quote","text":"مَرَّ النَّبِيُّ صلى الله عليه وسلم بِامْرَأَةٍ تَبْكِي عِنْدَ قَبْرٍ فَقَالَ «اتَّقِي اللَّهَ وَاصْبِرِي». قَالَتْ إِلَيْكَ عَنِّي، فَإِنَّكَ لَمْ تُصَبْ بِمُصِيبَتِي، وَلَمْ تَعْرِفْهُ. فَقِيلَ لَهَا إِنَّهُ النَّبِيُّ صلى الله عليه وسلم. فَأَتَتْ باب النَّبِيِّ صلى الله عليه وسلم فَلَمْ تَجِدْ عِنْدَهُ بَوَّابِينَ فَقَالَتْ لَمْ أَعْرِفْكَ. فَقَالَ «إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الأُولَى»","src":"رواه البخاري ١٢٨٣","pre":"وعن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1283,"id":"h1283"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَلَا بَأْسَ أَنْ يَزُورَ الرَّجُلُ الْمَقَابِرَ) لَا نَعْلَمُ بَيْنَ أَهْلِ الْعِلْمِ خِلَافًا فِي إبَاحَةِ زِيَارَةِ الرِّجَالِ الْقُبُورَ. وَقَالَ عَلِيُّ بْنُ سَعِيدٍ: سَأَلْت أَحْمَدَ عَنْ زِيَارَةِ الْقُبُورِ، تَرْكُهَا أَفْضَلُ عِنْدَك أَوْ زِيَارَتُهَا؟ قَالَ: زِيَارَتُهَا","src":"المغني","loc":"٢/٤٢٢","pre":"قال ابن قدامة:"},{"t":"quote","text":"اخْتَلَفَتْ الرِّوَايَةُ عَنْ أَحْمَدَ فِي زِيَارَةِ النِّسَاءِ الْقُبُورَ، فَرُوِيَ عَنْهُ كَرَاهَتُهَا؛ لِمَا رَوَتْ أُمُّ عَطِيَّةَ، قَالَتْ: «نُهِينَا عَنْ زِيَارَةِ الْقُبُورِ وَلَمْ يُعْزَمْ عَلَيْنَا.» رَوَاهُ مُسْلِمٌ. وَلِأَنَّ النَّبِيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «لَعَنَ اللَّهُ زَوَّارَاتِ الْقُبُورِ» . قَالَ التِّرْمِذِيُّ: هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. وَهَذَا خَاصٌّ فِي النِّسَاءِ، وَالنَّهْيُ الْمَنْسُوخُ كَانَ عَامًا لِلرِّجَالِ وَالنِّسَاءِ. وَيَحْتَمِلُ أَنَّهُ كَانَ خَاصًّا لِلرِّجَالِ. وَيَحْتَمِلُ أَيْضًا كَوْنَ الْخَبَرِ فِي لَعْنِ زَوَّارَاتِ الْقُبُورِ، بَعْدَ أَمْرِ الرِّجَالِ بِزِيَارَتِهَا، فَقَدْ دَارَ بَيْنَ الْحَظْرِ وَالْإِبَاحَةِ، فَأَقَلُّ أَحْوَالِهِ الْكَرَاهَةُ. وَلِأَنَّ الْمَرْأَةَ قَلِيلَةُ الصَّبْرِ، كَثِيرَةُ الْجَزَعِ، وَفِي زِيَارَتِهَا لِلْقَبْرِ تَهْيِيجٌ لِحُزْنِهَا","src":"المغني","loc":"٢/٤٢٤-٤٢٥","pre":"وقال في زيارة النساء:"},{"t":"quote","text":"في زيارة النسوان روايتان عن أبي حنيفة الجواز وعدمه، أقول: وجه الجواز أن النبي - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - أجاز زيارة القبور للرجال، والنساء تبع الرجال، ووجه الثانية: أن الإجازة المذكورة في الحديث للرجال، وتردد ابن عابدين في تعدد الرواية عن أبي حنيفة، أقول: يحمل على اختلاف الأحوال","src":"العرف الشذي","loc":"٢/٣٤٢","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن زيارة القبور سنة للرجال؛ للأمر بها، ولأنها تذكر الآخرة وتزهد في الدنيا، وينفع الزائرُ الميتَ بالدعاء والاستغفار. ويقول الزائر ما علمه النبي ﷺ أصحابه: «السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم للاحقون، أسأل الله لنا ولكم العافية»."},{"t":"p","text":"وأما النساء فالأظهر جواز زيارتهن القبور أحيانًا من غير إكثار، بشرط الحشمة والصبر وترك النياحة والجزع؛ لأن النبي ﷺ أقر المرأة التي كانت عند القبر وأمرها بالصبر ولم ينكر عليها الزيارة، وعلّم عائشة ما تقول إذا زارت القبور، وزارت عائشة قبر أخيها. ويُحمل اللعن على المكثرات من الزيارة أو المصحوبة بالنياحة والتبرج. والأحوط للمرأة أن تقلّ منها، ولا سيما إن كانت سريعة الجزع."},{"t":"tanbih","items":[{"t":"p","text":"لا تجوز الزيارة الشركية: من دعاء الأموات والاستغاثة بهم وطلب الحوائج منهم والطواف بقبورهم والتمسح بها، فإن ذلك من الشرك أو وسائله. ولا يشد الرحل لمجرد زيارة القبور عند جمع من المحققين؛ لحديث «لا تشد الرحال إلا إلى ثلاثة مساجد»، وأجازه آخرون، والزيارة الشرعية لا تحتاج إلى شد رحل."}]}],"refs":["مسلم ٩٧٧","مسلم ٩٧٥","الترمذي ١٠٥٦","البخاري ١٢٨٣","المغني (٢/٤٢٢)","المغني (٢/٤٢٤-٤٢٥)","العرف الشذي (٢/٣٤٢)"],"related":["ما ينتفع به الميت: الدعاء والصدقة والصيام والحج، وقراءة القرآن وإهداء الثواب"],"alts":["زيارة المرأة للقبور","دعاء زيارة القبور","حكم زيارة القبور","شد الرحال لزيارة القبور"]},{"n":199,"bab":"الجنائز","sub":"زيارة القبور","title":"ما ينتفع به الميت: الدعاء والصدقة والصيام والحج، وقراءة القرآن وإهداء الثواب","q":"ماتت أمي، فما الذي ينفعها مني؟ وهل يصل إليها ثواب قراءتي القرآن لها؟ وهل أتصدق عنها وأحج عنها؟","short":"أجمع العلماء على أن الميت ينتفع بالدعاء والاستغفار والصدقة وأداء الواجبات التي تدخلها النيابة كالحج وقضاء الدين. واختلفوا في وصول ثواب العبادات البدنية المحضة كقراءة القرآن والصلاة: فذهب أبو حنيفة وأحمد وجماعة من أصحاب مالك والشافعي إلى وصولها إذا أُهدي ثوابها، وذهب الشافعي في المشهور ومالك إلى أنها لا تصل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ: إِلَّا مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ","src":"رواه مسلم ١٦٣١","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1631,"id":"h1631"}]},{"t":"quote","text":"أَنَّ رَجُلاً، قَالَ لِلنَّبِيِّ صلى الله عليه وسلم إِنَّ أُمِّي افْتُلِتَتْ نَفْسُهَا، وَأَظُنُّهَا لَوْ تَكَلَّمَتْ تَصَدَّقَتْ، فَهَلْ لَهَا أَجْرٌ إِنْ تَصَدَّقْتُ عَنْهَا قَالَ «نَعَمْ»","src":"رواه البخاري ١٣٨٨","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_bukhari","num":1388,"id":"h1388"}]},{"t":"quote","text":"مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ صَامَ عَنْهُ وَلِيُّهُ «. تَابَعَهُ ابْنُ وَهْبٍ عَنْ عَمْرٍو. وَرَوَاهُ يَحْيَى بْنُ أَيُّوبَ عَنِ ابْنِ أَبِي جَعْفَرٍ»","src":"رواه البخاري ١٩٥٢","pre":"وعنها رضي الله عنها أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1952,"id":"h1952"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَيُّ قُرْبَةٍ فَعَلَهَا، وَجَعَلَ ثَوَابَهَا لِلْمَيِّتِ الْمُسْلِمِ، نَفَعَهُ ذَلِكَ، إنْ شَاءَ اللَّهُ، أَمَّا الدُّعَاءُ، وَالِاسْتِغْفَارُ، وَالصَّدَقَةُ، وَأَدَاءُ الْوَاجِبَاتِ، فَلَا أَعْلَمُ فِيهِ خِلَافًا، إذَا كَانَتْ الْوَاجِبَاتُ مِمَّا يَدْخُلُهُ النِّيَابَةُ","src":"المغني","loc":"٢/٤٢٣","pre":"قال ابن قدامة:"},{"t":"quote","text":"وَقَالَ الشَّافِعِيُّ: مَا عَدَا الْوَاجِبَ وَالصَّدَقَةَ وَالدُّعَاءَ وَالِاسْتِغْفَارَ، لَا يُفْعَلُ عَنْ الْمَيِّتِ، وَلَا يَصِلُ ثَوَابُهُ إلَيْهِ؛ لِقَوْلِ اللَّه تَعَالَى: {وَأَنْ لَيْسَ لِلإِنْسَانِ إِلا مَا سَعَى} النجم: 39 . وَقَوْلِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: «إذَا مَاتَ ابْنُ آدَمَ انْقَطَعَ عَمَلُهُ إلَّا مِنْ ثَلَاثٍ: صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ مِنْ بَعْدِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ»","src":"المغني","loc":"٢/٤٢٣","pre":"وقال:"},{"t":"quote","text":"الْأَصْلُ فِي هَذَا الْبَابِ أَنَّ الْإِنْسَانَ لَهُ أَنْ يَجْعَلَ ثَوَابَ عَمَلِهِ لِغَيْرِهِ صَلَاةً أَوْ صَوْمًا أَوْ صَدَقَةً أَوْ غَيْرَهَا عِنْدَ أَهْلِ السُّنَّةِ وَالْجَمَاعَةِ","src":"الهداية مع فتح القدير","loc":"٣/١٤٢","pre":"وقال صاحب الهداية من الحنفية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وقد ذهب بعض أهل العلم إلى جواز ذلك وقالوا: لا مانع من إهداء ثواب القرآن وغيره من الأعمال الصالحات، وقاسوا ذلك على الصدقة والدعاء للأموات وغيرهم، ولكن الصواب هو القول الأول للحديث المذكور وما جاء في معناه، ولو كان إهداء التلاوة مشروعا لفعله السلف الصالح","src":"مجموع فتاوى ابن باز","loc":"٥/٢٥٥","pre":"قال الشيخ عبد العزيز بن باز رحمه الله في إهداء ثواب القراءة:"},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"سبب الخلاف: معارضة عموم قوله تعالى: ﴿وَأَن لَّيْسَ لِلْإِنسَـٰنِ إِلَّا مَا سَعَىٰ﴾، وحديث انقطاع العمل، للأحاديث الصحيحة في وصول ثواب الصدقة والصوم والحج عن الميت؛ فمن قصر الوصول على ما ورد به النص منعه في غيره، ومن قاس سائر القرب على ما ورد أجازه، لأن الصوم والحج عبادتان بدنيتان وقد وصل نفعهما."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن أنفع ما يقدمه الحي للميت: الدعاء والاستغفار له، والصدقة عنه، وقضاء دينه، والحج والعمرة عنه، وصيام ما فاته من صيام واجب كالنذر، ووصل أقاربه وأصدقائه، وإنفاذ وصيته؛ فهذه كلها ثابتة بالنصوص والإجماع، والولد الصالح الذي يدعو لوالديه من أعظم ما يبقى للمرء بعد موته."},{"t":"p","text":"وأما قراءة القرآن وإهداء ثوابها للميت، فالأمر فيها واسع، فقد قال بوصولها أبو حنيفة وأحمد وكثير من العلماء، ومنعها الشافعي ومالك في المشهور، والأولى للمسلم أن يكثر من الدعاء للميت لأنه المنصوص، فإن قرأ ودعا الله أن يجعل ثواب قراءته لميته فله سلف من أهل العلم. وأما الاجتماع للقراءة على الميت في أيام معينة كالثالث والسابع والأربعين، واستئجار القراء لذلك، فلم يكن من عمل السلف، ولا يصح أخذ الأجرة على قراءة القرآن للميت عند المحققين من الحنفية وغيرهم."}],"refs":["مسلم ١٦٣١","البخاري ١٣٨٨","البخاري ١٩٥٢","المغني (٢/٤٢٣)","الهداية مع فتح القدير (٣/١٤٢)","مجموع فتاوى ابن باز (٥/٢٥٥)"],"related":["زيارة القبور للرجال والنساء، وما يقال عند زيارتها"],"alts":["إهداء ثواب القراءة للميت","الصدقة عن الميت","ما ينفع الميت","قراءة القرآن على الميت","الحج عن الميت"]},{"n":200,"bab":"الزكاة","sub":"وجوب الزكاة","title":"وجوب الزكاة، وحكم من منعها بخلًا مع إقراره بوجوبها","q":"ما حكم الزكاة؟ ومن كان يعلم وجوبها ولكنه لا يخرجها بخلًا أو تهاونًا، فهل يكفر؟ وما عقوبته؟","short":"الزكاة ركن من أركان الإسلام، ووجوبها معلوم من الكتاب والسنة والإجماع، فمن جحد وجوبها وهو عالم كفر. وأما من منعها بخلًا مع إقراره بوجوبها: فذهب جمهور العلماء، ومنهم الأئمة الأربعة في المشهور، إلى أنه لا يكفر، ولكنه آثم فاسق، تؤخذ منه قهرًا، ويقاتَل إن امتنع بقوة. وذهبت طائفة، منها رواية عن أحمد، إلى تكفيره.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"خُذْ مِنْ أَمْوَٰلِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِم بِهَا","ref":"التوبة: ١٠٣"},{"t":"aya","text":"وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","ref":"التوبة: ٣٤"},{"t":"quote","text":"إِنَّكَ سَتَأْتِي قَوْمًا أَهْلَ كِتَابٍ، فَإِذَا جِئْتَهُمْ فَادْعُهُمْ إِلَى أَنْ يَشْهَدُوا أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَإِنْ هُمْ أَطَاعُوا لَكَ بِذَلِكَ، فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ خَمْسَ صَلَوَاتٍ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ، فَإِنْ هُمْ أَطَاعُوا لَكَ بِذَلِكَ فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ","src":"رواه البخاري ١٤٩٦","pre":"عن ابن عباس رضي الله عنهما أن رسول الله ﷺ قال لمعاذ حين بعثه إلى اليمن:","links":[{"book":"mt_bukhari","num":1496,"id":"h1496"}]},{"t":"quote","text":"مَنْ آتَاهُ اللَّهُ مَالاً، فَلَمْ يُؤَدِّ زَكَاتَهُ مُثِّلَ لَهُ يَوْمَ الْقِيَامَةِ شُجَاعًا أَقْرَعَ، لَهُ زَبِيبَتَانِ، يُطَوَّقُهُ يَوْمَ الْقِيَامَةِ، ثُمَّ يَأْخُذُ بِلِهْزِمَتَيْهِ ـ يَعْنِي شِدْقَيْهِ ـ ثُمَّ يَقُولُ أَنَا مَالُكَ، أَنَا كَنْزُكَ","src":"رواه البخاري ١٤٠٣","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1403,"id":"h1403"}]},{"t":"quote","text":"لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَكَانَ أَبُو بَكْرٍ ـ رضى الله عنه ـ وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ فَقَالَ عُمَرُ ـ رضى الله عنه كَيْفَ تُقَاتِلُ النَّاسَ، وَقَدْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لاَ إِلَهَ إِلاَّ اللَّهُ. فَمَنْ قَالَهَا فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلاَّ بِحَقِّهِ، وَحِسَابُهُ عَلَى اللَّهِ». فَقَالَ وَاللَّهِ لأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلاَةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ","src":"رواه البخاري ١٤٠٠","pre":"وعن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1400,"id":"h1400"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا مَعْرِفَةُ وُجُوبِهَا فَمَعْلُومٌ مِنَ الْكِتَابِ وَالسُّنَّةِ وَالْإِجْمَاعِ وَلَا خِلَافَ فِي ذَلِكَ","src":"بداية المجتهد","loc":"٢/٥","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الزكاة فريضة وركن من أركان الإسلام، من جحد وجوبها عالمًا كفر، ومن منعها بخلًا وتهاونًا مع إقراره بوجوبها فقد ارتكب كبيرة من أعظم الكبائر، وتوعّده الله بالعذاب الأليم، ولكنه لا يكفر على قول الجمهور، وتؤخذ منه قهرًا، ويُعزّر، ولولي الأمر أن يقاتل الممتنعين عن أدائها إذا كانت لهم شوكة، كما فعل أبو بكر الصديق رضي الله عنه بإجماع الصحابة."},{"t":"p","text":"والواجب على المسلم أن يبادر بإخراج زكاته طيبة بها نفسه، فإنها طهرة لماله ونفسه، وسبب لنماء المال وبركته، ولا يؤخرها بعد وجوبها إلا لعذر."}],"refs":["البخاري ١٤٩٦","البخاري ١٤٠٣","البخاري ١٤٠٠","بداية المجتهد (٢/٥)","بداية المجتهد (٢/١٠)"],"related":["حكم تارك الصلاة","زكاة مال الصبي والمجنون"],"alts":["حكم الزكاة","مانع الزكاة","تارك الزكاة","عقوبة منع الزكاة"]},{"n":201,"bab":"الزكاة","sub":"وجوب الزكاة","title":"زكاة مال الصبي والمجنون","q":"لي ابن أخ يتيم صغير ورث مالًا كثيرًا وأنا وليه، فهل يجب علي أن أخرج زكاة ماله؟ وكذلك مال المجنون؟","short":"ذهب مالك والشافعي وأحمد وجمهور الفقهاء، وهو قول علي وابن عمر وجابر وعائشة رضي الله عنهم، إلى وجوب الزكاة في مال الصبي والمجنون، ويخرجها الولي. وذهب أبو حنيفة وأصحابه إلى أنه لا زكاة في أموالهما إلا فيما تخرجه الأرض من العشر وصدقة الفطر، وهو قول ابن مسعود والنخعي والحسن.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ","src":"رواه البخاري ١٤٩٦","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال لمعاذ:","links":[{"book":"mt_bukhari","num":1496,"id":"h1496"}]},{"t":"quote","text":"أَلاَ مَنْ وَلِيَ يَتِيمًا لَهُ مَالٌ فَلْيَتَّجِرْ فِيهِ وَلاَ يَتْرُكْهُ حَتَّى تَأْكُلَهُ الصَّدَقَةُ","src":"رواه الترمذي ٦٤١","pre":"وعن عمرو بن شعيب عن أبيه عن جده أن النبي ﷺ خطب الناس فقال:","links":[{"book":"mt_tirmidhi","num":641,"id":"h641"}]},{"t":"quote","text":"وَإِنَّمَا رُوِيَ هَذَا الْحَدِيثُ مِنْ هَذَا الْوَجْهِ وَفِي إِسْنَادِهِ مَقَالٌ لأَنَّ الْمُثَنَّى بْنَ الصَّبَّاحِ يُضَعَّفُ فِي الْحَدِيثِ","src":"رواه الترمذي ٦٤١","pre":"قال الترمذي:","links":[{"book":"mt_tirmidhi","num":641,"id":"h641"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا فِي وُجُوبِهَا عَلَى الْيَتِيمِ وَالْمَجْنُونِ وَالْعَبِيدِ وَأَهْلِ الذِّمَّةِ وَالنَّاقِصِ الْمِلْكِ مِثْلِ الَّذِي عَلَيْهِ دَيْنٌ أَوْ لَهُ الدَّيْنُ، وَمِثَالِ الْمَالِ الْمُحَبَّسِ الْأَصْلِ.","src":"بداية المجتهد","loc":"٢/٥","pre":"قال ابن رشد:"},{"t":"quote","text":"المراد من اليتيم الصبي غير الحالم مات والداه أم لا، وقال الشافعي: يزكي ماله، ولا مرفوع لأحد، وللطرفين آثار، لنا أثر ابن مسعود، ولهم أثر عائشة الصديقة، وأما حديث الباب فساقط لأن فيه مثنى بن الصباح وما حسن أحد رواياته","src":"العرف الشذي","loc":"٢/١١٦","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والقول بوجوب الزكاة في مال الصبي يتيماً كان أو غير يتيم، قال به جمهور الفقهاء، وحكى ابن المنذر وجوبها في مال الصبي عن عمر ابن الخطاب وعلي وابن عمر وجابر والحسن بن علي","src":"يسألونك عن الزكاة","loc":"١/٤٥","pre":"قال الدكتور حسام الدين عفانة:"},{"t":"quote","text":"فإذا حال الحول على مال الصبي أو المجنون وجب على وليه أن يخرج زكاته","src":"فتاوى نور على الدرب لابن باز","loc":"٦/١٤","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر وجوب الزكاة في مال الصبي والمجنون، يخرجها عنهما وليهما؛ لعموم النصوص الموجبة للزكاة في أموال الأغنياء، ولأن الزكاة حق للفقراء في المال، فلا يشترط لها التكليف كنفقة الأقارب وضمان المتلفات، وهو قول جمهور الصحابة كعمر وعلي وعائشة وابن عمر. والحنفية لهم في ذلك أثر ابن مسعود ونظر معتبر في أن الزكاة عبادة تفتقر إلى النية والتكليف."},{"t":"p","text":"فعلى الولي أن يحسب حول مال اليتيم ويخرج زكاته إذا بلغ نصابًا، ويستحب له أن يستثمره حتى لا تأكله الزكاة. ومن كان وليًّا على يتيم في بلد يعمل فيه بمذهب الحنفية فأخذ بقولهم فلا إنكار عليه، والأحوط الإخراج، أو أن يحسب الولي الزكاة ويخبر بها اليتيم إذا بلغ ليخرجها هو إن شاء."}],"refs":["البخاري ١٤٩٦","الترمذي ٦٤١","بداية المجتهد (٢/٥)","العرف الشذي (٢/١١٦)","يسألونك عن الزكاة (١/٤٥)","فتاوى نور على الدرب لابن باز (٦/١٤)","بداية المجتهد (٢/٦)"],"related":["وجوب الزكاة، وحكم من منعها بخلًا مع إقراره بوجوبها"],"alts":["زكاة مال اليتيم","زكاة مال الصغير","زكاة مال المجنون"]},{"n":202,"bab":"الزكاة","sub":"وجوب الزكاة","title":"الدين وأثره في الزكاة: من عليه دين، ومن له دين على غيره","q":"عندي مال بلغ النصاب، ولكن علي ديون، فهل أخرج الزكاة قبل سداد الدين؟ وإذا كان لي دين عند شخص لسنوات فهل أزكيه؟","short":"اختلفوا فيمن عليه دين: فقال أبو حنيفة: الدين يمنع زكاة الأموال الباطنة والماشية لا الزروع، وقال مالك: يمنع زكاة النقدين فقط، وقال أحمد في المشهور: يمنع الزكاة في الأموال الباطنة، وقال الشافعي في الجديد: لا يمنع الزكاة أصلًا. وأما الدين على الغير: فإن كان على مليء مقر فيزكيه إذا قبضه لما مضى عند الحنفية والحنابلة، ولسنة واحدة عند مالك، وكل سنة عند الشافعي، وإن كان على معسر أو جاحد فلا زكاة فيه حتى يقبضه عند كثير منهم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ","src":"رواه البخاري ١٤٩٦","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال لمعاذ:","links":[{"book":"mt_bukhari","num":1496,"id":"h1496"}]},{"t":"p","text":"وروى مالك في الموطأ أن عثمان رضي الله عنه كان يقول: «هذا شهر زكاتكم، فمن كان عليه دين فليؤد دينه حتى تحصل أموالكم فتؤدون منه الزكاة»."},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"اختلف العلماء فيمن عليه دين يستغرق ماله أو ينقصه عن النصاب، وبيده مال تجب فيه الزكاة، على أقوال:"},{"t":"qawl","label":"القول الأول","text":"الدين يمنع وجوب الزكاة في الأموال كلها بقدره، فيُخرج الدين أولًا، فإن بقي نصاب زكّاه، وهو قول الثوري وأبي ثور وابن المبارك، ورواية عن أحمد."},{"t":"qawl","label":"القول الثاني","text":"الدين يمنع زكاة الأموال الباطنة كالنقود وعروض التجارة، ولا يمنع زكاة الزروع والثمار، وهو قول أبي حنيفة وأصحابه، وقال مالك: يمنع زكاة النقود فقط إلا أن تكون له عروض تفي بدينه."},{"t":"qawl","label":"القول الثالث","text":"الدين لا يمنع الزكاة أصلًا، وهو قول الشافعي في الجديد."},{"t":"quote","text":"وَمَنْ كَانَ عَلَيْهِ دَيْنٌ يُحِيطُ بِمَالِهِ فَلَا زَكَاةَ عَلَيْهِ وَقَالَ الشَّافِعِيُّ: تَجِبُ لِتَحَقُّقِ السَّبَبِ وَهُوَ مِلْكُ نِصَابٍ تَامٍّ. وَلَنَا أَنَّهُ مَشْغُولٌ بِحَاجَتِهِ الْأَصْلِيَّةِ فَاعْتُبِرَ مَعْدُومًا كَالْمَاءِ الْمُسْتَحَقِّ بِالْعَطَشِ وَثِيَابِ الْبِذْلَةِ وَالْمَهْنَةِ وَإِنْ كَانَ مَالُهُ أَكْثَرَ مِنْ دَيْنِهِ زَكَّى الْفَاضِلَ إذَا بَلَغَ نِصَابًا","src":"الهداية مع فتح القدير","loc":"٢/١٦٠","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من عليه دين حالّ يستغرق ماله أو ينقصه عن النصاب، فلا زكاة عليه فيما يقابل الدين من النقود وعروض التجارة؛ لقول عثمان رضي الله عنه بمحضر الصحابة، ولأن المدين ليس بغني، والزكاة إنما تؤخذ من الأغنياء، وهذا قول أبي حنيفة وأحمد في المشهور ومالك في النقود، فيخصم دينه الحالّ ثم يزكي ما بقي إن بلغ نصابًا. وأما الديون المؤجلة الطويلة كأقساط البيت فلا يخصم منها إلا القسط الحال في سنته."},{"t":"p","text":"ومن كان له دين على غيره: فإن كان على مليء معترف باذل، زكّاه مع ماله كل سنة، أو إذا قبضه زكاه لما مضى، وإن كان على معسر أو مماطل أو جاحد لا يرجى، فالأظهر أنه لا زكاة فيه حتى يقبضه، فإذا قبضه زكاه لسنة واحدة، وهو قول مالك واختيار جمع من المحققين."}],"refs":["البخاري ١٤٩٦","الهداية مع فتح القدير (٢/١٦٠)"],"related":["زكاة عروض التجارة"],"alts":["زكاة المدين","هل الدين يمنع الزكاة","زكاة الدين","زكاة القرض"]},{"n":203,"bab":"الزكاة","sub":"ما تجب فيه الزكاة","title":"زكاة الحلي المعد للاستعمال","q":"عندي ذهب ألبسه للزينة وقد بلغ النصاب، فهل تجب فيه الزكاة كل سنة؟","short":"ذهب مالك والشافعي وأحمد، وفقهاء الحجاز، وهو قول عائشة وابن عمر وجابر وأسماء، إلى أنه لا زكاة في الحلي المباح المعد للاستعمال. وذهب أبو حنيفة وأصحابه، وهو قول عمر وابن مسعود وابن عباس، إلى وجوب الزكاة فيه إذا بلغ نصابًا. واتفقوا على وجوبها في الحلي المعد للادخار أو التجارة أو المحرم.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","ref":"التوبة: ٣٤"},{"t":"quote","text":"أَنَّ امْرَأَةً، أَتَتْ رَسُولَ اللَّهِ صلى الله عليه وسلم وَمَعَهَا ابْنَةٌ لَهَا وَفِي يَدِ ابْنَتِهَا مَسَكَتَانِ غَلِيظَتَانِ مِنْ ذَهَبٍ فَقَالَ لَهَا «أَتُعْطِينَ زَكَاةَ هَذَا» . قَالَتْ لاَ . قَالَ «أَيَسُرُّكِ أَنْ يُسَوِّرَكِ اللَّهُ بِهِمَا يَوْمَ الْقِيَامَةِ سِوَارَيْنِ مِنْ نَارٍ» . قَالَ فَخَلَعَتْهُمَا فَأَلْقَتْهُمَا إِلَى النَّبِيِّ صلى الله عليه وسلم وَقَالَتْ هُمَا لِلَّهِ عَزَّ وَجَلَّ وَلِرَسُولِهِ","src":"رواه أبو داود ١٥٦٣","pre":"عن عمرو بن شعيب عن أبيه عن جده:","links":[{"book":"mt_abudawud","num":1563,"id":"h1563"}]},{"t":"quote","text":"مَا مِنْ صَاحِبِ ذَهَبٍ وَلَا فِضَّةٍ، لَا يُؤَدِّي مِنْهَا حَقَّهَا، إِلَّا إِذَا كَانَ يَوْمُ الْقِيَامَةِ، صُفِّحَتْ لَهُ صَفَائِحُ مِنْ نَارٍ، فَأُحْمِيَ عَلَيْهَا فِي نَارِ جَهَنَّمَ، فَيُكْوَى بِهَا جَنْبُهُ وَجَبِينُهُ وَظَهْرُهُ","src":"رواه مسلم ٩٨٧","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":987,"id":"h987"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَالذين اخْتَلَفُوا فيه مِنَ الذَّهَبِ هو الْحُلِيُّ فَقَطْ) ، وَذَلِكَ أَنَّهُ ذَهَبَ فُقَهَاءُ الْحِجَازِ: مَالِكٌ وَاللَّيْثُ وَالشَّافِعِيُّ إِلَى أَنَّهُ لَا زَكَاةَ فِيهِ إِذَا أُرِيدَ لِلزِّينَةِ وَاللِّبَاسِ وَقَالَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ: فِيهِ الزَّكَاةُ","src":"بداية المجتهد","loc":"٢/١١","pre":"قال ابن رشد:"},{"t":"quote","text":"لا زكاة في الحلي عند الشافعي ومالك وأحمد، وقال أبو حنيفة: فيها زكاة إذا صيغت من الذهب والفضة وصح الحديثان لمذهب أبي حنيفة، وتعرض الشافعية وتبعهم أن يكلموا في إسنادهما ولا يمكن الكلام فيهما","src":"العرف الشذي","loc":"٢/١١٣","pre":"وقال الكشميري الحنفي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"واختلف العلماء في الزكاة هل تجب في الحلي أم لا","src":"مجموع فتاوى ابن باز","loc":"٤/١٢٤","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"باب زكاة الحلي، قال المصنف لا يصح في هذا الباب شيء عن النبي صلى الله عليه وسلم","src":"فتاوى اللجنة الدائمة","loc":"٩/٢٦٤","pre":"وجاء في فتاوى اللجنة الدائمة نقلًا عن بعض أهل الحديث:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر والأحوط إخراج الزكاة عن الحلي من الذهب والفضة إذا بلغ نصابًا وحال عليه الحول، وهو مذهب الحنفية، وقول عمر وابن مسعود وابن عباس؛ لعموم النصوص الموجبة للزكاة في الذهب والفضة، ولحديث المسكتين وحديث عائشة وأم سلمة في الأوضاح، وقد حسّنها جمع من المحدثين، ولأن الذهب والفضة أصل الأثمان فتجب فيهما الزكاة على كل حال."},{"t":"p","text":"ومن أخذ بقول الجمهور في عدم وجوبها في الحلي المعتاد المستعمل فله سلف من الصحابة كعائشة وابن عمر وجابر وأسماء، ولا يُنكر عليه، والقول بأن زكاته عاريته قول جماعة من السلف. وأما ما زاد عن المعتاد، أو اتُّخذ للادخار أو للتجارة أو للكراء، فتجب فيه الزكاة عند الجميع. وتُحسب الزكاة بوزن الذهب الخالص، فيخرج ربع العشر من قيمته يوم الإخراج."}],"refs":["أبو داود ١٥٦٣","مسلم ٩٨٧","بداية المجتهد (٢/١١)","العرف الشذي (٢/١١٣)","مجموع فتاوى ابن باز (٤/١٢٤)","فتاوى اللجنة الدائمة (٩/٢٦٤)","بداية المجتهد (٢/١١-١٢)"],"related":["نصاب الذهب والفضة والأوراق النقدية، وضم أحدهما إلى الآخر"],"alts":["زكاة الذهب الملبوس","زكاة حلي المرأة","زكاة المصوغات","زكاة الذهب المستعمل"]},{"n":204,"bab":"الزكاة","sub":"ما تجب فيه الزكاة","title":"زكاة الخيل والمواشي المعلوفة والعوامل","q":"عندي أبقار أعلفها في الحظيرة طوال السنة ولا ترعى، فهل فيها زكاة؟ وما حكم زكاة الخيل؟","short":"ذهب جمهور العلماء، ومنهم أبو حنيفة والشافعي وأحمد، إلى أن الزكاة في الإبل والبقر والغنم إنما تجب في السائمة التي ترعى أكثر الحول، ولا زكاة في المعلوفة والعوامل إلا إذا كانت للتجارة، وأوجبها مالك والليث في السائمة والمعلوفة. وأما الخيل فلا زكاة فيها عند الجمهور، وأوجبها أبو حنيفة في السائمة المتخذة للنسل إذا كانت ذكورًا وإناثًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَيْسَ عَلَى الْمُسْلِمِ فِي عَبْدِهِ وَلَا فَرَسِهِ صَدَقَةٌ","src":"رواه مسلم ٩٨٢","pre":"عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":982,"id":"h982"}]},{"t":"quote","text":"وَفِي سَائِمَةِ الْغَنَمِ إِذَا كَانَتْ أَرْبَعِينَ فَفِيهَا شَاةٌ","src":"رواه أبو داود ١٥٦٧","pre":"وعن أنس رضي الله عنه في كتاب أبي بكر الصديق الذي كتبه له في الصدقة:","links":[{"book":"mt_abudawud","num":1567,"id":"h1567"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَإِنَّ قَوْمًا أَوْجَبُوا الزَّكَاةَ فِي هَذِهِ الْأَصْنَافِ اَلثَّلَاثَةِ سَائِمَةً كَانَتْ أَوْ غَيْرَ سَائِمَةٍ، وَبِهِ قَالَ اللَّيْثُ وَمَالِكٌ. وَقَالَ سَائِرُ فُقَهَاءِ الْأَمْصَارِ: لَا زَكَاةَ فِي غَيْرِ السَّائِمَةِ مِنْ هَذِهِ الأَنْوَاع","src":"بداية المجتهد","loc":"٢/١٣","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أبو حنيفة: إن في الخيل إذا كانت للتجارة أو للتناسل زكاة، وقال سائر الأئمة: لا زكاة في الخيل وأتى الزيلعي لواقعتين أخذ فيهما عمر بن الخطاب زكاة الخيل","src":"العرف الشذي","loc":"٢/١٠٩","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن زكاة بهيمة الأنعام (الإبل والبقر والغنم) إنما تجب في السائمة، وهي التي ترعى من الكلأ المباح أكثر السنة؛ لتقييد النبي ﷺ ذلك بالسائمة، ولأن المعلوفة يكثر فيها المؤنة فلا يحتمل مالكها الزكاة، وهو قول الجمهور. فإن كانت المواشي معدة للتجارة، كمزارع تسمين الأبقار والدواجن للبيع، زُكيت زكاة عروض التجارة بقيمتها."},{"t":"p","text":"ولا زكاة في الخيل والبغال والحمير المتخذة للركوب والعمل؛ لحديث أبي هريرة، فإن اتخذت للتجارة ففيها زكاة التجارة. ومن أخذ بقول أبي حنيفة في الخيل السائمة المتخذة للنسل فأخرج عنها فله سلف من فعل عمر رضي الله عنه."}],"refs":["مسلم ٩٨٢","أبو داود ١٥٦٧","بداية المجتهد (٢/١٣)","بداية المجتهد (٢/١٢)","العرف الشذي (٢/١٠٩)"],"related":["زكاة عروض التجارة"],"alts":["زكاة الأبقار المعلوفة","زكاة الخيل","زكاة السائمة","زكاة الدواجن"]},{"n":205,"bab":"الزكاة","sub":"ما تجب فيه الزكاة","title":"ما تجب فيه الزكاة من الزروع والثمار، وزكاة الخضروات والفواكه والعسل","q":"أزرع القمح والذرة والطماطم والبطاطس وعندي بستان فاكهة، فما الذي تجب فيه الزكاة؟ وهل في العسل زكاة؟","short":"اتفقوا على وجوب الزكاة في الحنطة والشعير والتمر والزبيب. ثم أوجبها مالك والشافعي في كل ما يُقتات ويُدخر، وأوجبها أحمد في كل ما يُكال ويُدخر، وأوجبها أبو حنيفة في كل ما تخرجه الأرض مما يُقصد بزراعته استغلال الأرض، حتى الخضروات والفواكه، إلا الحطب والحشيش والقصب الفارسي. وأوجب أبو حنيفة وأحمد الزكاة في العسل، ولم يوجبها مالك والشافعي.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"وَءَاتُوا۟ حَقَّهُۥ يَوْمَ حَصَادِهِۦ","ref":"الأنعام: ١٤١"},{"t":"quote","text":"فِيمَا سَقَتِ السَّمَاءُ وَالْعُيُونُ أَوْ كَانَ عَثَرِيًّا الْعُشْرُ، وَمَا سُقِيَ بِالنَّضْحِ نِصْفُ الْعُشْرِ","src":"رواه البخاري ١٤٨٣","pre":"عن ابن عمر رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1483,"id":"h1483"}]},{"t":"quote","text":"لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ صَدَقَةٌ «. حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، حَدَّثَنَا عَبْدُ الْوَهَّابِ، قَالَ حَدَّثَنِي يَحْيَى بْنُ سَعِيدٍ، قَالَ أَخْبَرَنِي عَمْرٌو، سَمِعَ أَبَاهُ، عَنْ أَبِي سَعِيدٍ ـ رضى الله عنه ـ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم بِهَذَا»","src":"رواه البخاري ١٤٤٧","pre":"وعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1447,"id":"h1447"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا مَا اخْتَلَفُوا فِيهِ مِنَ النَّبَاتِ بَعْدَ اتِّفَاقِهِمْ عَلَى الْأَصْنَافِ الْأَرْبَعَةِ الَّتِي ذَكَرْنَاهَا: فَهُوَ جِنْسُ النَّبَاتِ الَّذِي تَجِبُ فِيهِ الزَّكَاةُ، فَمِنْهُمْ مَنْ لَمْ يَرَ الزَّكَاةَ إِلَّا فِي تِلْكَ الْأَرْبَعِ فَقَطْ، وَبِهِ قَالَ ابْنُ أَبِي لَيْلَى وَسُفْيَانُ الثَّوْرِيُّ وَابْنُ الْمُبَارَكِ.","src":"بداية المجتهد","loc":"٢/١٤","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الحجازيون: لا عشر في الخضروات، وقال أبو حنيفة: إن في الخضروات صدقة ويؤديها ديانة أي فيما بينه وبين الله، ولا يجب رفعها إلى بيت المال","src":"العرف الشذي","loc":"٢/١١٤-١١٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الزكاة تجب في كل ما يُكال ويُدخر من الحبوب والثمار، كالقمح والشعير والذرة والأرز والعدس والحمص والتمر والزبيب ونحوها، إذا بلغ النصاب خمسة أوسق، وهو قول أحمد، وقريب من قول مالك والشافعي؛ لأن النبي ﷺ قدّر نصابها بالأوسق، وهي مكاييل، فدل على أنها فيما يكال ويدخر."},{"t":"p","text":"وأما الخضروات والفواكه التي لا تدخر كالطماطم والبطاطس والبطيخ، فلا زكاة فيها على قول الجمهور، لكن إذا بيعت وحال الحول على ثمنها وهو نصاب زكي زكاة النقود. ومن أخذ بمذهب أبي حنيفة فأخرج العشر أو نصفه من جميع ما تخرجه أرضه فهو أحوط وأبرأ لذمته، وله ظاهر الآية وعموم الحديث. وفي العسل يستحب إخراج العشر؛ لثبوته عن عمر رضي الله عنه، وهو قول أبي حنيفة وأحمد."}],"refs":["البخاري ١٤٨٣","البخاري ١٤٤٧","بداية المجتهد (٢/١٤)","العرف الشذي (٢/١١٤-١١٥)"],"related":["نصاب الزروع والثمار، والعشر ونصف العشر، والخرص"],"alts":["زكاة الخضروات","زكاة الفواكه","زكاة الزرع","زكاة العسل","زكاة الحبوب"]},{"n":206,"bab":"الزكاة","sub":"ما تجب فيه الزكاة","title":"زكاة عروض التجارة: حكمها وكيفية تقويمها","q":"عندي محل تجاري فيه بضائع، فهل تجب فيها الزكاة؟ وكيف أحسبها: بسعر الشراء أو البيع؟ وهل في الأرض التي اشتريتها للبيع زكاة؟","short":"ذهب فقهاء الأمصار والأئمة الأربعة إلى وجوب الزكاة في عروض التجارة، وهو المروي عن عمر وابنه، ولا يعرف لهما مخالف من الصحابة، ومنعها أهل الظاهر. وتقوّم عند الحول بسعر السوق وتُخرج ربع العشر من قيمتها. وقال مالك في التاجر المحتكر الذي يتربص بسلعته الغلاء: لا يزكيها إلا لسنة واحدة إذا باعها.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَـٰتِ مَا كَسَبْتُمْ","ref":"البقرة: ٢٦٧"},{"t":"quote","text":"أَمَّا بَعْدُ فَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يَأْمُرُنَا أَنْ نُخْرِجَ الصَّدَقَةَ مِنَ الَّذِي نُعِدُّ لِلْبَيْعِ","src":"رواه أبو داود ١٥٦٢","pre":"عن سمرة بن جندب رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":1562,"id":"h1562"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاتَّفَقُوا عَلَى أَنْ لَا زَكَاةَ فِي الْعُرُوضِ الَّتِي لَمْ يُقْصَدْ بِهَا التِّجَارَةُ، وَاخْتَلَفُوا فِي إيجاب الزَّكَاة فِيمَا اتُّخِذَ مِنْهَا لِلتِّجَارَةِ، فَذَهَبَ فُقَهَاءُ الْأَمْصَارِ إِلَى وُجُوبِ ذَلِكَ، وَمَنَعَ ذَلِكَ أَهْلُ الظَّاهِرِ","src":"بداية المجتهد","loc":"٢/١٥","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر وجوب الزكاة في عروض التجارة، وهي كل ما أُعدّ للبيع بقصد الربح، من البضائع والسيارات والعقارات والأراضي المعدة للبيع، وهو قول الأئمة الأربعة وعامة أهل العلم. فإذا حال الحول، قوّم التاجر ما عنده من البضائع بسعر بيعها في السوق يوم وجوب الزكاة، وأضاف إليها ما عنده من النقود والديون المرجوة، وخصم الديون الحالّة التي عليه، ثم أخرج ربع العشر إن بلغ المجموع نصابًا."},{"t":"p","text":"ولا زكاة في الأصول الثابتة التي لا تباع، كالمحل نفسه وأثاثه وأجهزته وسيارات النقل، ولا في البيت المسكون والسيارة المستعملة، وإنما الزكاة فيما يعد للبيع. والأرض المشتراة للبيع تزكى بقيمتها كل سنة، فإن اشتريت للبناء والسكنى فلا زكاة فيها، فإن تغيرت النية إلى البيع بدأ حولها من حين النية عند جمع من أهل العلم."}],"refs":["أبو داود ١٥٦٢","بداية المجتهد (٢/١٥)"],"related":["الدين وأثره في الزكاة: من عليه دين، ومن له دين على غيره"],"alts":["زكاة البضائع","زكاة التجارة","زكاة الأرض المعدة للبيع","زكاة المحل التجاري","تقويم عروض التجارة"]},{"n":207,"bab":"الزكاة","sub":"وجوب الزكاة","title":"هلاك المال بعد وجوب الزكاة، وضياع الزكاة بعد عزلها، ومن مات وعليه زكاة","q":"عزلت زكاة مالي لأوزعها ثم سُرقت، فهل علي إخراجها مرة أخرى؟ ومات أبي ولم يخرج زكاة سنوات، فهل نخرجها من تركته؟","short":"إذا عزل الزكاة فضاعت من غير تفريط: فقال قوم: تجزئه، وقال قوم: يضمنها، وفصّل آخرون بين التفريط وعدمه. وإذا هلك المال بعد الوجوب وقبل التمكن من الإخراج سقطت الزكاة عند الجمهور، وعند الحنفية تسقط بهلاك المال مطلقًا. ومن مات وعليه زكاة أُخرجت من رأس ماله عند الشافعي وأحمد كسائر الديون، وقال أبو حنيفة ومالك: لا تُخرج إلا إن أوصى بها، فتكون من الثلث.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ صَامَ عَنْهُ وَلِيُّهُ «. تَابَعَهُ ابْنُ وَهْبٍ عَنْ عَمْرٍو. وَرَوَاهُ يَحْيَى بْنُ أَيُّوبَ عَنِ ابْنِ أَبِي جَعْفَرٍ»","src":"رواه البخاري ١٩٥٢","pre":"عن عائشة رضي الله عنها أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1952,"id":"h1952"}]},{"t":"p","text":"وقال النبي ﷺ في حديث الخثعمية: «فدين الله أحق أن يقضى»، متفق عليه."},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"إذا عزل المزكي زكاته فضاعت قبل أن يوصلها إلى مستحقيها، ففي ضمانها خمسة أقوال: أنه لا يضمن مطلقًا، وأنه يضمن مطلقًا، وأنه يضمن إن فرّط ولا يضمن إن لم يفرّط، وهو مشهور مذهب مالك ونحوه عند الحنابلة، وأنه إن فرّط ضمن وإن لم يفرّط زكّى ما بقي، وهو قول الشافعي وأبي ثور، وأنه والمساكين شريكان في الباقي بنسبة حظوظهما."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من عزل زكاته ليدفعها فتلفت أو سُرقت من غير تفريط منه ولا تأخير، فلا ضمان عليه، وإن كان قد فرّط في حفظها أو أخرها بلا عذر فعليه إخراجها مرة أخرى؛ لأنها في ذمته حتى تصل إلى مستحقها. وإن هلك المال كله بعد الحول وقبل أن يتمكن من الإخراج سقطت الزكاة، وإن تمكن ففرّط ضمن."},{"t":"p","text":"ومن مات وعليه زكاة سنوات لم يخرجها، فالأظهر أنها تخرج من تركته قبل قسمة الميراث، أوصى أو لم يوص؛ لأنها دين لله تعالى، و«دين الله أحق أن يقضى»، وهو قول الشافعي وأحمد. ومن أخذ بقول الحنفية والمالكية فإنه يستحب للورثة أن يخرجوها تبرعًا برًّا بميتهم وإبراءً لذمته."}],"refs":["البخاري ١٩٥٢"],"related":["ما ينتفع به الميت: الدعاء والصدقة والصيام والحج، وقراءة القرآن وإهداء الثواب"],"alts":["ضياع الزكاة","سرقة مال الزكاة","زكاة الميت","هلاك المال قبل الزكاة"]},{"n":208,"bab":"الزكاة","sub":"النصاب","title":"نصاب الذهب والفضة والأوراق النقدية، وضم أحدهما إلى الآخر","q":"ما نصاب الذهب والفضة بالغرامات؟ وكيف أحسب نصاب النقود الورقية التي عندي: بالذهب أو بالفضة؟ وإذا كان عندي ذهب وفضة ونقود لا يبلغ كل واحد منها نصابًا، فهل أضمها؟","short":"أجمعوا على أن نصاب الفضة خمس أواق (مائتا درهم)، وذهب جماهير العلماء ومنهم الأئمة الأربعة إلى أن نصاب الذهب عشرون مثقالًا (دينارًا)، والواجب فيهما ربع العشر. وذهب أبو حنيفة ومالك وأحمد في رواية إلى ضم الذهب إلى الفضة في تكميل النصاب، ومنعه الشافعي وأحمد في رواية. والأوراق النقدية في حكم الذهب والفضة عند عامة العلماء المعاصرين.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ مِنَ التَّمْرِ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ مِنَ الْوَرِقِ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ مِنَ الإِبِلِ صَدَقَةٌ","src":"رواه البخاري ١٤٥٩","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1459,"id":"h1459"}]},{"t":"quote","text":"فَإِذَا كَانَتْ لَكَ مِائَتَا دِرْهَمٍ وَحَالَ عَلَيْهَا الْحَوْلُ فَفِيهَا خَمْسَةُ دَرَاهِمَ وَلَيْسَ عَلَيْكَ شَىْءٌ - يَعْنِي فِي الذَّهَبِ - حَتَّى يَكُونَ لَكَ عِشْرُونَ دِينَارًا فَإِذَا كَانَ لَكَ عِشْرُونَ دِينَارًا وَحَالَ عَلَيْهَا الْحَوْلُ فَفِيهَا نِصْفُ دِينَارٍ فَمَا زَادَ فَبِحِسَابِ ذَلِكَ","src":"رواه أبو داود ١٥٧٣","pre":"وعن علي رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":1573,"id":"h1573"}]},{"t":"quote","text":"فِي الرِّقَةِ رُبْعُ الْعُشْرِ، فَإِنْ لَمْ تَكُنْ إِلاَّ تِسْعِينَ وَمِائَةً فَلَيْسَ فِيهَا شَىْءٌ، إِلاَّ أَنْ يَشَاءَ رَبُّهَا","src":"رواه البخاري ١٤٥٤","pre":"وفي كتاب أبي بكر الصديق رضي الله عنه في الصدقة:","links":[{"book":"mt_bukhari","num":1454,"id":"h1454"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْمِقْدَارُ الَّذِي تَجِبُ فِيهِ الزَّكَاةُ مِنَ الْفِضَّةِ، فَإِنَّهُمُ اتَّفَقُوا عَلَى أَنَّهُ خَمْسِ أَوَاقٍ لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - الثَّابِتُ: «لَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ مِنَ الْوَرِقِ صَدَقَةٌ»","src":"بداية المجتهد","loc":"٢/١٦","pre":"قال ابن رشد:"},{"t":"quote","text":"وفي حكم الذهب والفضة الأوراق النقدية التي يتعامل بها الناس اليوم، سواء سميت: درهما أو دينارا أو دولارا، أو غير ذلك من الأسماء، إذا بلغت قيمتها نصاب الفضة أو الذهب وحال عليها الحول وجبت فيها الزكاة","src":"مجموع فتاوى ابن باز","loc":"١٤/٣٣٣","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فإذا بلغت قيمة الأوراق النقدية والعروض المعدة للتجارة نصاب الذهب والفضة وجبت فيها الزكاة","src":"مجموع فتاوى ابن باز","loc":"١٤/٧٩","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"quote","text":"فما بلغ منها هذا الوزن فهو النصاب، واعرف قيمة ذلك النصاب من الأوراق النقدية المتعامل بها اليوم وأخرج منها ربع عشرها","src":"فتاوى اللجنة الدائمة","loc":"٩/١٩٧","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن نصاب الذهب عشرون مثقالًا، وتساوي نحو خمسة وثمانين غرامًا من الذهب الخالص، ونصاب الفضة مائتا درهم، وتساوي نحو خمسمائة وخمسة وتسعين غرامًا من الفضة الخالصة، والواجب فيهما ربع العشر (اثنان ونصف في المائة). وما زاد على النصاب ففيه بحسابه قلّ أو كثر، وهو قول الجمهور وصاحبي أبي حنيفة، وقال أبو حنيفة: لا شيء في الزيادة حتى تبلغ خُمس النصاب."},{"t":"p","text":"والأوراق النقدية والأرصدة البنكية لها حكم الذهب والفضة، فإذا بلغت قيمتها نصاب أحدهما وحال عليها الحول وجبت فيها الزكاة. والأحوط للمسلم، والأنفع للفقراء، أن يُقدَّر نصاب النقود بأدنى النصابين قيمة، وهو نصاب الفضة في زماننا، وهو اختيار كثير من المحققين ومراعاة لقول الحنفية في اعتبار الأنفع للفقراء، ومن قدّره بالذهب لأن قيمته أثبت وأقرب إلى قيمة نصاب الماشية في زماننا فله وجه معتبر قال به جمع من المعاصرين."},{"t":"p","text":"والأظهر ضم الذهب والفضة والنقود وعروض التجارة بعضها إلى بعض بالقيمة في تكميل النصاب؛ لأنها كلها أثمان مقصودها واحد، وهو قول أبي حنيفة ومالك وأحمد في رواية."}],"refs":["البخاري ١٤٥٩","أبو داود ١٥٧٣","البخاري ١٤٥٤","بداية المجتهد (٢/١٦)","بداية المجتهد (٢/١٨)","مجموع فتاوى ابن باز (١٤/٣٣٣)","مجموع فتاوى ابن باز (١٤/٧٩)","فتاوى اللجنة الدائمة (٩/١٩٧)"],"related":["زكاة الحلي المعد للاستعمال","زكاة عروض التجارة"],"alts":["نصاب الذهب بالغرام","نصاب الفضة","نصاب الزكاة في النقود","زكاة الرصيد البنكي","ضم الذهب إلى الفضة"]},{"n":209,"bab":"الزكاة","sub":"النصاب","title":"زكاة المعادن والركاز (الكنز المدفون)","q":"وجدت في أرضي كنزًا قديمًا مدفونًا فيه ذهب، فما الواجب علي فيه؟ وما زكاة ما يُستخرج من المعادن كالذهب والنفط؟","short":"أجمعوا على أن في الركاز، وهو دفين الجاهلية، الخمس. واختلفوا في المعدن: فذهب مالك والشافعي إلى أن فيه ربع العشر إذا بلغ نصابًا، ولا يشترط له الحول عند مالك، وقال أحمد: فيه ربع العشر في كل معدن، وذهب أبو حنيفة إلى أن المعدن من الركاز، ففيه الخمس بلا نصاب ولا حول.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الْعَجْمَاءُ جُبَارٌ، وَالْبِئْرُ جُبَارٌ، وَالْمَعْدِنُ جُبَارٌ، وَفِي الرِّكَازِ الْخُمُسُ","src":"رواه البخاري ١٤٩٩","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1499,"id":"h1499"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَهِيَ اخْتِلَافُهُمْ فِي اعْتِبَارِ النِّصَابِ فِي الْمَعْدِنِ وَقَدْرِ الْوَاجِبِ فِيهِ -: فَإِنَّ مَالِكًا وَالشَّافِعِيَّ رَاعَيَا النِّصَابَ فِي الْمَعْدِنِ، وَإِنَّمَا الْخِلَافُ بَيْنَهُمَا أَنَّ مَالِكًا لَمْ يَشْتَرِطِ الْحَوْلَ، وَاشْتَرَطَهُ الشَّافِعِيُّ عَلَى مَا سَنَقُولُ بَعْدُ فِي الْجُمْلَةِ الرَّابِعَةِ","src":"بداية المجتهد","loc":"٢/١٩","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الركاز، وهو المال المدفون من كنوز الأمم السابقة، يجب فيه الخمس على واجده قلّ أو كثر، بلا نصاب ولا حول؛ لحديث أبي هريرة. وأما المعدن، وهو ما يُستخرج من الأرض مما خلقه الله فيها كالذهب والفضة والحديد والنحاس، فالأظهر أن فيه ربع العشر إذا بلغ نصابًا، يخرجه عند استخراجه، وهو قول الجمهور؛ لأن الحديث فرّق بين المعدن والركاز. وقول أبي حنيفة بأن فيه الخمس قول معتبر، له وجه من اللغة."},{"t":"tanbih","items":[{"t":"p","text":"ما وُجد من المال وعليه علامة المسلمين فهو لقطة يُعرَّف، وليس ركازًا. والمعادن الكبرى كالنفط والغاز التي تملكها الدولة تصرف عوائدها في مصالح المسلمين العامة."}]}],"refs":["البخاري ١٤٩٩","بداية المجتهد (٢/١٩)","بداية المجتهد (٢/٢٠)"],"related":["نصاب الذهب والفضة والأوراق النقدية، وضم أحدهما إلى الآخر"],"alts":["زكاة الكنز","زكاة الركاز","زكاة المعادن","الخمس في الركاز"]},{"n":210,"bab":"الزكاة","sub":"النصاب","title":"نصاب الإبل والبقر والغنم، وما يؤخذ في زكاتها","q":"عندي غنم وأبقار ترعى في المراعي طوال السنة، فكم نصابها؟ وما الواجب فيها؟ وهل يؤخذ في الزكاة المعيب والهرم؟","short":"أجمعوا على أن في كل خمس من الإبل شاة إلى أربع وعشرين، ثم بنت مخاض، ثم بنت لبون، ثم حقة، ثم جذعة، على ما في كتاب الصدقة، واختلفوا فيما زاد على مائة وعشرين. وجمهور العلماء على أن في ثلاثين من البقر تبيعًا، وفي أربعين مسنة. وأجمعوا على أن في أربعين من الغنم شاة إلى مائة وعشرين، ثم شاتان إلى مائتين، ثم ثلاث إلى ثلاثمائة، ثم في كل مائة شاة. ولا تؤخذ الهرمة ولا المعيبة ولا التيس.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"هَذِهِ فَرِيضَةُ الصَّدَقَةِ الَّتِي فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى الْمُسْلِمِينَ، وَالَّتِي أَمَرَ اللَّهُ بِهَا رَسُولَهُ، فَمَنْ سُئِلَهَا مِنَ الْمُسْلِمِينَ عَلَى وَجْهِهَا فَلْيُعْطِهَا، وَمَنْ سُئِلَ فَوْقَهَا فَلاَ يُعْطِ فِي أَرْبَعٍ وَعِشْرِينَ مِنَ الإِبِلِ فَمَا دُونَهَا مِنَ الْغَنَمِ مِنْ كُلِّ خَمْسٍ شَاةٌ، إِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ إِلَى خَمْسٍ وَثَلاَثِينَ فَفِيهَا بِنْتُ مَخَاضٍ أُنْثَى","src":"رواه البخاري ١٤٥٤","pre":"عن أنس رضي الله عنه أن أبا بكر رضي الله عنه كتب له هذا الكتاب لما وجهه إلى البحرين:","links":[{"book":"mt_bukhari","num":1454,"id":"h1454"}]},{"t":"quote","text":"بَعَثَنِي النَّبِيُّ صلى الله عليه وسلم إِلَى الْيَمَنِ فَأَمَرَنِي أَنْ آخُذَ مِنْ كُلِّ ثَلاَثِينَ بَقَرَةً تَبِيعًا أَوْ تَبِيعَةً وَمِنْ كُلِّ أَرْبَعِينَ مُسِنَّةً","src":"رواه الترمذي ٦٢٣","pre":"وعن معاذ بن جبل رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":623,"id":"h623"}]},{"t":"quote","text":"وَلاَ يُخْرَجُ فِي الصَّدَقَةِ هَرِمَةٌ، وَلاَ ذَاتُ عَوَارٍ، وَلاَ تَيْسٌ، إِلاَّ مَا شَاءَ الْمُصَدِّقُ","src":"رواه البخاري ١٤٥٥","pre":"وفي كتاب أبي بكر رضي الله عنه:","links":[{"book":"mt_bukhari","num":1455,"id":"h1455"}]},{"t":"h","text":"أقوال العلماء"},{"t":"p","text":"أجمع المسلمون على مقادير زكاة الإبل الثابتة في كتاب الصدقة الذي كتبه رسول الله ﷺ وعمل به أبو بكر وعمر رضي الله عنهما: في كل خمس من الإبل شاة إلى أربع وعشرين، وفي خمس وعشرين بنت مخاض (فإن لم توجد فابن لبون)، وفي ست وثلاثين بنت لبون، وفي ست وأربعين حقة، وفي إحدى وستين جذعة، وفي ست وسبعين بنتا لبون، وفي إحدى وتسعين حقتان إلى عشرين ومائة. واختلفوا فيما زاد على عشرين ومائة."},{"t":"quote","text":"ولا خلاف في البقر إلى أربعين، وإذا زادت فعند أبي حنيفة في الكسور أيضاً زكاة لا عند صاحبيه","src":"العرف الشذي","loc":"٢/١٠٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن زكاة الماشية السائمة على ما جاء في كتاب الصدقة الذي كتبه أبو بكر الصديق رضي الله عنه، وكتاب عمر رضي الله عنه، وحديث معاذ: ففي الغنم: من أربعين إلى مائة وعشرين شاة، ومن مائة وإحدى وعشرين إلى مائتين شاتان، ومن مائتين وواحدة إلى ثلاثمائة ثلاث شياه، ثم في كل مائة شاة. وفي البقر: في كل ثلاثين تبيع أو تبيعة، وفي كل أربعين مسنة، وما بين الفرضين عفو على قول الجمهور. وفي الإبل: في كل خمس شاة إلى أربع وعشرين، ثم تؤخذ من الإبل بأسنانها المذكورة في الكتاب."},{"t":"p","text":"ويؤخذ من وسط المال، فلا يأخذ الساعي خيار المال وكرائمه، ولا يُخرج المالك الهرمة والمعيبة والتيس، إلا أن يرى الساعي في ذلك مصلحة للفقراء. ويُعد على المالك صغار الماشية التي ولدت في أثناء الحول تبعًا لأمهاتها، كما أمر عمر رضي الله عنه."}],"refs":["البخاري ١٤٥٤","الترمذي ٦٢٣","البخاري ١٤٥٥","العرف الشذي (٢/١٠٥)"],"related":["زكاة الخيل والمواشي المعلوفة والعوامل","الخلطة في الماشية وأثرها في الزكاة"],"alts":["زكاة الغنم","زكاة البقر","زكاة الإبل","نصاب الماشية","زكاة الأنعام"]},{"n":211,"bab":"الزكاة","sub":"النصاب","title":"الخلطة في الماشية وأثرها في الزكاة","q":"أنا وأخي نملك غنمًا ترعى معًا في مرعى واحد ولها راع واحد، لكل منا ثلاثون شاة، فهل تجب علينا الزكاة لأن المجموع ستون؟","short":"ذهب مالك والشافعي وأحمد وأكثر فقهاء الأمصار إلى أن للخلطة تأثيرًا في الزكاة، فالخليطان يزكيان زكاة المالك الواحد، ثم اختلفوا: فقال الشافعي وأحمد: تؤثر في النصاب والواجب معًا، وقال مالك: تؤثر في الواجب فقط بشرط أن يملك كل واحد نصابًا. وذهب أبو حنيفة وأصحابه إلى أنه لا أثر للخلطة لا في النصاب ولا في الواجب، فيزكي كل واحد ماله وحده.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَلاَ يُجْمَعُ بَيْنَ مُتَفَرِّقٍ، وَلاَ يُفَرَّقُ بَيْنَ مُجْتَمِعٍ، خَشْيَةَ الصَّدَقَةِ","src":"رواه البخاري ١٤٥٠","pre":"عن أنس رضي الله عنه أن أبا بكر رضي الله عنه كتب له التي فرض رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1450,"id":"h1450"}]},{"t":"quote","text":"وَمَا كَانَ مِنْ خَلِيطَيْنِ فَإِنَّهُمَا يَتَرَاجَعَانِ بَيْنَهُمَا بِالسَّوِيَّةِ","src":"رواه البخاري ١٤٥١","pre":"وفيه:","links":[{"book":"mt_bukhari","num":1451,"id":"h1451"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَكْثَرُ الْفُقَهَاءِ عَلَى أَنَّ لِلْخُلْطَةِ تَأْثِيرًا فِي قَدْرِ الْوَاجِبِ مِنَ الزَّكَاةِ. وَاخْتَلَفَ الْقَائِلُونَ بِذَلِكَ، هَلْ لَهَا تَأْثِيرٌ فِي قَدْرِ النِّصَابِ أَمْ لَا؟ وَأَمَّا أَبُو حَنِيفَةَ وَأَصْحَابُهُ فَلَمْ يَرَوْا لِلْخُلْطَةِ تَأْثِيرًا، لَا فِي قَدْرِ الْوَاجِبِ وَلَا فِي قَدْرِ النِّصَابِ","src":"بداية المجتهد","loc":"٢/٢٥","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن للخلطة في الماشية تأثيرًا في الزكاة، فإذا اختلط اثنان أو أكثر في ماشية سائمة طوال الحول، واشتركت في المراح والمسرح والمحلب والفحل والراعي، فإنهما يزكيان زكاة المال الواحد؛ لحديث «ما كان من خليطين فإنهما يتراجعان بينهما بالسوية»، وهو قول الجمهور. فإذا كان لكل منهما ثلاثون شاة وجبت عليهما شاة واحدة بينهما بالحصص."},{"t":"p","text":"ولا يجوز التحايل بالجمع أو التفريق لإسقاط الزكاة أو تقليلها، كما نصّ الحديث. ومن أخذ بقول الحنفية فزكى كل واحد ماله منفردًا فله وجه من حمل الحديث على الشركة في الملك. وأما خلطة الأموال الأخرى كالنقود والشركات فالأمر فيها أن يزكي كل شريك حصته إذا بلغت نصابًا عند الجمهور."}],"refs":["البخاري ١٤٥٠","البخاري ١٤٥١","بداية المجتهد (٢/٢٥)","بداية المجتهد (٢/٢٦)"],"related":["نصاب الإبل والبقر والغنم، وما يؤخذ في زكاتها"],"alts":["الخلطة في الزكاة","زكاة الغنم المشتركة","الشركاء في الماشية"]},{"n":212,"bab":"الزكاة","sub":"النصاب","title":"نصاب الزروع والثمار، والعشر ونصف العشر، والخرص","q":"كم نصاب القمح والتمر بالكيلوغرام؟ وهل أخرج العشر أو نصف العشر؟ وهل أخصم تكاليف الزراعة؟ وما حكم تقدير الثمر وهو على النخل؟","short":"أجمعوا على أن الواجب فيما سُقي بماء السماء والأنهار العشر، وفيما سُقي بالآلة والنضح نصف العشر. وذهب الجمهور إلى اشتراط النصاب خمسة أوسق، وقال أبو حنيفة: لا نصاب في الحبوب والثمار، ففي قليلها وكثيرها العشر. وأجاز الجمهور الخرص في النخل والعنب، ومنعه أبو حنيفة وصاحباه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فِيمَا سَقَتِ السَّمَاءُ وَالْعُيُونُ أَوْ كَانَ عَثَرِيًّا الْعُشْرُ، وَمَا سُقِيَ بِالنَّضْحِ نِصْفُ الْعُشْرِ","src":"رواه البخاري ١٤٨٣","pre":"عن ابن عمر رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1483,"id":"h1483"}]},{"t":"quote","text":"لَيْسَ فِيمَا دُونَ خَمْسَةِ أَوْسُقٍ مِنَ التَّمْرِ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ مِنَ الْوَرِقِ صَدَقَةٌ","src":"رواه البخاري ١٤٥٩","pre":"وعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1459,"id":"h1459"}]},{"t":"quote","text":"إِذَا خَرَصْتُمْ فَخُذُوا وَدَعُوا الثُّلُثَ فَإِنْ لَمْ تَدَعُوا أَوْ تَجِدُوا الثُّلُثَ فَدَعُوا الرُّبُعَ","src":"رواه أبو داود ١٦٠٥","pre":"وعن سهل بن أبي حثمة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1605,"id":"h1605"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَجْمَعُوا عَلَى أَنَّ الْوَاجِبَ فِي الْحُبُوبِ: أَمَّا مَا سُقِيَ بِالسَّمَاءِ فَالْعُشْرُ، وَأَمَّا مَا سُقِيَ بِالنَّضْحِ فَنِصْفُ الْعُشْرِ لِثُبُوتِ ذَلِكَ عَنْهُ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ","src":"بداية المجتهد","loc":"٢/٢٧","pre":"قال ابن رشد:"},{"t":"quote","text":"اتفقوا على أن ما سقت العيون والسماء العشر، وفيما سقي بالنضح نصف العشر ويدخل في النضح ما سقي بالدولاب أو الناقة أو بالدلاء، ثم اختلف في رفع المؤنة. فقيل: العشر أو نصفه بعد رفع المؤنة، وقيل: العشر أو نصفه بلا رفع المؤنة، وإليه ذهب أبو حنيفة","src":"العرف الشذي","loc":"٢/١١٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن نصاب الحبوب والثمار خمسة أوسق، وهي ثلاثمائة صاع بصاع النبي ﷺ، وتقارب ستمائة واثني عشر كيلوغرامًا من القمح ونحوه، ويختلف قليلًا باختلاف ثقل الحب؛ لحديث «ليس فيما دون خمسة أوسق صدقة»، وهو حديث خاص يقضي على العموم. والواجب العشر فيما سُقي بلا مؤنة كالمطر والأنهار والعيون، ونصف العشر فيما سُقي بمؤنة كالمضخات والآلات، وثلاثة أرباع العشر إن سُقي بهما نصفين."},{"t":"p","text":"ولا تُخصم تكاليف البذر والسماد والحصاد من الزكاة على قول الجمهور؛ لأن الشارع خفف الواجب إلى نصف العشر مراعاة للمؤنة، وأجاز بعض العلماء خصم الديون التي أنفقت على الزرع. والخرص مشروع في النخل والعنب بعد بدو صلاحهما، يبعث الإمام خارصًا يقدر الثمر ويترك لأهله الثلث أو الربع؛ للحديث. ومن أخذ بقول أبي حنيفة فأخرج العشر من قليل الزرع وكثيره فهو أحوط."}],"refs":["البخاري ١٤٨٣","البخاري ١٤٥٩","أبو داود ١٦٠٥","بداية المجتهد (٢/٢٧)","العرف الشذي (٢/١١٥)","بداية المجتهد (٢/٢٨)","بداية المجتهد (١/٢٤٦-٢٧)"],"related":["ما تجب فيه الزكاة من الزروع والثمار، وزكاة الخضروات والفواكه والعسل"],"alts":["نصاب القمح","زكاة الزرع بالكيلو","العشر ونصف العشر","الخرص","خصم تكاليف الزراعة"]},{"n":213,"bab":"الزكاة","sub":"النصاب","title":"إخراج القيمة في الزكاة بدل العين","q":"هل يجوز أن أخرج زكاة الغنم أو القمح نقودًا بدل الشاة أو الحب؟ وهل يجوز إخراج زكاة النقود ملابس أو طعامًا للفقراء؟","short":"ذهب مالك والشافعي وأحمد في المشهور إلى أنه لا يجوز إخراج القيمة بدل المنصوص عليه في الزكوات. وذهب أبو حنيفة إلى جواز إخراج القيمة مطلقًا، سواء قدر على المنصوص أو لم يقدر، وأجازه أحمد في رواية للحاجة والمصلحة، واختاره ابن تيمية.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ بَلَغَتْ عِنْدَهُ مِنَ الإِبِلِ صَدَقَةُ الْجَذَعَةِ، وَلَيْسَتْ عِنْدَهُ جَذَعَةٌ وَعِنْدَهُ حِقَّةٌ، فَإِنَّهَا تُقْبَلُ مِنْهُ الْحِقَّةُ وَيَجْعَلُ مَعَهَا شَاتَيْنِ إِنِ اسْتَيْسَرَتَا لَهُ أَوْ عِشْرِينَ دِرْهَمًا، وَمَنْ بَلَغَتْ عِنْدَهُ صَدَقَةُ الْحِقَّةِ وَلَيْسَتْ عِنْدَهُ الْحِقَّةُ وَعِنْدَهُ الْجَذَعَةُ، فَإِنَّهَا تُقْبَلُ مِنْهُ الْجَذَعَةُ، وَيُعْطِيهِ الْمُصَدِّقُ عِشْرِينَ دِرْهَمًا أَوْ شَاتَيْنِ","src":"رواه البخاري ١٤٥٣","pre":"عن أنس رضي الله عنه في كتاب أبي بكر رضي الله عنه:","links":[{"book":"mt_bukhari","num":1453,"id":"h1453"}]},{"t":"p","text":"وذكر البخاري تعليقًا عن معاذ رضي الله عنه أنه قال لأهل اليمن: «ائتوني بعرض ثياب خميص أو لبيس في الصدقة مكان الشعير والذرة، أهون عليكم، وخير لأصحاب النبي ﷺ بالمدينة»."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَاخْتَلَفُوا هَلْ يَجُوزُ فِيهَا أَنْ يُخْرِجَ بَدَلَ الْعَيْنِ الْقَيِّمَةَ أَوْ لَا يَجُوزُ؟ فَقَالَ مَالِكٌ وَالشَّافِعِيُّ: لَا يَجُوزُ إِخْرَاجُ الْقِيَمِ فِي الزَّكَوَاتِ بَدَلَ الْمَنْصُوصِ عَلَيْهِ فِي الزَّكَوَاتِ، وَقَالَ أَبُو حَنِيفَةَ: يَجُوزُ، سَوَاءٌ قَدَرَ عَلَى الْمَنْصُوصِ عَلَيْهِ أَوْ لَمْ يَقْدِرْ","src":"بداية المجتهد","loc":"٢/٣٠","pre":"قال ابن رشد:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وقد عنون الإمام البخاري في صحيحه فقال: باب العرض في الزكاة وذكر الأثر عن معاذ ونصه (وقال طاووس: قال معاذ رضي الله عنه لأهل اليمن ائتوني بعرض ثياب خميص أو لبيس في الصدقة مكان الشعير والذرة أهون عليكم وخير لأصحاب رسول الله صلى الله عليه وسلم بالمدينة) واحتجاج البخاري بهذا يدل على قوة الخبر عنده كما قال الحافظ بن حجر في فتح الباري 4/ 54. ونقل الحافظ عن ابن رشيد قال: وافق البخاري في هذه المسألة الحنفية مع كثرة مخالفته لهم لكن قاده إلى ذلك الدليل","src":"يسألونك عن الزكاة","loc":"١/١٦٢","pre":"قال الدكتور حسام الدين عفانة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأصل إخراج الزكاة من جنس المال المزكى كما نصّ الشارع، فيُخرج من الغنم شاة، ومن الحب حبًّا، ومن النقود نقودًا؛ اتباعًا للنص، وخروجًا من الخلاف. ويجوز إخراج القيمة عند الحاجة أو المصلحة الراجحة للفقير، كأن يكون الفقير محتاجًا إلى النقود أكثر من العين، أو يشق على المالك إخراج العين، وهو قول أبي حنيفة، ورواية عن أحمد، واختيار ابن تيمية، وله شاهد من تجويز النبي ﷺ دفع الدراهم في جبران الأسنان، ومن فعل معاذ رضي الله عنه."},{"t":"p","text":"ولا يجوز لمن عليه زكاة النقود أن يشتري بها سلعًا أو ملابس ويدفعها إلى الفقير إلا إذا كان ذلك أنفع له وبرضاه، أو كان الفقير سفيهًا لا يحسن التصرف، والأولى دفع النقود إليه ليشتري حاجته بنفسه."}],"refs":["البخاري ١٤٥٣","بداية المجتهد (٢/٣٠)","يسألونك عن الزكاة (١/١٦٢)"],"related":["نصاب الإبل والبقر والغنم، وما يؤخذ في زكاتها","زكاة الفطر: مقدارها وجنسها، وإخراج القيمة فيها"],"alts":["إخراج الزكاة نقدا","القيمة في الزكاة","إخراج الزكاة عروضا"]},{"n":214,"bab":"الزكاة","sub":"وقت الزكاة","title":"اشتراط الحول، والمال المستفاد في أثناء الحول، وزكاة الراتب والأرباح","q":"أتقاضى راتبًا شهريًا وأدخر منه، فكيف أحسب الحول؟ هل لكل مبلغ حول مستقل؟ وإذا ربحت في تجارتي أو ورثت مالًا في أثناء السنة فهل أضمه إلى ما عندي؟","short":"يشترط الحول في زكاة الذهب والفضة والنقود والماشية وعروض التجارة عند جمهور العلماء، لثبوته عن الخلفاء الأربعة. واتفقوا على أن ربح التجارة ونتاج الماشية يتبع الأصل في الحول إذا كان الأصل نصابًا. واختلفوا في المال المستفاد من غير الربح كالهبة والميراث والراتب: فقال أبو حنيفة وأصحابه: يُضم إلى ما عنده من جنسه ويزكى بحوله، وقال مالك والشافعي وأحمد: يُستقبل به حول جديد.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ زَكَاةَ فِي مَالٍ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ","src":"رواه ابن ماجه ١٧٩٢","pre":"عن عائشة رضي الله عنها قالت: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_ibnmajah","num":1792,"id":"h1792"}]},{"t":"quote","text":"مَنِ اسْتَفَادَ مَالاً فَلاَ زَكَاةَ عَلَيْهِ حَتَّى يَحُولَ عَلَيْهِ الْحَوْلُ عِنْدَ رَبِّهِ","src":"رواه الترمذي ٦٣١","pre":"وعن ابن عمر رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":631,"id":"h631"}]},{"t":"p","text":"والصحيح في هذا الحديث أنه موقوف على ابن عمر رضي الله عنهما كما قال الترمذي."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا وَقْتُ الزَّكَاةِ: فَإِنَّ جُمْهُورَ الْفُقَهَاءِ يَشْتَرِطُونَ فِي وُجُوبِ الزَّكَاةِ فِي الذَّهَبِ وَالْفِضَّةِ وَالْمَاشِيَةِ الْحَوْلَ، لِثُبُوتِ ذَلِكَ عَنِ الْخُلَفَاءِ الْأَرْبَعَةِ، وَلِانْتِشَارِهِ فِي الصَّحَابَةِ - رَضِيَ اللَّهُ عَنْهُمْ -، وَلِانْتِشَارِ الْعَمَلِ بِهِ، وَلِاعْتِقَادِهِمْ أَنَّ مِثْلَ هَذَا الِانْتِشَارِ مِنْ غَيْرِ خِلَافٍ لَا يَجُوزُ أَنْ يَكُونَ إِلَّا عَنْ تَوْقِيفٍ","src":"بداية المجتهد","loc":"٢/٣٢","pre":"قال ابن رشد:"},{"t":"quote","text":"واعلم أن المال المستفاد على ثلاثة أنواع: أحدها: الربح الذي حصل بعد التجارة ويضم هذا المستفاد إلى الأصل اتفاقاً. وثانيها: أن يحصل المال من غير جنس المال الذي عنده، كمن كانت عنده إبل فحصلت له الشياه ولا يضم هذا إلى ما عنده من المال اتفاقاً، ومال التجارة جنس واحد والنقدان من جنس واحد والسوائم أجناس مختلفة. وثالثها: المال الذي حصل من جنس ما عنده لا من ربح بل بوصية أو توريث أو غيرهما هذا مختلف في الضم وعدمه، قال أبو حنيفة ومن تبعه: يضم وقال الحجازيون: لا يضم","src":"العرف الشذي","loc":"٢/١١١","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"نعم تجب الزكاة عليه إذا تم عليه الحول، لأن ما وجبت الزكاة في عينه لا يشترط له نية التجارة","src":"مجموع فتاوى ابن عثيمين","loc":"١٨/١٧٧","pre":"وسئل الشيخ محمد بن صالح العثيمين رحمه الله عن الرصيد المدخر من الراتب، فقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الحول شرط في زكاة النقود وعروض التجارة والماشية، لا في الزروع والثمار والمعادن والركاز. وربح التجارة ونتاج الماشية تابعان لأصلهما في الحول بالاتفاق إذا كان الأصل نصابًا."},{"t":"p","text":"وأما المال المستفاد كالراتب والهبة والميراث، فالأيسر والأحوط، وهو مذهب الحنفية، أن يضم المسلم كل ما يدخل عليه من النقود إلى ما عنده من النقود التي بلغت نصابًا، فيجعل لنفسه يومًا معلومًا في السنة يحسب فيه جميع ما عنده من النقود ويخرج زكاته، فيكون قد عجّل زكاة ما لم يحل عليه الحول، وهذا جائز عند الجمهور، وفيه تيسير على الناس وبعد عن الخطأ في حساب حول كل مبلغ. ومن أراد أن يجعل لكل مبلغ حوله المستقل، كما يقول الجمهور، فله ذلك."}],"refs":["ابن ماجه ١٧٩٢","الترمذي ٦٣١","بداية المجتهد (٢/٣٢)","بداية المجتهد (٢/٣٣)","العرف الشذي (٢/١١١)","مجموع فتاوى ابن عثيمين (١٨/١٧٧)"],"related":["تعجيل الزكاة قبل الحول، وتأخيرها بعد وجوبها","نصاب الذهب والفضة والأوراق النقدية، وضم أحدهما إلى الآخر"],"alts":["زكاة الراتب الشهري","حول الزكاة","زكاة المال المستفاد","زكاة الميراث","زكاة المدخرات"]},{"n":215,"bab":"الزكاة","sub":"وقت الزكاة","title":"تعجيل الزكاة قبل الحول، وتأخيرها بعد وجوبها","q":"هل يجوز أن أخرج زكاة مالي قبل تمام الحول لحاجة الفقراء في رمضان؟ وهل يجوز أن أؤخرها بعد وجوبها لأوزعها شيئًا فشيئًا أو أنتظر فقيرًا قريبًا؟","short":"أجاز أبو حنيفة والشافعي وأحمد تعجيل الزكاة قبل الحول إذا ملك النصاب، ومنعه مالك. وأما تأخيرها بعد وجوبها: فالجمهور على وجوب إخراجها على الفور عند التمكن، ويأثم بتأخيرها بلا عذر، وأجاز بعضهم التأخير اليسير لمصلحة كانتظار قريب محتاج أو من هو أحوج.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ الْعَبَّاسَ، سَأَلَ النَّبِيَّ صلى الله عليه وسلم فِي تَعْجِيلِ صَدَقَتِهِ قَبْلَ أَنْ تَحِلَّ فَرَخَّصَ لَهُ فِي ذَلِكَ","src":"رواه أبو داود ١٦٢٤","pre":"عن علي رضي الله عنه:","links":[{"book":"mt_abudawud","num":1624,"id":"h1624"}]},{"t":"quote","text":"بَعَثَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عُمَرَ عَلَى الصَّدَقَةِ، فَقِيلَ: مَنَعَ ابْنُ جَمِيلٍ، وَخَالِدُ بْنُ الْوَلِيدِ، وَالْعَبَّاسُ عَمُّ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ «مَا يَنْقِمُ ابْنُ جَمِيلٍ إِلَّا أَنَّهُ كَانَ فَقِيرًا فَأَغْنَاهُ اللهُ، وَأَمَّا خَالِدٌ فَإِنَّكُمْ تَظْلِمُونَ خَالِدًا، قَدِ احْتَبَسَ أَدْرَاعَهُ وَأَعْتَادَهُ فِي سَبِيلِ اللهِ، وَأَمَّا الْعَبَّاسُ فَهِيَ عَلَيَّ، وَمِثْلُهَا مَعَهَا»","src":"رواه مسلم ٩٨٣","pre":"وعن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_muslim","num":983,"id":"h983"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَهِيَ جَوَازُ إِخْرَاجِ الزَّكَاةِ قَبْلَ الْحَوْلِ -: فَإِنَّ مَالِكًا مَنَعَ ذَلِكَ، وَجَوَّزَهُ أَبُو حَنِيفَةَ وَالشَّافِعِيُّ","src":"بداية المجتهد","loc":"٢/٣٦","pre":"قال ابن رشد:"},{"t":"quote","text":"يصح إذا كان مالك نصاب ثم له شروط وإن جواز التعجيل فلأنه إذا ملك النصاب فحصل نفس الوجوب","src":"العرف الشذي","loc":"٢/١٣٨","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر جواز تعجيل الزكاة قبل تمام الحول لسنة أو سنتين إذا ملك النصاب، لا سيما للمصلحة، كحاجة الفقراء أو موسم كرمضان؛ لحديث تعجيل العباس صدقته، وهو قول الجمهور. فإن نقص المال عن النصاب في آخر الحول كان ما أخرجه صدقة تطوع."},{"t":"p","text":"وأما تأخيرها بعد وجوبها فلا يجوز إلا لعذر أو مصلحة راجحة قصيرة، كانتظار قريب فقير أو من هو أشد حاجة، أو تعذر الوصول إلى المستحقين؛ لأن الزكاة حق واجب للفقراء متعلق بالمال. ولا يجوز تقسيطها على أشهر بعد وجوبها إلا لمصلحة الفقير نفسه، كأن يكون سفيهًا فيُعطى شيئًا فشيئًا، والأولى عزلها كلها وتسليمها لمن يتولى ذلك."}],"refs":["أبو داود ١٦٢٤","مسلم ٩٨٣","بداية المجتهد (٢/٣٦)","العرف الشذي (٢/١٣٨)"],"related":["اشتراط الحول، والمال المستفاد في أثناء الحول، وزكاة الراتب والأرباح"],"alts":["تعجيل الزكاة","إخراج الزكاة في رمضان","تأخير الزكاة","تقسيط الزكاة"]},{"n":216,"bab":"الزكاة","sub":"مصارف الزكاة","title":"مصارف الزكاة الثمانية، وهل يجب تعميمها؟","q":"لمن تُدفع الزكاة؟ وهل يجب أن أوزع زكاتي على الأصناف الثمانية كلها، أو يجوز أن أعطيها كلها لفقير واحد؟","short":"أجمعوا على أن مصارف الزكاة الثمانية الذين ذكرهم الله في آية التوبة، ولا يجوز صرفها لغيرهم. واختلفوا في التعميم: فقال أبو حنيفة ومالك وأحمد: يجوز صرفها إلى صنف واحد، بل إلى شخص واحد، بحسب الحاجة، وقال الشافعي: يجب تعميم الأصناف الموجودين، ويُعطى من كل صنف ثلاثة فأكثر.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"إِنَّمَا ٱلصَّدَقَـٰتُ لِلْفُقَرَآءِ وَٱلْمَسَـٰكِينِ وَٱلْعَـٰمِلِينَ عَلَيْهَا وَٱلْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِى ٱلرِّقَابِ وَٱلْغَـٰرِمِينَ وَفِى سَبِيلِ ٱللَّهِ وَٱبْنِ ٱلسَّبِيلِ ۖ فَرِيضَةً مِّنَ ٱللَّهِ ۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","ref":"التوبة: ٦٠"},{"t":"quote","text":"فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ","src":"رواه البخاري ١٤٩٦","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال لمعاذ:","links":[{"book":"mt_bukhari","num":1496,"id":"h1496"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا عَدَدُهُمْ: فَهُمُ الثَّمَانِيَةُ الَّذِينَ نَصَّ اللَّهُ عَلَيْهِمْ فِي قَوْله تَعَالَى: {إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ} التوبة: 60 الْآيَةَ","src":"بداية المجتهد","loc":"٢/٣٦","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الزكاة لا تُصرف إلا في الأصناف الثمانية التي حصرها الله تعالى بـ«إنما»: الفقراء، والمساكين، والعاملين عليها، والمؤلفة قلوبهم، وفي الرقاب، والغارمين، وفي سبيل الله، وابن السبيل. ويجوز أن تُدفع إلى صنف واحد منهم أو إلى شخص واحد إذا كانت تسد حاجته، وهو قول الجمهور؛ لأن ذكر الأصناف لبيان المصارف لا لوجوب التعميم، ولقوله ﷺ: «فترد على فقرائهم»، فذكر صنفًا واحدًا. والأفضل أن يراعي المزكي الأحوج فالأحوج، والأقارب المستحقين."},{"t":"tanbih","items":[{"t":"p","text":"لا تجوز الزكاة في بناء المساجد والمدارس والمستشفيات وحفر الآبار وتكفين الموتى عند جمهور العلماء؛ لأنها ليست تمليكًا لأحد الأصناف، وإنما تُصرف هذه المشاريع من الصدقات العامة والأوقاف."}]}],"refs":["البخاري ١٤٩٦","بداية المجتهد (٢/٣٦)","بداية المجتهد (٢/٣٧)"],"related":["من هو الفقير والمسكين؟ وحد الغنى المانع من أخذ الزكاة، وقدر ما يعطى","المصارف المختلف فيها: في سبيل الله، والمؤلفة قلوبهم، والغارمون، وابن السبيل"],"alts":["لمن تدفع الزكاة","أصناف الزكاة الثمانية","إعطاء الزكاة لشخص واحد","الزكاة في بناء المساجد"]},{"n":217,"bab":"الزكاة","sub":"مصارف الزكاة","title":"من هو الفقير والمسكين؟ وحد الغنى المانع من أخذ الزكاة، وقدر ما يعطى","q":"رجل له راتب لا يكفيه هو وعياله، فهل يجوز أن يأخذ من الزكاة؟ وما حد الغنى الذي يمنع أخذ الزكاة؟ وكم يُعطى الفقير؟ وهل يُعطى القوي القادر على الكسب؟","short":"ذهب أبو حنيفة إلى أن الغني المانع من أخذ الزكاة هو مالك النصاب الفاضل عن حاجته الأصلية. وذهب مالك والشافعي وأحمد إلى أن الغنى ما تحصل به الكفاية، فمن لم يجد كفايته وكفاية عياله فهو فقير يجوز له الأخذ ولو ملك نصابًا. وأجمعوا على أنها لا تحل للقوي المكتسب عند الجمهور. وأجاز مالك والشافعي أن يعطى الفقير ما يغنيه ولو كان نصابًا، وكره أبو حنيفة أن يعطى الواحد نصابًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ وَلاَ لِذِي مِرَّةٍ سَوِيٍّ","src":"رواه أبو داود ١٦٣٤","pre":"عن عبد الله بن عمرو رضي الله عنهما عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":1634,"id":"h1634"}]},{"t":"quote","text":"لاَ تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ إِلاَّ لِخَمْسَةٍ لِغَازٍ فِي سَبِيلِ اللَّهِ أَوْ لِعَامِلٍ عَلَيْهَا أَوْ لِغَارِمٍ أَوْ لِرَجُلٍ اشْتَرَاهَا بِمَالِهِ أَوْ لِرَجُلٍ كَانَ لَهُ جَارٌ مِسْكِينٌ فَتُصُدِّقَ عَلَى الْمِسْكِينِ فَأَهْدَاهَا الْمِسْكِينُ لِلْغَنِيِّ","src":"رواه أبو داود ١٦٣٥","pre":"وعن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1635,"id":"h1635"}]},{"t":"quote","text":"يَا قَبِيصَةُ إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثَةٍ رَجُلٍ، تَحَمَّلَ حَمَالَةً، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَهَا، ثُمَّ يُمْسِكُ، وَرَجُلٌ أَصَابَتْهُ جَائِحَةٌ اجْتَاحَتْ مَالَهُ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ - وَرَجُلٌ أَصَابَتْهُ فَاقَةٌ حَتَّى يَقُومَ ثَلَاثَةٌ مِنْ ذَوِي الْحِجَا مِنْ قَوْمِهِ: لَقَدْ أَصَابَتْ فُلَانًا فَاقَةٌ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ - فَمَا سِوَاهُنَّ مِنَ الْمَسْأَلَةِ يَا قَبِيصَةُ سُحْتًا يَأْكُلُهَا صَاحِبُهَا سُحْتًا","src":"رواه مسلم ١٠٤٤","pre":"وعن قبيصة بن مخارق رضي الله عنه أن رسول الله ﷺ قال له:","links":[{"book":"mt_muslim","num":1044,"id":"h1044"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا حَدُّ الْغِنَى الَّذِي يَمْنَعُ مِنَ الصَّدَقَةِ: فَذَهَبَ الشَّافِعِيُّ إِلَى أَنَّ الْمَانِعَ مِنَ الصَّدَقَةِ هُوَ أَقَلُّ مَا يَنْطَلِقُ عَلَيْهِ الِاسْمُ.","src":"بداية المجتهد","loc":"٢/٣٨","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الفقير والمسكين كلاهما من لا يجد كفايته وكفاية من يعولهم من الطعام والكسوة والسكن والعلاج والتعليم ونحوها من غير إسراف، والفقير أشد حاجة عند الجمهور. فمن كان له راتب أو دخل لا يكفيه هو وعياله جاز أن يأخذ من الزكاة تمام كفايته، ولو ملك نصابًا لا يكفيه، وهو قول الجمهور؛ لحديث قبيصة: «حتى يصيب قوامًا من عيش». والأحوط مراعاة قول الحنفية بأن يكون ما يملكه من المال الفاضل عن حاجاته الأصلية دون النصاب."},{"t":"p","text":"ولا تحل الزكاة للغني ولا للقوي القادر على الكسب المناسب الذي يجد عملًا، فإن لم يجد عملًا فهو من أهلها. ويُعطى الفقير من الزكاة ما يكفيه لسنة، ويجوز أن يعطى ما يغنيه عن السؤال، كأدوات حرفة أو رأس مال تجارة يسيرة، وهو أنفع له."}],"refs":["أبو داود ١٦٣٤","أبو داود ١٦٣٥","مسلم ١٠٤٤","بداية المجتهد (٢/٣٨)","بداية المجتهد (٢/٣٨-٣٩)","بداية المجتهد (٢/٣٩)"],"related":["مصارف الزكاة الثمانية، وهل يجب تعميمها؟","دفع الزكاة إلى الأقارب والزوج، ولآل النبي ﷺ"],"alts":["من هو الفقير في الزكاة","حد الغنى","إعطاء الزكاة لصاحب الراتب","كم يعطى الفقير من الزكاة"]},{"n":218,"bab":"الزكاة","sub":"مصارف الزكاة","title":"دفع الزكاة إلى الأقارب والزوج، ولآل النبي ﷺ","q":"هل يجوز أن أعطي زكاة مالي لأخي الفقير أو عمي أو خالتي؟ وهل تعطي المرأة زكاتها لزوجها الفقير؟ وهل يُعطى السيد الهاشمي من الزكاة؟","short":"أجمعوا على أنه لا يجوز دفع الزكاة إلى من تجب على المزكي نفقته من الأصول والفروع، كالوالدين والأولاد، ولا إلى الزوجة. وأجازوا دفعها إلى سائر الأقارب الفقراء كالإخوة والأعمام والأخوال إذا لم تجب نفقتهم، وهي أفضل. واختلفوا في دفع الزوجة زكاتها إلى زوجها الفقير: فأجازه الشافعي وصاحبا أبي حنيفة وأحمد في رواية، ومنعه أبو حنيفة. وأجمعوا على تحريم الزكاة على بني هاشم في الجملة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنْتُ فِي الْمَسْجِدِ فَرَأَيْتُ النَّبِيَّ صلى الله عليه وسلم فَقَالَ «تَصَدَّقْنَ وَلَوْ مِنْ حُلِيِّكُنَّ». وَكَانَتْ زَيْنَبُ تُنْفِقُ عَلَى عَبْدِ اللَّهِ وَأَيْتَامٍ فِي حَجْرِهَا، قَالَ فَقَالَتْ لِعَبْدِ اللَّهِ سَلْ رَسُولَ اللَّهِ صلى الله عليه وسلم أَيَجْزِي عَنِّي أَنْ أُنْفِقَ عَلَيْكَ وَعَلَى أَيْتَامِي فِي حَجْرِي مِنَ الصَّدَقَةِ فَقَالَ سَلِي أَنْتِ رَسُولَ اللَّهِ صلى الله عليه وسلم. فَانْطَلَقْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم. فَوَجَدْتُ امْرَأَةً مِنَ الأَنْصَارِ عَلَى الْبَابِ، حَاجَتُهَا مِثْلُ حَاجَتِي، فَمَرَّ عَلَيْنَا بِلاَلٌ فَقُلْنَا سَلِ النَّبِيَّ صلى الله عليه وسلم أَيَجْزِي عَنِّي أَنْ أُنْفِقَ عَلَى زَوْجِي وَأَيْتَامٍ لِي فِي حَجْرِي وَقُلْنَا لاَ تُخْبِرْ بِنَا. فَدَخَلَ فَسَأَلَهُ فَقَالَ «مَنْ هُمَا». قَالَ زَيْنَبُ قَالَ «أَىُّ الزَّيَانِبِ». قَالَ امْرَأَةُ عَبْدِ اللَّهِ. قَالَ «نَعَمْ لَهَا أَجْرَانِ أَجْرُ الْقَرَابَةِ وَأَجْرُ الصَّدَقَةِ»","src":"رواه البخاري ١٤٦٦","pre":"عن زينب امرأة عبد الله بن مسعود رضي الله عنهما قالت:","links":[{"book":"mt_bukhari","num":1466,"id":"h1466"}]},{"t":"quote","text":"الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَهِيَ عَلَى ذِي الرَّحِمِ ثِنْتَانِ صَدَقَةٌ وَصِلَةٌ","src":"رواه الترمذي ٦٥٨","pre":"وعن سلمان بن عامر رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":658,"id":"h658"}]},{"t":"quote","text":"إِنَّ الصَّدَقَةَ لَا تَنْبَغِي لِآلِ مُحَمَّدٍ إِنَّمَا هِيَ أَوْسَاخُ النَّاسِ","src":"رواه مسلم ١٠٧٢","pre":"وعن عبد المطلب بن ربيعة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1072,"id":"h1072"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"قال أبو حنيفة: لا تتأدى الزكاة بدفعها إلى من له قرابة الولادة أو الزوجية، وأما النافلة ففيها أجران أجر القرابة وأجر الصدقة","src":"العرف الشذي","loc":"٢/١٢٦","pre":"قال الكشميري:"},{"t":"quote","text":"المسألة متفق عليها، وأهل البيت هم آل عليّ وحارث وجعفر وعقيل والحارث عمه عليه الصلاة والسلام والثلاثة بنو أبي طالب، ثم في كتبنا أن الهاشمي لو سعى أي عمل السعاية فلا يأخذ من الزكاة، ويجوز أخذه من الوقف بلا خلاف","src":"العرف الشذي","loc":"٢/١٢٥","pre":"وقال في آل البيت:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن دفع الزكاة إلى الأقارب الفقراء الذين لا تجب على المزكي نفقتهم، كالإخوة والأخوات والأعمام والعمات والأخوال والخالات وأولادهم، جائز بل أفضل؛ لأنها صدقة وصلة. ولا يجوز دفعها إلى الأصول (الوالدين والأجداد) ولا إلى الفروع (الأولاد وأولادهم) ولا إلى الزوجة؛ لأن نفقتهم واجبة عليه، فكأنه يدفعها إلى نفسه، إلا أن يكونوا غارمين في دين لا يلزمه قضاؤه فيعطيهم لقضائه."},{"t":"p","text":"ويجوز للمرأة أن تعطي زكاتها لزوجها الفقير على الأظهر؛ لحديث زينب امرأة ابن مسعود، فإن النبي ﷺ أقرها وقال: «لها أجران»، وهو قول صاحبي أبي حنيفة والشافعي ورواية عن أحمد، ومن أخذ بقول أبي حنيفة في المنع فقد احتاط، وحمل الحديث على صدقة التطوع."},{"t":"p","text":"ولا تحل الزكاة لآل النبي ﷺ من بني هاشم؛ لقوله ﷺ: «إن الصدقة لا تنبغي لآل محمد، إنما هي أوساخ الناس»، ويجوز لهم أخذ صدقة التطوع والوقف والهدية. وأجاز بعض العلماء المتأخرين إعطاءهم من الزكاة إذا مُنعوا حقهم من الخمس واشتدت حاجتهم، وهو رواية عن أبي حنيفة ذكرها الطحاوي، والأحوط أن يُعطوا من غير الزكاة."}],"refs":["البخاري ١٤٦٦","الترمذي ٦٥٨","مسلم ١٠٧٢","العرف الشذي (٢/١٢٦)","العرف الشذي (٢/١٢٥)"],"related":["من هو الفقير والمسكين؟ وحد الغنى المانع من أخذ الزكاة، وقدر ما يعطى"],"alts":["الزكاة للأقارب","زكاة الزوجة لزوجها","الزكاة للأخ الفقير","الزكاة للسادة","الزكاة لبني هاشم"]},{"n":219,"bab":"الزكاة","sub":"مصارف الزكاة","title":"المصارف المختلف فيها: في سبيل الله، والمؤلفة قلوبهم، والغارمون، وابن السبيل","q":"هل يدخل في سهم «في سبيل الله» طلب العلم والدعوة إلى الله والحج؟ وهل بقي سهم المؤلفة قلوبهم؟ ومن هو الغارم الذي يُعطى؟","short":"ذهب الأئمة الأربعة إلى أن «في سبيل الله» هم الغزاة المتطوعون في الجهاد، وأدخل أحمد في رواية الحج، وألحق كثير من المعاصرين الدعوة إلى الله ونشر العلم بالجهاد. وقال مالك: لا مؤلفة اليوم، وقال الشافعي وأبو حنيفة في رواية وأحمد: حقهم باق إذا رأى الإمام ذلك، والمشهور عند الحنفية سقوطه. والغارم عند الحنفية المدين العاجز عن الوفاء، وعند الجمهور يدخل فيه من تحمل حمالة لإصلاح ذات البين.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ إِلاَّ لِخَمْسَةٍ لِغَازٍ فِي سَبِيلِ اللَّهِ أَوْ لِعَامِلٍ عَلَيْهَا أَوْ لِغَارِمٍ أَوْ لِرَجُلٍ اشْتَرَاهَا بِمَالِهِ أَوْ لِرَجُلٍ كَانَ لَهُ جَارٌ مِسْكِينٌ فَتُصُدِّقَ عَلَى الْمِسْكِينِ فَأَهْدَاهَا الْمِسْكِينُ لِلْغَنِيِّ","src":"رواه أبو داود ١٦٣٥","pre":"عن أبي سعيد الخدري رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1635,"id":"h1635"}]},{"t":"quote","text":"رَجُلٍ، تَحَمَّلَ حَمَالَةً، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَهَا، ثُمَّ يُمْسِكُ، وَرَجُلٌ أَصَابَتْهُ جَائِحَةٌ اجْتَاحَتْ مَالَهُ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ - وَرَجُلٌ أَصَابَتْهُ فَاقَةٌ حَتَّى يَقُومَ ثَلَاثَةٌ مِنْ ذَوِي الْحِجَا مِنْ قَوْمِهِ: لَقَدْ أَصَابَتْ فُلَانًا فَاقَةٌ، فَحَلَّتْ لَهُ الْمَسْأَلَةُ حَتَّى يُصِيبَ قِوَامًا مِنْ عَيْشٍ - أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ - فَمَا سِوَاهُنَّ مِنَ الْمَسْأَلَةِ يَا قَبِيصَةُ سُحْتًا يَأْكُلُهَا صَاحِبُهَا سُحْتًا","src":"رواه مسلم ١٠٤٤","pre":"وعن قبيصة بن مخارق رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1044,"id":"h1044"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الثَّانِيَةُ: فَهَلِ الْمُؤَلَّفَةُ قُلُوبُهُمْ حَقُّهُمْ بَاقٍ إِلَى الْيَوْمِ أَمْ لَا؟ فَقَالَ مَالِكٌ: لَا مُؤَلَّفَةَ الْيَوْمَ. وَقَالَ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ: بَلْ حَقُّ الْمُؤَلَّفَةِ بَاقٍ إِلَى الْيَوْمِ إِذَا رَأَى الْإِمَامُ ذَلِكَ، وَهُمُ الَّذِينَ يَتَأَلَّفُهُمُ الْإِمَامُ عَلَى الْإِسْلَامِ","src":"بداية المجتهد","loc":"٢/٣٧","pre":"قال ابن رشد:"},{"t":"quote","text":"الغارم عند أبي حنيفة المديون، وعند الشافعي من تحمل غرامة الصلح وإطفاء ما بين الرجلين أو القبيلتين، وفي اللغة كلا المعنيين ثابت بل يجيء الغارم بمعنى الدائن أيضاً","src":"العرف الشذي","loc":"٢/١٢٤","pre":"وقال الكشميري في الغارم:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن سهم «في سبيل الله» للمجاهدين في سبيل الله لإعلاء كلمته، ويدخل فيه عند كثير من المحققين ما كان في معناه من الجهاد بالعلم والدعوة إلى الله ورد الشبهات عن الإسلام، إذا كان القائمون بها محتاجين، والأحوط ألا يتوسع فيه إلى كل وجوه البر. وسهم المؤلفة قلوبهم باق عند الحاجة إليه، يصرفه ولي الأمر أو الجهات الموثوقة لتأليف من يُرجى إسلامه أو تقوية إيمان الحديث العهد بالإسلام؛ لأن الأصل بقاء الحكم."},{"t":"p","text":"والغارم يشمل المدين الذي استدان لنفسه في مباح وعجز عن الوفاء، ومن استدان لإصلاح ذات البين ولو كان غنيًّا. وابن السبيل هو المسافر المنقطع الذي نفدت نفقته، فيُعطى ما يوصله إلى بلده ولو كان غنيًّا في بلده."}],"refs":["أبو داود ١٦٣٥","مسلم ١٠٤٤","بداية المجتهد (٢/٣٧)","بداية المجتهد (٢/٣٩)","العرف الشذي (٢/١٢٤)"],"related":["مصارف الزكاة الثمانية، وهل يجب تعميمها؟"],"alts":["في سبيل الله في الزكاة","الزكاة لطالب العلم","المؤلفة قلوبهم","الزكاة للمدين","ابن السبيل"]},{"n":220,"bab":"الزكاة","sub":"مصارف الزكاة","title":"نقل الزكاة من بلد إلى بلد آخر","q":"أعيش في بلد غربي وأهلي فقراء في بلدي الأصلي، فهل يجوز أن أرسل زكاتي إليهم؟ وهل يجوز إرسال الزكاة إلى البلاد المنكوبة؟","short":"ذهب الجمهور، ومنهم مالك والشافعي وأحمد، إلى أن الأصل تفريق الزكاة في بلد المال، وكرهوا نقلها أو منعوه إلا لضرورة أو حاجة. وأجاز أبو حنيفة نقلها مع الكراهة، إلا إلى قريب محتاج أو إلى قوم أحوج من أهل بلده فلا كراهة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَأَخْبِرْهُمْ أَنَّ اللَّهَ قَدْ فَرَضَ عَلَيْهِمْ صَدَقَةً تُؤْخَذُ مِنْ أَغْنِيَائِهِمْ فَتُرَدُّ عَلَى فُقَرَائِهِمْ","src":"رواه البخاري ١٤٩٦","pre":"عن ابن عباس رضي الله عنهما أن النبي ﷺ قال لمعاذ:","links":[{"book":"mt_bukhari","num":1496,"id":"h1496"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَقَالَ الشَّافِعِيُّ: هُوَ الْغَازِي جَارُ الصَّدَقَةِ، وَإِنَّمَا اشْتَرَطَ جَارَ الصَّدَقَةِ لِأَنَّ؛ عِنْدَ أَكْثَرِهِمْ أَنَّهُ لَا يَجُوزُ تَنْقِيلُ الصَّدَقَةِ مِنْ بَلَدٍ إِلَى بَلَدٍ إِلَّا مِنْ ضَرُورَةٍ","src":"بداية المجتهد","loc":"٢/٣٩","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الأصل أن تُوزع الزكاة في البلد الذي فيه المال؛ لقوله ﷺ: «تؤخذ من أغنيائهم فترد على فقرائهم»، ولتعلق أطماع فقراء البلد بها. ويجوز نقلها إلى بلد آخر لمصلحة راجحة، كأن يكون فيه أقارب محتاجون، أو قوم أشد حاجة كأهل المجاعات والكوارث والحروب، أو لا يوجد في بلده مستحق، وهو قول أبي حنيفة واختيار كثير من المحققين، وقد كان الصحابة رضي الله عنهم ينقلون الصدقات إلى المدينة."},{"t":"p","text":"فمن كان في بلد غير مسلم أو بلد قلّ فيه الفقراء المسلمون، فإرسال زكاته إلى أهله الفقراء أو إلى المسلمين المحتاجين في بلاد أخرى أولى، ويتحرى أن تصل إلى مستحقيها عبر جهات موثوقة."}],"refs":["البخاري ١٤٩٦","بداية المجتهد (٢/٣٩)"],"related":["مصارف الزكاة الثمانية، وهل يجب تعميمها؟","دفع الزكاة إلى الأقارب والزوج، ولآل النبي ﷺ"],"alts":["نقل الزكاة","إرسال الزكاة إلى بلد آخر","زكاة المغترب"]},{"n":221,"bab":"الزكاة","sub":"زكاة الفطر","title":"حكم زكاة الفطر، وعلى من تجب، وعمن يخرجها الرجل","q":"هل زكاة الفطر واجبة على الفقير الذي لا يملك نصابًا؟ وهل يخرجها الرجل عن زوجته وأولاده الكبار ووالديه؟ وهل تخرج عن الجنين؟","short":"جمهور العلماء على أن زكاة الفطر فرض واجب على كل مسلم، ذكر أو أنثى، صغير أو كبير. وقال الحنفية: هي واجبة (بالمعنى الذي هو دون الفرض عندهم). واختلفوا في شرط الغنى: فقال مالك والشافعي وأحمد: تجب على من عنده ما يفضل عن قوته وقوت عياله يوم العيد وليلته، وقال أبو حنيفة: لا تجب إلا على مالك النصاب الفاضل عن حاجته الأصلية. ويخرجها الرجل عن نفسه وعمن تلزمه نفقته عند الجمهور، ومنهم الزوجة، وقال أبو حنيفة: تخرجها الزوجة عن نفسها، ويخرج الأب عن أولاده الصغار الذين لا مال لهم. ولا تجب عن الجنين بالإجماع، واستحب أحمد إخراجها عنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى الْعَبْدِ وَالْحُرِّ، وَالذَّكَرِ وَالأُنْثَى، وَالصَّغِيرِ وَالْكَبِيرِ مِنَ الْمُسْلِمِينَ، وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلاَةِ","src":"رواه البخاري ١٥٠٣","pre":"عن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1503,"id":"h1503"}]},{"t":"quote","text":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِينِ مَنْ أَدَّاهَا قَبْلَ الصَّلاَةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ وَمَنْ أَدَّاهَا بَعْدَ الصَّلاَةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ","src":"رواه أبو داود ١٦٠٩","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":1609,"id":"h1609"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا زَكَاةُ الْفِطْرِ: فَإِنَّ الْجُمْهُورَ عَلَى أَنَّهَا فَرْضٌ، وَذَهَبَ بَعْضُ الْمُتَأَخِّرِينَ مِنْ أَصْحَابِ مَالِكٍ إِلَى أَنَّهَا سُنَّةٌ، وَبِهِ قَالَ أَهْلُ الْعِرَاقِ. وَقَالَ قَوْمٌ: هِيَ مَنْسُوخَةٌ بِالزَّكَاةِ","src":"بداية المجتهد","loc":"٢/٤٠","pre":"قال ابن رشد:"},{"t":"quote","text":"أما الأول أي على من تجب فعلى مالك النصاب ولو غير نام، وأما عند الشافعي: فعلى من له فاضل من قوت يوم وليلة","src":"العرف الشذي","loc":"٢/١٣٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن زكاة الفطر واجبة على كل مسلم يجد يوم العيد وليلته ما يزيد على قوته وقوت من تلزمه نفقته، ولو لم يملك نصابًا، وهو قول الجمهور؛ لعموم قول ابن عمر رضي الله عنهما: «فرض رسول الله ﷺ زكاة الفطر... على العبد والحر، والذكر والأنثى، والصغير والكبير من المسلمين»، فلم يشترط غنى، ولأنها طهرة للصائم وزكاة للبدن. ومن أخذ بقول الحنفية في اشتراط النصاب فله وجه، والأحوط أن يخرجها كل من قدر عليها."},{"t":"p","text":"ويخرجها المسلم عن نفسه وعن أولاده الصغار الذين لا مال لهم، وعن زوجته عند الجمهور؛ لأنه ينفق عليها، فإن أخرجتها هي من مالها أجزأ ذلك عند الجميع. والأولاد الكبار القادرون والوالدان الموسران يخرجون عن أنفسهم، فإن أخرجها عنهم بإذنهم جاز. ولا تجب عن الجنين، ويستحب إخراجها عنه إذا أتم أربعة أشهر، لفعل عثمان رضي الله عنه. ومن ولد بعد غروب شمس آخر يوم من رمضان، أو أسلم بعده، ففي وجوبها عنه خلاف ينبني على وقت الوجوب."}],"refs":["البخاري ١٥٠٣","أبو داود ١٦٠٩","بداية المجتهد (٢/٤٠)","بداية المجتهد (٢/٤١)","العرف الشذي (٢/١٣٥)"],"related":["زكاة الفطر: مقدارها وجنسها، وإخراج القيمة فيها","وقت إخراج زكاة الفطر، ومن تُصرف إليه"],"alts":["حكم زكاة الفطر","صدقة الفطر","زكاة الفطر على الفقير","زكاة الفطر عن الزوجة","زكاة الفطر عن الجنين","فطرة رمضان"]},{"n":222,"bab":"الزكاة","sub":"زكاة الفطر","title":"زكاة الفطر: مقدارها وجنسها، وإخراج القيمة فيها","q":"كم مقدار زكاة الفطر عن الشخص الواحد؟ ومن أي الأطعمة تخرج: الأرز أو الدقيق أو التمر؟ وهل يجوز إخراجها نقودًا كما يفعل كثير من الناس؟","short":"اتفقوا على أن الواجب من التمر والشعير صاع عن كل شخص. واختلفوا في البر (القمح): فقال مالك والشافعي وأحمد: صاع، وقال أبو حنيفة وأصحابه: نصف صاع. والجمهور على أنها تخرج من غالب قوت البلد من الطعام. واختلفوا في إخراج القيمة: فمنعه مالك والشافعي وأحمد، وأجازه أبو حنيفة وأصحابه، وهو قول عمر بن عبد العزيز والحسن البصري والثوري.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كُنَّا نُخْرِجُ زَكَاةَ الْفِطْرِ صَاعًا مِنْ طَعَامٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ أَقِطٍ، أَوْ صَاعًا مِنْ زَبِيبٍ","src":"رواه البخاري ١٥٠٦","pre":"عن أبي سعيد الخدري رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1506,"id":"h1506"}]},{"t":"quote","text":"كُنَّا نُعْطِيهَا فِي زَمَانِ النَّبِيِّ صلى الله عليه وسلم صَاعًا مِنْ طَعَامٍ، أَوْ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ، أَوْ صَاعًا مِنْ زَبِيبٍ، فَلَمَّا جَاءَ مُعَاوِيَةُ وَجَاءَتِ السَّمْرَاءُ قَالَ أُرَى مُدًّا مِنْ هَذَا يَعْدِلُ مُدَّيْنِ","src":"رواه البخاري ١٥٠٨","pre":"وعن أبي سعيد رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1508,"id":"h1508"}]},{"t":"quote","text":"فَأَمَّا أَنَا فَلَا أَزَالُ أُخْرِجُهُ كَمَا كُنْتُ أُخْرِجُهُ، أَبَدًا مَا عِشْتُ","src":"رواه مسلم ٩٨٥","pre":"وفي رواية مسلم: قال أبو سعيد:","links":[{"book":"mt_muslim","num":985,"id":"h985-2"}]},{"t":"quote","text":"صَاعٌ مِنْ بُرٍّ أَوْ قَمْحٍ عَلَى كُلِّ اثْنَيْنِ صَغِيرٍ أَوْ كَبِيرٍ حُرٍّ أَوْ عَبْدٍ ذَكَرٍ أَوْ أُنْثَى","src":"رواه أبو داود ١٦١٩","pre":"وعن ثعلبة بن عبد الله بن أبي صعير عن أبيه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":1619,"id":"h1619"}]},{"t":"quote","text":"صَاعًا مِنْ تَمْرٍ أَوْ شَعِيرٍ أَوْ نِصْفَ صَاعٍ مِنْ قَمْحٍ عَلَى كُلِّ حُرٍّ أَوْ مَمْلُوكٍ ذَكَرٍ أَوْ أُنْثَى صَغِيرٍ أَوْ كَبِيرٍ فَلَمَّا قَدِمَ عَلِيٌّ - رضى الله عنه - رَأَى رُخْصَ السِّعْرِ قَالَ قَدْ أَوْسَعَ اللَّهُ عَلَيْكُمْ فَلَوْ جَعَلْتُمُوهُ صَاعًا مِنْ كُلِّ شَىْءٍ","src":"رواه أبو داود ١٦٢٢","pre":"وعن ابن عباس رضي الله عنهما أنه قال في خطبته بالبصرة: فرض رسول الله ﷺ هذه الصدقة","links":[{"book":"mt_abudawud","num":1622,"id":"h1622"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا مِمَّاذَا تَجِبُ؟ فَإِنَّ قَوْمًا ذَهَبُوا إِلَى أَنَّهَا تَجِبُ إِمَّا مِنَ الْبُرِّ أَوِ التَّمْرِ أَوِ الشَّعِيرِ أَوِ الزَّبِيبِ أَوِ الْأَقِطِ، وَأَنَّ ذَلِكَ عَلَى التَّخْيِيرِ لِلَّذِي تَجِبُ عَلَيْهِ، وَقَوْمٌ ذَهَبُوا إِلَى أَنَّ الْوَاجِبَ عَلَيْهِ هُوَ غَالِبُ قُوتِ الْبَلَدِ، أَوْ قُوتُ الْمُكَلَّفِ إِذَا لَمْ يَقْدِرْ عَلَى قُوتِ الْبَلَدِ، وَهُوَ الَّذِي حَكَاهُ عَبْدُ الْوَهَّابِ عَنِ الْمَذْهَبِ","src":"بداية المجتهد","loc":"٢/٤٢","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الشافعية: إن في صدقة الفطر صاعاً من كل شيء، وفي كفارة اليمين مدين من كل شيء، وقال أبو حنيفة رحمه الله: إن في الصدقة صاعاً من بعض الأشياء ونصف صاع من بعض الأشياء مثل الحنطة","src":"العرف الشذي","loc":"٢/١٣٦","pre":"وقال الكشميري:"},{"t":"quote","text":"وأما كم تجب؟ فالصاع عند أبي حنيفة في بعض الأشياء ونصف صاع في بعض الأشياء، وقال الشافعي: يجب الصاع من كل شيء، وأما مم تجب؟ فبأن يعطي الحنطة أو الشعير أو الأقط أو قيمتها","src":"العرف الشذي","loc":"٢/١٣٥","pre":"وقال في جنسها:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"ولا يجوز إخراج زكاة الفطر نقودا؛ لأن الأدلة الشرعية قد دلت على وجوب إخراجها طعاما","src":"فتاوى اللجنة الدائمة","loc":"٩/٣٧٩","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"quote","text":"وجمهور الفقهاء المالكية والشافعية والحنابلة يرون وجوب إخراج الأعيان في صدقة الفطر كالتمر والشعير والزبيب أو من غالب قوت الناس ولا يجيزون إخراج القيمة أي إخراج النقود. ومذهب الحنفية جواز إخراج القيمة ونقل هذا القول عن جماعة من أهل العلم منهم الحسن البصري وعمر بن عبد العزيز والثوري","src":"يسألونك عن الزكاة","loc":"١/١٦١","pre":"وقال الدكتور حسام الدين عفانة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن زكاة الفطر صاع عن كل شخص من غالب قوت أهل البلد، كالأرز والقمح والتمر والشعير والزبيب ونحوها مما يقتاته الناس. والصاع النبوي أربعة أمداد، ويقدر بالوزن بنحو كيلوين ونصف إلى ثلاثة كيلوغرامات تقريبًا بحسب نوع الطعام، والاحتياط إخراج ثلاثة كيلوغرامات من الأرز ونحوه."},{"t":"p","text":"وأما القمح فمن أخرج منه نصف صاع أخذ بقول الحنفية ومعاوية ومن وافقه من الصحابة، ولهم فيه أحاديث وآثار، ومن أخرج صاعًا كاملًا فقد أخذ بالأحوط وفعل أبي سعيد رضي الله عنه، وهو أولى إن تيسر."},{"t":"p","text":"وأما إخراجها نقودًا: فالأصل والأفضل إخراجها طعامًا كما فرضها النبي ﷺ وأخرجها الصحابة رضي الله عنهم، مع وجود الدراهم والدنانير في زمانهم. ومن أخرج القيمة أخذ بقول الحنفية ومن وافقهم، ولقولهم وجه معتبر، لا سيما إذا كانت النقود أنفع للفقير وأيسر له في قضاء حاجاته، كما في كثير من البلدان اليوم، فلا ينكر على من أخذ به. والأحسن أن يُعطى الفقير ما هو أنفع له من الطعام أو القيمة، ومن قدر على إخراجها طعامًا دون مشقة ولم يكن الفقير محتاجًا إلى النقد فالطعام أولى، خروجًا من الخلاف."}],"refs":["البخاري ١٥٠٦","البخاري ١٥٠٨","مسلم ٩٨٥","أبو داود ١٦١٩","أبو داود ١٦٢٢","بداية المجتهد (٢/٤٢)","بداية المجتهد (٢/٤٣)","العرف الشذي (٢/١٣٦)","العرف الشذي (٢/١٣٥)","فتاوى اللجنة الدائمة (٩/٣٧٩)","يسألونك عن الزكاة (١/١٦١)"],"related":["إخراج القيمة في الزكاة بدل العين","حكم زكاة الفطر، وعلى من تجب، وعمن يخرجها الرجل","وقت إخراج زكاة الفطر، ومن تُصرف إليه"],"alts":["مقدار زكاة الفطر","كم زكاة الفطر بالكيلو","زكاة الفطر نقدا","إخراج زكاة الفطر مالا","زكاة الفطر من الأرز","الصاع النبوي"]},{"n":223,"bab":"الزكاة","sub":"زكاة الفطر","title":"وقت إخراج زكاة الفطر، ومن تُصرف إليه","q":"متى يبدأ وقت إخراج زكاة الفطر؟ وهل يجوز إخراجها في أول رمضان؟ وما حكم من أخرها إلى ما بعد صلاة العيد؟ ولمن تعطى؟ وهل يجوز دفعها إلى جمعية خيرية؟","short":"اختلفوا في وقت وجوبها: فقال الشافعي وأحمد ومالك في رواية: تجب بغروب الشمس من آخر يوم من رمضان، وقال أبو حنيفة ومالك في رواية: تجب بطلوع الفجر يوم العيد. واتفقوا على استحباب إخراجها قبل صلاة العيد. وأجاز الجمهور تقديمها قبل العيد بيوم أو يومين، وأجاز الشافعي تقديمها من أول رمضان، وأجاز أبو حنيفة تقديمها ولو قبل رمضان. واتفقوا على أنها لا تسقط بالتأخير، بل تبقى دينًا يجب قضاؤه. والجمهور على أنها تصرف لفقراء المسلمين ومساكينهم، وأجاز أبو حنيفة دفعها إلى فقراء أهل الذمة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى الْعَبْدِ وَالْحُرِّ، وَالذَّكَرِ وَالأُنْثَى، وَالصَّغِيرِ وَالْكَبِيرِ مِنَ الْمُسْلِمِينَ، وَأَمَرَ بِهَا أَنْ تُؤَدَّى قَبْلَ خُرُوجِ النَّاسِ إِلَى الصَّلاَةِ","src":"رواه البخاري ١٥٠٣","pre":"عن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1503,"id":"h1503"}]},{"t":"quote","text":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِينِ مَنْ أَدَّاهَا قَبْلَ الصَّلاَةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ وَمَنْ أَدَّاهَا بَعْدَ الصَّلاَةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ","src":"رواه أبو داود ١٦٠٩","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":1609,"id":"h1609"}]},{"t":"quote","text":"وَكَانَ ابْنُ عُمَرَ ـ رضى الله عنهما ـ يُعْطِيهَا الَّذِينَ يَقْبَلُونَهَا، وَكَانُوا يُعْطُونَ قَبْلَ الْفِطْرِ بِيَوْمٍ أَوْ يَوْمَيْنِ","src":"رواه البخاري ١٥١١","pre":"وقال نافع:","links":[{"book":"mt_bukhari","num":1511,"id":"h1511"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا مَتَى تَجِبُ زَكَاةُ الْفِطْرِ؟ فَإِنَّهُمُ اتَّفَقُوا عَلَى أَنَّهَا تَجِبُ فِي آخِرِ رَمَضَانَ لِحَدِيثِ ابْنِ عُمَرَ: «فَرَضَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - زَكَاةَ الْفِطْرِ مِنْ رَمَضَانَ» .","src":"بداية المجتهد","loc":"٢/٤٤","pre":"قال ابن رشد:"},{"t":"quote","text":"وأما متى تجب؟ فعند أبي حنيفة بعد صبح يوم العيد، وعند الشافعي بعد غروب ذكاء اخر رمضان","src":"العرف الشذي","loc":"٢/١٣٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن أفضل وقت لإخراج زكاة الفطر صباح يوم العيد قبل الخروج إلى الصلاة؛ لأمر النبي ﷺ بأدائها قبل خروج الناس إلى الصلاة. ويجوز تقديمها قبل العيد بيوم أو يومين؛ لفعل ابن عمر رضي الله عنهما والصحابة، وهو قول الجمهور. ومن أخرجها قبل ذلك من أول رمضان أخذ بقول الشافعي، ومن قدمها أكثر أخذ بقول الحنفية، ولا سيما إذا دفعها إلى جمعية أو جهة موثوقة توصلها إلى الفقراء قبل العيد، فالأمر فيه سعة، والأحوط ألا تصل إلى الفقير قبل العيد بأكثر من يوم أو يومين إلا لمصلحة."},{"t":"p","text":"ولا يجوز تأخيرها عن صلاة العيد بلا عذر، فمن أخرها أثم ووجب عليه قضاؤها، ولا تسقط عنه بالتأخير؛ لقوله ﷺ: «من أداها قبل الصلاة فهي زكاة مقبولة، ومن أداها بعد الصلاة فهي صدقة من الصدقات». ومن نسيها أو لم يعلم بالعيد إلا متأخرًا أخرجها حين يذكر ولا إثم عليه."},{"t":"p","text":"وتصرف زكاة الفطر إلى فقراء المسلمين ومساكينهم؛ لأنها «طعمة للمساكين». ويجوز أن يعطي الفقير الواحد فطرة جماعة، وأن توزع فطرة الواحد على أكثر من فقير. ويجوز دفعها إلى جمعية خيرية أو شخص موثوق وكيلًا عن المزكي، بشرط أن يوصلها إلى المستحقين في وقتها."}],"refs":["البخاري ١٥٠٣","أبو داود ١٦٠٩","البخاري ١٥١١","بداية المجتهد (٢/٤٤)","العرف الشذي (٢/١٣٥)"],"related":["حكم زكاة الفطر، وعلى من تجب، وعمن يخرجها الرجل","زكاة الفطر: مقدارها وجنسها، وإخراج القيمة فيها","تعجيل الزكاة قبل الحول، وتأخيرها بعد وجوبها"],"alts":["وقت زكاة الفطر","إخراج زكاة الفطر بعد العيد","تقديم زكاة الفطر","لمن تعطى زكاة الفطر","زكاة الفطر للجمعيات الخيرية"]},{"n":224,"bab":"الصيام","sub":"فرض الصيام","title":"فرض صيام رمضان، وفضله، وعلى من يجب","q":"ما حكم صيام شهر رمضان؟ وعلى من يجب؟ ومتى يؤمر الصبي بالصيام؟","short":"صيام شهر رمضان ركن من أركان الإسلام، فرض بالكتاب والسنة والإجماع، فرض في السنة الثانية من الهجرة. ويجب على كل مسلم بالغ عاقل مقيم صحيح قادر، خالٍ من الحيض والنفاس. ومن جحد وجوبه كفر، ومن تركه تكاسلًا فقد أتى كبيرة عظيمة. ولا يجب على الصبي، لكن يؤمر به إذا أطاقه ليعتاده.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ","ref":"البقرة: ١٨٣"},{"t":"quote","text":"بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ","src":"رواه البخاري ٨","pre":"عن ابن عمر رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":8,"id":"h8"}]},{"t":"quote","text":"مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","src":"رواه البخاري ٣٨","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":38,"id":"h38"}]},{"t":"quote","text":"أَرْسَلَ النَّبِيُّ صلى الله عليه وسلم غَدَاةَ عَاشُورَاءَ إِلَى قُرَى الأَنْصَارِ «مَنْ أَصْبَحَ مُفْطِرًا فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ، وَمَنْ أَصْبَحَ صَائِمًا فَلْيَصُمْ». قَالَتْ فَكُنَّا نَصُومُهُ بَعْدُ، وَنُصَوِّمُ صِبْيَانَنَا، وَنَجْعَلُ لَهُمُ اللُّعْبَةَ مِنَ الْعِهْنِ، فَإِذَا بَكَى أَحَدُهُمْ عَلَى الطَّعَامِ أَعْطَيْنَاهُ ذَاكَ، حَتَّى يَكُونَ عِنْدَ الإِفْطَارِ","src":"رواه البخاري ١٩٦٠","pre":"وعن الربيع بنت معوذ رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1960,"id":"h1960"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا صَوْمُ شَهْرِ رَمَضَانَ: فَهُوَ وَاجِبٌ بِالْكِتَابِ وَالسُّنَّةِ وَالْإِجْمَاعِ. أَمَّا الْكِتَابُ: فَقَوْلُهُ تَعَالَى: {يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ} البقرة: 183 . وَأَمَّا السُّنَّةُ: فَفِي قَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ» وَذَكَرَ فِيهَا الصَّوْمَ.","src":"بداية المجتهد","loc":"٢/٤٥","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"صيام رمضان فرض على كل مسلم بالغ عاقل مقيم قادر على الصيام، والمرأة الحائض والنفساء لا تصوم وتقضي. والمريض والمسافر رخص الله لهما في الفطر والقضاء، والعاجز عجزًا دائمًا يطعم عن كل يوم مسكينًا، وسيأتي تفصيل ذلك."},{"t":"p","text":"ويستحب أن يؤمر الصبي بالصيام إذا أطاقه ليتمرن عليه، كما كان الصحابة رضي الله عنهم يصوّمون صبيانهم ويلهونهم باللعب حتى يأتي الإفطار. ومن بلغ في أثناء الشهر أو أسلم الكافر لزمه صيام ما بقي، ولا يلزمه قضاء ما مضى."}],"refs":["البخاري ٨","البخاري ٣٨","البخاري ١٩٦٠","بداية المجتهد (٢/٤٥)","بداية المجتهد (٢/٤٦)"],"related":["ثبوت دخول شهر رمضان وخروجه: الرؤية وإكمال العدة والحساب الفلكي","النية في الصيام: تبييتها وتعيينها، وهل تكفي نية واحدة للشهر؟"],"alts":["حكم صيام رمضان","فرض الصيام","صيام الصبي","على من يجب الصوم","فضل صيام رمضان"]},{"n":225,"bab":"الصيام","sub":"ثبوت الشهر","title":"ثبوت دخول شهر رمضان وخروجه: الرؤية وإكمال العدة والحساب الفلكي","q":"كيف يثبت دخول شهر رمضان وخروجه؟ وهل يجوز الاعتماد على الحساب الفلكي؟ وما حكم رؤية الهلال بالمراصد والمناظير؟","short":"أجمع العلماء على أن الشهر العربي يكون تسعة وعشرين أو ثلاثين، وأن الاعتبار في دخول رمضان وخروجه بالرؤية، فإن لم ير الهلال أكملت عدة شعبان ثلاثين يومًا، وهذا قول الأئمة الأربعة وجمهور العلماء. ونقل عن بعض السلف كمطرف بن الشخير وعن ابن سريج من الشافعية اعتبار الحساب عند الغيم، ولم يعتد به الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صُومُوا لِرُؤْيَتِهِ، وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ غُبِّيَ عَلَيْكُمْ فَأَكْمِلُوا عِدَّةَ شَعْبَانَ ثَلاَثِينَ","src":"رواه البخاري ١٩٠٩","pre":"عن أبي هريرة رضي الله عنه قال: قال النبي ﷺ:","links":[{"book":"mt_bukhari","num":1909,"id":"h1909"}]},{"t":"quote","text":"إِنَّا أُمَّةٌ أُمِّيَّةٌ، لاَ نَكْتُبُ وَلاَ نَحْسُبُ الشَّهْرُ هَكَذَا وَهَكَذَا","src":"رواه البخاري ١٩١٣","pre":"وعن ابن عمر رضي الله عنهما عن النبي ﷺ أنه قال:","links":[{"book":"mt_bukhari","num":1913,"id":"h1913"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"فَأَمَّا طَرَفَا هَذَا الزَّمَانِ: فَإِنَّ الْعُلَمَاءَ أَجْمَعُوا عَلَى أَنَّ الشَّهْرَ الْعَرَبِيَّ يَكُونُ تِسْعًا وَعِشْرِينَ وَيَكُونُ ثَلَاثِينَ، وَعَلَى أَنَّ الِاعْتِبَارَ فِي تَحْدِيدِ شَهْرِ رَمَضَانَ إِنَّمَا هُوَ الرُّؤْيَةُ، لِقَوْلِهِ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ -: «صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ» وَعَنَى بِالرُّؤْيَةِ أَوَّلَ ظُهُورِ الْقَمَرِ بَعْدَ الزَّوَالِ","src":"بداية المجتهد","loc":"٢/٤٦","pre":"قال ابن رشد:"},{"t":"quote","text":"الحساب لا يعول عليه في رؤية هلال رمضان ولا غيره من الأحكام الشرعية بإجماع أهل العلم، حكى الإجماع في ذلك شيخ الإسلام أبو العباس أحمد بن عبد الحليم بن تيمية رحمه الله","src":"مجموع فتاوى ابن باز","loc":"١٥/٦٨","pre":"وقال الشيخ ابن باز:"},{"t":"quote","text":"أما الآلات فظاهر الأدلة الشرعية عدم تكليف الناس بالتماس الهلال بها، بل تكفي رؤية العين. ولكن من طالع الهلال بها وجزم بأنه رآه بواسطتها بعد غروب الشمس وهو مسلم عدل، فلا أعلم مانعا من العمل برؤيته الهلال؛ لأنها من رؤية العين لا من الحساب","src":"مجموع فتاوى ابن باز","loc":"١٥/٦٩","pre":"وقال في الرؤية بالآلات:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن دخول رمضان وخروجه يثبت برؤية الهلال، أو بإكمال عدة شعبان ثلاثين يومًا إن لم ير، وكذلك خروجه برؤية هلال شوال أو بإكمال رمضان ثلاثين؛ لقوله ﷺ: «صوموا لرؤيته، وأفطروا لرؤيته، فإن غُبِّي عليكم فأكملوا عدة شعبان ثلاثين»، فعلّق الحكم بالرؤية لا بالحساب، وهو قول الأئمة الأربعة."},{"t":"p","text":"ولا يُعتمد على الحساب الفلكي في إثبات الشهر، ولكن لا بأس بالاستعانة به في تحري مواضع الرؤية وأوقاتها، وبرد الشهادة التي يقطع الحساب القطعي باستحالتها عند بعض المحققين. والرؤية بالمراصد والمناظير رؤية بصرية معتبرة إذا كان الرائي عدلًا. وعلى المسلم أن يصوم ويفطر مع جماعة المسلمين في بلده وفق ما تعلنه الجهة المختصة بإثبات الهلال، ولا ينفرد عنهم."}],"refs":["البخاري ١٩٠٩","البخاري ١٩١٣","بداية المجتهد (٢/٤٦)","مجموع فتاوى ابن باز (١٥/٦٨)","مجموع فتاوى ابن باز (١٥/٦٩)","بداية المجتهد (٢/٤٧)"],"related":["عدد الشهود في رؤية هلال رمضان وشوال، ومن رأى الهلال وحده","اختلاف المطالع: هل يلزم أهل البلاد كلها الصوم برؤية بلد واحد؟","صوم يوم الشك، وتقدم رمضان بصوم يوم أو يومين"],"alts":["رؤية الهلال","الحساب الفلكي في رمضان","إثبات دخول رمضان","إكمال شعبان ثلاثين","رؤية الهلال بالمرصد"]},{"n":226,"bab":"الصيام","sub":"ثبوت الشهر","title":"عدد الشهود في رؤية هلال رمضان وشوال، ومن رأى الهلال وحده","q":"هل يكفي شاهد واحد في رؤية هلال رمضان؟ وكم يشترط في هلال شوال؟ ومن رأى الهلال وحده وردّت شهادته، هل يصوم أو يفطر وحده؟","short":"قال الشافعي في المشهور عنه وأحمد: يثبت هلال رمضان بشهادة عدل واحد، ولا يثبت هلال شوال إلا بشاهدين. وقال مالك: لا يثبت هلال رمضان ولا شوال إلا بشاهدين. وقال أبو حنيفة: إن كانت السماء مغيمة قُبل في رمضان واحد، وإن كانت صاحية لم يقبل إلا جمع كثير يقع العلم بخبرهم. وأجمعوا، إلا عطاء، على أن من رأى هلال رمضان وحده لزمه الصوم. واختلفوا فيمن رأى هلال شوال وحده: فقال الجمهور: لا يفطر، وقال الشافعي: يفطر سرًّا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"تَرَاءَى النَّاسُ الْهِلاَلَ فَأَخْبَرْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم أَنِّي رَأَيْتُهُ فَصَامَهُ وَأَمَرَ النَّاسَ بِصِيَامِهِ","src":"رواه أبو داود ٢٣٤٢","pre":"عن ابن عمر رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":2342,"id":"h2342"}]},{"t":"quote","text":"جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنِّي رَأَيْتُ الْهِلاَلَ - قَالَ الْحَسَنُ فِي حَدِيثِهِ يَعْنِي رَمَضَانَ - فَقَالَ «أَتَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ» . قَالَ نَعَمْ . قَالَ «أَتَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ» . قَالَ نَعَمْ . قَالَ «يَا بِلاَلُ أَذِّنْ فِي النَّاسِ فَلْيَصُومُوا غَدًا»","src":"رواه أبو داود ٢٣٤٠","pre":"وعن ابن عباس رضي الله عنهما قال:","links":[{"book":"mt_abudawud","num":2340,"id":"h2340"}]},{"t":"quote","text":"الصَّوْمُ يَوْمَ تَصُومُونَ وَالْفِطْرُ يَوْمَ تُفْطِرُونَ وَالأَضْحَى يَوْمَ تُضَحُّونَ","src":"رواه الترمذي ٦٩٧","pre":"وعن أبي هريرة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":697,"id":"h697"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا طَرِيقُ الْخَبَرِ: فَإِنَّهُمُ اخْتَلَفُوا فِي عَدَدِ الْمُخْبِرِينَ الَّذِينَ يَجِبُ قَبُولُ خَبَرِهِمْ عَنِ الرُّؤْيَةِ فِي صِفَتِهِمْ: فَأَمَّا مَالِكٌ فَقَالَ: إِنَّهُ لَا يَجُوزُ أَنْ يُصَامَ وَلَا يُفْطَرَ بِأَقَلِّ مِنْ شَهَادَةِ رَجُلَيْنِ عَدْلَيْنِ.","src":"بداية المجتهد","loc":"٢/٤٨","pre":"قال ابن رشد:"},{"t":"quote","text":"وفي متوننا أن هلال رمضان يثبت بشهادة رجل يوم الغيم، وأما يوم الصحو فلا بد من جماعة يقع بهم علم اليقين، وأما هلال الفطر يوم الغيم فيكفي فيه شهادة رجلين وفي الصحو يجب جماعة","src":"العرف الشذي","loc":"٢/١٤٥","pre":"وقال الكشميري:"},{"t":"quote","text":"واعلم أن في بلادنا التي ليست حكومة الإسلام فيها فالحكم فيها: صوموا بقول ثقة وأفطروا بقول ثقتين، ولا ينبغي لمفتي العصر المشي على ما هو شأن قضاة دار الإسلام من الشهادة وغيرها","src":"العرف الشذي","loc":"٢/١٤٧","pre":"وقال:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن هلال رمضان يثبت بشهادة مسلم عدل واحد؛ لحديث ابن عمر رضي الله عنهما أن النبي ﷺ صام وأمر الناس بالصيام بخبره وحده، ولا يثبت هلال شوال إلا بشهادة عدلين؛ احتياطًا للعبادة، وهو قول الشافعي وأحمد، وقريب منه ما ذكره الكشميري من العمل في البلاد التي لا قضاء شرعي فيها."},{"t":"p","text":"ومن رأى هلال رمضان وحده فرُدّت شهادته صام على قول الجمهور، والأقرب أن يصوم مع الناس ويفطر مع الناس؛ لقوله ﷺ: «الصوم يوم تصومون، والفطر يوم تفطرون». ومن رأى هلال شوال وحده لم يفطر علانية، بل يصوم مع الناس على قول الجمهور، دفعًا للفرقة والتهمة."}],"refs":["أبو داود ٢٣٤٢","أبو داود ٢٣٤٠","الترمذي ٦٩٧","بداية المجتهد (٢/٤٨)","العرف الشذي (٢/١٤٥)","العرف الشذي (٢/١٤٧)"],"related":["ثبوت دخول شهر رمضان وخروجه: الرؤية وإكمال العدة والحساب الفلكي","اختلاف المطالع: هل يلزم أهل البلاد كلها الصوم برؤية بلد واحد؟"],"alts":["شهادة رؤية الهلال","رؤية هلال شوال","من رأى الهلال وحده","كم شاهدا لرؤية الهلال"]},{"n":227,"bab":"الصيام","sub":"ثبوت الشهر","title":"اختلاف المطالع: هل يلزم أهل البلاد كلها الصوم برؤية بلد واحد؟","q":"إذا رئي الهلال في بلد، فهل يجب على المسلمين في البلاد الأخرى أن يصوموا معهم؟ ونحن في بلد غير إسلامي، فمع من نصوم؟","short":"قال الحنفية والمالكية في المشهور والحنابلة: إذا ثبتت الرؤية في بلد لزم سائر البلاد، ولا عبرة باختلاف المطالع. وقال الشافعية: لكل بلد رؤيتهم إذا اختلفت المطالع، وهو رواية المدنيين عن مالك، ونقل ابن رشد الإجماع على اعتبار اختلاف المطالع في البلاد المتباعدة جدًّا. واتفقوا على أن حكم الحاكم يرفع الخلاف.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صُومُوا لِرُؤْيَتِهِ، وَأَفْطِرُوا لِرُؤْيَتِهِ، فَإِنْ غُبِّيَ عَلَيْكُمْ فَأَكْمِلُوا عِدَّةَ شَعْبَانَ ثَلاَثِينَ","src":"رواه البخاري ١٩٠٩","pre":"عن أبي هريرة رضي الله عنه قال: قال النبي ﷺ:","links":[{"book":"mt_bukhari","num":1909,"id":"h1909"}]},{"t":"quote","text":"أَنَّ أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ، بَعَثَتْهُ إِلَى مُعَاوِيَةَ بِالشَّامِ، قَالَ: فَقَدِمْتُ الشَّامَ، فَقَضَيْتُ حَاجَتَهَا، وَاسْتُهِلَّ عَلَيَّ رَمَضَانُ وَأَنَا بِالشَّامِ، فَرَأَيْتُ الْهِلَالَ لَيْلَةَ الْجُمُعَةِ، ثُمَّ قَدِمْتُ الْمَدِينَةَ فِي آخِرِ الشَّهْرِ، فَسَأَلَنِي عَبْدُ اللهِ بْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، ثُمَّ ذَكَرَ الْهِلَالَ فَقَالَ: مَتَى رَأَيْتُمُ الْهِلَالَ؟ فَقُلْتُ: رَأَيْنَاهُ لَيْلَةَ الْجُمُعَةِ، فَقَالَ: أَنْتَ رَأَيْتَهُ؟ فَقُلْتُ: نَعَمْ، وَرَآهُ النَّاسُ، وَصَامُوا وَصَامَ مُعَاوِيَةُ، فَقَالَ: «لَكِنَّا رَأَيْنَاهُ لَيْلَةَ السَّبْتِ، فَلَا نَزَالُ نَصُومُ حَتَّى نُكْمِلَ ثَلَاثِينَ، أَوْ نَرَاهُ، فَقُلْتُ: أَوَ لَا تَكْتَفِي بِرُؤْيَةِ مُعَاوِيَةَ وَصِيَامِهِ؟ فَقَالَ: لَا، هَكَذَا أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ»","src":"رواه مسلم ١٠٨٧","pre":"عن كريب:","links":[{"book":"mt_muslim","num":1087,"id":"h1087"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَإِذَا قُلْنَا: إِنَّ الرُّؤْيَةَ تَثْبُتُ بِالْخَبَرِ فِي حَقِّ مَنْ لَمْ يَرَهُ، فَهَلْ يَتَعَدَّى ذَلِكَ مِنْ بَلَدٍ إِلَى بَلَدٍ؟ - أَعْنِي: هَلْ يَجِبُ عَلَى أَهْلِ بَلَدٍ مَا إِذَا لَمْ يَرَوْهُ أَنْ يَأْخُذُوا فِي ذَلِكَ بِرُؤْيَةِ بَلَدٍ آخَرَ أَمْ لِكُلِّ بَلَدٍ رُؤْيَةٌ؟","src":"بداية المجتهد","loc":"٢/٥٠","pre":"قال ابن رشد:"},{"t":"quote","text":"وكنت قطعت بما قال الزيلعي ثم رأيت في قواعد ابن رشد إجماعاً على اعتبار اختلاف المطالع في البلدان النائية، وأما تحديد القرب والنائي فمحمول إلى المبتلى به ليس له حد معين وذكر الشافعية في التحديد شيئاً","src":"العرف الشذي","loc":"٢/١٤٥","pre":"وقال الكشميري:"},{"t":"quote","text":"الصواب اعتماد الرؤية وعدم اعتبار اختلاف المطالع في ذلك؛ لأن النبي صلى الله عليه وسلم أمر باعتماد الرؤية ولم يفصل في ذلك","src":"مجموع فتاوى ابن باز","loc":"١٥/٨٣","pre":"وقال الشيخ ابن باز:"},{"t":"quote","text":"وهذا قول له حظه من القوة، وقد رأى القول به أعضاء مجلس هيئة كبار العلماء في المملكة العربية السعودية جمعا بين الأدلة","src":"مجموع فتاوى ابن باز","loc":"٢/٤٩٧","pre":"وقال في القول باعتبار المطالع:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"المسألة اجتهادية، ولكل من القولين دليل معتبر: فمن أخذ بعموم «صوموا لرؤيته» جعل رؤية بلد رؤية للجميع، ومن أخذ بحديث كريب وفعل ابن عباس رضي الله عنهما اعتبر اختلاف المطالع. والأظهر أن البلاد المتقاربة التي تتحد مطالعها يلزم بعضها رؤية بعض، وأما المتباعدة جدًّا فلكل منها رؤيته، كما نقل ابن رشد الإجماع عليه."},{"t":"p","text":"والذي يرفع الخلاف في الواقع أن يصوم المسلم مع أهل بلده وجماعة المسلمين فيه، تبعًا لما تعلنه الجهة الشرعية المسؤولة عن إثبات الهلال، فإن حكم الحاكم يرفع الخلاف، وقد قال ﷺ: «الصوم يوم تصومون، والفطر يوم تفطرون». ومن كان في بلد غير إسلامي صام مع المراكز والجمعيات الإسلامية التي يجتمع عليها أكثر المسلمين هناك، سواء أخذت برؤية محلية أو برؤية أقرب بلد إسلامي أو بلد الحرمين، والمهم ألا يتفرق المسلمون في البلد الواحد."}],"refs":["البخاري ١٩٠٩","مسلم ١٠٨٧","بداية المجتهد (٢/٥٠)","العرف الشذي (٢/١٤٥)","مجموع فتاوى ابن باز (١٥/٨٣)","مجموع فتاوى ابن باز (٢/٤٩٧)"],"related":["ثبوت دخول شهر رمضان وخروجه: الرؤية وإكمال العدة والحساب الفلكي","عدد الشهود في رؤية هلال رمضان وشوال، ومن رأى الهلال وحده"],"alts":["اختلاف المطالع","توحيد الصوم","الصيام في البلاد الغربية","رؤية بلد واحد","الصوم مع السعودية"]},{"n":228,"bab":"الصيام","sub":"ثبوت الشهر","title":"صوم يوم الشك، وتقدم رمضان بصوم يوم أو يومين","q":"ما هو يوم الشك؟ وهل يجوز صومه احتياطًا لرمضان؟ ومن كانت عادته صيام الاثنين فوافق آخر شعبان، فهل يصومه؟","short":"يوم الشك هو يوم الثلاثين من شعبان إذا تحدث الناس برؤية الهلال ولم تثبت، أو حال دونه غيم عند بعضهم. وقد كره جمهور العلماء صومه بنية رمضان، ونهى النبي ﷺ عن تقدم رمضان بصوم يوم أو يومين إلا لمن وافق عادة له. وذهب أحمد في المشهور عنه إلى صومه احتياطًا إذا حال دون الهلال غيم أو قتر، وهو قول ابن عمر رضي الله عنهما. واستحب الحنفية للخواص صومه بنية النفل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ يَتَقَدَّمَنَّ أَحَدُكُمْ رَمَضَانَ بِصَوْمِ يَوْمٍ أَوْ يَوْمَيْنِ، إِلاَّ أَنْ يَكُونَ رَجُلٌ كَانَ يَصُومُ صَوْمَهُ فَلْيَصُمْ ذَلِكَ الْيَوْمَ","src":"رواه البخاري ١٩١٤","pre":"عن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":1914,"id":"h1914"}]},{"t":"quote","text":"مَنْ صَامَ الْيَوْمَ الَّذِي يَشُكُّ فِيهِ النَّاسُ فَقَدْ عَصَى أَبَا الْقَاسِمِ صلى الله عليه وسلم","src":"رواه الترمذي ٦٨٦","pre":"وعن عمار بن ياسر رضي الله عنه قال:","links":[{"book":"mt_tirmidhi","num":686,"id":"h686"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَذَهَبَ ابْنُ عُمَرَ إِلَى أَنَّهُ إِنْ كَانَ الْمُغَمَّى عَلَيْهِ هِلَالَ أَوَّلِ الشَّهْرِ صِيمَ الْيَوْمُ الثَّانِي وَهُوَ الَّذِي يُعْرَفُ بِيَوْمِ الشَّكِّ","src":"بداية المجتهد","loc":"٢/٤٦","pre":"قال ابن رشد:"},{"t":"quote","text":"وفي الهداية أن تقديم رمضان بيوم أو يومين بنية رمضان مكروه تحريماً، وأما صوم ثلاثة أيام فصاعداً قبل رمضان فلا بأس فيه وأما القضاء والكفارة فقيل: إنه خلاف الأولى ومكروه تنزيهاً، وأما النفل المطلق قبل رمضان بثلاثة أيام فصاعداً فلا كراهة فيه","src":"العرف الشذي","loc":"٢/١٤٢","pre":"وقال الكشميري:"},{"t":"quote","text":"يوم الشك يوم الغيم لا يوم الصحو كما قالوا، ونقلوا أن الشافعي وأبا حنيفة ومالكاً كرهوا الصوم يوم الشك وأحمد بن حنبل يحبّه هكذا في عامة الكتب، ثم قال ابن تيمية: إن صوم يوم الشك المنهي عنه في الحديث ليس المراد به يوم الغيم بل يوم الصحو، والشك هو الوسواس والوهم المحض، وقد ثبت صوم يوم الغيم عن بعض السلف منهم ابن عمر","src":"العرف الشذي","loc":"٢/١٤٣","pre":"وقال في يوم الشك:"},{"t":"quote","text":"وَمِنْهَا صَوْمُ يَوْمِ الشَّكِّ بِنِيَّةِ رَمَضَانَ، أَوْ بِنِيَّةٍ مُتَرَدِّدَةٍ، أَمَّا بِنِيَّةِ رَمَضَانَ فَلِقَوْلِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - «لَا يُصَامُ الْيَوْمُ الَّذِي يُشَكُّ فِيهِ مِنْ رَمَضَانَ إلَّا تَطَوُّعًا» وَعَنْ عُمَرَ وَعُثْمَانَ وَعَلِيٍّ - رَضِيَ اللَّهُ عَنْهُمْ - أَنَّهُمْ كَانُوا يَنْهَوْنَ عَنْ صَوْمِ الْيَوْمِ الَّذِي يُشَكُّ فِيهِ مِنْ رَمَضَانَ وَلِأَنَّهُ يُرِيدُ أَنْ يَزِيدَ فِي رَمَضَانَ","src":"بدائع الصنائع","loc":"٢/٧٨","pre":"قال الكاساني الحنفي رحمه الله في «بدائع الصنائع» فيما يكره من الصيام:"},{"t":"quote","text":"حَدِيثُ عَمَّارٍ رَوَاهُ أَبُو دَاوُد وَالتِّرْمِذِيُّ وَقَالَ هُوَ حَدِيثٌ حَسَنٌ صَحِيحٌ","src":"المجموع","loc":"٦/٣٩٩","pre":"وقال النووي الشافعي رحمه الله في «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صيام يوم الشك أقرب الأقوال فيه أنه حرام، لقول عمار بن ياسر رضي الله عنه: «من صام اليوم الذي يشك فيه فقد عصى أبا القاسم صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ»","src":"مجموع فتاوى ابن عثيمين","loc":"٢٠/٥٩","pre":"سئل الشيخ محمد بن صالح العثيمين رحمه الله عن صوم يوم الشك فقال:"},{"t":"h","text":"سبب الخلاف"},{"t":"p","text":"سبب الخلاف: اختلافهم في معنى قوله ﷺ: «فإن غم عليكم فاقدروا له»؛ فحمله الجمهور على إكمال عدة شعبان ثلاثين، لحديث: «فأكملوا عدة شعبان ثلاثين»، فلم يروا صوم يوم الغيم، وحمله ابن عمر رضي الله عنهما ومن وافقه على التضييق، أي يقدر الشهر تسعة وعشرين فيُصام اليوم الثلاثون احتياطًا."},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه لا يجوز صوم يوم الشك بنية رمضان احتياطًا، ولا تقدم رمضان بيوم أو يومين بنية الاحتياط؛ لحديث أبي هريرة رضي الله عنه في الصحيحين، وقول عمار رضي الله عنه: «من صام اليوم الذي يشك فيه الناس فقد عصى أبا القاسم ﷺ»، وهو قول جمهور العلماء."},{"t":"p","text":"ومن كانت له عادة صيام، كالاثنين والخميس، أو كان عليه قضاء أو نذر، فوافق ذلك يوم الشك، صامه ولا حرج؛ لاستثناء النبي ﷺ: «إلا أن يكون رجل كان يصوم صومه فليصم ذلك اليوم»."}],"refs":["البخاري ١٩١٤","الترمذي ٦٨٦","بداية المجتهد (٢/٤٦)","العرف الشذي (٢/١٤٢)","العرف الشذي (٢/١٤٣)","بدائع الصنائع (٢/٧٨)","المجموع (٦/٣٩٩)","مجموع فتاوى ابن عثيمين (٢٠/٥٩)"],"related":["ثبوت دخول شهر رمضان وخروجه: الرؤية وإكمال العدة والحساب الفلكي"],"alts":["يوم الشك","صيام آخر شعبان","الصيام احتياطا لرمضان","تقدم رمضان بصوم"]},{"n":229,"bab":"الصيام","sub":"النية في الصيام","title":"النية في الصيام: تبييتها وتعيينها، وهل تكفي نية واحدة للشهر؟","q":"هل يجب أن أنوي الصيام كل ليلة؟ ومن نام قبل المغرب ولم يستيقظ إلا بعد الفجر ولم ينو، فهل يصح صومه؟ وهل يجوز أن أنوي صيام النفل في النهار؟ وهل يلزم التلفظ بالنية؟","short":"اتفق الجمهور على أن النية شرط في صحة الصيام. واختلفوا في وقتها: فقال مالك: لا يصح صوم إلا بنية قبل الفجر، فرضًا كان أو نفلًا، وتكفي في رمضان نية واحدة في أوله. وقال الشافعي وأحمد: يجب تبييت النية من الليل في الفرض لكل يوم، وتصح نية النفل في النهار قبل الزوال. وقال أبو حنيفة: تصح نية رمضان والنذر المعين والنفل قبل نصف النهار، ولا بد من التبييت في القضاء والكفارة والنذر المطلق.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى، فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى دُنْيَا يُصِيبُهَا أَوْ إِلَى امْرَأَةٍ يَنْكِحُهَا، فَهِجْرَتُهُ إِلَى مَا هَاجَرَ إِلَيْهِ","src":"رواه البخاري ١","pre":"عن عمر بن الخطاب رضي الله عنه قال: سمعت رسول الله ﷺ يقول:","links":[{"book":"mt_bukhari","num":1,"id":"h1"}]},{"t":"quote","text":"مَنْ لَمْ يُجْمِعِ الصِّيَامَ قَبْلَ الْفَجْرِ فَلاَ صِيَامَ لَهُ","src":"رواه الترمذي ٧٣٠","pre":"وعن حفصة رضي الله عنها عن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":730,"id":"h730"}]},{"t":"p","text":"قال الترمذي: لا نعرفه مرفوعًا إلا من هذا الوجه، وروي عن ابن عمر موقوفًا وهو أصح."},{"t":"quote","text":"أَرْسَلَ النَّبِيُّ صلى الله عليه وسلم غَدَاةَ عَاشُورَاءَ إِلَى قُرَى الأَنْصَارِ «مَنْ أَصْبَحَ مُفْطِرًا فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ، وَمَنْ أَصْبَحَ صَائِمًا فَلْيَصُمْ»","src":"رواه البخاري ١٩٦٠","pre":"وعن الربيع بنت معوذ رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1960,"id":"h1960"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا كَوْنُ النِّيَّةِ شَرْطًا فِي صِحَّةِ الصِّيَامِ: فَإِنَّهُ قَوْلُ الْجُمْهُورِ; وَشَذَّ زُفَرُ فَقَالَ: لَا يَحْتَاجُ رَمَضَانُ إِلَى نِّيَّةٍ إِلَّا أَنْ يَكُونَ الَّذِي يُدْرِكُهُ صِيَامُ رَمَضَانَ مَرِيضًا أَوْ مُسَافِرًا فَيُرِيدُ الصَّوْمَ","src":"بداية المجتهد","loc":"٢/٥٥","pre":"قال ابن رشد:"},{"t":"quote","text":"فَقُلْنَا فِي رَمَضَانَ وَالْمَنْذُورِ الْمُعَيَّنِ وَالنَّفَلِ تَجْزِيهِ النِّيَّةُ مِنْ بَعْدِ الْغُرُوبِ إلَى مَا قَبْلَ نِصْفِ النَّهَارِ فِي صَوْمِ ذَلِكَ النَّهَارِ وَفِيمَا سِوَى ذَلِكَ مِنْ الْقَضَاءِ وَالْكَفَّارَاتِ، وَالْمَنْذُورِ الْمُطْلَقِ كَنَذْرِ صَوْمِ يَوْمٍ مِنْ غَيْرِ تَعْيِينٍ لَا بُدَّ مِنْ وُجُودِهَا فِي اللَّيْلِ. وَقَالَ الشَّافِعِيُّ: لَا تَجْزِي فِي غَيْرِ النَّفْلِ إلَّا مِنْ اللَّيْلِ. وَقَالَ مَالِكٌ: لَا تَجْزِي إلَّا مِنْ اللَّيْلِ فِي النَّفْلِ وَغَيْرِهِ","src":"الهداية مع فتح القدير","loc":"٢/٣٠٣","pre":"قال الكمال ابن الهمام الحنفي رحمه الله في «فتح القدير» مبيّنًا المذاهب:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وصيام الفرض لا بد أن ينويه من الليل قبل طلوع الفجر، ويجب عليه أن ينوي لكل يوم نية جديدة، لأن كل يوم عبادة مستقلة تحتاج إلى نية متجددة بتجدد الأيام لعموم قوله صلى الله عليه وسلم: «إنما الأعمال بالنيات وإنما لكل امرئ ما نوى» ، وكل يوم من رمضان فإنه عبادة مستقلة، يجب أن تخص بنية، ولا تكفي النية التي من أول الشهر، إلا إذا جددها كل ليلة","src":"مجموع فتاوى الشيخ صالح الفوزان","loc":"٢/٣٩٠","pre":"وقال الشيخ صالح بن فوزان الفوزان حفظه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن صوم الفرض، كرمضان والقضاء والكفارة والنذر، لا بد فيه من نية من الليل قبل طلوع الفجر؛ لحديث حفصة رضي الله عنها، وهو قول الجمهور. والنية محلها القلب، ولا يشرع التلفظ بها، ومن تسحر أو عزم على صيام الغد وهو يعلم أنه من رمضان فقد نوى."},{"t":"p","text":"ومن نام قبل المغرب في رمضان ولم يستيقظ إلا بعد الفجر صح صومه على الأظهر؛ لأن نية صيام الشهر كله حاصلة منه، وهو قول مالك ورواية عن أحمد، ولقول الحنفية بصحة النية في النهار. والأحوط أن ينوي كل ليلة، وأن ينوي في أول الشهر صيامه كله."},{"t":"p","text":"وأما صوم النفل فيصح بنية من النهار، قبل الزوال أو بعده على الأظهر، ما لم يأكل أو يشرب أو يفعل مفطرًا بعد الفجر؛ لحديث عائشة رضي الله عنها: «فإني إذًا صائم»، وهو قول الجمهور."}],"refs":["البخاري ١","الترمذي ٧٣٠","البخاري ١٩٦٠","بداية المجتهد (٢/٥٥)","بداية المجتهد (٢/٥٦)","الهداية مع فتح القدير (٢/٣٠٣)","مجموع فتاوى الشيخ صالح الفوزان (٢/٣٩٠)"],"related":["فرض صيام رمضان، وفضله، وعلى من يجب","وقت الإمساك والسحور: طلوع الفجر، والأكل مع الشك فيه"],"alts":["نية الصيام","تبييت النية","نية صيام رمضان","التلفظ بنية الصوم","نية صوم النفل"]},{"n":230,"bab":"الصيام","sub":"وقت الصيام","title":"وقت الإمساك والسحور: طلوع الفجر، والأكل مع الشك فيه","q":"متى يجب الإمساك عن الطعام؟ وهل ما يسمى بالإمساك قبل الفجر بعشر دقائق مشروع؟ ومن سمع الأذان والطعام أو الماء في يده فماذا يفعل؟ ومن أكل شاكًّا في طلوع الفجر ثم تبين أنه طلع؟","short":"أجمعوا على أن الصائم يجب عليه الإمساك عن الطعام والشراب والجماع من طلوع الفجر الصادق إلى غروب الشمس. وجمهور العلماء على جواز الأكل حتى يتبين طلوع الفجر الثاني المستطير. واختلفوا فيمن أكل يظن الليل فإذا الفجر قد طلع: فالجمهور على أن عليه القضاء، وقال بعض السلف: لا قضاء عليه.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ ۚ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَٱلْـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ ۚ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ۖ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ ۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ ۗ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا ۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ","ref":"البقرة: ١٨٧"},{"t":"quote","text":"كُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ابْنُ أُمِّ مَكْتُومٍ، فَإِنَّهُ لاَ يُؤَذِّنُ حَتَّى يَطْلُعَ الْفَجْرُ","src":"رواه البخاري ١٩١٨","pre":"عن عائشة رضي الله عنها أن بلالًا كان يؤذن بليل فقال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1918,"id":"h1918"}]},{"t":"quote","text":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً","src":"رواه البخاري ١٩٢٣","pre":"وعن أنس رضي الله عنه قال: قال النبي ﷺ:","links":[{"book":"mt_bukhari","num":1923,"id":"h1923"}]},{"t":"quote","text":"تَسَحَّرْنَا مَعَ النَّبِيِّ صلى الله عليه وسلم ثُمَّ قَامَ إِلَى الصَّلاَةِ. قُلْتُ كَمْ كَانَ بَيْنَ الأَذَانِ وَالسَّحُورِ قَالَ قَدْرُ خَمْسِينَ آيَةً","src":"رواه البخاري ١٩٢١","pre":"وعن زيد بن ثابت رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1921,"id":"h1921"}]},{"t":"quote","text":"إِذَا سَمِعَ أَحَدُكُمُ النِّدَاءَ وَالإِنَاءُ عَلَى يَدِهِ فَلاَ يَضَعْهُ حَتَّى يَقْضِيَ حَاجَتَهُ مِنْهُ","src":"رواه أبو داود ٢٣٥٠","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":2350,"id":"h2350"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الَّتِي تَتَعَلَّقُ بِزَمَانِ الْإِمْسَاكِ: فَإِنَّهُمُ اتَّفَقُوا عَلَى أَنَّ آخِرَهُ غَيْبُوبَةُ الشَّمْسِ لِقَوْلِهِ - تَعَالَى -: {ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ} البقرة: 187 وَاخْتَلَفُوا فِي أَوَّلِهِ، فَقَالَ الْجُمْهُورُ: هُوَ طُلُوعُ الْفَجْرِ الثَّانِي الْمُسْتَطِيرِ الْأَبْيَضِ لِثُبُوتِ ذَلِكَ عَنْ رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَعْنِي: حَدَّهُ بِالْمُسْتَطِيرِ - وَلِظَاهِرِ قَوْلِهِ - تَعَالَى -: {حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ} البقرة: 187 الْآيَةَ","src":"بداية المجتهد","loc":"٢/٥١","pre":"قال ابن رشد:"},{"t":"quote","text":"يستحب تأخير السحور وتعجيل الإفطار","src":"العرف الشذي","loc":"٢/١٥٣","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يجب الإمساك عند طلوع الفجر الصادق، وهو البياض المعترض في الأفق، ويجوز الأكل والشرب إلى أن يتبين طلوعه. وأما ما يسمى «الإمساك» قبل الأذان بعشر دقائق أو نحوها فليس بواجب، وإنما يُذكر احتياطًا للتنبيه، ومن أكل فيه فصومه صحيح. والسحور سنة مؤكدة فيه بركة، ويستحب تأخيره إلى قبيل الفجر، وكان بين سحوره ﷺ والصلاة قدر خمسين آية."},{"t":"p","text":"ومن سمع الأذان والإناء في يده فله أن يقضي حاجته منه إذا كان المؤذن يؤذن مع طلوع الفجر أو كان يشك في ذلك؛ لحديث أبي هريرة رضي الله عنه، فإن علم يقينًا أن الفجر قد طلع وجب عليه الإمساك فورًا. ومن أكل شاكًّا في طلوع الفجر ثم لم يتبين له شيء فصومه صحيح؛ لأن الأصل بقاء الليل. ومن أكل ظانًّا بقاء الليل فتبين أن الفجر كان قد طلع، فالأحوط أن يقضي ذلك اليوم، وهو قول الجمهور، ومن أخذ بقول من لا يوجب القضاء لأنه لم يتعمد فله وجه."}],"refs":["البخاري ١٩١٨","البخاري ١٩٢٣","البخاري ١٩٢١","أبو داود ٢٣٥٠","بداية المجتهد (٢/٥١)","بداية المجتهد (٢/٥٢)","العرف الشذي (٢/١٥٣)"],"related":["النية في الصيام: تبييتها وتعيينها، وهل تكفي نية واحدة للشهر؟","وقت الفطر وتعجيله، وما يفطر عليه، ومن أفطر يظن الغروب"],"alts":["وقت السحور","الإمساك قبل الفجر","الأكل أثناء الأذان","فضل السحور","الأكل مع الشك في الفجر"]},{"n":231,"bab":"الصيام","sub":"وقت الصيام","title":"وقت الفطر وتعجيله، وما يفطر عليه، ومن أفطر يظن الغروب","q":"متى يفطر الصائم؟ وهل الأفضل تعجيل الفطر أو تأخيره احتياطًا؟ وعلى ماذا يفطر؟ ومن أفطر ظانًّا غروب الشمس ثم ظهرت الشمس، فهل عليه القضاء؟","short":"اتفقوا على أن وقت الفطر غروب الشمس، وأنه يستحب تعجيل الفطر إذا تحقق الغروب، وأن يفطر على رطب أو تمر أو ماء. واختلفوا فيمن أفطر يظن الغروب ثم طلعت الشمس: فالأئمة الأربعة على أن عليه القضاء، وقال بعض السلف، واختاره ابن تيمية: لا قضاء عليه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِذَا أَقْبَلَ اللَّيْلُ مِنْ هَا هُنَا، وَأَدْبَرَ النَّهَارُ مِنْ هَا هُنَا، وَغَرَبَتِ الشَّمْسُ، فَقَدْ أَفْطَرَ الصَّائِمُ","src":"رواه البخاري ١٩٥٤","pre":"عن عمر بن الخطاب رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_bukhari","num":1954,"id":"h1954"}]},{"t":"quote","text":"لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ","src":"رواه البخاري ١٩٥٧","pre":"وعن سهل بن سعد رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1957,"id":"h1957"}]},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُفْطِرُ عَلَى رُطَبَاتٍ قَبْلَ أَنْ يُصَلِّيَ فَإِنْ لَمْ تَكُنْ رُطَبَاتٌ فَعَلَى تَمَرَاتٍ فَإِنْ لَمْ تَكُنْ حَسَا حَسَوَاتٍ مِنْ مَاءٍ","src":"رواه أبو داود ٢٣٥٦","pre":"وعن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_abudawud","num":2356,"id":"h2356"}]},{"t":"quote","text":"أَفْطَرْنَا عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم يَوْمَ غَيْمٍ، ثُمَّ طَلَعَتِ الشَّمْسُ. قِيلَ لِهِشَامٍ فَأُمِرُوا بِالْقَضَاءِ قَالَ بُدٌّ مِنْ قَضَاءٍ. وَقَالَ مَعْمَرٌ سَمِعْتُ هِشَامًا لاَ أَدْرِي أَقْضَوْا أَمْ لاَ","src":"رواه البخاري ١٩٥٩","pre":"وعن أسماء بنت أبي بكر رضي الله عنهما قالت:","links":[{"book":"mt_bukhari","num":1959,"id":"h1959"}]},{"t":"quote","text":"ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللَّهُ","src":"رواه أبو داود ٢٣٥٧","pre":"وعن ابن عمر رضي الله عنهما قال: كان رسول الله ﷺ إذا أفطر قال:","links":[{"book":"mt_abudawud","num":2357,"id":"h2357"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"مطمح نظر الشريعة أن يكون الإفطار على شيء حلال طيب","src":"العرف الشذي","loc":"٢/١٥٠","pre":"قال الكشميري:"},{"t":"quote","text":"ظاهر حديث الباب يدل على أن الإفطار عند إقبال الليل وإدبار النهار بحكم الشريعة وجبرها وإن لم يفطر حقيقة، أي ظاهراً، وأنه يكون مرتكب الفعل اللغو إلا أن ابن تيمية جوز الوصال إلى السحر وقال باستحبابه كما سأبين، فلا يتمشى على ظاهر حديث الباب، فإن حديث الصحيحين: (لا تواصلوا، وأيكم واصل يواصل إلى السحر) إلخ يخالفه، ويؤيد ابن تيمية، فيحمل حديث الباب على من لا يريد الوصال إلى السحر","src":"العرف الشذي","loc":"٢/١٥٢","pre":"وقال:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والرسول صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حث على تعجيل الفطر، وقال: «لا يزال الناس بخير ما عجلوا الفطر»","src":"مجموع فتاوى ابن عثيمين","loc":"٢٠/٦٠","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يفطر الصائم إذا تحقق غروب قرص الشمس، ولا عبرة بالحمرة الباقية، ويستحب تعجيل الفطر عند تحقق الغروب؛ لقوله ﷺ: «لا يزال الناس بخير ما عجلوا الفطر»، وتأخيره احتياطًا بعد تحقق الغروب خلاف السنة. والسنة أن يفطر على رطبات، فإن لم يجد فعلى تمرات، فإن لم يجد فعلى ماء، ثم يصلي المغرب، ويدعو عند فطره بما ورد: «ذهب الظمأ، وابتلت العروق، وثبت الأجر إن شاء الله»."},{"t":"p","text":"ومن أفطر ظانًّا غروب الشمس ثم تبين أنها لم تغرب وجب عليه الإمساك بقية يومه، والأحوط أن يقضي ذلك اليوم، وهو قول الأئمة الأربعة، ومن أخذ بقول من لم يوجب القضاء لأنه لم يتعمد، ولعدم ثبوت الأمر بالقضاء في حديث أسماء رضي الله عنها، فله وجه. ولا يجوز الفطر مع الشك في الغروب؛ لأن الأصل بقاء النهار."}],"refs":["البخاري ١٩٥٤","البخاري ١٩٥٧","أبو داود ٢٣٥٦","البخاري ١٩٥٩","أبو داود ٢٣٥٧","العرف الشذي (٢/١٥٠)","العرف الشذي (٢/١٥٢)","مجموع فتاوى ابن عثيمين (٢٠/٦٠)"],"related":["وقت الإمساك والسحور: طلوع الفجر، والأكل مع الشك فيه"],"alts":["وقت الإفطار","تعجيل الفطر","على ماذا يفطر الصائم","من أفطر قبل الغروب خطأ","دعاء الإفطار"]},{"n":232,"bab":"الصيام","sub":"المفطرات","title":"من أكل أو شرب ناسيًا وهو صائم","q":"نسيت أني صائم فأكلت وشربت، ثم تذكرت، فهل صومي صحيح؟ وإذا رأيت صائمًا يأكل ناسيًا فهل أذكّره؟","short":"ذهب أبو حنيفة والشافعي وأحمد إلى أن من أكل أو شرب ناسيًا فصومه صحيح ولا قضاء عليه، فرضًا كان أو نفلًا. وقال مالك: يقضي في الفرض دون النفل. وأما من جامع ناسيًا فقال أبو حنيفة والشافعي: لا قضاء ولا كفارة، وقال مالك: عليه القضاء، وقال أحمد: عليه القضاء والكفارة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ نَسِيَ وَهُوَ صَائِمٌ، فَأَكَلَ أَوْ شَرِبَ، فَلْيُتِمَّ صَوْمَهُ، فَإِنَّمَا أَطْعَمَهُ اللهُ وَسَقَاهُ","src":"رواه مسلم ١١٥٥","pre":"عن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1155,"id":"h1155"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"قال الثلاثة: إن صوم من أكل وشرب ناسياً باقي، وقال مالك: إن كان صومه صوم الفريضة فيقضيه وإن كان صوم تطوع فلا قضاء قد تم صومه","src":"العرف الشذي","loc":"٢/١٦٢","pre":"قال الكشميري:"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الثَّانِيَةُ: وَهُوَ إِذَا جَامَعَ نَاسِيًا لِصَوْمِهِ -: فَإِنَّ الشَّافِعِيَّ وَأَبَا حَنِيفَةَ يَقُولَانِ: لَا قَضَاءَ عَلَيْهِ وَلَا كَفَّارَةَ. وَقَالَ مَالِكٌ: عَلَيْهِ الْقَضَاءُ دُونَ الْكَفَّارَةِ. وَقَالَ أَحْمَدُ وَأَهْلُ الظَّاهِرُ: عَلَيْهِ الْقَضَاءُ وَالْكَفَّارَةُ","src":"بداية المجتهد","loc":"٢/٦٥","pre":"وقال ابن رشد في الجماع ناسيًا:"},{"t":"quote","text":"وَإِذَا أَكَلَ الصَّائِمُ أَوْ شَرِبَ أَوْ جَامَعَ نَهَارًا نَاسِيًا لَمْ يُفْطِرْ وَالْقِيَاسُ أَنْ يُفْطِرَ، وَهُوَ قَوْلُ مَالِكٍ لِوُجُودِ مَا يُضَادُّ الصَّوْمَ فَصَارَ كَالْكَلَامِ نَاسِيًا فِي الصَّلَاةِ، وَجْهُ الِاسْتِحْسَانِ «قَوْلُهُ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - لِلَّذِي أَكَلَ وَشَرِبَ نَاسِيًا تِمَّ عَلَى صَوْمِكَ فَإِنَّمَا أَطْعَمَكَ اللَّهُ وَسَقَاكَ»","src":"الهداية مع فتح القدير","loc":"٢/٣٢٧","pre":"جاء في «الهداية» للمرغيناني الحنفي مع «فتح القدير»:"},{"t":"quote","text":"أَرَأَيْتَ مَنْ أَكَلَ أَوْ شَرِبَ أَوْ جَامَعَ امْرَأَتَهُ فِي رَمَضَانَ نَاسِيًا، أَعَلَيْهِ الْقَضَاءُ فِي قَوْلِ مَالِكٍ؟ قَالَ: نَعَمْ وَلَا كَفَّارَةَ عَلَيْهِ","src":"المدونة","loc":"١/٢٧٧","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"quote","text":"إذَا أَكَلَ أَوْ شَرِبَ أَوْ تَقَايَأَ أَوْ اسْتَعَطَ أَوْ جَامَعَ أَوْ فَعَلَ غَيْرَ ذَلِكَ مِنْ مُنَافِيَاتِ الصَّوْمِ نَاسِيًا لَمْ يُفْطِرْ عِنْدَنَا سَوَاءٌ قَلَّ ذَلِكَ أَمْ كَثُرَ","src":"المجموع","loc":"٦/٣٢٤","pre":"وقال النووي الشافعي رحمه الله:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"من أكل أو شرب ناسياً وهو صائم فإن صيامه صحيح، لكن إذا تذكر يجب عليه أن يقلع حتى إذا كانت اللقمة أو الشربة في فمه، فإنه يجب عليه أن يلفظها","src":"مجموع فتاوى ابن عثيمين","loc":"١٩/٢٧٢","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن من أكل أو شرب ناسيًا فصومه صحيح، ولا قضاء عليه، فرضًا كان الصوم أو نفلًا؛ لقوله ﷺ: «فليتم صومه، فإنما أطعمه الله وسقاه»، فسمّاه صومًا وأمر بإتمامه، وهو قول الجمهور. ويجب عليه أن يمسك فور تذكره، ويلفظ ما في فمه. وكذلك من جامع ناسيًا على الأظهر؛ لعموم رفع الحرج عن الناسي، وهو قول أبي حنيفة والشافعي."},{"t":"p","text":"ومن رأى صائمًا يأكل ناسيًا فالأولى أن يذكّره؛ لأنه من التعاون على البر وإنكار ما صورته منكر، وذكر الحنفية أنه إن كان الآكل ضعيفًا يشق عليه الصوم فلا بأس أن يتركه."}],"refs":["مسلم ١١٥٥","العرف الشذي (٢/١٦٢)","بداية المجتهد (٢/٦٥)","الهداية مع فتح القدير (٢/٣٢٧)","المدونة (١/٢٧٧)","المجموع (٦/٣٢٤)","مجموع فتاوى ابن عثيمين (١٩/٢٧٢)","بداية المجتهد (٢/٦٥-٦٦)"],"related":["وقت الفطر وتعجيله، وما يفطر عليه، ومن أفطر يظن الغروب"],"alts":["الأكل ناسيا في رمضان","من نسي فأكل","الشرب ناسيا","تذكير الصائم الناسي"]},{"n":233,"bab":"الصيام","sub":"المفطرات","title":"القيء للصائم: من غلبه القيء ومن تعمده","q":"تقيأت وأنا صائم دون قصد، فهل فسد صومي؟ وما حكم من أدخل إصبعه ليتقيأ؟","short":"جمهور الفقهاء على أن من غلبه القيء لم يفطر، ولا قضاء عليه، وأن من استقاء عامدًا فقاء فقد أفطر وعليه القضاء، وهو قول الأئمة الأربعة، وخالف ربيعة في الأول وطاوس في الثاني. ولا كفارة في القيء عند الجمهور.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ ذَرَعَهُ الْقَىْءُ فَلَيْسَ عَلَيْهِ قَضَاءٌ وَمَنِ اسْتَقَاءَ عَمْدًا فَلْيَقْضِ","src":"رواه الترمذي ٧٢٠","pre":"عن أبي هريرة رضي الله عنه أن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":720,"id":"h720"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْقَيْءُ: فَإِنَّ جُمْهُورَ الْفُقَهَاءِ عَلَى أَنَّ مَنْ ذَرَعَهُ الْقَيْءُ فَلَيْسَ بِمُفْطِرٍ، إِلَّا رَبِيعَةَ فَإِنَّهُ قَالَ: مُفْطِرٌ، وَجُمْهُورُهُمْ أَيْضًا عَلَى أَنَّ مَنِ اسْتَقَاءَ فَقَاءَ فَإِنَّهُ مُفْطِرٌ إِلَّا طَاوُسًا","src":"بداية المجتهد","loc":"٢/٥٤","pre":"قال ابن رشد:"},{"t":"quote","text":"ظاهر الرواية لنا أن ذرع القيء غير مفسد والستقاء مفسد، ثم فصل المصنفون فيها وصارت اثنتي عشر صورة لأن القيء وإما قليل أو كثير، ثم إما ذرعه أو استقاء، ثم يرب هذه الأربعة في الثلاثة أي أنه خرج أو أعاده فمصلت ثثنتي عشر صورة، وأحكام الكل مذكورة في المبسوطات مثل البحر وغيره","src":"العرف الشذي","loc":"٢/١٦٠","pre":"وقال الكشميري:"},{"t":"quote","text":"ومن الأمور التي قد يخفى حكمها على بعض الناس: ما قد يعرض للصائم من جراح أو رعاف أو قيء أو ذهاب الماء أو البنزين إلى حلقه بغير اختياره، فكل هذه الأمور لا تفسد الصوم، لكن من تعمد القيء فسد صومه","src":"مجموع فتاوى ابن باز","loc":"١٥/١٦","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"من غلبه القيء وهو صائم فصومه صحيح، ولا قضاء عليه، قليلًا كان أو كثيرًا، ما لم يتعمد إعادة شيء منه إلى جوفه. ومن تعمد القيء، بإدخال إصبعه أو بشم ما يقيئه أو نحو ذلك، فقاء، فسد صومه ولزمه قضاء ذلك اليوم، ولا كفارة عليه؛ لحديث أبي هريرة رضي الله عنه، وهو قول الأئمة الأربعة. ومن احتاج إلى ذلك لمرض فله أن يفطر ويقضي."}],"refs":["الترمذي ٧٢٠","بداية المجتهد (٢/٥٤)","العرف الشذي (٢/١٦٠)","مجموع فتاوى ابن باز (١٥/١٦)"],"related":["الحجامة وسحب الدم والتبرع به للصائم","من أكل أو شرب ناسيًا وهو صائم"],"alts":["القيء في رمضان","التقيؤ للصائم","الاستقاء عمدا","الغثيان والقيء"]},{"n":234,"bab":"الصيام","sub":"المفطرات","title":"الحجامة وسحب الدم والتبرع به للصائم","q":"هل الحجامة تفطر الصائم؟ وما حكم سحب الدم للتحليل أو التبرع بالدم في نهار رمضان؟","short":"ذهب أحمد وإسحاق والأوزاعي إلى أن الحجامة تفطر الحاجم والمحجوم. وقال مالك والشافعي والثوري: لا تفطر، لكنها تكره لمن يُضعفه ذلك. وقال أبو حنيفة وأصحابه: لا تفطر ولا تكره. ويلحق بالحجامة عند من يقول بالفطر بها ما كان في معناها من إخراج الدم الكثير كالتبرع بالدم، دون سحب العينة اليسيرة للتحليل.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَفْطَرَ الْحَاجِمُ وَالْمَحْجُومُ","src":"رواه أبو داود ٢٣٦٧","pre":"عن ثوبان رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_abudawud","num":2367,"id":"h2367"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم احْتَجَمَ، وَهْوَ مُحْرِمٌ وَاحْتَجَمَ وَهْوَ صَائِمٌ","src":"رواه البخاري ١٩٣٨","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_bukhari","num":1938,"id":"h1938"}]},{"t":"quote","text":"أَكُنْتُمْ تَكْرَهُونَ الْحِجَامَةَ لِلصَّائِمِ قَالَ لاَ. إِلاَّ مِنْ أَجْلِ الضَّعْفِ","src":"رواه البخاري ١٩٤٠","pre":"وسئل أنس بن مالك رضي الله عنه:","links":[{"book":"mt_bukhari","num":1940,"id":"h1940"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْحِجَامَةُ فَإِنَّ فِيهَا ثَلَاثَةَ مَذَاهِبَ: قَوْمٌ قَالُوا: إِنَّهَا تُفْطِرُ وَأَنَّ الْإِمْسَاكَ عَنْهَا وَاجِبٌ، وَبِهِ قَالَ أَحْمَدُ وَالْأَوْزَاعِيُّ وَإِسْحَاقُ بْنُ رَاهَوَيْهِ. وَقَوْمٌ قَالُوا: إِنَّهَا مَكْرُوهَةٌ لِلصَّائِمِ وَلَيْسَتْ تُفْطِرُ، وَبِهِ قَالَ مَالِكٌ وَالشَّافِعِيُّ وَالثَّوْرِيُّ. وَقَوْمٌ قَالُوا: إِنَّهَا غَيْرُ مَكْرُوهَةٍ وَلَا مُفْطِرَةٍ، وَبِهِ قَالَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ","src":"بداية المجتهد","loc":"٢/٥٣","pre":"قال ابن رشد:"},{"t":"quote","text":"وعندي حديث الباب معناه أنه قد أفطر أي أدخل النقص في صومه، وإنما يظهر في أحكام الآخرة لا أحكام الدنيا مثل الغيبة","src":"العرف الشذي","loc":"٢/١٩٣","pre":"وقال الكشميري:"},{"t":"quote","text":"ومن الأمور التي لا تفسد الصوم: تحليل الدم، وضرب الإبر، غير التي يقصد بها التغذية، لكن تأخير ذلك إلى الليل أولى وأحوط إذا تيسر ذلك","src":"مجموع فتاوى ابن باز","loc":"١٥/١٧","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"المسألة من مسائل الخلاف القوي: والأظهر قول الجمهور أن الحجامة لا تفطر؛ لأن النبي ﷺ احتجم وهو صائم، ولقول أنس رضي الله عنه: إنهم كانوا يكرهونها من أجل الضعف، فدل على أن النهي لخشية الضعف، وقد ذهب جمع من أهل العلم إلى أن حديث «أفطر الحاجم والمحجوم» منسوخ. ومن أخذ بقول أحمد فقد احتاط لصومه، والأولى للصائم أن يؤخر الحجامة إلى الليل خروجًا من الخلاف."},{"t":"p","text":"وسحب الدم اليسير للتحليل لا يفطر بالاتفاق تقريبًا. وأما التبرع بالدم الكثير فحكمه حكم الحجامة: لا يفطر عند الجمهور، ويفطر عند من يقول بالفطر بالحجامة، فالأحوط أن يؤخره إلى الليل إلا لضرورة، كإنقاذ مريض محتاج، فيتبرع ويقضي احتياطًا. ولا يفطر خروج الدم بالرعاف أو الجرح أو قلع الضرس."}],"refs":["أبو داود ٢٣٦٧","البخاري ١٩٣٨","البخاري ١٩٤٠","بداية المجتهد (٢/٥٣)","العرف الشذي (٢/١٩٣)","مجموع فتاوى ابن باز (١٥/١٧)","بداية المجتهد (٢/٥٤)"],"related":["القيء للصائم: من غلبه القيء ومن تعمده","ما يدخل الجوف من غير الفم: الكحل والقطرة والإبر والبخاخ"],"alts":["الحجامة في رمضان","التبرع بالدم للصائم","تحليل الدم للصائم","سحب الدم في رمضان"]},{"n":235,"bab":"الصيام","sub":"المفطرات","title":"ما يدخل الجوف من غير الفم: الكحل والقطرة والإبر والبخاخ","q":"هل تفطر قطرة العين أو الأذن أو الأنف؟ وما حكم الإبر (الحقن) في العضل أو الوريد، والمغذية منها؟ وما حكم بخاخ الربو، والتحاميل، والكحل؟","short":"أجمعوا على أن الأكل والشرب والجماع تفطر. واختلفوا فيما يصل إلى الجوف من غير الفم، أو مما ليس بمغذٍّ: فمذهب الأئمة الأربعة في الجملة أن ما وصل إلى الجوف أو الحلق أو الدماغ من منفذ مفتوح كالأنف والأذن والدبر يفطر، وأن ما وصل من المسام كالدهن لا يفطر. والكحل لا يفطر عند الحنفية والشافعية، ويفطر عند المالكية والحنابلة إذا وجد طعمه في حلقه. وأما الإبر غير المغذية فلا تفطر عند جمهور المعاصرين، والمغذية تفطر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَسْبِغِ الْوُضُوءَ وَخَلِّلْ بَيْنَ الأَصَابِعِ وَبَالِغْ فِي الاِسْتِنْشَاقِ إِلاَّ أَنْ تَكُونَ صَائِمًا","src":"رواه الترمذي ٧٨٨","pre":"عن لقيط بن صبرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":788,"id":"h788"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَجْمَعُوا عَلَى أَنَّهُ يَجِبُ عَلَى الصَّائِمِ الْإِمْسَاكُ زَمَانَ الصَّوْمِ عَنِ الْمَطْعُومِ وَالْمَشْرُوبِ وَالْجِمَاعِ لِقَوْلِهِ - تَعَالَى -: {فَالآنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الأَبْيَضُ مِنَ الْخَيْطِ الأَسْوَدِ مِنَ الْفَجْرِ} البقرة: 187","src":"بداية المجتهد","loc":"٢/٥٢","pre":"قال ابن رشد:"},{"t":"quote","text":"لا بأس بالكحل للصائم وإن ظهر أثره في البزاق، ومن بزق وفيه أثر الكحل ثم أعاده فسد صومه وإن لم يعد فلا شيء عليه","src":"العرف الشذي","loc":"٢/١٦٥","pre":"وقال الكشميري:"},{"t":"quote","text":"مخافة بلوغ الماء الدماغ، ومفسد الصوم عندنا ما يبلغ الدماغ أو الجوف","src":"العرف الشذي","loc":"٢/١٩٩","pre":"وقال في الاستنشاق:"},{"t":"quote","text":"ومن الأمور التي لا تفسد الصوم: تحليل الدم، وضرب الإبر، غير التي يقصد بها التغذية، لكن تأخير ذلك إلى الليل أولى وأحوط إذا تيسر ذلك","src":"مجموع فتاوى ابن باز","loc":"١٥/١٧","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأصل أن المفطر هو الأكل والشرب والجماع، وما كان في معنى الأكل والشرب مما يصل إلى الجوف من منفذ معتاد أو يقوم مقام الطعام في تغذية البدن. وعلى هذا:"},{"t":"p","text":"الإبر (الحقن) العلاجية في العضل أو الجلد أو الوريد لا تفطر، كإبر المضادات والأنسولين والتطعيم والتخدير الموضعي؛ لأنها ليست أكلًا ولا شربًا ولا في معناهما. وأما الإبر المغذية والمحاليل التي يستغنى بها عن الطعام والشراب فتفطر."},{"t":"p","text":"وقطرة العين والكحل لا تفطران على الأظهر، وهو قول الحنفية والشافعية؛ لأن العين ليست منفذًا إلى الجوف، ولو وجد طعمها في حلقه فالأحوط ألا يبتلعه. وقطرة الأذن لا تفطر إذا كانت طبلة الأذن سليمة. وأما قطرة الأنف وبخاخه فالأحوط تركهما في النهار؛ لأن الأنف منفذ إلى الحلق، ولقوله ﷺ: «وبالغ في الاستنشاق إلا أن تكون صائمًا»، فإن احتاج إليهما فليحترز من ابتلاع ما يصل إلى حلقه."},{"t":"p","text":"وبخاخ الربو الذي يحمل دواء رذاذًا إلى الرئة اختلف فيه المعاصرون: فأفتى كثير منهم بأنه لا يفطر لقلة ما يصل منه إلى المعدة وشبهه بالمضمضة، وقال آخرون: يفطر لأنه يدخل من الفم، والأظهر أنه لا يفطر، لا سيما للمحتاج إليه، ومن احتاط فاستعمله وقضى فلا حرج. والتحاميل الشرجية والحقنة الشرجية تفطر عند الأئمة الأربعة، وذهب بعض المحققين إلى أن ما لا يغذي منها لا يفطر، والأحوط أن يقضي من احتاج إليها. ودهن الجلد والمراهم واللصقات العلاجية لا تفطر."}],"refs":["الترمذي ٧٨٨","بداية المجتهد (٢/٥٢)","العرف الشذي (٢/١٦٥)","العرف الشذي (٢/١٩٩)","مجموع فتاوى ابن باز (١٥/١٧)"],"related":["الحجامة وسحب الدم والتبرع به للصائم","الدخان والبخور والعطر وبلع الريق وذوق الطعام للصائم"],"alts":["قطرة العين للصائم","الإبر في رمضان","بخاخ الربو للصائم","الكحل للصائم","المغذي الوريدي","التحاميل في رمضان"]},{"n":236,"bab":"الصيام","sub":"المفطرات","title":"القبلة والمباشرة للصائم، والإنزال والمذي والاحتلام","q":"هل يجوز للصائم أن يقبّل زوجته؟ وما حكم من أنزل بسبب القبلة أو النظر أو الاستمناء؟ وهل يفسد الصوم بالاحتلام أو خروج المذي؟","short":"اتفقوا على أن من قبّل أو باشر فأنزل المني فقد أفطر، واختلفوا في الكفارة عليه. واختلفوا في القبلة: فأجازها قوم مطلقًا، وكرهها قوم للشاب الذي لا يأمن على نفسه وأجازوها للشيخ، وهو قول الحنفية والشافعية، وكرهها مالك مطلقًا. وأجمعوا على أن الاحتلام لا يفسد الصوم. وأما المذي فلا يفطر عند أبي حنيفة والشافعي، ويفطر عند مالك وأحمد في رواية.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"كَانَ النَّبِيُّ صلى الله عليه وسلم يُقَبِّلُ وَيُبَاشِرُ، وَهُوَ صَائِمٌ، وَكَانَ أَمْلَكَكُمْ لإِرْبِهِ","src":"رواه البخاري ١٩٢٧","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1927,"id":"h1927"}]},{"t":"quote","text":"الصِّيَامُ جُنَّةٌ، فَلاَ يَرْفُثْ وَلاَ يَجْهَلْ، وَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ إِنِّي صَائِمٌ. مَرَّتَيْنِ، وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ، يَتْرُكُ طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي","src":"رواه البخاري ١٨٩٤","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1894,"id":"h1894"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا مَا عَدَا الْمَأْكُولَ وَالْمَشْرُوبَ مِنَ الْمُفْطِرَاتِ فَكُلُّهُمْ يَقُولُونَ: إِنَّ مَنْ قَبَّلَ فَأَمْنَى فَقَدْ أَفْطَرَ وَإِنْ أَمْذَى فَلَمْ يُفْطِرْ إِلَّا مَالِكٌ","src":"بداية المجتهد","loc":"٢/٥٢","pre":"قال ابن رشد:"},{"t":"quote","text":"تجوز القبلة لمن يأمن على نفسه الجماع مثل المشيخة، وتكره لمن لم يأمن مثل الشبان","src":"العرف الشذي","loc":"٢/١٦٦","pre":"وقال الكشميري:"},{"t":"quote","text":"وَلَا بَأْسَ لِلصَّائِمِ أَنْ يُقَبِّلَ وَيُبَاشِرَ إذَا أَمِنَ عَلَى نَفْسِهِ مَا سِوَى ذَلِكَ","src":"بدائع الصنائع","loc":"٢/١٠٦","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"quote","text":"وَنَقَلَ صَاحِبُ الْحَاوِي وَغَيْرُهُ الْإِجْمَاعَ عَلَى بُطْلَانِ صَوْمِ مَنْ قَبَّلَ أَوْ بَاشَرَ دُونَ الْفَرْجِ فَأَنْزَلَ","src":"المجموع","loc":"٦/٣٢٢","pre":"وقال النووي الشافعي رحمه الله:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"فمفهومه أنه إذا لم يملك إربه لا يجوز له التقبيل في رمضان وهو صائم، ويفسد صومه بالإنزال عن شهوة، ولا كفارة عليه، وعليه القضاء والتوبة","src":"فتاوى اللجنة الدائمة","loc":"٦/٤٠","pre":"وجاء في فتاوى اللجنة الدائمة بعد ذكر حديث عائشة رضي الله عنها:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن القبلة والمباشرة دون الجماع جائزة للصائم الذي يملك نفسه ويأمن من الإنزال والجماع، ومكروهة لمن تتحرك شهوته ولا يأمن على نفسه؛ لحديث عائشة رضي الله عنها: «وكان أملككم لإربه»، وهو قول الحنفية والشافعية وغيرهم."},{"t":"p","text":"ومن قبّل أو باشر أو استمنى فأنزل المني فسد صومه، وعليه التوبة والقضاء، ولا كفارة عليه عند الجمهور. ومن أنزل بمجرد التفكير أو النظر من غير تكرار فلا يفسد صومه عند الجمهور، ومن كرر النظر حتى أنزل فقد أفسده عند المالكية والحنابلة، والأحوط أن يقضي. وخروج المذي لا يفسد الصوم على الأظهر، وهو قول أبي حنيفة والشافعي. والاحتلام لا يفسد الصوم بالإجماع؛ لأنه بغير اختيار."}],"refs":["البخاري ١٩٢٧","البخاري ١٨٩٤","بداية المجتهد (٢/٥٢)","بداية المجتهد (٢/٥٢-٥٣)","العرف الشذي (٢/١٦٦)","بدائع الصنائع (٢/١٠٦)","المجموع (٦/٣٢٢)","فتاوى اللجنة الدائمة (٦/٤٠)","بداية المجتهد (٢/٥٣)"],"related":["الجماع في نهار رمضان وكفارته","الجنب يصبح صائمًا، والسواك والمضمضة للصائم"],"alts":["القبلة في رمضان","تقبيل الزوجة للصائم","الاستمناء في رمضان","الاحتلام في رمضان","خروج المذي للصائم"]},{"n":237,"bab":"الصيام","sub":"المفطرات","title":"الجنب يصبح صائمًا، والسواك والمضمضة للصائم","q":"من أصبح جنبًا ولم يغتسل إلا بعد الفجر، فهل يصح صومه؟ وهل يجوز السواك للصائم بعد الزوال؟ وما حكم المضمضة والاستنشاق في الوضوء ومعجون الأسنان؟","short":"جمهور الفقهاء، ومنهم الأئمة الأربعة، على أن من أصبح جنبًا صح صومه، وكذلك الحائض إذا طهرت قبل الفجر ولم تغتسل إلا بعده. والسواك جائز للصائم عند الجمهور، وكرهه الشافعي وأحمد في رواية بعد الزوال، ولم يكرهه أبو حنيفة ومالك في أي وقت. والمضمضة والاستنشاق مشروعان للصائم دون مبالغة.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ يُدْرِكُهُ الْفَجْرُ وَهُوَ جُنُبٌ مِنْ أَهْلِهِ، ثُمَّ يَغْتَسِلُ وَيَصُومُ","src":"رواه البخاري ١٩٢٥","pre":"عن عائشة وأم سلمة رضي الله عنهما:","links":[{"book":"mt_bukhari","num":1925,"id":"h1925"}]},{"t":"quote","text":"الصِّيَامُ جُنَّةٌ، فَلاَ يَرْفُثْ وَلاَ يَجْهَلْ، وَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ إِنِّي صَائِمٌ. مَرَّتَيْنِ، وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ","src":"رواه البخاري ١٨٩٤","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1894,"id":"h1894"}]},{"t":"quote","text":"أَسْبِغِ الْوُضُوءَ وَخَلِّلْ بَيْنَ الأَصَابِعِ وَبَالِغْ فِي الاِسْتِنْشَاقِ إِلاَّ أَنْ تَكُونَ صَائِمًا","src":"رواه الترمذي ٧٨٨","pre":"وعن لقيط بن صبرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_tirmidhi","num":788,"id":"h788"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَجُمْهُورُ الْفُقَهَاءِ عَلَى أَنَّهُ لَيْسَتِ الطَّهَارَةُ مِنَ الْجَنَابَةِ شَرْطًا فِي صِحَّةِ الصَّوْمِ؛ لِمَا ثَبَتَ مِنْ حَدِيثِ عَائِشَةَ وَأُمِّ سَلَمَةَ زَوْجَيِ النَّبِيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهُمَا قَالَتَا: «كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرِ احْتِلَامٍ فِي رَمَضَانَ ثُمَّ يَصُومُ» وَمِنَ الْحُجَّةِ لَهُمَا الْإِجْمَاعُ عَلَى أَنَّ الِاحْتِلَامَ بِالنَّهَارِ لَا يُفْسِدُ الصَّوْمَ","src":"بداية المجتهد","loc":"٢/٥٦","pre":"قال ابن رشد:"},{"t":"quote","text":"الجنابة لا تنافي الصوم عند الأئمة الأربعة إلا أبا هريرة، وهو أيضاً رجع عنه بعد مدة","src":"العرف الشذي","loc":"٢/١٩٦","pre":"وقال الكشميري:"},{"t":"quote","text":"يستحب السواك عندنا في جميع الأحيان قبل الزوال وبعده، وما من حديث يدل على نفي السواك بعد الزوال كما هو مذهب الشافعي، ومختارنا مختار البخاري، وأما حديث: «خلوف فم الصائم» إلخ فلا يدل على النهي عن السواك بل حث على الصيام بذكر فضله","src":"العرف الشذي","loc":"٢/١٦٥","pre":"وقال في السواك:"},{"t":"quote","text":"وما يعرض لبعض النساء من تأخر غسل الحيض أو النفاس إلى طلوع الفجر، إذا رأت الطهر قبل الفجر، فإنه يلزمها الصوم، ولا مانع من تأخير الغسل إلى ما بعد طلوع الفجر","src":"مجموع فتاوى ابن باز","loc":"١٥/١٧","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"من أصبح جنبًا من جماع أو احتلام صح صومه، ويغتسل ويصلي الفجر في وقتها؛ لحديث عائشة وأم سلمة رضي الله عنهما، وهو قول الأئمة الأربعة. وكذلك الحائض والنفساء إذا طهرت قبل الفجر صامت ولو أخرت الغسل إلى ما بعده، ولا يجوز تأخير الغسل حتى تفوت صلاة الفجر."},{"t":"p","text":"والسواك سنة للصائم في كل وقت من النهار، قبل الزوال وبعده، وهو قول أبي حنيفة ومالك واختيار جماعة من محققي الشافعية والحنابلة؛ لعموم الأحاديث في فضل السواك عند كل صلاة ووضوء. ولا بأس باستعمال معجون الأسنان مع التحرز من ابتلاع شيء منه، والأولى أن يكون ذلك ليلًا لقوة طعمه. والمضمضة والاستنشاق سنتان في الوضوء للصائم بلا مبالغة، فإن سبق الماء إلى حلقه بغير تعمد ولا مبالغة فلا يفسد صومه على الأظهر."}],"refs":["البخاري ١٩٢٥","البخاري ١٨٩٤","الترمذي ٧٨٨","بداية المجتهد (٢/٥٦)","العرف الشذي (٢/١٩٦)","العرف الشذي (٢/١٦٥)","مجموع فتاوى ابن باز (١٥/١٧)","بداية المجتهد (٢/٥٧)"],"related":["القبلة والمباشرة للصائم، والإنزال والمذي والاحتلام","ما يدخل الجوف من غير الفم: الكحل والقطرة والإبر والبخاخ"],"alts":["الصيام جنبا","تأخير غسل الجنابة في رمضان","السواك للصائم","معجون الأسنان للصائم","المضمضة للصائم"]},{"n":238,"bab":"الصيام","sub":"المفطرات","title":"الدخان والبخور والعطر وبلع الريق وذوق الطعام للصائم","q":"هل يفطر التدخين في نهار رمضان؟ وما حكم شم البخور والعطور؟ وبلع الريق والنخامة وذوق الطعام للطباخة؟","short":"اتفق الفقهاء على أن شرب الدخان (التدخين) يفطر الصائم؛ لأنه دخان يُتعمّد إدخاله إلى الجوف وله جرم يصل إليه. وفرقوا بين إدخال الدخان عمدًا فيفطر، ودخوله بغير اختيار فلا يفطر. وأما شم الروائح والعطور فلا يفطر، واستنشاق البخور عمدًا يفطر عند الحنفية والشافعية. وبلع الريق لا يفطر بالإجماع. وذوق الطعام لحاجة دون ابتلاع لا يفطر عند الجمهور مع الكراهة لغير حاجة.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"الصِّيَامُ جُنَّةٌ، فَلاَ يَرْفُثْ وَلاَ يَجْهَلْ، وَإِنِ امْرُؤٌ قَاتَلَهُ أَوْ شَاتَمَهُ فَلْيَقُلْ إِنِّي صَائِمٌ. مَرَّتَيْنِ، وَالَّذِي نَفْسِي بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ تَعَالَى مِنْ رِيحِ الْمِسْكِ، يَتْرُكُ طَعَامَهُ وَشَرَابَهُ وَشَهْوَتَهُ مِنْ أَجْلِي","src":"رواه البخاري ١٨٩٤","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1894,"id":"h1894"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"واعلم أن دخول الدخان ليس بمفسد وأما إدخاله فمفسد، وكذلك شرب الدخان (تمباكونوشي) ، مفسد ويوجب الكفارة كما في نظم وهبانية: ~ وأفتوا بتحريم الدخان وشربه ... وشاربه لا شك في الصوم يفطر ~ ويلزمه التكفير لو ظن نافعاً ... كذا دافعاً شهوات بطن فقرروا والتجمير بالعود مفسد ويلزم الكفارة، وأما شم الرائحة فليس بمفسد","src":"العرف الشذي","loc":"٢/١٩٩","pre":"قال الكشميري:"},{"t":"quote","text":"ومن الأمور التي قد يخفى حكمها على بعض الناس: ما قد يعرض للصائم من جراح أو رعاف أو قيء أو ذهاب الماء أو البنزين إلى حلقه بغير اختياره، فكل هذه الأمور لا تفسد الصوم","src":"مجموع فتاوى ابن باز","loc":"١٥/١٦","pre":"وقال الشيخ ابن باز:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"التدخين يفطر الصائم ويوجب القضاء، مع أنه محرم في نفسه لضرره، فرمضان فرصة لتركه. وما دخل الحلق بغير اختيار، كالغبار ودخان السيارات وغبار الطحين ورائحة البنزين، فلا يفطر."},{"t":"p","text":"وشم العطور والروائح الطيبة لا يفطر. وأما البخور فلا يتعمد الصائم استنشاق دخانه؛ لأنه يدخل إلى الجوف ويفطر عند الحنفية والشافعية، ولا بأس بالتطيب به بلا استنشاق."},{"t":"p","text":"وبلع الريق لا يفطر بالإجماع، وأما النخامة إذا وصلت إلى الفم فالأحوط أن يلفظها ولا يبتلعها. ولا بأس للمرأة الطباخة أو المشتري أن يذوق الطعام بطرف لسانه لحاجة، ثم يلفظه ولا يبتلع منه شيئًا، ويكره ذلك لغير حاجة. ولا يفطر مضغ العلك الذي لا يتحلل منه شيء، ويكره، وأما العلك الذي له طعم أو يتحلل فيفطر إن ابتلع منه شيئًا."}],"refs":["البخاري ١٨٩٤","العرف الشذي (٢/١٩٩)","مجموع فتاوى ابن باز (١٥/١٦)"],"related":["ما يدخل الجوف من غير الفم: الكحل والقطرة والإبر والبخاخ","الجنب يصبح صائمًا، والسواك والمضمضة للصائم"],"alts":["التدخين في رمضان","البخور للصائم","العطر للصائم","بلع الريق","ذوق الطعام للصائم","العلك للصائم"]},{"n":239,"bab":"الصيام","sub":"أهل الأعذار","title":"الصوم والفطر في السفر: أيهما أفضل؟ ومتى يفطر المسافر؟","q":"أسافر في رمضان بالطائرة أو السيارة سفرًا مريحًا، فهل الأفضل أن أصوم أو أفطر؟ وهل يجوز أن أفطر في يوم سفري إذا خرجت بعد الفجر؟ ومن قدم من سفره مفطرًا في النهار، هل يمسك؟","short":"أجمعوا على جواز الفطر للمسافر سفرًا تقصر فيه الصلاة، وعلى أن عليه القضاء. وجمهور العلماء على أنه إن صام صح صومه، وخالف أهل الظاهر. واختلفوا في الأفضل: فقال أبو حنيفة ومالك والشافعي: الصوم أفضل لمن لا يشق عليه، وقال أحمد: الفطر أفضل، وقال آخرون: هو مخير. واختلفوا فيمن أصبح صائمًا مقيمًا ثم سافر: فأجاز له أحمد الفطر في يومه، ومنعه أبو حنيفة ومالك والشافعي. واختلفوا فيمن قدم مفطرًا في النهار: فقال أبو حنيفة وأحمد في رواية: يمسك بقية يومه، وقال مالك والشافعي: لا يلزمه الإمساك.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ","ref":"البقرة: ١٨٤"},{"t":"quote","text":"كُنَّا نُسَافِرُ مَعَ النَّبِيِّ صلى الله عليه وسلم فَلَمْ يَعِبِ الصَّائِمُ عَلَى الْمُفْطِرِ، وَلاَ الْمُفْطِرُ عَلَى الصَّائِمِ","src":"رواه البخاري ١٩٤٧","pre":"عن أنس بن مالك رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1947,"id":"h1947"}]},{"t":"quote","text":"أَنَّ حَمْزَةَ بْنَ عَمْرٍو الأَسْلَمِيَّ قَالَ لِلنَّبِيِّ صلى الله عليه وسلم أَأَصُومُ فِي السَّفَرِ وَكَانَ كَثِيرَ الصِّيَامِ. فَقَالَ «إِنْ شِئْتَ فَصُمْ، وَإِنْ شِئْتَ فَأَفْطِرْ»","src":"رواه البخاري ١٩٤٣","pre":"وعن عائشة رضي الله عنها:","links":[{"book":"mt_bukhari","num":1943,"id":"h1943"}]},{"t":"quote","text":"كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي سَفَرٍ، فَرَأَى زِحَامًا، وَرَجُلاً قَدْ ظُلِّلَ عَلَيْهِ، فَقَالَ «مَا هَذَا». فَقَالُوا صَائِمٌ. فَقَالَ «لَيْسَ مِنَ الْبِرِّ الصَّوْمُ فِي السَّفَرِ»","src":"رواه البخاري ١٩٤٦","pre":"وعن جابر بن عبد الله رضي الله عنهما قال:","links":[{"book":"mt_bukhari","num":1946,"id":"h1946"}]},{"t":"quote","text":"أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم خَرَجَ إِلَى مَكَّةَ فِي رَمَضَانَ فَصَامَ حَتَّى بَلَغَ الْكَدِيدَ أَفْطَرَ، فَأَفْطَرَ النَّاسُ","src":"رواه البخاري ١٩٤٤","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_bukhari","num":1944,"id":"h1944"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الثَّانِيَةُ: وَهِيَ هَلِ الصَّوْمُ أَفْضَلُ أَوِ الْفِطْرُ؟ إِذَا قُلْنَا: إِنَّهُ مِنْ أَهْلِ الْفِطَرِ عَلَى مَذْهَبِ الْجُمْهُورِ; فَإِنَّهُمُ اخْتَلَفُوا فِي ذَلِكَ عَلَى ثَلَاثَةِ مَذَاهِبَ: فَبَعْضُهُمْ رَأَى أَنَّ الصَّوْمَ أَفْضَلُ، وَمِمَّنْ قَالَ بِهَذَا الْقَوْلِ مَالِكٌ وَأَبُو حَنِيفَةَ.","src":"بداية المجتهد","loc":"٢/٥٨","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الأئمة الأربعة: إن الأفضل في السفر الصوم ويجوز الإفطار، وقال داود الظاهري: إن صوم رمضان في السفر باطل ويشير بعض الأحاديث إلى ما قال أي أن يكون الأصوب الإفطار، ولكن الأربعة حملوها على حال الجهد والمشقة","src":"العرف الشذي","loc":"٢/١٥٦","pre":"وقال الكشميري:"},{"t":"quote","text":"ثُمَّ الصَّوْمُ فِي السَّفَرِ أَفْضَلُ مِنْ الْإِفْطَارِ عِنْدَنَا، إذَا لَمْ يُجْهِدْهُ الصَّوْمُ وَلَمْ يُضْعِفْهُ","src":"بدائع الصنائع","loc":"٢/٩٦","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"والأفضل للمسافر سفر قصر أن يفطر، ولكنه لو صام أجزأه","src":"فتاوى اللجنة الدائمة","loc":"١٠/٣٨٣","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يجوز للمسافر سفرًا تقصر فيه الصلاة أن يفطر في رمضان ويقضي، سواء كان سفره شاقًّا أو مريحًا؛ لأن الرخصة معلقة بالسفر. والأفضل أن يفعل الأيسر عليه: فإن لم يشق عليه الصوم فالصوم أفضل، وهو قول أكثر الأئمة، لأنه أسرع في براءة الذمة وأنشط له مع الناس، وإن شق عليه فالفطر أفضل، بل يكره له الصوم مع المشقة الشديدة؛ لقوله ﷺ: «ليس من البر الصوم في السفر» فيمن رآه قد ظُلِّل عليه."},{"t":"p","text":"ومن نوى الصوم وهو مقيم ثم سافر في أثناء النهار، فالأحوط أن يتم صومه ذلك اليوم، وهو قول الأئمة الثلاثة، ومن أفطر فيه أخذ بقول أحمد ومن وافقه، ولا يفطر إلا بعد أن يفارق عمران بلده. ومن قدم من سفره نهارًا وهو مفطر فالأولى أن يمسك بقية يومه احترامًا للشهر، وعليه قضاء ذلك اليوم على كل حال."}],"refs":["البخاري ١٩٤٧","البخاري ١٩٤٣","البخاري ١٩٤٦","البخاري ١٩٤٤","بداية المجتهد (٢/٥٨)","بداية المجتهد (٢/٥٩)","العرف الشذي (٢/١٥٦)","بدائع الصنائع (٢/٩٦)","فتاوى اللجنة الدائمة (١٠/٣٨٣)"],"related":["المريض في رمضان: حد المرض المبيح للفطر، والمريض المزمن","قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر"],"alts":["الصيام في السفر","الفطر للمسافر","صيام المسافر بالطائرة","متى يفطر المسافر","القادم من السفر في رمضان"]},{"n":240,"bab":"الصيام","sub":"أهل الأعذار","title":"المريض في رمضان: حد المرض المبيح للفطر، والمريض المزمن","q":"ما المرض الذي يجوز معه الفطر؟ وهل يفطر من به صداع أو زكام خفيف؟ ومن قال له الطبيب إن الصوم يضره؟ والمريض بمرض مزمن لا يرجى شفاؤه كالسكري، ماذا يجب عليه؟","short":"أجمعوا على أن المريض الذي يشق عليه الصوم أو يضره يجوز له الفطر وعليه القضاء. واختلفوا في حد المرض: فقال مالك: هو الذي تلحق فيه مشقة، وقال أحمد: المرض الغالب، وقال قوم: كل ما يسمى مرضًا. والجمهور على أن الذي لا يرجى برؤه يطعم عن كل يوم مسكينًا، ولا قضاء عليه.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَـٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ","ref":"البقرة: ١٨٥"},{"t":"quote","text":"لَيْسَتْ بِمَنْسُوخَةٍ، هُوَ الشَّيْخُ الْكَبِيرُ وَالْمَرْأَةُ الْكَبِيرَةُ لاَ يَسْتَطِيعَانِ أَنْ يَصُومَا، فَلْيُطْعِمَانِ مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا","src":"رواه البخاري ٤٥٠٥","pre":"عن ابن عباس رضي الله عنهما في آية الفدية من سورة البقرة قال:","links":[{"book":"mt_bukhari","num":4505,"id":"h4505"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْمَرَضُ الَّذِي يَجُوزُ فِيهِ الْفِطْرُ، فَإِنَّهُمُ اخْتَلَفُوا فِيهِ أَيْضًا: فَذَهَبَ قَوْمٌ إِلَى أَنَّهُ الْمَرَضُ الَّذِي يَلْحَقُ مِنَ الصَّوْمِ فِيهِ مَشَقَّةٌ وَضَرُورَةٌ، وَبِهِ قَالَ مَالِكٌ. وَذَهَبَ قَوْمٌ إِلَى أَنَّهُ الْمَرَضُ الْغَالِبُ، وَبِهِ قَالَ أَحْمَدُ. وَقَالَ قَوْمٌ: إِذَا انْطَلَقَ عَلَيْهِ اسْمُ الْمَرِيضِ أَفْطَرَ","src":"بداية المجتهد","loc":"٢/٥٩","pre":"قال ابن رشد:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"المرض المبيح للفطر هو الذي يشق معه الصوم مشقة ظاهرة، أو يزيد بالصوم أو يتأخر شفاؤه، أو يخبر الطبيب الثقة أن الصوم يضره. فأما المرض اليسير الذي لا يتأثر بالصوم، كالزكام الخفيف والصداع اليسير، فلا يبيح الفطر. وإن خشي المريض على نفسه الهلاك أو الضرر الشديد وجب عليه الفطر؛ لأن الله تعالى يريد بعباده اليسر كما في الآية."},{"t":"p","text":"والمريض بمرض يرجى شفاؤه يفطر ويقضي بعد شفائه. والمريض بمرض مزمن لا يرجى شفاؤه، ويضره الصوم بقول الأطباء، كبعض مرضى السكري والكلى والقلب، يفطر ويطعم عن كل يوم مسكينًا، ولا قضاء عليه، كالشيخ الكبير. فإن شفاه الله بعد ذلك على خلاف المتوقع فلا يلزمه قضاء ما أطعم عنه على الأظهر. وليرجع المريض في تقدير ضرر الصوم إلى الطبيب المسلم الثقة."}],"refs":["البخاري ٤٥٠٥","بداية المجتهد (٢/٥٩)","بداية المجتهد (٢/٦٠)"],"related":["الشيخ الكبير والعاجز عن الصوم: الفدية ومقدارها","الصوم والفطر في السفر: أيهما أفضل؟ ومتى يفطر المسافر؟"],"alts":["فطر المريض","مريض السكري في رمضان","المرض المزمن والصيام","المريض الذي لا يرجى شفاؤه"]},{"n":241,"bab":"الصيام","sub":"أهل الأعذار","title":"الحامل والمرضع في رمضان: الفطر، والقضاء والفدية","q":"امرأة حامل أو مرضع تخاف على نفسها أو على ولدها من الصوم، فهل تفطر؟ وهل عليها القضاء فقط، أو الفدية، أو كلاهما؟","short":"أجمعوا على أن الحامل والمرضع إذا خافتا على أنفسهما أو على الولد جاز لهما الفطر. واختلفوا فيما يلزمهما: فقال أبو حنيفة وأصحابه: عليهما القضاء فقط، وقال الشافعي وأحمد: إن خافتا على الولد فعليهما القضاء والإطعام، وإن خافتا على أنفسهما فالقضاء فقط، وقال مالك: الحامل تقضي ولا تطعم، والمرضع تقضي وتطعم. وروي عن ابن عباس وابن عمر رضي الله عنهم: تطعمان ولا قضاء عليهما.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"إِنَّ اللَّهَ عَزَّ وَجَلَّ وَضَعَ عَنِ الْمُسَافِرِ شَطْرَ الصَّلاَةِ وَعَنِ الْمُسَافِرِ وَالْحَامِلِ وَالْمُرْضِعِ الصَّوْمَ أَوِ الصِّيَامَ","src":"رواه ابن ماجه ١٦٦٧","pre":"عن أنس بن مالك الكعبي رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_ibnmajah","num":1667,"id":"h1667"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَحَدُهَا: أَنَّهُمَا يُطْعِمَانِ وَلَا قَضَاءَ عَلَيْهِمَا، وَهُوَ مَرْوِيٌّ عَنِ ابْنِ عُمَرَ وَابْنِ عَبَّاسٍ. وَالْقَوْلُ الثَّانِي: أَنَّهُمَا يَقْضِيَانِ فَقَطْ وَلَا إِطْعَامَ عَلَيْهِمَا، وَهُوَ مُقَابِلُ الْأَوَّلِ، وَبِهِ قَالَ أَبُو حَنِيفَةَ وَأَصْحَابُهُ وَأَبُو ثَوْرٍ. وَالثَّالِثُ: أَنَّهُمَا يَقْضِيَانِ وَيُطْعِمَانِ، وَبِهِ قَالَ الشَّافِعِيُّ. وَالْقَوْلُ الرَّابِعُ: أَنَّ الْحَامِلَ تَقْضِي وَلَا تُطْعِمُ، وَالْمُرْضِعُ تَقْضِي وَتُطْعِمُ","src":"بداية المجتهد","loc":"٢/٦٢-٦٣","pre":"قال ابن رشد:"},{"t":"quote","text":"إن خشيت على ولدها يجوز لها الإفطار ولا فدية عليها بل القضاء","src":"العرف الشذي","loc":"٢/١٥٨","pre":"وقال الكشميري:"},{"t":"quote","text":"إنَّ اللَّهَ وَضَعَ عَنْ الْمُسَافِرِ شَطْرَ الصَّلَاةِ وَعَنْ الْحُبْلَى، وَالْمُرْضِعِ الصِّيَامَ» وَعَلَيْهِمَا الْقَضَاءُ وَلَا فِدْيَةَ عَلَيْهِمَا عِنْدَنَا","src":"بدائع الصنائع","loc":"٢/٩٧","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"quote","text":"أَرَأَيْتَ الْحَامِلَ وَالْمُرْضِعَ إذَا خَافَتَا عَلَى وَلَدَيْهِمَا فَأَفْطَرَتَا؟ فَقَالَ: تُطْعِمُ الْمُرْضِعُ وَتُفْطِرُ وَتَقْضِي إنْ خَافَتْ عَلَى وَلَدِهَا","src":"المدونة","loc":"١/٢٧٨","pre":"وفي «المدونة» من كتب المالكية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"إن خافت الحامل على نفسها أو جنينها من صوم رمضان أفطرت وعليها القضاء فقط، شأنها في ذلك شأن المريض الذي لا يقوى على الصوم أو يخشى منه على نفسه مضرة","src":"فتاوى اللجنة الدائمة","loc":"١٠/٢٢٠","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الحامل والمرضع إذا خافتا على أنفسهما أو على ولديهما أفطرتا، وعليهما القضاء فقط كالمريض، وهو قول الحنفية، واستحسنه ابن رشد؛ لأن النبي ﷺ قرنهما بالمسافر في وضع الصوم عنهم، والمسافر يقضي. ومن أرادت الاحتياط فقضت وأطعمت عن كل يوم مسكينًا إذا كان خوفها على الولد، أخذًا بقول الشافعي وأحمد، فحسن."},{"t":"p","text":"فإن تتابع عليها الحمل والرضاع سنوات فلم تقدر على القضاء، قضت متى قدرت، ولا يسقط عنها، ومن العلماء من رأى لها في هذه الحال أن تطعم ولا تقضي أخذًا بقول ابن عباس رضي الله عنهما، والقضاء أحوط."}],"refs":["ابن ماجه ١٦٦٧","بداية المجتهد (٢/٦٢-٦٣)","العرف الشذي (٢/١٥٨)","بدائع الصنائع (٢/٩٧)","المدونة (١/٢٧٨)","فتاوى اللجنة الدائمة (١٠/٢٢٠)","بداية المجتهد (٢/٦٣)"],"related":["المريض في رمضان: حد المرض المبيح للفطر، والمريض المزمن","قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر"],"alts":["صيام الحامل","صيام المرضع","فدية الحامل والمرضع","قضاء الحامل"]},{"n":242,"bab":"الصيام","sub":"أهل الأعذار","title":"الشيخ الكبير والعاجز عن الصوم: الفدية ومقدارها","q":"أبي شيخ كبير لا يستطيع الصيام، فماذا يجب عليه؟ وكم مقدار الفدية؟ وهل يجوز إخراجها نقودًا أو دفعة واحدة في أول الشهر أو آخره؟ ومن فقد عقله بالخرف؟","short":"أجمعوا على أن الشيخ الكبير والعجوز اللذين لا يقدران على الصيام لهما أن يفطرا. والجمهور، ومنهم أبو حنيفة والشافعي وأحمد، على أن عليهما الإطعام عن كل يوم مسكينًا، وقال مالك: يستحب لهما الإطعام ولا يجب. ومقدار الإطعام عند الحنفية نصف صاع من بر أو صاع من غيره، وعند مالك والشافعي مد، وعند أحمد مد من بر أو نصف صاع من غيره.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"أَيَّامًا مَّعْدُودَٰتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ ۚ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ","ref":"البقرة: ١٨٤"},{"t":"quote","text":"لَيْسَتْ بِمَنْسُوخَةٍ، هُوَ الشَّيْخُ الْكَبِيرُ وَالْمَرْأَةُ الْكَبِيرَةُ لاَ يَسْتَطِيعَانِ أَنْ يَصُومَا، فَلْيُطْعِمَانِ مَكَانَ كُلِّ يَوْمٍ مِسْكِينًا","src":"رواه البخاري ٤٥٠٥","pre":"عن ابن عباس رضي الله عنهما في هذه الآية قال:","links":[{"book":"mt_bukhari","num":4505,"id":"h4505"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الشَّيْخُ الْكَبِيرُ وَالْعَجُوزُ اللَّذَانِ لَا يَقْدِرَانِ عَلَى الصِّيَامِ: فَإِنَّهُمْ أَجْمَعُوا عَلَى أَنَّ لَهُمَا أَنْ يُفْطِرَا، وَاخْتَلَفُوا فِيمَا عَلَيْهِمَا إِذَا أَفْطَرَا، فَقَالَ قَوْمٌ: عَلَيْهِمَا الْإِطْعَامُ. وَقَالَ قَوْمٌ: لَيْسَ عَلَيْهِمَا إِطْعَامٌ. وَبِالْأَوَّلِ قَالَ الشَّافِعِيُّ وَأَبُو حَنِيفَةَ، وَبِالثَّانِي قَالَ مَالِكٌ إِلَّا أَنَّهُ اسْتَحَبَّهُ.","src":"بداية المجتهد","loc":"٢/٦٣","pre":"قال ابن رشد:"},{"t":"quote","text":"واعلم ان المشهور على الألسنة أن آية الفدية نسخت، وأقول إن الفدية ثابتة عند الكل وعندنا ستة مواضع، ولو قيل بنسخها فكيف تكون الفدية باقية","src":"العرف الشذي","loc":"٢/١٥٩","pre":"وقال الكشميري:"},{"t":"quote","text":"وَالشَّيْخُ الْفَانِي الَّذِي لَا يَقْدِرُ عَلَى الصِّيَامِ يُفْطِرُ وَيُطْعِمُ لِكُلِّ يَوْمٍ مِسْكِينًا كَمَا يُطْعِمُ فِي الْكَفَّارَاتِ وَالْأَصْلُ فِيهِ قَوْله تَعَالَى {وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ} البقرة: 184 قِيلَ مَعْنَاهُ: لَا يُطِيقُونَهُ، وَلَوْ قَدَرَ عَلَى الصَّوْمِ يَبْطُلُ حُكْمُ الْفِدَاءِ","src":"الهداية مع فتح القدير","loc":"٢/٣٥٦","pre":"جاء في «الهداية» للمرغيناني الحنفي مع «فتح القدير»:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الشيخ الكبير والمرأة الكبيرة اللذان لا يستطيعان الصوم، والمريض الذي لا يرجى برؤه، يفطران ويطعمان عن كل يوم مسكينًا، ولا قضاء عليهما؛ لقول ابن عباس رضي الله عنهما في الآية: «هو الشيخ الكبير والمرأة الكبيرة لا يستطيعان أن يصوما، فليطعمان مكان كل يوم مسكينًا»، وهو قول الجمهور."},{"t":"p","text":"ومقدار الفدية طعام مسكين عن كل يوم: نحو نصف صاع (قرابة كيلو ونصف) من غالب قوت البلد كالأرز، أو وجبة مشبعة، والاحتياط أن يكون نصف صاع. ويجوز أن يطعمها مسكينًا كل يوم، أو يجمعها في آخر الشهر فيطعم ثلاثين مسكينًا كما كان أنس رضي الله عنه يصنع، أو يعطيها لمسكين واحد أو أكثر، ولا يقدمها قبل دخول الأيام التي يفطرها. ومن أخرجها نقدًا أخذ بقول الحنفية في جواز القيمة، والطعام أولى."},{"t":"p","text":"وأما من فقد عقله بالخرف أو الإغماء الطويل فلا صيام عليه ولا فدية في الأيام التي لا يعقل فيها؛ لأنه غير مكلف."}],"refs":["البخاري ٤٥٠٥","بداية المجتهد (٢/٦٣)","العرف الشذي (٢/١٥٩)","الهداية مع فتح القدير (٢/٣٥٦)"],"related":["المريض في رمضان: حد المرض المبيح للفطر، والمريض المزمن","زكاة الفطر: مقدارها وجنسها، وإخراج القيمة فيها"],"alts":["فدية الصيام","صيام كبير السن","العاجز عن الصوم","مقدار الفدية","إطعام مسكين عن كل يوم"]},{"n":243,"bab":"الصيام","sub":"القضاء","title":"قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر","q":"علي أيام من رمضان، فهل يجب أن أقضيها متتابعة؟ وهل يجوز تأخيرها إلى شعبان؟ ومن أخرها حتى دخل رمضان التالي بلا عذر، فهل عليه شيء غير القضاء؟","short":"أجمعوا على وجوب قضاء ما أفطره المريض والمسافر ونحوهما. والجمهور على أنه لا يجب التتابع في القضاء بل يستحب، وأوجبه بعض السلف. ويجوز تأخيره ما لم يدخل رمضان التالي. واختلفوا فيمن أخره بلا عذر حتى دخل رمضان آخر: فقال مالك والشافعي وأحمد: عليه القضاء مع إطعام مسكين عن كل يوم، وقال أبو حنيفة وأصحابه: عليه القضاء فقط.","body":[{"t":"h","text":"الدليل من الكتاب والسنة"},{"t":"aya","text":"شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَـٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ","ref":"البقرة: ١٨٥"},{"t":"quote","text":"كَانَ يَكُونُ عَلَىَّ الصَّوْمُ مِنْ رَمَضَانَ، فَمَا أَسْتَطِيعُ أَنْ أَقْضِيَ إِلاَّ فِي شَعْبَانَ","src":"رواه البخاري ١٩٥٠","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1950,"id":"h1950"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْمَسْأَلَةُ الأُولَى: فَإِنَّ بَعْضَهُمْ أَوْجَبَ أَنْ يَكُونَ الْقَضَاءُ مُتَتَابِعًا عَلَى صِفَةِ الْأَدَاءِ، وَبَعْضَهُمْ لَمْ يُوجِبْ ذَلِكَ، وَهَؤُلَاءِ مِنْهُمْ مَنْ خَيَّرَ وَمِنْهُمْ مَنِ اسْتَحَبَّ التَّتَابُعَ، وَالْجَمَاعَةُ عَلَى تَرْكِ إِيجَابِ التَّتَابُعِ","src":"بداية المجتهد","loc":"٢/٦١","pre":"قال ابن رشد:"},{"t":"quote","text":"لو أخر قضاء رمضان إلى أن دخل رمضان الثاني فليس عليه عندنا إلا القضاء، وقال الشافعي: إنه مفرط إذا أخره إلى رمضان الثاني، ثم عن الشافعي روايتان؛ في رواية أنه يقضي ويفدي، وفي رواية أنه يقضي فقط","src":"العرف الشذي","loc":"٢/١٩٧","pre":"وقال الكشميري:"},{"t":"quote","text":"وَإِنْ أَخَّرَهُ حَتَّى دَخَلَ رَمَضَانُ آخَرُ صَامَ الثَّانِيَ لِأَنَّهُ فِي وَقْتِهِ وَقَضَى الْأَوَّلَ بَعْدَهُ لِأَنَّهُ وَقْتُ الْقَضَاءِ وَلَا فِدْيَةَ عَلَيْهِ","src":"الهداية مع فتح القدير","loc":"٢/٣٥٤","pre":"جاء في «الهداية» للمرغيناني الحنفي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"تأخير قضاء رمضان إلى رمضان التالي لا يجوز على المشهور عند أهل العلم، لأن عائشة رضي الله عنها قالت: «كان يكون عليّ الصوم من رمضان فلا أستطيع أن أقضيه إلا في شعبان» ، وهذا يدل على أن لا رخصة بعد رمضان الثاني، فإن فعل بدون عذر فهو آثم، وعليه أن يبادر القضاء بعد رمضان الثاني، واختلف العلماء هل يلزمه مع ذلك إطعام أو لا يلزمه؟ والصحيح أنه لا يلزمه إطعام","src":"مجموع فتاوى ابن عثيمين","loc":"١٩/٣٧٨","pre":"قال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"quote","text":"يجوز تأخير قضاء رمضان إلى شعبان ولو بلا عذر، لكن الأفضل التعجيل بالقضاء","src":"فتاوى اللجنة الدائمة","loc":"١٠/٣٣٨","pre":"وجاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يجب قضاء أيام رمضان التي أفطرها لعذر، ويجوز قضاؤها متفرقة؛ لإطلاق الآية في عدة من أيام أخر دون اشتراط التتابع، والتتابع والمبادرة أفضل. ويجوز تأخيره إلى شعبان لمن له عذر أو شغل، كما كانت عائشة رضي الله عنها تفعل، ولا يجوز تأخيره بلا عذر حتى يدخل رمضان التالي."},{"t":"p","text":"ومن أخره بلا عذر حتى دخل رمضان آخر أثم، وعليه التوبة والقضاء. وأما الإطعام مع القضاء فقد أفتى به جماعة من الصحابة رضي الله عنهم وهو قول الجمهور، ولم يثبت فيه حديث مرفوع، فمن أطعم مع القضاء عن كل يوم مسكينًا فقد احتاط، ومن اقتصر على القضاء فقد أخذ بقول الحنفية. ومن أخره لعذر مستمر، كمرض أو حمل أو رضاع، فليس عليه إلا القضاء بالاتفاق. ويجوز صيام النفل كالست من شوال قبل القضاء عند الجمهور، والأولى تقديم القضاء."}],"refs":["البخاري ١٩٥٠","بداية المجتهد (٢/٦١)","العرف الشذي (٢/١٩٧)","الهداية مع فتح القدير (٢/٣٥٤)","مجموع فتاوى ابن عثيمين (١٩/٣٧٨)","فتاوى اللجنة الدائمة (١٠/٣٣٨)"],"related":["من مات وعليه صيام: هل يصوم عنه وليه؟","الصوم والفطر في السفر: أيهما أفضل؟ ومتى يفطر المسافر؟"],"alts":["قضاء رمضان","تأخير القضاء","التتابع في القضاء","قضاء الصيام في شعبان","كفارة تأخير القضاء"]},{"n":244,"bab":"الصيام","sub":"القضاء","title":"من مات وعليه صيام: هل يصوم عنه وليه؟","q":"مات والدي وعليه أيام من رمضان لم يقضها، أو صيام نذر، فهل أصوم عنه؟ أو أطعم عنه؟","short":"أجمعوا على أن من أفطر لعذر ثم مات قبل أن يتمكن من القضاء فلا شيء عليه. واختلفوا فيمن تمكن ثم مات: فقال أبو حنيفة ومالك والشافعي في الجديد: لا يصوم عنه أحد، ويطعم عنه عن كل يوم مسكينًا، وعند مالك وأبي حنيفة إذا أوصى بذلك. وقال الشافعي في القديم وجماعة من أهل الحديث: يصوم عنه وليه. وقال أحمد: يصوم عنه وليه في النذر، ويطعم عنه في رمضان.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ مَاتَ وَعَلَيْهِ صِيَامٌ صَامَ عَنْهُ وَلِيُّهُ","src":"رواه البخاري ١٩٥٢","pre":"عن عائشة رضي الله عنها أن رسول الله ﷺ قال:","links":[{"book":"mt_bukhari","num":1952,"id":"h1952"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا إِذَا مَاتَ وَعَلَيْهِ صَوْمٌ فَإِنَّ قَوْمًا قَالُوا: لَا يَصُومُ أَحَدٌ عَنْ أَحَدٍ. وَقَوْمٌ قَالُوا: يَصُومُ عَنْهُ وَلَيُّهُ","src":"بداية المجتهد","loc":"٢/٦٢","pre":"قال ابن رشد:"},{"t":"quote","text":"وأما دليلنا فما في النسائي عن ابن عباس موقوفاً عليه: لا يصلي أحد عن أحد ولا يصوم أحد عن أحد، وكذلك عن ابن عمر في موطأ مالك ، وأخرج الطحاوي عن عائشة موقوفاً: لا يصلي أحد عن أحد ولا يصوم أحد عن أحد، وهي رواية حديث الباب المرفوع","src":"العرف الشذي","loc":"٢/١٣٢","pre":"وقال الكشميري:"},{"t":"quote","text":"وَإِنْ صَامَ أَوْ صَلَّى عَنْهُ الْوَلِيُّ لَا لِحَدِيثِ النَّسَائِيّ «لَا يَصُومُ أَحَدٌ عَنْ أَحَدٍ وَلَا يُصَلِّي أَحَدٌ عَنْ أَحَدٍ وَلَكِنْ يُطْعِمُ عَنْهُ وَلِيُّهُ»","src":"الدر المختار مع رد المحتار","loc":"٢/٤٢٥","pre":"جاء في «الدر المختار» من كتب الحنفية:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"وهكذا الصوم عن الميت إذا كان عليه صوم واجب سواء كان عن نذر أو كفارة أو عن صوم رمضان لعموم قوله صلى الله عليه وسلم: «من مات وعليه صيام صام عنه وليه » متفق على صحته، ولأحاديث أخرى في المعنى، لكن من تأخر في صوم رمضان بعذر شرعي كمرض أو سفر ثم مات قبل أن يتمكن من القضاء فلا قضاء عنه ولا إطعام لكونه معذورا","src":"مجموع فتاوى ابن باز","loc":"١/٢٥١","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"من أفطر لعذر ومات قبل التمكن من القضاء فلا شيء عليه ولا على ورثته. ومن تمكن من القضاء ففرّط حتى مات، فالأظهر أنه يُشرع لوليه أن يصوم عنه؛ لقوله ﷺ: «من مات وعليه صيام صام عنه وليه»، وهو حديث صحيح، وذلك على الاستحباب لا الوجوب، ويجوز أن يصوم عنه جماعة من أوليائه كل يوم واحد. فإن لم يصم عنه أحد أطعم عنه من تركته عن كل يوم مسكينًا، وهذا قول أكثر الأئمة."},{"t":"p","text":"وأما صيام النذر فيصوم عنه وليه باتفاق أكثر من قال بالصيام عن الميت، وهو قول أحمد. ومن أخذ بقول الحنفية والمالكية بالإطعام دون الصيام فله سلف من فتوى ابن عباس وعائشة رضي الله عنهم."}],"refs":["البخاري ١٩٥٢","بداية المجتهد (٢/٦٢)","العرف الشذي (٢/١٣٢)","الدر المختار مع رد المحتار (٢/٤٢٥)","مجموع فتاوى ابن باز (١/٢٥١)"],"related":["قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر","ما ينتفع به الميت: الدعاء والصدقة والصيام والحج، وقراءة القرآن وإهداء الثواب"],"alts":["الصيام عن الميت","قضاء صوم الميت","من مات وعليه صوم","الإطعام عن الميت"]},{"n":245,"bab":"الصيام","sub":"الكفارة","title":"الجماع في نهار رمضان وكفارته","q":"رجل جامع زوجته في نهار رمضان، فماذا عليه؟ وما الكفارة؟ وهل على المرأة كفارة؟ وإذا تكرر ذلك في أيام، فهل تتكرر الكفارة؟","short":"أجمعوا على أن من جامع في نهار رمضان عامدًا وهو صائم صومًا واجبًا فقد أفسد صومه وأثم، والجمهور على أن عليه القضاء والكفارة المغلظة: عتق رقبة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكينًا، على الترتيب عند الجمهور، وقال مالك: على التخيير، واستحب الإطعام. واختلفوا في المرأة المطاوعة: فقال أبو حنيفة ومالك: عليها الكفارة أيضًا، وقال الشافعي في المشهور: كفارة واحدة على الزوج. وأجمعوا على أن من وطئ مرارًا في يوم واحد فعليه كفارة واحدة، واختلفوا فيمن وطئ في يومين: فالجمهور على أن لكل يوم كفارة، وقال أبو حنيفة: كفارة واحدة ما لم يكفر.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ صلى الله عليه وسلم إِذْ جَاءَهُ رَجُلٌ، فَقَالَ يَا رَسُولَ اللَّهِ هَلَكْتُ. قَالَ «مَا لَكَ». قَالَ وَقَعْتُ عَلَى امْرَأَتِي وَأَنَا صَائِمٌ. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «هَلْ تَجِدُ رَقَبَةً تُعْتِقُهَا». قَالَ لاَ. قَالَ «فَهَلْ تَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ». قَالَ لاَ. فَقَالَ «فَهَلْ تَجِدُ إِطْعَامَ سِتِّينَ مِسْكِينًا». قَالَ لاَ. قَالَ فَمَكَثَ النَّبِيُّ صلى الله عليه وسلم، فَبَيْنَا نَحْنُ عَلَى ذَلِكَ أُتِيَ النَّبِيُّ صلى الله عليه وسلم بِعَرَقٍ فِيهَا تَمْرٌ ـ وَالْعَرَقُ الْمِكْتَلُ ـ قَالَ «أَيْنَ السَّائِلُ». فَقَالَ أَنَا. قَالَ «خُذْهَا فَتَصَدَّقْ بِهِ». فَقَالَ الرَّجُلُ أَعَلَى أَفْقَرَ مِنِّي يَا رَسُولَ اللَّهِ فَوَاللَّهِ مَا بَيْنَ لاَبَتَيْهَا ـ يُرِيدُ الْحَرَّتَيْنِ ـ أَهْلُ بَيْتٍ أَفْقَرُ مِنْ أَهْلِ بَيْتِي، فَضَحِكَ النَّبِيُّ صلى الله عليه وسلم حَتَّى بَدَتْ أَنْيَابُهُ ثُمَّ قَالَ «أَطْعِمْهُ أَهْلَكَ»","src":"رواه البخاري ١٩٣٦","pre":"عن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1936,"id":"h1936"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا مَنْ أَفْطَرَ بِجِمَاعٍ مُتَعَمِّدًا فِي رَمَضَانَ، فَإِنَّ الْجُمْهُورَ عَلَى أَنَّ الْوَاجِبَ عَلَيْهِ الْقَضَاءُ وَالْكَفَّارَةُ","src":"بداية المجتهد","loc":"٢/٦٤","pre":"قال ابن رشد:"},{"t":"quote","text":"فقال الثلاثة: إن الخصائل الثلاثة: بالترتيب كما في الحديث، وقال مالك: لا ترتيب بل العبد مخير بينهما","src":"العرف الشذي","loc":"٢/١٦٣","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"من جامع في نهار رمضان ممن يجب عليه الصوم وهو عالم بصومه، وأن الجماع فيه حرام والتقى الختانان وجبت عليه الكفارة مع القضاء ولو لم ينزل، ووجب عليه أن يتوب إلى الله، ويستغفره، فإنه ارتكب إثما كبيرا وذنبا عظيما","src":"فتاوى اللجنة الدائمة","loc":"١٠/٣٠٦","pre":"جاء في فتاوى اللجنة الدائمة:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"من جامع زوجته في نهار رمضان عامدًا مختارًا وهو صائم فقد ارتكب كبيرة، وعليه التوبة، وقضاء ذلك اليوم، والكفارة المغلظة على الترتيب الذي في الحديث: عتق رقبة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع لمرض أو كبر أو مشقة شديدة فإطعام ستين مسكينًا، لكل مسكين نصف صاع من قوت البلد. فإن عجز عن ذلك كله بقيت في ذمته يكفر متى قدر على الأظهر، وقيل: تسقط بالعجز."},{"t":"p","text":"والمرأة إن كانت مطاوعة فعليها التوبة والقضاء والكفارة على الأظهر، وهو قول أبي حنيفة ومالك ورواية عن أحمد؛ لأنها هتكت حرمة الصوم مثله، وإن كانت مكرهة فلا كفارة عليها وعليها القضاء. ومن جامع في أيام متعددة من رمضان فعليه لكل يوم كفارة عند الجمهور، والأحوط ذلك، ومن جامع مرارًا في يوم واحد فكفارة واحدة بالإجماع. ومن جامع ناسيًا، أو كان مسافرًا مفطرًا، أو في صيام قضاء أو نذر، فلا كفارة عليه."}],"refs":["البخاري ١٩٣٦","بداية المجتهد (٢/٦٤)","بداية المجتهد (٢/٦٨)","العرف الشذي (٢/١٦٣)","فتاوى اللجنة الدائمة (١٠/٣٠٦)","بداية المجتهد (٢/٦٧)"],"related":["الإفطار عمدًا في رمضان بالأكل والشرب: القضاء والكفارة","القبلة والمباشرة للصائم، والإنزال والمذي والاحتلام"],"alts":["كفارة الجماع في رمضان","الجماع في نهار رمضان","كفارة المرأة في رمضان","صيام شهرين متتابعين","إطعام ستين مسكينا"]},{"n":246,"bab":"الصيام","sub":"الكفارة","title":"الإفطار عمدًا في رمضان بالأكل والشرب: القضاء والكفارة","q":"شاب أفطر متعمدًا في رمضان بالأكل والشرب أيامًا بلا عذر، فماذا يجب عليه؟ هل عليه كفارة كفارة الجماع أو القضاء فقط؟","short":"أجمعوا على أن من أفطر عامدًا بلا عذر بأكل أو شرب فقد ارتكب كبيرة. واختلفوا فيما يلزمه: فقال أبو حنيفة ومالك وأصحابهما والثوري: عليه القضاء والكفارة كالمجامع، وقال الشافعي وأحمد: عليه القضاء فقط مع التوبة، ولا كفارة إلا في الجماع.","body":[{"t":"h","text":"الدليل"},{"t":"quote","text":"بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ النَّبِيِّ صلى الله عليه وسلم إِذْ جَاءَهُ رَجُلٌ، فَقَالَ يَا رَسُولَ اللَّهِ هَلَكْتُ. قَالَ «مَا لَكَ». قَالَ وَقَعْتُ عَلَى امْرَأَتِي وَأَنَا صَائِمٌ. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم «هَلْ تَجِدُ رَقَبَةً تُعْتِقُهَا». قَالَ لاَ. قَالَ «فَهَلْ تَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ». قَالَ لاَ. فَقَالَ «فَهَلْ تَجِدُ إِطْعَامَ سِتِّينَ مِسْكِينًا». قَالَ لاَ. قَالَ فَمَكَثَ النَّبِيُّ صلى الله عليه وسلم، فَبَيْنَا نَحْنُ عَلَى ذَلِكَ أُتِيَ النَّبِيُّ صلى الله عليه وسلم بِعَرَقٍ فِيهَا تَمْرٌ ـ وَالْعَرَقُ الْمِكْتَلُ ـ قَالَ «أَيْنَ السَّائِلُ». فَقَالَ أَنَا. قَالَ «خُذْهَا فَتَصَدَّقْ بِهِ». فَقَالَ الرَّجُلُ أَعَلَى أَفْقَرَ مِنِّي يَا رَسُولَ اللَّهِ فَوَاللَّهِ مَا بَيْنَ لاَبَتَيْهَا ـ يُرِيدُ الْحَرَّتَيْنِ ـ أَهْلُ بَيْتٍ أَفْقَرُ مِنْ أَهْلِ بَيْتِي، فَضَحِكَ النَّبِيُّ صلى الله عليه وسلم حَتَّى بَدَتْ أَنْيَابُهُ ثُمَّ قَالَ «أَطْعِمْهُ أَهْلَكَ»","src":"رواه البخاري ١٩٣٦","pre":"عن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1936,"id":"h1936"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْمَسْأَلَةُ الأُولَى: وَهِيَ هَلْ تَجِبُ الْكَفَّارَةُ بِالْإِفْطَارِ بِالْأَكْلِ وَالشُّرْبِ مُتَعَمَّدًا؟ فَإِنَّ مَالِكًا وَأَصْحَابَهُ وَأَبَا حَنِيفَةَ وَأَصْحَابَهُ وَالثَّوْرِيَّ وَجَمَاعَةً ذَهَبُوا إِلَى أَنَّ مَنْ أَفْطَرَ مُتَعَمِّدًا بِأَكْلٍ أَوْ شُرْبٍ أَنَّ عَلَيْهِ الْقَضَاءَ وَالْكَفَّارَةَ الْمَذْكُورَةَ فِي هَذَا الْحَدِيثِ. وَذَهَبَ الشَّافِعِيُّ وَأَحْمَدُ وَأَهْلُ الظَّاهِرِ إِلَى أَنَّ الْكَفَّارَةَ إِنَّمَا تَلْزَمُ فِي الْإِفْطَارِ مِنَ الْجِمَاعِ فَقَطْ","src":"بداية المجتهد","loc":"٢/٦٥","pre":"قال ابن رشد:"},{"t":"quote","text":"قال مالك وأبو حنيفة: إن الأكل والشرب عمداً أيضاً يوجب الكفارة، وقال الشافعي وأحمد: إن الكفارة مقتصرة على الجماع عمداً","src":"العرف الشذي","loc":"٢/١٦٢","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"من أفطر في رمضان متعمدًا بلا عذر بالأكل أو الشرب فقد أتى كبيرة من كبائر الذنوب، وعليه التوبة الصادقة، وقضاء ما أفطره، والإكثار من الاستغفار والعمل الصالح. وأما الكفارة فهي واجبة عند الحنفية والمالكية، لأنه انتهك حرمة الشهر كالمجامع، ولا تجب عند الشافعية والحنابلة لأن النص ورد في الجماع وحده، ولكل منهما دليله."},{"t":"p","text":"والأحوط لمن فعل ذلك، لا سيما من تعمد ذلك استهانة بالشهر، أن يكفر مع القضاء خروجًا من الخلاف، وأما من وقع في ذلك عن جهل أو تأويل فيكفيه القضاء والتوبة على قول الشافعي وأحمد. ومن أفطر أيامًا عمدًا ثم تاب قضى كل الأيام التي أفطرها."}],"refs":["البخاري ١٩٣٦","بداية المجتهد (٢/٦٥)","العرف الشذي (٢/١٦٢)"],"related":["الجماع في نهار رمضان وكفارته","قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر"],"alts":["الإفطار عمدا","من أفطر متعمدا في رمضان","كفارة الأكل في رمضان","التوبة من الإفطار"]},{"n":247,"bab":"الصيام","sub":"صيام التطوع","title":"صيام يوم عاشوراء وتاسوعاء، وصيام شهر المحرم","q":"ما فضل صيام يوم عاشوراء؟ وهل يصام التاسع معه؟ وهل يجوز إفراد العاشر بالصوم؟","short":"اتفق العلماء على استحباب صيام يوم عاشوراء، وهو العاشر من المحرم عند الجمهور، وذهب الحنفية وغيرهم إلى أن صوم عاشوراء كان فرضًا ثم نسخ فرضه وبقي استحبابه. ويستحب أن يصام التاسع معه مخالفة لأهل الكتاب، وكره الحنفية إفراد العاشر، ولم يكرهه آخرون. وأفضل الصيام بعد رمضان صيام شهر المحرم.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"وَصِيَامُ يَوْمِ عَاشُورَاءَ، أَحْتَسِبُ عَلَى اللهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ","src":"رواه مسلم ١١٦٢","pre":"عن أبي قتادة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1162,"id":"h1162"}]},{"t":"quote","text":"«لَئِنْ بَقِيتُ إِلَى قَابِلٍ لَأَصُومَنَّ التَّاسِعَ» وَفِي رِوَايَةِ أَبِي بَكْرٍ: قَالَ: يَعْنِي يَوْمَ عَاشُورَاءَ","src":"رواه مسلم ١١٣٤","pre":"وعن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1134,"id":"h1134-2"}]},{"t":"quote","text":"أَفْضَلُ الصِّيَامِ، بَعْدَ رَمَضَانَ، شَهْرُ اللهِ الْمُحَرَّمُ، وَأَفْضَلُ الصَّلَاةِ، بَعْدَ الْفَرِيضَةِ، صَلَاةُ اللَّيْلِ","src":"رواه مسلم ١١٦٣","pre":"وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1163,"id":"h1163"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"أَمَّا الْمُرَغَّبُ فِيهِ الْمُتَّفَقُ عَلَيْهِ: فَصِيَامُ يَوْمِ عَاشُورَاءَ","src":"بداية المجتهد","loc":"٢/٧٠","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الطحاوي: إن صوم عاشوراء في بدء الإسلام كان فرضاً ثم نسخ الفرضية وبقي الاستحباب وأثبته بالروايات","src":"العرف الشذي","loc":"٢/١٧٨","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"صيام يوم عاشوراء، العاشر من المحرم، سنة مؤكدة، يرجى أن يكفر الله به ذنوب السنة الماضية. والأفضل أن يصوم التاسع والعاشر معًا؛ لقوله ﷺ: «لئن بقيت إلى قابل لأصومن التاسع»، مخالفة لأهل الكتاب، فإن لم يتيسر فالعاشر والحادي عشر، ومن صام العاشر وحده فلا حرج عليه وله الأجر إن شاء الله، وإن كان الأولى ضم يوم إليه. ويستحب الإكثار من الصيام في شهر المحرم كله."},{"t":"p","text":"ولا يخص يوم عاشوراء بشيء من البدع، كالمآتم أو التوسعة الخاصة أو الاكتحال؛ فإن السنة فيه الصيام."}],"refs":["مسلم ١١٦٢","مسلم ١١٣٤","مسلم ١١٦٣","بداية المجتهد (٢/٧٠)","العرف الشذي (٢/١٧٨)"],"related":["صيام يوم عرفة لغير الحاج وللحاج","الأيام المنهي عن صيامها: العيدان وأيام التشريق"],"alts":["صيام عاشوراء","صيام تاسوعاء","فضل يوم عاشوراء","صيام المحرم","إفراد عاشوراء بالصوم"]},{"n":248,"bab":"الصيام","sub":"صيام التطوع","title":"صيام يوم عرفة لغير الحاج وللحاج","q":"ما فضل صيام يوم عرفة؟ وهل يصومه الحاج الواقف بعرفة؟ وإذا اختلف يوم عرفة بين بلدي ومكة، فمتى أصوم؟","short":"اتفقوا على استحباب صيام يوم عرفة لغير الحاج. واختلفوا في الحاج: فالجمهور على أن الفطر له أفضل اقتداء بالنبي ﷺ وتقويًا على الدعاء، وكره بعضهم صومه له، وأجازه بعض السلف لمن قوي عليه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"صِيَامُ يَوْمِ عَرَفَةَ، أَحْتَسِبُ عَلَى اللهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ، وَالسَّنَةَ الَّتِي بَعْدَهُ","src":"رواه مسلم ١١٦٢","pre":"عن أبي قتادة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1162,"id":"h1162"}]},{"t":"quote","text":"أَنَّ النَّبِيَّ صلى الله عليه وسلم أَفْطَرَ بِعَرَفَةَ وَأَرْسَلَتْ إِلَيْهِ أُمُّ الْفَضْلِ بِلَبَنٍ فَشَرِبَ","src":"رواه الترمذي ٧٥٠","pre":"وعن ابن عباس رضي الله عنهما:","links":[{"book":"mt_tirmidhi","num":750,"id":"h750"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا اخْتِلَافُهُمْ فِي يَوْمِ عَرَفَةَ، فَلِأَنَّ النَّبِيَّ - عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ - أَفْطَرَ يَوْمَ عَرَفَةَ، وَقَالَ فِيهِ: «صِيَامُ يَوْمِ عَرَفَةَ يُكَفِّرُ السَّنَةَ الْمَاضِيَةَ وَالْآتِيَةَ» . وَلِذَلِكَ اخْتَلَفَ النَّاسُ فِي ذَلِكَ، وَاخْتَارَ الشَّافِعِيُّ الْفِطْرَ فِيهِ لِلْحَاجِّ، وَصِيَامَهُ لِغَيْرِ الْحَاجِّ جَمْعًا بَيْنَ الْأَثَرَيْنِ.","src":"بداية المجتهد","loc":"٢/٧٠-٧١","pre":"قال ابن رشد:"},{"t":"quote","text":"وَأَمَّا صَوْمُ يَوْمِ عَرَفَةَ: فَفِي حَقِّ غَيْرِ الْحَاجِّ مُسْتَحَبٌّ، لِكَثْرَةِ الْأَحَادِيثِ الْوَارِدَةِ بِالنَّدْبِ إلَى صَوْمِهِ، وَلِأَنَّ لَهُ فَضِيلَةً عَلَى غَيْرِهِ مِنْ الْأَيَّامِ، وَكَذَلِكَ فِي حَقِّ الْحَاجِّ إنْ كَانَ لَا يُضْعِفُهُ عَنْ الْوُقُوفِ، وَالدُّعَاءِ لِمَا فِيهِ مِنْ الْجَمْعِ بَيْنَ الْقُرْبَتَيْنِ وَإِنْ كَانَ يُضْعِفُهُ عَنْ ذَلِكَ يُكْرَهُ لِأَنَّ فَضِيلَةَ صَوْمِ هَذَا الْيَوْمِ مِمَّا يُمْكِنُ اسْتِدْرَاكُهَا فِي غَيْرِ هَذِهِ السَّنَةِ، وَيُسْتَدْرَكُ عَادَةً","src":"بدائع الصنائع","loc":"٢/٧٩","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"quote","text":"ويستحب لغير الحاج ان يصوم يوم عرفة لما روى أبو قتادة قَالَ \" قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وسلم صوم عاشوراء كفارة سنة وصوم يوم عرفة كفارة سنتين سنة قبلها ماضية وسنة بعدها مستقبلة\"","src":"المجموع","loc":"٦/٣٧٩","pre":"وفي «المهذب» للشيرازي الشافعي مع «المجموع»:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صوم يوم عرفة مستقل، وله فضل عظيم يكفر الله به السنة التي قبله والسنة التي بعده أما الحاج فلا يجوز له أن يصوم يوم عرفة؛ لأن النبي صلى الله عليه وسلم وقف في ذلك اليوم وهو مفطر","src":"مجموع فتاوى ابن باز","loc":"١٥/٤٠٥","pre":"وقال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"صيام يوم عرفة، التاسع من ذي الحجة، سنة مؤكدة لغير الحاج، يرجى أن يكفر الله به ذنوب سنتين: الماضية والباقية. وأما الحاج الواقف بعرفة فالسنة له الفطر؛ لأن النبي ﷺ أفطر بعرفة، وليتقوى على الذكر والدعاء."},{"t":"p","text":"ويصوم المسلم يوم عرفة بحسب التاسع من ذي الحجة في بلده الذي يصوم ويعيد مع أهله، لأنه يوم معين من الشهر، وهذا جارٍ على الخلاف في اختلاف المطالع؛ ومن صام اليوم الذي يقف فيه الحجاج بعرفة إذا كان هو التاسع أو الثامن عنده فلا حرج، إلا أن يوافق يوم العيد في بلده فلا يصومه."}],"refs":["مسلم ١١٦٢","الترمذي ٧٥٠","بداية المجتهد (٢/٧٠-٧١)","بدائع الصنائع (٢/٧٩)","المجموع (٦/٣٧٩)","مجموع فتاوى ابن باز (١٥/٤٠٥)"],"related":["صيام يوم عاشوراء وتاسوعاء، وصيام شهر المحرم","صيام شعبان، والنصف الثاني منه، وعشر ذي الحجة","اختلاف المطالع: هل يلزم أهل البلاد كلها الصوم برؤية بلد واحد؟"],"alts":["صيام يوم عرفة","فضل يوم عرفة","صيام الحاج يوم عرفة","يوم عرفة في البلاد المختلفة"]},{"n":249,"bab":"الصيام","sub":"صيام التطوع","title":"صيام ست من شوال: فضلها، وتتابعها، وتقديمها على القضاء","q":"ما فضل صيام الست من شوال؟ وهل يجب أن تكون متتابعة بعد العيد مباشرة؟ ومن عليها قضاء من رمضان، هل تصوم الست قبل القضاء؟ وهل يجوز الجمع بين نية القضاء والست؟","short":"استحب صيام ست من شوال أبو حنيفة في المختار عند أصحابه، والشافعي وأحمد وجمهور العلماء، وكرهه مالك خشية أن يظن الجهال أنها من رمضان، ونقل عن أبي حنيفة كراهتها متصلة بالعيد. ويجوز صيامها متتابعة ومتفرقة في الشهر كله، واستحب أبو يوسف تفريقها، واستحب الشافعية تتابعها عقب العيد.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ، كَانَ كَصِيَامِ الدَّهْرِ","src":"رواه مسلم ١١٦٤","pre":"عن أبي أيوب الأنصاري رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_muslim","num":1164,"id":"h1164"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا السِّتُّ مِنْ شَوَّالٍ، فَإِنَّهُ ثَبَتَ أَنَّ رَسُولَ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: «مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ» إِلَّا أَنَّ مَالِكًا كَرِهَ ذَلِكَ، إِمَّا مَخَافَةَ أَنْ يُلْحِقَ النَّاسُ بِرَمَضَانَ مَا لَيْسَ فِي رَمَضَانَ، وَإِمَّا لِأَنَّهُ لَعَلَّهُ لَمْ يَبْلُغْهُ الْحَدِيثُ أَوْ لَمْ يَصِحَّ عِنْدَهُ وَهُوَ الْأَظْهَرُ","src":"بداية المجتهد","loc":"٢/٧١","pre":"قال ابن رشد:"},{"t":"quote","text":"قال أبو يوسف: يستحب ستة أيام متفرقاً ويجوز متوالياً أيضاً","src":"العرف الشذي","loc":"٢/١٨١","pre":"وقال الكشميري:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"صيام ست من شوال سنة وليست فريضة؛ لقول النبي صلى الله عليه وسلم: «من صام رمضان ثم أتبعه ستا من شوال كان كصيام الدهر » خرجه الإمام مسلم في صحيحه","src":"مجموع فتاوى ابن باز","loc":"٥/٤١٧","pre":"قال الشيخ عبد العزيز بن باز رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"صيام ست من شوال سنة مستحبة لمن صام رمضان؛ لحديث أبي أيوب رضي الله عنه، ومعناه أن الحسنة بعشر أمثالها، فرمضان بعشرة أشهر، والست بشهرين. ويجوز صيامها متتابعة أو متفرقة في أي أيام شوال بعد يوم العيد، والمبادرة بها أفضل."},{"t":"p","text":"ومن عليه قضاء من رمضان فالأولى أن يقضي أولًا ثم يصوم الست، لقوله ﷺ: «من صام رمضان ثم أتبعه»، ومن لم يكمل رمضان لم يصمه بعدُ كله؛ فإن ضاق شوال، كالمرأة التي أفطرت أيامًا كثيرة لنفاس أو حيض، جاز عند الجمهور تقديم الست ثم القضاء بعدها، ويرجى لها الأجر. ولا يصح الجمع بين نية القضاء ونية الست في يوم واحد على الأظهر؛ لأن كلًّا منهما عبادة مقصودة."}],"refs":["مسلم ١١٦٤","بداية المجتهد (٢/٧١)","العرف الشذي (٢/١٨١)","مجموع فتاوى ابن باز (٥/٤١٧)"],"related":["قضاء رمضان: وقته، والتتابع فيه، وتأخيره إلى رمضان آخر"],"alts":["ست من شوال","الست البيض","صيام شوال","الست قبل القضاء"]},{"n":250,"bab":"الصيام","sub":"صيام التطوع","title":"صيام الاثنين والخميس، وثلاثة أيام من كل شهر، وصيام داود، وصوم الدهر","q":"ما أفضل صيام التطوع المتكرر؟ وما الأيام البيض؟ وهل يجوز أن أصوم كل يوم من السنة غير الأيام المحرمة؟","short":"اتفقوا على استحباب صيام الاثنين والخميس، وصيام ثلاثة أيام من كل شهر، واستحب أكثرهم أن تكون الأيام البيض: الثالث عشر والرابع عشر والخامس عشر، وكره مالك تحري الغرر خشية ظن وجوبها. وأفضل صيام التطوع صيام داود عليه السلام: يوم ويوم. واختلفوا في صوم الدهر مع إفطار الأيام المنهي عنها: فكرهه الحنفية تنزيهًا وجماعة، وأجازه مالك والشافعي لمن لا يضره ولا يفوت به حقًّا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"تُعْرَضُ الأَعْمَالُ يَوْمَ الاِثْنَيْنِ وَالْخَمِيسِ فَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ","src":"رواه الترمذي ٧٤٧","pre":"عن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_tirmidhi","num":747,"id":"h747"}]},{"t":"quote","text":"أَوْصَانِي خَلِيلِي صلى الله عليه وسلم بِثَلاَثٍ صِيَامِ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَرَكْعَتَىِ الضُّحَى، وَأَنْ أُوتِرَ قَبْلَ أَنْ أَنَامَ","src":"رواه البخاري ١٩٨١","pre":"وعن أبي هريرة رضي الله عنه قال:","links":[{"book":"mt_bukhari","num":1981,"id":"h1981"}]},{"t":"quote","text":"أَحَبَّ الصِّيَامِ إِلَى اللهِ، صِيَامُ دَاوُدَ، وَأَحَبَّ الصَّلَاةِ إِلَى اللهِ، صَلَاةُ دَاوُدَ عَلَيْهِ السَّلَام، كَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ، وَكَانَ يَصُومُ يَوْمًا، وَيُفْطِرُ يَوْمًا","src":"رواه مسلم ١١٥٩","pre":"وعن عبد الله بن عمرو رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1159,"id":"h1159-9"}]},{"t":"quote","text":"لاَ صَامَ مَنْ صَامَ الأَبَدَ","src":"رواه البخاري ١٩٧٧","pre":"وقال ﷺ:","links":[{"book":"mt_bukhari","num":1977,"id":"h1977"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَكَذَلِكَ كَرِهَ مَالِكٌ تَحَرِّيَ صِيَامِ الْغُرَرِ مَعَ مَا جَاءَ فِيهَا مِنَ الْأَثَرِ مَخَافَةَ أَنْ يَظُنَّ الْجُهَّالُ بِهَا أَنَّهَا وَاجِبَةٌ","src":"بداية المجتهد","loc":"٢/٧١","pre":"قال ابن رشد:"},{"t":"quote","text":"قال الحجازيون: إن صوم الدهر وصوم داود متساويان، وفي كتب الحنفية أن صوم الدهر مكروه تنزيهاً، أقول: إن صوم داود أفضل من صوم الدهر","src":"العرف الشذي","loc":"٢/١٨٥","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يستحب للمسلم أن يكون له نصيب دائم من صيام التطوع، وأيسره ثلاثة أيام من كل شهر، والأفضل أن تكون الأيام البيض، ويستحب صيام الاثنين والخميس، فإن الأعمال تعرض فيهما. وأفضل التطوع صيام داود عليه السلام: يصوم يومًا ويفطر يومًا، لمن قوي عليه."},{"t":"p","text":"وأما صوم الدهر، أي صيام كل الأيام سوى المنهي عنها، فالأولى تركه؛ لقوله ﷺ: «لا صام من صام الأبد»، ولأن صيام داود أفضل منه بنص الحديث، ومن صامه وهو لا يضعف به عن واجب ولا يضيع حقًّا فقد أجازه بعض الأئمة. وليكن التطوع بما يداوم عليه المسلم، فأحب الأعمال إلى الله أدومها وإن قل."}],"refs":["الترمذي ٧٤٧","البخاري ١٩٨١","مسلم ١١٥٩","البخاري ١٩٧٧","بداية المجتهد (٢/٧١)","بداية المجتهد (٢/٧٣)","العرف الشذي (٢/١٨٥)"],"related":["صيام ست من شوال: فضلها، وتتابعها، وتقديمها على القضاء","إفراد يوم الجمعة أو السبت بالصيام"],"alts":["صيام الاثنين والخميس","الأيام البيض","صيام داود","صوم الدهر","ثلاثة أيام من كل شهر"]},{"n":251,"bab":"الصيام","sub":"الأيام المنهي عنها","title":"الأيام المنهي عن صيامها: العيدان وأيام التشريق","q":"هل يجوز صيام يوم العيد لمن عليه قضاء أو نذر؟ وما حكم صيام أيام التشريق؟","short":"أجمعوا على تحريم صيام يوم عيد الفطر ويوم عيد الأضحى، فرضًا كان أو نفلًا أو نذرًا. واختلفوا في أيام التشريق، وهي الثلاثة بعد عيد الأضحى: فمنع صيامها أهل الظاهر وأكثر العلماء، وكرهها مالك وأجازها للمتمتع الذي لم يجد الهدي، وهو قول أحمد في رواية، وعند الحنفية يكره صيامها تحريمًا.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"نَهَى عَنْ صِيَامِ يَوْمَيْنِ يَوْمِ الْأَضْحَى، وَيَوْمِ الْفِطْرِ","src":"رواه مسلم ١١٣٨","pre":"عن أبي سعيد الخدري رضي الله عنه أن رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1138,"id":"h1138"}]},{"t":"quote","text":"أَيَّامُ التَّشْرِيقِ أَيَّامُ أَكْلٍ وَشُرْبٍ","src":"رواه مسلم ١١٤١","pre":"وعن نبيشة الهذلي رضي الله عنه قال: قال رسول الله ﷺ:","links":[{"book":"mt_muslim","num":1141,"id":"h1141"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا الْأَيَّامُ الْمَنْهِيُّ عَنْهَا: فَمِنْهَا أَيْضًا مُتَّفَقٌ عَلَيْهَا، وَمِنْهَا مُخْتَلَفٌ فِيهَا. أَمَّا الْمُتَّفَقُ عَلَيْهَا: فَيَوْمُ الْفِطْرِ، وَيَوْمُ الْأَضْحَى ; لِثُبُوتِ النَّهْيِ عَنْ صِيَامِهِمَا. وَأَمَّا الْمُخْتَلَفُ فِيهَا: فَأَيَّامُ التَّشْرِيقِ، فَإِنَّ أَهْلَ الظَّاهِرِ لَمْ يُجِيزُوا الصَّوْمَ فِيهَا","src":"بداية المجتهد","loc":"٢/٧١-٧٢","pre":"قال ابن رشد:"},{"t":"quote","text":"صيام الأيام الخمسة مكروه تحريماً عندنا، والمكروه تحريماً قريب من الحرام أو حرام كما قال محمد، وقال الحجازيون: إن صوم الخمسة حرام","src":"العرف الشذي","loc":"٢/١٨٧","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يحرم صيام يومي العيدين بالإجماع، ولا يصح فيهما فرض ولا نفل ولا نذر. ويحرم صيام أيام التشريق الثلاثة (الحادي عشر والثاني عشر والثالث عشر من ذي الحجة)؛ لقوله ﷺ: «أيام التشريق أيام أكل وشرب»، إلا للحاج المتمتع أو القارن الذي لم يجد الهدي، فله أن يصومها عن الأيام الثلاثة الواجبة في الحج، كما ثبت عن ابن عمر وعائشة رضي الله عنهم، وهو قول مالك والشافعي في القديم وأحمد في رواية."}],"refs":["مسلم ١١٣٨","مسلم ١١٤١","بداية المجتهد (٢/٧١-٧٢)","العرف الشذي (٢/١٨٧)","بداية المجتهد (٢/٧٢)"],"related":["صيام يوم عرفة لغير الحاج وللحاج","إفراد يوم الجمعة أو السبت بالصيام"],"alts":["صيام يوم العيد","صيام أيام التشريق","الأيام المحرم صومها","صيام أيام منى"]},{"n":252,"bab":"الصيام","sub":"الأيام المنهي عنها","title":"إفراد يوم الجمعة أو السبت بالصيام","q":"هل يجوز أن أصوم يوم الجمعة وحده لأنه يوم إجازتي؟ وما حكم صيام يوم السبت؟ وإذا وافق يوم عرفة أو عاشوراء يوم الجمعة أو السبت فهل أصومه؟","short":"اختلفوا في صوم يوم الجمعة: فلم يكرهه مالك وأصحابه، واستحبه بعض الحنفية، وكره الشافعي وأحمد إفراده بالصوم إلا أن يصوم يومًا قبله أو بعده، أو يوافق عادة له. واختلفوا في يوم السبت لاختلافهم في تصحيح حديث النهي عن صيامه: فكره بعضهم إفراده، ولم يكرهه آخرون.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لاَ يَصُومَنَّ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ، إِلاَّ يَوْمًا قَبْلَهُ أَوْ بَعْدَهُ","src":"رواه البخاري ١٩٨٥","pre":"عن أبي هريرة رضي الله عنه قال: سمعت النبي ﷺ يقول:","links":[{"book":"mt_bukhari","num":1985,"id":"h1985"}]},{"t":"quote","text":"لاَ تَصُومُوا يَوْمَ السَّبْتِ إِلاَّ فِيمَا افْتَرَضَ اللَّهُ عَلَيْكُمْ فَإِنْ لَمْ يَجِدْ أَحَدُكُمْ إِلاَّ لِحَاءَ عِنَبَةٍ أَوْ عُودَ شَجَرَةٍ فَلْيَمْضُغْهُ","src":"رواه الترمذي ٧٤٤","pre":"وعن الصماء بنت بسر رضي الله عنها أن رسول الله ﷺ قال:","links":[{"book":"mt_tirmidhi","num":744,"id":"h744"}]},{"t":"p","text":"قال الترمذي: هذا حديث حسن، ومعنى كراهته أن يخص الرجل يوم السبت بصيام؛ لأن اليهود تعظمه. وقد ضعفه جماعة من الحفاظ أو حكموا عليه بالشذوذ."},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا يَوْمُ الْجُمُعَةِ: فَإِنَّ قَوْمًا لَمْ يَكْرَهُوا صِيَامَهُ، وَمِنْ هَؤُلَاءِ مَالِكٌ وَأَصْحَابُهُ وَجَمَاعَةٌ، وَقَوْمٌ كَرِهُوا صِيَامَهُ إِلَّا أَنْ يُصَامَ قَبْلَهُ أَوْ بَعْدَهُ","src":"بداية المجتهد","loc":"٢/٧٢","pre":"قال ابن رشد:"},{"t":"quote","text":"يستحب صوم يوم الجمعة كما في الدر المختار ص (89) إلا أن المحشِّين ترددوا في الاستحباب، وعندي: إن كان يتوهم فساد الاعتقاد لا يصوم، وإلا فيستحب وهكذا يجمع في الروايات الفقهية والحديثية","src":"العرف الشذي","loc":"٢/١٧٣","pre":"وقال الكشميري:"},{"t":"quote","text":"وَكَرِهَ بَعْضُهُمْ صَوْمَ يَوْمِ الْجُمُعَةِ بِانْفِرَادِهِ، وَكَذَا يَوْمُ الِاثْنَيْنِ، وَالْخَمِيسِ، وَقَالَ عَامَّتُهُمْ: إنَّهُ مُسْتَحَبٌّ لِأَنَّ هَذِهِ الْأَيَّامَ مِنْ الْأَيَّامِ الْفَاضِلَةِ فَكَانَ تَعْظِيمُهَا بِالصَّوْمِ مُسْتَحَبًّا، وَيُكْرَهُ صَوْمُ يَوْمِ السَّبْتِ بِانْفِرَادِهِ، لِأَنَّهُ تَشَبُّهٌ بِالْيَهُودِ","src":"بدائع الصنائع","loc":"٢/٧٩","pre":"قال الكاساني الحنفي رحمه الله:"},{"t":"quote","text":"ويكره أن يصوم يوم الجمعة وحده فان وصله بيوم قبله أو بيوم بعده لم يكره","src":"المجموع","loc":"٦/٤٣٦","pre":"وفي «المهذب» للشيرازي الشافعي:"},{"t":"h","text":"من فتاوى العلماء المعاصرين"},{"t":"quote","text":"بل ينهى الإنسان أن يصوم يوم الجمعة على وجه التخصيص لهذا اليوم، أما إذا كان من عادته أن يصوم يوماً ويفطر يوماً، فصادف يوم صومه يوم الجمعة فلا بأس، وكذلك لو كان عليه قضاء من رمضان ولا يفرغ لصوم القضاء إلا يوم الجمعة فلا بأس؛ لأنه لم يخصصه","src":"مجموع فتاوى ابن عثيمين","loc":"١٦/٣١","pre":"وقال الشيخ محمد بن صالح العثيمين رحمه الله:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أنه يكره إفراد يوم الجمعة بصيام التطوع قصدًا لتخصيصه؛ لنهي النبي ﷺ عن ذلك إلا أن يصوم يومًا قبله أو يومًا بعده، وهو قول الشافعي وأحمد. فإن وافق صومًا له سبب، كيوم عرفة أو عاشوراء، أو كان من عادته صيام يوم وإفطار يوم، أو كان قضاء، فلا كراهة."},{"t":"p","text":"وأما يوم السبت فالأظهر أنه لا يكره صيامه إذا صام معه غيره، أو وافق صومًا مشروعًا كعرفة أو عاشوراء أو الأيام البيض، وإنما يكره من كرهه إفراده تطوعًا مطلقًا تعظيمًا له."}],"refs":["البخاري ١٩٨٥","الترمذي ٧٤٤","بداية المجتهد (٢/٧٢)","العرف الشذي (٢/١٧٣)","بدائع الصنائع (٢/٧٩)","المجموع (٦/٤٣٦)","مجموع فتاوى ابن عثيمين (١٦/٣١)"],"related":["صيام الاثنين والخميس، وثلاثة أيام من كل شهر، وصيام داود، وصوم الدهر","الأيام المنهي عن صيامها: العيدان وأيام التشريق"],"alts":["صيام يوم الجمعة","إفراد الجمعة بالصوم","صيام يوم السبت","صيام عرفة يوم الجمعة"]},{"n":253,"bab":"الصيام","sub":"صيام التطوع","title":"صيام شعبان، والنصف الثاني منه، وعشر ذي الحجة","q":"هل يستحب الإكثار من الصيام في شعبان؟ وما حكم الصيام بعد النصف من شعبان؟ وهل يستحب صيام التسع الأولى من ذي الحجة؟","short":"يستحب الإكثار من الصيام في شعبان باتفاق. واختلفوا في الصيام بعد نصف شعبان لمن لم يصم قبله: فكرهه الشافعية وجماعة لحديث «إذا انتصف شعبان فلا تصوموا»، ولم يكرهه الجمهور، وضعفوا الحديث. ويستحب صيام التسع الأولى من ذي الحجة أو ما تيسر منها عند جمهور العلماء.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"لَمْ يَكُنِ النَّبِيُّ صلى الله عليه وسلم يَصُومُ شَهْرًا أَكْثَرَ مِنْ شَعْبَانَ، فَإِنَّهُ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ","src":"رواه البخاري ١٩٧٠","pre":"عن عائشة رضي الله عنها قالت:","links":[{"book":"mt_bukhari","num":1970,"id":"h1970"}]},{"t":"quote","text":"إِذَا انْتَصَفَ شَعْبَانُ فَلاَ تَصُومُوا","src":"رواه أبو داود ٢٣٣٧","pre":"وعن أبي هريرة رضي الله عنه أن رسول الله ﷺ قال:","links":[{"book":"mt_abudawud","num":2337,"id":"h2337"}]},{"t":"quote","text":"مَا مِنْ أَيَّامٍ الْعَمَلُ الصَّالِحُ فِيهَا أَحَبُّ إِلَى اللَّهِ مِنْ هَذِهِ الأَيَّامِ «. يَعْنِي أَيَّامَ الْعَشْرِ . قَالُوا يَا رَسُولَ اللَّهِ وَلاَ الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ» وَلاَ الْجِهَادُ فِي سَبِيلِ اللَّهِ إِلاَّ رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَىْءٍ","src":"رواه أبو داود ٢٤٣٨","pre":"وعن ابن عباس رضي الله عنهما قال: قال رسول الله ﷺ:","links":[{"book":"mt_abudawud","num":2438,"id":"h2438"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا صِيَامُ النِّصْفِ الْآخِرِ مِنْ شَعْبَانَ: فَإِنَّ قَوْمًا كَرِهُوهُ، وَقَوْمًا أَجَازُوهُ","src":"بداية المجتهد","loc":"٢/٧٣","pre":"قال ابن رشد:"},{"t":"quote","text":"أي لمعنى رمضان ورعاية رمضان، هذا الحديث في حق من يصوم بعد نصف شعبان، وأما فعله عليه الصلاة والسلام المار فكان النبي - صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - يأخذ في الصوم قبل نصف شعبان","src":"العرف الشذي","loc":"٢/١٧١","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"يستحب الإكثار من الصيام في شعبان اقتداء بالنبي ﷺ، فقد كان يصوم أكثره. ومن كان له عادة صيام، أو بدأ الصيام قبل النصف ووصله، أو عليه قضاء، صام بعد النصف بلا كراهة. ومن لم يكن صائمًا قبل النصف فالأولى أن لا يبتدئ التطوع بعده، خروجًا من خلاف من كرهه، لا سيما في اليومين الأخيرين قبل رمضان فإنه منهي عنه بالاتفاق إلا لمن له عادة."},{"t":"p","text":"ويستحب صيام الأيام التسعة الأولى من ذي الحجة أو ما تيسر منها؛ لأنها أفضل أيام السنة للعمل الصالح، والصيام من أفضل العمل، وآكدها يوم عرفة لغير الحاج."}],"refs":["البخاري ١٩٧٠","أبو داود ٢٣٣٧","أبو داود ٢٤٣٨","بداية المجتهد (٢/٧٣)","العرف الشذي (٢/١٧١)"],"related":["صوم يوم الشك، وتقدم رمضان بصوم يوم أو يومين","صيام يوم عرفة لغير الحاج وللحاج"],"alts":["صيام شعبان","الصيام بعد نصف شعبان","صيام عشر ذي الحجة","صيام تسع ذي الحجة"]},{"n":254,"bab":"الصيام","sub":"صيام التطوع","title":"قطع صوم التطوع وقضاؤه، وصوم المرأة تطوعًا بغير إذن زوجها","q":"صمت تطوعًا ثم دعيت إلى طعام أو شق علي الصوم، فهل يجوز أن أفطر؟ وهل يجب علي القضاء؟ وهل تصوم المرأة تطوعًا بغير إذن زوجها؟","short":"أجمعوا على أن من قطع صوم التطوع لعذر فلا قضاء عليه عند الجمهور. واختلفوا فيمن قطعه بغير عذر: فقال مالك وأبو حنيفة: يلزمه بالشروع، وعليه القضاء، وعند أبي حنيفة القضاء مطلقًا ولو بعذر، وقال الشافعي وأحمد: لا قضاء عليه ويستحب. ولا يجوز للمرأة أن تصوم تطوعًا وزوجها حاضر إلا بإذنه.","body":[{"t":"h","text":"الدليل من السنة"},{"t":"quote","text":"الصَّائِمُ الْمُتَطَوِّعُ أَمِينُ نَفْسِهِ إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ","src":"رواه الترمذي ٧٣٢","pre":"عن أم هانئ رضي الله عنها أن النبي ﷺ قال:","links":[{"book":"mt_tirmidhi","num":732,"id":"h732"}]},{"t":"quote","text":"لاَ تَصُومُ الْمَرْأَةُ وَبَعْلُهَا شَاهِدٌ إِلاَّ بِإِذْنِهِ","src":"رواه البخاري ٥١٩٢","pre":"وعن أبي هريرة رضي الله عنه عن النبي ﷺ قال:","links":[{"book":"mt_bukhari","num":5192,"id":"h5192"}]},{"t":"h","text":"أقوال العلماء"},{"t":"quote","text":"وَأَمَّا حُكْمُ الْإِفْطَارِ فِي التَّطَوُّعِ: فَإِنَّهُمْ أَجْمَعُوا عَلَى أَنَّهُ لَيْسَ عَلَى مَنْ دَخَلَ فِي صِيَامِ تَطَوُّعٍ فَقَطَعَهُ لِعُذْرٍ قَضَاءٌ. وَاخْتَلَفُوا إِذَا قَطَعَهُ لِغَيْرِ عُذْرٍ عَامِدًا، فَأَوْجَبَ مَالِكٌ وَأَبُو حَنِيفَةَ عَلَيْهِ الْقَضَاءَ، وَقَالَ الشَّافِعِيُّ وَجَمَاعَةٌ: لَيْسَ عَلَيْهِ قَضَاءٌ","src":"بداية المجتهد","loc":"٢/٧٤","pre":"قال ابن رشد:"},{"t":"quote","text":"هاهنا مسألتان أحدهما جواز إفطار المتنفل وعدمه، وثانيتها أنه لو أفطر فهل عليه القضاء أم لا؟ وفي مدونة مالك أنه إن أفطر لعذر مسموع فلا قضاء وإلا فيقضي، وقال أبو حنيفة: يلزم بالشروع وإن أفطر يقضي بلا تفصيل","src":"العرف الشذي","loc":"٢/١٦٨","pre":"وقال الكشميري:"},{"t":"h","text":"الترجيح","k":"r"},{"t":"p","text":"الأظهر أن الصائم المتطوع له أن يفطر لعذر أو حاجة، كإجابة دعوة يشق على صاحبها امتناعه، أو ضيف، أو مشقة؛ لقوله ﷺ: «الصائم المتطوع أمين نفسه، إن شاء صام وإن شاء أفطر»، والأفضل أن يتمه إذا لم يكن له حاجة إلى الفطر. ولا يجب عليه القضاء على الأظهر، وهو قول الشافعي وأحمد، ويستحب له أن يقضيه، ومن قضاه أخذ بقول الحنفية والمالكية فهو أحوط. وأما صوم الفرض كالقضاء والنذر فلا يجوز قطعه بلا عذر."},{"t":"p","text":"ولا يجوز للمرأة أن تصوم تطوعًا وزوجها حاضر إلا بإذنه؛ لحديث أبي هريرة رضي الله عنه، فإن صامت بغير إذنه فله أن يفطرها. وأما صيام رمضان وقضاؤه إذا ضاق وقته فلا يتوقف على إذنه."}],"refs":["الترمذي ٧٣٢","البخاري ٥١٩٢","بداية المجتهد (٢/٧٤)","العرف الشذي (٢/١٦٨)","بداية المجتهد (٢/٧٥)"],"related":["النية في الصيام: تبييتها وتعيينها، وهل تكفي نية واحدة للشهر؟"],"alts":["قطع صوم التطوع","الإفطار في صوم النفل","قضاء صوم التطوع","صوم المرأة بغير إذن زوجها"]}]};
